import type { BankQuestion } from "@/lib/bank";

/** Child Development and Pedagogy (Child Development and Pedagogy): 2000 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"cdp-child-development-1","question":"The RTE Act, 2009 provides free and compulsory education for children aged:","options":["3–14 years","6–14 years","6–18 years","5–15 years"],"answer":1,"explanation":"Article 21A, made operational by the RTE Act 2009, guarantees free and compulsory education to every child aged 6 to 14 (Classes 1–8). 3–6 is the pre-school (ECCE) band, and extending the right to age 18 is only a proposal, not the law.","difficulty":"easy"},
  {"id":"cdp-child-development-2","question":"RTE stands for:","options":["Right to Education","Rules of Teaching Excellence","Right to Employment","Reading, Teaching and Evaluation"],"answer":0,"explanation":"The Right of Children to Free and Compulsory Education Act, 2009.","difficulty":"easy"},
  {"id":"cdp-child-development-3","question":"Which thinker is associated with the stages of cognitive development?","options":["Jean Piaget","B. F. Skinner","Ivan Pavlov","Sigmund Freud"],"answer":0,"explanation":"Piaget described four stages of cognitive development: sensorimotor, preoperational, concrete operational and formal operational. Skinner and Pavlov are behaviourists, and Freud's stages are psychosexual, not cognitive.","difficulty":"easy"},
  {"id":"cdp-child-development-4","question":"The concept of the Zone of Proximal Development was given by:","options":["Piaget","Vygotsky","Kohlberg","Skinner"],"answer":1,"explanation":"Lev Vygotsky introduced the ZPD: what a learner can do with help but not yet alone.","difficulty":"moderate"},
  {"id":"cdp-child-development-5","question":"The theory of multiple intelligences was proposed by:","options":["Howard Gardner","Jean Piaget","Lawrence Kohlberg","B. F. Skinner"],"answer":0,"explanation":"Howard Gardner proposed multiple intelligences in Frames of Mind (1983), listing linguistic, logical-mathematical, spatial and other separate intelligences. Kohlberg's stages describe moral reasoning, not kinds of intelligence.","difficulty":"moderate"},
  {"id":"cdp-child-development-6","question":"The term “scaffolding” in learning is associated with:","options":["Piaget","Vygotsky","Kohlberg","Erikson"],"answer":1,"explanation":"Scaffolding, temporary support from a more capable person, comes from Vygotsky’s sociocultural theory.","difficulty":"moderate"},
  {"id":"cdp-child-development-7","question":"Object permanence develops during which of Piaget’s stages?","options":["Sensorimotor","Pre-operational","Concrete operational","Formal operational"],"answer":0,"explanation":"Object permanence develops in the sensorimotor stage (0–2 years).","difficulty":"hard"},
  {"id":"cdp-child-development-8","question":"According to Piaget, abstract and hypothetical thinking develops in the:","options":["Sensorimotor stage","Pre-operational stage","Concrete operational stage","Formal operational stage"],"answer":3,"explanation":"The formal operational stage (11+ years) brings abstract and hypothetical reasoning.","difficulty":"hard"},
  {"id":"cdp-child-development-9","question":"Kohlberg’s theory deals with:","options":["Cognitive development","Moral development","Psychosocial development","Language development"],"answer":1,"explanation":"Kohlberg proposed three levels and six stages of moral development.","difficulty":"hard"},
  {"id":"cdp-child-development-10","question":"Operant conditioning was proposed by:","options":["Ivan Pavlov","B. F. Skinner","Edward Thorndike","Albert Bandura"],"answer":1,"explanation":"Skinner showed that behaviour is shaped by reinforcement and punishment; Pavlov’s is classical conditioning.","difficulty":"very-hard"},
  {"id":"cdp-child-development-11","question":"“Egocentrism” is a characteristic of which Piagetian stage?","options":["Sensorimotor","Pre-operational","Concrete operational","Formal operational"],"answer":1,"explanation":"Pre-operational children (2–7) find it hard to see things from another person’s point of view.","difficulty":"very-hard"},
  {"id":"cdp-child-development-12","question":"Erik Erikson’s stage of “Industry vs Inferiority” corresponds to the age group:","options":["0–1 years","3–6 years","6–12 years","12–18 years"],"answer":2,"explanation":"Industry vs Inferiority covers the school years, about 6 to 12.","difficulty":"very-hard"},
  {"id":"cdp-child-development-13","question":"According to Piaget, the stage of development from birth to about 2 years is the:","options":["Pre-operational stage","Sensorimotor stage","Concrete operational stage","Formal operational stage"],"answer":1,"explanation":"Infants learn through senses and movement in the sensorimotor stage.","difficulty":"easy","source":"CTET · UPTET"},
  {"id":"cdp-child-development-14","question":"The Right to Education Act, 2009 makes education free and compulsory for children aged:","options":["3–6 years","6–14 years","5–15 years","6–18 years"],"answer":1,"explanation":"The RTE Act 2009 (under Article 21A) makes education free and compulsory for children aged 6 to 14, i.e. Classes 1 to 8. The 3–6 band is early childhood care and education, and 6–18 is not covered by the Act.","difficulty":"easy","source":"CTET · SUPER TET"},
  {"id":"cdp-child-development-15","question":"Vygotsky’s “Zone of Proximal Development” refers to the gap between what a child can do:","options":["Alone and with a more capable person’s help","In the home language and in the school language","When rewarded and when no reward is offered","In familiar and in unfamiliar settings"],"answer":0,"explanation":"ZPD is the range of tasks a learner can do with guidance but not yet alone.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-16","question":"Howard Gardner is known for the theory of:","options":["Moral development","Multiple intelligences","Classical conditioning","Psychosocial development"],"answer":1,"explanation":"Gardner proposed several independent intelligences: linguistic, logical, spatial, musical and more.","difficulty":"moderate","source":"CTET · KVS"},
  {"id":"cdp-child-development-17","question":"Classical conditioning was demonstrated by Pavlov using:","options":["Rats in a box","Dogs and a bell","Pigeons","Children and a doll"],"answer":1,"explanation":"Pavlov paired a bell with food until the bell alone made dogs salivate.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-18","question":"A child who learns to read a word and then reads it again correctly a week later is showing which process of memory?","options":["Encoding","Storage","Retrieval","Forgetting"],"answer":2,"explanation":"Encoding and storage happened when the word was first learnt; reading it correctly a week later means pulling it back out of long-term memory, which is retrieval. Forgetting would be the failure of that retrieval.","difficulty":"very-hard","source":"CTET · DSSSB"},
  {"id":"cdp-child-development-19","question":"At Kohlberg’s pre-conventional level, a child judges right and wrong mainly by:","options":["Social approval","Punishment and reward","Universal ethical principles","Law and order"],"answer":1,"explanation":"Pre-conventional morality is about avoiding punishment and getting rewards.","difficulty":"hard"},
  {"id":"cdp-child-development-20","question":"Which of these is an example of formative assessment?","options":["The board exam at the end of the year","Class quizzes with feedback during a unit","An entrance test used to select students","The final term exam that decides promotion"],"answer":1,"explanation":"Formative assessment happens during learning and is used to improve it.","difficulty":"hard"},
  {"id":"cdp-child-development-21","question":"Bruner’s three modes of representation are:","options":["Enactive, iconic, symbolic","Sensory, motor, verbal","Concrete, abstract, formal","Visual, auditory, kinaesthetic"],"answer":0,"explanation":"Bruner said knowledge is represented through action (enactive), images (iconic) and language or symbols (symbolic), and good teaching moves through all three. Visual-auditory-kinaesthetic is the VAK learning-styles model, not Bruner's.","difficulty":"very-hard"},
  {"id":"cdp-child-development-22","question":"Wolfgang Köhler demonstrated “learning by insight” in experiments with:","options":["Cats","Dogs","Chimpanzees","Laboratory rats"],"answer":2,"explanation":"His chimpanzee Sultan joined sticks to reach a banana, showing sudden insight.","difficulty":"very-hard"},
  {"id":"cdp-child-development-23","question":"How many of these statements are correct? I. Piaget’s concrete operational stage covers roughly 2 to 7 years. II. Conservation develops in the concrete operational stage. III. Object permanence develops in the sensorimotor stage. IV. Abstract reasoning begins in the pre-operational stage.","options":["Only 1","Only 2","Only 3","All 4"],"answer":1,"explanation":"II and III are correct. I is wrong: 2 to 7 years is the pre-operational stage; the concrete operational stage is about 7 to 11. IV is wrong: abstract reasoning belongs to the formal operational stage.","difficulty":"very-hard"},
  {"id":"cdp-child-development-24","question":"How many of these statements are correct? I. The RTE Act, 2009 came into force on 1 April 2010. II. It reserves 25% of entry-level seats in private unaided schools for disadvantaged children. III. It lets schools hold screening tests for admission.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. The Act bans screening procedures and capitation fees.","difficulty":"very-hard"},
  {"id":"cdp-child-development-25","question":"A child knows that a ball of clay rolled into a sausage still has the same amount of clay. According to Piaget, the child has acquired:","options":["Conservation","Object permanence","Egocentrism","Animism"],"answer":0,"explanation":"Conservation develops in the concrete operational stage (about 7 to 11 years).","difficulty":"very-hard"},
  {"id":"cdp-child-development-26","question":"Vygotsky’s Zone of Proximal Development is the gap between:","options":["What a child can do alone and with guidance","A child’s mental age and chronological age","What a child knows and what the curriculum expects","A child’s performance at home and at school"],"answer":0,"explanation":"The ZPD is what a learner can do with help from a more knowledgeable other but not yet alone; scaffolding works inside it.","difficulty":"very-hard"},
  {"id":"cdp-child-development-27","question":"How many of these statements are correct? I. Kohlberg’s theory deals with moral development. II. Erikson proposed eight psychosocial stages. III. Piaget proposed five stages of cognitive development.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Piaget proposed four stages: sensorimotor, pre-operational, concrete operational and formal operational.","difficulty":"very-hard"},
  {"id":"cdp-child-development-28","question":"Which pair of theory and psychologist is NOT correctly matched?","options":["Classical conditioning – Ivan Pavlov","Social learning theory – Bandura","Multiple intelligences – Gardner","Trial-and-error learning – Skinner"],"answer":3,"explanation":"Trial-and-error learning, with the laws of effect, exercise and readiness, is Thorndike’s. Skinner gave operant conditioning.","difficulty":"very-hard","source":"CTET · KVS"},
  {"id":"cdp-child-development-29","question":"How many of these statements about Erikson’s theory are correct? I. Autonomy vs shame and doubt is the first stage. II. Identity vs role confusion belongs to early adulthood. III. The stages end with adolescence. IV. Initiative vs guilt covers roughly 3 to 6 years.","options":["Only 1","Only 2","Only 3","All 4"],"answer":0,"explanation":"Only IV is correct. The first stage is trust vs mistrust, identity vs role confusion is the adolescent stage (early adulthood is intimacy vs isolation), and the stages run to old age, ending with integrity vs despair.","difficulty":"very-hard","source":"CTET · DSSSB"},
  {"id":"cdp-child-development-30","question":"The Right of Children to Free and Compulsory Education Act, 2009 gives effect to which Article of the Constitution?","options":["Article 14","Article 21A","Article 45","Article 51A"],"answer":1,"explanation":"Article 21A, inserted by the 86th Amendment (2002), makes elementary education a fundamental right; Article 45 now deals with early childhood care below six years.","difficulty":"easy","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-31","question":"According to Piaget, the stage of cognitive development from about 2 to 7 years is the:","options":["Sensorimotor stage","Pre-operational stage","Concrete operational stage","Formal operational stage"],"answer":1,"explanation":"The pre-operational stage (2–7 years) is marked by symbolic play, egocentrism and lack of conservation.","difficulty":"easy","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-32","question":"The “law of effect” in learning was proposed by:","options":["Ivan Pavlov","B. F. Skinner","Thorndike","Albert Bandura"],"answer":2,"explanation":"Thorndike’s law of effect states that responses followed by satisfying consequences are strengthened; Skinner later built operant conditioning on this idea.","difficulty":"easy","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-33","question":"The 5+3+3+4 curricular structure for school education was recommended by:","options":["National Policy on Education, 1986","Right to Education Act, 2009","National Education Policy, 2020","Kothari Commission, 1966"],"answer":2,"explanation":"NEP 2020 replaces the 10+2 pattern with foundational (5 years), preparatory (3), middle (3) and secondary (4) stages covering ages 3 to 18.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-34","question":"The formula IQ = (Mental age ÷ Chronological age) × 100 was given by:","options":["Alfred Binet","William Stern","Lewis Terman","Charles Spearman"],"answer":1,"explanation":"William Stern proposed the intelligence quotient in 1912; Binet devised the mental-age scale and Terman popularised the IQ in the Stanford–Binet test.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-35","question":"According to Vygotsky, the most important tool for cognitive development is:","options":["Maturation","Language","Reinforcement","Physical play"],"answer":1,"explanation":"For Vygotsky, language and social interaction mediate thinking; private speech becomes inner speech that guides problem solving.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-36","question":"A child is generally regarded as “gifted” if the IQ is above:","options":["90","110","130","150"],"answer":2,"explanation":"An IQ of about 130 or more (two standard deviations above the mean of 100) is the usual threshold for giftedness.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-37","question":"An examination held at the end of a term to judge how much students have learnt is an example of:","options":["Formative assessment","Diagnostic assessment","Summative assessment","Placement assessment"],"answer":2,"explanation":"Summative assessment measures learning at the end of a unit or course; formative assessment happens during teaching to improve it.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-38","question":"Dyslexia is a learning disability that mainly affects:","options":["Reading","Arithmetic","Handwriting","Motor coordination"],"answer":0,"explanation":"Dyslexia affects reading and spelling; dyscalculia affects arithmetic, dysgraphia writing and dyspraxia motor coordination.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-39","question":"Under NEP 2020, the foundational stage covers children aged:","options":["3 to 6 years","3 to 8 years","6 to 10 years","5 to 8 years"],"answer":1,"explanation":"The foundational stage spans three years of pre-school (ages 3–6) plus classes 1 and 2 (ages 6–8).","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-40","question":"Kohlberg’s “good boy–good girl” orientation, where a child seeks approval of others, belongs to the:","options":["Pre-conventional level","Conventional level","Post-conventional level","Autonomous level"],"answer":1,"explanation":"Stage 3 (interpersonal conformity) is the first stage of the conventional level; stage 4 is law-and-order orientation.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-41","question":"A toddler who has learnt the word “dog” sees a cow for the first time and calls it “dog”. In Piaget’s terms this is an example of:","options":["Accommodation","Assimilation","Equilibration","Conservation"],"answer":1,"explanation":"The child fits new experience into an existing schema (assimilation); creating a new schema for “cow” would be accommodation.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-42","question":"Erikson’s stage of “autonomy vs shame and doubt” corresponds to the age range:","options":["Birth to 1 year","1 to 3 years","3 to 6 years","6 to 12 years"],"answer":1,"explanation":"Toddlers (1–3 years) learn self-control and independence; success gives autonomy, over-restriction gives shame and doubt.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-43","question":"The pupil–teacher ratio prescribed by the RTE Act for classes I to V is:","options":["25:1","30:1","35:1","40:1"],"answer":1,"explanation":"The Schedule to the RTE Act requires 30:1 for classes I–V (two teachers for up to 60 children) and 35:1 for classes VI–VIII.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-44","question":"Dyscalculia refers to a specific learning difficulty in:","options":["Reading fluency","Spelling and writing","Mathematics","Speech articulation"],"answer":2,"explanation":"Dyscalculia affects number sense and arithmetic; such children struggle with counting, place value and simple calculations.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-45","question":"A student who easily understands the moods and feelings of classmates shows, in Gardner’s theory, a high level of:","options":["Intrapersonal intelligence","Interpersonal intelligence","Naturalistic intelligence","Linguistic intelligence"],"answer":1,"explanation":"Interpersonal intelligence is sensitivity to others’ feelings and motives; intrapersonal intelligence is understanding one’s own emotions.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-46","question":"Bandura’s Bobo doll experiment demonstrated:","options":["Classical conditioning","Insight learning","Observational learning","Trial-and-error learning"],"answer":2,"explanation":"Children who watched an adult hit the doll imitated the aggression, showing that behaviour is learnt by observing models (social learning theory).","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-47","question":"Under the RTE Act, a child above six years who has never been admitted to a school shall be admitted to:","options":["Class I, regardless of the child’s actual age","A class appropriate to his or her age","A bridge course for one year first","A pre-primary class to build school readiness"],"answer":1,"explanation":"Section 4 provides age-appropriate admission with special training to help the child catch up with peers.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-48","question":"How many of these statements about Piaget’s theory are correct? I. The formal operational stage begins at about 11 years. II. Reversibility of thought is achieved in the concrete operational stage. III. Animism is a feature of the pre-operational stage. IV. Piaget held that learning precedes development.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: Piaget held that development precedes and limits learning; it is Vygotsky who argued that learning can lead development.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-49","question":"Assertion (A): Vygotsky stressed scaffolding by a more knowledgeable other. Reason (R): For Vygotsky, cognitive development is a socially mediated process.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because higher mental functions develop through interaction with capable others, support within the zone of proximal development (scaffolding) is central; R is the reason for A.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-50","question":"Match Kohlberg’s stages with their orientations: 1. Stage 1 2. Stage 2 3. Stage 4 4. Stage 6; a. Universal ethical principles b. Law and order c. Punishment and obedience d. Instrumental exchange (“what’s in it for me”)","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":0,"explanation":"Stage 1 punishment–obedience, stage 2 instrumental exchange, stage 3 good boy–good girl, stage 4 law and order, stage 5 social contract, stage 6 universal ethical principles.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-51","question":"Which of the following is NOT a principle of development?","options":["Development proceeds from head to toe (cephalocaudal)","Development proceeds from the centre of the body outward (proximodistal)","Development proceeds from specific to general","Development is a continuous process"],"answer":2,"explanation":"Development moves from general to specific: a baby waves its whole arm before it can grasp with its fingers.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-52","question":"How many of these statements about the RTE Act, 2009 are correct? I. It covers children aged 6 to 14 years. II. Section 12(1)(c) requires private unaided schools to admit at least 25% children from weaker sections in the entry class. III. No board examination may be held until the completion of elementary education. IV. Mild physical punishment is permitted as a last resort.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"I, II and III are correct (Section 30 bars board exams). IV is wrong: Section 17 prohibits all physical punishment and mental harassment.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-53","question":"How many of these statements about NEP 2020 are correct? I. It replaces the 10+2 structure with 5+3+3+4. II. It aims at a 100% Gross Enrolment Ratio in school education by 2030. III. It makes the mother tongue compulsory as the medium of instruction up to class 8. IV. It was approved by the Union Cabinet on 29 July 2020.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"I, II and IV are correct. III is wrong: NEP 2020 says the home language or mother tongue should be the medium “wherever possible” at least till class 5, preferably till class 8; it is a recommendation, not a compulsion.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-54","question":"In Maslow’s hierarchy, which need comes immediately above safety needs?","options":["Esteem and recognition needs","Self-actualisation needs","Belongingness and love needs","Physiological (survival) needs"],"answer":2,"explanation":"The order from the base is physiological → safety → belongingness and love → esteem → self-actualisation.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-55","question":"Assertion (A): A teacher should use formative assessment regularly during a unit. Reason (R): Formative assessment gives feedback that lets the teacher modify teaching while learning is still in progress.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Formative assessment is “assessment for learning”; its purpose is timely feedback, which is exactly why it should be continuous.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-56","question":"Match the psychologist with the concept: 1. Pavlov 2. Chomsky 3. Binet 4. Spearman; a. g-factor of intelligence b. Language acquisition device c. First intelligence test d. Classical conditioning","options":["1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-a, 4-c"],"answer":0,"explanation":"Pavlov → classical conditioning, Chomsky → innate language acquisition device, Binet → first practical intelligence test (1905), Spearman → two-factor (g and s) theory.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-57","question":"How many of these statements about theories of intelligence are correct? I. Spearman proposed the two-factor theory. II. Thurstone proposed seven primary mental abilities. III. The Binet–Simon scale was first published in 1905. IV. Sternberg’s triarchic theory includes analytical, creative and practical intelligence.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct; the common confusion is attributing multiple intelligences (Gardner) to Thurstone or the g-factor to Binet.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-58","question":"A four-year-old says her doll is “sad” because it fell down. According to Piaget, this illustrates:","options":["Conservation","Animism","Reversibility","Decentration"],"answer":1,"explanation":"Animism, attributing life and feelings to inanimate objects, is typical of the pre-operational stage; conservation and reversibility come later.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-59","question":"A student refuses to copy in an examination, saying “rules must be obeyed, otherwise there will be chaos in school”. In Kohlberg’s scheme the student is at:","options":["Stage 1, punishment and obedience","Stage 3, interpersonal conformity","Stage 4, law and order","Stage 5, social contract"],"answer":2,"explanation":"Reasoning that rules must be upheld to maintain social order is the law-and-order orientation (stage 4, conventional level); stage 1 would cite fear of punishment.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-60","question":"Inclusive education means:","options":["Separate special schools for children with disabilities","All children learning together in regular classrooms","Admitting only students who pass an entrance test","Teaching every subject only through the mother tongue"],"answer":1,"explanation":"Inclusive education places every child, whatever their ability, background or disability, in the same classroom and adapts teaching to meet their needs.","difficulty":"easy","source":"CTET · State TETs"},
  {"id": "cdp-child-development-61", "question": "The idea of “learning by doing” is most closely associated with:", "options": ["B. F. Skinner", "Ivan Pavlov", "John Dewey", "Sigmund Freud"], "answer": 2, "explanation": "John Dewey, the pragmatist philosopher, held that children learn best through activity and real experience rather than passive listening.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id":"cdp-child-development-62","question":"Kohlberg’s theory of moral development has:","options":["Three stages with no separate levels","Six stages grouped into three levels","Eight stages that span the whole lifespan","Four stages that match Piaget’s stages"],"answer":1,"explanation":"Kohlberg described pre-conventional, conventional and post-conventional levels, each with two stages, making six stages in all.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-63","question":"Which of these is an example of intrinsic motivation?","options":["A student studies hard to win the class prize","A student reads storybooks because she enjoys it","A student works hard so as to avoid punishment","A student studies to please her parents and teachers"],"answer":1,"explanation":"Intrinsic motivation comes from interest and enjoyment of the activity itself. Prizes, punishment and approval of others are external (extrinsic) motivators.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id": "cdp-child-development-64", "question": "ADHD, a condition that affects a child’s attention and self-control in class, stands for:", "options": ["Attention Deficit Hyperactivity Disorder", "Auditory Development Hearing Disorder", "Acquired Developmental Handicap Disorder", "Attention Delay and Hearing Difficulty"], "answer": 0, "explanation": "Children with Attention Deficit Hyperactivity Disorder find it hard to sustain attention and may be impulsive or overactive; short tasks and structured routines help them.", "difficulty": "moderate", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-65", "question": "Continuous and comprehensive evaluation (CCE) of a child’s understanding is provided for in which law?", "options": ["The Right to Education Act, 2009", "The Rights of Persons with Disabilities Act, 2016", "The Juvenile Justice Act, 2015", "The National Commission for Protection of Child Rights Act, 2005"], "answer": 0, "explanation": "Section 29(2) of the RTE Act requires the curriculum and evaluation procedure to include comprehensive and continuous evaluation of the child’s understanding and ability to apply knowledge.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-66", "question": "According to Freud, the “id” operates on the:", "options": ["Reality principle", "Morality principle", "Pleasure principle", "Social principle"], "answer": 2, "explanation": "The id seeks immediate gratification (pleasure principle), the ego follows the reality principle, and the superego represents moral standards.", "difficulty": "moderate", "source": "CTET · KVS · State TETs"},
  {"id":"cdp-child-development-67","question":"In Piaget’s theory, a “schema” is:","options":["A reward-and-punishment plan for shaping behaviour","An organised mental pattern for understanding the world","A standardised test that measures a child’s mental age","The gap between what a child can do alone and with help"],"answer":1,"explanation":"Schemas are mental frameworks that are built and changed through assimilation and accommodation. The gap described in the last option is Vygotsky’s ZPD.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-68","question":"Which intelligence did Howard Gardner add in 1995 as the eighth in his theory of multiple intelligences?","options":["Existential","Naturalistic","Emotional","Interpersonal"],"answer":1,"explanation":"Gardner added naturalistic intelligence (recognising and classifying plants, animals and nature) in 1995. Existential intelligence has only been suggested as a possible ninth.","difficulty":"hard","source":"CTET · State TETs"},
  {"id": "cdp-child-development-69", "question": "Which of these is NOT one of Thorndike’s primary laws of learning?", "options": ["Law of readiness", "Law of exercise", "Law of effect", "Law of insight"], "answer": 3, "explanation": "Thorndike’s three primary laws are readiness, exercise and effect. Insight learning comes from Köhler and the Gestalt school.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-70", "question": "A teacher asks, “In how many ways can we use a brick?” This question mainly encourages:", "options": ["Convergent thinking", "Divergent thinking", "Rote memory", "Concrete operational thinking"], "answer": 1, "explanation": "Open-ended questions with many possible answers promote divergent (creative) thinking. Convergent thinking aims at one correct answer.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id":"cdp-child-development-71","question":"According to Vygotsky, a child talking aloud to herself while solving a puzzle (private speech):","options":["Shows that she is egocentric and immature","Helps her guide and regulate her own thinking","Is an early sign of a speech or language disorder","Should be stopped at once, as it disturbs others"],"answer":1,"explanation":"Vygotsky saw private speech as a tool of self-regulation that later becomes inner speech. Piaget, by contrast, called it egocentric speech.","difficulty":"hard","source":"CTET · State TETs"},
  {"id": "cdp-child-development-72", "question": "Which of the following is a projective test of personality?", "options": ["16PF questionnaire", "Rorschach inkblot test", "Stanford–Binet test", "Raven’s Progressive Matrices"], "answer": 1, "explanation": "In the Rorschach test the subject interprets ambiguous inkblots, projecting inner feelings. 16PF is a self-report inventory, while Stanford–Binet and Raven’s are intelligence tests.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-73", "question": "A test given to find the specific areas in which a student has learning difficulties is a:", "options": ["Diagnostic test", "Achievement test", "Aptitude test", "Placement test"], "answer": 0, "explanation": "A diagnostic test pinpoints the exact weaknesses so that remedial teaching can follow. An achievement test measures how much has been learnt.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-74", "question": "Arrange these levels of Bloom’s revised taxonomy from the lowest to the highest: 1. Applying 2. Remembering 3. Creating 4. Analysing", "options": ["2, 1, 4, 3", "2, 4, 1, 3", "1, 2, 4, 3", "2, 1, 3, 4"], "answer": 0, "explanation": "The revised taxonomy (Anderson and Krathwohl, 2001) runs Remembering → Understanding → Applying → Analysing → Evaluating → Creating, with Creating at the top.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-75", "question": "Assertion (A): Constructivist teaching discourages rote memorisation of facts. Reason (R): Constructivism holds that learners actively build knowledge by linking new experiences to what they already know.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Because knowledge is constructed, not received, constructivists prefer activities, discussion and exploration over memorising. R explains A.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-76", "question": "Assertion (A): Boys and girls should be given different curricula because gender decides intellectual ability. Reason (R): Gender roles are largely shaped by society through socialisation.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false: intellectual ability does not depend on gender, and separate curricula reinforce stereotypes. R is true: gender is a social construct learnt through family, school and media.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-77", "question": "Match the psychologist with the idea: 1. Albert Bandura 2. Jerome Bruner 3. David Ausubel 4. Wolfgang Köhler; a. Insight learning b. Meaningful verbal learning and advance organisers c. Discovery learning d. Social (observational) learning", "options": ["1-d, 2-b, 3-c, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a"], "answer": 3, "explanation": "Bandura proposed social learning, Bruner discovery learning, Ausubel meaningful reception learning with advance organisers, and Köhler insight learning.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-78", "question": "Child A is 8 years old with a mental age of 10 years; child B is 10 years old with a mental age of 8 years. What is the difference between their IQs?", "options": ["20", "45", "25", "2"], "answer": 1, "explanation": "IQ = (MA ÷ CA) × 100. A: 10/8 × 100 = 125. B: 8/10 × 100 = 80. Difference = 125 − 80 = 45.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id":"cdp-child-development-79","question":"Which of the following is NOT a feature of a child-centred classroom?","options":["Children learn through activities, play and group discussion","The teacher acts as a facilitator rather than a lecturer","The textbook and teacher are the sole sources of knowledge","Children’s own experiences are linked to what is taught"],"answer":2,"explanation":"Child-centred pedagogy uses many sources of learning and treats the teacher as a facilitator; treating the textbook and teacher as the sole sources of knowledge is the traditional, teacher-centred approach.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-80","question":"How many of these statements about the Rights of Persons with Disabilities Act, 2016 are correct? I. It recognises 14 types of disabilities. II. It replaced the Persons with Disabilities Act, 1995. III. It gives every child with benchmark disability aged 6 to 18 years the right to free education. IV. Specific learning disabilities are not included among the specified disabilities.","options":["Only 1","Only 2","Only 3","All 4"],"answer":1,"explanation":"II and III are correct. I is wrong: the Act recognises 21 types of disabilities, up from seven in the 1995 Act. IV is wrong: specific learning disabilities such as dyslexia are among those 21.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id": "cdp-child-development-81", "question": "How many of these statements are correct? I. Piaget saw the child as a “little scientist” who constructs knowledge. II. Vygotsky argued that learning leads development. III. Piaget held that language drives thought. IV. Vygotsky proposed four universal, fixed stages of cognitive development.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. Piaget held that thought comes before language, and the four universal stages are Piaget’s idea; Vygotsky stressed culture and social interaction instead of fixed stages.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-82", "question": "A teacher excuses students from an extra written task whenever they listen attentively in class, and attentive listening increases. This is an example of:", "options": ["Positive reinforcement", "Negative reinforcement", "Punishment", "Extinction"], "answer": 1, "explanation": "Removing something unpleasant (the extra task) to strengthen a behaviour is negative reinforcement. Punishment weakens behaviour, so it is the common wrong answer.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id":"cdp-child-development-83","question":"How many of these are examples of assessment for learning? I. Oral questions during a lesson followed by feedback II. Peer assessment of first drafts III. A year-end board examination IV. A portfolio reviewed with feedback during the term","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"I, II and IV give feedback while learning is going on, so they are assessment for learning (formative). A year-end board exam is assessment of learning (summative).","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id": "cdp-child-development-84", "question": "Arrange in chronological order: 1. National Curriculum Framework 2005 2. Right to Education Act 3. Kothari Commission report 4. National Education Policy 2020", "options": ["3, 2, 1, 4", "1, 3, 2, 4", "3, 1, 2, 4", "3, 1, 4, 2"], "answer": 2, "explanation": "Kothari Commission report 1966 → NCF 2005 → RTE Act 2009 → NEP 2020.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id":"cdp-child-development-85","question":"Who described adolescence as a period of ‘storm and stress’?","options":["G. Stanley Hall","Erik H. Erikson","Sigmund Freud","Lawrence Kohlberg"],"answer":0,"explanation":"G. Stanley Hall, in his 1904 work on adolescence, called it a time of ‘storm and stress’ marked by emotional ups and downs. Erikson described adolescence as identity vs role confusion, and later researchers found that not every adolescent goes through such turmoil.","difficulty":"easy","source":"CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-86", "question": "The ‘kindergarten’ (children’s garden) system of early education was started by:", "options": ["John Locke", "Rabindranath Tagore", "Friedrich Froebel", "Maria Montessori"], "answer": 2, "explanation": "Friedrich Froebel opened the first kindergarten in Germany in 1837, stressing play, songs and ‘gifts’ (educational toys). Montessori developed her own method later, around 1907.", "difficulty": "easy", "source": "CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-87","question":"‘Emile’, the book that urged education according to the child’s nature, was written by:","options":["Jean-Jacques Rousseau","John Dewey","Johann Heinrich Pestalozzi","Friedrich Froebel"],"answer":0,"explanation":"Rousseau’s ‘Emile’ (1762) argued that children should learn through nature and experience at their own pace, an early root of child-centred education.","difficulty":"easy","source":"CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-88", "question": "Development of control proceeding from the head towards the feet, so that a baby controls its head before its legs, is called the:", "options": ["Cephalocaudal principle", "Principle of individual differences", "Principle of integration", "Proximodistal principle"], "answer": 0, "explanation": "Cephalocaudal means ‘head to tail’. The proximodistal principle describes development from the centre of the body outward, for example arm control before finger control.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-89","question":"The Montessori method of education places the greatest emphasis on:","options":["Self-directed learning with sensory materials","Rote learning under strict teacher control","Competitive examinations from an early age","Learning only through stories told by the teacher"],"answer":0,"explanation":"Montessori classrooms give children self-correcting materials that train the senses, so they learn by themselves (auto-education) while the teacher observes and guides.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-90", "question": "The theory that an infant’s early emotional bond with a caregiver shapes later relationships is the attachment theory of:", "options": ["John Bowlby", "Lawrence Kohlberg", "Edward Thorndike", "B. F. Skinner"], "answer": 0, "explanation": "John Bowlby argued that a secure attachment to a responsive caregiver gives the child a safe base from which to explore. Mary Ainsworth later studied attachment types with the ‘strange situation’ test.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-91", "question": "Parents who are warm and responsive but also set clear rules and explain them follow which parenting style, according to Diana Baumrind?", "options": ["Authoritative", "Authoritarian", "Permissive", "Neglectful"], "answer": 0, "explanation": "Authoritative parenting combines high warmth with high control and is linked with confident, self-reliant children. Authoritarian parents are strict but cold, and permissive parents are warm but set few limits.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-92", "question": "A ‘spiral curriculum’, in which topics are revisited at increasing levels of depth, was proposed by:", "options": ["Jean Piaget", "Jerome Bruner", "Abraham Maslow", "Ivan Pavlov"], "answer": 1, "explanation": "Bruner held that any subject can be taught in some honest form to any child, and then revisited in more complex forms as the child grows.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-93","question":"The ‘forgetting curve’, showing that most forgetting happens soon after learning, was given by:","options":["Wolfgang Köhler","Hermann Ebbinghaus","Edward L. Thorndike","Frederic Bartlett"],"answer":1,"explanation":"Ebbinghaus tested his own memory of nonsense syllables and found a steep early drop in retention that later levels off. This is why regular revision soon after learning helps.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-94", "question": "A child who calls every four-legged animal ‘dog’ learns that cows are different and forms a new category for them. In Piaget’s terms, the child has shown:", "options": ["Conservation", "Object permanence", "Assimilation", "Accommodation"], "answer": 3, "explanation": "Accommodation is changing an existing schema or making a new one when new experience does not fit. Calling the cow ‘dog’ in the first place would have been assimilation.", "difficulty": "hard", "source": "CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-95","question":"Carol Gilligan criticised Kohlberg’s theory of moral development mainly because she felt it:","options":["Had too few stages to capture adult moral growth","Drew on male subjects and ignored an ethic of care","Ignored the role of rewards and punishment in morality","Was meant only for adults, not for children"],"answer":1,"explanation":"Gilligan argued that Kohlberg’s justice-based stages, drawn mostly from boys, undervalued moral reasoning based on care and relationships, which she found more often in women.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id": "cdp-child-development-96", "question": "J. P. Guilford’s ‘Structure of Intellect’ model classifies intellectual abilities along which three dimensions?", "options": ["Operations, contents and products", "Fluid, crystallised and general", "Analytical, creative and practical", "Verbal, numerical and spatial"], "answer": 0, "explanation": "Guilford crossed operations (such as cognition and divergent production), contents and products to produce many distinct abilities. Analytical, creative and practical belong to Sternberg, and fluid–crystallised to Cattell.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-97", "question": "The idea of ‘emotional intelligence’ was popularised by whose 1995 book?", "options": ["Alfred Binet", "Robert Sternberg", "Howard Gardner", "Daniel Goleman"], "answer": 3, "explanation": "Daniel Goleman’s ‘Emotional Intelligence’ (1995) spread the concept, first proposed by Salovey and Mayer, of recognising and managing one’s own and others’ emotions.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-98", "question": "A child who has learnt to ride a bicycle finds it easier to learn to ride a scooter. This is an example of:", "options": ["Retroactive inhibition", "Zero transfer", "Negative transfer", "Positive transfer"], "answer": 3, "explanation": "Positive transfer occurs when earlier learning helps new learning because the skills share elements such as balance. Negative transfer is when earlier learning gets in the way.", "difficulty": "hard", "source": "CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-99","question":"The NIPUN Bharat Mission, launched in July 2021, aims to ensure that every child achieves:","options":["Proficiency in spoken English by the end of Class 5","Basic digital and coding literacy by Class 8","Job-ready vocational skills by Class 10","Foundational literacy and numeracy by Class 3"],"answer":3,"explanation":"NIPUN Bharat (National Initiative for Proficiency in Reading with Understanding and Numeracy) targets foundational literacy and numeracy by the end of Grade 3, with 2026–27 as the target year.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-100","question":"‘Action research’ was introduced into education to help teachers solve their own classroom problems by:","options":["B. F. Skinner and Sidney Pressey","Jean Piaget and Bärbel Inhelder","Kurt Lewin and Stephen M. Corey","Lev Vygotsky and Alexander Luria"],"answer":2,"explanation":"Kurt Lewin coined the term, and Stephen M. Corey popularised action research in education in the 1950s as a way for teachers to study and improve their own practice.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-101","question":"Paulo Freire criticised the ‘banking concept’ of education, in which:","options":["The teacher deposits facts into passive students","Students save up marks to use in final examinations","Students are taught how to save and manage money","Schools are run like banks, chiefly to make a profit"],"answer":0,"explanation":"In ‘Pedagogy of the Oppressed’ Freire argued against treating learners as empty accounts to be filled, and called for dialogue and critical thinking instead.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id": "cdp-child-development-102", "question": "A student who learnt French last year keeps mixing up French words while learning Spanish this year. This is an example of:", "options": ["Positive transfer", "Proactive interference", "Decay", "Retroactive interference"], "answer": 1, "explanation": "In proactive interference old learning disrupts the recall of new learning. If the new Spanish words made the student forget French, that would be retroactive interference.", "difficulty": "hard", "source": "CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-103","question":"How many of these statements about the principles of development are correct? I. Development is a continuous process. II. Development proceeds from the centre of the body outward. III. All children develop at the same rate. IV. Development results from the interaction of heredity and environment.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"I, II and IV are correct; II is the proximodistal principle. III is wrong: development follows a similar sequence in all children, but its rate differs from child to child.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-104", "question": "Match the learning difficulty with the area it mainly affects: 1. Dyslexia 2. Dysgraphia 3. Dyspraxia 4. Dysphasia; a. Language and speech b. Motor coordination c. Writing d. Reading", "options": ["1-d, 2-b, 3-c, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b"], "answer": 2, "explanation": "Dyslexia affects reading, dysgraphia writing, dyspraxia the planning and coordination of movement, and dysphasia the use and understanding of spoken language.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-105", "question": "Assertion (A): Teachers should avoid labelling children as ‘slow learners’ or ‘failures’. Reason (R): Labels can lower a child’s self-concept and teachers’ expectations, which can then become a self-fulfilling prophecy.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Studies of the Pygmalion effect show that children tend to perform as teachers expect, so a negative label can push achievement down. That is why R explains A.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-106", "question": "A student argues: ‘Laws are agreements made by people for the common good; if a law violates basic rights, it should be changed through democratic means.’ In Kohlberg’s scheme this reasoning belongs to:", "options": ["Stage 5, social contract orientation", "Stage 2, instrumental exchange", "Stage 3, good boy–good girl orientation", "Stage 4, law and order orientation"], "answer": 0, "explanation": "Seeing laws as changeable social contracts that should protect rights is Stage 5 (post-conventional). Stage 4 treats laws as fixed rules to be obeyed to keep order.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id":"cdp-child-development-107","question":"How many of these statements are correct? I. PARAKH was set up as a national assessment centre under the CBSE. II. The National Curriculum Framework for the Foundational Stage (2022) covers children aged 6 to 14. III. Vidya Pravesh is a three-month play-based school-preparation module for children entering Grade 6. IV. The National Curriculum Framework for School Education (2023) was drafted by a committee headed by Dr K. Kasturirangan.","options":["Only 1","Only 2","Only 3","All 4"],"answer":0,"explanation":"Only IV is correct. PARAKH was set up under the NCERT, the foundational stage covers ages 3 to 8, and Vidya Pravesh is the three-month play-based module for children entering Grade 1.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-108", "question": "Arrange in chronological order: 1. Bandura’s Bobo doll experiments 2. Gardner proposes multiple intelligences 3. Binet–Simon intelligence scale 4. Skinner publishes ‘The Behavior of Organisms’", "options": ["3, 4, 1, 2", "3, 4, 2, 1", "3, 1, 4, 2", "4, 3, 1, 2"], "answer": 0, "explanation": "The Binet–Simon scale came in 1905, Skinner’s book on operant conditioning in 1938, the Bobo doll studies in 1961 and Gardner’s ‘Frames of Mind’ in 1983.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-109", "question": "A student who fails a test says, ‘I was just unlucky today.’ According to Weiner’s attribution theory, the student has attributed the failure to a cause that is:", "options": ["External, stable and controllable", "External, unstable and uncontrollable", "Internal, stable and uncontrollable", "Internal, unstable and controllable"], "answer": 1, "explanation": "Luck lies outside the person, changes from day to day and cannot be controlled. Lack of effort would be internal, unstable and controllable, and low ability internal, stable and uncontrollable.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-110", "question": "Match the defence mechanism with its example: 1. Rationalisation 2. Projection 3. Displacement 4. Regression; a. An older child starts sucking his thumb after a sibling is born b. A child scolded by the teacher kicks his little brother at home c. A dishonest pupil accuses classmates of cheating d. A boy who is not chosen for the team says he never wanted to play anyway", "options": ["1-d, 2-c, 3-a, 4-b", "1-d, 2-b, 3-c, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a"], "answer": 3, "explanation": "Rationalisation gives a convenient excuse (sour grapes), projection puts one’s own faults on others, displacement vents feelings on a safer target, and regression is a return to earlier, childish behaviour.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id":"cdp-child-development-111","question":"Which of the following is NOT usually a characteristic of a creative child?","options":["Preference for a single, fixed correct answer","Curiosity and a habit of asking unusual questions","Tolerance for ambiguity and open-ended tasks","Divergent thinking with many original ideas"],"answer":0,"explanation":"Creative children produce many original ideas and are comfortable with open-ended problems. Looking for one fixed answer is convergent thinking, which tests of creativity do not reward.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-112", "question": "Assertion (A): Gifted children do not need any special educational provision because they can learn on their own. Reason (R): Gifted children have exceptional abilities that need enrichment or acceleration to develop fully.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false and R is true. Without challenge, gifted children may become bored, underachieve or develop behaviour problems, so they need enrichment, acceleration or ability-appropriate tasks.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-113", "question": "How many of these statements about intelligence tests are correct? I. The Stanford–Binet test is an individual test. II. The WISC was developed by David Wechsler. III. Raven’s Progressive Matrices is a verbal test. IV. Bhatia’s Battery is a verbal test of intelligence.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. Raven’s Progressive Matrices is a non-verbal, culture-reducing test of abstract reasoning, and C. M. Bhatia’s Battery is a set of performance tests designed for Indian children.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-114", "question": "Arrange Bronfenbrenner’s environmental systems from the innermost to the outermost around the child: 1. Exosystem 2. Microsystem 3. Macrosystem 4. Mesosystem", "options": ["2, 1, 4, 3", "2, 4, 3, 1", "2, 4, 1, 3", "4, 2, 1, 3"], "answer": 2, "explanation": "The microsystem (family, school) is closest; the mesosystem links microsystems (home–school); the exosystem affects the child indirectly (a parent’s workplace); the macrosystem is the wider culture. The chronosystem adds change over time.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-115", "question": "Which of the following is NOT usually counted as a domain of child development?", "options": ["Physical", "Cognitive", "Socio-emotional", "Financial"], "answer": 3, "explanation": "Child development is usually studied in physical, cognitive (including language) and socio-emotional domains, which interact with one another.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id":"cdp-child-development-116","question":"The “Heinz dilemma”, about a man who steals a drug to save his dying wife, was used to study moral reasoning by:","options":["Jean Piaget","Lawrence Kohlberg","Erik H. Erikson","Abraham H. Maslow"],"answer":1,"explanation":"Kohlberg classified children's reasons for their answers, not the answers themselves, into six stages of moral reasoning.","difficulty":"easy","source":"CTET · State TETs"},
  {"id": "cdp-child-development-117", "question": "A baby first controls the movements of the shoulders and arms, and only later the fingers. This illustrates the:", "options": ["Cephalocaudal principle", "Principle of individual differences", "Proximodistal principle", "Principle of interaction"], "answer": 2, "explanation": "Proximodistal development proceeds from the centre of the body outwards. Cephalocaudal development proceeds from head to foot.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-118", "question": "In Erikson's theory, the stage of “initiative vs guilt” corresponds roughly to the age of:", "options": ["Birth to 1 year", "3 to 6 years", "6 to 12 years", "12 to 18 years"], "answer": 1, "explanation": "Pre-school children who are encouraged to plan and try things develop initiative; harsh criticism breeds guilt. Industry vs inferiority follows in the school years.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-119", "question": "A collection of a child's work gathered over a term to show progress and reflection is called a:", "options": ["Portfolio", "Rubric", "Anecdotal record", "Achievement test"], "answer": 0, "explanation": "A portfolio shows growth over time and often includes the child's own reflections. A rubric is a scoring guide; an anecdotal record notes a single observed incident.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-120", "question": "A five-year-old says a tall, thin glass holds more juice than a short, wide one with the same amount, looking only at the height. According to Piaget, this shows:", "options": ["Animism", "Centration", "Object permanence", "Hypothetical reasoning"], "answer": 1, "explanation": "Centration is focusing on one striking feature and ignoring others, typical of the pre-operational stage; it is why such children fail conservation tasks.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-121", "question": "The ability to arrange sticks in order of length (seriation) generally develops in which Piagetian stage?", "options": ["Sensorimotor", "Pre-operational", "Formal operational", "Concrete operational"], "answer": 3, "explanation": "Seriation, along with conservation, reversibility and class inclusion, is mastered in the concrete operational stage (about 7 to 11 years).", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-122", "question": "Raymond Cattell divided general intelligence into:", "options": ["Fluid and crystallised intelligence", "Verbal and performance intelligence", "Analytical, creative and practical intelligence", "Primary mental abilities"], "answer": 0, "explanation": "Fluid intelligence is the ability to reason with new problems; crystallised intelligence is accumulated knowledge. Sternberg proposed the triarchic model and Thurstone the primary mental abilities.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id":"cdp-child-development-123","question":"Robert Sternberg's triarchic theory describes intelligence as having which three aspects?","options":["Verbal, numerical and spatial reasoning","Fluid, crystallised and emotional","Analytical, creative and practical","Linguistic, logical and musical"],"answer":2,"explanation":"Sternberg's theory includes componential (analytical), experiential (creative) and contextual (practical) intelligence.","difficulty":"hard","source":"CTET · State TETs"},
  {"id": "cdp-child-development-124", "question": "Rats that explored a maze without reward and then quickly found the food once it was introduced showed that they had learnt the layout. Who described this “latent learning”?", "options": ["Edward Tolman", "Ivan Pavlov", "B. F. Skinner", "Edward Thorndike"], "answer": 0, "explanation": "Tolman argued the rats had formed a “cognitive map” that was not shown until there was a reason to use it, challenging strict behaviourism.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-125", "question": "George Miller's classic finding about short-term memory is that it can hold about:", "options": ["Two or three items", "Seven, plus or minus two, items", "Twenty items", "An unlimited number of items for a few seconds"], "answer": 1, "explanation": "Miller (1956) put the span at about 7 ± 2 chunks; grouping information into chunks helps learners hold more.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id":"cdp-child-development-126","question":"To build a “growth mindset” as described by Carol Dweck, a teacher should mainly praise children for:","options":["Being naturally clever and gifted","Getting answers right on the first try","Effort, strategies and persistence","Finishing work before everyone else"],"answer":2,"explanation":"Praising effort and strategy teaches that ability can grow; praising only “cleverness” can make children avoid challenges for fear of failing.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-127","question":"After the RTE (Amendment) Act, 2019, which is true of examinations in Classes 5 and 8?","options":["Detention is completely prohibited in every class until elementary education ends","Board examinations become compulsory for every student at the end of Class 5","Failing students get a re-exam in two months; States may then allow detention","Only private unaided schools may hold back students who fail these exams"],"answer":2,"explanation":"The amendment to Section 16 lets the appropriate government hold regular exams in Classes 5 and 8, with a re-exam within two months, before a child can be held back.","difficulty":"hard","source":"CTET · State TETs"},
  {"id": "cdp-child-development-128", "question": "Consider the following statements about Bloom's revised taxonomy (2001): 1. It names the levels with verbs, such as remembering and understanding, instead of nouns. 2. It places creating above evaluating at the top. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Anderson and Krathwohl's revision renamed the levels and replaced “synthesis” with “creating” as the highest level.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-129", "question": "Arrange the levels of the affective domain (Krathwohl) from the lowest to the highest: 1. Valuing 2. Receiving 3. Characterisation 4. Responding 5. Organisation", "options": ["2, 4, 1, 3, 5", "2, 1, 4, 5, 3", "4, 2, 1, 5, 3", "2, 4, 1, 5, 3"], "answer": 3, "explanation": "The order is receiving, responding, valuing, organisation and characterisation by a value, as values become part of the learner's character.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-130", "question": "Match the section of the RTE Act, 2009 with its subject: A. Section 13 B. Section 17 C. Section 21 D. Section 29 — 1. School Management Committee 2. Ban on capitation fee and screening for admission 3. Curriculum and evaluation procedure 4. Ban on physical punishment and mental harassment", "options": ["A-2, B-4, C-1, D-3", "A-4, B-2, C-1, D-3", "A-2, B-4, C-3, D-1", "A-2, B-1, C-4, D-3"], "answer": 0, "explanation": "Section 13 bars capitation fees and screening, 17 bans corporal punishment, 21 requires School Management Committees, and 29 lays down curriculum principles, including continuous and comprehensive evaluation.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-131", "question": "Assertion (A): Samagra Shiksha treats school education as a continuum from pre-school to Class XII. Reason (R): Launched in 2018, it subsumed the Sarva Shiksha Abhiyan, the Rashtriya Madhyamik Shiksha Abhiyan and the Teacher Education scheme.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: merging the elementary, secondary and teacher-education schemes created one integrated programme for all stages of school.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id":"cdp-child-development-132","question":"How many of these abilities are typically achieved in Piaget's concrete operational stage? I. Reversibility II. Conservation III. Seriation IV. Class inclusion","options":["Only 1","Only 2","Only 3","All 4"],"answer":3,"explanation":"All four belong to the concrete operational stage: reversibility, conservation, seriation (ordering by size) and class inclusion all appear at about 7 to 11 years.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id": "cdp-child-development-133", "question": "Consider the following statements about Vygotsky's ideas: 1. The “more knowledgeable other” can be a peer, not only an adult. 2. Scaffolding should be gradually withdrawn as the child becomes competent. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. This is why peer tutoring and group work are useful, and why support is faded so the learner can work independently.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-134", "question": "Assertion (A): Shown seven roses and three lilies and asked, “Are there more roses or more flowers?”, a pre-operational child often says “more roses”. Reason (R): Pre-operational children have not yet mastered class inclusion.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: the child compares the two sub-classes instead of the sub-class with the whole class, an ability that comes in the concrete operational stage.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id":"cdp-child-development-135","question":"A six-year-old agrees that two rows of seven coins are equal when they are lined up. When one row is spread out, she says it has more. When the teacher pushes it back, she says they are equal again, but on spreading it once more she repeats her claim. Which feature of pre-operational thought most directly stops her from mentally ‘undoing’ the change?","options":["Animism","Irreversibility","Lack of object permanence","Transductive reasoning"],"answer":1,"explanation":"She cannot run the transformation backwards in her head, so each new layout is judged afresh; this is irreversibility. Centration on length adds to the error, but the inability to undo the change is the core limitation asked about.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-136","question":"A teacher helps a Class 2 child assemble a 30-piece jigsaw. Which of her actions goes AGAINST the principle of scaffolding?","options":["Showing how to start with the edge pieces and then letting the child continue","Asking, ‘Which pieces have a straight side?’ to focus the child’s attention","Keeping up full hints for every piece after she starts fitting them alone","Grouping the pieces by colour so that the task is broken into smaller parts"],"answer":2,"explanation":"Scaffolding is temporary and contingent: support should fade as competence grows. Continuing full hints after the child shows independence removes the challenge that drives development.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-137","question":"Two eight-year-olds both solve tasks up to an eight-year level on their own. With hints and leading questions, Arjun solves tasks up to a twelve-year level, while Bunty reaches only a nine-year level. From Vygotsky’s viewpoint, the most valid conclusion is:","options":["Their independent level is equal, but Arjun has a wider zone of proximal development","Both children are at the same level of development, so they should be taught in exactly the same way","Arjun is more intelligent, because his independent score is higher than Bunty’s","Bunty has reached the upper limit of his development and cannot learn further"],"answer":0,"explanation":"Vygotsky argued that what a child can do with help reveals maturing functions; equal independent scores can hide very different ZPDs, which matter for instruction. Their independent scores are equal, so the third option is factually wrong.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-138","question":"Asked why he shares his tiffin with Kabir, a nine-year-old says, ‘Kabir gave me half his sandwich yesterday, and if I share today he’ll share tomorrow too.’ This reasoning best fits Kohlberg’s:","options":["Stage 3: good boy–good girl orientation","Stage 1: punishment and obedience orientation","Stage 4: law and order orientation","Stage 2: instrumental exchange orientation"],"answer":3,"explanation":"The act is justified by a fair deal that serves his own interest, the hallmark of Stage 2. Stage 3 would appeal to being seen as a good, caring friend.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-139","question":"Two students both say Heinz should NOT steal the drug. Student P says, ‘He would be caught and put in jail.’ Student Q says, ‘If everyone broke the law whenever they felt justified, society would collapse.’ In Kohlberg’s scheme:","options":["Both are at the same stage because they reach the same decision","P is at Stage 1 and Q is at Stage 4","P is at Stage 2 and Q is at Stage 3","P is at Stage 4 and Q is at Stage 5"],"answer":1,"explanation":"Kohlberg classified the reasoning, not the decision. Fear of punishment marks Stage 1; maintaining social order through law marks Stage 4.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-140","question":"A Class 9 student keeps changing friend groups, hobbies and career plans, and often asks, ‘Who am I really?’ Her parents fear something is wrong. According to Erik Erikson, the teacher should explain that:","options":["Her exploration is normal in the identity vs role confusion stage and helps form identity","She has regressed to the industry vs inferiority stage and needs remedial teaching","She is facing the intimacy vs isolation crisis, which normally belongs to adolescence","Her autonomy was not developed in early childhood, so the problem cannot now be corrected"],"answer":0,"explanation":"Trying out roles is the normal work of Erikson’s adolescent stage. Intimacy vs isolation belongs to young adulthood, and Erikson did not see earlier stages as permanently fixing later outcomes.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-141","question":"A Class 3 child is constantly compared with a ‘topper’ sibling and given tasks far beyond his ability, at which he keeps failing. Erikson’s theory warns that he is at risk of developing:","options":["Mistrust, from the trust vs mistrust stage","Guilt, from the initiative vs guilt stage","Inferiority, from the industry vs inferiority stage","Role confusion, from the identity vs role confusion stage"],"answer":2,"explanation":"From about 6 to 12 years children judge themselves by their competence at tasks valued by school and peers; repeated failure and comparison breed inferiority. Achievable tasks and recognition of effort build industry.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-142","question":"Jerome Bruner claimed that any subject can be taught effectively in some intellectually honest form to any child at any stage of development. Which classroom implication follows from this claim?","options":["Complex ideas should be postponed until the child has reached the formal operational stage","Abstract symbols should be introduced as early as possible to speed up development","Each topic should be taught only once, in full depth, so that it need not be repeated","Big ideas can be taught early in enactive or iconic form and revisited in a spiral"],"answer":3,"explanation":"Bruner’s claim underlies the spiral curriculum: big ideas are introduced early in a form suited to the child and revisited with greater abstraction. Waiting for readiness is the position he was challenging.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-143","question":"To teach the water cycle, a teacher uses a song, a role-play of water drops, a labelled diagram and a group discussion on local rainfall. Which statement best reflects Howard Gardner’s theory in this case?","options":["The lesson offers several entry points, so children with different strengths can engage","The teacher should first find each child’s single learning style and teach that child only through it","Intelligence is one general ability, so the variety of activities only adds interest","Each child’s intelligences are fixed at birth, so the activities cannot develop them"],"answer":0,"explanation":"Gardner recommends teaching important ideas in several ways. He explicitly rejected equating multiple intelligences with ‘learning styles’ that restrict a child to one channel, and he saw intelligences as open to development.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-144","question":"Which of the following was NOT one of Howard Gardner’s criteria for accepting an ability as a separate intelligence?","options":["It can be isolated by brain damage, sparing other abilities","It has a distinct developmental history and an expert ‘end-state’ performance","It has an identifiable core operation or set of operations","It correlates highly with scores on standard IQ tests"],"answer":3,"explanation":"Gardner’s criteria include potential isolation by brain damage, a developmental history, core operations, existence of savants and prodigies, and encoding in a symbol system. A high correlation with IQ would argue against it being a separate intelligence.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-145","question":"A child believes that heavy things always sink. On a field trip she sees a large log floating, becomes puzzled, and after discussion begins to think that whether something floats depends on more than its weight. In Piaget’s terms, her puzzlement and her revised idea are respectively:","options":["Assimilation and equilibrium","Disequilibrium and accommodation","Accommodation and disequilibrium","Conservation and seriation"],"answer":1,"explanation":"The conflict between her schema and what she saw creates disequilibrium; changing the schema to fit the new experience is accommodation, which restores equilibrium.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-146","question":"Asked to find out what decides how fast a pendulum swings, a 14-year-old changes only the length while keeping the weight and the push the same, then tests each factor in turn. A 9-year-old changes the length and the weight together. The older child is showing:","options":["Seriation, the ordering skill that the younger child has not yet acquired","Class inclusion, the part–whole logic typical of the concrete operational stage","Hypothetico-deductive reasoning, isolating one variable at a time","Object permanence, which lets the older child keep the pendulum in mind"],"answer":2,"explanation":"Testing one variable at a time to check hypotheses is the hallmark of formal operational thought (Inhelder and Piaget’s pendulum task). Concrete operational children tend to vary several factors at once.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-147","question":"A Class 5 child easily solves ‘Ravi is taller than Mohan and Mohan is taller than Sohan; who is the tallest?’ But told ‘Suppose all elephants were purple; Moti is an elephant, so what colour is Moti?’, he replies, ‘Elephants are grey, not purple.’ This best shows that:","options":["He is concrete operational: he reasons about real facts, not contrary-to-fact premises","He is still pre-operational, since he cannot yet use transitive reasoning about heights","He has reached formal operations but is careless with imaginary premises","He lacks conservation, which is a prerequisite for all logical reasoning"],"answer":0,"explanation":"He handles transitivity (concrete operations) but cannot accept a hypothetical premise and reason from it, which needs formal operational thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-148","question":"Students forget new science terms within days when they just repeat them aloud, but remember them for weeks when they link each term to familiar examples and use it to explain events around them. According to the levels-of-processing view of Craik and Lockhart, this is because:","options":["Repeating aloud moves information straight into long-term memory storage","Short-term memory has unlimited capacity whenever the information is meaningful","Forgetting is caused only by the passage of time, not by how one studies","Meaningful, elaborative processing leaves deeper, longer-lasting memory traces"],"answer":3,"explanation":"Craik and Lockhart argued that retention depends on depth of processing; semantic elaboration produces stronger traces than maintenance rehearsal.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-149","question":"A child was repeatedly humiliated in front of the class during maths periods. Now she feels anxious as soon as she sees her maths textbook, even at home. In terms of classical conditioning:","options":["The textbook is the unconditioned stimulus and anxiety the unconditioned response","The humiliation is the conditioned stimulus and the textbook the unconditioned stimulus","The textbook is now a conditioned stimulus, and the anxiety a conditioned response","The anxiety is an operant behaviour that is being negatively reinforced"],"answer":2,"explanation":"Humiliation (UCS) naturally caused fear (UCR). Paired with it, the once-neutral textbook became a CS that alone now produces anxiety, a CR. Such conditioned anxiety is why classroom climate matters.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-150","question":"Whenever Manav disrupts the class, the teacher takes away ten minutes of his break time, and his disruptions decrease. In operant terms this is:","options":["Negative reinforcement","Negative punishment","Positive punishment","Extinction"],"answer":1,"explanation":"Removing something pleasant to reduce a behaviour is negative punishment. Negative reinforcement removes something unpleasant and increases a behaviour, a common mix-up.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-151","question":"A teacher decides to stop responding to a child who calls out answers without raising her hand. For the first few days the calling out becomes louder and more frequent. The teacher should understand that:","options":["This is an extinction burst; if she stays consistent the behaviour should decline","Ignoring has failed, so she should go back to responding to the child","The child is being negatively reinforced by being ignored","This shows spontaneous recovery, which means the behaviour has been permanently learnt"],"answer":0,"explanation":"When a reinforcer is withdrawn, behaviour often intensifies briefly (an extinction burst). Giving in at this point reinforces the louder behaviour on an intermittent schedule and makes it harder to remove.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-152","question":"A teacher wants students to keep reading at home even after the class reward chart is withdrawn. Which pattern of rewards, while the chart is in use, is most likely to produce reading that resists extinction?","options":["A sticker for every single book, so that no reading goes unrewarded","A sticker exactly after every fifth book, so pupils know what to expect","A sticker on the last day of every month, whatever was read","A sticker after an unpredictable number of books, about one in four"],"answer":3,"explanation":"A variable-ratio schedule produces high, steady responding that is most resistant to extinction, because the learner cannot tell when the reward has stopped. Continuous reinforcement extinguishes fastest.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-153","question":"Simran is convinced she ‘can never do maths’. According to Bandura, which step would most strongly raise her self-efficacy in maths?","options":["Telling her again and again, ‘You are a bright girl, you can surely do it’","Letting her watch the class topper solve difficult problems with ease","Giving her graded tasks she can really succeed at, then harder ones","Excusing her from maths tests until she feels more confident in herself"],"answer":2,"explanation":"Mastery experiences are the strongest source of self-efficacy. Verbal persuasion is weaker, and a model seen as very unlike oneself (the topper) has less effect than a similar model.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-154","question":"A child watches a folk dance closely and can describe every step accurately afterwards, wanting badly to perform it, but cannot yet coordinate her movements to do so. In Bandura’s model of observational learning, the breakdown is at the stage of:","options":["Attention to the model","Motor reproduction","Retention in memory","Motivation to perform"],"answer":1,"explanation":"She attended and retained the steps, and she is motivated; what is missing is the physical ability to reproduce them. Practice with feedback is needed.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-155","question":"After seeing the teacher praise Rekha for her neat notebook in front of the class, several other children begin to keep their notebooks neat, though none of them has been praised yet. This is best explained by:","options":["Vicarious reinforcement","Classical conditioning","Trial-and-error learning","Negative reinforcement"],"answer":0,"explanation":"Seeing a model rewarded raises the observers’ expectation of reward, which Bandura called vicarious reinforcement.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-156","question":"A Class 4 student with low vision has joined a regular school. Which plan best reflects inclusive education under the RPwD Act, 2016?","options":["Recommend a special school, since the pace of a regular class may slow her down","Exempt her from all written assessments so that she is never under pressure","Ask her to sit at the back so that she does not feel singled out by classmates","Seat her near the board, give large-print or audio material and read aloud the board work"],"answer":3,"explanation":"Inclusion means adapting seating, materials and teaching so that the child learns in the regular class with reasonable accommodation, not segregating or exempting her.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-157","question":"In a lesson on plants, a teacher presents the content as a picture chart, a real potted plant to touch, an oral explanation and a short text with key words highlighted. Under Universal Design for Learning, she is mainly applying the principle of:","options":["Multiple means of engagement","Multiple means of action and expression","Multiple means of representation","Individualised remedial teaching"],"answer":2,"explanation":"Offering the same content in several forms (visual, tactile, auditory, text) is multiple means of representation. Letting children show learning in different ways would be action and expression.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-158","question":"A school admits children with disabilities into its regular classes but makes no change in teaching, materials, building or assessment; the children are expected to ‘cope like everyone else’. This situation is best described as:","options":["Inclusion, because the children study in the same classroom as others","Integration: placed in the mainstream but expected to fit an unchanged system","Segregation, because the children are kept in a separate special unit","Mainstreaming with full reasonable accommodation, as the RPwD Act requires"],"answer":1,"explanation":"Inclusion changes the system to fit every child; mere physical placement without accommodation is integration. The RPwD Act 2016 requires reasonable accommodation.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-159","question":"A school claims to follow continuous and comprehensive evaluation because it now holds a written unit test every week in every subject. The strongest criticism of this claim is that:","options":["It equates continuous with frequent testing and ignores co-scholastic areas","Weekly tests are too few; CCE requires a written test every single day","CCE forbids all written tests, so the school is actually breaking the rules","CCE is meant only for co-scholastic areas, so subject tests are irrelevant"],"answer":0,"explanation":"‘Continuous’ refers to ongoing assessment during learning (observation, projects, discussion, portfolios), and ‘comprehensive’ to scholastic and co-scholastic growth. More tests only add testing pressure.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-160","question":"After a writing task, students use a rubric to judge their own drafts, note what they need to improve, and set a target for the next draft. This is best described as:","options":["Assessment of learning","Summative assessment","Norm-referenced assessment","Assessment as learning"],"answer":3,"explanation":"When learners themselves monitor and regulate their learning through self-assessment, assessment becomes part of learning (assessment as learning), developing metacognition.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-161","question":"Which report on a Class 2 reading test is criterion-referenced?","options":["Riya scored higher than 80% of the Class 2 children in her whole district","Riya reads 40 words a minute with 95% accuracy, meeting the set Grade 2 standard","Riya ranked 3rd out of 42 children in her section on this test","Riya’s score lies one standard deviation above the mean of her class"],"answer":1,"explanation":"A criterion-referenced report compares performance with a fixed standard of what the child can do. Percentiles, ranks and standard scores compare her with other children (norm-referenced).","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-162","question":"A Class 4 maths test on multiplication uses long word problems written in difficult English. Many children who multiply well in class score poorly. The main problem with the test is its:","options":["Reliability, because the scores would change if the test were repeated","Objectivity, because different teachers would mark it differently","Validity, as it partly measures English reading, not multiplication","Practicability, because it takes too long to administer"],"answer":2,"explanation":"A test is valid if it measures what it intends to. Here reading ability contaminates the score, so it is not a valid test of multiplication, even if it gives consistent results.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-163","question":"Studies show that identical twins reared apart have more similar intelligence test scores than unrelated children reared together, yet adopted children from deprived homes gain considerably when raised in enriched homes. The most defensible conclusion is:","options":["Heredity sets a range; environment decides where within it a child develops","Intelligence is fixed entirely by heredity, so enrichment cannot really raise it","Intelligence is decided entirely by environment, as adoption studies prove","Heredity and environment act separately, so their effects can simply be added"],"answer":0,"explanation":"Both findings together point to interaction: genes contribute substantially, but environment shapes how that potential is realised. Neither extreme position fits both findings.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-164","question":"A four-year-old, while playing with a friend, explains how to play a board game: ‘You put this here, then that goes there,’ pointing at pieces the friend cannot see from across the room. According to Piaget, this speech shows:","options":["Animism, treating the game pieces as if they were alive","Centration, focusing on a single dimension of the game","A lack of object permanence for pieces out of sight","Egocentrism: difficulty taking another’s point of view"],"answer":3,"explanation":"The child assumes the listener sees what she sees, so ‘this’ and ‘there’ seem clear to her. Piaget called this egocentric thought and speech.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-165","question":"A Class 3 textbook picture shows only mothers cooking and only fathers going to an office. The most appropriate response of a gender-sensitive teacher is to:","options":["Skip the picture so that the issue of gender does not come up at all","Explain that this is how families naturally divide work between men and women","Ask who does which work at home and discuss whether any work belongs to one gender","Tell the girls in the class that they will not have to cook when they grow up"],"answer":2,"explanation":"Drawing on children’s own experiences and discussing stereotypes helps them question fixed gender roles, as NCF 2005 urges. Ignoring or endorsing the picture leaves the stereotype unexamined.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-166","question":"At the start of the year a teacher is told (wrongly) that five randomly chosen children are ‘late bloomers’ about to make big gains. She gives them more attention, wait-time and encouragement, and by the year’s end they have indeed improved more than others. This illustrates:","options":["The halo effect","The Pygmalion effect","Regression towards the mean","The Hawthorne effect"],"answer":1,"explanation":"Rosenthal and Jacobson showed that teachers’ expectations can change how they treat pupils and so shape achievement. This is why labelling children is harmful.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-167","question":"Children in a class love drawing in their free time. The school begins to give a prize for every drawing. Some weeks later the prizes are stopped, and the children now draw much less than they did before prizes began. The best explanation is that:","options":["The prizes undermined their intrinsic interest, so drawing began to feel like work","The prizes were too small to make a lasting difference to their habits","The children have become better at drawing and no longer need practice","Drawing has been extinguished, since it was never reinforced before the prizes"],"answer":0,"explanation":"Expected tangible rewards for an already enjoyable activity can reduce intrinsic motivation (the overjustification effect). Drawing was intrinsically motivated before the prizes, so the last option is wrong.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-168","question":"Before a difficult problem-solving test, a teacher tells the class that this test will ‘decide your whole future’. Students who were confident in practice now make careless errors on the hardest questions. According to the Yerkes–Dodson principle:","options":["Higher anxiety always improves performance, so the errors must be due to lack of preparation","Performance does not depend on the level of arousal or anxiety at all","Arousal improves performance on complex tasks but harms performance on simple ones","Performance peaks at moderate arousal, and the peak is lower for complex tasks"],"answer":3,"explanation":"Performance rises with arousal up to an optimum and then falls; for difficult tasks the optimum is lower. The third option reverses the actual relationship.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-169","question":"Several children in a rural school come to school without breakfast and cannot concentrate in the first periods. In terms of Maslow’s hierarchy, the most logical first step is to:","options":["Meet their physiological needs first, for example through a morning snack","Offer prizes and praise to build up their self-esteem in class","Give them more interesting lessons so that they want to learn for its own sake","Hold parent meetings on the importance of regular study and education"],"answer":0,"explanation":"Maslow held that lower (deficiency) needs such as hunger must be met before higher needs such as esteem and self-actualisation can guide behaviour.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-170","question":"Aman, aged 9, gives thoughtful oral answers in science discussions and does well in mental maths, but reads very slowly, guesses words from the first letter, and spells ‘was’ as ‘saw’ and ‘said’ as ‘sed’. The most likely explanation is:","options":["Intellectual disability, because his reading is far below the level for his age","Dyslexia: his difficulty is limited to decoding and spelling, not reasoning","Laziness, since he clearly answers well in class whenever he wants to","ADHD, since his reading errors show careless attention to the text"],"answer":1,"explanation":"Average or better reasoning with a specific, unexpected difficulty in decoding and spelling fits dyslexia; intellectual disability would affect reasoning broadly. Labelling him lazy is a damaging misconception.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-171","question":"Which classroom strategy is most suitable for a child with ADHD?","options":["Giving long worksheets so that he slowly learns to sit still for longer periods","Seating him near the window so that he can relax and calm himself down","Short tasks with clear steps, brief movement breaks and a seat near the teacher","Ignoring all his work until he finishes a whole task without any help"],"answer":2,"explanation":"Children with ADHD benefit from structure, short tasks, frequent feedback and chances to move. A seat by the window adds distraction, and long tasks set them up to fail.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-172","question":"A Class 2 child becomes very upset when the timetable changes without notice, rarely makes eye contact, and talks at length only about trains. Which support is most appropriate in an inclusive class?","options":["Insisting that she make eye contact while talking, so that she learns social skills","Changing her seat often so that she gets used to change and becomes flexible","Avoiding her interest in trains, as it distracts her and the class from the lesson","Using a visual daily schedule, warning her of changes and using her interest in trains"],"answer":3,"explanation":"These traits suggest autism spectrum disorder. Predictable routines, visual supports and building on special interests reduce anxiety and aid learning; forced eye contact and sudden change raise distress.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-173","question":"Priya, a gifted Class 4 student, finishes class work early and is bored. Which of the following is an example of ENRICHMENT rather than acceleration?","options":["Promoting her straight to Class 5 so that she studies at a higher level","Giving her another worksheet of similar sums each time she finishes early","Asking her to explore an open-ended question on the topic in depth and present it","Letting her spend the extra time helping the teacher check other children’s notebooks"],"answer":2,"explanation":"Enrichment broadens and deepens learning at the same grade level through challenging, higher-order tasks. Grade skipping is acceleration, and more of the same is just busy work.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-174","question":"Children from a tribal community in a Class 1 classroom speak a language different from the school language and remain silent in class. Consistent with NEP 2020 and NCF 2005, the teacher should:","options":["Use their home language in class as a bridge while building the school language","Insist on the school language only, so that they pick it up faster by immersion","Seat them separately until they have learnt enough of the school language","Tell parents to speak only the school language at home from now on"],"answer":0,"explanation":"Both documents treat the home language as a resource; learning through it builds confidence and concepts, and supports the move to other languages. Banning it silences children.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-175","question":"Assertion (A): Piaget held that a child’s language reflects the concepts the child has already formed. Reason (R): For Piaget, cognitive development comes first and language develops on its basis.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Piaget saw language as dependent on thought: children use words for the concepts their cognitive structures allow. Vygotsky, by contrast, gave language a formative role in thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-176","question":"In a science activity, students must hang a lamp using a ruler, string and tape. Most of them say there is ‘nothing to use as a support’, because they see the ruler only as something for measuring. Their difficulty is called:","options":["Insight","Transfer of learning","Functional fixedness","Proactive interference"],"answer":2,"explanation":"Functional fixedness (Duncker) is the tendency to see an object only in its usual function, which blocks creative problem solving.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-177","question":"Before her exam, Neha lists the topics she does not yet understand, decides which to revise first, and after each session tests herself to see whether her plan is working. Neha is mainly using:","options":["Rote memorisation","Metacognition","Convergent thinking","Overlearning"],"answer":1,"explanation":"Planning, monitoring and evaluating one’s own learning is metacognition, a key aim of learner-centred teaching.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-178","question":"A Class 6 child says, ‘Plants get their food from the soil, that is why we put manure.’ A teacher following constructivist principles would most likely:","options":["Mark the answer wrong and dictate the correct definition of photosynthesis","Ignore the answer because the child will learn the correct idea in higher classes","Tell the class that the child is wrong and ask another child for the right answer","Ask her to explain her reasoning, then let her test it by growing plants in light and dark"],"answer":3,"explanation":"Constructivism treats a misconception as the child’s present idea; it should be surfaced and challenged through experience so that the child reconstructs it, not merely overwritten by a definition.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-179","question":"A teacher divides a lesson on the Indian monsoon into four parts. Each member of a home group studies one part with members of other groups who have the same part, then returns to teach it to the home group. Each student is tested on all four parts. This technique is:","options":["The jigsaw technique","Peer tutoring by an abler student","Programmed instruction","Brainstorming"],"answer":0,"explanation":"In Aronson’s jigsaw method each learner becomes an ‘expert’ on one piece, creating positive interdependence, since the group needs everyone’s part.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-180","question":"How many of the following statements about Kohlberg’s theory are correct? I. The stages follow an invariant sequence, so a stage cannot be skipped. II. Every adult eventually reaches Stage 6. III. Advanced moral reasoning requires a matching level of cognitive development, though cognitive development alone does not ensure it. IV. A person’s stage is decided by the action chosen in a dilemma.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. Few people reach the post-conventional stages, and the stage is judged from the reasoning behind a choice, not the choice itself.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-181","question":"To help Class 1 children understand that the amount of water does not change when it is poured into a differently shaped glass, which approach would Piaget most strongly favour?","options":["Telling them the rule clearly and asking them to memorise it for the test","Showing a chart that explains conservation with labelled pictures","Letting them pour water between different containers, predict, check and discuss","Rewarding children who give the correct answer until all of them say it"],"answer":2,"explanation":"Piaget saw children as active constructors of knowledge through action on materials; teaching a verbal rule or rewarding the answer gives a parroted response without the underlying operation.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-182","question":"Tanu began walking at 10 months and her cousin at 15 months; both are healthy and now walk equally well. Both crawled before they walked. Which principle of development do these facts illustrate together?","options":["Development is unpredictable in both its sequence and its rate","Development proceeds from specific responses to general ones","Later development depends entirely on early development","The sequence of development is similar for all, but the rate varies"],"answer":3,"explanation":"Both crawled before walking (same sequence) but at different ages (different rate), the principle of individual differences within a common pattern.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-183","question":"NEP 2020 gives high priority to Early Childhood Care and Education. Its stated reason is that:","options":["Children must learn to read and write fluently before the age of three","Over 85% of cumulative brain development occurs before age six","Formal written examinations should begin at the pre-school stage","Children below six cannot learn through play and need formal lessons"],"answer":1,"explanation":"NEP 2020 notes that over 85% of cumulative brain development happens before age 6, so play-based, activity-based early learning is critical. It does not call for early formal reading or exams.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-184","question":"A teacher asks children to find out how much water their family uses in a day and to suggest ways of saving it, then uses their data in class. Which NCF 2005 guiding principle does this best reflect?","options":["Making examinations more flexible and integrated with classroom life","Enriching the curriculum so that it goes beyond textbooks","Connecting knowledge to life outside the school","Nurturing an overriding identity informed by caring concerns within the democratic polity"],"answer":2,"explanation":"Using children’s home experience as the basis of learning connects school knowledge with life outside school, the first of NCF 2005’s guiding principles.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-185","question":"Which piece of written feedback on a student’s essay is most effective for formative purposes?","options":["‘7/10. A good effort overall, though some parts need more work.’","‘Excellent work! Keep it up and you will surely get full marks.’","‘Your work is better than most of the class, so you should feel very proud.’","‘In paragraph 3, give an example to support your claim about pollution.’"],"answer":3,"explanation":"Effective formative feedback is specific, focuses on the task, and tells the learner how to close the gap. Marks, vague praise and comparisons with others give no direction for improvement.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-186","question":"The holistic progress card proposed in NEP 2020 is best described as:","options":["A report card showing only the marks scored in the board-subject tests each term","A 360-degree report with self, peer and teacher assessment across all domains","A record of the child’s progress kept only by the parents at home","A rank list comparing every child’s marks with the class average"],"answer":1,"explanation":"NEP 2020 proposes a 360-degree progress card covering all domains, with inputs from the child, peers and teacher, to show each learner’s progress and uniqueness.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-187","question":"In a subtraction test, 14 of 35 students write 82 − 46 = 44, and make similar errors in other sums that need regrouping. What should the teacher do first?","options":["Reteach the whole chapter to the entire class from the very beginning","Give these students more subtraction worksheets of the same type for practice","Treat the result as a careless mistake and move on to the next chapter","Analyse the shared error to diagnose the misconception, then plan remedial teaching"],"answer":3,"explanation":"A shared error pattern points to a shared misconception (here, subtracting the smaller digit from the larger in each column); diagnosis comes before remediation. 82 − 46 = 36, but taking 6 − 2 = 4 in the ones column and 8 − 4 = 4 in the tens gives 44.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-188","question":"Insulted by a classmate, Kavya notices her anger rising, takes a few deep breaths, and replies calmly. In Daniel Goleman’s model of emotional intelligence, she is mainly showing:","options":["Empathy","Social skills","Self-regulation","Self-motivation"],"answer":2,"explanation":"Recognising an emotion is self-awareness; controlling how one acts on it is self-regulation. Empathy concerns others’ feelings.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-189","question":"In Mary Ainsworth’s ‘strange situation’, a toddler shows little distress when the mother leaves and, when she returns, looks away and does not seek contact. This pattern is classified as:","options":["Insecure-avoidant attachment","Secure attachment","Insecure-resistant (ambivalent) attachment","Stranger anxiety, a normal sign of secure attachment"],"answer":0,"explanation":"A securely attached child is upset at separation and is comforted on reunion; ignoring or avoiding the mother on return marks the avoidant pattern.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-190","question":"Parents give their child whatever he asks for, rarely set rules or limits, and are very warm and affectionate. In Baumrind’s classification this is the:","options":["Authoritarian style","Authoritative style","Permissive (indulgent) style","Uninvolved (neglectful) style"],"answer":2,"explanation":"High warmth with low demands and control is permissive. Authoritative parents are warm but also set and explain limits; neglectful parents are low on both.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-191","question":"A three-year-old who has not had her afternoon nap insists, ‘It isn’t afternoon, because I haven’t had my nap.’ According to Piaget, this is an example of:","options":["Deductive reasoning","Inductive reasoning","Hypothetico-deductive reasoning","Transductive reasoning"],"answer":3,"explanation":"Transductive reasoning links one particular to another as if one caused the other (nap → afternoon), instead of reasoning from general to particular or particular to general.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-192","question":"Which statement correctly contrasts Piaget and Vygotsky on the relation between learning and development?","options":["Piaget held that learning leads development; Vygotsky held that development must come first","Piaget: development sets limits for learning; Vygotsky: instruction runs ahead and leads it","Both held that development is entirely due to biological maturation, not learning","Both held that social interaction plays no real part in children’s cognitive growth"],"answer":1,"explanation":"For Piaget, what a child can learn depends on stage; for Vygotsky, instruction within the ZPD awakens functions that are maturing, so learning drives development.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-193","question":"A teacher keeps a running record of how each child participates in group work, notes the strategies children use, and adjusts the next day’s lesson accordingly. Which statement about this practice is correct?","options":["It is formative assessment, because it is used to adapt ongoing teaching","It is summative assessment, because it records children’s performance","It is not assessment at all, because no marks or grades are given","It is norm-referenced assessment, because children are being compared"],"answer":0,"explanation":"Assessment is formative when its evidence is used to shape ongoing teaching and learning; marks are not needed, and the purpose, not the format, decides the type.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-194","question":"A teacher makes a restless Class 1 child copy the same row of letters again and again just before lunch, although the child’s hand is tired and he is not interested. The child becomes irritated and starts scribbling. Which of Thorndike’s laws best explains his reaction?","options":["Law of exercise","Law of effect","Law of readiness","Law of belongingness"],"answer":2,"explanation":"By the law of readiness, being forced to act when not ready is annoying. More drill (exercise) without readiness produces frustration, not learning.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-195","question":"Before a unit on the solar system, a teacher begins with a short overview: ‘Just as children in a ring game move around the person in the centre, planets move around the sun, each on its own path.’ According to David Ausubel, this introduction serves as:","options":["An advance organiser linking new material to what learners know","A discovery task in which learners find the principle on their own","Negative reinforcement for attentive behaviour","A summative check of prior knowledge"],"answer":0,"explanation":"Ausubel’s advance organiser is a broad, introductory frame that anchors new information to existing cognitive structure, making it meaningful rather than rote.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-196","question":"To teach the concept ‘mammal’, a teacher includes a bat and a whale among her examples, and a penguin and a crocodile as non-examples. The main reason for choosing these is to:","options":["Make the lesson longer and more interesting with some unusual animals","Test whether children have memorised the names of many different animals","Avoid any discussion of the common animals that children already know","Make the defining features clear, so children neither over- nor undergeneralise"],"answer":3,"explanation":"Unusual examples and close non-examples force attention to the defining features (e.g. hair, feeding young on milk) rather than surface features such as habitat or flight, so children neither overgeneralise (‘all flying things are birds’) nor undergeneralise (‘animals in water cannot be mammals’).","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-197","question":"A teacher reads out a list of 15 new words once. When children are asked to recall them, most remember the first few and the last few, but forget those in the middle. This is the:","options":["Zeigarnik effect","Serial position effect","Law of exercise","Distributed practice effect"],"answer":1,"explanation":"Recall is better for early items (primacy, more rehearsal) and late items (recency, still in short-term memory) than for middle items.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-198","question":"Two groups spend three hours in total revising the same chapter. Group A revises for three hours on the night before the test; Group B revises for 30 minutes on each of six days. A week after the test, Group B remembers much more. This supports the principle that:","options":["Massed practice is better for long-term retention than spaced practice","Total study time alone decides how much is remembered, not its spacing","Spaced practice gives better long-term retention than massed practice","Forgetting does not happen if the material studied is meaningful"],"answer":2,"explanation":"Spacing the same amount of practice over time strengthens retention, the spacing effect first shown by Ebbinghaus. Cramming may help briefly but is forgotten faster.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-199","question":"After learning a new set of spellings in English this week, Meena finds she can no longer recall some spellings she learnt last month. This is an example of:","options":["Proactive interference","Positive transfer","Repression (motivated forgetting)","Retroactive interference"],"answer":3,"explanation":"Retroactive interference is when new learning disrupts the recall of older learning. Proactive interference works the other way, with old learning disrupting new.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-200","question":"Asked why he did not copy in the test, a Class 6 student says, ‘My teacher trusts me, and she would be so disappointed; I want her to think I am a good student.’ This reasoning belongs to Kohlberg’s:","options":["Pre-conventional level, Stage 2","Conventional level, Stage 3","Conventional level, Stage 4","Post-conventional level, Stage 5"],"answer":1,"explanation":"Seeking approval and wanting to be seen as ‘good’ by significant others marks Stage 3. Stage 4 would appeal to rules and order, Stage 2 to personal gain.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-201","question":"Piaget told children two stories: John accidentally broke 15 cups while opening a door; Henry broke one cup while trying to steal jam. A six-year-old says John is naughtier. This shows:","options":["Heteronomous morality: judging by damage rather than intention","Autonomous morality, in which the child carefully weighs intentions","Kohlberg’s Stage 4 reasoning about upholding law and order","Post-conventional reasoning based on universal ethical principles"],"answer":0,"explanation":"Young children in Piaget’s heteronomous stage (moral realism) judge by visible consequences; older children in the autonomous stage judge by intention and would call Henry naughtier.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-202","question":"A five-year-old keeps planning ‘shop’ and ‘doctor’ games and organising other children, but the teacher repeatedly calls her bossy and stops her games. According to Erikson, the child is at risk of developing a sense of:","options":["Shame and doubt","Inferiority","Guilt","Mistrust"],"answer":2,"explanation":"In the preschool years (initiative vs guilt) children take initiative in planning and leading play; repeated criticism of such initiative can produce guilt. Inferiority belongs to the school-age stage.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-203","question":"A student keeps a reflective diary, knows her own strengths and weaknesses well, and sets realistic personal goals. In Gardner’s theory she shows high:","options":["Interpersonal intelligence","Existential intelligence","Linguistic intelligence","Intrapersonal intelligence"],"answer":3,"explanation":"Intrapersonal intelligence is understanding oneself, one’s feelings and motives. Interpersonal intelligence concerns understanding other people.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-204","question":"Asked for unusual uses of a brick, Rahul lists 20 uses, but every one is a kind of building or support (wall, step, doorstop, pillar…). Sana lists 8 uses that include a paperweight, a weapon, a weight for exercise and crushed red powder for colour. Which statement is correct?","options":["Rahul is higher in both fluency and flexibility","Sana is higher in fluency; Rahul is higher in originality","Rahul is higher in fluency, while Sana is higher in flexibility","Both are equal in creativity, because creativity is measured only by the total number of ideas"],"answer":2,"explanation":"Fluency is the number of ideas; flexibility is the number of different categories. Rahul’s many ideas fall in one category, while Sana’s fewer ideas cover several categories.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-205","question":"An intelligence test standardised on urban children asks, ‘What do you do when an escalator stops?’ Rural children who have never seen an escalator score lower on it. The main problem is that the test:","options":["Is culturally biased: it measures exposure, not ability","Is too reliable, giving rural children the same score every time","Measures emotional intelligence instead of general intelligence","Correctly shows that rural children have lower general intelligence"],"answer":0,"explanation":"Items that depend on specific cultural experience disadvantage children who lack it; the score reflects exposure, not intelligence. Culture-fair tests try to reduce this.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-206","question":"On a modern deviation-IQ test with a mean of 100 and a standard deviation of 15, a child scores 130. Assuming a normal distribution, which statement is correct?","options":["The child’s mental age is 30% higher than her chronological age","The child scored 30% more marks than an average child of the same age","The child is in the ‘very superior’ range only if her chronological age is above 10","The child is two standard deviations above the mean, above about 97–98% of peers"],"answer":3,"explanation":"130 = 100 + 2 × 15. About 2.3% of a normal distribution lies above +2 SD. A deviation IQ compares a child with same-age peers; it is not a mental-age ratio or a percentage of marks.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-207","question":"Under the Rights of Persons with Disabilities Act, 2016, ‘reasonable accommodation’ means:","options":["Admitting a child with a disability only if she can follow the regular class without help","Appropriate adjustments, without undue burden, so she can exercise rights equally","Providing a separate special school close to the child’s home, with transport","Reducing the syllabus for all children in a class that has a child with a disability"],"answer":1,"explanation":"The Act defines reasonable accommodation as appropriate modifications and adjustments, without undue burden, to ensure equal enjoyment of rights; examples are ramps, scribes, extra time and accessible materials.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-208","question":"A mother’s employer suddenly changes her working hours to a late shift, so she can no longer help her son with homework, and his work suffers. In Bronfenbrenner’s ecological model, the mother’s workplace is part of the child’s:","options":["Microsystem","Mesosystem","Exosystem","Macrosystem"],"answer":2,"explanation":"The exosystem includes settings the child does not take part in directly but that affect him, such as a parent’s workplace. The mesosystem links two of the child’s own settings, such as home and school.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-209","question":"A 14-year-old refuses to go to school because of a small pimple, convinced that ‘everyone will be staring at me all day’. David Elkind called this form of adolescent egocentrism the:","options":["Imaginary audience","Personal fable","Identity foreclosure","Psychosocial moratorium"],"answer":0,"explanation":"The imaginary audience is the belief that one is the focus of everyone’s attention. The personal fable is the belief that one’s experiences are unique and that one is invulnerable.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-210","question":"A student learning to type improves steadily for three weeks, then shows no improvement for ten days in spite of practice, and later starts improving again. The flat period is best described as:","options":["Extinction of the learned skill","Forgetting due to disuse","Negative transfer of training","A plateau in the learning curve"],"answer":3,"explanation":"A plateau is a temporary flat stretch in a learning curve, often caused by fatigue, loss of motivation, or the need to reorganise a skill at a higher level; it does not mean learning has stopped for good.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-211","question":"A teacher assesses a science project with a tool that lists criteria (planning, data, explanation, presentation) and, for each criterion, describes what ‘beginning’, ‘developing’ and ‘proficient’ work looks like. This tool is a:","options":["Checklist","Rubric","Anecdotal record","Cumulative record"],"answer":1,"explanation":"A rubric pairs criteria with descriptions of performance at each level. A checklist records only whether a feature is present or absent.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-212","question":"During recess a teacher notices a usually shy child comforting a younger child who has fallen, and later writes a brief, factual note of what happened, with the date. This record is called:","options":["A rating scale","A cumulative record","An anecdotal record","A sociogram"],"answer":2,"explanation":"An anecdotal record is a short, objective description of a significant incident in a child’s behaviour, useful for assessing personal and social qualities.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-213","question":"Which question targets the ‘evaluating’ level of Bloom’s revised taxonomy?","options":["Name two methods of purifying water that are used in Indian homes.","Explain in your own words why boiling makes water safe to drink.","Use a filter to clean a sample of muddy water from the school pond.","Boiling or filtering: which would you recommend for your village, and why?"],"answer":3,"explanation":"Evaluating means making and justifying a judgement against criteria. Naming is remembering, explaining is understanding, and using a filter is applying.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-214","question":"A teacher who knows that a student comes from a well-off family and has neat handwriting gives his essay higher marks than another essay of equal quality. This is an example of:","options":["The halo effect","The central tendency error","The recency effect","Criterion-referenced marking"],"answer":0,"explanation":"The halo effect is when one favourable impression (neatness, background) colours the judgement of unrelated qualities. Clear rubrics and anonymous marking reduce it.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-215","question":"A 22-month-old says ‘Daddy go car’ and ‘more juice’. This stage of language development is called:","options":["Babbling","Holophrastic speech","Telegraphic speech","Cooing"],"answer":2,"explanation":"Two- or three-word utterances keeping the key content words and dropping function words are telegraphic speech. Holophrastic speech uses single words for whole ideas.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-216","question":"According to Vygotsky, the order in which speech develops in relation to thought is:","options":["Inner speech → private speech → social speech","Private speech → social speech → inner speech","Social speech → inner speech → private speech","Social speech → private speech → inner speech"],"answer":3,"explanation":"Speech first serves to communicate with others, is then turned on oneself aloud as private speech to guide action, and finally goes ‘underground’ as silent inner speech, a tool of thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-217","question":"In a science lesson the teacher gives students magnets and various objects, asks, ‘What kinds of things does a magnet attract?’, and lets them test, record and find the pattern themselves, stepping in with questions only when needed. This approach is most closely linked with:","options":["Bruner’s discovery learning","Skinner’s programmed learning","Pavlov’s classical conditioning","Thorndike’s trial-and-error learning by drill"],"answer":0,"explanation":"Bruner advocated discovery learning, in which learners find principles through active exploration with guidance; it builds understanding and transfer.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-218","question":"Which of the following statements about adolescent peer groups is most accurate for a teacher planning classroom activities?","options":["Peers have no influence once children reach adolescence, because family influence dominates","Peer influence is always negative and should be kept out of the classroom entirely","Peer acceptance matters greatly to adolescents, so structured group work can use it well","Adolescents learn best working alone, because they are naturally egocentric"],"answer":2,"explanation":"Need for belonging and peer approval rises in adolescence; it can lead to conformity, but well-planned cooperative tasks channel it towards learning and social skills.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-219","question":"A Class 2 teacher notices that a child who learnt to count objects by tens in maths now groups items in tens on her own while sorting seeds in EVS. The teacher is seeing:","options":["Negative transfer","Positive transfer","Retroactive interference","Spontaneous recovery"],"answer":1,"explanation":"Learning in one setting that helps performance in another is positive transfer. Teaching for understanding and showing links across subjects promotes it.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-220","question":"Assertion (A): According to Vygotsky, cultural tools such as language, number systems and writing shape the way children think. Reason (R): Vygotsky held that higher mental functions first appear between people and are then internalised by the individual.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Vygotsky’s ‘general genetic law’ says every function appears twice, first socially and then individually; because cultural tools are used socially before being internalised, they come to shape thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-221","question":"How many of these statements about formative and summative assessment are correct? I. The same test can be formative or summative depending on how its results are used. II. Summative assessment usually comes at the end of a unit or term. III. Formative assessment can use observation, quizzes and drafts during instruction. IV. Formative assessment is mainly for improving learning, while summative is mainly for certifying it.","options":["Only 1","Only 2","Only 3","All 4"],"answer":3,"explanation":"All four are correct. The purpose decides whether a test is formative or summative; summative comes at the end of a unit or term; formative uses many tools such as observation, quizzes and drafts; and it mainly aims to improve learning.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-222","question":"A Class 5 child often hits other children. When the teacher shouts at him and gives a slap in anger, the hitting does not stop and he begins hitting younger children more often. Social learning theory best explains this because:","options":["Punishment of any kind always increases the behaviour it follows","The child is being negatively reinforced by the teacher’s shouting","The child’s hitting is due to heredity and so cannot be changed","The teacher is modelling aggression, which the child imitates"],"answer":3,"explanation":"Bandura showed that children imitate aggressive models, especially powerful adults. Corporal punishment is also banned under Section 17 of the RTE Act.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-223","question":"An 18-month-old who saw a cousin throw a tantrum yesterday stamps her feet and screams in exactly the same way today, with the cousin nowhere around. For Piaget, this deferred imitation is important because it shows:","options":["That the child is still at the stage of simple reflex actions","The start of mental representation, as the sensorimotor stage ends","That the child has already acquired conservation of quantity","That the behaviour was learnt through classical conditioning"],"answer":1,"explanation":"Imitating a model who is no longer present requires a stored mental image; Piaget took this as evidence of emerging symbolic thought at the end of the sensorimotor period.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-224","question":"A four-year-old rides a stick as a ‘horse’ and, while playing ‘school’, sits still far longer than she does in real class. From Vygotsky’s viewpoint, the main developmental value of such pretend play is that it:","options":["Lets the child escape from all rules and adult demands for a while","Is only a way of releasing the child’s surplus physical energy","Separates meaning from objects and makes her follow the rules of a role","Shows that the child is still egocentric and should be moved on to formal tasks"],"answer":2,"explanation":"Vygotsky saw make-believe play as a leading activity that creates a zone of proximal development: substituting objects frees thought from things, and keeping to role rules builds self-regulation beyond the child’s everyday level, so she behaves ‘a head taller’ than herself.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-225","question":"To teach a child with a mild intellectual disability to wash his hands properly, the teacher breaks the skill into small steps (wet hands, apply soap, rub palms, rub backs, rinse, dry), teaches each step with demonstration and praise, and links them together. This approach is called:","options":["Task analysis","Brainstorming","Discovery learning","Programmed failure"],"answer":0,"explanation":"Task analysis breaks a complex skill into small, sequenced steps that are taught and reinforced one by one, a key strategy for learners with intellectual disabilities.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-226","question":"Varun asks unusually deep questions in class discussions and solves puzzles quickly, but rarely finishes written work, scores poorly and often disturbs others. A thoughtful teacher should first consider that he may be:","options":["A slow learner who needs simpler tasks and more drill","A child with an intellectual disability needing special help","A child who is simply indisciplined and needs stricter punishment","A gifted underachiever who is bored by unchallenging work"],"answer":3,"explanation":"High reasoning ability with poor performance and disruptive boredom is a classic profile of gifted underachievement; challenge and engagement, not simplification or punishment, address it.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-227","question":"A teacher always asks boys to move benches and girls to decorate the notice board and serve water to guests. She never states any view on gender. Through these routine practices, children are learning gender roles via the:","options":["Formal curriculum","Hidden curriculum","Spiral curriculum","Co-scholastic curriculum"],"answer":1,"explanation":"The hidden curriculum is the unstated lessons conveyed by routines, expectations and practices; here it quietly teaches stereotyped gender roles.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-228","question":"Which remark from a student best shows a mastery (learning) goal orientation rather than a performance goal orientation?","options":["‘I chose the easy questions so that I would not look stupid in front of the class.’","‘I picked the hard problem to really understand fractions, even if I get it wrong.’","‘I want to score more marks than Rohit in this test, at any cost.’","‘I only study the topics that are likely to come in the exam.’"],"answer":1,"explanation":"Mastery goals focus on understanding and improving; performance goals focus on looking competent or beating others, and often lead learners to avoid challenge.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-229","question":"After failing a test, a student says, ‘I am just not a maths person.’ Using Weiner’s attribution theory, the teacher would most help her by encouraging her to attribute the failure to:","options":["Bad luck, which is external and beyond anyone’s control","The difficulty of the test, which is external and stable over time","Low ability, which is internal and stable, so she should accept it","Insufficient effort or a poor strategy, which she can change and control"],"answer":3,"explanation":"Attributing failure to stable, uncontrollable causes such as ability lowers persistence; attributing it to effort or strategy, which the student can change, keeps motivation alive.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-230","question":"After failing repeatedly in maths and being scolded each time, a Class 5 child now does not even try the easy sums and says, ‘What’s the use? I’ll get it wrong anyway.’ This condition is best described as:","options":["Learned helplessness","Intrinsic motivation","Functional fixedness","Self-actualisation"],"answer":0,"explanation":"Seligman described learned helplessness: after repeated experiences of uncontrollable failure a person stops trying even when success is possible. Small, assured successes help to break it.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-231","question":"A teacher who used to call on a student within a second of asking a question begins waiting three to five seconds before taking an answer. According to research on wait time, the most likely effect is:","options":["Students lose interest and the class becomes noisy and restless","More students answer, and answers become longer and more thoughtful","Only the fastest students answer, just as they did before","Students answer less, because the silence makes them anxious"],"answer":1,"explanation":"Mary Budd Rowe found that a longer wait time leads to more students responding, longer and better-reasoned answers, and more questions from students.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-232","question":"How many of these statements about growth and development are correct? I. Growth refers mainly to quantitative changes such as height and weight. II. Development includes qualitative changes in functioning. III. Growth in height continues throughout life. IV. Development can continue even after physical growth stops.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"I, II and IV are correct. Growth in height stops after adolescence, but development (in thinking, skills and personality) continues throughout life.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-233","question":"According to Freud, the period from about six years to puberty, when children’s energy is directed mainly towards school learning, skills and same-sex friendships, is the:","options":["Phallic stage","Anal stage","Genital stage","Latency stage"],"answer":3,"explanation":"Freud’s latency stage covers the primary school years, when sexual impulses are relatively dormant and energy goes into learning and friendships. It roughly matches Erikson’s industry vs inferiority stage.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-234","question":"In a crèche, one caregiver responds promptly and warmly to an infant’s cries, while in another, infants are fed and changed at irregular times and their crying is often ignored. According to Erikson, infants in the second crèche are more likely to develop:","options":["A basic mistrust of the world","A sense of guilt about their own actions","A sense of inferiority","Role confusion"],"answer":0,"explanation":"Erikson’s first stage (trust vs mistrust) depends on consistent, responsive care; unpredictable or neglectful care breeds mistrust.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-235","question":"Under NEP 2020’s 5+3+3+4 structure, a 12-year-old in Grade 7 is in which stage, and what is the recommended emphasis?","options":["Preparatory stage; play- and discovery-based learning with light textbooks","Middle stage; experiential learning across subjects, with subject teachers","Secondary stage; multidisciplinary study with choice of subjects and greater critical thinking","Foundational stage; flexible, multilevel, activity-based learning"],"answer":1,"explanation":"The Middle stage covers Grades 6–8 (ages about 11–14) and introduces subject teachers and more abstract concepts through experiential learning. Grades 3–5 form the Preparatory stage and 9–12 the Secondary stage.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-236","question":"NCF 2005’s concern about heavy school bags, rote learning and exam stress drew on which earlier report?","options":["The Kothari Commission report, 1966","The Mudaliar Commission report, 1953","The Yash Pal Committee report, 1993","The Radhakrishnan Commission report, 1949"],"answer":2,"explanation":"The Yash Pal Committee’s ‘Learning Without Burden’ (1993) identified the burden of non-comprehension as a key problem, and NCF 2005 built on it.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-237","question":"Studies in several collectivist societies found that adults who reasoned mainly in terms of duties to family and community were often scored at Kohlberg’s Stage 3 or 4, rarely higher. This finding is mainly used to argue that Kohlberg’s scheme:","options":["Proves that people in those societies are morally less developed than Westerners","Shows that moral reasoning does not really develop with age at all","Is a theory of moral emotions rather than of moral reasoning","May be culturally biased towards Western ideas of individual rights and justice"],"answer":3,"explanation":"Critics argue that the highest stages reflect an individualistic, justice-based ideal; community-oriented moral reasoning may be mature in its own terms but is underscored.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-238","question":"In Martin Hughes’s ‘policeman doll’ task, many children aged about 3½ to 5 could hide a doll where two ‘policemen’ could not see it, though most failed Piaget’s three-mountains task. The finding is used to argue that:","options":["Piaget overestimated the perspective-taking abilities of young children","Young children can take another’s view when a task makes human sense to them","Egocentrism in fact lasts until the formal operational stage","Perspective taking depends only on a child’s language ability"],"answer":1,"explanation":"Hughes showed that in a meaningful, familiar context young children can decentre; the abstract mountains task masked their competence, a common critique of Piaget.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-239","question":"NEP 2020 calls for board examinations to be reformed mainly so that they:","options":["Test core competencies rather than coaching and memorisation","Are held every month instead of once at the end of the year","Are made harder so that fewer students pass and standards rise","Test only objective, factual recall that is easy to mark"],"answer":0,"explanation":"NEP 2020 wants board exams to be ‘easier’ in the sense of testing core concepts and competencies, reducing the need for coaching and rote learning.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-240","question":"The same essay is given 8/20 by one examiner and 16/20 by another. The main weakness this reveals is in the test’s:","options":["Content validity","Predictive validity","Scoring reliability","Norm-referencing"],"answer":2,"explanation":"When different scorers give very different marks to the same answer, the scoring is unreliable. Rubrics and moderation improve inter-rater reliability; validity concerns whether the right thing is measured.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-241","question":"A music school gives applicants a test to predict how well they would do if trained, though most have never studied music. This is:","options":["An achievement test","A diagnostic test","An attitude scale","An aptitude test"],"answer":3,"explanation":"An aptitude test predicts potential to learn a skill with training. An achievement test measures what has already been learnt, and a diagnostic test finds specific difficulties.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-242","question":"Each child in a class names two classmates they would most like to work with. The teacher draws the choices as arrows. One child receives no arrows from anyone. The tool and the child’s position are respectively:","options":["A sociogram; an isolate","A rating scale; a star","A cumulative record; a leader","A projective test; a rejectee"],"answer":0,"explanation":"Sociometry (Moreno) uses peer choices drawn as a sociogram; a child chosen by none is an isolate, while one chosen by many is a star.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-243","question":"In a Montessori class, a child tries to fit wooden cylinders into holes of matching sizes. If one goes into the wrong hole, the last cylinder will not fit, so the child sees the mistake without being told. This feature reflects Montessori’s principle of:","options":["Reinforcement by the teacher’s praise","Auto-education via control of error","Learning by rote repetition of tasks","Group competition among the children"],"answer":1,"explanation":"Montessori’s materials have a built-in ‘control of error’, letting the child discover and correct mistakes independently, the idea of auto-education.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-244","question":"Class 6 students run a small school stationery shop, keeping accounts, ordering stock and dividing duties, and learn maths and social skills through it. This reflects John Dewey’s view that:","options":["Learning should happen mainly through lectures and textbooks","Children should be kept away from real-life responsibilities","The school should be a miniature society built on purposeful activity","Discipline is best taught through a system of rewards and punishments"],"answer":2,"explanation":"Dewey saw the school as an embryonic community in which children learn by doing purposeful, social activities connected to life.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-245","question":"Which classroom practice is most distinctively social constructivist (Vygotskian) rather than individual cognitive constructivist (Piagetian)?","options":["A child working alone with materials to discover a rule for herself","The teacher giving a lecture followed by individual practice at desks","A child being rewarded with a star for each correct answer","Small groups debating explanations and building on one another’s ideas"],"answer":3,"explanation":"Both see learners as active, but social constructivism places the source of understanding in dialogue and joint activity with others. Lone discovery fits Piaget; rewards fit behaviourism.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-246","question":"How many of these ideas are consistent with behaviourism? I. Learning is a change in observable behaviour. II. Punishment strengthens the behaviour it follows. III. Learners actively construct meaning from experience. IV. Complex behaviour can be built by reinforcing successive approximations.","options":["Only 1","Only 2","Only 3","All 4"],"answer":1,"explanation":"I and IV are behaviourist. II is wrong: it is reinforcement that strengthens a behaviour, while punishment weakens it. III is a constructivist idea that behaviourism leaves out.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-247","question":"A very withdrawn child never speaks in class. The teacher first praises her for looking at the speaker, then only when she raises her hand, then only when she says a word, and finally only when she gives a full answer. This technique is called:","options":["Shaping","Chaining of reflexes","Extinction","Modelling"],"answer":0,"explanation":"Shaping reinforces successive approximations of the target behaviour, raising the requirement step by step (Skinner).","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-248","question":"A child in Class 3 stammers when answering. What should the teacher do?","options":["Complete the words for him so that he and the class save time","Tell him to speak faster and more confidently, without stopping","Listen patiently, without finishing his sentences or allowing mockery","Exempt him from all oral activities to spare him embarrassment"],"answer":2,"explanation":"Patience and an accepting class reduce the anxiety that worsens stammering; finishing words, hurrying him or excluding him from speaking all lower confidence.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-249","question":"A teacher tells a student caught bullying, ‘I don’t accept what you did, and there will be consequences, but I still value you and believe you can do better.’ This reflects Carl Rogers’s idea of:","options":["Conditional positive regard","Negative reinforcement","Authoritarian classroom control","Unconditional positive regard"],"answer":3,"explanation":"Rogers held that accepting the person while disapproving of a behaviour supports a healthy self-concept and growth; regard tied to good behaviour is conditional.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-250","question":"Which statement about emotion and learning is best supported by research and by NCF 2005?","options":["A safe, supportive climate aids attention and memory; chronic fear impairs them","Emotions are irrelevant to learning, which is a purely cognitive process","Fear of punishment is the most effective way to keep children attentive","Emotions matter only in co-scholastic activities such as sports and music"],"answer":0,"explanation":"Emotion and cognition are intertwined: anxiety narrows attention and hampers working memory, while a secure classroom encourages questioning and exploration.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-251","question":"In a Class 3 room in Jaipur, the teacher always rang a brass hand-bell just before scolding the class loudly. Weeks later the children fall silent and tense up at the bell even on days she is calm and does not scold. In this situation the bell is functioning as the:","options":["Conditioned stimulus","Unconditioned stimulus","Conditioned response","Neutral stimulus that is not yet conditioned"],"answer":0,"explanation":"The bell was originally neutral; after repeated pairing with scolding (the unconditioned stimulus) it alone now triggers tension, so it has become a conditioned stimulus. The tension it evokes is the conditioned response.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-252","question":"Meenu was humiliated at the blackboard during a maths period in Class 4. Now her heart races not only when she sees her maths notebook but also when she merely sees a geometry box or a page of number puzzles. The spread of her anxiety to these related objects illustrates:","options":["Stimulus discrimination","Stimulus generalisation","Spontaneous recovery","Extinction"],"answer":1,"explanation":"When a conditioned response is evoked by stimuli similar to the original conditioned stimulus, it is stimulus generalisation. Discrimination would be the opposite: responding only to the original stimulus.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-253","question":"A Class 2 child's fear of the school's guard dog was gradually removed after many friendly, harmless encounters. After the two-month summer break, on the first day back, he briefly shows fear again on seeing the dog, though less strongly than before. This reappearance is best explained as:","options":["Stimulus generalisation","Higher-order conditioning","Spontaneous recovery","Negative reinforcement"],"answer":2,"explanation":"A conditioned response that was extinguished can reappear, usually weaker, after a rest interval: Pavlov called this spontaneous recovery. It shows extinction suppresses a response rather than erasing the learning.","difficulty":"hard","source":"CTET Paper 1 · REET"},
  {"id":"cdp-child-development-254","question":"Using Pavlov's principles, which procedure would extinguish a Class 1 child's conditioned fear of the school's loud assembly siren?","options":["Pair the siren with an even stronger frightening event so the child habituates","Present the frightening event alone many times without the siren","Punish the child each time he shows fear of the siren","Sound the siren repeatedly while nothing frightening follows it"],"answer":3,"explanation":"Classical extinction occurs when the conditioned stimulus is repeatedly presented without the unconditioned stimulus. Punishing fear or adding stronger aversive events would only strengthen or add anxiety.","difficulty":"hard","source":"KVS PRT · DSSSB PRT"},
  {"id":"cdp-child-development-255","question":"Ms Kaur's frown always came just before she gave detention, so the class learned to fall silent at her frown. Later, she started tapping the duster on the desk just before frowning. Now the duster tap alone silences the class, though it was never directly followed by detention. This is an example of:","options":["Higher-order conditioning","Stimulus generalisation from the frown","Shaping by successive steps","Insight into the teacher's signals"],"answer":0,"explanation":"A new neutral stimulus (duster tap) paired with an already conditioned stimulus (frown) itself becomes conditioned: second-order or higher-order conditioning. Generalisation would need the tap to resemble the frown.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-256","question":"Consider these statements on classical conditioning. I. The conditioned response is usually similar to, but weaker than, the unconditioned response. II. Conditioning is generally strongest when the conditioned stimulus comes slightly before the unconditioned stimulus. III. Backward pairing, with the unconditioned stimulus first, is usually the most effective arrangement. IV. It mainly explains involuntary, reflex-like responses such as fear or salivation. Which are correct?","options":["I and III only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"Forward (delay) pairing, where the CS slightly precedes the UCS, works best; backward pairing produces weak or no conditioning, so III is false. The other three are standard findings.","difficulty":"very-hard","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-257","question":"Arjun, in Class 1, is terrified of the school swimming pool. His teacher first lets him sit near the pool eating his favourite snack with his best friend, then dip his feet while chatting, and only weeks later stand in the shallow end. Which principle is the teacher applying?","options":["Negative reinforcement, removing his fear each time he moves closer to the pool","Vicarious punishment of fear by watching a calm friend in the water","Counter-conditioning, pairing the pool with pleasure in graded steps","Insight learning through a sudden restructuring of the whole situation"],"answer":2,"explanation":"Pairing a feared stimulus, in small graded steps, with a response incompatible with fear (relaxation, pleasure) is counter-conditioning or systematic desensitisation, which grows out of classical conditioning.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-258","question":"A Class 5 teacher announces a visit to the science lab. The children line up eagerly with notebooks, but at the door she cancels the visit and the children become irritable and restless. Thorndike would explain their annoyance mainly through the:","options":["Law of effect","Law of exercise","Law of multiple response","Law of readiness"],"answer":3,"explanation":"By the law of readiness, when a person is prepared to act, being prevented from acting is annoying. The children were set for the activity and blocking it frustrated them.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-259","question":"In his later work (1930s), Thorndike revised his own laws of learning. Which revision did he actually make?","options":["He gave repetition less weight and found punishment weakens bonds far less than reward strengthens them","He dropped the law of effect entirely and kept only the law of exercise, since practice alone builds bonds","He made the law of readiness the master law, replacing the law of effect as the basis of all learning","He concluded that repetition without any feedback is the strongest single factor in fixing a response"],"answer":0,"explanation":"Thorndike found that repetition alone does little without satisfying consequences, and that the 'annoyer' half of the law of effect is weak: reward strengthens connections far more than punishment weakens them.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-260","question":"Riya mastered her multiplication tables in Class 3 but did not use them at all during a long illness. When she returned months later she had forgotten many of them. Which of Thorndike's laws best accounts for this?","options":["Law of readiness, since illness left her unprepared","Law of exercise, through its law of disuse","Law of effect, through the annoyance of illness","Law of associative shifting to new contexts"],"answer":1,"explanation":"The law of exercise has two parts, use and disuse: connections that are not practised weaken over time. Riya's loss came from disuse, not from an annoying consequence.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-261","question":"Which observation most clearly separates Thorndike's puzzle-box learning in cats from Köhler's insight learning in chimpanzees?","options":["Thorndike's cats were rewarded with food on escaping, while Köhler's apes received no reward","Köhler's apes needed many more trials than Thorndike's cats before reaching a solution","In Thorndike's work escape time fell gradually and irregularly, with no sudden solution","Thorndike's cats solved the box only after watching other cats escape from it first"],"answer":2,"explanation":"Trial-and-error learning shows a gradual, irregular learning curve; insight shows a sudden drop once the relationships are grasped. Köhler's apes also received food (bananas), and Thorndike's cats did not learn by observation.","difficulty":"hard","source":"CTET Paper 2 · UPTET"},
  {"id":"cdp-child-development-262","question":"A Class 2 child who has learnt to knock and say ‘May I come in?’ at the classroom door does the same, unprompted, on reaching the principal's office for the first time. Among Thorndike's subsidiary laws, this response to a new situation in the way one responded to a similar familiar one is the law of:","options":["Set or attitude","Partial activity or prepotency","Multiple response","Assimilation or analogy"],"answer":3,"explanation":"Thorndike's law of assimilation (analogy) says a learner responds to a new situation as he did to a similar one already learnt. Multiple response refers to trying varied responses until one succeeds.","difficulty":"hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-263","question":"Which classroom practice is the most direct application of Thorndike's law of effect?","options":["Making sure a beginner's correct attempt is promptly followed by success or approval","Asking children to copy each new word twenty times so the bond is fixed by practice","Starting a lesson only when children seem physically and mentally ready to write","Teaching each topic in small separate parts before showing children the whole"],"answer":0,"explanation":"The law of effect says responses followed by satisfying consequences are strengthened. Repeated copying reflects the law of exercise and starting when ready reflects the law of readiness.","difficulty":"moderate","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-264","question":"A Class 7 teacher announces that anyone who submits every homework this week will be excused from the Saturday extra worksheet. Homework submission rises sharply. The teacher has used:","options":["Positive punishment","Negative reinforcement","Negative punishment","Positive reinforcement"],"answer":1,"explanation":"Removing something unpleasant (the extra worksheet) to increase a behaviour is negative reinforcement. Any reinforcement, positive or negative, increases behaviour; punishment decreases it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-265","question":"Whenever Kabir throws chalk in class he loses ten minutes of his games period, and soon he stops throwing chalk. In operant terms the teacher has used:","options":["Negative reinforcement","Positive punishment","Negative punishment","Extinction"],"answer":2,"explanation":"Taking away something pleasant (games time) to reduce a behaviour is negative punishment (response cost). Negative reinforcement would increase a behaviour by removing something unpleasant.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-266","question":"A Class 8 science teacher gives short surprise quizzes at unpredictable times, sometimes twice a week and sometimes once in ten days. Students now revise steadily every day. Reinforcement for revising is being delivered on which schedule?","options":["Continuous reinforcement","Fixed interval","Variable ratio","Variable interval"],"answer":3,"explanation":"Reinforcement becomes available after unpredictable lengths of time, which is a variable-interval schedule; it produces steady, moderate responding without the end-of-period cramming of fixed intervals.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-267","question":"A school holds its monthly unit test on the last Friday of every month. Teachers notice students barely study in the first three weeks and cram heavily in the final week, then slack again after the test. This pattern is typical of a:","options":["Fixed-interval schedule","Variable-interval schedule","Fixed-ratio schedule","Continuous reinforcement schedule"],"answer":0,"explanation":"Predictable time-based reinforcement produces the fixed-interval 'scallop': low responding just after reinforcement, rising sharply as the known time approaches.","difficulty":"hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-child-development-268","question":"Assertion (A): A child's habit of whining for sweets, rewarded by a parent only occasionally and unpredictably, is very hard to extinguish. Reason (R): Under a variable-ratio schedule the learner has often gone unrewarded before, so a run of unrewarded responses does not signal that reward has stopped.","options":["A is true but R is false","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"Behaviour on a variable-ratio schedule is the most resistant to extinction precisely because non-reward is normal under it, so the learner cannot easily detect that reinforcement has ended.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-269","question":"Tanvi, a Class 1 child, does not speak at all in school. Her teacher first praises her for nodding, then for whispering to a friend, then for whispering to the teacher, and finally for saying a word aloud in a small group. The teacher is using:","options":["Forward chaining of already learnt steps","Extinction of silence","Shaping by successive approximations","Vicarious reinforcement"],"answer":2,"explanation":"Reinforcing closer and closer approximations of a target behaviour that the child cannot yet produce is shaping. Chaining links already learnt steps into a sequence.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-270","question":"A teacher wants Class 3 children to quickly learn the habit of writing the date on every page and then keep doing it for the rest of the year. Which reinforcement plan best fits operant research?","options":["Reinforce only now and then from the very first day, so the habit never depends on reward","Reinforce every instance throughout the whole year, so the habit never weakens","Reinforce every instance at first and then stop all reinforcement at once","Reinforce every instance at first, then gradually shift to intermittent reinforcement"],"answer":3,"explanation":"Continuous reinforcement gives the fastest acquisition, while intermittent reinforcement gives the greatest persistence; thinning from one to the other gives both. Stopping abruptly invites extinction.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-271","question":"Rohan used to call out answers and the teacher always responded to him. She now decides to ignore every call-out and attend only when he raises his hand. In the first few days his calling out becomes louder and more frequent. What should she do?","options":["Treat it as an expected extinction burst; stay consistent and reinforce hand-raising","Conclude that ignoring has failed and switch to scolding him firmly in front of the class","Respond to him occasionally so that he calms down and the burst passes sooner","Move him to the back of the room so his calling out disturbs fewer children"],"answer":0,"explanation":"A temporary surge when reinforcement is withdrawn is an extinction burst. Giving in occasionally would place calling out on an intermittent schedule and make it even harder to extinguish.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-272","question":"A Class 4 teacher tells a child who dislikes arithmetic but loves drawing: ‘Finish these five sums and then you may paint for the rest of the period.’ The arithmetic work increases. Which principle is being used?","options":["Law of readiness","Premack principle","Negative reinforcement","Vicarious reinforcement"],"answer":1,"explanation":"Using a preferred, high-frequency activity (painting) as the reinforcer for a less preferred one (sums) is the Premack principle, sometimes called 'Grandma's rule'.","difficulty":"hard","source":"KVS PRT · Super TET"},
  {"id":"cdp-child-development-273","question":"Which of the following is NOT a feature of Skinner's programmed instruction?","options":["Material broken into small, logically ordered steps called frames","The learner makes an active, written response in every single frame","The learner moves on only after the teacher grades the whole unit","Each learner works through the programme at his or her own pace"],"answer":2,"explanation":"Programmed instruction relies on immediate feedback after each frame; delaying feedback until the end of a unit violates the principle of immediate reinforcement.","difficulty":"moderate","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-274","question":"Which of these statements about punishment in school are supported by behavioural research and Indian law? I. Punishment tends to suppress a behaviour without teaching what to do instead. II. Repeated punishment can make the teacher herself a conditioned stimulus for fear. III. Mild physical punishment is permitted under the RTE Act if parents consent. IV. If any punishment is used, it is more effective when immediate and consistent.","options":["I and II only","II and III only","I, III and IV only","I, II and IV only"],"answer":3,"explanation":"Section 17 of the RTE Act, 2009 prohibits physical punishment and mental harassment, so III is false. The other statements reflect well-known behavioural findings about punishment.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-275","question":"A Class 2 teacher runs a token system: children earn stars for finishing work, and ten stars can be exchanged for extra library time. In behavioural terms, the stars are:","options":["Primary reinforcers, valued for their own sake","Unconditioned stimuli for working","Secondary (conditioned) reinforcers","Negative reinforcers that remove boredom"],"answer":2,"explanation":"Stars have no value in themselves; they become reinforcing through their link with something valued, which makes them secondary or conditioned reinforcers. Primary reinforcers satisfy biological needs.","difficulty":"moderate","source":"CTET Paper 1 · REET"},
  {"id":"cdp-child-development-276","question":"In a Class 6 classroom in Jaipur, Ravi solves every arithmetic puzzle in the textbook quickly, but when friends must share a limited budget for a cricket kit fairly among players with different needs, he cannot find a workable plan. Salma, an average scorer in written tests, quickly proposes an arrangement everyone accepts. In Sternberg’s triarchic theory, Salma’s strength lies mainly in:","options":["Componential (analytical) intelligence","Contextual (practical) intelligence","Experiential (creative) intelligence","Interpersonal intelligence"],"answer":1,"explanation":"Solving real-life problems in one’s everyday setting is Sternberg’s contextual or practical intelligence; ‘interpersonal intelligence’ belongs to Gardner’s theory, not Sternberg’s, and Ravi’s puzzle skill is the analytical (componential) part.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-277","question":"Which of the following statements about Howard Gardner’s theory are correct? I. Frames of Mind (1983) originally proposed seven intelligences. II. Naturalist intelligence was added to the list later. III. Gardner treats each intelligence as the same thing as a learning style. IV. Gardner argued that each intelligence can be measured adequately by a short paper-and-pencil test.","options":["I, II and III only","II and IV only","I and II only","I, III and IV only"],"answer":2,"explanation":"Gardner began with seven intelligences and added the naturalist one in the 1990s. He has explicitly rejected equating intelligences with learning styles and criticised reliance on short written tests, so III and IV are false.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-278","question":"Assertion (A): A student who scores well above average in mathematics is, on the whole, also likely to score somewhat above average in language tests. Reason (R): Spearman held that a general factor, ‘g’, enters into performance on all intellectual tasks, along with specific factors for each task.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Scores on different mental tests correlate positively (the ‘positive manifold’); Spearman explained this by a common g factor, with s factors accounting for the differences between tasks.","difficulty":"hard","source":"CTET · State TET"},
  {"id":"cdp-child-development-279","question":"Which of the following tasks is the clearest example of what J. P. Guilford called ‘convergent production’?","options":["Suggesting as many titles as possible for a story read in class","Writing three different endings for a folk tale the class has just heard","Completing the analogy ‘Hand : Glove :: Foot : ?’ with one word","Listing as many unusual uses as possible for an old bicycle tyre"],"answer":2,"explanation":"Convergent production narrows to a single correct answer, as in an analogy with one right completion; the other three tasks ask for many varied responses, which is divergent production.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-280","question":"A test battery used in a Bhopal school reports separate scores for verbal comprehension, word fluency, number, space, associative memory, perceptual speed and reasoning, and deliberately gives no single overall score. The test designer’s view of intelligence is closest to that of:","options":["Spearman’s two-factor theory","Cattell’s fluid and crystallised intelligence","Jensen’s Level I and Level II abilities","Thurstone’s primary mental abilities"],"answer":3,"explanation":"Thurstone identified seven primary mental abilities (exactly the seven listed) and initially rejected a single dominant g, so a profile without one overall score reflects his view.","difficulty":"hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-281","question":"A 68-year-old retired Hindi teacher in Varanasi has a richer vocabulary and general knowledge than ever, but she now solves unfamiliar timed pattern puzzles more slowly than she did at 25. This pattern is best explained by the view that:","options":["Crystallised ability is kept or grows with age while fluid ability tends to decline","Fluid intelligence keeps growing with age while crystallised intelligence steadily declines","General intelligence (g) declines equally across all abilities after middle age","Her linguistic intelligence has gradually replaced her logical-mathematical intelligence"],"answer":0,"explanation":"In Cattell’s model, crystallised intelligence (accumulated knowledge, vocabulary) holds up or rises with age, while fluid intelligence (solving novel problems quickly) peaks early and declines; option B reverses the two.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-282","question":"An 8-year-old has a mental age of 10. At 12 years, the same child has a mental age of 14, so she is still exactly two years ahead. Using the classic ratio IQ (MA ÷ CA × 100), which conclusion is correct?","options":["The ratio IQ stays at 125 because her two-year lead over her age is unchanged","The ratio IQ rises to about 140 because her mental age has increased by four years","The ratio IQ falls to 100 because both of her ages increased by the same four years","The ratio IQ falls from 125 to about 117 though she is still two years ahead"],"answer":3,"explanation":"10/8 × 100 = 125 but 14/12 × 100 ≈ 116.7. The same absolute lead gives a smaller ratio as age rises, one reason ratio IQ was replaced by the deviation IQ.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PGT"},
  {"id":"cdp-child-development-283","question":"On a deviation-IQ test with a mean of 100 and a standard deviation of 15, Pooja scores 85. Assuming scores are normally distributed, about what proportion of children of her age score BELOW her?","options":["About 16%","About 15%","About 34%","About 50%"],"answer":0,"explanation":"85 is one standard deviation below the mean; about 34% of scores lie between −1 SD and the mean, so about 50 − 34 = 16% fall below. ‘15%’ confuses the SD value with a percentage.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-284","question":"A school psychologist in Chennai still uses an intelligence test whose norms were set about 25 years ago. Given the Flynn effect, today’s children tested against these old norms will most likely:","options":["Score lower than their true standing, because tests become harder over time","Score higher than on freshly normed tests, overestimating their standing","Score the same, because well-made IQ norms stay valid and never need revision","Score randomly, because the Flynn effect makes the old test unreliable"],"answer":1,"explanation":"Average raw performance on IQ tests rose over the 20th century (the Flynn effect), so old norms are too easy a yardstick and inflate today’s IQ scores, which is why tests are periodically re-normed.","difficulty":"very-hard","source":"KVS PGT · State TET"},
  {"id":"cdp-child-development-285","question":"Match the thinkers with their contribution: 1. Salovey and Mayer 2. Daniel Goleman 3. Robert Sternberg 4. J. P. Guilford; a. Introduced the term ‘emotional intelligence’ in a 1990 research paper b. Popularised emotional intelligence through a 1995 best-selling book c. Triarchic theory of intelligence d. Structure-of-intellect model","options":["1-b, 2-a, 3-c, 4-d","1-a, 2-b, 3-d, 4-c","1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-d, 4-c"],"answer":2,"explanation":"Peter Salovey and John Mayer coined and defined emotional intelligence in 1990; Goleman’s 1995 book made it popular. Sternberg gave the triarchic theory and Guilford the structure of intellect.","difficulty":"hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-286","question":"Ankit fails to get selected for the district football team. Instead of blaming the selectors, he draws up a practice plan, keeps working at it with optimism, and tries again next season. In Daniel Goleman’s model of emotional intelligence, this mainly reflects:","options":["Empathy","Social skills with teammates","Self-awareness of feelings","Self-motivation"],"answer":3,"explanation":"Goleman’s ‘motivation’ domain covers persisting towards goals with optimism despite setbacks. Empathy and social skills concern others’ feelings and relationships, and self-awareness is only recognising one’s own emotions.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-287","question":"A child with autism who has very limited speech can draw a detailed, accurate sketch of a temple after seeing it once. Howard Gardner cites cases like this (savants and selective brain damage) mainly as evidence that:","options":["Different intelligences are relatively independent of one another","Intelligence is fixed entirely by heredity and cannot be changed","A single general intelligence underlies all of a person's abilities","Standard IQ tests measure spatial ability adequately on their own"],"answer":0,"explanation":"Savants and patients who lose one ability while keeping others show that abilities can be isolated, one of Gardner’s criteria for counting a capacity as a separate intelligence; this argues against one all-purpose g.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-288","question":"Which of the following classroom practices MISAPPLIES Howard Gardner’s theory of multiple intelligences?","options":["Offering several entry points to a topic, such as a story, a diagram and a hands-on activity","Letting students show their understanding of a chapter through a poem, a model or a presentation","Labelling a child ‘bodily-kinaesthetic’ and teaching her every subject only through movement","Using a child’s strength in music to build her confidence before a hard grammar unit begins"],"answer":2,"explanation":"Gardner himself warns against labelling children by one intelligence or treating intelligences as fixed learning styles; the theory calls for varied approaches for all children, not confining a child to one channel.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-289","question":"Before attempting a word problem, Meena decides which strategy to use, keeps checking whether it is working, and switches to drawing a diagram when she gets stuck. In Sternberg’s componential subtheory, these executive processes are called:","options":["Metacomponents","Knowledge-acquisition components","Performance components","Automatisation"],"answer":0,"explanation":"Metacomponents plan, monitor and evaluate problem-solving. Performance components actually carry out the steps, and knowledge-acquisition components learn new information.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-290","question":"Sunita, a girl from a tribal village in Bastar, finds that her hostel’s rigid meal timings clash with the early bus she must take to reach a science coaching class. Rather than skipping meals or leaving the hostel, she persuades the warden to keep a packed breakfast for students who leave early. In Sternberg’s contextual subtheory, this is an example of:","options":["Adaptation to the environment","Selection of a new environment","Automatisation of a routine","Shaping of the environment"],"answer":3,"explanation":"Sternberg’s practical intelligence works through adapting to, shaping or selecting environments. Sunita changes the environment to suit her needs, which is shaping; adapting would mean changing herself, and selection would mean moving to another hostel.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-291","question":"Asked to list uses of a brick, Rahul gives twelve answers: wall, house, hut, well, cowshed, temple, school, boundary, steps, toilet, oven and tank. On the usual divergent-thinking scoring (as in Torrance’s tests), his response is:","options":["High in flexibility but low in fluency","High in fluency but low in flexibility","High in originality and elaboration","Low in fluency and low in flexibility"],"answer":1,"explanation":"Fluency counts the number of ideas (twelve is many), while flexibility counts the number of different categories; all his ideas fall in one category, ‘building something’, so flexibility is low.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-292","question":"Gauri struggles for an hour with a geometry construction, gives up and goes to play kabaddi, and the next morning the method suddenly strikes her while brushing her teeth; she then checks it carefully. In Graham Wallas’s model of creative thinking, the time when she had stopped working on the problem consciously is the stage of:","options":["Preparation","Illumination","Verification","Incubation"],"answer":3,"explanation":"Wallas’s stages are preparation (working on it), incubation (setting it aside while ideas form unconsciously), illumination (the sudden insight) and verification (checking it). The break corresponds to incubation.","difficulty":"moderate","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-293","question":"A principal proposes that the school’s creativity club admit only students with an IQ above 140, ‘because only very intelligent children can be truly creative’. Which response is best supported by research on intelligence and creativity?","options":["Agree, since creativity rises steadily with IQ at every level of ability","Agree, since creativity and intelligence are really one and the same ability","Disagree, since creativity is purely inherited and cannot be developed","Disagree, since above a moderate IQ, IQ predicts creativity only weakly"],"answer":3,"explanation":"The threshold hypothesis holds that some reasonable level of intelligence (often put near IQ 120) helps creativity, but above it IQ and creativity are only weakly related; creativity can also be nurtured, so a high IQ cut-off is not justified.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-294","question":"Which teacher practice is most likely to SUPPRESS divergent thinking in a Class 5 classroom?","options":["Asking ‘In how many ways could we measure the length of this room?’ before teaching units","Awarding marks only when an answer matches the guidebook's model answer word for word","Accepting unusual answers and asking the child to explain the reasoning behind them","Giving children time to think before calling for answers to an open question"],"answer":1,"explanation":"Rewarding only the one ‘approved’ wording teaches children to converge on expected answers and avoid risk; the other practices invite many ideas and value original reasoning.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-295","question":"A city school selects children for its gifted programme solely on an IQ score above 130. A critic using Joseph Renzulli’s three-ring conception of giftedness would say the selection ignores:","options":["Creativity and task commitment","Emotional intelligence and parental income","Chronological age and mental age","Fluid and crystallised intelligence"],"answer":0,"explanation":"Renzulli sees gifted behaviour as the overlap of above-average ability, creativity and task commitment; an IQ cut-off captures only the first ring.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-296","question":"Imran, a Class 5 student in Pune, has dyslexia and writes slowly with many spelling errors, but his oral explanations of how pulleys and gears work are far beyond his age. The most appropriate response is to:","options":["Treat him as an underachiever who is simply not trying hard enough at his writing","Place him only in remedial reading classes until his reading reaches grade level","Recognise him as twice-exceptional: enrich his strength and support his reading","Withhold enrichment activities until his written work matches his oral ability"],"answer":2,"explanation":"A child can be gifted and have a learning disability at once (twice-exceptional); focusing only on the deficit wastes the talent and harms motivation, so both needs must be met together.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-297","question":"A three-year-old in a Bengaluru preschool says ‘I goed to the park’ and ‘I saw two mouses’, forms she has never heard from adults. Such errors are most damaging to which view?","options":["Chomsky’s view that children have an innate capacity to discover the grammatical rules of language","Skinner’s view that language is learned by imitating and being reinforced for adult speech","Vygotsky’s view that speech is first social and only later turns inward as thought","The view that children actively construct language rules from the speech they hear"],"answer":1,"explanation":"Over-regularisation shows that the child is applying a rule (add ‘-ed’, add ‘-s’) to new cases, not copying heard forms; this supports rule-based, nativist or constructivist accounts and challenges pure imitation and reinforcement.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-298","question":"A five-year-old in Lucknow talks aloud to herself while building a block tower (‘No, the big one goes at the bottom…’), and talks even more when the tower falls. Which pairing of interpretations is correct?","options":["Piaget: speech that guides her action and later turns into inner speech; Vygotsky: egocentric speech of immature thought","Piaget and Vygotsky: both see it as a sign of language delay needing speech therapy","Piaget: egocentric speech showing she cannot yet take others’ views; Vygotsky: private speech regulating her actions","Piaget and Vygotsky: both see it as useless speech that should be discouraged"],"answer":2,"explanation":"Piaget saw such talk as egocentric speech that fades as thinking matures; Vygotsky saw it as private speech, a tool of self-regulation that increases with task difficulty and later goes underground as inner speech.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PGT"},
  {"id":"cdp-child-development-299","question":"Which statement best reflects the present status of the Sapir–Whorf hypothesis among psychologists?","options":["The weak version, that language can influence some perception and memory, has support; the strong version is largely rejected","Both versions have been completely disproved, so language has no effect at all on thought or memory","The strong version, that language completely determines what people can think, is now widely accepted","Only the strong version has experimental support, because people cannot perceive colours for which they have no name at all"],"answer":0,"explanation":"Research (for example on colour terms and spatial words) shows language can shape some habits of thought (linguistic relativity), but people can perceive and think about things they have no word for, so strict linguistic determinism is rejected.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-300","question":"Assertion (A): In a Class 8 physics quiz in a Haryana school, girls scored lower than boys, which proves that girls have less natural aptitude for physics. Reason (R): Gender roles and expectations are learned through socialisation in the family, the school and the media.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"One quiz result cannot prove an innate difference; such gaps are better explained by expectations, encouragement and opportunities. R correctly states that gender roles are socially learned.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-301","question":"A three-month-old in an anganwadi holds her head steady but cannot yet sit, and she swipes at a rattle with her whole arm long before she can pick up a bead with her fingers. Which pair of principles, in that order, explains the two observations?","options":["Cephalocaudal; proximodistal","Proximodistal; cephalocaudal","Continuity; individual differences","Cephalocaudal; specific to general"],"answer":0,"explanation":"Head control before sitting is head-to-tail (cephalocaudal); whole-arm swipes before finger grasp is centre-to-periphery (proximodistal). Option B swaps the two, the commonest mix-up.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-302","question":"Riya walked at 10 months and Arjun at 15 months; both are healthy and in Class 1 now run and jump equally well. Which inference is most consistent with the principles of development?","options":["Arjun’s development is delayed and he needs remedial motor training now","The sequence of motor milestones is shared by children, but the rate varies","Both the rate and the sequence vary so much that developmental norms are useless","Early walking signals higher intelligence, so Riya will do better in academics"],"answer":1,"explanation":"Children pass through the same broad sequence (sit, stand, walk) at different rates; a five-month spread in walking is normal variation, not delay.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-303","question":"‘Development is continuous, but its rate is not uniform.’ Which observation best illustrates this statement?","options":["Height increases by exactly the same amount every year from birth to eighteen","All children speak their first word at exactly twelve months, without exception","A toddler’s vocabulary grows slowly at first and then spurts in the second year","Once a skill is mastered, development in that particular area stops for good"],"answer":2,"explanation":"Development never halts but moves in spurts and plateaus; the vocabulary spurt shows continuity with an uneven rate. Uniform yearly growth (A) contradicts the statement.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-304","question":"Assertion (A): A Class 2 teacher should not expect every child in her class to be ready to read fluently at the same time. Reason (R): Development follows a predictable sequence.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements are true, but A follows from individual differences in the RATE of development, not from the common sequence; a predictable sequence alone would not explain different readiness times.","difficulty":"very-hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-305","question":"In Gesell’s co-twin study, one twin was trained in stair-climbing for weeks from an early age; the other was trained only briefly, weeks later, and quickly caught up. What does the result mainly support?","options":["Intensive early training can make any skill appear at any age the trainer chooses","Maturation sets readiness, so practice before readiness gives little lasting gain","Motor skills depend on environment and practice alone, not on biological maturation","Identical twins always develop at different rates, whatever training they receive"],"answer":1,"explanation":"The late-trained twin matched the early-trained one with far less practice, showing that maturation (readiness) limits what early training can achieve.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-306","question":"A Class 7 girl with a strong musical bent keeps asking to join the school band, spends free periods in the music room and seeks out older students who play, which sharpens her talent further. Which kind of heredity–environment link does this illustrate?","options":["Passive gene–environment correlation via her home","Evocative gene–environment correlation from teachers","Active gene–environment correlation (niche-picking)","Canalisation of an inborn musical talent"],"answer":2,"explanation":"When a child herself seeks out settings that suit her inherited tendencies, it is active correlation or niche-picking, which grows stronger with age. Evocative would mean others reacting to her, not her choosing.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-307","question":"A cheerful infant who smiles and babbles a lot draws more talk and play from adults around her, and this extra interaction further boosts her social skills. This is best described as:","options":["Active gene–environment correlation (niche-picking)","Passive gene–environment correlation","Canalisation","Evocative gene–environment correlation"],"answer":3,"explanation":"The child’s inherited temperament evokes particular responses from others, which then shape her development: evocative (reactive) correlation. Active would require her to choose environments, which infants cannot yet do.","difficulty":"very-hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-308","question":"Both parents of a child are keen readers who fill the home with books and talk; the child inherits some of their verbal aptitude and also grows up surrounded by print. Which concept describes this?","options":["Passive gene–environment correlation","Evocative gene–environment correlation","Active gene–environment correlation","Reaction range"],"answer":0,"explanation":"Parents provide both the genes and an environment matching them, without any choice by the child: passive correlation, strongest in early childhood.","difficulty":"very-hard","source":"KVS PRT · DSSSB"},
  {"id":"cdp-child-development-309","question":"When a two-month-old is upset she cries, kicks and waves her arms with her whole body; by age four she may simply frown or say she is angry. Which principle of development does this mainly illustrate?","options":["Proximodistal direction, from the trunk out to the limbs","Cephalocaudal direction, from head to toe","Development proceeds from general to specific responses","Development is spiral rather than linear"],"answer":2,"explanation":"Diffuse whole-body reactions give way to specific, differentiated responses: the general-to-specific principle. Proximodistal is about motor control spreading from trunk to fingers, not about emotional expression.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-310","question":"A Class 1 child with an untreated hearing loss shows delayed speech, avoids playing with classmates and is falling behind in reading. Which principle of development explains why one problem has spread to so many areas?","options":["Development proceeds cephalocaudally, so problems spread from the head downwards","Development is decided solely by heredity, so all of her delays share one cause","Development in each domain runs independently, so these are three separate problems","Development in different domains is interrelated, so one difficulty affects others"],"answer":3,"explanation":"Physical, language, social and cognitive development are interlinked; hearing loss hampers speech, which in turn affects peer interaction and literacy.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-311","question":"Children who start learning a second language in early childhood usually acquire a native-like accent, whereas those who start as adults rarely do, though adults still learn grammar and vocabulary well. Which idea best explains this?","options":["There are sensitive periods when some kinds of learning come most readily","Development stops completely after puberty, so adults cannot change","Language ability is entirely inherited and is fixed at birth for every person","Adults cannot learn any new language once their first language is set"],"answer":0,"explanation":"A sensitive period is a window of heightened readiness, not an absolute cut-off; adults can still learn a language, just with more difficulty in pronunciation, so B and D overstate it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-312","question":"Which of these statements are correct? I. The sequence of development is largely similar across children. II. The rate of development is the same for all children of an age. III. Development results from interaction between heredity and environment. IV. Growth and development mean the same thing.","options":["I and III only","I, II and III only","II and IV only","I, III and IV only"],"answer":0,"explanation":"Sequence is common and heredity–environment interact (I, III). The rate differs between children (II false) and growth is quantitative while development is broader, including qualitative change (IV false).","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-313","question":"An LKG teacher has children make big arm movements tracing shapes in sand and on the board, then crayon work on large sheets, and only later pencil work in four-line notebooks. Which principle is she following?","options":["Cephalocaudal","Proximodistal","Individual differences","Development is reversible"],"answer":1,"explanation":"Control spreads from the shoulder and arm (near the body’s centre) to the wrist and fingers, so large movements precede fine pencil grip: proximodistal.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-314","question":"Two boys inherit a similar potential for height, but one suffers chronic malnutrition and ends up much shorter. Which statement best captures the heredity–environment relationship here?","options":["Heredity fixes the exact height a child will reach, whatever he eats or does","Environment alone decides height, so the boys’ shared heredity is irrelevant here","Heredity sets a range, and environment largely decides where within it a child ends up","A height lost through malnutrition will be inherited by the shorter boy’s children"],"answer":2,"explanation":"Heredity sets limits (a reaction range); nutrition and care determine how much of that potential is realised. D is the Lamarckian misconception that acquired traits are inherited.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-315","question":"Many Class 6 students in a Kendriya Vidyalaya are weak in fractions. Which step best reflects the principle that development and learning are continuous and cumulative?","options":["Start the Class 6 syllabus as written, since earlier learning does not matter","Find out what students already know about parts and wholes and build on it","Conclude that the weak students lack the inherited ability for mathematics","Wait, because maturation alone will remove the gap as they grow older"],"answer":1,"explanation":"Because each new stage builds on earlier ones, gaps must be identified and bridged from where children are. C wrongly blames heredity; D wrongly leaves learning to maturation.","difficulty":"moderate","source":"KVS TGT · NVS"},
  {"id":"cdp-child-development-316","question":"A teacher declares, ‘Give me any child and I can make him a doctor or a thief; it depends only on how I train him.’ Which is the soundest criticism of this view?","options":["It overstates the role of heredity, which training can easily overcome","It ignores the limits set by heredity and maturation, and individual differences","It is fully correct, since learning is all that matters in development","It ignores the role of reinforcement and punishment in shaping learning"],"answer":1,"explanation":"This echoes Watson’s extreme environmentalism; it ignores the contribution of heredity, maturation and individual differences. A gets the direction backwards, and D misses that reinforcement IS the training it relies on.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-317","question":"In adoption studies, children’s IQ scores tend to correlate more with their biological parents’ scores than with their adoptive parents’, yet children adopted into enriched homes often score higher on average than expected. What is the best conclusion?","options":["Only heredity matters, because the correlations follow the biological parents, not the adoptive ones","Only environment matters, because the average scores of adopted children rose","Heredity relates to individual differences; a better environment can raise the average level","Neither heredity nor environment affects intelligence, as the two results conflict"],"answer":2,"explanation":"Correlation reflects rank-order similarity (largely linked to heredity), whereas the mean level can shift with environment; both findings together show interaction, not one factor alone.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-318","question":"Which of the following does NOT illustrate the cephalocaudal principle?","options":["An infant controls eye and neck movements before controlling the trunk","At birth the head is proportionally the largest part of the body","A baby controls arm movements before finger movements","A baby sits before she stands"],"answer":2,"explanation":"Arm before fingers is centre-to-periphery, i.e. proximodistal. The other three show the head-to-tail order of cephalocaudal development.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-319","question":"Infants can distinguish speech sounds from many languages, but by around their first birthday they become expert in the sounds of their mother tongue and lose some ability to tell apart sounds their language does not use. Which view of development does this support?","options":["Development is a one-way process of gains only","Development is fixed entirely by heredity","Development proceeds from head to toe","Development involves both gains and losses"],"answer":3,"explanation":"Specialising in the home language (a gain) comes with reduced sensitivity to foreign contrasts (a loss): development is multidirectional, not only accumulation.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-320","question":"Assertion (A): Early childhood experiences have a strong influence on later development. Reason (R): Development is cumulative, with later abilities built on earlier ones.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because each stage builds on what came before, early experiences lay the base for later development; R directly explains A.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-321","question":"Phenylketonuria (PKU) is a genetic disorder that, untreated, causes intellectual disability; a special diet started in infancy largely prevents this. What does PKU best demonstrate?","options":["Genetic traits can never be modified by the environment a child grows up in","Intelligence is determined by environment alone, here by the child's diet","Diet changes a child’s genes so the disorder is no longer inherited","The effect of a genetic condition can depend on environmental conditions"],"answer":3,"explanation":"The gene is unchanged, but the environment (diet) changes its outcome: heredity and environment interact, and ‘genetic’ does not mean ‘unchangeable’.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-322","question":"What is the most appropriate way for a primary teacher to use developmental norms such as ‘most children can hop on one foot by age four’?","options":["Label any child who is even a month behind the norm as abnormal and refer him at once","Ignore norms completely, since every child is unique and cannot be compared with others","Promote to the next class only those children who meet every single norm on time","Use norms as broad guides to flag children for closer observation, allowing for variation"],"answer":3,"explanation":"Norms are averages around which normal variation is wide; they flag children for observation, not for labelling or detention. Option D balances predictability of sequence with individual differences in rate.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-323","question":"An eight-year-old not only knows more words than a four-year-old but also sorts objects into categories like ‘fruits’ and ‘vehicles’, whereas the younger child groups them by colour. The second change is best described as:","options":["Quantitative change, i.e. growth in size","Maturation without any learning","Cephalocaudal change","Qualitative change in development"],"answer":3,"explanation":"Knowing more words is a quantitative increase; a new way of organising knowledge (taxonomic rather than perceptual) is a qualitative change, which is what distinguishes development from mere growth.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-324","question":"Which classroom situation best reflects the principle that development is a product of heredity and environment working together rather than of either alone?","options":["A teacher assumes a child of illiterate parents can never learn to read well, whatever the teaching","A child with an aptitude for drawing improves greatly once given materials, time and guidance","A teacher believes rigorous daily drill can turn every child in the class into a top athlete","A child’s height is attributed solely to the diet provided at home"],"answer":1,"explanation":"Aptitude (heredity) flowers only with opportunity and guidance (environment). A wrongly treats heredity as destiny, C overstates environment, D ignores genetic potential.","difficulty":"moderate","source":"KVS PRT · NVS"},
  {"id":"cdp-child-development-325","question":"How many of these statements about growth and development are correct? I. Development continues through life, while physical growth largely stops at maturity. II. Development can be both progressive and regressive, as in old age. III. Development is predictable in direction. IV. All aspects of development proceed at the same rate in a child.","options":["One","Two","Three","Four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: different domains develop at different rates, e.g. the brain grows fastest early, reproductive organs at puberty.","difficulty":"very-hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-326","question":"Ritika, a Class 3 student in a Jaipur school, has a moderate hearing loss and uses hearing aids. Which teacher practice will help her most during whole-class explanation?","options":["Speaking much louder than usual and exaggerating lip movements so that she can catch every single word","Seating her at the back so that she is not singled out, and giving her a copy of the notes later","Facing the class at a natural pace, seating her near the front with a view of faces, and adding written key words","Excusing her from oral discussions and giving her written work instead, since listening is tiring for her"],"answer":2,"explanation":"Speech-reading needs a clear view of a natural, unexaggerated face, and visual back-up fills the gaps; shouting distorts sound through hearing aids and exaggerated lips mislead, while exclusion from discussion defeats inclusion.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-327","question":"Assertion (A): In an inclusive class, a child with a disability must be assessed on exactly the same task, in the same mode and time, as everyone else, otherwise the assessment is unfair. Reason (R): Equity in education means giving every child identical treatment.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","Both A and R are false"],"answer":3,"explanation":"Equity means giving each child what she needs to reach the same goal (e.g. extra time, a scribe, Braille), which is equality of opportunity, not identical treatment; so both A and R are false.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-328","question":"Match the arrangement with its description. 1. Segregation 2. Integration 3. Inclusion 4. Exclusion; a. The child is denied access to any form of schooling b. Children with disabilities are taught in separate special schools c. The child is placed in a regular class but must adapt to an unchanged system d. The regular school changes its curriculum, teaching and environment so that all children learn together","options":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-d, 4-a","1-b, 2-d, 3-c, 4-a","1-a, 2-c, 3-d, 4-b"],"answer":1,"explanation":"Segregation separates, integration places the child in the mainstream but expects her to fit in, and inclusion changes the system to fit every child; exclusion keeps her out altogether.","difficulty":"moderate","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-329","question":"Fatima, in Class 4 at a Lucknow school, reads fluently and writes well-organised stories. Yet she still counts on her fingers to decide whether 7 or 4 is larger, cannot estimate whether 48 + 39 is nearer 90 or 50, and keeps mixing up the steps of subtraction. Her difficulty most likely points to:","options":["Dyslexia","Dyscalculia","Dysgraphia","Mild intellectual disability"],"answer":1,"explanation":"A specific, unexpected weakness in number sense, magnitude comparison and arithmetic procedures, with strong reading and writing, fits dyscalculia; intellectual disability would show a general delay across areas.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-330","question":"Kabir, in Class 5, gives rich oral answers and reads well, plays cricket and ties his shoelaces easily, but his written work has uneven letter sizes, poor spacing and mixed capitals, and he tires quickly while writing. Which step best supports him without lowering the learning goal?","options":["Letting him show knowledge orally or by typing in tests, with short, targeted handwriting support","Giving him extra copywriting pages as homework every day until his handwriting finally improves","Deducting marks for neatness so that he learns to take more care over his written work","Exempting him from all written subjects so that he is not stressed by writing at all"],"answer":0,"explanation":"His difficulty is specific to the act of writing (dysgraphia), so an alternative mode of expression keeps the content goal intact while the skill is supported separately; extra copying and penalties only punish the disability.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-331","question":"Which of these statements about ADHD are correct? I. The signs must be seen in more than one setting, such as both home and school, not in one class only. II. It is mainly caused by poor parenting and eating too much sugar. III. Children with the mainly inattentive type are often quiet daydreamers who go unnoticed. IV. ADHD is named as one of the 21 specified disabilities in the RPwD Act, 2016.","options":["I, II and III only","III and IV only","I and III only","I, III and IV only"],"answer":2,"explanation":"ADHD shows across settings and the inattentive type is easily missed; the parenting-and-sugar idea is a myth, and the RPwD Act's list includes specific learning disabilities and autism but not ADHD as a separate category.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-332","question":"Meera, a Class 2 child on the autism spectrum, covers her ears and becomes very distressed every day during morning assembly, when loudspeakers are used. What is the most appropriate response?","options":["Insisting that she stays in the middle of the assembly every day so that she gets used to the noise","Recording each outburst as indiscipline and informing the parents so they can correct her at home","Advising the parents to keep her at home until she outgrows the problem, to avoid upsetting her","Planning a sensory adjustment, such as ear defenders or a quieter spot, with a visual schedule"],"answer":3,"explanation":"Sensory over-sensitivity is common in autism and is real distress, not defiance; reasonable adjustments and predictability let her take part, whereas forced exposure, punishment or exclusion all fail her.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-333","question":"A teacher tells her Class 4 students, ‘Come on, pull up your socks for the exam!’ Arjun, who is on the autism spectrum, bends down and pulls up his socks. Which interpretation and response are most appropriate?","options":["He is mocking the teacher, so he should be warned in front of the class to stop such behaviour","He has taken the words literally, so instructions should be literal and idioms taught explicitly","He has a hearing problem and should be referred for an audiometry test before the exam","He is not paying attention and should be moved to the front bench where she can watch him"],"answer":1,"explanation":"Many autistic children take language literally and miss implied meanings; the teacher should say exactly what she means and teach figurative expressions directly, not treat it as defiance.","difficulty":"moderate","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-334","question":"Sana, who is totally blind, studies in Class 6 of a government school in Bhopal. The class is starting a unit on triangles and angles. What is the most appropriate plan?","options":["Exempting her from geometry, since it is a visual topic, and giving her extra arithmetic practice instead","Asking a classmate to draw all her figures and write her answers for her, so she keeps pace with the class","Explaining every figure orally in detail, since she can follow spoken descriptions without needing to touch anything","Using raised-line diagrams and cut-outs she can handle, describing the board aloud, and a Taylor frame for sums"],"answer":3,"explanation":"Blind learners build spatial concepts through touch combined with description; tactile materials and adapted tools give her access to the same content, while exemption or dependence on peers denies it.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-335","question":"Parents of Ishaan, a Class 3 child with low vision, ask the teacher not to let him read print because using his weak eyes will ‘use up’ his remaining sight. What is the most appropriate response?","options":["Agree and start teaching him only through Braille and listening, so that his remaining sight is saved","Agree, but let him read print for only a few minutes a day, resting his eyes in between sessions","Explain that using residual vision does not harm it, and support print with large type, magnifiers and good contrast","Explain that low vision usually improves with age, so he can start reading print later when his eyes are stronger"],"answer":2,"explanation":"Using remaining vision does not wear it out; children with low vision are taught to use it efficiently with optical aids and adapted print, with Braille chosen on the basis of functional assessment, not fear.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-336","question":"For teaching a Class 3 child with mild intellectual disability, which of the following practices is the LEAST appropriate?","options":["Teaching a general rule in abstract form first and expecting him to apply it on his own","Breaking a skill into small steps and teaching each with demonstration and practice","Using concrete objects and real-life contexts such as shopping with coins at a class shop","Giving frequent, immediate feedback and repeating practice in varied situations"],"answer":0,"explanation":"Children with intellectual disability find abstraction and spontaneous transfer especially difficult, so concepts should start concrete, be broken into steps and be practised across settings; abstract-first teaching is the mismatch.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-337","question":"A school selects children for its ‘gifted’ programme only by their scores on a timed IQ test. Which view of giftedness most directly challenges this practice?","options":["Spearman’s idea of a general factor ‘g’ that underlies performance on all mental tasks","Renzulli’s view that giftedness is ability interacting with creativity and task commitment","Binet’s concept of mental age, measured through tasks graded by difficulty for each age","Terman’s long-term study, which identified gifted children by their high IQ scores alone"],"answer":1,"explanation":"Renzulli argued that ability alone is not giftedness; creativity and task commitment must interact with it, so a single IQ cut-off misses many gifted learners. The other three views support or rely on IQ measurement.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-338","question":"After a unit on the water cycle, a Class 5 teacher lets each child show what they have learnt through a labelled poster, a short skit, a written paragraph or a working model. Which principle of Universal Design for Learning is she applying most directly?","options":["Multiple means of representation of content","Multiple means of engagement and interest","Multiple means of action and expression","Differentiation by content"],"answer":2,"explanation":"Offering several ways for learners to demonstrate understanding is ‘action and expression’ (the ‘how’ of learning); representation concerns how content is presented, and engagement concerns interest and motivation.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-339","question":"Assertion (A): Universal Design for Learning builds flexible options into a lesson from the planning stage, instead of adding special modifications after some children fail. Reason (R): Universal Design for Learning is meant only for children with certified disabilities.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"UDL designs for learner variability from the start, which benefits every learner (like a ramp that also helps people with prams), so it is not limited to children with disabilities.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-340","question":"Before teaching fractions, a Class 4 teacher gives a short pre-test. Based on it, one group folds paper strips, a second uses fraction cards on a number line, and a third solves word problems, all working towards the same learning goal. She is differentiating:","options":["Content, according to students’ interests","Product, according to students’ learning profiles","Process, according to students’ readiness","The learning environment, according to students’ interests"],"answer":2,"explanation":"Different activities towards the same goal is differentiation of process, and grouping on pre-test results is differentiation by readiness; the product (what they finally show) and content (the goal) stay the same.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-341","question":"A teacher who claims to practise differentiated instruction divides her class in April into fixed ‘slow’, ‘average’ and ‘bright’ groups that stay the same for the whole year. What is the main problem with this?","options":["Differentiation requires that all children always do exactly the same task at the same pace","Fixed groups are the correct method; the only issue is that the names should be kept secret","Grouping of any kind is against inclusive education and should be avoided in every class","Fixed ability groups become tracking; differentiation needs flexible groups that change"],"answer":3,"explanation":"Differentiation relies on flexible grouping that shifts by task and by fresh evidence; fixed groups label children and can create a self-fulfilling prophecy, while grouping itself is not the problem.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-342","question":"A recognised school refuses to build a ramp or make any adjustment for a Class 2 child with a certified locomotor disability of 30%, arguing that the RPwD Act, 2016 applies only to ‘benchmark disabilities’ of 40% or more. Which statement is correct?","options":["The school is right, because the Act gives no educational rights to children below the 40% benchmark","The school is wrong: the 40% benchmark only unlocks extra benefits; reasonable accommodation is owed to all","The school is right, but only if it is a private unaided school that receives no government aid","The school is wrong, because every disability is treated as a benchmark disability once it is certified"],"answer":1,"explanation":"A benchmark disability (not less than 40% of a specified disability) unlocks certain extra benefits, but the Act's provisions on inclusive education and reasonable accommodation are framed for children with disabilities as a whole.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-343","question":"Consider: I. Under the RTE Act, 2009, the right to free and compulsory education covers ages 6 to 14. II. Under the RPwD Act, 2016, every child with a benchmark disability has the right to free education from 6 to 18 years. III. The RPwD Act defines inclusive education as a system in which students with and without disability learn together and teaching is suitably adapted. Which are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":3,"explanation":"All three are correct: RTE covers 6–14, the RPwD Act extends free education to 18 for children with benchmark disabilities, and it defines inclusive education as learning together with adapted teaching.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-344","question":"A private unaided school in Delhi admits children under the RTE quota for disadvantaged and weaker sections, but seats them in a separate section in the afternoon with a different uniform. How should this be judged?","options":["It is discriminatory segregation; these children should learn in the same classes with no visible marker","It is acceptable because the children may feel more comfortable with peers from similar backgrounds","It is acceptable if the parents sign their written consent to the separate arrangement","It is necessary so that the school can track the children for its fee reimbursement claims"],"answer":0,"explanation":"The 25% provision exists so that children from different backgrounds learn together; separate sections or uniforms mark and segregate them, which is discrimination, not inclusion.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-345","question":"Several children in a Class 2 class in rural Bihar are first-generation learners whose parents cannot read. Their homework is often incomplete. What is the most appropriate step for the teacher?","options":["Send notes asking the parents to arrange private tuition so the homework gets completed regularly","Design homework children can do alone or with family through talk and activity, and support them in school","Lower her expectations of these children, since they lack a literate home environment to help","Make them stand at the back until their homework becomes regular, so that the habit is built early"],"answer":1,"explanation":"First-generation learners lack academic help at home, not ability; homework that does not depend on literate parents and support in school address the real gap, while lowered expectations and punishment widen it.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-346","question":"In a Class 1 classroom in a Jharkhand village, most children speak Santhali or Mundari at home, while the textbook is in Hindi. Which approach is most appropriate?","options":["Forbidding home languages in class so that the children pick up Hindi faster through immersion","Translating every sentence of the textbook word for word into the home language throughout the year","Referring these children for speech-and-language assessment because they are slow in Hindi","Using the children’s home languages as a resource and building a bridge from them to Hindi"],"answer":3,"explanation":"Children learn a new language best when their first language is respected and used as a foundation; banning it is subtractive and damages confidence, and second-language learning is not a disorder.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-347","question":"A Class 6 teacher regularly asks the girls to decorate the classroom and serve water at events, and the boys to shift benches and manage the sound system. What is the main concern here?","options":["It wastes teaching time that should be spent on completing the syllabus for the term","It reinforces gender stereotypes through the hidden curriculum; tasks should be rotated","It is fine because it matches what boys and girls are naturally good at doing","It is fine as long as the textbook content itself is fully gender-neutral"],"answer":1,"explanation":"Routine task allocation teaches children what is ‘proper’ for each gender even if no one says it aloud; rotating tasks challenges the stereotype, and gender-neutral textbooks cannot undo what classroom practice teaches.","difficulty":"moderate","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-348","question":"On learning that Pinki’s parents are migrant construction workers, her teacher quietly assumes she will not do well. Over the term she gives Pinki less time to answer, fewer challenging questions and less praise, and Pinki’s performance actually falls. This best illustrates:","options":["Stereotype threat experienced by Pinki","The halo effect of her family's background on grading","A self-fulfilling prophecy (Pygmalion effect)","Learned helplessness after repeated failure"],"answer":2,"explanation":"The teacher's low expectation changed her own behaviour, which in turn lowered the child's performance, which is the self-fulfilling prophecy; stereotype threat is the student's own anxiety about confirming a stereotype at the moment of performance.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-349","question":"Just before a maths test, a teacher jokes, ‘Let’s see if the girls can manage this one.’ Several girls who usually do well in maths score noticeably lower that day. Which concept best explains this drop?","options":["Stereotype threat","The Pygmalion effect","The Hawthorne effect","The halo effect"],"answer":0,"explanation":"Reminding a group of a negative stereotype just before a task creates anxiety about confirming it, which lowers performance on the spot; the Pygmalion effect works through a teacher's treatment of a child over time.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-350","question":"Which of these statements about teaching children with hearing impairment are correct? I. Delayed vocabulary in such a child is often a result of reduced access to language, not of low intelligence. II. Lip-reading alone gives full access to speech, because every speech sound can be seen on the lips. III. The teacher should stand so that light falls on her face, not with a window behind her.","options":["I only","I and II only","II and III only","I and III only"],"answer":3,"explanation":"Many sounds look alike or are invisible on the lips (p/b/m, k/g), so lip-reading alone is incomplete; a well-lit face aids speech-reading, and language delay reflects reduced access, not low intelligence.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-351","question":"Ten-month-old Tara has twice found a rattle hidden under a red cloth. Now, while she watches, her mother hides it under a blue cloth placed beside the red one. Tara lifts the red cloth again. According to Piaget, this behaviour shows that:","options":["Her object permanence is still incomplete; she links the toy to the action and place where she found it before","She has entered the tertiary circular reaction substage and is deliberately varying her actions to test outcomes","She has full object permanence but is egocentric, assuming the toy is where she wants it to be","She is showing a primary circular reaction, repeating an action centred on her own body"],"answer":0,"explanation":"This is the classic A-not-B error of sensorimotor substage 4: the infant searches for hidden objects but ties them to past successful actions. Only around substage 5 does she follow visible displacements correctly.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-352","question":"A six-month-old in a crèche in Pune accidentally kicks and sees the hanging toy above her cot jingle. She then kicks again and again, smiling each time the toy moves. Piaget would place this behaviour in the substage of:","options":["Primary circular reactions","Secondary circular reactions","Tertiary circular reactions","Coordination of secondary schemes"],"answer":1,"explanation":"Secondary circular reactions (about 4 to 8 months) are repeated actions that produce an interesting effect in the external world. Primary reactions centre on the infant’s own body; tertiary reactions involve deliberately varying the action.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-353","question":"A 15-month-old drops a spoon from his high chair, then throws it, then drops it from higher, then rolls it off the edge, watching closely each time to see where it lands. Piaget would describe this as:","options":["A secondary circular reaction, since the same interesting result is reproduced","Deferred imitation of an action he saw an adult perform earlier","A tertiary circular reaction, varying actions to discover new results","Symbolic play using the spoon to stand for something else"],"answer":2,"explanation":"In tertiary circular reactions (about 12 to 18 months) the toddler experiments like a ‘little scientist’, deliberately varying actions to see what happens. A secondary reaction repeats the same action for the same effect.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-354","question":"Asked how the hills near her village came to be, a five-year-old in Uttarakhand replies, ‘Big people made them by piling up lots and lots of stones.’ Which feature of pre-operational thought does this reply show?","options":["Animism","Centration","Transductive reasoning","Artificialism"],"answer":3,"explanation":"Artificialism is the belief that natural things were made by people or human-like agents. Animism, by contrast, would attribute life or feelings to the hills themselves.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-355","question":"A Class 1 child is shown seven marigolds and three roses and agrees that all of them are flowers. Asked, ‘Are there more marigolds or more flowers?’, she says, ‘More marigolds.’ The best Piagetian explanation is that she:","options":["Cannot yet keep the whole class and a sub-class in mind at the same time","Has not learnt the words ‘marigold’ and ‘flower’, so the error is purely linguistic","Lacks object permanence for the roses, which are fewer","Is showing animism by treating the marigolds as more alive"],"answer":0,"explanation":"Failure of class inclusion comes from centration on the larger sub-class: once she thinks of the marigolds, she loses sight of the whole set. The child already knows the words, so the error is about logic, not vocabulary.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-356","question":"Three Class 2 children explain why the water poured into a taller, narrower glass is still the same amount. Match each reason with Piaget’s term. P. ‘You didn’t add any or take any away.’ Q. ‘It is taller, but it is also thinner.’ R. ‘Pour it back and it will look just like before.’ 1. Compensation (reciprocity) 2. Identity 3. Inversion (negation)","options":["P-1, Q-2, R-3","P-2, Q-3, R-1","P-2, Q-1, R-3","P-3, Q-1, R-2"],"answer":2,"explanation":"Nothing added or removed is the identity argument; height offset by width is compensation; undoing the action to return to the start is inversion. All three show the reversible thinking of concrete operations.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-357","question":"Rohit, aged 8, is sure that a clay ball flattened into a roti still has the same amount of clay, but insists that the roti now weighs less. Piaget’s term for such unevenness in the use of the same mental operation across different tasks is:","options":["Vertical décalage","Horizontal décalage","Centration","Transductive reasoning"],"answer":1,"explanation":"Horizontal décalage is the uneven appearance of one operation, such as conservation, across different contents within the same stage. Vertical décalage refers to the same content being mastered again at a higher stage.","difficulty":"very-hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-358","question":"According to Piaget, the different types of conservation are usually mastered in which order?","options":["Number → substance (mass) → weight → volume","Substance (mass) → number → volume → weight","Number → weight → substance (mass) → volume","Volume → weight → substance (mass) → number"],"answer":0,"explanation":"Conservation of number appears around 6 to 7 years, substance around 7 to 8, weight around 9 to 10, and volume only around 11 to 12. This staggered order is itself an example of horizontal décalage.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-359","question":"Given four bottles of colourless liquid and a dropper bottle that turns certain mixtures yellow, a 15-year-old first writes down every possible combination and then tests them one by one. A 9-year-old mixes them at random and stops as soon as yellow appears. The older student is showing:","options":["Seriation, the ordering skill typical of concrete operations","Tertiary circular reactions carried into adolescence","Conservation of quantity across the four liquids","Combinatorial reasoning of the formal operational stage"],"answer":3,"explanation":"Planning all possible combinations in advance is the combinatorial, hypothetico-deductive reasoning of formal operations. The younger child’s unplanned trial and error is typical of concrete operational thinking.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-360","question":"Which sequence best describes how Piaget’s equilibration works when a child meets a fact that clashes with her current idea?","options":["Accommodation → disequilibrium → assimilation → equilibrium","Equilibrium → disequilibrium → accommodation → a new, more stable equilibrium","Disequilibrium → equilibrium → accommodation → assimilation","Equilibrium → assimilation → disequilibrium → the old equilibrium restored unchanged"],"answer":1,"explanation":"A conflicting experience upsets the existing balance; the child restores it by changing her schemas (accommodation), reaching a higher-level equilibrium. Development is a move to a better balance, not a return to the old one.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-361","question":"Consider these statements about the factors Piaget saw behind cognitive development. 1. Social transmission, such as being told something, helps only if the child has schemas able to assimilate it. 2. Maturation alone is enough for conservation to appear, whatever the child’s experiences. 3. Equilibration is the self-regulating process that coordinates maturation, experience and social transmission. Which is/are correct?","options":["1 and 3 only","2 and 3 only","1 only","1, 2 and 3"],"answer":0,"explanation":"Piaget held that no single factor is sufficient; maturation sets possibilities but needs experience, and telling helps only when the child can assimilate it. Equilibration integrates the other factors, so statement 2 is wrong.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-362","question":"In the conservation-of-number task, a Class 1 child says the spread-out row of counters has ‘more’ than the bunched row. Which response from the teacher is most in keeping with Piaget’s ideas?","options":["Tell her the correct answer firmly and have her repeat it until she remembers","Praise her every time she says ‘same’, so that the correct reply is reinforced","Ask her how she knows, and let her count and rearrange both rows to test her own idea","Drop the topic until she turns seven, since stages cannot be influenced by experience"],"answer":2,"explanation":"Piaget valued the child’s own activity and the conflict between prediction and result. Drilling or rewarding the answer (behaviourist) gives no understanding, and Piaget never said experience is irrelevant, only that it must match the child’s level.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-363","question":"During a game of hide-and-seek, a four-year-old stands in the open with her hands over her eyes and calls out, ‘You can’t see me now!’ Piaget would explain this mainly as:","options":["Absence of object permanence when eyes are shut","Animism","Centration on a single dimension of the game","Egocentrism: assuming others see what she sees"],"answer":3,"explanation":"Pre-operational egocentrism is the difficulty of separating one’s own point of view from another’s. She knows she still exists, so object permanence is not the issue.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-364","question":"A five-year-old watches a pencil standing upright fall flat on the table. Asked to draw what happened, she draws only the upright pencil and the flat pencil, nothing in between. Piaget would say this reflects her tendency to:","options":["Focus on states rather than on transformations","Reason transductively from one particular to another","Use reciprocity in place of inversion","Attribute life to moving objects"],"answer":0,"explanation":"Pre-operational children attend to the start and end states and ignore the transformation linking them. This is one reason they fail conservation tasks.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-365","question":"A two-and-a-half-year-old holds a banana to her ear and says, ‘Hello, Nani!’ In Piaget’s theory this behaviour is significant because it shows:","options":["A tertiary circular reaction, varying actions to see results","The symbolic (semiotic) function that marks the pre-operational stage","Egocentric speech that will later go inward as inner speech","Conservation of identity of the banana"],"answer":1,"explanation":"Using one object to stand for another shows the child can now represent things mentally with symbols, which marks the pre-operational stage. Linking such speech to inner speech is Vygotsky’s idea, not the point here.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-366","question":"How many of these statements about Piaget’s formal operational stage are correct? I. All adolescents show formal reasoning in every subject by about 15 years. II. Even adults may use formal reasoning mainly in areas they know well. III. Schooling and culture influence whether formal operational reasoning is shown. IV. Thinking about one’s own thinking and about hypothetical possibilities develops in this stage.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"II, III and IV are correct. Later research, which Piaget himself accepted in 1972, showed formal operations are neither universal nor applied evenly; many adults use them only in familiar domains, so I is false.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-367","question":"Step 1: Meena, who believed that every sea animal with fins is a fish, learns that whales breathe air and feed milk to their young, and revises her idea. Step 2: Later she reads that dolphins do the same and immediately calls them mammals. In Piaget’s terms, Steps 1 and 2 are respectively:","options":["Assimilation and accommodation","Equilibration and disequilibrium","Accommodation and assimilation","Accommodation and accommodation"],"answer":2,"explanation":"In Step 1 she changes her schema to fit a new fact (accommodation). In Step 2 the new information fits the revised schema without change (assimilation).","difficulty":"very-hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-368","question":"A teacher keeps a notebook of the wrong answers children give and asks them, ‘How did you get that?’, because she finds that children of the same age make the same kinds of mistakes. This practice most closely follows the approach of:","options":["Skinner, who treated errors as behaviour to be extinguished","Thorndike, who saw errors as part of blind trial and error","Pavlov, who studied conditioned responses in learning","Piaget, who saw consistent errors as windows into thinking"],"answer":3,"explanation":"Piaget’s interest in cognition grew from noticing that children of the same age made similar wrong answers on intelligence tests; his clinical method probes the reasoning behind answers. Behaviourists treat errors as responses to be weakened.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-369","question":"A 20-month-old wants a chain out of a matchbox that is open only a slit. She stops, looks at the slit, slowly opens and closes her own mouth, and then pushes the box open wider. Piaget saw such behaviour as evidence of:","options":["Secondary circular reactions repeating an interesting effect","Simple reflexes being modified by experience","Mental representation: inner combination of actions before acting","Tertiary circular reactions based on open trial and error with the box"],"answer":2,"explanation":"In the final sensorimotor substage (18 to 24 months) the child begins to think out a solution internally before acting, here shown by the mouth movement imitating the opening. Tertiary reactions involve overt trial and error instead.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-370","question":"A six-year-old sorts leaves correctly by shape, but when asked why, says only, ‘It just looks right.’ She also judges quantities by how they look. Piaget would place her in the:","options":["Preconceptual sub-stage of the pre-operational period","Intuitive sub-stage of the pre-operational period","Concrete operational stage","Last substage of the sensorimotor period"],"answer":1,"explanation":"In the intuitive sub-stage (about 4 to 7 years) children solve some problems by perception and intuition but cannot explain the logic. The preconceptual sub-stage (2 to 4) is marked more by emerging symbols and play.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-371","question":"Asked what ‘Empty vessels make the most noise’ means, a 9-year-old says that empty pots ring loudly when you hit them. A 14-year-old says that people who know little often talk the most. The difference reflects the shift from:","options":["Concrete operational to formal operational thinking","Pre-operational thinking to concrete operational thinking","Assimilation to accommodation","Private speech to inner speech"],"answer":0,"explanation":"Interpreting a proverb requires abstract, figurative thought, which is characteristic of formal operations. The concrete operational child stays with the literal, physical meaning.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-372","question":"Assertion (A): Piaget regarded discussion among peers as especially useful for cognitive growth. Reason (R): Among equals, conflicting views create disequilibrium that the child must resolve herself, whereas an adult’s view tends to be accepted simply on authority.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Piaget valued socio-cognitive conflict between peers because it forces children to rethink. Disagreement with an adult tends to produce compliance rather than real accommodation.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-373","question":"A Class 3 teacher in Jaipur wants to teach fractions to children who are mostly in Piaget’s concrete operational stage. Which plan fits their thinking best?","options":["Begin with the rule for adding fractions with unlike denominators and then give practice sums","Discuss what fractions would mean in a world with no whole numbers","Ask them to learn the definitions of numerator and denominator by heart first","Let them fold paper strips and share rotis into equal parts before writing fraction symbols"],"answer":3,"explanation":"Concrete operational children reason logically about things they can see and handle. Abstract rules, rote definitions or hypothetical worlds suit formal operational thinkers.","difficulty":"moderate","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-374","question":"Which of these is NOT a characteristic of thinking in Piaget’s concrete operational stage?","options":["Decentration: attending to several features of a problem at once","Reversibility: mentally undoing an action to its start","Reasoning about hypothetical premises that contradict known facts","Seriation and class inclusion with real, concrete objects"],"answer":2,"explanation":"Reasoning from premises that contradict reality belongs to formal operations. Decentration, reversibility, seriation and class inclusion all emerge in the concrete operational stage.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-375","question":"A child sees that a short, fat clay ball and a long sausage made from it have ‘the same clay’. Piaget held that, of the following, the abilities that make this possible are:","options":["Centration and irreversibility","Decentration and reversibility","Animism and artificialism","Assimilation and egocentrism"],"answer":1,"explanation":"Conservation needs decentration (considering length and thickness together) and reversibility (mentally rolling the sausage back). Centration and irreversibility are exactly what cause pre-operational children to fail.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-376","question":"Ms. Rekha and Mr. Imran give the same 10-item quiz on fractions to their Class 5 sections on the last day of the unit. Rekha enters the scores in the register as the unit grade and starts the next chapter. Imran groups the wrong answers by error type and spends the next two periods reteaching the error of ‘adding the denominators’ before moving on. Which conclusion is most defensible?","options":["Both used formative assessment, since a short quiz is a formative tool by its nature","Both used summative assessment, since the quiz came on the last day of the unit","Rekha used it summatively, Imran formatively; how evidence is used decides the function","Imran’s use is diagnostic rather than formative, because diagnosis can only follow a summative test"],"answer":2,"explanation":"Whether assessment is formative or summative depends on how the evidence is used, not on the tool or its timing. Imran fed the evidence back into teaching; Rekha only recorded a judgement.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-377","question":"After a practice test, a Class 8 teacher stops handing out the answer key. Instead, each student compares her own work with three worked exemplars, marks exactly where her reasoning broke down and writes one strategy she will try next time. The teacher is mainly trying to develop:","options":["Students’ ability to monitor and regulate their learning, i.e. assessment as learning","A more reliable record of achievement for the term report, i.e. assessment of learning","The teacher’s own evidence for regrouping the class, i.e. assessment for learning","A norm-referenced comparison of each student with the class average on the practice test"],"answer":0,"explanation":"In assessment as learning the student is the one who uses the evidence, checking work against criteria and adjusting strategy; that metacognitive self-regulation is the goal, not grading or the teacher’s planning.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-378","question":"In a classroom trial, one group of Class 6 students gets only marks on their written work, a second group gets only specific written comments, and a third gets both marks and comments. Research on feedback (for example, Ruth Butler’s studies) most consistently predicts that on the next task:","options":["The marks-plus-comments group improves most, since it receives the most information","All three groups improve equally, since any kind of feedback motivates learners to try","The marks-only group improves most, since a number is clear, objective and easy to act on","The comments-only group improves most, since a mark draws attention away from comments"],"answer":3,"explanation":"When a grade is present, students focus on it and largely ignore the comment, so marks-plus-comments behaves much like marks alone; descriptive comments alone produced the most improvement.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-379","question":"Which teacher remark on a Class 4 child’s story is task-involving feedback rather than ego-involving feedback?","options":["‘You are the brightest child in this class, so I expect the best story from you.’","‘Your story has a clear beginning; now add a sentence showing how Meena felt.’","‘Better than last time, but Riya’s story is still the best in the class.’","‘Good work, here is a gold star for you to put on your chart.’"],"answer":1,"explanation":"Task-involving feedback points to the work and the next step; praise of the person, comparison with peers and stars draw attention to the self or to rank rather than to how to improve.","difficulty":"moderate","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-380","question":"A Class 3 teacher notices several children writing 304 for ‘thirty-four’. Before planning remedial work she gives them a short set of tasks designed only to find whether the error comes from place-value confusion or from writing numbers the way they are spoken. This set of tasks is best called:","options":["A summative test, since it checks what children have learnt in the unit so far","A diagnostic test, since it pinpoints the cause of a learning difficulty","A prognostic test, since it forecasts future achievement in mathematics","A placement test, since it decides which section a child should join"],"answer":1,"explanation":"A diagnostic test probes the root cause of a known difficulty so that remedial teaching can target it; it neither grades achievement nor predicts future performance.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-381","question":"Consider these statements: I. A summative assessment can be used formatively if its results guide the next term’s teaching. II. Formative assessment must always be informal and never recorded. III. Grading every formative task tends to weaken its formative function. IV. Summative assessment is necessarily norm-referenced. Which are correct?","options":["I and II only","II and IV only","I, III and IV only","I and III only"],"answer":3,"explanation":"Formative evidence can be structured and recorded (II is false), and summative judgements can be criterion-referenced, as in a competency test (IV is false). I and III are correct.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-382","question":"Assertion (A): Giving marks after every classroom activity in the name of CCE can turn formative assessment into continuous summative testing. Reason (R): The value of formative assessment lies in a feedback loop that changes teaching and learning, not in the number of records kept.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Frequent marking without feedback only produces more summative judgements; R explains why: what makes assessment formative is that the evidence is used to change teaching and learning.","difficulty":"hard","source":"CTET · State TET"},
  {"id":"cdp-child-development-383","question":"A state wants to know whether each Class 5 child can read a short paragraph with comprehension, regardless of how classmates perform. A test built for this purpose should be:","options":["Norm-referenced, ranking each child against a state-wide average score","Speeded, so that only quick readers are counted as successful readers","Criterion-referenced, judging each child against a set reading standard","Percentile-based, reporting the child’s position within her own class"],"answer":2,"explanation":"‘Can this child do X?’ is a criterion-referenced question; ranks and percentiles (norm-referencing) say where a child stands relative to others, not whether the standard has been met.","difficulty":"moderate","source":"KVS PRT · NVS"},
  {"id":"cdp-child-development-384","question":"A teacher decides that in every class test the top 10% of students will get grade A, the next 20% grade B, and so on, whatever the actual scores. In a section where every student has fully mastered the unit, this policy will:","options":["Correctly reward mastery, since the grading is criterion-referenced and fixed in advance","Still give lower grades to many who mastered it, because the grading is norm-referenced","Give every student grade A, since all of them have reached the required standard","Be unfair only if the test happens to be an objective-type test with one right answer"],"answer":1,"explanation":"Fixing proportions for each grade is relative (norm-referenced) grading: it reports rank, not mastery, so even students who have mastered the unit are pushed into B, C and lower grades.","difficulty":"very-hard","source":"DSSSB TGT · KVS TGT"},
  {"id":"cdp-child-development-385","question":"A Class 6 English teacher keeps a writing portfolio for each child. Which practice would most weaken the portfolio as an assessment tool?","options":["Asking each child to write a short note on why she chose each piece for it","Including early drafts alongside the final versions of the same pieces","Filling it only with neat, teacher-corrected final copies chosen by the teacher","Using shared criteria to discuss the pieces with the child and her parents"],"answer":2,"explanation":"A portfolio’s value lies in showing growth over time and the learner’s own selection and reflection; a file of polished, teacher-chosen final copies shows neither progress nor student voice.","difficulty":"hard","source":"CTET Paper II · State TET"},
  {"id":"cdp-child-development-386","question":"Which entry is the best example of a properly written anecdotal record?","options":["‘Raju is a naughty and aggressive boy who always troubles others in the games period.’","‘Raju seemed jealous of Sunil today, probably because of problems at home, I feel.’","‘Raju behaved badly in the games period today, as usual, and upset others.’","‘12 Aug, games: Raju pushed Sunil when Sunil took the ball; he said, “It was my turn.”’"],"answer":3,"explanation":"An anecdotal record is dated, specific and factual, with any interpretation kept separate; labels (‘naughty’), generalisations (‘always’, ‘as usual’) and guesses about causes make a record unreliable.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-387","question":"Match each tool with what it records: P. Checklist  Q. Rating scale  R. Analytic rubric  S. Anecdotal record — 1. Whether a behaviour or feature is present or absent  2. The degree or frequency of a trait on a graded continuum  3. A description of each performance level for each separate criterion  4. A brief factual account of a significant incident","options":["P-2, Q-1, R-3, S-4","P-1, Q-3, R-2, S-4","P-1, Q-2, R-3, S-4","P-1, Q-2, R-4, S-3"],"answer":2,"explanation":"A checklist is yes/no, a rating scale records how much or how often, an analytic rubric describes levels for each criterion, and an anecdotal record narrates an incident.","difficulty":"hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-388","question":"While rating children on a five-point scale for ‘participation’, a teacher who does not want to seem either strict or soft rates almost every child 3. Earlier, she rated one child high on every trait simply because he is very polite. These two errors are respectively:","options":["Leniency error and logical error","Central tendency error and halo effect","Halo effect and central tendency error","Severity error and leniency error"],"answer":1,"explanation":"Bunching ratings in the middle is the central tendency error; letting one favourable trait (politeness) raise ratings on all traits is the halo effect.","difficulty":"very-hard","source":"DSSSB TGT · KVS TGT"},
  {"id":"cdp-child-development-389","question":"A teacher must assess 40 short poems and also tell each child exactly which aspect, whether imagery, rhythm or word choice, needs work. Which rubric design suits this second goal, and why?","options":["An analytic rubric, since it scores each criterion separately and shows the weakness","A holistic rubric, because a single overall score is the most specific feedback","A holistic rubric, because it is always more reliable than an analytic one","No rubric, because creative writing cannot be judged against any fixed criteria"],"answer":0,"explanation":"A holistic rubric gives one overall judgement (quick but not diagnostic); an analytic rubric rates each criterion, so it tells the child which aspect to improve.","difficulty":"hard","source":"CTET Paper II · State TET"},
  {"id":"cdp-child-development-390","question":"A Class 7 social science test gives almost the same scores when repeated after a week, but all its questions are about dates and names, although the unit aimed at map reading and reasoning about causes. The test is best described as:","options":["Valid but not reliable","Neither valid nor reliable","Both reliable and valid, since consistent scores show validity","Reliable but low in content validity"],"answer":3,"explanation":"Consistent scores show reliability, but a test that ignores the unit’s main objectives does not measure what it should, so its content validity is low; consistency alone never proves validity.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-391","question":"Which of these statements are correct? I. A test cannot be valid for a purpose unless it is reasonably reliable. II. A highly reliable test is necessarily valid. III. Adding more good items to a test generally increases its reliability. IV. Inter-rater reliability matters most for essay-type and performance tasks.","options":["I and II only","II, III and IV only","I, III and IV only","I, II, III and IV"],"answer":2,"explanation":"Reliability is necessary but not sufficient for validity, so II is false. Longer tests of good items sample more consistently, and scorer agreement matters most where marking involves judgement.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-392","question":"A school uses a Class 8 aptitude test to advise students on taking science in Class 11. To check whether the test is worth using for this, the school compares the same students’ Class 8 scores with their Class 11 science results. It is examining the test’s:","options":["Content validity","Predictive validity","Test–retest reliability","Face validity"],"answer":1,"explanation":"Comparing test scores with a later criterion (future performance) checks predictive validity; test–retest reliability would compare the same test given twice.","difficulty":"hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-393","question":"Parents complain that a new Class 4 maths test ‘does not look like a maths test’ because it has stories and pictures, though subject experts confirm that its items cover every learning outcome of the term. The test is:","options":["High in content validity, though perhaps low in face validity","Low in content validity, since parents find it unconvincing","High in face validity but low in content validity overall","Invalid, since a maths test should contain only numbers and sums"],"answer":0,"explanation":"Content validity is judged by how well items sample the intended outcomes; face validity is only how valid the test appears to lay observers, which may be low here.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-394","question":"A teacher scores the odd-numbered and even-numbered items of one test separately and finds that children who do well on one half also do well on the other. She has gathered evidence of the test’s:","options":["Predictive validity against later scores","Test–retest reliability across two sittings","Internal consistency (split-half)","Content validity of the two halves"],"answer":2,"explanation":"Correlating two halves of a single administration is the split-half method, a measure of internal consistency; test–retest needs two administrations at different times.","difficulty":"hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-395","question":"Which item best assesses competency rather than recall in Class 7 science?","options":["‘Define the term acid and give one example from daily life.’","‘Name two acids found in the kitchen and the foods they occur in.’","‘What colour does blue litmus paper turn when it is dipped in an acidic solution?’","‘Ant bites inject acid. Should you apply baking soda paste or lemon juice, and why?’"],"answer":3,"explanation":"A competency item asks the learner to apply a concept to a new real-life situation; choosing a base (baking soda) to neutralise an acid needs understanding, while the others need only recall.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-396","question":"Which observation best captures the main criticism of how CCE was often implemented in schools after 2009?","options":["It made assessment too infrequent, as children were tested only at the end of the year","It often became mere record-keeping of grades, with little evidence used to improve teaching","It ignored co-scholastic areas such as attitudes, values, arts and health education","It replaced grades with raw marks, increasing examination stress among young children"],"answer":1,"explanation":"Critics noted that CCE was frequently reduced to mechanical record-keeping and frequent testing, adding to teachers’ workload without the feedback loop that makes evaluation formative.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-397","question":"A school says its evaluation is ‘comprehensive’. This claim is justified only if the school:","options":["Assesses scholastic and co-scholastic aspects such as attitudes, values and health","Assesses every chapter of every textbook at least twice a term in written tests","Uses a variety of question types, from MCQs to essays, in its written tests","Conducts tests regularly and frequently throughout the academic year"],"answer":0,"explanation":"In CCE, ‘comprehensive’ refers to covering all aspects of a child’s development, scholastic and co-scholastic; regular testing through the year relates to ‘continuous’, not ‘comprehensive’.","difficulty":"hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-398","question":"Midway through a lesson on evaporation, a teacher asks one multiple-choice question in which each wrong option matches a known misconception, and all students show their choice at the same moment with their fingers. Her main purpose is to:","options":["Award marks for participation to every student who shows an answer in class","Rank the students on their understanding before the term test begins","Decide at once, from the answer pattern, whether to move on or reteach, and whom","Prepare students for the multiple-choice format of board examinations"],"answer":2,"explanation":"Such a ‘hinge’ question is an assessment-for-learning technique: the pattern of answers tells the teacher at once which misconception exists and who needs reteaching before moving on.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-399","question":"Which is a key condition for peer assessment in Class 6 to support learning?","options":["Peers should award marks that count in the final result, so that they take it seriously","Only the best students should assess others’ work, as they know the right answers","Peers should compare each piece of work with that of the class topper","Students first understand clear shared criteria, then give specific suggestions"],"answer":3,"explanation":"Peer assessment helps learning when students understand the success criteria and give specific, usable suggestions; turning it into marking or ranking makes it threatening and unreliable.","difficulty":"moderate","source":"CTET · State TET"},
  {"id":"cdp-child-development-400","question":"A teacher asks a question and, if no hand rises within about a second, answers it herself. Research on classroom questioning suggests that increasing the wait time to three to five seconds mainly:","options":["Increases the number and length of student responses and the quality of thinking","Wastes teaching time without changing how students respond to the question","Benefits only the fastest students, who answer before the others can think","Encourages indiscipline because the class becomes idle while it waits"],"answer":0,"explanation":"Studies of wait time found that a few extra seconds lead to longer, more reasoned answers and more students responding, giving the teacher better evidence of understanding.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-401","question":"In a variation of Bandura's Bobo doll study, children who saw the adult model punished imitated the aggression least. Yet when all children were later offered attractive rewards to show what the model had done, those children reproduced the aggressive acts about as well as the others. What does this finding show?","options":["Punishment of a model prevents observers from learning the punished behaviour at all","Learning can occur by observation alone; consequences mainly affect whether it is performed","Children learn only behaviours that are directly reinforced in their own actions","Rewards create new learning that was not present before the rewards were offered"],"answer":1,"explanation":"The behaviour had been acquired by observation; the model's punishment only suppressed its performance. Bandura's learning–performance distinction is exactly this point.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-402","question":"In a Class 2 room, the teacher warmly praises Priya for drawing neat margins on her page. The next morning, many children who were not praised also draw careful margins. This change is best explained by:","options":["Vicarious reinforcement","Negative reinforcement","Stimulus generalisation","Law of readiness"],"answer":0,"explanation":"The other children saw a peer's behaviour being reinforced and increased the same behaviour themselves: vicarious reinforcement, a key idea in Bandura's social learning theory.","difficulty":"moderate","source":"CTET Paper 1 · REET"},
  {"id":"cdp-child-development-403","question":"Aman watches his chemistry teacher demonstrate a titration with full attention, but the next day he cannot recall the sequence of steps. To strengthen the weak process in Bandura's model, the teacher should:","options":["Offer him a reward for performing the titration correctly next time","Ask him to watch the same demonstration again without any discussion","Have him put the steps into words or a flow chart and rehearse them","Tell him that the titration will be tested in the final examination"],"answer":2,"explanation":"He attended but did not retain. Bandura's retention process is helped by symbolic coding (verbal labels, images) and rehearsal; rewards or exam threats work on motivation, which is not the problem here.","difficulty":"hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-child-development-404","question":"According to social learning research, which model is a Class 8 student most likely to imitate when learning to present a project confidently?","options":["A famous actor seen in an advertisement, whose life is very unlike his own","A much younger child who is praised by the teacher for at least trying","A strict adult who demonstrates the skill and then criticises the class","A classmate of similar background who is competent and visibly rewarded for it"],"answer":3,"explanation":"Imitation is more likely when the model is perceived as similar, competent and reinforced. Dissimilar or unrewarded models are less influential for a learner's own behaviour.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-405","question":"Pooja believes she cannot speak English in front of the class. Her teacher wants to use a vicarious source of self-efficacy. Which plan is most likely to work?","options":["Let her watch a classmate from her village, once nervous too, give a short English talk","Show Pooja a video of a famous news anchor reading the news fluently in English","Tell Pooja every day, firmly and warmly, that she is a confident speaker","Teach Pooja to ignore her nervousness completely and simply start speaking"],"answer":0,"explanation":"Vicarious experience raises self-efficacy most when the model is similar to the observer ('if she can, I can'). A celebrity is too dissimilar; repeated telling is verbal persuasion, a different and weaker source.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-406","question":"Isha is cheerful, popular and feels good about herself, yet she is sure she cannot write geometry proofs and avoids them. Which statement best explains this in Bandura's terms?","options":["High self-esteem always produces high self-efficacy, so her doubt must be temporary","Self-efficacy is task-specific, so it can be low for proofs even when overall self-worth is high","Self-efficacy depends only on intelligence, which is fixed for a subject like geometry","Her avoidance shows low self-esteem that she is hiding behind her cheerful manner"],"answer":1,"explanation":"Self-efficacy is a belief about one's ability to perform a particular task, while self-esteem is a general evaluation of self-worth. The two can differ widely for the same person.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-407","question":"Shy Ravi avoids group work in Class 6. Because he rarely joins in, classmates stop inviting him, which makes him more convinced that he is disliked, so he withdraws further. Bandura's concept that best describes this cycle is:","options":["Law of effect","Vicarious punishment by peers","Reciprocal determinism","Spontaneous recovery"],"answer":2,"explanation":"Reciprocal determinism holds that personal factors (beliefs), behaviour and environment continually influence one another; here each strengthens the others in a cycle.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-408","question":"According to Bandura, which of these are typical of students with high self-efficacy for a task? I. They choose more challenging versions of the task. II. They persist longer after setbacks. III. They tend to attribute failure to insufficient effort or strategy. IV. They avoid the task to protect their image.","options":["I and IV only","II and IV only","I, II and IV only","I, II and III only"],"answer":3,"explanation":"High self-efficacy leads to challenging choices, persistence and effort-based explanations of failure. Avoidance to protect one's image is typical of low self-efficacy.","difficulty":"hard","source":"KVS PRT · Super TET"},
  {"id":"cdp-child-development-409","question":"Before her first oral test, Neha notices her heart pounding and concludes, ‘This proves I will fail.’ Her teacher explains that a racing heart is a normal sign of the body getting ready to perform. Which source of self-efficacy is the teacher working on?","options":["Mastery experiences of past success","Physiological and emotional states","Vicarious experience of peers","Social comparison of grades"],"answer":1,"explanation":"Bandura listed four sources: mastery experiences, vicarious experience, verbal persuasion and physiological/emotional states. Reinterpreting bodily arousal works on the last of these.","difficulty":"hard","source":"CTET Paper 2 · NVS TGT"},
  {"id":"cdp-child-development-410","question":"Sana sets herself a goal of solving twenty sums before dinner and lets herself watch her favourite cartoon only after reaching it. In Bandura's theory this is an example of:","options":["Self-reinforcement within self-regulation","Vicarious reinforcement from a peer's success","Negative reinforcement by parents","Law of exercise through repeated sums"],"answer":0,"explanation":"Bandura described self-regulation: learners set standards, monitor themselves and reward themselves on meeting them. No outside agent is reinforcing her.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-411","question":"During a Class 9 test, students see a classmate copying openly without being caught or punished. Copying in the room then increases. According to Bandura, seeing that a forbidden act has no bad consequences produces:","options":["Response facilitation","Stimulus discrimination","A disinhibitory effect","An inhibitory effect"],"answer":2,"explanation":"Observing a model perform a prohibited act without punishment weakens observers' restraint: the disinhibitory effect. Seeing the model punished would produce an inhibitory effect.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-412","question":"Assertion (A): Bandura's social learning theory is often described as a bridge between behaviourism and cognitive psychology. Reason (R): It gives a central place to mental processes such as attention and retention while still accepting that consequences influence behaviour.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Bandura kept reinforcement (from behaviourism) but added cognition: attention, retention, expectations and self-efficacy. That combination is why the theory is called a bridge, so R explains A.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-413","question":"A Class 7 teacher wants students to learn how to approach word problems. Which form of modelling suits social cognitive theory best?","options":["Solving a problem silently on the board and asking students to copy each step","Giving a list of rules for word problems for students to memorise at home","Showing only the final answers so that students can check their own work","Solving a problem while thinking aloud about what to look for, try and check"],"answer":3,"explanation":"Cognitive modelling (thinking aloud) makes the model's invisible thinking observable, so learners can attend to and retain the strategy, not just the final steps.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-414","question":"A teacher loses her temper and shouts, ‘Stop shouting at each other!’ at a noisy Class 4. Social learning theory would predict that, over time, this habit is most likely to:","options":["Reduce shouting because children are punished for it","Teach children that shouting is a way to control others","Have no effect because children imitate only peers","Weaken the teacher's authority but not affect the children's behaviour"],"answer":1,"explanation":"Children learn from what adults do, not only from what they say. The teacher is modelling shouting as an effective means of control, which children may later imitate.","difficulty":"moderate","source":"CTET Paper 1 · UPTET"},
  {"id":"cdp-child-development-415","question":"Which of the following is NOT a characteristic of insight learning as described by Gestalt psychologists?","options":["The solution appears suddenly after a period of exploration","The solution can be transferred to similar new problems","Errors fall gradually through many blind, random trials","The solution, once found, is retained well"],"answer":2,"explanation":"Insight is sudden, transferable and durable, and rests on perceiving relationships. Gradual reduction of errors through blind trials describes Thorndike's trial-and-error learning.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-416","question":"Kavya, in Class 6, stares at an L-shaped figure whose area she must find. Suddenly she sees that it can be split into two rectangles, solves it, and then at once applies the same idea to other irregular shapes. This is best described as:","options":["Trial-and-error learning with many shapes","Classical conditioning to the L-shape","Rote memorisation of an area formula","Insight through restructuring of the figure"],"answer":3,"explanation":"Kavya reorganised how she saw the figure, grasped the relationship, and transferred it immediately, which are hallmarks of Gestalt insight learning.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-417","question":"Köhler observed that his chimpanzees solved the banana problem far more readily when the stick and the banana were in view together than when the stick lay behind them. What does this imply for setting problems for children?","options":["All parts of a solution should be in the learner's view so relations can be seen","Problems should be hidden so that children learn by random trials and errors","Children should be rewarded for every incorrect attempt so that they keep trying","The teacher should give the solution first and the problem later, to save time"],"answer":0,"explanation":"Insight depends on perceiving relationships among parts of the situation; when the parts are visible together, restructuring is far easier. Hidden elements push the learner toward blind trial and error.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-418","question":"A teacher writes the causes of the 1857 revolt in one tight cluster on the left of the board and the consequences in a separate cluster on the right, with clear space in between. Students immediately see two groups. Which Gestalt law is she using?","options":["Similarity","Closure","Proximity","Figure and ground"],"answer":2,"explanation":"Items placed close together are perceived as a group: the law of proximity. Similarity would need shared features such as the same colour or shape.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-419","question":"Match each Gestalt principle with the classroom practice that uses it. P. Similarity  Q. Closure  R. Figure–ground  S. Proximity. 1. Writing all verbs in a passage in green so they are seen as one class 2. Placing the key formula alone on a plain chart so it stands out 3. Leaving a diagram partly drawn so pupils mentally complete it 4. Seating each group's materials together on one table","options":["P-1, Q-3, R-2, S-4","P-1, Q-2, R-3, S-4","P-4, Q-3, R-2, S-1","P-3, Q-1, R-2, S-4"],"answer":0,"explanation":"Same colour groups by similarity; completing an incomplete figure is closure; making one item stand out from a plain background is figure–ground; physical nearness is proximity.","difficulty":"very-hard","source":"CTET · Super TET"},
  {"id":"cdp-child-development-420","question":"A Class 5 teacher introducing a new poem first reads the entire poem aloud with expression and discusses its overall mood before taking up difficult words line by line. Which school of thought most directly supports this approach?","options":["Pavlov's classical conditioning","Gestalt psychology","Skinner's operant conditioning","Thorndike's connectionism"],"answer":1,"explanation":"Gestalt psychology stresses that the whole is more than the sum of its parts and is perceived first, so meaning is built by moving from the whole to the parts.","difficulty":"moderate","source":"CTET Paper 1 · REET"},
  {"id":"cdp-child-development-421","question":"Köhler trained hens to peck grain from the darker of two grey papers. When then shown that same darker paper beside an even darker one, most hens pecked at the new, darker paper. What does this show?","options":["The hens had learnt a response to a particular absolute shade of grey","The hens had forgotten their training once a new paper appeared","The hens had learnt a relationship (‘the darker one’), not a specific shade","The hens were responding by chance, as birds cannot compare shades"],"answer":2,"explanation":"Transposition shows that the learner responds to the relationship between stimuli, a Gestalt argument against purely stimulus–response explanations based on absolute features.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-422","question":"A wall chart on the water cycle is crowded with bright cartoons, borders and decorations, and most Class 4 children cannot find the main diagram. In Gestalt terms the chart fails mainly because of poor:","options":["Law of exercise and repetition","Insight","Closure","Figure–ground separation"],"answer":3,"explanation":"The key content (figure) must stand out from the background. Clutter makes the background compete with the figure, so the main diagram does not emerge.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-423","question":"Which pairing of an explanation of learning with its typical evidence is INCORRECT?","options":["Trial and error – gradual, irregular fall in time taken across many trials","Insight – sudden solution that transfers to related problems","Classical conditioning – a voluntary response increased by consequences","Observational learning – new behaviour acquired by watching a model"],"answer":2,"explanation":"Voluntary behaviour strengthened by its consequences is operant conditioning. Classical conditioning pairs stimuli to evoke largely involuntary responses.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-424","question":"Assertion (A): Gestalt psychologists argued that breaking learning into isolated stimulus–response bonds misses how learners understand. Reason (R): For them, perception and learning are organised into meaningful wholes, and the whole has properties that its separate parts lack.","options":["A is false but R is true","A is true but R is false","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Because Gestaltists held that the organised whole has its own properties, they rejected atomistic S–R explanations; R gives the reason for A.","difficulty":"hard","source":"CTET Paper 2 · UPTET"},
  {"id":"cdp-child-development-425","question":"Ms Rao notices that her Class 3 children start yawning and looking out of the window whenever one child does it first, even though no one is rewarded or punished. Bandura would classify this as:","options":["Response facilitation: a model prompts an already-known behaviour","Observational learning of an entirely new skill from a peer","A disinhibitory effect, as an unpunished prohibited act is copied","Higher-order conditioning"],"answer":0,"explanation":"Response facilitation occurs when a model's actions cue observers to perform behaviours they already know and that are not prohibited. Nothing new is learnt and no restraint is lifted.","difficulty":"very-hard","source":"KVS PRT · DSSSB PRT"},
  {"id":"cdp-child-development-426","question":"A Class 1 teacher in Delhi says that children from a nearby settlement ‘come to school with no language at all’ because at home they speak a mix of Bhojpuri and Hindi. Which response is most in line with NCF 2005?","options":["She is right; such children must first be taught ‘proper’ Hindi before any other learning can begin","The children bring a full, rule-governed home language to use as a resource for school learning","Mixing languages shows confusion, so the children should be asked to speak only one language in school","The children should be referred for a language-delay assessment before formal teaching"],"answer":1,"explanation":"Every child entering school already has a rich, rule-governed language; NCF 2005 asks teachers to treat home languages and multilingualism as a resource. Calling a dialect or a language mix ‘no language’ is a deficit view.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-427","question":"Which of the following statements reflect the position of NCF 2005 on multilingualism? I. Multilingualism is a resource for the classroom. II. Research links bilingualism with cognitive flexibility and school achievement. III. A child’s home language should be dropped as early as possible so that the school language is learned faster. IV. Teachers may draw on several languages in the classroom to help children understand concepts.","options":["I, II and IV only","I and III only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"NCF 2005 calls multilingualism a resource, cites research linking bilingualism with cognitive flexibility and achievement, and supports using home languages; dropping the home language early (III) contradicts it.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-428","question":"At the start of the session, a researcher tells a Class 3 teacher in Nagpur that five named children are ‘late bloomers’ who will show great progress this year; in fact the names were picked at random. By the year’s end these five have gained more than their classmates. This outcome illustrates:","options":["The halo effect in marking these five children","The Hawthorne effect of being studied","Regression towards the mean in their scores","A self-fulfilling prophecy of teacher expectations"],"answer":3,"explanation":"This is the design of Rosenthal and Jacobson’s ‘Pygmalion in the Classroom’ study: raised teacher expectations changed how the teacher treated the children, which in turn raised their performance.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-429","question":"Two equally able groups of Class 9 girls take the same mathematics test. One group is told, ‘This test usually shows that boys do better than girls’; the other is told the test is gender-neutral. The first group scores noticeably lower. This is best explained by:","options":["Stereotype threat","The Flynn effect","Gender constancy","Test–retest unreliability"],"answer":0,"explanation":"Stereotype threat is the anxiety of possibly confirming a negative stereotype about one’s group, which can lower performance on the very task the stereotype concerns, even when ability is the same.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-430","question":"Assertion (A): Labelling a child as a ‘slow learner’ in Class 2 can lower her achievement in later years. Reason (R): Labels shape the teacher’s expectations and the child’s own self-concept, and both affect future learning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Labels tend to be self-fulfilling: teachers give labelled children fewer challenges and less wait time, and the children come to see themselves as incapable, which depresses later achievement.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-431","question":"An intelligence test used in a rural block of Odisha includes picture items asking children to name an escalator, a lift button and a parking meter. Many children score low on these items. The most valid conclusion is that:","options":["The children have lower general intelligence than children from urban areas","The children have weak visual memory for pictured objects","The items carry cultural bias, measuring familiarity with urban objects","The test is valid because it measures what children ought to know"],"answer":2,"explanation":"Items that depend on experiences common in one group but rare in another measure exposure, not intelligence; low scores here reflect cultural bias in the test content.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-432","question":"Which of these statements about ‘culture-fair’ intelligence tests such as Raven’s Progressive Matrices are correct? I. They reduce dependence on language and specific school knowledge. II. They use mainly non-verbal items such as patterns and figures. III. They are completely free of cultural influence. IV. Familiarity with test-taking and abstract patterns can still affect scores.","options":["I and III only","I, II and IV only","II and III only","I, II, III and IV"],"answer":1,"explanation":"Non-verbal tests reduce, but cannot remove, cultural influence: schooling and familiarity with abstract figures and timed tests still matter, so no test is truly ‘culture-free’ (statement III is false).","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-433","question":"A textbook states that ‘the heritability of IQ in a certain population is about 0.5’. Which interpretation is correct?","options":["Half of each child’s IQ points come from genes and half from the environment","Any IQ difference between two different populations is half genetic in origin","IQ cannot be changed by more than 50% through education, however good it is","About half the variation in IQ within that population is linked to genetic differences"],"answer":3,"explanation":"Heritability describes the share of variation within a particular population linked to genetic variation; it says nothing about an individual’s IQ, does not fix the limits of change, and cannot be applied to differences between groups.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-434","question":"Which teacher remark reflects ‘deficit thinking’ about children from low-income families?","options":["‘Munna works in the fields after school, so I give him class time to finish practice work.’","‘Children from that basti have no interest in studies; expecting much from them is pointless.’","‘Many of my students know a lot about crops and markets; I use that in my maths lessons.’","‘Some students have no books at home, so I keep a class library they can borrow from.’"],"answer":1,"explanation":"Deficit thinking blames the child’s home and community and lowers expectations. The other remarks recognise constraints or draw on children’s real knowledge while keeping expectations high.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-435","question":"In a Mumbai school, children whose parents read English newspapers, take them to museums and talk at home in the style used by teachers seem to ‘fit’ school more easily and are often judged more able. The sociologist Pierre Bourdieu’s term for the advantage these children carry is:","options":["Emotional capital","Crystallised intelligence","Cultural capital","Social learning"],"answer":2,"explanation":"Cultural capital is familiarity with the dominant culture’s language, tastes and knowledge, which schools tend to reward as if it were natural ability, reproducing social inequality.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-436","question":"Which of the following statements about individual differences are correct? I. They arise from the interaction of heredity and environment. II. A single child may be strong in some abilities and weak in others. III. All children of the same age in a class learn best at the same pace. IV. NCF 2005 recommends permanently streaming young children into ability groups.","options":["I and IV only","II and III only","I and II only","I, II and IV only"],"answer":2,"explanation":"Differences come from heredity–environment interaction and exist both between and within children. A uniform pace ignores these differences, and NCF 2005 cautions against rigid, permanent ability grouping.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-437","question":"Aarav, a Class 4 student, draws remarkably detailed maps of his village but reads much below his class level. The difference between his drawing and reading abilities is an example of:","options":["Inter-individual difference","Gender difference","Cultural difference","Intra-individual difference"],"answer":3,"explanation":"Intra-individual differences are variations among the abilities of the same person; inter-individual differences are differences between persons.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-438","question":"A Class 4 teacher in Hyderabad writes in a report card: ‘Lakshmi can read an unseen Telugu paragraph fluently and answer four of five comprehension questions correctly.’ This is an example of:","options":["Norm-referenced reporting","Criterion-referenced reporting","Ipsative ranking against peers","Percentile reporting"],"answer":1,"explanation":"Criterion-referenced reporting describes what a learner can do against a defined standard; norm-referenced reporting (such as percentiles or ranks) compares her with other learners.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-439","question":"Which reform is most in line with NCF 2005’s recommendations on examinations?","options":["Making board exams longer so that they cover the whole syllabus in more detail","Adding more board-level exams from Class 5 onwards to raise standards across schools","Replacing all written tests with oral tests only, to remove the fear of writing","Shifting exams towards understanding and application, with less rote recall and stress"],"answer":3,"explanation":"NCF 2005 criticised exams that reward rote memory and cause stress, and called for questions testing understanding and application and for more flexible, less high-stakes examinations.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-440","question":"A Class 7 science teacher in Kochi ends each lesson by asking students to write one thing they understood and one question they still have; she uses the slips to plan the next day’s lesson. This is best described as:","options":["Assessment of learning","Summative assessment","Assessment for learning","Norm-referenced testing"],"answer":2,"explanation":"Assessment for learning is ongoing and formative: the evidence is used to adjust teaching while learning is happening, not to grade or rank at the end.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-441","question":"A school plans to place Class 3 children into ‘bright’ and ‘dull’ sections on the basis of a single IQ test. Which is the most valid criticism?","options":["IQ tests sample few abilities, reflect language and background, and labels can self-fulfil","IQ tests are unreliable because a child's scores change randomly from day to day","IQ tests should be used only for older children; otherwise the plan is sound","Sectioning is fine but should be based on parents’ income and education instead"],"answer":0,"explanation":"A single score leaves out creativity, practical and other abilities, is shaped by language and opportunity, and fixed sections lower expectations for the ‘dull’ group, worsening the gap.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-442","question":"While checking answers on ‘causes of the 1857 revolt’, a teacher in Patna gives higher marks to students with neat handwriting and good behaviour in class, even when the content is similar to others’. This assessment error is called:","options":["The halo effect","The central tendency error","The recency effect","The Flynn effect"],"answer":0,"explanation":"The halo effect occurs when an overall impression or an unrelated trait (neatness, conduct) colours the judgement of a specific performance.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-443","question":"Sonamoni, whose home language is Santhali, takes a verbal IQ test in Hindi in her Jharkhand school and scores 78. What is the most defensible interpretation?","options":["She should be retested in Hindi after a month of coaching in test-taking skills","The score is valid but should be kept confidential so that she is not labelled","The test likely underestimates her; assess with non-verbal tasks or in Santhali first","The score suggests slow learning, so she needs extra remedial support in all subjects"],"answer":2,"explanation":"A verbal test in a language she has not mastered measures her Hindi, not her intelligence, so a fair, non-verbal or home-language assessment is needed. Retesting in Hindi after coaching is tempting but keeps the same language barrier in place.","difficulty":"very-hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-444","question":"An observer in a co-educational Class 8 science class records that the teacher asks boys most of the follow-up ‘why’ questions, gives them longer wait time and more detailed feedback, while girls are mostly praised for neatness. This pattern is best described as:","options":["Fair treatment, since the teacher never says anything against girls","Assessment for learning tailored to each group","Evidence that boys are by nature more interested in science than girls","Gender bias working through the hidden curriculum of classroom talk"],"answer":3,"explanation":"Differences in questioning, wait time and type of feedback send unspoken messages about who is a ‘science person’; this is gender bias through the hidden curriculum even without any explicit statement.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-445","question":"After being shown a picture of a woman flying a plane, a six-year-old later insists she saw ‘a man pilot’. Which theory best explains this memory distortion?","options":["Freud’s theory of identification with the same-sex parent during early childhood","Gender schema theory: children organise and distort information to fit gender categories","Piaget’s theory that object permanence is incomplete at six","Bandura's view that children copy only same-sex models they see"],"answer":1,"explanation":"Sandra Bem’s gender schema theory holds that children build mental categories of what fits each gender and tend to forget or distort information that does not fit them, as in remembering the pilot as a man.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-446","question":"Four-year-old Rohan says, ‘I am a boy and I will grow up to be a man like Papa’, but also says that if he wore his sister’s frock he would become a girl. In Kohlberg’s account of gender understanding, Rohan has reached:","options":["Gender stability but not gender constancy","Gender identity only, without stability","Full gender constancy across all situations","No gender understanding at all"],"answer":0,"explanation":"Rohan knows his gender (identity) and that it stays the same over time (stability), but thinks it changes with clothes, so he lacks constancy (consistency across situations), usually reached around 5–7 years.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-447","question":"Assertion (A): Children in all cultures master the complex grammar of their language within a few years, even though the speech they hear is often incomplete and full of errors. Reason (R): Noam Chomsky proposed that children have an inborn language acquisition device that supplies universal principles of grammar.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Chomsky’s ‘poverty of the stimulus’ argument says imperfect input cannot by itself explain rapid mastery of grammar, so an innate LAD with universal grammar is proposed as the explanation.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-448","question":"Which of the following statements is consistent with Vygotsky’s view of thought and language?","options":["Language is merely a reflection of thought and plays no role in shaping it","Thought and speech have different roots and merge around age two, so thought becomes verbal","Children first think in inner speech and only later begin to speak aloud to others","Speech is an inborn module that develops independently of social interaction"],"answer":1,"explanation":"Vygotsky argued that pre-linguistic thought and pre-intellectual speech develop separately and then join, after which language becomes a major tool of thinking; inner speech develops last, from social and private speech.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-449","question":"A Class 2 teacher in Indore says, ‘Teaching a child who cannot yet conserve the words “same amount” will not by itself make him understand that pouring water into a taller glass does not change the quantity.’ Her view is closest to:","options":["Vygotsky’s view that learning the words drives the formation of concepts","Chomsky’s view that grammar is innate and needs only exposure","Piaget’s view that language reflects thought, which follows cognitive growth","Skinner’s view that verbal behaviour is shaped by reinforcement"],"answer":2,"explanation":"Piaget held that language depends on and reflects the level of thought: a child can learn the words but not the concept until the underlying operations develop.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-450","question":"During daily picture-book time, a mother in Kolkata points and names objects, waits for her toddler to respond, and expands his ‘doggy run’ into ‘Yes, the dog is running fast’. Jerome Bruner called such patterned adult support for language learning the:","options":["Language Acquisition Device (LAD) in action","Zone of Proximal Development in language","Universal grammar","Language Acquisition Support System (LASS)"],"answer":3,"explanation":"Bruner proposed LASS to stress that adults scaffold language through routines, turn-taking and expansions, complementing Chomsky’s innate LAD.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-451","question":"During a maths test, a Class 4 teacher gives a child a series of graded hints whenever he gets stuck and records how many hints he needs before he succeeds. She uses this record to plan his next lessons. This approach is best described as:","options":["Summative assessment of what he has learnt by the end of the unit","Norm-referenced testing of the child against classmates","Dynamic assessment, estimating the child’s zone of proximal development","A purely diagnostic test for a specific learning disability"],"answer":2,"explanation":"Dynamic assessment builds on Vygotsky’s ZPD: it measures not only what a child can do alone but how much and what kind of help he needs. A static test captures only the independent level.","difficulty":"very-hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-452","question":"A Class 4 child can add two-digit numbers alone, can add three-digit numbers with carrying only when the teacher prompts each step, and cannot do long division even with full help. According to Vygotsky, instruction for her should now focus on:","options":["Two-digit addition, until it is perfect and fully automatic","Three-digit addition with carrying, with support that is gradually withdrawn","Long division, because hard tasks speed up development","Whatever the rest of the class is doing, since the ZPD is the same for a whole age group"],"answer":1,"explanation":"Three-digit addition lies in her ZPD: beyond her independent level but within reach with help. Two-digit work is already mastered, long division is beyond even assisted performance, and ZPDs differ between children.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-453","question":"Which sequence of teacher actions best shows scaffolding being faded correctly while a Class 5 child learns to write a paragraph?","options":["Child writes alone → teacher gives hints → teacher models the paragraph → teacher and child write together","Teacher models a paragraph → they write one together → teacher gives only hints → child writes alone","Teacher gives hints → child writes alone → teacher models the paragraph → teacher and child write together","Teacher models a paragraph → child writes alone → teacher and child write together → teacher gives hints"],"answer":1,"explanation":"Support should start high and be reduced step by step as competence grows, ending with independent performance. The other orders either begin without support or add it back after independence.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-454","question":"How many of these statements about private speech are supported by Vygotsky’s theory and later research? I. Children use more private speech when a task is very easy than when it is challenging. II. Private speech gradually becomes silent inner speech. III. Children who talk to themselves on hard tasks are usually less capable than those who stay silent. IV. Private speech helps children plan and regulate their actions.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and IV are correct. I is reversed: private speech rises on moderately challenging tasks. III is a misconception: Berk and others found that children who use it often perform better.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-455","question":"A child uses the word ‘brother’ correctly at home but cannot say what a brother is. In school she learns ‘photosynthesis’ through a definition but cannot connect it to the plants on her windowsill. Vygotsky would call these respectively:","options":["Scientific concept and spontaneous concept","Elementary function and higher mental function","Spontaneous concept and scientific concept","Assimilated schema and accommodated schema"],"answer":2,"explanation":"Spontaneous concepts grow from everyday experience and are used without conscious awareness; scientific concepts are learnt systematically through instruction. Vygotsky argued that good teaching links the two so that each strengthens the other.","difficulty":"very-hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-456","question":"A grandmother ties a knot in the end of her dupatta so that she will remember to buy medicine on the way home. In Vygotsky’s terms, the knot is:","options":["A psychological tool (sign) that turns natural memory into mediated memory","A conditioned stimulus formed by repeated pairing of the knot with buying medicine","A schema that has been accommodated to fit the new information","An iconic representation of the medicine in Bruner’s sense"],"answer":0,"explanation":"Vygotsky used exactly such examples to show how people use signs to control their own mental processes. Mediated memory is a higher mental function, unlike unaided natural memory.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-457","question":"Thirteen-year-old Kabir learns to use a new video-editing app from his nine-year-old sister, who shows him the steps and corrects his mistakes. From Vygotsky’s viewpoint, the sister is acting as:","options":["A peer who cannot teach Kabir, since a younger child is less developed","A model only for observational learning in Bandura’s sense","A source of disequilibrium in Piaget’s sense","The more knowledgeable other for this particular task"],"answer":3,"explanation":"The MKO is whoever knows more about the specific task, regardless of age or status. Her guiding and correcting goes beyond simple modelling.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-458","question":"In ‘reciprocal teaching’ of reading, the teacher first models four strategies (summarising, questioning, clarifying and predicting) and then gradually lets students take turns leading the group discussion. The idea most directly behind this method is:","options":["Operant shaping through reinforcement of each strategy","Scaffolding within the zone of proximal development","Piaget’s concept of horizontal décalage in reading","Learning by insight into the text"],"answer":1,"explanation":"Reciprocal teaching, developed by Palincsar and Brown, transfers responsibility from teacher to students as they become competent, which is Vygotskian scaffolding in the ZPD.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-459","question":"At first, a three-year-old counts mangoes only while her mother points to each one and counts aloud with her. Months later she points to each mango herself and whispers the numbers. Later still, she counts silently without pointing. Vygotsky would describe this as:","options":["Internalisation: what happens first between people later occurs within her","Assimilation of counting into an existing schema, then accommodation","Maturation unfolding at its own pace regardless of the mother’s help","Shaping by successive approximations, each reinforced by the mother"],"answer":0,"explanation":"Vygotsky’s general genetic law says every higher function appears twice, first socially and then individually. Counting moves from shared activity to whispered self-guidance to silent mental action.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-460","question":"Assertion (A): Vygotsky held that the only ‘good learning’ is that which runs ahead of development. Reason (R): Instruction aimed within the zone of proximal development awakens functions that are still in the process of maturing.","options":["Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"For Vygotsky, learning leads development: teaching aimed only at matured functions adds nothing new. R gives the reason, since instruction in the ZPD pulls developing functions forward.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-461","question":"Children in a weaving community in Assam become skilled at estimating thread lengths and patterns, while children in a city school become skilled at written arithmetic. Which explanation fits Vygotsky’s theory best?","options":["Both groups pass through the same universal stages at exactly the same ages","Cognitive skills develop through the tools and activities a culture offers","Weaving children are less intelligent because they lack formal operations","The differences arise only from the maturation of the brain with age"],"answer":1,"explanation":"Vygotsky saw cognitive development as shaped by the cultural tools and practices children take part in. He did not propose universal, culture-free stages, and different skills are not proof of lower intelligence.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-462","question":"Teacher X gives every child the same full explanation whenever they ask for help. Teacher Y gives a more specific hint after a child makes an error, and less help after the child succeeds. Teacher Y’s approach is best described as:","options":["Inconsistent, since all children should get equal help from a fair teacher","Negative reinforcement of correct answers by withdrawing help","Contingent scaffolding, adjusting help to the learner’s ongoing performance","Discovery learning without any guidance from the teacher"],"answer":2,"explanation":"Effective scaffolding is contingent: more help when the learner struggles and less when she succeeds. Equal help for all ignores differences in each child’s ZPD.","difficulty":"hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-463","question":"Consider these statements about Vygotsky’s zone of proximal development. 1. A child’s ZPD is fixed by her IQ and does not change. 2. Two children with the same independent level may have ZPDs of very different widths. 3. Once a task within the ZPD is mastered, the zone moves forward to new tasks. Which is/are correct?","options":["1 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The ZPD is dynamic: it shifts as learning occurs and differs between children with the same independent level. It is not a fixed trait like an IQ score.","difficulty":"very-hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-464","question":"Drawing a picture, a five-year-old finds there is no blue crayon and says aloud, ‘Where’s the blue? No blue... I’ll make the sky with purple and wet it.’ How would Piaget and Vygotsky respectively view this speech?","options":["Piaget: socially directed speech; Vygotsky: speech that will soon disappear without use","Both would see it as egocentric speech with no function in solving the problem","Piaget: inner speech said aloud; Vygotsky: social speech meant for others","Piaget: egocentric speech of immature thought; Vygotsky: private speech to plan and solve"],"answer":3,"explanation":"Piaget saw such speech as a sign of egocentrism that fades away. Vygotsky showed it increases when an obstacle appears, because the child uses it to guide problem solving, and that it later becomes inner speech.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-465","question":"How many of these statements reflect Vygotsky’s view of thought and language? I. Before about two years, thought and speech develop along separate lines. II. Later the two lines meet, so that thought becomes verbal and speech becomes rational. III. Language is merely a label for concepts the child has already formed. IV. Speech first serves to communicate with others and later to direct one’s own thinking.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are Vygotsky’s views. Statement III, that language only reflects concepts already formed, is closer to Piaget’s position.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-466","question":"Vygotsky compared a teacher who judges a child only by what she can do alone to a gardener who judges an orchard only by its ripe fruit. His point was that such assessment ignores:","options":["Functions still maturing, which show in what the child can do with help","The child’s physical health and nutrition, which also affect her growth","The child’s scores compared with the class average on the same task","Errors, which reveal the child’s egocentrism and immature logic"],"answer":0,"explanation":"Independent performance shows only matured functions (the fruit); the buds and flowers are the maturing functions visible in assisted performance. This is the case for assessing the ZPD.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-467","question":"Which teacher in a Class 2 lesson on subtraction is using a mediating tool in Vygotsky’s sense?","options":["One who gives a sweet each time a child answers a subtraction correctly","One who waits for children to reach the right stage before teaching subtraction","One who lets children use a bead string and a number line to count back","One who has the class chant subtraction tables aloud every day"],"answer":2,"explanation":"For Vygotsky, tools and signs such as a number line mediate thinking and are later internalised. Rewards and chanting are behaviourist techniques, and waiting for readiness is closer to Piaget.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-468","question":"Consider these statements about ‘scaffolding’. 1. The term was introduced by Wood, Bruner and Ross (1976) to describe how a tutor helps a child, and it is closely linked with Vygotsky’s ZPD. 2. Vygotsky himself used the word ‘scaffolding’ throughout his writings on the ZPD. Which is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Wood, Bruner and Ross coined the metaphor in their 1976 study of tutoring; it is used to describe help within Vygotsky’s ZPD, but the word itself does not come from Vygotsky.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-469","question":"In a pottery family in Khurja, a girl first fetches clay, then shapes small pots while her mother finishes the rims, and finally makes whole pots herself as the adults step back. This learning is best described by:","options":["Operant conditioning with a fixed schedule of reinforcement by adults","Guided participation in a cultural activity, a sociocultural idea","Piaget’s spontaneous discovery without adult involvement","Bruner’s symbolic mode of representation in craft"],"answer":1,"explanation":"She learns by taking increasing responsibility in a real activity alongside skilled adults, which is guided participation or apprenticeship in the sociocultural tradition. Adults are central here, so it is not solitary discovery.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-470","question":"Which statement about Vygotsky’s theory is correct?","options":["It proposes four fixed, universal stages of cognitive development","It holds that development must be complete before learning can occur","It treats the child as a lone scientist who constructs knowledge without help","It predicts that children in different cultures may develop different skills"],"answer":3,"explanation":"Because development depends on cultural tools and social interaction, Vygotsky’s theory expects cultural differences in thinking. The other options describe Piaget or misstate both theories.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-471","question":"For a group activity on reading a map, which grouping would Vygotsky most likely recommend?","options":["Mixed groups where each child works with someone a little more skilled","Groups of children with identical ability, so that no one dominates the task","Each child working alone, so that the teacher can see individual effort","The best readers grouped together so that they are not held back by others"],"answer":0,"explanation":"Working with a slightly more capable peer lets a child perform within her ZPD with help. Equal-ability or solo grouping removes the more knowledgeable other.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-472","question":"A Class 3 teacher shows children how to measure the classroom with a metre scale, then asks them to measure the corridor in pairs while she asks guiding questions, and finally asks each child to measure her own desk. Which statement best explains her approach?","options":["She is following Piaget, because she lets each child discover length alone from the start","She is using Skinner’s programmed learning with immediate reinforcement","She is using Bruner’s iconic mode only","She is moving the children from assisted to independent performance, as Vygotsky advised"],"answer":3,"explanation":"Modelling, then guided pair work, then independent work is the gradual transfer of responsibility at the heart of Vygotskian teaching. Nothing here involves reinforcement schedules or solitary discovery.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-473","question":"A Class 7 student solves a long-division problem while muttering, ‘Bring down the 4... how many 7s in 34? four...’. The teacher asks the class to stay completely silent during practice, and her errors increase. From Vygotsky’s viewpoint, the most likely reason is that:","options":["Silence is always harmful to every kind of learning","She is still at the pre-operational stage of thought","Her private speech was regulating a multi-step task","The teacher should have given her a reward for speaking"],"answer":2,"explanation":"Older children and even adults return to audible private speech on demanding tasks; it organises their steps. Banning it can remove a useful self-regulation tool, which says nothing about her Piagetian stage.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-474","question":"Assertion (A): Vygotsky would see a teacher’s explanation as unhelpful if a child cannot use it even with prompting. Reason (R): Instruction that falls beyond the upper limit of a child’s zone of proximal development cannot be taken up by the child.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The ZPD has an upper boundary: tasks beyond what the child can do even with help are not yet learnable. So explanation pitched there does not help, which is why R explains A.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-475","question":"Which classroom statement about language best reflects Vygotsky’s view?","options":["‘Children must master concepts first; the words can be taught after that.’","‘Talking about a problem with others helps children reorganise their thinking.’","‘Children should stay silent so that language does not interfere with thought.’","‘Language develops only from imitation and from reinforcement by adults.’"],"answer":1,"explanation":"For Vygotsky, language is the chief tool of thought, and dialogue reshapes how children think. The first option is closer to Piaget and the last to Skinner.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-476","question":"Discussing the Heinz dilemma in a Class 8 value-education period, four students argue that Heinz should steal the drug. Whose reasoning reflects Kohlberg’s Stage 3?","options":["Seema: ‘His wife will cook for him and look after him once she is well again, so it pays.’","Rohan: ‘A loving husband would do it; people would think him heartless if he let her die.’","Aditi: ‘The right to life comes before property, and any fair society should recognise that.’","Kunal: ‘If he lets her die he could land in trouble; the police might even question him.’"],"answer":1,"explanation":"Stage 3 reasoning centres on being a ‘good’ person in others’ eyes and on loving relationships. Seema’s is an exchange of favours (Stage 2), Kunal’s is avoiding punishment (Stage 1), Aditi’s appeals to rights (Stage 5).","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-477","question":"A Class 10 student argues in the school council: ‘The rule that only boys can join the cricket team was made by agreement; rules exist to serve all students fairly, so we should vote to change it.’ In Kohlberg’s scheme this reasoning belongs to:","options":["Stage 4: law and order and social system","Stage 3: good boy–good girl orientation","Stage 5: social contract and rights","Stage 6: universal ethical principles"],"answer":2,"explanation":"Seeing rules as social agreements that should be revised democratically when they fail to serve people’s rights is Stage 5. Stage 4 would treat the existing rule as binding simply to maintain order.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-478","question":"A teacher grades her students’ moral development by counting how many said Heinz should NOT steal the drug: the more who said ‘no’, the higher she rates the class. What is the basic flaw, from Kohlberg’s standpoint?","options":["Kohlberg’s stages are judged by the reasoning given, not by the decision","Saying ‘steal’ is always the higher-stage answer to the Heinz dilemma","Moral development can only be measured by observing actual behaviour","The Heinz dilemma is meant for adults, not for adolescents in school"],"answer":0,"explanation":"The same decision can come from Stage 1 fear or Stage 4 respect for law; Kohlberg scored the justification. No answer, steal or not steal, is in itself higher.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-479","question":"Following Kohlberg and the work of Blatt, a teacher wants to move a class that reasons mostly at Stage 2 to higher reasoning. Which strategy is most likely to work?","options":["Lecture them on Stage 6 universal principles of justice every day in assembly","Punish selfish behaviour strictly so that they learn the rules of the class","Reward obedient students with stars so that others copy their behaviour","Hold dilemma discussions where they meet reasoning one stage above their own"],"answer":3,"explanation":"Exposure to reasoning slightly above one’s own (‘plus one’) creates productive conflict and is understood; reasoning far above (Stage 6) is not grasped, and punishments or rewards only reinforce Stage 1–2 thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-480","question":"Assertion (A): A student whose moral reasoning is at Stage 2 cannot move directly to Stage 4 without passing through Stage 3. Reason (R): Kohlberg held that his stages form an invariant sequence.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Kohlberg’s stages are hierarchical and invariant: each must be passed through in order, and none is skipped, so R explains A.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-481","question":"In a dilemma discussion, Neha argues cogently that cheating is wrong because exams must be fair to everyone and rules keep the system running. A week later she copies during an unsupervised test. Which criticism of Kohlberg’s theory does this illustrate?","options":["The theory ignores the role of culture in moral thinking","Moral reasoning does not always predict moral behaviour","The stages do not follow an invariant sequence","The theory is based on a sample of girls only"],"answer":1,"explanation":"Kohlberg studied moral reasoning; critics note the gap between what people reason and what they actually do. The original sample was of boys, not girls.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-482","question":"Match the student statements with Kohlberg’s stages: P. ‘I returned the extra change so the shopkeeper would give me a discount next time.’ Q. ‘I returned it because a good student doesn’t keep what isn’t his; my parents would be ashamed.’ R. ‘I returned it because if people kept extra change, trust in trade would collapse.’ S. ‘I returned it because every person deserves to be treated honestly, whatever the law says.’","options":["P-2, Q-3, R-4, S-6","P-1, Q-3, R-5, S-6","P-2, Q-4, R-3, S-5","P-1, Q-2, R-4, S-5"],"answer":0,"explanation":"P is instrumental exchange (Stage 2), Q seeks approval as a ‘good’ person (Stage 3), R maintains the social system (Stage 4), S appeals to a self-chosen universal principle (Stage 6).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-483","question":"A six-year-old says breaking his father’s phone was wrong ‘because Papa will beat me’. When asked if it would still be wrong if Papa never found out, he says, ‘Then it’s okay.’ This reasoning is typical of:","options":["Stage 2: instrumental exchange","Stage 3: interpersonal conformity","Stage 4: law and order","Stage 1: obedience and punishment"],"answer":3,"explanation":"At Stage 1 an act is wrong because it is punished; if no punishment follows, it is not seen as wrong. Stage 2 would weigh what the child gains in an exchange.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-484","question":"A Class 9 girl learns that her close friend took money from the class fund. She decides to tell the teacher: ‘The class fund works only if its rules apply to everyone; if friends cover for each other, the whole system fails.’ Her reasoning reflects:","options":["Stage 3, because she is concerned about her friend's character","Stage 5, because she is thinking of the welfare of all","Stage 4, because she upholds rules to maintain the system","Stage 2, because she gains nothing by staying silent"],"answer":2,"explanation":"Upholding rules because the system depends on them is Stage 4 (law and order). Stage 5 would treat rules as revisable agreements serving rights, which she does not mention.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-485","question":"Which feature is common to Kohlberg’s Stages 3 and 4 and distinguishes them from Stages 1–2?","options":["Morality is judged by physical consequences such as punishment or reward","Moral standards are those of family, group or society, taken on and lived up to","Moral principles are self-chosen and may override the law of the land","Right action is whatever satisfies one’s own needs in a fair exchange"],"answer":1,"explanation":"At the conventional level (Stages 3–4) people conform to and uphold the expectations of family, group or society. Physical consequences and self-interest mark the preconventional level; self-chosen principles mark the postconventional.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-486","question":"A school wants to promote moral development along the lines Kohlberg recommended. Which practice fits best?","options":["Daily moral lectures and value slogans painted on the walls of every classroom","Strict punishment for every rule broken, so that students learn self-control","Discussing real dilemmas in which students justify views and hear others’ reasons","Prizes for the most obedient student of the month, announced at assembly"],"answer":2,"explanation":"Kohlberg saw moral growth as arising from cognitive conflict and perspective-taking, fostered by dilemma discussion and democratic ‘just community’ practices, not by preaching or reward and punishment.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-487","question":"Which of these statements about Kohlberg’s theory is INCORRECT?","options":["His original study interviewed boys using hypothetical dilemmas","He built on Piaget’s idea that moral reasoning depends on cognitive development","Most adults, he found, reason at the conventional level","A person’s stage is identified from the action he or she chooses in the dilemma"],"answer":3,"explanation":"Stage is identified from the reasoning, not the chosen action. The other three are accurate: a male sample, a Piagetian base, and most adults at Stages 3–4.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-488","question":"A Class 11 student says, ‘If a law forces children to work in factories, it is unjust, and I would break it openly and accept the punishment, because the dignity of every human being matters more than any law.’ According to Kohlberg this is:","options":["Stage 6: universal ethical principles","Stage 4: law and social order","Stage 5: social contract and rights","Stage 3: good boy–good girl orientation"],"answer":0,"explanation":"Acting on a self-chosen universal principle of human dignity, even against the law, while accepting the penalty, is the hallmark of Stage 6. Stage 5 would work to change the law through agreed democratic means.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-489","question":"‘You helped me with my homework, so I’ll let you copy my drawing.’ ‘It’s fair if we both get the same.’ Such reasoning, common among primary children, belongs to:","options":["Kohlberg’s Stage 1, as the child simply obeys authority to avoid punishment","Kohlberg’s Stage 3, as the child wants to be seen as a good friend","Kohlberg’s Stage 2, as fairness is an equal exchange serving each one’s interest","Kohlberg’s Stage 5, as the child respects a social contract between friends"],"answer":2,"explanation":"Stage 2 treats fairness as a tit-for-tat deal serving each person’s own interests. A ‘contract’ here is not the Stage 5 social contract, which concerns rights and the welfare of society.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-490","question":"Assertion (A): Kohlberg’s highest stages are seldom found in the reasoning of children in primary classes. Reason (R): Postconventional reasoning requires the ability to think abstractly about principles and hypothetical societies.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Kohlberg linked moral stages to cognitive development; principled reasoning needs abstract (formal operational) thought, which primary children generally lack.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-491","question":"Two Class 7 students refuse to join a bunk. Ishaan: ‘My class teacher believes in me; I can’t let her down.’ Farhan: ‘School rules apply to all of us; if everyone bunked, the school couldn’t function.’ Their stages are respectively:","options":["Stage 2 and Stage 3","Stage 3 and Stage 4","Stage 3 and Stage 5","Stage 4 and Stage 3"],"answer":1,"explanation":"Ishaan seeks to live up to a trusted person’s expectations (Stage 3); Farhan upholds rules to keep the system working (Stage 4). Neither mentions rights or revisable agreements, so not Stage 5.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-492","question":"Which of these statements are correct according to Kohlberg? I. Each stage is a more adequate way of reasoning than the one before. II. A person usually reasons mostly at one stage, with some reasoning at adjacent stages. III. Moral education should directly teach the answers of Stage 6. IV. Reasoning develops through cognitive conflict and social interaction.","options":["I and III only","II and III only","I, II and IV only","I, III and IV only"],"answer":2,"explanation":"Higher stages are more adequate (I), reasoning clusters around one stage (II), and growth comes from conflict and interaction (IV). Stage 6 answers cannot be directly taught (III false); students cannot grasp reasoning far above their own.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-493","question":"A Class 4 boy says he did not take another child’s eraser ‘because Sir is standing right there and I would get punished’. His teacher wants to nudge him upward in Kohlberg’s sequence. Which kind of reasoning should she present next in class discussion?","options":["Rules of society must be kept so that order is maintained","Respecting everyone’s rights is a universal principle","Taking without asking is wrong because the Constitution protects property","If you treat others fairly, they will treat you fairly too"],"answer":3,"explanation":"He is at Stage 1; the next stage is Stage 2 reciprocity (‘fair exchange’). Stage 4 or Stage 5–6 arguments are too far ahead for him to assimilate.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-494","question":"Which of these is the most accurate statement about how Kohlberg collected his data?","options":["He observed children’s actual behaviour in real temptation situations","He presented hypothetical moral dilemmas and analysed the reasons participants gave","He gave children multiple-choice tests of moral knowledge","He used stories comparing accidental and intentional damage to find the age of moral realism"],"answer":1,"explanation":"Kohlberg used the clinical interview with dilemmas such as Heinz and probed reasons. Stories of accidental versus intentional damage were Piaget’s method.","difficulty":"moderate","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-495","question":"A Class 12 student argues: ‘Speed limits are agreed by society to protect everyone’s life. A driver rushing a dying patient to hospital may break one, because the law’s own purpose is protecting life; but the rule itself should stand and be applied fairly.’ This shows:","options":["Stage 4, because he insists that the rule itself should stand and be applied fairly","Stage 3, because he is concerned for the patient and the driver","Stage 2, because the driver gains personally from breaking the rule","Stage 5, as he sees law as a social agreement serving people’s rights and welfare"],"answer":3,"explanation":"Judging the law by its purpose (protecting life and welfare) and seeing it as a social agreement is Stage 5. Wanting the rule to remain does not make it Stage 4, which treats rules as binding for order’s sake.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-496","question":"A teacher notices that most of her Class 9 students explain good behaviour with ‘What will people say?’ or ‘Our class has a good name to keep.’ What does Kohlberg’s theory suggest about this?","options":["They are morally backward and need counselling to correct their thinking","Conventional reasoning is normal for adolescents; dilemma discussions can help them grow","They have reached the highest stage possible for their age and nothing more can be done","They are at the postconventional level since they think about society’s view"],"answer":1,"explanation":"Adolescents and most adults reason at the conventional level (approval of others, social order); this is normal, and challenging discussions can nudge growth. Concern for the group’s name is not postconventional.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-497","question":"Which response to ‘Should Heinz steal the drug?’ is the clearest example of Stage 1 reasoning, whatever answer it gives?","options":["‘No, because the druggist worked hard and deserves to profit from his invention.’","‘Yes, because a husband has a duty to his wife that society expects him to fulfil.’","‘No, because he will be caught and sent to jail.’","‘Yes, because she will repay him by taking care of him later.’"],"answer":2,"explanation":"Stage 1 judges by punishment. Repayment is Stage 2 exchange, society’s expectation of a husband is conventional, and the druggist’s deserved profit reflects rights-based concerns rather than fear.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-498","question":"Assertion (A): Kohlberg advocated running schools as ‘just communities’ where students and teachers make rules democratically. Reason (R): Kohlberg believed that moral development is primarily the result of rewards and punishments given by adults.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Kohlberg did promote just-community schools, but he saw moral growth as cognitive restructuring through participation and discussion, not as conditioning by rewards and punishments; R is false.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-499","question":"After a quarrel during a cricket match, the umpire in a Class 6 game gives a decision against his own team. Asked why, he says, ‘That’s the rule everyone signed up to; if umpires favour their friends, the game becomes meaningless.’ Which stage best fits?","options":["Stage 4","Stage 3","Stage 2","Stage 1"],"answer":0,"explanation":"Upholding the shared rule so that the system (the game) keeps working is Stage 4 law-and-order thinking. He sets aside friendship (Stage 3) and personal gain (Stage 2).","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-500","question":"Which of these best describes the difference between Kohlberg’s preconventional and postconventional levels, though both may sometimes reach the same decision to disobey a rule?","options":["Preconventional disobedience rests on self-interest or fear; postconventional, on justice or rights","Preconventional children never disobey rules, while postconventional adults always do","Both levels judge actions by social approval and the wish to be seen as good","Preconventional reasoning is based on abstract principles, while postconventional is based on fear"],"answer":0,"explanation":"A preconventional child may break a rule for personal gain; a postconventional thinker may break it out of principle. Same act, different reasoning, which is exactly what Kohlberg measured.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-501","question":"Nikhil, in Class 7, has been assessed as having dyslexia. He understands science concepts well when they are discussed orally. Which arrangement for his term test is most appropriate?","options":["Extra time and a reader, with the paper testing the same competencies as the rest of the class","An easier paper with only one-word answers, since writing long answers is the main thing he finds hard","Exemption from the term test, with promotion decided on the basis of attendance and class conduct","A paper made entirely of multiple-choice questions, to be completed within the same time limit as others"],"answer":0,"explanation":"An accommodation removes the barrier (decoding print, speed) without lowering what is assessed; an easier paper changes the standard, exemption denies assessment, and MCQs still demand fast reading.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-502","question":"Which of the following is a MODIFICATION of the curriculum rather than an accommodation?","options":["A child with intellectual disability works on two-digit addition with objects while the class learns long division","A child with low vision receives exactly the same question paper as the rest of the class, printed in a larger font size","A child with dysgraphia types his answers on a computer instead of writing them by hand on paper","A child with hearing impairment is seated in the front row near the teacher so that she can lip-read"],"answer":0,"explanation":"Accommodations change how a child learns or shows learning; a modification changes what is expected, as when a different, simpler learning goal replaces the class goal.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-503","question":"For a Class 2 child with dyslexia who cannot yet link letters with their sounds, which approach is best supported?","options":["Asking him to read harder books silently every day, so that greater exposure to print slowly builds his reading on its own","Making him memorise long lists of whole words by sight, so that he can skip the slow work of decoding sounds","Using coloured overlays on every page as the main remedy, since dyslexia is chiefly a visual problem with print","Explicit, systematic phonics taught multisensorily, such as seeing a letter, saying its sound and tracing it in sand"],"answer":3,"explanation":"Structured, multisensory phonics directly targets the weak sound–symbol link at the heart of dyslexia; more difficult reading, sight-word cramming or overlays do not teach decoding.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-504","question":"Tanvi, a Class 3 student with good vocabulary and reasoning, often bumps into furniture, struggles with buttons and scissors, cannot catch a ball in PE, and copies slowly from the board with poorly formed letters. Her pattern of difficulties most closely matches:","options":["Dyspraxia (developmental coordination disorder)","Dyslexia (specific learning disability in reading)","Dysphasia (developmental language disorder)","Dyscalculia (specific learning disability in mathematics)"],"answer":0,"explanation":"Difficulty in planning and coordinating movement across gross and fine motor tasks, with intact language and reasoning, indicates dyspraxia; poor handwriting here is one part of a wider motor problem.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-505","question":"Assertion (A): A child can be gifted and also have a specific learning disability at the same time. Reason (R): Both giftedness and learning disability are defined by an IQ score above 130.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"‘Twice-exceptional’ children have high ability along with a learning disability, which often masks both; a learning disability is not defined by high IQ, so R is false.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-506","question":"Which of these statements about educating gifted children are correct? I. Skipping a grade is a form of acceleration. II. Enrichment adds depth and breadth to learning without moving the child to a higher class. III. Giving a gifted child extra sums of the same kind after she finishes is meaningful enrichment.","options":["I only","II and III only","I, II and III","I and II only"],"answer":3,"explanation":"Grade skipping is acceleration and enrichment deepens or widens learning; more of the same work is just ‘more’, not enrichment, and gifted children often see it as a penalty for finishing early.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-507","question":"Raju scores about 65 on an IQ test, but he manages daily routines, money for small purchases, friendships and self-care as well as most children his age. Should he be labelled as having intellectual disability?","options":["No; diagnosis also needs significant limits in adaptive behaviour, so the score alone is not enough","Yes; any IQ score below 70 is enough on its own to confirm intellectual disability, whatever his daily functioning","Yes; once a standardised test score is available, adaptive skills no longer need to be considered","No; intellectual disability can only be formally identified after the child turns 18 years of age"],"answer":0,"explanation":"Intellectual disability requires significant limits in both intellectual functioning and adaptive behaviour, starting in the developmental period; a single score without adaptive deficits does not justify the label.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-508","question":"In staff-room talk, a teacher refers to her students as ‘the blind one’ and ‘that ADHD boy’. Which response reflects sound inclusive practice?","options":["It is acceptable, since the labels are medically accurate and help colleagues identify which child is meant","It is acceptable as long as the children themselves never hear it, since staff-room talk is private","Teachers should use children's names and mention needs only when relevant, as labels can define a child","Teachers should use labels freely, since naming the condition is the first step to providing support"],"answer":2,"explanation":"Person-first thinking sees the child before the condition; labels used as identities shape how adults treat a child and can lower expectations, whereas needs can be described when they matter.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-509","question":"In a village school, some parents ask that their children be seated apart from Dalit classmates during the midday meal. What should the head teacher do?","options":["Quietly agree to the request for now, to avoid conflict in the village and keep all parents sending their children","Let all children choose their own seats, so that the school cannot be blamed for whatever groups form","Serve the meal in two separate shifts, so that both groups of parents are satisfied and no child is forced to mix","Refuse, seat all children together, and explain to parents and the SMC that this discrimination is unconstitutional"],"answer":3,"explanation":"Untouchability is abolished and caste discrimination is prohibited; the school must actively prevent it, and ‘free choice’ or shifts would simply let the segregation continue.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-510","question":"A Class 4 EVS textbook used in a tribal area of Odisha draws its examples from city life, such as escalators and shopping malls. Children seem disengaged. What should the teacher do?","options":["Teach the examples exactly as given, since the textbook is prescribed and the exam will follow it","Connect the same concepts to the children's own lives, such as forest produce and local festivals","Spend extra time explaining city life first, so that the children understand the textbook's examples","Conclude that tribal children learn more slowly, and reduce the content to suit their pace"],"answer":1,"explanation":"Learning builds on what children already know; drawing on their context makes concepts meaningful and values their culture, while a deficit view or rigid textbook-following alienates them.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-511","question":"In group activities, a Class 5 teacher always makes Sonu, who has an intellectual disability, the child who is helped, while others take turns to explain things to him. Which change would best promote inclusion?","options":["Seating Sonu separately with a helper, so that the groups can move faster and he gets individual attention","Rotating roles so that Sonu also helps others in tasks where he is strong, such as handling materials","Excusing Sonu from group work and giving him colouring, so that he is not stressed by difficult tasks","Letting the brightest child in each group do all the tasks, so that the group's work is of good quality"],"answer":1,"explanation":"Inclusion means being a valued member, not a permanent receiver of help; giving every child roles that use their strengths builds belonging and genuine cooperation.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-512","question":"Which of the following is the best-written goal for the Individualised Education Plan of a Class 3 child with a reading difficulty?","options":["Rohan will improve his reading a great deal this year and become a much more confident reader","By term end, Rohan will read aloud a 50-word Class 2 level passage with at most 3 errors in 2 of 3 trials","Rohan will try harder, pay attention in reading lessons and practise reading at home every evening","Rohan will complete the full Class 3 reading syllabus by the end of the year, just like his classmates"],"answer":1,"explanation":"A good IEP goal is specific, measurable and time-bound, so progress can be checked; vague hopes or effort-based goals give nothing to measure.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-513","question":"Over two terms, a Class 2 teacher notices that one child still struggles to match letters with sounds despite good classroom teaching, though he is quick in oral work. What is the most appropriate step?","options":["Wait until Class 5 before acting, since many children outgrow such early reading problems on their own","Record specific observations, give targeted support, discuss with parents and refer him for assessment","Announce to the class that he has dyslexia, so that his classmates are patient and do not tease him","Keep him back in Class 2 for another year, until he has properly learnt to read like the others"],"answer":1,"explanation":"Early identification with documented evidence and timely intervention is the expected approach; waiting loses precious time, public labelling harms, and retention does not address the cause.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-514","question":"A teacher is considering whether a child’s reading problem may be a specific learning disability. Which finding would make this LEAST likely and point first to another cause?","options":["The child's difficulty continues even after a full year of good, targeted teaching in small groups","The child missed most of the last two years of school because the family kept migrating for work","The child reasons well and speaks fluently in class but is far behind classmates in reading","The child has normal vision and hearing on screening and no history of any serious illness"],"answer":1,"explanation":"A specific learning disability is suspected when a difficulty is unexpected and persists despite adequate teaching; a long gap in schooling is a lack of opportunity to learn, which must be ruled out first.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-515","question":"During group discussions, Neha, who has a hearing impairment, keeps losing track of who is speaking. Which set of practices helps her most?","options":["Asking the group to speak louder and faster, so that the discussion finishes before she gets tired","Giving her a written summary of the discussion after class, so she can read what she missed","Seating the group in a circle, one speaker at a time after a raised hand, and key points on the board","Asking a friend sitting beside her to repeat everything the others say directly into her ear"],"answer":2,"explanation":"She needs to see each speaker's face and know who is talking; a circle, turn-taking signals and written key points give her real access, while noise and speed make it worse.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-516","question":"Which teacher habit most disadvantages a blind student in a mathematics class?","options":["Asking the student to explain her method aloud to the class","Allowing extra time for her Braille work during tests and classwork","Pointing at the board and saying ‘this number plus this one gives that’","Reading out every number and symbol aloud as it is written on the board"],"answer":2,"explanation":"Words like ‘this’, ‘that’ and ‘here’ carry meaning only for those who can see the gesture; for a blind learner the teacher must say exactly what is written.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-517","question":"Which of these statements about Braille are correct? I. Braille is a tactile code, not a separate language, so it can be used to write different languages such as Hindi and English. II. The basic Braille cell has six dot positions arranged in two columns of three. III. Once a blind child learns Braille, developing her listening skills is no longer important.","options":["I and III only","II only","II and III only","I and II only"],"answer":3,"explanation":"Braille is a six-dot code adapted for many scripts, including Bharati Braille for Indian languages; listening remains a key channel of learning for a blind child, so III is false.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-518","question":"Which of the following is a misconception about sign language?","options":["Indian Sign Language has its own grammar, which differs from that of spoken Hindi or English","Sign language is a full language with its own vocabulary, not just a set of gestures","Deaf children benefit from early access to a fully accessible language such as sign language","Sign language is the same all over the world, so any deaf person can understand any other"],"answer":3,"explanation":"Sign languages differ from country to country and have their own grammar, like spoken languages; they are complete languages, and early accessible language supports a deaf child's development.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-519","question":"Ayaan, a Class 4 student with ADHD, often leaves classwork incomplete. His class teacher plans to keep him inside during recess every day to finish it. What is the best judgement?","options":["Unwise; losing activity tends to raise restlessness, so break the work into short chunks with movement breaks","A good plan, because it teaches him that unfinished work has consequences and builds a habit of completing it","A good plan if done only on alternate days, so that he still gets some play while learning to finish work","Unwise; since ADHD is a medical condition, he should simply be excused from completing classwork"],"answer":0,"explanation":"Children with ADHD need movement to regulate attention; taking away recess removes that outlet, whereas short tasks, movement breaks and immediate feedback help completion.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-520","question":"Next week Class 3 is going on a trip to a museum. Kavya, who is on the autism spectrum, finds new places and changes in routine very upsetting. What is the best preparation?","options":["Not telling her about the trip in advance, so that she does not spend the whole week before it worrying","Leaving her at school with another class for the day, so that her routine is not disturbed at all","Telling her firmly on the morning of the trip that she must behave well and stay with the group","Preparing her with photos of the museum, a step-by-step picture story and the trip on her visual schedule"],"answer":3,"explanation":"Predictability reduces anxiety for many autistic children; photos, a step-by-step story and a visual schedule prepare her to take part instead of being surprised or excluded.","difficulty":"moderate","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-521","question":"Assertion (A): Inclusive education also benefits children without disabilities. Reason (R): Learning alongside diverse classmates develops empathy, acceptance of difference and varied ways of solving problems.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Inclusion is not a cost borne by other children; learning with diverse peers builds social understanding and flexible thinking, which is exactly why it benefits everyone.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-522","question":"A school appoints a special educator who takes its children with disabilities to a resource room for every subject; they join their regular classes only for assembly and games. This arrangement is best described as:","options":["Full inclusion, because the children study in the same building and share assembly and games with others","Integration at a physical and social level, not inclusion, as regular-class teaching has not changed for them","Exclusion, because the children are completely denied their right to education by this arrangement","Universal Design for Learning, because specialised support is available to every child who needs it"],"answer":1,"explanation":"Sharing a building and games is placement, not inclusion; inclusion means the children learn in the regular class with adapted teaching, with resource-room help only as a supplement.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-523","question":"Which behaviour is LEAST reliable as a sign of giftedness in a child?","options":["Always having neat handwriting, obeying rules and finishing work on time","Asking probing questions that go well beyond what is taught in the lesson","Becoming bored quickly and restless with repetitive drill and practice work","Showing intense, long-lasting curiosity about a topic of personal interest"],"answer":0,"explanation":"Gifted children are often curious, questioning and impatient with repetition; neatness and compliance describe a ‘good student’, which is not the same as giftedness.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-524","question":"In a Class 7 class discussion, the boys answer most questions while the girls stay silent. Which strategy is most appropriate?","options":["Letting the boys continue answering, since forcing shy girls to speak in front of others may upset them","Asking only the girls questions for the next month, so that they get a fair share of classroom talk","Structured turn-taking such as think-pair-share, equal wait time, and rotating leadership roles among all","Holding separate discussion periods for boys and girls, so that girls can speak without feeling dominated"],"answer":2,"explanation":"Structured participation and equal wait time draw in quieter students without excluding anyone; doing nothing lets the pattern harden, and separating genders avoids rather than addresses it.","difficulty":"moderate","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-525","question":"A 10-year-old girl who has never attended school comes with her parents to seek admission to a government school. Under the RTE Act, 2009, what should the school do?","options":["Admit her in Class 1, since she cannot read yet and must start from the very beginning like others","Refuse admission until she passes an entrance test showing which class she is ready for","Admit her to an age-appropriate class and provide special training so that she can catch up","Ask her to come back at the start of the next academic session, when new admissions are made"],"answer":2,"explanation":"RTE requires an out-of-school child to be admitted to an age-appropriate class with special training to bring her on par; screening tests and denial of mid-year admission are not allowed.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-526","question":"A Class 8 task reads: ‘Plan a week’s menu for your school hostel that stays within a fixed budget and meets the daily need for proteins, carbohydrates and vitamins.’ In the revised Bloom’s taxonomy (Anderson and Krathwohl), this task mainly targets:","options":["Understanding","Applying","Analysing","Creating"],"answer":3,"explanation":"In the revised taxonomy, ‘Create’ includes generating, planning and producing something new and coherent; designing an original menu under constraints is planning, the highest category.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-527","question":"Which of these statements about the revision of Bloom’s taxonomy by Anderson and Krathwohl (2001) are correct? I. Category names were changed from nouns (e.g. knowledge) to verbs (e.g. remembering). II. ‘Synthesis’ became ‘creating’ and was placed above ‘evaluating’. III. A separate knowledge dimension (factual, conceptual, procedural, metacognitive) was added. IV. ‘Application’ was dropped from the hierarchy.","options":["I and II only","I, II and III only","II and IV only","I, III and IV only"],"answer":1,"explanation":"The revision used verbs, put creating at the top above evaluating and added a knowledge dimension; ‘application’ survives as ‘applying’, so IV is false.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-528","question":"A school redesigning its Class 4 report card in line with the holistic progress card of NEP 2020 is considering four changes. Which one goes AGAINST its spirit?","options":["Adding a section in which the child records what she enjoyed and what she found difficult","Including peer and teacher observations on teamwork and creativity","Printing each child’s class rank in every subject so that parents can compare children","Reporting progress in socio-emotional and physical domains along with the cognitive"],"answer":2,"explanation":"The holistic progress card is multidimensional and includes self- and peer-assessment to show each child’s own progress; ranking children against one another runs against that purpose.","difficulty":"hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-529","question":"Which of these are proposals of NEP 2020 on school examinations? I. Board exams should test core capacities rather than months of coaching and memorisation. II. Students may be allowed to take board exams on up to two occasions in a school year. III. School examinations in Grades 3, 5 and 8, conducted by the appropriate authority, to track progress. IV. Board examinations at Grades 10 and 12 to be abolished.","options":["I and IV only","II and IV only","I, II and IV only","I, II and III only"],"answer":3,"explanation":"NEP 2020 keeps Grade 10 and 12 board exams but reforms them, allows up to two attempts a year, and proposes Grade 3, 5 and 8 examinations; it does not abolish board exams.","difficulty":"very-hard","source":"CTET · DSSSB TGT"},
  {"id":"cdp-child-development-530","question":"A Class 2 teacher wants her children to assess their own reading. Which method is most developmentally appropriate?","options":["A written self-evaluation essay on how their reading has progressed over the term","Asking each child to give herself marks out of 100 for her reading at the end of each week","Smiley or traffic-light cards against two or three simple ‘I can’ statements, discussed with the teacher","A wall chart on which children rank themselves against their classmates after each reading session"],"answer":2,"explanation":"Young children can self-assess when the criteria are few, concrete and visual and the result is talked over; essays, percentages and peer ranking are beyond their level or harmful to motivation.","difficulty":"moderate","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-531","question":"Section 29 of the RTE Act, 2009 lists what the academic authority must take into account while laying down curriculum and evaluation procedure. Which of these is NOT among them?","options":["Learning through activities, discovery and exploration in a child-friendly and child-centred manner","Medium of instruction, as far as practicable, in the child’s mother tongue","Making the child free of fear, trauma and anxiety","Deciding promotion through a single written examination at the end of each year"],"answer":3,"explanation":"Section 29 calls for child-centred learning, mother-tongue instruction as far as practicable, freedom from fear and anxiety, and comprehensive and continuous evaluation, not a single year-end examination.","difficulty":"hard","source":"CTET · UPTET · REET"},
  {"id":"cdp-child-development-532","question":"Assertion (A): A test with high reliability may still be unfair to some groups of students. Reason (R): Reliability concerns the consistency of scores, not whether the test measures the intended ability equally well for all learners.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"A test can consistently measure the wrong thing for some groups (for example, through unfamiliar language or contexts); consistency says nothing about fairness or validity, which is exactly why A holds.","difficulty":"very-hard","source":"CTET Paper II · KVS PGT"},
  {"id":"cdp-child-development-533","question":"Before setting a Class 9 science test, a teacher prepares a two-way table showing how many marks will go to each chapter and to each objective (knowledge, understanding, application). This blueprint mainly protects the test’s:","options":["Predictive validity","Content validity","Inter-rater reliability","Face validity"],"answer":1,"explanation":"A blueprint makes the test sample the taught content and objectives in the intended proportion, which is what content validity means.","difficulty":"hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-534","question":"Two teachers mark the same Class 6 answer sheets. On the objective section their scores are identical, but on the essay section their marks differ widely. Which step most directly improves the essay section?","options":["Replacing the essay with more multiple-choice items on facts, which can be marked objectively","Allowing the students more time to write the essays, so that their answers are more complete","A shared rubric with clear criteria and model answers, and joint moderation of a sample","Averaging the two teachers' marks for each sheet, so that individual differences cancel out"],"answer":2,"explanation":"Shared criteria and moderation raise inter-rater reliability while keeping the essay’s purpose; replacing essays with fact items would gain consistency but lose validity for writing skills.","difficulty":"hard","source":"CTET Paper II · State TET"},
  {"id":"cdp-child-development-535","question":"In a Class 10 test, 40 students attempt an item and 30 answer it correctly. Of the 10 highest scorers on the whole test, 9 answer it correctly; of the 10 lowest scorers, 8 do. Which conclusion about the item is most accurate?","options":["It is a very difficult item that discriminates highly between high and low achievers","It is of moderate difficulty and discriminates well between high and low achievers","It is a very easy item that shows negative discrimination between the two groups","It is fairly easy and discriminates poorly between high and low achievers"],"answer":3,"explanation":"Difficulty index = 30/40 = 0.75 (fairly easy); discrimination = (9 − 8)/10 = 0.1, positive but very low, so the item hardly separates strong from weak students.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-536","question":"Which feedback practice best fits the principle that feedback should help ‘close the gap’ between present and desired performance?","options":["Returning the draft with one specific improvement point and class time to revise before final submission","Returning fully corrected final copies at the end of term, each with a grade and a short comment","Displaying the marks of all students on the notice board so that each can see where they stand","Writing ‘See me’ on the work of weak students so that they come for a private discussion later"],"answer":0,"explanation":"Feedback closes the gap only if it is specific and the learner gets a chance to act on it; feedback given after the work is finished, or only as marks, cannot be used.","difficulty":"moderate","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-537","question":"In a Class 7 section of 55 students with one teacher, which strategy gives the teacher the most information about everyone’s understanding in the least time?","options":["Calling on the two students who raise their hands first and judging from their answers","Asking ‘Have you all understood?’ and watching the class closely for nods and smiles","Exit slips with one diagnostic question, sorted after class into ‘got it / partly / not yet’","A detailed written test at the end of every week, covering all the topics that were taught that week"],"answer":2,"explanation":"Exit slips collect evidence from every student quickly and can be sorted to plan the next lesson; volunteers and nods give biased or unreliable evidence, and weekly tests come too late.","difficulty":"hard","source":"CTET Paper II · NVS TGT"},
  {"id":"cdp-child-development-538","question":"A teacher introduces open-book tests in Class 9 social science. For the change to be meaningful, the questions should be:","options":["Direct questions whose answers can be found and copied from a single page of the book","Questions requiring analysis, comparison and application of the text's ideas to new situations","Questions about page numbers, headings and figure titles, to check skill in using the book","Fill-in-the-blanks taken from the chapter-end summary, so that students revise key terms"],"answer":1,"explanation":"An open-book test removes the need to memorise, so it is worthwhile only if questions demand higher-order thinking; copy-able questions would test nothing.","difficulty":"moderate","source":"CTET Paper II · State TET"},
  {"id":"cdp-child-development-539","question":"Which of these statements about rubrics are correct? I. A rubric shared before the task can guide students’ work, not just the teacher’s marking. II. Rubric levels should describe the quality of performance rather than merely count features. III. A rubric guarantees a valid assessment even if its criteria ignore the learning goal.","options":["I and II only","I only","II and III only","I, II and III"],"answer":0,"explanation":"Shared rubrics clarify success criteria for learners and good level descriptors describe quality; but a rubric is only as valid as its criteria, so III is false.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-540","question":"A teacher asks Class 8 students to draw a concept map linking ‘sun, producer, consumer, decomposer, energy’. Such a map is especially useful for assessing:","options":["How quickly and accurately students can recall the textbook definitions of each of the five terms","Students' handwriting, neatness and their ability to draw clear diagrams","Their memory of the order in which the topics appear in the textbook chapter","How students understand the relationships among concepts, including misconceptions in their links"],"answer":3,"explanation":"A concept map makes visible the links a learner draws between ideas, so faulty links (misconceptions) show up in a way a definition test cannot reveal.","difficulty":"moderate","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-541","question":"For a four-year-old in a Balvatika or anganwadi, which form of assessment fits the approach of NEP 2020 and the foundational-stage framework?","options":["Short written tests every month to check which letters and numbers the child has learnt","Observation of the child in play and daily activities, along with samples of her work","An oral examination with marks before promotion to Grade 1, to confirm school readiness","A standardised entrance test for school admission, to place the child in the right section"],"answer":1,"explanation":"At the foundational stage, assessment is through observation and children’s artefacts during play and activity; formal tests and marks are developmentally inappropriate.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-542","question":"A private unaided school holds a short interview of the child and parents before admission to Class 1 so as to choose ‘suitable’ children. Under the RTE Act, 2009, this is:","options":["Allowed, provided the interview is held in the child's mother tongue and the parents are put at ease","Allowed, but only for seats outside the 25% quota reserved for children from disadvantaged groups","Prohibited, as Section 13 bars any screening procedure for admission and penalises it with a fine","Prohibited only in government and aided schools, since unaided schools may set their own admission rules"],"answer":2,"explanation":"Section 13 forbids capitation fees and any screening procedure (any selection other than a random method) for admission in all schools covered by the Act, with fines for contravention.","difficulty":"hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-543","question":"A teacher tells Neha, ‘Last month you read 20 words a minute; today you read 35.’ The teacher is judging Neha’s performance with reference to:","options":["Her own earlier performance (ipsative or self-referenced assessment)","Her classmates’ performance (norm-referenced assessment)","A fixed standard of reading fluency (criterion-referenced assessment)","A final certification of her level (summative assessment)"],"answer":0,"explanation":"Comparing a learner with her own earlier performance is ipsative assessment; it highlights personal growth, which supports motivation, especially for struggling readers.","difficulty":"hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-544","question":"Which tool would give the most valid evidence of a Class 5 child’s cooperation with others?","options":["A written test with the question ‘Why is cooperation important?’ marked against a model answer","Systematic observation during group work over several weeks, recorded in a checklist or anecdotal notes","A true/false quiz on good manners and helping behaviour, given at the end of the term","The child's marks in moral science, since that subject directly covers values such as sharing and cooperation"],"answer":1,"explanation":"Cooperation is a behaviour, so the valid evidence is observed behaviour in real situations over time; written answers show only what the child knows to say.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-545","question":"Assertion (A): Continuous evaluation means testing children every week. Reason (R): Continuous evaluation aims at regular monitoring of learning and timely feedback during the teaching–learning process.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Continuity means assessment is woven into everyday teaching (observation, questioning, feedback), not frequent formal tests; equating it with weekly testing was the very distortion critics of CCE pointed out.","difficulty":"very-hard","source":"CTET · State TET"},
  {"id":"cdp-child-development-546","question":"After a unit test, a Class 3 teacher finds that 70% of the class got the same item on subtraction with regrouping wrong. The most appropriate inference is:","options":["Most of the class is weak in mathematics and needs extra tuition after school hours","The item was too difficult for Class 3 and should be dropped from future tests","The concept may not have been taught effectively, so she should reteach it differently","The children did not revise the topic at home, so parents should be asked to supervise practice"],"answer":2,"explanation":"When most of a class makes the same error, the evidence points to the teaching rather than to the children; assessment data should first feed back into the teacher’s own practice.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-547","question":"In a Class 8 science practical examination, students are marked largely on the neatness of their diagrams and the length of their records. The main problem is that:","options":["Construct-irrelevant factors are influencing the scores, reducing validity","The examination has too high an inter-rater reliability for a practical test","The examination is criterion-referenced when it should be norm-referenced","The examination is formative in nature when it ought to be summative"],"answer":0,"explanation":"Scores should reflect scientific skills such as handling apparatus, observing and inferring; neatness and length are irrelevant to that construct, so they lower validity.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-548","question":"At a parent–teacher meeting, a Class 6 child presents her portfolio to her parents, explains her goals and progress, and the teacher only facilitates. This student-led conference mainly:","options":["Shifts the responsibility for reporting from the teacher to the parents","Builds the child’s ownership of and reflection on her own learning","Removes the need for any assessment by the teacher","Suits only gifted children who speak confidently"],"answer":1,"explanation":"When children explain their own evidence and goals, they practise reflection and take ownership of learning; the teacher still assesses and guides.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-549","question":"Which is the best example of assessment OF learning being used appropriately?","options":["Grading a Class 6 student's first draft so that she knows her exact mark before she starts revising","Using a pre-test score at the start of the year to label a child ‘slow’ for the rest of the year","Certifying at the end of Class 8 which competencies each child has achieved, for parents and the next school","Giving marks for every homework task throughout the year so that students stay motivated to work"],"answer":2,"explanation":"Assessment of learning summarises achievement at the end of a period for reporting and certification; grading drafts or every homework, or labelling from a pre-test, misuses summative judgement.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-550","question":"A teacher gives the same test to the same class on Monday and again on Tuesday and finds nearly identical scores. Why may this overstate the test’s reliability?","options":["Students may remember their Monday answers, which inflates agreement between the two sets of scores","One day is too long a gap, so genuine learning between the sittings has changed the scores","Test–retest reliability can be calculated only for essay-type tests, not for objective ones","Nearly identical scores on two sittings always indicate that the test has low validity"],"answer":0,"explanation":"With a very short gap, memory of the first sitting (carry-over effect) makes the scores agree more than the test’s true consistency warrants; very long gaps cause the opposite problem through real learning.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-551","question":"Most Class 5 children in a Varanasi school say ‘heavy things sink and light things float’. The teacher floats a large wooden log in a tub and drops in a small iron nail, which sinks. The children look puzzled and begin to argue. In Piaget's terms, what is the teacher trying to bring about?","options":["Assimilation of the event into their existing idea, with no change to it","Disequilibrium that pushes children to accommodate, revising their idea","Conditioning of a new response through repeated pairing with the event","Rote memorisation of the rule of flotation through a vivid demonstration"],"answer":1,"explanation":"A discrepant event creates cognitive conflict (disequilibrium). To restore equilibrium the children must modify their schema, which Piaget called accommodation.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-552","question":"Two-year-old Chiku, who knows only ‘dog’, sees a calf and shouts ‘Big dog!’. His mother says, ‘No, that is a calf; see, it says moo and has hooves.’ After a few days Chiku correctly calls calves ‘calf’. Which part of this episode shows accommodation?","options":["Calling the calf a ‘big dog’ on first seeing it","The mother pointing at the calf and naming it for him","Forming a separate category for calves, distinct from dogs","Chiku continuing to call all the dogs he meets ‘dog’"],"answer":2,"explanation":"Fitting the calf into the existing dog schema was assimilation; creating a new schema for calves because the old one did not fit is accommodation.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-553","question":"Which of these classroom practices is LEAST consistent with a constructivist view of learning?","options":["Asking children to predict what will happen before an experiment is done","Starting a topic by finding out what children already think about it","Letting groups compare and justify their different methods of solution","Dictating notes so that every child memorises the same correct answers"],"answer":3,"explanation":"Constructivism holds that learners build knowledge actively from experience and prior ideas. Dictated notes treat the learner as a passive receiver of ready-made knowledge.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-554","question":"Mohit, in Class 4, can add two-digit numbers on his own. With hints and a place-value chart he can add three-digit numbers with carrying, but even with help he cannot follow long division. Where should the teacher pitch her next lessons according to Vygotsky?","options":["Three-digit addition with carrying, with support she gradually withdraws","Two-digit addition, which he should keep practising until he is perfect at it","Long division, because a tougher challenge always speeds up development","Any topic at all, since maturation alone fixes the order in which he learns"],"answer":0,"explanation":"The Zone of Proximal Development lies between what a child can do alone and what he can do with help. Three-digit addition is in his ZPD; long division is beyond it even with support.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-555","question":"A teacher helping Class 3 children write a letter first gives a full template with sentence starters, then only headings, then just a checklist, and finally nothing. This gradual change mainly reflects which feature of scaffolding?","options":["Rewarding every correct sentence to strengthen it","Fading of support as competence grows","Assimilation of the new letter format into a schema","Moving from abstract rules to concrete examples"],"answer":1,"explanation":"Scaffolding is temporary: support is reduced step by step and handed over to the learner as she becomes able to do the task independently.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-556","question":"In a Class 6 reading period, the teacher and small groups take turns to lead the discussion of a passage. The leader asks the group to predict what comes next, frame questions, clear up confusing words and summarise each part. This approach is:","options":["Programmed instruction, based on Skinner's work","Discovery learning, based on Bruner's ideas","Reciprocal teaching, rooted in Vygotsky's ideas","Rote reading aloud, to build reading fluency"],"answer":2,"explanation":"Reciprocal teaching (Palincsar and Brown) uses four strategies: predicting, questioning, clarifying and summarising. The teacher models them and gradually hands over the leader role, as in Vygotsky's view of guided participation.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-557","question":"While solving a puzzle, Class 1 child Anu mutters, ‘This piece is blue... no, it goes at the top... now the corner.’ How would Vygotsky interpret this talk and what should the teacher do?","options":["It is egocentric speech showing she cannot take others' view; the teacher should stop it","It is a sign of a speech disorder; she should be referred for therapy","It is attention-seeking; the teacher should ignore it so it extinguishes","It is private speech that helps her guide her own thinking; the teacher should allow it"],"answer":3,"explanation":"For Vygotsky, private speech is a tool of self-regulation that later becomes inner speech, and it increases on harder tasks. Calling it merely egocentric is Piaget's view.","difficulty":"very-hard","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-558","question":"Assertion (A): Vygotsky held that good instruction can run ahead of and lead development. Reason (R): Teaching within the Zone of Proximal Development awakens functions that are still in the process of maturing.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Unlike Piaget, who saw development as setting limits on learning, Vygotsky argued that instruction aimed at the ZPD pulls development forward; R is precisely why.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-559","question":"To introduce halves, a Class 2 teacher first has children fold and tear chapatis and paper, then draw pictures of shapes split into two equal parts, and only then write ½. Which theorist's sequence of representation is she following?","options":["Piaget's stages of cognitive development, from sensorimotor to formal","Bruner's enactive, iconic and symbolic modes of representation","Gagné's hierarchy of learning types, from signal learning upwards","Kohlberg's levels of moral reasoning, from pre- to post-conventional"],"answer":1,"explanation":"Bruner proposed three modes of representing knowledge: through action (enactive), images (iconic) and symbols (symbolic). Moving from folding to drawing to writing ½ follows this order.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-560","question":"A school's science syllabus introduces ‘plants need water and light’ in Class 2, revisits it through simple experiments in Class 5, and returns to it as photosynthesis with equations in Class 10. This design reflects:","options":["Thorndike's law of exercise","Gestalt law of closure","Bruner's spiral curriculum","Skinner's linear programming"],"answer":2,"explanation":"In a spiral curriculum the same big ideas are revisited at increasing levels of depth and abstraction as children grow. Simple repetition (law of exercise) does not deepen the idea each time.","difficulty":"moderate","source":"CTET · HTET"},
  {"id":"cdp-child-development-561","question":"A teacher asks: what does research most firmly support about discovery learning for school children?","options":["Pure, unguided discovery is always better than any kind of teacher explanation","Discovery learning is unsuitable for primary school children, who need firm rules first","Telling children every rule first and then giving only practice works best for all","Guided discovery, with well-designed tasks and timely prompts, beats unguided discovery"],"answer":3,"explanation":"Children with little prior knowledge often flounder or form misconceptions in unguided discovery; structured tasks, prompts and feedback make discovery productive. Pure telling misses the benefits of active construction.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-562","question":"Before a lesson on rocks, a Class 7 teacher spends three minutes presenting a short overview: ‘All rocks form in one of three ways: by cooling, by settling in layers, or by being changed by heat and pressure.’ She then teaches each type. This overview is best described as:","options":["An advance organiser in Ausubel's meaningful reception learning","A discriminative stimulus that cues responses in operant conditioning","A spiral curriculum, as described in Bruner's theory of instruction","Shaping by successive approximation towards the full classification"],"answer":0,"explanation":"Ausubel's advance organiser is a brief, general framework given before new material so that new details can be anchored to an organised structure in the learner's mind.","difficulty":"hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-563","question":"‘The most important single factor influencing learning is what the learner already knows; ascertain this and teach accordingly.’ Which classroom step most directly applies this idea of Ausubel?","options":["Giving a surprise test at the end of the chapter to see what was retained","Beginning a chapter by drawing out what the children already know and believe","Making children memorise the key terms before any discussion of them","Grouping children by age for every activity, so that levels are matched"],"answer":1,"explanation":"Ausubel stressed anchoring new learning to existing knowledge. Eliciting prior ideas at the start lets the teacher connect new material to them and spot misconceptions.","difficulty":"moderate","source":"CTET Paper 1 · REET"},
  {"id":"cdp-child-development-564","question":"Two Class 4 children both score 40% on a test taken alone. With the same hints from the teacher, one rises to 80% and the other to 50%. A Vygotskian teacher would conclude that:","options":["Both children are at the same level, since their unaided scores are equal","The second child should simply be given harder work so that he catches up","The first child has a wider zone of proximal development and different needs","Hints spoil the validity of an assessment and so should never be given"],"answer":2,"explanation":"Dynamic assessment measures what a child can do with help as well as alone. Equal independent scores can hide very different ZPDs, which matter for planning instruction.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-565","question":"Which of these statements about the ‘more knowledgeable other’ in Vygotsky's theory are correct? I. It may be a classmate rather than an adult. II. It may be a younger person who knows more about a specific task. III. It must always be the class teacher. IV. Its help is most useful within the learner's zone of proximal development.","options":["I and III only","II and III only","I, III and IV only","I, II and IV only"],"answer":3,"explanation":"The MKO is anyone with greater skill in that particular task: a peer, a younger sibling who knows phones better, or an adult. Help works best when it targets the ZPD.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-566","question":"Assertion (A): Simply telling Class 6 students the correct explanation of day and night often fails to remove their misconception that the Sun goes round the Earth. Reason (R): Learners tend to interpret new information through their existing ideas, so it can be bent to fit the old belief rather than replace it.","options":["Both A and R are true and R is the correct explanation of A","A is true but R is false","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":0,"explanation":"Constructivism predicts that new input is assimilated into prior schemas; without cognitive conflict and active reconstruction, misconceptions persist. R explains A.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-567","question":"A Class 5 teacher forms groups for a mapping project. Which grouping best uses Vygotsky's ideas?","options":["All high achievers grouped together, so that they are not held back by others","Mixed-ability groups in which children explain and support one another","Each child working alone on the map, so that there is no copying at all","Groups chosen by roll number, with no thought given to ability or interest"],"answer":1,"explanation":"Mixed groups let more able children act as more knowledgeable others and let all children work within their ZPD through dialogue. Explaining also deepens the helper's own understanding.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-568","question":"Which statement about the teacher's role in a constructivist classroom is accurate?","options":["The teacher stays silent and leaves children entirely to discover everything","The teacher mainly transmits correct information as clearly and efficiently as possible","The teacher designs problems, probes children's thinking and guides their understanding","The teacher's role ends once the activity sheets have been handed out to groups"],"answer":2,"explanation":"Constructivist teachers are facilitators, not absent: they plan rich tasks, ask questions that reveal thinking, challenge misconceptions and support learners. Pure transmission is the opposite model.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-569","question":"Class 4 children in a Nashik village learn measurement by weighing vegetables at the weekly haat with a shopkeeper, estimating and checking weights, and recording prices. This most closely reflects:","options":["Programmed learning, in which the content is broken into small graded frames","Classical conditioning of number responses through repeated market experiences","Rote learning of the weights and measures tables through daily repetition","Situated learning, with knowledge built through participation in authentic activity"],"answer":3,"explanation":"Situated learning holds that knowledge is closely tied to the activity and context in which it is used; authentic participation makes concepts meaningful and transferable to life.","difficulty":"hard","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-570","question":"Which statement correctly contrasts how Piaget and Vygotsky viewed children's social interaction in learning?","options":["Piaget valued interaction among equals for the conflict it creates; Vygotsky stressed guidance from more capable others","Piaget believed that only adults can really teach children, while Vygotsky thought interaction with peers was useless","Both held that social interaction plays no real role in cognitive development, which is driven by maturation alone","Vygotsky valued only conflict and disagreement between peers, while Piaget stressed guidance from adults"],"answer":0,"explanation":"Piaget saw peer disagreement between equals as a trigger for disequilibrium; Vygotsky emphasised collaboration with a more knowledgeable other within the ZPD.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-571","question":"Students in a tribal area of Jharkhand discuss a science problem in their home language, Santhali, before writing their answers in Hindi. From Vygotsky's perspective, why is this valuable?","options":["It keeps the children quiet and disciplined, since they feel at ease in their own language","Language is a key tool for thinking, so a familiar language lets them reason more deeply","It allows the teacher to skip explaining the concept, since peers will explain it instead","It reduces the need for them to learn a second language such as Hindi or English later"],"answer":1,"explanation":"Vygotsky saw language as the main tool of thought. Talking through ideas in a language children command supports concept building; NCF 2005 also treats multilingualism as a resource.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-572","question":"Which of these ideas is shared by both Piaget and Vygotsky?","options":["Development proceeds through four universal stages in a fixed order","Learning can lead development and pull it forward ahead of maturation","Children are active constructors of knowledge, not passive receivers","Private speech disappears because it is merely egocentric and immature"],"answer":2,"explanation":"Both were constructivists who saw the child as active. Fixed stages and egocentric speech are Piagetian ideas; learning leading development is Vygotsky's.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-573","question":"A Class 8 teacher asks pupils to draw a concept map of ‘nutrition in plants’, linking terms with labelled arrows such as ‘needs’, ‘produces’ and ‘occurs in’. Which purpose does this serve best?","options":["It ensures that pupils memorise the textbook definitions word for word","It replaces the need for any experiments or observation of real plants","It is mainly a way of keeping fast learners busy while others catch up","It shows how pupils organise and relate ideas, revealing gaps and errors"],"answer":3,"explanation":"Concept maps (developed by Novak from Ausubel's ideas) make the learner's knowledge structure visible, so missing or wrong links can be spotted and discussed.","difficulty":"hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-child-development-574","question":"Which classroom practice best reflects the constructivist emphasis of the National Curriculum Framework 2005?","options":["Connecting classroom knowledge with children's life outside school, and letting them explore","Finishing the textbook early, so that more time is left for revision before the examinations","Treating the textbook as the only legitimate source of knowledge for the class to rely on","Giving children well-written model answers to learn thoroughly for their examinations"],"answer":0,"explanation":"NCF 2005 asks that knowledge be linked to life outside school, that learning move away from rote methods, and that children be active constructors of knowledge.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-575","question":"A colleague says, ‘Fractions are far too abstract to start before Class 5.’ Which reply best reflects Jerome Bruner's position?","options":["She is right: abstract ideas must wait until the child reaches the formal operational stage","Fractions can be taught at any age, but only through rote drill of rules and symbols","Any subject can be taught honestly at any stage if matched to the child's mode of representation","Young children should learn mainly through rewards and punishments, not through ideas"],"answer":2,"explanation":"Bruner argued that the basic idea of any subject can be taught honestly to a child of any age, beginning with enactive and iconic forms and moving to symbols, which also underlies the spiral curriculum.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-576","question":"Match each child with the intelligence (Gardner) most clearly shown: 1. Tenzin sorts leaves, insects and seeds from the school garden into groups by their features 2. Fatima mentally rotates a folded paper and predicts where the holes will appear 3. Joseph keeps a diary of his moods and knows which tasks drain him 4. Kiran copies a dance step perfectly after seeing it once; a. Spatial b. Naturalist c. Bodily-kinaesthetic d. Intrapersonal","options":["1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-b, 2-a, 3-d, 4-c","1-d, 2-a, 3-b, 4-c"],"answer":2,"explanation":"Classifying living things is naturalist, mental rotation is spatial, knowing one’s own moods is intrapersonal, and skilled body movement is bodily-kinaesthetic.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-577","question":"Which of the following is the most frequently raised scholarly criticism of Howard Gardner’s theory of multiple intelligences?","options":["It relies too heavily on IQ test scores to identify each of the separate intelligences","It claims that intelligence is entirely inherited and cannot be changed by schooling","It ignores music and bodily skill, treating only academic abilities as intelligence","Some ‘intelligences’ may be talents, and the theory has limited psychometric evidence"],"answer":3,"explanation":"Critics argue that abilities like music or movement are talents, and that the intelligences are not shown to be independent in test data. Gardner, in fact, rejected reliance on IQ tests and did include music and movement.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-578","question":"Assertion (A): Howard Gardner rejects the idea that a single general intelligence can adequately describe human abilities. Reason (R): Gardner holds that each person’s profile of intelligences is fixed at birth and cannot be developed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Gardner proposes several relatively independent intelligences instead of one g, but he stresses that intelligences can be developed through culture and education, so R is false.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-579","question":"When a new type of puzzle appears in a maths olympiad, Nisha quickly works out a way to approach it; she has also practised long division so much that she does it almost without thought, freeing her mind for harder steps. Both abilities belong to which part of Sternberg’s triarchic theory?","options":["The componential subtheory","The experiential subtheory","The contextual subtheory","The two-factor theory"],"answer":1,"explanation":"Sternberg’s experiential subtheory deals with handling novelty and with automatising familiar processes; both are aspects of how experience relates to intelligent behaviour.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-580","question":"Robert Sternberg’s idea of ‘successful intelligence’ is best described as:","options":["The ability to score consistently high on standard IQ tests and school achievement tests","Balancing analytical, creative and practical abilities to reach one's goals in one's context","Having high emotional intelligence together with a high IQ, as measured by standard tests","Excelling in at least one of Gardner's eight intelligences and using it in a chosen career"],"answer":1,"explanation":"Sternberg defines successful intelligence as balancing analytical, creative and practical abilities to adapt to, shape and select environments in line with personal goals, a broader idea than test success.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-581","question":"Bunty can repeat long strings of digits and learn lists of state capitals by heart easily, but finds it hard to see the rule behind a series such as 2, 6, 12, 20, 30. In Arthur Jensen’s terms, he is strong in:","options":["Level II (conceptual) ability but weak in Level I (associative) ability","Fluid intelligence but weak in crystallised intelligence","Level I (associative) ability but weak in Level II (conceptual) ability","Divergent production but weak in convergent production"],"answer":2,"explanation":"Jensen’s Level I covers rote and associative learning such as digit span; Level II covers reasoning and abstract problem-solving, such as finding the rule n(n + 1) in a series.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-582","question":"J. P. Guilford classified intellectual abilities along three dimensions. These are:","options":["Analytical, creative and practical abilities","General, specific and group factors","Abstract, mechanical and social abilities","Operations, contents and products"],"answer":3,"explanation":"Guilford’s structure-of-intellect model crosses operations (the kind of thinking), contents (the kind of information) and products (the form the result takes). The other options are Sternberg, Spearman/group-factor and Thorndike ideas.","difficulty":"hard","source":"CTET · DSSSB TGT"},
  {"id":"cdp-child-development-583","question":"Guilford’s original structure-of-intellect model had 5 operations, 4 contents and 6 products. If the ‘figural’ content is later split into visual and auditory contents, with operations and products unchanged, how many distinct abilities does the model then describe?","options":["120","150","180","144"],"answer":1,"explanation":"Original: 5 × 4 × 6 = 120. Splitting figural gives 5 contents, so 5 × 5 × 6 = 150. The figure 180 arose only when memory was also split, giving 6 operations.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-584","question":"Philip Vernon’s hierarchical model places ‘g’ at the top, with two major group factors below it. These are:","options":["Fluid (gf) and crystallised (gc) intelligence","Verbal–educational (v:ed) and practical–mechanical–spatial (k:m)","Level I (associative) and Level II (conceptual) learning abilities","Convergent and divergent thinking (production) abilities"],"answer":1,"explanation":"Vernon’s hierarchy puts g first, then the major group factors v:ed and k:m, which split into minor group factors and finally specific factors.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-585","question":"E. L. Thorndike rejected one unitary intelligence and distinguished three broad kinds of intelligence. They are:","options":["Abstract, mechanical and social intelligence","Linguistic, logical and spatial intelligence","Analytical, creative and practical intelligence","Verbal, numerical and perceptual intelligence"],"answer":0,"explanation":"Thorndike’s multifactor view separated abstract (ideas and symbols), mechanical (objects and tools) and social (people) intelligence; the analytical–creative–practical triad belongs to Sternberg.","difficulty":"hard","source":"CTET · State TET"},
  {"id":"cdp-child-development-586","question":"Which trait is most consistently associated with creative students in research on creativity?","options":["A strong need for the teacher's approval before trying anything new","A preference for questions that have one clear and correct answer","Tolerance for ambiguity and willingness to take intellectual risks","Avoidance of tasks that come without clear, step-by-step instructions"],"answer":2,"explanation":"Creative people tend to tolerate uncertainty, stay with open problems and risk being wrong; needing approval and preferring single answers point to convergent, conforming habits.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-587","question":"During a brainstorming session on ‘How can our school save water?’, the teacher says ‘That won’t work’ and ‘That’s silly’ to several suggestions as they come. Which principle of brainstorming is she violating most directly?","options":["Aim for quantity of ideas","Defer judgement until all ideas are collected","Build on others’ ideas","Welcome unusual ideas only from the brightest students"],"answer":1,"explanation":"Brainstorming (Osborn) separates idea generation from evaluation; criticising ideas immediately makes students hold back and reduces both the number and the originality of ideas.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-588","question":"In a Class 6 creativity task, 35 of 40 children say a newspaper can be used ‘to wrap things’. Only Devika says, ‘to make a sound-proof lining for the music room door’. On Torrance-type scoring, Devika’s answer earns credit mainly for:","options":["Fluency","Flexibility","Elaboration","Originality"],"answer":3,"explanation":"Originality is scored by how statistically rare a response is in the group; a single unusual answer counts as original, while fluency counts the number of ideas.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-589","question":"Asked to design a bird feeder, Ishaan gives only one idea, but describes it in great detail: the material, the size of the holes, the slope of the roof to drain rain and how to hang it away from cats. On divergent-thinking scoring, he would score highest on:","options":["Elaboration","Fluency","Flexibility","Originality"],"answer":0,"explanation":"Elaboration is the amount of detail used to develop an idea. With a single idea, his fluency and flexibility are low.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-590","question":"Assertion (A): A child who scores very high on an IQ test will always also score very high on creativity tests. Reason (R): Most traditional IQ tests mainly measure convergent thinking.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"IQ and creativity are only moderately related, so a high IQ does not guarantee high creativity. R is true: IQ items usually have one right answer, which is exactly why IQ tests miss much of divergent thinking.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-591","question":"Which question would best promote divergent thinking in a Class 4 EVS lesson on rivers?","options":["Name five rivers that flow through India, and the states they pass through.","Why does the Ganga carry much more water during the monsoon than in summer?","Which river is the longest in India, and where does it begin and end?","If our village river dried up for a year, in how many ways might life here change?"],"answer":3,"explanation":"An open hypothetical question invites many varied answers; the other questions, even the ‘why’ question, lead towards one expected answer.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-592","question":"Parents want their gifted ten-year-old to skip from Class 5 to Class 7. Which concern about such acceleration should the school weigh most carefully along with academic readiness?","options":["Whether his social and emotional maturity will let him fit in with older classmates","Whether skipping a class could actually lower his IQ score over the next few years","Whether acceleration of a child across classes is illegal under the RTE Act, 2009","Whether gifted children ever benefit academically from any form of acceleration"],"answer":0,"explanation":"Research generally finds acceleration helps academically for well-chosen children; the main caution concerns individual social-emotional readiness, which should be judged case by case.","difficulty":"hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-593","question":"Megha, a very able Class 8 girl in Ranchi, deliberately gives wrong answers in class and stops taking part in the science quiz because her friends tease her as a ‘padhaku’. The most appropriate teacher response is to:","options":["Assume she has lost interest in science and remove her from the advanced group","Scold her in front of the class for not trying, so that she takes her studies seriously","Accept it, since it is natural for girls to hide their abilities during adolescence","Talk with her privately, build a culture that values effort, and challenge her discreetly"],"answer":3,"explanation":"Gifted students, especially adolescent girls, may underachieve to fit in with peers. Supportive private guidance, a classroom culture that respects achievement and suitable challenge address the cause instead of punishing or accepting it.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-594","question":"Which behaviour of a gifted child is most often misread by teachers as indiscipline?","options":["Finishing work slowly and very carefully, checking each step twice before handing it in","Asking probing ‘why’ questions and challenging rules that make no sense to them","Preferring to work in a group with friends rather than alone on most tasks","Copying all the board work neatly and colourfully into notebooks"],"answer":1,"explanation":"Gifted children often question authority, ask searching questions and get restless with repetition; teachers may see this as defiance, which can lead to the child’s ability being missed.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-595","question":"Which of the following practices for identifying gifted children are sound? I. Using several sources such as observations, portfolios, teacher and peer nominations and tests. II. Using a single IQ cut-off as the only criterion. III. Looking for talent among children with disabilities and from disadvantaged groups. IV. Allowing children to show ability in their home language.","options":["I, III and IV only","I and II only","II and III only","I, II, III and IV"],"answer":0,"explanation":"Sound identification uses multiple measures and looks across groups and languages; a single IQ cut-off misses creative, practically talented and under-served children.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-596","question":"Speakers of some languages, such as Guugu Yimithirr in Australia, describe locations using compass directions (‘the cup is north of the plate’) instead of ‘left’ and ‘right’, and they keep track of directions remarkably well. Such findings are usually cited as support for:","options":["The strong version of the Sapir–Whorf hypothesis, that language completely determines thought","Chomsky’s claim that all languages are identical in vocabulary","The weak version of the Sapir–Whorf hypothesis, that language can influence habits of thought","Piaget’s view that language has no influence at any stage of thinking"],"answer":2,"explanation":"Such studies show language can shape habitual attention and memory (linguistic relativity) without showing that speakers cannot think in other ways, so they support the weak, not the strong, version.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-597","question":"A girl who was kept isolated with almost no exposure to language until about 13 years of age learned many words after rescue but never fully mastered grammar. Such cases are commonly cited in support of:","options":["The critical (or sensitive) period hypothesis for language acquisition","Skinner's view that language is learned only through reinforcement","The strong Sapir–Whorf hypothesis that language determines thought","Piaget's claim that early speech is egocentric and serves no social use"],"answer":0,"explanation":"Lenneberg’s critical period hypothesis holds that language, especially grammar, is acquired most easily during a biologically sensitive early period; cases like ‘Genie’ are often cited as evidence, though they involve other deprivations too.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-598","question":"Match the theorist with the view of language development: 1. B. F. Skinner 2. Noam Chomsky 3. Lev Vygotsky 4. Jean Piaget; a. Language develops through social interaction and becomes a tool of thought b. Language reflects the child’s level of cognitive development c. Language is verbal behaviour shaped by reinforcement d. Children have an inborn device for acquiring grammar","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-a, 2-d, 3-c, 4-b"],"answer":0,"explanation":"Skinner: reinforcement of verbal behaviour; Chomsky: innate LAD; Vygotsky: social origin of speech and its role in thought; Piaget: language follows and reflects thought.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-599","question":"During a difficult subtraction exercise with borrowing, a Class 2 child in Shimla whispers to himself, ‘First the ones… can’t take 7 from 3… so borrow from the tens.’ The class rule is ‘work silently’. In the light of Vygotsky’s theory, the teacher should:","options":["Stop him, because talking to oneself shows that he is not yet ready for this topic","Allow it, because such private speech helps children regulate their thinking on hard tasks","Move him to an easier worksheet, so that he no longer needs to talk himself through it","Ask him to say it louder, so that the whole class can hear and benefit from his steps"],"answer":1,"explanation":"For Vygotsky, private speech is a self-regulating tool that increases with task difficulty and gradually becomes inner speech; suppressing it removes support the child is using to think.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-600","question":"Which classroom practice best counters gender stereotyping in a primary school?","options":["Letting girls clean the classroom and boys carry the furniture, as each group prefers","Using only male examples in maths word problems, to keep boys motivated in the subject","Rotating all duties, from leading assembly to sweeping, among children of every gender","Seating boys and girls in separate rows, so that they do not distract one another"],"answer":2,"explanation":"Rotating every responsibility across genders breaks the hidden message that certain tasks belong to one gender; the other practices reinforce gendered roles.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-601","question":"To teach the idea of balance, a Class 3 teacher first has children sit on a seesaw and shift their positions, then shows a picture of a beam balance with weights, and finally writes 2 × 6 = 3 × 4 on the board to show why the two sides balance. In terms of Bruner’s modes, this sequence moves from:","options":["Iconic → enactive → symbolic","Symbolic → iconic → enactive","Enactive → iconic → symbolic","Enactive → symbolic → iconic"],"answer":2,"explanation":"Acting on the seesaw is enactive, the picture is iconic and the written statement is symbolic. Bruner advised this order for introducing new ideas to young learners.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-602","question":"How many of these statements about Bruner’s modes of representation are correct? I. Each mode is tied to a fixed age range, as in Piaget’s stages. II. The symbolic mode completely replaces the earlier modes once it develops. III. A single concept can be represented in all three modes. IV. Language plays a central role in the symbolic mode.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"III and IV are correct. I and II are wrong: Bruner’s modes are not tied to fixed ages and they coexist throughout life, so an adult may still learn enactively and the symbolic mode does not replace the others.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-603","question":"Match each example with Bruner’s mode of representation. P. A girl ties her shoelaces quickly but cannot explain the steps in words. Q. A boy recalls the route to school as a mental picture of the lanes. R. A student writes H₂O for water. 1. Iconic 2. Symbolic 3. Enactive","options":["P-1, Q-3, R-2","P-3, Q-2, R-1","P-2, Q-1, R-3","P-3, Q-1, R-2"],"answer":3,"explanation":"Knowledge stored as action is enactive, knowledge as images is iconic, and knowledge as conventional signs such as formulae is symbolic.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-604","question":"A school claims to follow Bruner’s spiral curriculum because Classes 3, 4 and 5 each study the same chapter on plants with identical content and exercises. Why is this NOT a spiral curriculum?","options":["A spiral curriculum must cover each topic only once, in the class best suited to it","Each return to a topic in a spiral curriculum must go deeper, building on earlier learning","A spiral curriculum is meant only for the higher classes, where abstract thought is possible","Bruner said that plants should be taught only through the symbolic mode, not with real specimens"],"answer":1,"explanation":"Mere repetition is not a spiral. Each return to the idea should deepen it and connect with what was learnt before, for example moving from naming parts to how leaves make food.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-605","question":"A Class 6 teacher asks students to cut out the three corners of a paper triangle and place them side by side on a straight line, trying several triangles, and then asks, ‘What do you notice?’ Which feature makes this Bruner’s discovery learning?","options":["The students find the general rule themselves from examples they handle","The teacher states the rule first and the students then verify it on paper","The students are rewarded with marks for every correct answer they give","The rule is memorised before the activity begins, so it can be applied"],"answer":0,"explanation":"In discovery learning learners infer the principle (the angles make a straight angle) from instances, guided by the teacher’s questions. Stating the rule first is expository teaching.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-606","question":"Assertion (A): Bruner believed that a teacher need not simply wait for a child to become ‘ready’ for a subject. Reason (R): For Bruner, readiness can be nurtured by presenting ideas in a form that matches the child’s way of representing the world.","options":["Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"Bruner rejected passive waiting for readiness: by translating ideas into enactive or iconic forms, teachers can help children learn earlier. That is exactly why A holds.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-607","question":"Bruner argued that teaching the basic structure of a subject (its fundamental ideas) rather than isolated facts helps students mainly because it:","options":["Reduces the need for any practice or revision once the main ideas are clear","Makes learning easier to remember and to transfer to new situations","Allows teachers to skip the enactive and iconic modes and go straight to symbols","Ensures that every student reaches formal operational thinking at an early age"],"answer":1,"explanation":"In ‘The Process of Education’ Bruner held that grasping structure makes a subject comprehensible, aids memory and allows transfer. It does not remove the need for practice or for concrete forms.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-608","question":"Before working out a sum, a Class 7 student quickly guesses, ‘The answer should be close to 200,’ and then checks it by calculation. Bruner’s view of such guessing is that:","options":["It is a bad habit that should be stopped, because it encourages careless work","It shows that the student is still stuck in the iconic mode of representation","It is a sign of test anxiety, and the student should be referred to a counsellor","Intuitive thinking is valuable and should be encouraged alongside checking"],"answer":3,"explanation":"Bruner valued intuitive thinking, the ability to make educated leaps, and felt schools neglected it. He wanted intuition to be tested by analytical thinking rather than suppressed.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-609","question":"A mother reads the same picture book with her toddler every evening: she points and asks, ‘What’s that?’, waits, and says, ‘Yes, it’s a cow!’ Over time she expects more words from the child. Bruner described such routine adult support for language as:","options":["A Language Acquisition Support System (LASS)","A Language Acquisition Device (LAD) at work","Holophrastic speech, using one word for a whole idea","Operant conditioning of verbal behaviour by praise"],"answer":0,"explanation":"Bruner proposed LASS to stress the role of structured social routines, in contrast to Chomsky’s inborn LAD. The adult raises expectations as the child grows, which is a form of scaffolding.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-610","question":"To teach place value, a Class 2 teacher in Bihar uses bundles of ten matchsticks, then has children draw bundles and loose sticks, and finally writes 34 as 3 tens 4 ones. The drawing step corresponds to Bruner’s:","options":["Enactive mode","Symbolic mode","Iconic mode","Formal operational mode"],"answer":2,"explanation":"Pictures and drawings are iconic representations. The common concrete-pictorial-abstract sequence in maths teaching follows Bruner’s enactive-iconic-symbolic order.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-611","question":"A Class 1 teacher writes ‘3 + 2 = 5’ on the board and explains it, but many children cannot use it. Following Bruner, the best way to improve the lesson is to:","options":["Repeat the written statement more slowly and loudly until the children remember it","Start with children joining groups of real objects, then pictures, and then the written sum","Give a short test so that the weak children can be identified and sent for remedial help","Wait until the children reach the concrete operational stage before teaching addition"],"answer":1,"explanation":"Bruner held that young children grasp ideas best when they meet them first through action and images. He rejected simply waiting for readiness, which makes the last option a Piaget-style misreading.","difficulty":"moderate","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-612","question":"Consider these statements comparing Bruner with Piaget. 1. Bruner gave language and culture a stronger role in speeding up cognitive growth than Piaget did. 2. Bruner, like Piaget, held that the earlier modes of thinking disappear once a higher mode develops. 3. Both saw the learner as active rather than a passive receiver. Which is/are correct?","options":["1 and 3 only","2 and 3 only","1 and 2 only","3 only"],"answer":0,"explanation":"Bruner stressed language, culture and instruction more than Piaget, and both were constructivists. Statement 2 is wrong: Bruner’s modes coexist, and even in Piaget earlier abilities are integrated rather than lost.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-613","question":"While helping a child build a pyramid of wooden blocks, a tutor holds the lower blocks steady so that the child can concentrate on fitting the top piece. In Wood, Bruner and Ross’s account of scaffolding, this tutoring function is called:","options":["Recruitment of the child's interest","Frustration control during failures","Demonstration of an ideal solution","Reduction in degrees of freedom"],"answer":3,"explanation":"Reducing degrees of freedom means simplifying the task so the learner handles only a manageable part. Recruitment is getting the child interested, and frustration control is keeping failure from discouraging him.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-614","question":"A Class 5 teacher draws a labelled flow diagram of the water cycle on the board. Which mode of representation is she mainly using, and what should follow according to Bruner?","options":["Enactive; the next step should be a practical demonstration of evaporation","Iconic; it should lead on to children explaining the cycle in words and terms","Symbolic; nothing further is needed, since a diagram is already abstract","Enactive; the children should copy the diagram several times to fix it in memory"],"answer":1,"explanation":"A diagram is an iconic representation. Bruner’s sequence moves on to the symbolic mode, where children use language and terms like evaporation and condensation.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-615","question":"How many of these are recognised limitations of pure, unguided discovery learning? I. It usually takes less time than direct instruction. II. Learners may ‘discover’ and keep wrong ideas if there is no guidance. III. It always reduces intrinsic motivation. IV. Learners with little prior knowledge may find it overwhelming.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and IV are real limitations. I is wrong: unguided discovery usually takes much more time than direct instruction. III is wrong: discovery tends to increase intrinsic motivation, as Bruner argued.","difficulty":"very-hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-616","question":"In a Bruner-style discovery lesson on magnets, what is the main role of the teacher?","options":["To deliver the complete rule at the start and then test children's recall at the end","To stay completely away from the groups, so that children are not influenced at all","To set up a problem, provide materials and ask questions that lead to the principle","To award marks to each child who reaches the answer first, to keep interest high"],"answer":2,"explanation":"Bruner’s teacher designs the situation and guides through questions, rather than lecturing or withdrawing entirely. Racing for marks shifts motivation from understanding to reward.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-617","question":"Assertion (A): Bruner recommended that basic ideas be revisited again and again through the school years. Reason (R): A learner’s understanding of a concept deepens as she can represent it in increasingly powerful ways.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The spiral curriculum follows from the idea that the same concept can be understood at higher levels as the learner’s modes of representation develop. R therefore explains A.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-618","question":"A Class 8 student plays a complex tabla rhythm perfectly but cannot describe it in words or draw it. In Bruner’s terms, this shows that:","options":["The student has not yet reached Piaget's concrete operational stage of thinking","Knowledge can be held enactively even by older learners with symbolic thought","The student's symbolic mode of representation has failed to develop normally","The skill was learnt purely through classical conditioning and not through thought"],"answer":1,"explanation":"Bruner’s modes are not confined to early childhood; motor skills often stay enactive. Lack of a verbal description does not mean the symbolic mode is absent.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-619","question":"A teacher shows ‘yes’ examples (mango, pea pod, tomato, cucumber) and ‘no’ examples (potato, carrot, onion) of the concept ‘fruit’ in the botanical sense, without naming it, and asks students to work out what the ‘yes’ examples share. This concept attainment approach is based on the work of:","options":["Jerome Bruner","B. F. Skinner","Lawrence Kohlberg","Erik Erikson"],"answer":0,"explanation":"Bruner, Goodnow and Austin studied how people attain concepts by testing hypotheses about the attributes of positive and negative examples; the concept attainment teaching model grew from this work.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-620","question":"Which statement about Bruner’s discovery learning is most accurate?","options":["It means leaving students to find out everything with no teacher involvement","It applies only to science, and not to languages or the social studies","It is essentially rote learning of rules followed by plenty of practice","It aims to make students active problem solvers who find relationships themselves"],"answer":3,"explanation":"Discovery learning centres on learners finding structure and relationships. It is used across subjects, and in practice it works best as guided discovery rather than total withdrawal of the teacher.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-621","question":"A Class 4 teacher asks students to act out the movement of the Earth around the Sun, then sketch the orbit, and later explains it using the terms ‘rotation’ and ‘revolution’. A visiting teacher says, ‘Acting is a waste of time at this age.’ Bruner would reply that:","options":["The visitor is right, since Class 4 children already think only in symbols and words","Acting out gives an enactive base on which iconic and symbolic understanding can build","Acting out is useful only for children with disabilities, not for the whole class","Only the final explanation matters, since knowledge exists only in the form of symbols"],"answer":1,"explanation":"For Bruner, enactive and iconic experiences support the later symbolic understanding of an idea, especially when it is new. He did not regard any mode as useless.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-622","question":"Which of the following pairs is correctly matched?","options":["Spiral curriculum: Vygotsky","Modes of representation: Piaget","Equilibration: Bruner","Discovery learning: Bruner"],"answer":3,"explanation":"Discovery learning, the spiral curriculum and the enactive-iconic-symbolic modes are Bruner’s ideas; equilibration is Piaget’s.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-623","question":"Bruner held that discovery learning tends to shift students’ motivation from:","options":["Intrinsic reward towards dependence on the teacher's approval and praise","Extrinsic rewards such as marks to the satisfaction of finding things out","Natural curiosity towards anxiety about making mistakes in front of others","Shared group goals towards individual competition for the highest marks"],"answer":1,"explanation":"Bruner argued that the reward of discovery lies in the discovery itself, so learners become less dependent on external rewards. This is one of his main arguments for the method.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-624","question":"A Class 9 student can solve 2x + 3 = 11 by rules but is confused when a problem is written in words. Her teacher shows a balance with a bag of unknown marbles plus 3 marbles on one side and 11 on the other, then a drawing of it. In Bruner’s terms, the teacher is:","options":["Lowering the standard, since students of Class 9 should work only with symbols","Using operant shaping, rewarding each step that brings her closer to the answer","Going back to enactive and iconic forms to give meaning to the symbolic rule","Applying Piaget's idea of horizontal décalage to the solving of linear equations"],"answer":2,"explanation":"Bruner held that any learner meeting a hard idea can benefit from enactive and iconic representations, which give meaning to symbols. Using them is not lowering the standard.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-625","question":"Which classroom practice best reflects Bruner’s idea that learners should ‘go beyond the information given’?","options":["Asking students to copy the worked notes exactly as they appear on the board","Giving a few examples of a pattern and asking students to predict and explain the rule","Reading the textbook aloud carefully while all the students follow along in their books","Asking students to memorise all the definitions given at the end of the chapter"],"answer":1,"explanation":"Bruner saw learning as forming categories and coding systems that allow inference beyond what is directly given. Copying and memorising stay within the information given.","difficulty":"hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-626","question":"A teacher tells Class 1 two stories: Ravi broke twelve glasses by accident while helping his mother; Sonu broke one glass while secretly reaching for sweets. Most children say Ravi was naughtier. According to Piaget, these children are showing:","options":["Autonomous morality, because they consider the facts of each case carefully","Moral realism, judging the act by the damage done rather than the intention","Kohlberg's Stage 2 reasoning, because they weigh up costs against benefits","Moral relativism, because they are comparing the two cases with each other"],"answer":1,"explanation":"In heteronomous morality (moral realism), young children judge by objective consequences; twelve glasses outweigh one, regardless of intention. Older children shift to judging by intention.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-627","question":"Asked about the same two stories, an eleven-year-old says, ‘Sonu was worse, because he was doing something he wasn’t supposed to; Ravi was only trying to help.’ In Piaget’s terms this child has moved to:","options":["Heteronomous morality (morality of constraint)","The premoral stage of rule-free play","Autonomous morality (morality of cooperation)","Immanent justice (automatic punishment)"],"answer":2,"explanation":"Weighing intentions above consequences marks the shift to autonomous morality, which Piaget placed at around ten years and beyond. Immanent justice is a belief of the younger, heteronomous child.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-628","question":"A seven-year-old who lied to his teacher in the morning trips on the way home and scrapes his knee. He tells his mother, ‘That happened because I lied.’ Piaget called this belief:","options":["Reciprocal punishment","Moral relativism","Egocentric speech","Immanent justice"],"answer":3,"explanation":"Immanent justice is the belief that wrongdoing is automatically punished by the world itself, typical of the heteronomous stage. Reciprocal punishment is a later idea that punishment should fit the wrong.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-629","question":"During a games period, Class 5 children agree among themselves to change the rules of kho-kho so that a younger child who has joined can also play fairly. According to Piaget, this shows that they:","options":["See rules as agreements that can be changed by mutual consent","Are still in moral realism, since they follow rules very strictly","Believe that rules come from adults and can never be altered","Are at Kohlberg's Stage 1, as they act mainly to avoid punishment"],"answer":0,"explanation":"Treating rules as mutual agreements open to change is the core of Piaget’s autonomous morality, which he observed in children’s games of marbles.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-630","question":"A boy breaks a neighbour’s window with his ball. A six-year-old says he should ‘get a big beating’; a ten-year-old says he should ‘pay for the glass from his pocket money and say sorry’. Piaget would describe these two views respectively as:","options":["Reciprocal punishment and expiatory punishment","Expiatory punishment and reciprocal punishment","Immanent justice and moral realism","Autonomous and heteronomous morality"],"answer":1,"explanation":"Younger children favour severe, arbitrary (expiatory) punishment; older children prefer punishment that fits and repairs the wrong (reciprocal). The first option reverses them.","difficulty":"very-hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-631","question":"Which experience did Piaget consider most important in moving children from heteronomous to autonomous morality?","options":["Strict discipline and close supervision by parents","Repeated moral instruction by teachers","Fear of punishment for breaking rules","Cooperative interaction with peers of equal status"],"answer":3,"explanation":"Piaget argued that relations of unilateral respect for adults sustain heteronomy, while give-and-take among equals shows rules to be mutual agreements. Adult control and fear work against autonomy.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-632","question":"Assertion (A): Piaget believed that cooperative peer interaction promotes autonomous morality. Reason (R): Among equals, children must negotiate, take others’ viewpoints and discover that rules are mutual agreements.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Peer interaction reduces egocentrism and shows rules as negotiated; that is precisely why Piaget saw it as driving autonomous morality.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-633","question":"In Class 2, children demand the same punishment for Meena, who spilt ink on a library book by accident, and Tara, who did it deliberately. What is the most appropriate response from the teacher?","options":["Punish both girls equally, since the children see that as the fair thing to do","Scold the class for being harsh and unforgiving towards their classmates","Ignore the issue, because moral thinking at this age cannot really be taught","Accept the view as age-typical and gently prompt them to consider each girl's intent"],"answer":3,"explanation":"Judging by outcome is age-typical moral realism; questions about intentions help children move toward autonomous judgment, while punishing equally reinforces the outcome-based view.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-634","question":"Which of these are features of Piaget’s heteronomous morality? I. Acts are judged by their consequences. II. Rules are seen as fixed and handed down by authorities. III. Punishment should fit the wrongdoing and repair the harm. IV. Belief that wrongdoing is automatically punished.","options":["I, II and IV only","I, II and III only","II, III and IV only","I and IV only"],"answer":0,"explanation":"Consequence-based judgment, fixed rules and immanent justice belong to the heteronomous stage; punishment that fits and repairs (reciprocity) belongs to autonomous morality.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-635","question":"A five-year-old says that a boy who told his mother ‘I saw a dog as big as an elephant’ told a worse lie than a boy who falsely told her ‘I got good marks’ and was believed. An older child says the opposite. What does Piaget’s work suggest?","options":["The younger child judges the lie by intention, and the older child by its consequence","Both children are still in the stage of moral realism, judging by fixed rules","The younger child judges by how far it departs from reality, the older by intent to deceive","The older child is still in heteronomous morality, as he relies on whether the mother believed it"],"answer":2,"explanation":"Piaget found young children rate a lie as worse the more unbelievable it is, an objective standard; older children judge the intent to deceive, so the believed lie is worse.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-636","question":"In a Class 5 football game, a boy grabs the ball and refuses to pass it. The other children decide that he will not get to keep the ball during the next game. Piaget would call this:","options":["Expiatory (atoning) punishment","Immanent justice from the world","Moral realism about fixed rules","Punishment by reciprocity"],"answer":3,"explanation":"Reciprocal punishment is logically linked to the offence (misuse the ball, lose access to it); it marks autonomous morality, in contrast to arbitrary, painful expiatory punishment.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-637","question":"Why did Piaget call the younger child’s morality ‘moral realism’?","options":["Because the child thinks realistically about both the consequences and the intentions","Because rules are seen as real, fixed things existing independently of people's purposes","Because the child is very realistic about the chances of actually being caught","Because the child prefers real-life examples to imaginary stories when judging acts"],"answer":1,"explanation":"Rules are treated as objective realities, sacred and unchangeable, with right and wrong read off the letter of the rule and the visible outcome, not intention.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-638","question":"Asked whether Heinz should steal the drug, Anjali (Class 10) says, ‘Maybe he could talk to the druggist again, or borrow the money. If he steals and goes to jail, who will look after his wife?’ How would Carol Gilligan interpret this response?","options":["As a care orientation focused on relationships, no less mature than a justice orientation","As Stage 3 reasoning, showing that Anjali is morally less developed than her peers","As preconventional reasoning, because she avoids taking a clear position on stealing","As evidence that girls cannot really reason about rights and justice in the abstract"],"answer":0,"explanation":"Gilligan argued that such responses, often scored at Kohlberg’s Stage 3, reflect a different voice: an ethic of care that seeks to preserve relationships, not lower maturity.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-639","question":"Which of these statements about Gilligan’s critique of Kohlberg are correct? I. Kohlberg’s original study was based on boys. II. His scoring tended to undervalue reasoning based on care, placing many women at Stage 3. III. Gilligan argued that women are morally inferior to men. IV. She proposed an ethic of care centred on relationships and responsibility.","options":["I and IV only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"I, II and IV describe her critique. III is the opposite of her claim: she argued the theory made women look less mature because it ignored the care perspective.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-640","question":"A woman explains a difficult decision: ‘I must think of my children, but I also have to look after myself; caring for myself is not selfish if it lets me keep caring for them.’ In Gilligan’s sequence this reflects:","options":["Orientation to individual survival","Goodness as self-sacrifice","Kohlberg's Stage 2, since she considers her own needs","Morality of non-violence (care for self and others)"],"answer":3,"explanation":"Gilligan’s highest level balances care for others with care for oneself (no one should be hurt, including the self). Self-sacrifice comes before it, and pure survival concern before that.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-641","question":"A Class 12 girl says, ‘A good daughter always puts the family first; I should drop my plan to study further so that my brother can go to college.’ In Gilligan’s terms she is at the level of:","options":["Goodness as self-sacrifice","Orientation to individual survival","Morality of non-violence","Postconventional justice"],"answer":0,"explanation":"Equating goodness with meeting others’ needs at the cost of one’s own is Gilligan’s second level; the mature level would also count her own needs as legitimate.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-642","question":"Later large reviews of research on Gilligan’s claim about gender and moral orientation found that:","options":["Women use only the care orientation and men use only the justice orientation","Gender differences are small; both sexes use care and justice reasoning","Men consistently score higher than women on Kohlberg's scale in every study","Moral orientation is fixed early by biological sex and cannot later change"],"answer":1,"explanation":"Meta-analyses found only small average differences; both men and women use both orientations, and real-life dilemmas involving relationships draw more care reasoning from everyone.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-643","question":"Which pairing correctly contrasts Kohlberg’s and Gilligan’s emphases?","options":["Kohlberg: care and relationships in context; Gilligan: rights, rules and impartial principles","Kohlberg: punishment and reward; Gilligan: justice and the law","Kohlberg: justice and impartial principles; Gilligan: care and relationships in context","Kohlberg: emotions and feelings; Gilligan: cognition and logical reasoning"],"answer":2,"explanation":"Kohlberg’s scale is built on an ethic of justice applied impartially; Gilligan stressed an ethic of care sensitive to relationships and particular situations.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-644","question":"A teacher designing a value-education unit wants it to reflect both Kohlberg’s and Gilligan’s insights. Which approach fits best?","options":["Use only Heinz-type dilemmas about rules and rights, as these are the standard measure","Present dilemmas of both fairness and care, and value both kinds of reasoning","Teach girls care-based values and boys justice-based values in separate sessions","Grade students by how closely their answers match Kohlberg's Stage 6 principles"],"answer":1,"explanation":"Both orientations are part of mature moral thinking and are used by both sexes; including real-life relational dilemmas and valuing care reasoning avoids the bias Gilligan identified.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-645","question":"Assertion (A): Gilligan argued that Kohlberg’s theory was biased against a care orientation. Reason (R): Kohlberg’s stages were originally derived from interviews with male participants only.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Gilligan traced the bias largely to the all-male sample from which the stages were built, which made justice reasoning the yardstick of maturity.","difficulty":"moderate","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-646","question":"How does Kohlberg’s account of moral development most clearly differ from Piaget’s?","options":["Kohlberg ignored cognition entirely, while Piaget based his account of morality on it","Kohlberg described only two broad stages, while Piaget described six detailed ones","Kohlberg extended a more detailed sequence into adolescence and adulthood","Kohlberg studied only girls, while Piaget based his studies only on boys"],"answer":2,"explanation":"Kohlberg built on Piaget’s cognitive base but proposed three levels and six stages stretching into adulthood; Piaget’s main account covered two moralities in childhood. The second option swaps the numbers.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-647","question":"A six-year-old insists that the rules of ludo ‘were made by God and the elders’ and refuses to let friends add a new rule even when all of them agree. A ten-year-old says, ‘If we all agree, we can play it the new way.’ Which statement best explains the difference?","options":["The younger child is in moral realism, viewing rules as sacred; the older sees them as agreements","The older child has no real respect for rules and is still in the premoral stage","Both children are at Kohlberg's Stage 4, as both are concerned with keeping rules","The younger child is more morally developed, since he shows greater respect for authority"],"answer":0,"explanation":"Piaget found younger children treat rules as fixed and from authority, while older children see rules as products of mutual consent that can be altered. Changing rules by agreement is not disrespect.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-648","question":"Gilligan described a transition ‘from selfishness to responsibility’. Which pair of levels does this transition link?","options":["Goodness as self-sacrifice to morality of non-violence","Orientation to individual survival to goodness as self-sacrifice","Morality of non-violence back to goodness as self-sacrifice","Kohlberg's preconventional level to his postconventional level"],"answer":1,"explanation":"The first transition moves from concern only for oneself (survival) to responsibility for others (self-sacrifice); the second, ‘from goodness to truth’, leads on to care for both self and others.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-649","question":"Which of these correctly matches Piaget’s moral ideas with ages? P. Judging by consequences. Q. Judging by intentions. R. Belief in immanent justice. S. Reciprocal punishment.","options":["P and R: older children; Q and S: younger children","P and S: younger children; Q and R: older children","P, Q, R and S: all typical of children under seven","P and R: younger children; Q and S: older children"],"answer":3,"explanation":"Consequence-based judgment and immanent justice mark the younger, heteronomous child; intention-based judgment and reciprocal punishment mark the older, autonomous child.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-650","question":"A Class 3 child says it is fine to hit a classmate ‘if Ma’am is not looking’, but in a later discussion argues that hitting is wrong ‘because the rule says so, and rules can never be broken’. Which statement is consistent with both Piaget and Kohlberg?","options":["Rule-bound, authority-based thinking is typical at this age and matures with cognition and experience","The child has reached autonomous morality, because he can clearly state the rule involved","The child is at Kohlberg's postconventional level, because he refers to rules and principles","Moral reasoning in children develops separately from, and is unrelated to, their cognitive development"],"answer":0,"explanation":"Both theorists see young children’s morality as authority- and consequence-oriented, with change driven by cognition and interaction; quoting a rule is not autonomy or principled thought.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-651","question":"Which of the following are among the specified disabilities listed in the Rights of Persons with Disabilities Act, 2016? I. Acid attack victims II. Thalassemia III. Dwarfism IV. Attention Deficit Hyperactivity Disorder","options":["I and II only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"The Act's 21 specified disabilities include acid attack victims, thalassemia and dwarfism; ADHD is not named as a separate category in the list.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-652","question":"When the RPwD Act, 2016 replaced the Persons with Disabilities Act, 1995, which change did it bring that most affects schools?","options":["It reduced the number of recognised disabilities, to make certification simpler and faster for families","It made special schools compulsory for all children with disabilities, so that experts meet their needs","It widened the list from 7 to 21 disabilities, adding conditions such as autism and specific learning disabilities","It removed all disability-related duties of schools and passed them entirely to the health department"],"answer":2,"explanation":"The 2016 Act widened the list from seven to twenty-one disabilities, so teachers must now recognise and support children with conditions like autism and specific learning disabilities.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-653","question":"A Class 6 student with low vision is given a seat near the board, large-print worksheets and permission to photograph the board on a tablet. The principal calls these ‘special favours that are unfair to other students’. Which response is correct?","options":["These are reasonable accommodations: necessary adjustments that let her participate equally, not favours","The principal is right; fairness means every student must be treated in exactly the same way","The adjustments are permitted only if her certified disability is assessed at above 80 per cent","The adjustments are favours, and should be given only during examinations, not in daily lessons"],"answer":0,"explanation":"The RPwD Act defines reasonable accommodation as necessary and appropriate adjustment, without disproportionate or undue burden, to ensure rights equally with others; denying it is itself a form of discrimination.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-654","question":"Under the RPwD Act, 2016, which of the following is NOT a duty of educational institutions funded or recognised by the government?","options":["Admitting children with disabilities without discrimination in any of its classes","Making buildings, campuses and facilities accessible to all children with disabilities","Detecting specific learning disabilities in children at the earliest and taking suitable steps","Placing children with disabilities in separate sections so that others' pace is not affected"],"answer":3,"explanation":"The Act requires non-discriminatory admission, accessibility, early detection of specific learning disabilities and individualised support towards full inclusion; separate sections would be segregation.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-655","question":"Zoya, in Class 5, has cerebral palsy, uses a wheelchair and has unclear speech. Her new teacher assumes she cannot follow Class 5 work and gives her Class 2 worksheets. What is wrong with this decision?","options":["Nothing; children with cerebral palsy nearly always have an intellectual disability as well","CP mainly affects movement and posture; her understanding must first be assessed by accessible means","The teacher should have started with Class 1 worksheets, to be sure that she meets success first","Children with cerebral palsy are better placed in special schools, where such worksheets are designed"],"answer":1,"explanation":"Unclear speech and motor difficulty are not evidence of low intelligence; many children with cerebral palsy have typical cognition, so the teacher must find an accessible way for her to show what she knows.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-656","question":"Dinesh, in Class 4, learns slowly but steadily in every subject, is somewhat below average all round, and his measured IQ is in the 70–85 range. He does not show a sharp gap between one skill and the rest. He is best described as:","options":["A child with a specific learning disability","A child with intellectual disability","A slow learner","A gifted underachiever"],"answer":2,"explanation":"A general, even slowness with borderline ability fits a slow learner; a specific learning disability involves an unexpected weakness in one area, and intellectual disability needs significant limits in both intelligence and adaptive behaviour.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-657","question":"Which of these statements about gifted underachievers are correct? I. Underachievement can result from classwork that is too easy and repetitive. II. A hidden learning disability may mask a child’s high ability. III. Underachievement proves that the child was never really gifted.","options":["I only","I and III only","II and III only","I and II only"],"answer":3,"explanation":"Boredom, unchallenging work and a masking disability are common causes of underachievement; a gap between potential and performance does not cancel the potential.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-658","question":"While teaching photosynthesis, a Class 7 teacher gives all students the same key concept but three versions of the follow-up task: one with labelled diagrams to complete, one with guided questions, and one asking them to design an experiment. This strategy is called:","options":["Tracking","A tiered assignment","Curriculum compacting","Peer tutoring"],"answer":1,"explanation":"Tiered assignments keep the same core concept while varying complexity to match readiness; tracking places children permanently in ability streams, and compacting removes already-mastered content.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-659","question":"A pre-test shows that Ananya, in Class 5, already knows about 90% of the coming unit on decimals. Her teacher lets her skip the parts she has mastered and use the saved time for an independent project on the use of decimals in sports. This is an example of:","options":["Curriculum compacting","Grade skipping (acceleration)","Ability tracking into streams","Remedial teaching of gaps"],"answer":0,"explanation":"Curriculum compacting tests what a learner already knows, drops the mastered content and replaces it with more challenging work, without moving her to a higher class.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-660","question":"For a unit on ratios, a Class 6 teacher lets students choose to work with cricket scores, recipe quantities or rangoli patterns, while all of them learn the same ratio concept. She is differentiating mainly on the basis of:","options":["Readiness","Interest","Age","Learning disability status"],"answer":1,"explanation":"Letting students choose the context they care about is differentiation by interest; the concept and its level stay the same, so it is not based on readiness.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-661","question":"To keep her Class 8 students motivated, a teacher offers a choice of project topics linked to local life, helps each student set a personal goal and lets them check their own progress against it. Which UDL principle does this mainly reflect?","options":["Multiple means of engagement","Multiple means of representation","Multiple means of action and expression","The theory of multiple intelligences"],"answer":0,"explanation":"Choice, relevance, goal-setting and self-monitoring sustain interest and effort, which is the engagement (‘why’) principle of UDL; representation concerns presenting content, and action-expression concerns showing learning.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-662","question":"Match the UDL principle with the aspect of learning it addresses. 1. Engagement 2. Representation 3. Action and expression; a. The ‘what’: how learners perceive and understand information b. The ‘how’: how learners plan and show what they know c. The ‘why’: learners’ interest, effort and self-regulation","options":["1-a, 2-b, 3-c","1-b, 2-a, 3-c","1-c, 2-b, 3-a","1-c, 2-a, 3-b"],"answer":3,"explanation":"Engagement is the why, representation the what, and action and expression the how of learning.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-663","question":"Assertion (A): Subtitles added to a classroom video for a deaf student also help many hearing students, such as those learning the language of instruction. Reason (R): Supports designed for accessibility often benefit a wide range of learners, which is a central idea of universal design.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Like a pavement ramp that helps wheelchair users and people with luggage alike, accessibility features such as subtitles benefit many learners, which explains A.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-664","question":"During a lesson on occupations, a Class 3 child declares, ‘Girls can’t become pilots.’ What is the most appropriate teacher response?","options":["Ignoring the remark, since children will learn the truth on their own as they grow up","Scolding the child in front of the class, so that no one repeats such a rude remark","Showing real women pilots and asking the class where such ideas come from","Telling the girls in the class to choose jobs that are more suited to them instead"],"answer":2,"explanation":"Stereotypes are best challenged with counter-examples and discussion that helps children examine their beliefs; silence lets the idea stand, and scolding shuts down thinking.","difficulty":"moderate","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-665","question":"Classmates keep calling a Class 5 boy by a term linked to his family’s caste-based occupation. He has started avoiding school. What should the teacher do?","options":["Advise the boy to ignore the teasing, since bullies lose interest when they get no reaction","Move the boy quietly to another section, so that he is protected from the same group","Wait for the boy's parents to complain formally before taking any action on the matter","Stop it at once, make clear caste-based name-calling is unacceptable, and follow up with the class"],"answer":3,"explanation":"Caste-based humiliation is discrimination the school must actively stop; asking the victim to ignore it or moving him places the burden on the child who is harmed.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-666","question":"In a Class 5 reading test, children from affluent families do much better than others on a passage about checking in at an airport, though the two groups do equally well on other passages. What is the most reasonable interpretation?","options":["Affluent children are generally more intelligent, and this passage simply revealed it","Children from poorer homes did not try their best on that particular passage","The passage drew on experiences familiar only to some children, so it is culturally biased","Reading comprehension tests are always free of bias, so the gap must reflect real ability"],"answer":2,"explanation":"Background knowledge strongly affects comprehension; when one passage alone shows a gap, its content, not the children's ability, is the likely cause.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-667","question":"Which teacher approach reflects an asset-based (rather than deficit-based) view of a Class 4 child from a fishing community?","options":["Using his knowledge of tides, boats and weighing the catch as a base for measurement lessons","Assuming he needs remedial work, since his home has few books and little print exposure","Advising his parents to stop involving him in family work so that he can focus on studies","Placing him with the weaker readers because of his background, to give him extra support"],"answer":0,"explanation":"An asset view treats the knowledge children bring from home as a resource for learning; a deficit view sees only what the home lacks and lowers expectations.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-668","question":"Assertion (A): Allowing Class 6 students in Bengaluru to discuss science in Kannada, Tamil or Urdu before writing answers in English will slow their learning of both English and science. Reason (R): Children can think and learn in only one language at a time.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","Both A and R are false"],"answer":3,"explanation":"Multilingual children draw on all their languages to build understanding, and talking in a familiar language deepens concepts that can then be expressed in English; both statements are false.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-669","question":"A head teacher argues that children from Gondi-speaking homes should be taught only in Hindi from the first day, since ‘early immersion is the fastest route’. Which counter-argument is best supported by NEP 2020 and research on multilingual learners?","options":["Children should not be taught Hindi at all until Class 8, so that their Gondi is fully protected first","Where possible, the home language should be the medium till at least Class 5, as a base for the second","Immersion is right, provided children are firmly discouraged from using any Gondi in the classroom","The medium of instruction makes no real difference to learning, so either choice is fine"],"answer":1,"explanation":"NEP 2020 recommends the home language or mother tongue as the medium wherever possible until at least Grade 5, preferably Grade 8, while other languages are still taught; it does not ban Hindi.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-670","question":"Which observation is LEAST suggestive that a Class 2 child may have a hearing difficulty?","options":["She watches other children before following spoken instructions","She often asks for instructions to be repeated","She responds quickly when her name is called softly from behind her","She turns one ear towards the speaker and seems inattentive when not facing the teacher"],"answer":2,"explanation":"Responding to a soft call from behind, without visual cues, shows good hearing; copying others, frequent requests to repeat and turning an ear are typical warning signs.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-671","question":"Pooja, in Class 4, holds her book very close, squints, often rubs her eyes, complains of headaches and makes many errors while copying from the board. Her teacher suspects dyslexia. What should be done first?","options":["Rule out a vision problem through eye screening, informing parents and seating her near the board","Begin intensive phonics remediation immediately, since her copying errors suggest dyslexia","Record her as careless and reduce marks for copying errors, so that she learns to be more careful","Refer her straight away for an IQ test, to check whether she has a general learning problem"],"answer":0,"explanation":"Her signs point to a possible visual problem, which must be ruled out before any learning disability is considered; teaching phonics would not correct poor eyesight.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-672","question":"A Class 3 child is restless and inattentive. Before anyone suspects ADHD, which of the following could also produce ADHD-like behaviour? I. An undetected hearing or vision problem II. Boredom because the work is far too easy III. Anxiety or stress at home IV. A learning difficulty that makes the work too hard","options":["I and II only","II and III only","I, III and IV only","I, II, III and IV"],"answer":3,"explanation":"All four can make a child appear inattentive or restless, which is why teachers should observe carefully and refer for professional assessment rather than label a child themselves.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-673","question":"When asked, ‘Do you want water?’, Aarav, a Class 1 child on the autism spectrum, replies, ‘Do you want water?’ What is the most appropriate interpretation and response?","options":["He is mocking the teacher by repeating her words and should be corrected firmly","This is echolalia, common in autism; model the answer and offer picture choices","He has not heard the question properly and needs to be sent for a hearing test","He is too young to answer such questions and should not be asked them for now"],"answer":1,"explanation":"Repeating heard words (echolalia) is frequent in autism and may be a step in processing or communicating; modelling the response and offering visual choices helps him reply meaningfully.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-674","question":"Assertion (A): When an autistic child has a meltdown because of sensory overload, the teacher should first reduce stimulation and help the child to a calm space, rather than lecture him about behaviour. Reason (R): A meltdown is a loss of control caused by being overwhelmed, not a deliberate attempt to get something.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because a meltdown is involuntary overwhelm, reasoning or punishment in the moment does not help; calming the environment first, then teaching coping strategies later, is the right sequence.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-675","question":"Gopal, a Class 4 child with intellectual disability, counts money correctly in class but cannot pay or check change at the village shop. Which teaching strategy addresses this problem most directly?","options":["Giving him more worksheets on money in class until he gets every sum right","Moving on to a new topic, since he has clearly mastered money in the classroom","Practising with real coins in varied settings, including role-play and real shops","Asking his parents to handle all his purchases until he is old enough to manage"],"answer":2,"explanation":"Children with intellectual disability often find it hard to transfer skills to new settings, so skills should be practised in varied, real contexts until they generalise.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-676","question":"Inspired by ‘learning by doing’, a teacher lets her Class 6 children do whatever activities they like all day, without any planning, saying ‘every experience is learning’. John Dewey would most likely object because:","options":["He held that children learn best through strict drill under the teacher's direct control","Not every experience is educative; experiences must be chosen to lead to further growth","He wanted activity in school to be limited to manual crafts such as weaving and carpentry","He argued that the curriculum must always follow the sequence laid down in the textbook"],"answer":1,"explanation":"In ‘Experience and Education’ Dewey warned that some experiences are mis-educative; the teacher must organise experiences with continuity and interaction so that each leads to further growth. Progressive education was never ‘anything goes’.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-677","question":"Which of these ideas are associated with John Dewey? I. The school should be a miniature community reflecting the life of the wider society. II. Education is a process of living, not merely a preparation for future living. III. The mind is a blank slate to be filled through drill. IV. Thinking begins with a felt problem or difficulty.","options":["I and III only","II and III only","I, II and III only","I, II and IV only"],"answer":3,"explanation":"Dewey saw school as an embryonic community, education as life itself, and reflective thinking as starting from a felt difficulty; the blank-slate-and-drill view is the very tradition he opposed.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-678","question":"Class 7 children notice stagnant water near their school breeding mosquitoes. With the teacher’s help they decide to survey the area, collect data from the local health centre, carry out the survey and present a plan to the panchayat, and finally judge what worked. This approach is the:","options":["Project method, developed by W. H. Kilpatrick from Dewey's ideas","Montessori method, based on self-correcting sensorial materials","Lecture-demonstration method, led and directed by the teacher","Programmed instruction, based on Skinner's operant conditioning"],"answer":0,"explanation":"Purposing, planning, executing and judging a real, learner-owned task are the steps of Kilpatrick’s project method, which grew out of Dewey’s pragmatism.","difficulty":"hard","source":"CTET Paper II · State TET"},
  {"id":"cdp-child-development-679","question":"Dewey contrasted ‘reflective action’ with ‘routine action’. Which teacher behaviour is an example of routine action in his sense?","options":["Asking why a lesson failed and deliberately trying a different approach the next time","Seeking students' views on what helped them learn and adjusting the plan accordingly","Teaching a chapter the same way every year because it has always been done so","Reading research and talking to colleagues to understand a persistent classroom problem"],"answer":2,"explanation":"Routine action is guided by habit, tradition and authority; reflective action is careful, persistent examination of beliefs and practices in the light of evidence and consequences.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-680","question":"A teacher is willing to consider that her favourite method may be wrong for this class (P), thinks carefully about the long-term consequences of her choices for her students (Q), and commits herself fully to improving despite setbacks (R). These match Dewey’s three attitudes for reflective teaching as:","options":["P-responsibility, Q-open-mindedness, R-wholeheartedness","P-wholeheartedness, Q-responsibility, R-open-mindedness","P-open-mindedness, Q-wholeheartedness, R-responsibility","P-open-mindedness, Q-responsibility, R-wholeheartedness"],"answer":3,"explanation":"Open-mindedness is readiness to consider other views and one’s own possible error; responsibility is weighing consequences; wholeheartedness is full commitment that keeps the other two going.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-681","question":"A Montessori-trained teacher notices a three-year-old pouring water from one jug to another, again and again, for twenty minutes. In keeping with Montessori’s ideas, she should:","options":["Stop the child and shift her to a reading lesson, since such repetition wastes valuable time","Not interrupt, since focused repetition of a chosen activity builds skill, order and focus","Give her a small reward each time she pours without spilling, to reinforce careful pouring","Show her the correct way repeatedly until she copies the adult's movements exactly"],"answer":1,"explanation":"Montessori valued deep, self-chosen concentration in ‘practical life’ work; the adult protects it rather than interrupting it or adding external rewards.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-682","question":"Montessori’s idea of ‘sensitive periods’ implies that a teacher of young children should:","options":["Watch for phases of intense interest, such as in order or language, and offer suitable activities","Delay all formal teaching until the child is seven, when the sensitive periods begin","Teach every child the same skill at the same chronological age, as the periods are fixed","Make children sensitive to criticism, so that they learn to correct their own errors quickly"],"answer":0,"explanation":"Montessori held that children pass through periods of special receptivity to particular kinds of learning; careful observation lets the teacher match materials to these phases instead of a fixed calendar.","difficulty":"hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-683","question":"Which statement correctly contrasts Froebel and Montessori?","options":["Froebel rejected play as a waste of time, while Montessori made imaginative play central to her method","Montessori's materials were symbolic gifts expressing spiritual unity; Froebel's were self-correcting sensory apparatus","Froebel's gifts were symbolic and used in group play with songs; Montessori's were self-correcting, for individual work","Both educators left no real role for the teacher, who was expected simply to stay out of the way"],"answer":2,"explanation":"Froebel, an idealist, gave his gifts symbolic meaning and used them in teacher-led group play and songs; Montessori designed self-correcting didactic apparatus for individual work. Option B swaps the two.","difficulty":"very-hard","source":"KVS PRT · DSSSB PRT"},
  {"id":"cdp-child-development-684","question":"Which image of the teacher best reflects Friedrich Froebel’s view?","options":["A drill master who moulds the child as a potter moulds clay into a set shape","A lecturer who transmits knowledge clearly to attentive but passive listeners","A judge who ranks children by achievement so that each knows where he stands","A gardener who provides conditions for the child's nature to unfold through play"],"answer":3,"explanation":"Froebel’s ‘kindergarten’ (children’s garden) pictured children as plants and the teacher as a gardener nurturing natural growth, not shaping it from outside.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-685","question":"Assertion (A): Froebel regarded play as the highest expression of human development in early childhood. Reason (R): For Froebel, play is the free self-expression of the child’s inner nature, that is, self-activity.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Froebel valued play so highly precisely because he saw it as self-activity, the outward expression of the child’s inner nature; R therefore explains A.","difficulty":"very-hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-686","question":"A common criticism of the Montessori method is that it:","options":["Gives too much importance to group singing, story-telling and make-believe games","Leaves little room for imaginative play and group activity, stressing individual work","Ignores the training of the senses in favour of early reading and writing","Depends entirely on rote memorisation of facts that the teacher dictates"],"answer":1,"explanation":"Critics argued that Montessori’s individual, material-bound work left little room for fantasy, free imaginative play and group social activity; sense training was in fact her strength.","difficulty":"hard","source":"KVS PRT · DSSSB PRT"},
  {"id":"cdp-child-development-687","question":"Which classroom practice would John Dewey most strongly criticise?","options":["Children growing a kitchen garden and keeping careful records of how the plants grow","Discussing a local problem as a class and testing out possible solutions to it","Fixed subject periods in which children memorise facts unconnected with experience","Group work in which children share out tasks and work towards a common goal"],"answer":2,"explanation":"Dewey opposed isolated, memorised subject matter cut off from the child’s experience; gardening, problem-solving and shared purposeful activity were central to his school.","difficulty":"moderate","source":"CTET · State TET"},
  {"id":"cdp-child-development-688","question":"In ‘Democracy and Education’ (1916), Dewey linked education and democracy mainly by arguing that:","options":["Only elected representatives should decide what is taught in the nation's schools","Democracy requires that children be trained to obey authority without questioning it","Schools should mainly prepare a small, capable elite for leadership in public life","Democracy needs schools where children share purposeful activity across differences"],"answer":3,"explanation":"For Dewey democracy is ‘a mode of associated living’; schools nurture it by being communities of shared, purposeful activity, not by drilling obedience or training an elite.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-689","question":"Match each educator with the institution linked to him or her: P. Maria Montessori  Q. Friedrich Froebel  R. Rabindranath Tagore  S. John Dewey — 1. Casa dei Bambini, Rome  2. The first kindergarten, Germany  3. Patha Bhavana, Santiniketan  4. Laboratory School, Chicago","options":["P-1, Q-2, R-3, S-4","P-2, Q-1, R-3, S-4","P-1, Q-2, R-4, S-3","P-4, Q-2, R-3, S-1"],"answer":0,"explanation":"Montessori opened the Casa dei Bambini in Rome (1907), Froebel founded the kindergarten in Germany (1837), Tagore began his school at Santiniketan (1901), and Dewey ran the Laboratory School in Chicago (1896).","difficulty":"hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-690","question":"Dewey’s pragmatism implies which view of knowledge in the classroom?","options":["Knowledge is fixed and eternal, and should be handed on unchanged to each generation","Knowledge is tested by its consequences in experience and stays open to revision","Knowledge is found only in authoritative texts, which the teacher interprets for pupils","Knowledge is innate in the mind and is merely recalled through skilful questioning"],"answer":1,"explanation":"For the pragmatist, ideas are tools judged by how they work out in experience, so knowledge is provisional and built through inquiry, not received as fixed truth.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-691","question":"In a Montessori classroom the teacher is called a ‘directress’ because she:","options":["Directs every activity step by step, so that the materials are used correctly","Directs the class mainly through short lectures followed by guided practice","Prepares the environment, demonstrates materials, then observes and guides","Directs children to compete with one another for prizes and recognition"],"answer":2,"explanation":"The Montessori teacher’s main work is preparing the environment and observing; after a brief demonstration, the child works independently while the teacher guides unobtrusively.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-692","question":"Which of these statements about Maria Montessori are correct? I. She trained as a physician and first worked with children with intellectual disabilities. II. Mixed-age groups are a feature of Montessori classrooms. III. She favoured rewards and punishments to motivate children. IV. ‘Practical life’ activities such as buttoning and pouring develop independence and coordination.","options":["I and III only","II, III and IV only","I and IV only","I, II and IV only"],"answer":3,"explanation":"Montessori was a medical doctor, used mixed-age groups and practical-life work, and rejected rewards and punishments in favour of the satisfaction of the work itself, so III is false.","difficulty":"very-hard","source":"CTET Paper I · DSSSB PRT"},
  {"id":"cdp-child-development-693","question":"Dewey argued that ‘interest’ and ‘effort’ are not opposites. In the classroom this means that:","options":["Tasks linked to the child's genuine purposes call out effort without outside pressure","Children should be given only tasks they find entertaining, so that effort is never needed","Effort must be compelled through punishment or rewards whenever interest is absent","Interest matters only in the early years; later, effort alone must carry the learner"],"answer":0,"explanation":"Dewey held that real interest in an end generates the effort needed to reach it; pure entertainment and forced effort are both failures to connect the task with the child’s purposes.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-694","question":"A kindergarten teacher gives children a soft ball, then a sphere, a cube and a cylinder, followed by building blocks, and accompanies the play with songs and finger rhymes. She is following:","options":["Montessori’s self-correcting didactic apparatus","Pestalozzi’s object lessons","Froebel’s gifts and occupations","Skinner’s teaching machines"],"answer":2,"explanation":"The ball, the sphere-cube-cylinder set and building blocks are Froebel’s ‘gifts’, used with songs and rhymes; Pestalozzi’s object lessons used everyday objects to train observation and naming.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-695","question":"Arrange Dewey’s steps of reflective thinking as a Class 8 group investigates wilting plants: P. They notice the plants drooping and feel puzzled. Q. They test by moving one pot to the window and watering another more often. R. They pin down exactly what the problem is: only the plants on the dark side of the room droop. S. They suggest possible causes and reason out what each would predict.","options":["P, S, R, Q","P, R, S, Q","R, P, Q, S","P, Q, R, S"],"answer":1,"explanation":"Dewey’s sequence is felt difficulty, locating and defining it, suggesting solutions, reasoning out their implications, and testing by observation or experiment: P, R, S, Q.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-696","question":"Which feature is common to the educational ideas of Dewey, Montessori and Froebel?","options":["Reliance on firm corporal punishment to maintain classroom discipline","Strictly uniform pacing, so that all children move through work together","A child-centred view in which the child's own activity is central","Emphasis on memorising set texts and reciting them before the class"],"answer":2,"explanation":"Despite their differences, all three placed the active child at the centre: Dewey through experience, Montessori through self-education with materials and Froebel through self-activity in play.","difficulty":"moderate","source":"CTET · State TET"},
  {"id":"cdp-child-development-697","question":"Assertion (A): Montessori recommended giving children stars and prizes for correct work. Reason (R): Montessori held that the satisfaction of the work itself, helped by self-correcting materials, is sufficient motivation.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Montessori rejected external rewards and punishments; she believed children find satisfaction in purposeful work and that the materials let them correct their own mistakes.","difficulty":"very-hard","source":"CTET Paper I · DSSSB PRT"},
  {"id":"cdp-child-development-698","question":"Froebel’s philosophy was rooted in idealism. Which belief follows from this?","options":["The child's mind is a blank slate on which experience writes everything it knows","Learning is nothing more than conditioning by rewards, so behaviour is shaped from outside","All things form a divine unity, and education helps the child's inner nature unfold","An idea is true only if it works in practice and leads to useful consequences"],"answer":2,"explanation":"Froebel, an idealist, saw a spiritual unity in nature, God and humanity and saw education as the unfolding of the child’s inner nature; the other options belong to empiricism, behaviourism and pragmatism.","difficulty":"hard","source":"KVS PRT · DSSSB PRT"},
  {"id":"cdp-child-development-699","question":"Dewey called his school at the University of Chicago a ‘laboratory school’ because:","options":["It was a place to test and develop educational ideas through actual practice","It taught only science subjects, with most lessons held in its laboratories","It trained young people to work as laboratory assistants for local industry","It carried out controlled experiments on animal learning for the university"],"answer":0,"explanation":"Like a science laboratory, the school was a site where educational theory was tried out, observed and revised in practice with real children.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-700","question":"Which of these are features of a good project in the project method? I. It arises from a purpose the learners genuinely feel. II. The learners plan and carry it out. III. The teacher fixes every step in advance. IV. It ends with the learners judging the outcome.","options":["I, II and III only","I, II and IV only","II and III only","I, III and IV only"],"answer":1,"explanation":"Kilpatrick’s project is a ‘wholehearted purposeful activity’: learners purpose, plan, execute and judge it; a teacher who fixes every step turns it into an assignment.","difficulty":"very-hard","source":"CTET Paper II · State TET"},
  {"id":"cdp-child-development-701","question":"A Class 3 teacher wants children to recall the order in which to solve a long-division sum, and she reads out all eleven steps at once. Most children manage only the first three or four. What is the best explanation and remedy?","options":["Long-term memory is already full; the children should rest before the lesson resumes","The children lack motivation; announce a prize for anyone who remembers all the steps","Working memory holds only a few items; give the steps in small sets with a step chart","Sensory memory lasts for hours; simply repeat all eleven steps again tomorrow"],"answer":2,"explanation":"Working (short-term) memory has a small capacity, roughly 7 ± 2 items for adults and fewer for children. Breaking information into small chunks and giving an external aid reduces the load.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-702","question":"Sumit remembers his father's mobile number 9876543210 by saying it as ‘98765 – 43210’. Which memory process makes this easier?","options":["Chunking, which groups items into fewer meaningful units","Proactive interference from numbers learnt earlier","Decay of the sensory trace after a few seconds","Maintenance of iconic memory through visual imagery"],"answer":0,"explanation":"Chunking packs several items into a smaller number of meaningful units, so more information fits within the limited span of short-term memory.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-703","question":"Three groups of Class 8 students see the same list of words. Group A says whether each word is in capital letters, Group B whether it rhymes with ‘tree’, and Group C whether it fits the sentence ‘She bought a ___ at the market.’ In a surprise recall test, which result is expected and why?","options":["Group A recalls most, because visual features are noticed first and stored most firmly","All groups recall equally, because the exposure time for the words was the same","Group B recalls most, because sound is the main code used by long-term memory","Group C recalls most, because meaning-based processing gives more durable memories"],"answer":3,"explanation":"Craik and Lockhart's levels-of-processing view holds that semantic (meaning) processing yields better retention than shallow structural or phonemic processing.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-704","question":"Match each memory with its type. P. Knowing how to ride a bicycle  Q. Remembering the school trip to Agra in Class 4  R. Knowing that the Ganga rises at Gangotri  S. Feeling uneasy in a room where one once got scolded, without recalling why. 1. Episodic  2. Semantic  3. Procedural  4. Implicit emotional conditioning","options":["P-1, Q-3, R-2, S-4","P-3, Q-1, R-2, S-4","P-3, Q-2, R-1, S-4","P-4, Q-1, R-2, S-3"],"answer":1,"explanation":"Skills are procedural; personal events located in time are episodic; general facts are semantic; a conditioned emotional reaction without conscious recall is implicit memory.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-705","question":"In Baddeley's model of working memory, which component directs attention, decides what to focus on and coordinates the other subsystems while a Class 7 student solves a multi-step word problem?","options":["Phonological loop","Visuospatial sketchpad","Central executive","Sensory register"],"answer":2,"explanation":"The central executive is the attentional control system of working memory; the phonological loop holds speech-based information and the sketchpad holds visual and spatial information.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-706","question":"Assertion (A): In free recall of a word list, the advantage for the last few words disappears if students do 30 seconds of counting backwards before recalling. Reason (R): The last items are recalled well because they are still held in short-term memory, which is displaced by the distracting task.","options":["A is true but R is false","A is false but R is true","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"The recency effect depends on short-term memory, so a filled delay wipes it out, while the primacy effect (from extra rehearsal into long-term memory) survives.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-707","question":"Nisha revised her history notes in her quiet bedroom and knew them well, but in the noisy, unfamiliar examination hall she could not recall several points that came back to her once she got home. This is best explained by:","options":["Decay of memory traces through disuse in the days between revision and the exam","Cue-dependent forgetting, as the retrieval cues present during learning were missing","Retroactive interference from other subjects she revised after her history notes","Repression of anxiety-provoking material, pushed out of awareness by exam stress"],"answer":1,"explanation":"The information was stored (it returned at home) but could not be retrieved without matching cues. Context-dependent, cue-dependent forgetting is a retrieval failure, not loss.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-708","question":"Two Class 9 students have one hour before a science test next week. Asha re-reads her notes three times. Bilal reads once and then spends the rest of the time closing the book and writing down everything he can recall, checking gaps afterwards. Research on memory predicts that:","options":["Bilal will remember more a week later, because retrieval practice strengthens memory","Asha will remember more, because repeated reading builds strong familiarity with the notes","Both will remember equally, because the time they spent studying was exactly the same","Asha will remember more, because self-testing causes anxiety that blocks later recall"],"answer":0,"explanation":"The testing effect shows that actively retrieving information strengthens long-term retention more than re-reading, which mostly produces a feeling of familiarity.","difficulty":"hard","source":"CTET Paper 2 · NVS TGT"},
  {"id":"cdp-child-development-709","question":"Rani studies spellings for 20 minutes a day for six days; Gauri studies the same spellings for two hours the night before the test. On a test given a month later, which is most likely?","options":["Gauri remembers more, because a long massed session builds stronger memory traces","Both remember the same amount, because their total study time was roughly equal","Rani remembers more, because distributed practice gives better long-term retention","Neither remembers anything, because spellings are almost always forgotten within a month"],"answer":2,"explanation":"The spacing effect: practice spread over time gives better long-term retention than the same amount crammed into one session, even if cramming helps a test the next morning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-710","question":"Ebbinghaus's forgetting curve shows that forgetting is not steady over time. What does it imply for when a teacher should first review a new lesson?","options":["After about a month, when most of it is forgotten and relearning is quickest","Only just before the annual examination, so that it is fresh for the paper","Never, because whatever is forgotten was never really learnt in the first place","Soon after the lesson, such as the next day, since the steepest loss is early"],"answer":3,"explanation":"Most forgetting occurs shortly after learning and then levels off. An early review catches material before the steep drop, and later reviews can be spaced further apart.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-711","question":"A man cannot recall a single line of a Sanskrit shloka he learnt as a child, yet he relearns it in far fewer repetitions than a similar shloka he has never studied. What does this demonstrate?","options":["The memory had completely decayed, so the quick relearning was only chance","Some trace remained in memory, as Ebbinghaus showed with the savings method","Proactive interference from the second shloka slowed down learning of that one","Childhood memories are stored only as procedural memory, not as verbal memory"],"answer":1,"explanation":"Ebbinghaus measured retention by savings: if relearning takes fewer trials than original learning, something was retained even when nothing could be recalled.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-712","question":"The Sharma family changed their landline number six months ago, but when asked for the new number, Mrs Sharma keeps saying the old one. This is an example of:","options":["Proactive interference","Retroactive interference","Motivated forgetting","Decay of the sensory register"],"answer":0,"explanation":"In proactive interference, older learning disrupts the recall of newer learning. Here the old number intrudes on recall of the new one.","difficulty":"hard","source":"CTET Paper 1 · REET"},
  {"id":"cdp-child-development-713","question":"A Class 8 student learns the reigns of the Mughal emperors in the first week and the Delhi Sultanate rulers in the second week. In the third week, when asked about the Mughals, he mixes in Sultanate names and dates. Which kind of forgetting is this?","options":["Proactive interference, since the Mughal rulers were the ones learnt first","Decay, since the Mughal learning is older and has faded with the passage of time","Retroactive interference, since newer learning disrupts recall of the earlier material","Repression, since history lessons are anxiety-provoking and pushed out of awareness"],"answer":2,"explanation":"What matters is which memory is being recalled: when later learning disrupts recall of earlier learning, it is retroactive interference. Recalling the Mughals (older) is disrupted by the Sultanate (newer).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-714","question":"During an oral quiz, Arnav is sure he knows the name of the river on which Hirakud dam is built; he says it begins with ‘Maha’ and is a long name, but cannot produce it until a classmate whispers it. This tip-of-the-tongue state shows that:","options":["The information was never properly encoded into memory in the first place","The information has decayed completely from long-term memory over time","He is unconsciously motivated to forget it because quizzes make him anxious","The information is stored but temporarily inaccessible: a retrieval failure"],"answer":3,"explanation":"Partial recall (the first part of the word) proves the word is in memory; the problem is retrieval. The cue from a classmate immediately unlocks it. (The river is the Mahanadi.)","difficulty":"moderate","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-715","question":"In a classic study, students who slept after learning nonsense syllables recalled more after eight hours than students who stayed awake and went about their daily activities. Which explanation of forgetting does this most support?","options":["Interference from intervening activity, rather than the simple passage of time","Decay, since an equal amount of time passed for both groups of students","Motivated forgetting of material that the waking students found unpleasant","Lack of initial encoding, since the awake group paid less attention while learning"],"answer":0,"explanation":"Jenkins and Dallenbach found less forgetting after sleep. If time alone caused decay both groups should be equal; the awake group forgot more because of interfering experiences.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-child-development-716","question":"While reading a passage, Class 6 student Lata stops, asks herself whether she has understood the paragraph, realises she has not, and decides to re-read it slowly and underline key words. This shows:","options":["Automaticity: reading fluently without needing conscious effort","Metacognition: monitoring and regulating one's own thinking","Proactive interference: earlier reading disrupting new reading","Classical conditioning: a learned response to a reading cue"],"answer":1,"explanation":"Metacognition (Flavell) is awareness and control of one's own cognitive processes: checking comprehension and changing strategy are its two core parts.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-717","question":"Assertion (A): Children who still decode words letter by letter often understand little of what they read, even short passages. Reason (R): Slow decoding uses up most of the limited capacity of working memory, leaving little for comprehension.","options":["A is true but R is false","A is false but R is true","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A"],"answer":2,"explanation":"When basic skills become automatic they need little working-memory capacity, freeing it for meaning. Effortful decoding consumes the capacity that comprehension needs.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-718","question":"To remember that the French word ‘pain’ means bread, a student imagines a loaf of bread that causes him pain when it falls on his foot. Which memory aid is this?","options":["Method of loci","Acronym","Rote rehearsal","Keyword method"],"answer":3,"explanation":"The keyword method links a foreign word to a similar-sounding familiar word and an interactive image of its meaning. The method of loci places items in familiar locations; an acronym uses first letters.","difficulty":"hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-719","question":"After Class 3 children can say the table of 7 without error, the teacher continues short practice of it for a few more days. Psychologically, this extra practice:","options":["Is overlearning, which improves long-term retention and makes recall automatic","Is wasteful, since learning is complete at the very first error-free recall","Causes retroactive interference with the table of 6 learnt earlier in the term","Reduces children's motivation through boredom, and therefore weakens memory"],"answer":0,"explanation":"Practice beyond the point of first mastery (overlearning) slows forgetting and builds automaticity, especially for basic facts used repeatedly.","difficulty":"hard","source":"CTET · REET"},
  {"id":"cdp-child-development-720","question":"Many Class 6 students answer a multiple-choice item on the capital of Meghalaya correctly but leave the same question blank when it appears as a fill-in-the-blank. The most likely reason is that:","options":["Multiple-choice items really test a different subject from fill-in-the-blank items","Recognition needs less retrieval effort than recall, because the cue is supplied","Students forget faster when they are taking a fill-in-the-blank type of test","Recall tests measure only short-term memory, not what is held in long-term memory"],"answer":1,"explanation":"In recognition the correct answer is present as a cue, so a weaker trace can be enough; recall requires the learner to generate it unaided, so it is harder.","difficulty":"moderate","source":"CTET Paper 2 · NVS TGT"},
  {"id":"cdp-child-development-721","question":"A Class 7 science worksheet shows a diagram of the heart with numbers 1–10, and the explanation of each numbered part is printed on the next page. Students struggle. What is the best change according to cognitive load research?","options":["Add more decorative pictures and colours to make the page more attractive","Ask students to memorise the ten numbers and their parts before the lesson","Place short labels and explanations directly next to the parts on the diagram","Remove the diagram altogether and keep only the written text explanations"],"answer":2,"explanation":"Splitting related information forces learners to hold one source in working memory while searching for the other (split-attention). Integrating labels with the diagram reduces this extraneous load.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-722","question":"A teacher explains the water cycle while pointing to a simple labelled diagram, rather than using only words. Paivio's dual coding theory explains the benefit as follows:","options":["Pictures distract attention from the words, so they should generally be avoided","Images are processed only in short-term memory and never reach long-term memory","The diagram helps only the ‘visual learners’ in the class, not the others","Information coded both verbally and visually has two retrieval routes"],"answer":3,"explanation":"Dual coding theory holds that verbal and imaginal codes are separate but linked systems; encoding in both increases the chance of later retrieval for learners generally.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-723","question":"According to the information processing model, which of these statements are correct? I. Information in the sensory register is lost within seconds unless it is attended to. II. Attention decides what moves from the sensory register into working memory. III. Long-term memory has a very small capacity of about seven items. IV. Elaborative encoding helps transfer information from working memory into long-term memory.","options":["I, II and IV only","I and III only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"The 7 ± 2 limit applies to short-term (working) memory; long-term memory is thought to have practically unlimited capacity, so III is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-724","question":"A teacher flashes a card with twelve letters for half a second. Children say they ‘saw them all’ but can report only four or five before the image fades. This illustrates the:","options":["Limited capacity of long-term memory for letters","Very brief duration of iconic (visual sensory) memory","Primacy effect favouring the first letters seen","Retroactive interference from the later letters"],"answer":1,"explanation":"Iconic memory briefly holds a large amount of visual information but fades in well under a second, so only what is attended to quickly can be reported.","difficulty":"moderate","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-725","question":"Children forget an embarrassing incident in which they wet their clothes during a school function, though they remember the rest of the function clearly. Freud would explain this selective loss as:","options":["Proactive interference from earlier functions","Decay of the memory trace through disuse","Motivated forgetting, or repression","Cue overload from too many similar events"],"answer":2,"explanation":"Motivated forgetting (repression in Freudian terms) is the pushing of painful or anxiety-provoking memories out of awareness, which explains why only the embarrassing part is lost.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-726","question":"Mayer and Salovey’s ability model describes emotional intelligence in four branches. Which of the following is NOT one of these four branches?","options":["Perceiving emotions accurately","Using emotions to facilitate thinking","Self-motivation in the face of setbacks","Managing emotions in oneself and others"],"answer":2,"explanation":"The four branches are perceiving, using, understanding and managing emotions. ‘Motivation’ is one of the domains in Goleman’s popular mixed model, not a Mayer–Salovey branch.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-727","question":"Assertion (A): Schools can strengthen students’ emotional intelligence through planned social-emotional learning activities. Reason (R): Emotional intelligence is a fixed inborn trait that does not change with experience.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Skills such as recognising and regulating emotions and showing empathy can be taught and practised; if R were true, A would be impossible, so R is false.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-728","question":"Riya notices that her friend Ayesha, usually chatty, has been silent since morning. Without being told, Riya guesses that something has upset her, sits beside her at lunch and listens. In Goleman’s model, Riya is mainly showing:","options":["Self-regulation","Empathy","Self-awareness","Self-motivation"],"answer":1,"explanation":"Empathy is sensing and understanding other people’s feelings; the other three domains in the options concern one’s own emotions and drive.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-729","question":"On sports day in a Guwahati school, two house groups start quarrelling over a disputed relay result. The Class 10 captain calms both sides, gets them to agree on a re-run and keeps both teams in good spirits. In Goleman’s model of emotional intelligence, this mainly reflects:","options":["Self-awareness of his own feelings","Self-motivation towards his goals","Empathy alone, sensing others' moods","Social skills (managing relationships)"],"answer":3,"explanation":"Handling conflict, negotiating and influencing groups is Goleman’s social-skills domain; empathy is part of what makes it possible, but resolving the dispute goes beyond merely sensing others’ feelings.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-730","question":"Which of the following statements about Alfred Binet’s work are correct? I. The Binet–Simon scale (1905) was developed to identify children who needed special help in school. II. Binet introduced the idea of mental age. III. Binet held that intelligence is fixed and cannot be improved by education. IV. Binet himself coined the formula IQ = MA ÷ CA × 100.","options":["I and II only","I, II and III only","II and IV only","I, II and IV only"],"answer":0,"explanation":"Binet built his scale for the French schools to find children needing help and used the idea of mental age. He warned against seeing intelligence as fixed; the quotient idea came from William Stern and the ×100 form from Lewis Terman.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-731","question":"Match the psychologist with the contribution: 1. William Stern 2. Lewis Terman 3. David Wechsler 4. Alfred Binet; a. Stanford–Binet test and the IQ multiplied by 100 b. Proposed the intelligence quotient as mental age divided by chronological age c. First practical intelligence scale with Simon d. Deviation IQ and separate verbal and performance scales","options":["1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-b, 2-a, 3-d, 4-c","1-c, 2-a, 3-d, 4-b"],"answer":2,"explanation":"Stern proposed the quotient MA/CA, Terman revised Binet’s test at Stanford and multiplied by 100, Wechsler introduced the deviation IQ with verbal and performance sub-scales, and Binet and Simon built the first practical scale.","difficulty":"hard","source":"CTET · KVS PGT"},
  {"id":"cdp-child-development-732","question":"If the classic ratio-IQ formula is applied to a 32-year-old whose measured mental age is 16, it gives an IQ of 50. This result is misleading mainly because:","options":["Mental age, as these tests measure it, stops rising in late adolescence, so adults look less able","Adults always have higher mental ages than chronological ages, so the score should be above 100","The formula should multiply the two ages rather than divide one by the other to give the IQ","Intelligence tests cannot validly be given to adults at all, so any adult score is meaningless"],"answer":0,"explanation":"Mental-age scores level off around the mid to late teens, so the ratio falls steadily with age for everyone. The deviation IQ, which compares a person with others of the same age, removes this problem.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-733","question":"Arjun, 11, scores 68 on an individual intelligence test, but he manages money at his family’s shop, travels alone by bus, cooks simple meals and gets along well with others. Which conclusion is most appropriate?","options":["He must be classed as having intellectual disability, since his IQ score is below 70","He should be placed in a special school straight away, without any further assessment","The score is irrelevant, because IQ tests have no value at all in such decisions","An IQ score alone cannot establish it; significant adaptive limitations must also exist"],"answer":3,"explanation":"Standard definitions of intellectual disability require significant limitations in both intellectual functioning and adaptive behaviour, beginning in the developmental period; good adaptive functioning argues against the label and the score may also contain error.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PGT"},
  {"id":"cdp-child-development-734","question":"A school counsellor must decide whether one particular Class 3 child needs special educational support. Which type of intelligence test is most suitable, and why?","options":["A group verbal test, because it is quick, cheap and easy to score for any child","An individual test, since the examiner can observe the child and probe her answers","A group non-verbal test, because individual tests are always biased against children","No test at all, because intelligence cannot be measured in any meaningful way"],"answer":1,"explanation":"Group tests suit large-scale screening; decisions about one child need individual testing (along with other information), where the examiner can watch attention, anxiety and strategies.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-735","question":"Bhatia’s Battery of Performance Tests, developed in India, would be especially suitable for assessing the intelligence of:","options":["A child who cannot read and has limited command of the test-giver's language","A college student applying for a merit scholarship in an English-medium course","A child who must be compared with classmates on reading speed and accuracy","A child already diagnosed using a verbal test, to confirm the same verbal score"],"answer":0,"explanation":"Performance tests use tasks such as block designs and pattern drawing that need little language or literacy, so they suit non-literate children or those with limited proficiency in the testing language.","difficulty":"very-hard","source":"KVS PGT · State TET"},
  {"id":"cdp-child-development-736","question":"Which statement about the stability of measured intelligence is best supported by research?","options":["Scores on infant developmental tests predict a person's adult IQ almost perfectly","IQ never changes at all once a child has started going to school","IQ scores are equally unstable at all ages, from infancy right through to adulthood","Infant scores predict later IQ poorly; scores grow more stable in the school years"],"answer":3,"explanation":"Infant tests measure mainly sensory and motor skills and predict later IQ weakly; stability increases through childhood, yet environments such as schooling and deprivation can still shift scores.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-737","question":"In a well-known American study (Getzels and Jackson), students who were highly creative but not the highest in IQ were compared with students who had very high IQ but were less creative. What did teachers’ ratings reveal?","options":["Teachers clearly preferred the highly creative students for their original ideas","Teachers rated both groups equally, since their achievement was about the same","Teachers tended to prefer the high-IQ students, though both groups achieved similarly","Teachers could not tell the two groups apart in their ratings of the students"],"answer":2,"explanation":"The study found similar achievement in both groups but teachers favoured the high-IQ, more conforming students; creative students’ unusual ideas and humour were less welcomed, a caution for classrooms.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-738","question":"A Class 7 teacher wants to assess a creative-writing task without killing originality. Which approach is most suitable?","options":["Award marks only if the piece closely matches the format of the sample answer given","Use a rubric with clear criteria that include credit for original ideas and good language","Give equal marks to every student, since creativity cannot really be assessed fairly","Mark only spelling and handwriting, since these can be checked objectively by anyone"],"answer":1,"explanation":"A transparent rubric that explicitly values originality alongside craft guides students without forcing a single model answer; the other options either punish originality or give no useful feedback.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-739","question":"Given a candle, a box of drawing pins and matches, and asked to fix the candle to a soft board so it can burn without dripping on the floor, most Class 9 students cannot see that the empty pin box itself can be pinned up as a shelf. This block to creative problem-solving is called:","options":["Functional fixedness","Mental set built by reinforcement","Incubation","Divergent production"],"answer":0,"explanation":"Functional fixedness (Duncker’s candle problem) is the tendency to see an object only in its usual function, here a container for pins, which blocks a novel use.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-740","question":"Students solve five measuring problems with jars, each needing the same long sequence of steps. On the sixth problem, which can be solved in one simple step, most of them still use the long method. This illustrates:","options":["Functional fixedness about the jars","Insight into the problem's structure","Creativity in finding a new method","Mental set (Einstellung)"],"answer":3,"explanation":"A mental set is a habit of approaching problems in a way that worked before, which blinds the solver to simpler solutions (Luchins’s water-jar experiment). Functional fixedness concerns an object’s use, not a method.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-741","question":"Lewis Terman’s long-term study of children with very high IQs found that, on average, these children:","options":["Were physically weaker and socially awkward, just as the popular stereotype claimed","Were as healthy and well-adjusted as their peers or better, contradicting the stereotype","All went on to become famous inventors, scientists or artists by middle adulthood","Lost their intellectual advantage over other children completely by adolescence"],"answer":1,"explanation":"Terman’s ‘Genetic Studies of Genius’ found gifted children generally healthy and well adjusted, contrary to the image of the frail, odd genius, though not all achieved eminence.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-742","question":"Which of these statements about gifted children are correct? I. Gifted children do not need any special help because they will succeed anyway. II. A gifted child’s intellectual, emotional and physical development may be uneven. III. Gifted children are found in all social, economic and cultural groups. IV. A gifted child always excels in every school subject.","options":["I and IV only","I, II and III only","II and IV only","II and III only"],"answer":3,"explanation":"Giftedness occurs in every group and development can be asynchronous; gifted children can underachieve without support, and many are strong in some areas but not all, so I and IV are myths.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-743","question":"Before a unit on fractions, a teacher gives a pre-test and finds that Kabir already knows most of it. She lets him skip the practice he has already mastered and use that time for an independent project on ratios in Indian music. This strategy is called:","options":["Remedial teaching","Grade skipping","Curriculum compacting","Mastery learning for the whole class"],"answer":2,"explanation":"Curriculum compacting pre-assesses learners, removes what they have already mastered and replaces it with more challenging work; it is a form of differentiation, not grade skipping.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-744","question":"A three-year-old correctly follows the instruction ‘Give the red ball that is under the chair to Didi’, but in her own speech says only short phrases like ‘ball chair’. Chomsky’s distinction that best describes the gap between what she knows and what she produces is between:","options":["Langue and parole","Surface structure and transformation","Holophrase and telegraphic speech","Competence and performance"],"answer":3,"explanation":"Chomsky separated competence, the underlying knowledge of language, from performance, the actual use of it, which is limited by memory, attention and motor skills. Langue/parole is Saussure’s distinction.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-745","question":"A child knows from daily life that ‘things fall down’ but cannot explain why. In school, the teacher builds on this to introduce the idea of gravitational force. In Vygotsky’s terms, the teacher is linking:","options":["Spontaneous (everyday) concepts with scientific concepts","Egocentric speech with social speech used in class","Assimilation of the idea with accommodation of schemas","Fluid intelligence with crystallised intelligence"],"answer":0,"explanation":"Vygotsky distinguished spontaneous concepts formed in daily experience from systematic scientific concepts learned through instruction; good teaching connects the two, each strengthening the other.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-746","question":"Assertion (A): According to Vygotsky, a child’s private speech gradually turns into silent inner speech. Reason (R): Vygotsky held that higher mental functions appear first between people, on the social plane, and are later internalised by the individual.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Speech begins as social communication, is taken over as private speech to guide oneself, and is internalised as inner speech: a direct case of Vygotsky’s general law of internalisation from social to individual.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-747","question":"Linguist William Labov showed that African American Vernacular English, often dismissed as ‘broken’ speech, follows consistent grammatical rules. For Indian classrooms, the most direct implication of such work is that:","options":["Children who speak non-standard dialects have a cognitive deficit that must be corrected first","Only the standard language is precise enough to express logical and scientific thought","Home dialects are rule-governed, so the standard language should be added, not substituted","Dialect speakers should be placed in separate sections until their speech is standardised"],"answer":2,"explanation":"Labov’s work challenged deficit views of non-standard varieties; teachers should respect the logic of children’s home speech and build the standard school language on it (an additive approach).","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-748","question":"Which of the following is an example of GENDER rather than of biological sex?","options":["Girls generally reach puberty a year or two earlier than boys do","Only women can become pregnant and give birth to children","Boys' voices usually deepen noticeably during adolescence","A village belief that girls should stop playing cricket after Class 5"],"answer":3,"explanation":"Sex refers to biological differences; gender refers to socially constructed roles, norms and expectations, such as rules about which games girls may play.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-749","question":"Carol Gilligan criticised Kohlberg’s theory of moral development mainly because it:","options":["Ignored the role of cognitive development in moral reasoning, focusing only on feelings","Was built largely on males and ranked justice above care, so women seemed less developed","Placed too much importance on punishment and reward at every stage of development","Was based only on studies of children from India and other non-Western cultures"],"answer":1,"explanation":"Gilligan argued that Kohlberg’s scheme, derived from interviews with boys and men, privileged abstract justice and undervalued an ethic of care and relationships, producing a gender bias in scoring.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-750","question":"Match each idea with its theorist. P. Equilibration Q. Speech used aloud to guide one’s own actions R. Enactive representation S. Horizontal décalage; 1. Piaget 2. Vygotsky 3. Bruner","options":["P-1, Q-2, R-3, S-2","P-2, Q-1, R-3, S-1","P-1, Q-3, R-2, S-1","P-1, Q-2, R-3, S-1"],"answer":3,"explanation":"Equilibration and horizontal décalage are Piaget’s terms, private speech as self-guidance is Vygotsky’s, and enactive representation is Bruner’s.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-751","question":"A six-year-old fails a conservation-of-liquid task when tested alone, but succeeds when the teacher asks, ‘What if we pour it back?’ and ‘Did we add any water?’ Which comment would Vygotsky be most likely to make?","options":["She is simply not ready for conservation, since she failed the task when working alone","Conservation lies in her zone of proximal development and can be taught with such support","The questions spoiled the test, which should measure only what she can do independently","She is still in Bruner’s enactive mode, so she cannot yet handle a conservation task"],"answer":1,"explanation":"Success with help shows the ability is maturing, which is exactly what the ZPD captures. Judging only her solo failure, as in the first option, reflects a Piagetian readiness view.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-752","question":"Which of these theorists would agree that well-designed instruction can actually speed up a child’s cognitive development?","options":["Piaget and Vygotsky only","Piaget and Bruner only","Vygotsky and Bruner","Piaget, Vygotsky and Bruner equally"],"answer":2,"explanation":"Vygotsky held that learning leads development and Bruner that readiness can be nurtured by suitable teaching. Piaget was sceptical of attempts to accelerate stages through instruction.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-753","question":"Match the role of the teacher with the theorist. P. Creates situations that challenge children’s present ideas and lets them resolve the conflict themselves. Q. Works alongside the child as a more knowledgeable partner, giving support that is withdrawn over time. R. Organises material so that learners find its structure, revisiting it at higher levels. 1. Bruner 2. Piaget 3. Vygotsky","options":["P-2, Q-3, R-1","P-3, Q-2, R-1","P-2, Q-1, R-3","P-1, Q-3, R-2"],"answer":0,"explanation":"Piaget’s teacher provokes disequilibrium, Vygotsky’s teacher scaffolds within the ZPD, and Bruner’s teacher structures discovery and the spiral curriculum.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-754","question":"How many of these are widely accepted criticisms of Piaget’s theory? I. He underestimated what infants and young children can do when tasks are simplified. II. He gave too much weight to social and cultural influences. III. He claimed that cognitive development is driven mainly by reinforcement. IV. He placed too much emphasis on language as the driver of thought.","options":["Only one","Only two","Only three","All four of them"],"answer":0,"explanation":"Only I is a standard criticism. Piaget is criticised for giving too little weight to social and cultural influences, he treated language as secondary to thought, and reinforcement-driven development is a behaviourist idea, not his.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-755","question":"Which statement is true of BOTH Piaget and Vygotsky?","options":["Both proposed four universal stages that every child passes through","Both held that language is the main source of thought from birth onward","Both rejected any meaningful role for the teacher in learning","Both saw children as active in constructing their own understanding"],"answer":3,"explanation":"Both were constructivists. Only Piaget proposed universal stages, only Vygotsky made language the central tool of thought, and both gave teachers a role, though a different one.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-756","question":"A Class 2 child in a Jharkhand village school speaks Santhali at home. While explaining a maths idea, the teacher lets her think and talk in Santhali before moving to Hindi terms. Which theoretical idea most strongly supports this practice?","options":["Vygotsky’s view that language is the main tool through which children think","Piaget’s idea that object permanence must be secured before any concept is taught","Skinner’s idea that negative reinforcement strengthens use of the school language","Bruner’s claim that only symbolic thinking in the school language counts as learning"],"answer":0,"explanation":"For Vygotsky, the child’s language mediates her thinking, so working in the familiar language supports concept formation. NCF 2005 also advises using the home language as a resource.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-757","question":"Group 1: two equally able Class 5 students who disagree argue about why a steel spoon sinks but a steel bowl floats until they test it. Group 2: a skilled student guides a weaker one through the steps of the same test. Which theorists would most value each group respectively?","options":["Group 1: Vygotsky; Group 2: Piaget","Group 1: Bruner; Group 2: Skinner","Group 1: Vygotsky; Group 2: Bruner","Group 1: Piaget; Group 2: Vygotsky"],"answer":3,"explanation":"Piaget valued conflict between equals because it produces disequilibrium that children resolve themselves. Vygotsky valued collaboration with a more capable peer who works within the learner’s ZPD.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-758","question":"A Class 6 teacher in a Kendriya Vidyalaya first lets students test which objects float in water, then asks guiding questions as they record results in groups, and promises to return to the topic in Class 9 with the idea of density as mass divided by volume. Which part of her plan reflects Bruner most specifically?","options":["Letting students find out for themselves which objects float","Asking guiding questions during group work","Planning to revisit the topic later at a more formal level","Recording results in a table"],"answer":2,"explanation":"Returning to the same idea at a deeper, more symbolic level is Bruner’s spiral curriculum. Guided group questioning is more Vygotskian, and hands-on testing fits Piaget as well as Bruner.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-759","question":"Which two theorists gave language a major role in driving cognitive growth?","options":["Piaget and Bruner","Vygotsky and Bruner","Piaget and Vygotsky","Piaget alone"],"answer":1,"explanation":"Vygotsky made language the chief psychological tool, and Bruner linked the symbolic mode and cognitive growth closely to language. Piaget saw language as reflecting thought rather than driving it.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-760","question":"A Class 4 child insists that heavier objects always fall faster. Which teacher response is most Piagetian?","options":["Correct her at once and give her the scientific rule to memorise for the next test","Let her drop a heavy and a light ball of equal size together, then discuss what she saw","Ask a brighter classmate to explain the right answer to her during the lesson","Ignore the error, since she will understand it naturally once she reaches the next stage"],"answer":1,"explanation":"Piaget favoured experiences that clash with the child’s belief, creating disequilibrium that she resolves by accommodation. Telling the answer gives no conflict, and Piaget did not advise doing nothing.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-761","question":"Match each assessment approach with the theorist whose ideas it most reflects. P. Asking a child to explain her answers with open-ended follow-up questions (‘Why do you think so?’) Q. Measuring how much help a child needs to solve a problem R. Checking whether a child can show an idea with objects, with a picture and with symbols. 1. Bruner 2. Vygotsky 3. Piaget","options":["P-2, Q-3, R-1","P-3, Q-1, R-2","P-1, Q-2, R-3","P-3, Q-2, R-1"],"answer":3,"explanation":"Piaget’s clinical interview probes reasoning; dynamic assessment of assisted performance comes from Vygotsky’s ZPD; checking the three modes of representation follows Bruner.","difficulty":"hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-762","question":"Consider these statements. 1. Piaget saw development as a series of qualitatively different stages. 2. Vygotsky described a fixed sequence of universal stages that all cultures pass through. 3. Bruner’s modes of representation are not strictly age-bound stages and remain available in adulthood. Which is/are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Piaget’s stages are qualitative and invariant in order; Bruner’s modes coexist. Vygotsky did not propose universal fixed stages; he stressed cultural and social variation.","difficulty":"very-hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-763","question":"Assertion (A): Piaget was doubtful about trying to speed up children’s passage through the stages by direct training. Reason (R): For Piaget, logical operations must be built through the child’s own activity and equilibration, not simply transmitted by an adult.","options":["Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"Piaget called attempts to accelerate development ‘the American question’ and doubted their value, because operations are self-constructed. Telling or drilling cannot replace that construction.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-764","question":"Which of these is NOT an educational implication of Piaget’s theory?","options":["Create cognitive conflict by showing results that clash with children’s predictions","Let peers debate their differing answers, as disagreement helps children decentre","Present the same content in the same way to all, so every child gets equal input","Avoid hurrying children through stages with intensive drill on advanced tasks"],"answer":2,"explanation":"Piaget stressed matching tasks to each child’s level of thinking, so identical teaching for all is not Piagetian. Peer debate may look Vygotskian, but Piaget valued peer disagreement for decentring, and he warned against accelerating stages.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-765","question":"Which of these is NOT consistent with Vygotsky’s ideas?","options":["Teachers should avoid helping children so that they discover everything alone","Peers as well as adults can act as the more knowledgeable other for a child","Support should be reduced step by step as the child becomes more competent","Language and dialogue with others help to shape the way children think"],"answer":0,"explanation":"Vygotsky saw help from others as essential to development; withholding all assistance contradicts his theory. The other three options follow directly from the ZPD and his view of language.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-766","question":"A Class 3 teacher scolds children for counting on their fingers during subtraction. Drawing on Vygotsky and Bruner, the best advice for her is to:","options":["Continue the ban, so that children are pushed to think abstractly from the start","Allow finger counting as a support and encourage mental strategies as confidence grows","Allow finger counting only for the weakest children and shame the rest into stopping","Replace subtraction with rote learning of tables until children reach Class 5"],"answer":1,"explanation":"Fingers are an external, enactive aid that children later internalise; removing them too early takes away a support. The goal is gradual withdrawal, not a ban or shaming.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-767","question":"‘What a child can do today with the help of others, she will be able to do by herself tomorrow.’ This idea is the basis of:","options":["Piaget’s concept of equilibration and self-regulation","Bruner’s spiral curriculum","Kohlberg’s stages of moral reasoning","Vygotsky’s zone of proximal development"],"answer":3,"explanation":"Vygotsky argued that assisted performance foreshadows independent performance; the space between the two levels is the ZPD.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-768","question":"In a Class 9 science practical, many students change two factors at once when testing what affects the rate of evaporation. What is the most suitable response from a teacher who knows both Piaget’s and Vygotsky’s ideas?","options":["Conclude that the students are still pre-operational and should not do experiments yet","Assume that all 14-year-olds should already reason this way and give zero marks","Model a one-variable fair test, guide them through one, then let them design their own","Drop experiments and teach only from the textbook, since practicals confuse them"],"answer":2,"explanation":"Research shows formal reasoning such as controlling variables is not automatic in adolescence; modelling and guided practice scaffold it. The students are not pre-operational, and marking them down teaches nothing.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-769","question":"Assertion (A): A teacher who follows Piaget and one who follows Vygotsky may both organise group work. Reason (R): Piaget saw peers as a source of cognitive conflict, while Vygotsky saw them as possible more knowledgeable others.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both theorists value peer interaction, but for different reasons. R gives those reasons and so explains why both kinds of teacher might use group work.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-770","question":"Which theory most strongly suggests that a child’s level of thinking can be broadly predicted from her age?","options":["Vygotsky’s sociocultural theory","Piaget’s stage theory","Bruner’s theory of instruction","None, as all three reject any link with age"],"answer":1,"explanation":"Piaget linked his stages to approximate age ranges, although ages vary. Vygotsky focused on social context and Bruner’s modes are not strict age-stages.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-771","question":"A teacher notices that a Class 1 child can sort buttons by colour but not by colour and size together, while a Class 4 child easily makes a 2 × 2 table sorting them by both. The ability the older child shows is called multiple classification. In Piaget’s theory it depends mainly on:","options":["Decentration, which lets a child attend to two attributes at once","Object permanence, which lets a child keep track of hidden objects","Private speech, which lets a child guide her own sorting aloud","Iconic representation alone, which lets a child picture the buttons"],"answer":0,"explanation":"Multiple classification needs the child to attend to two dimensions together, which becomes possible with decentration in the concrete operational stage. Object permanence and private speech are unrelated.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-772","question":"How many of these statements correctly compare the three theorists? I. Piaget: the child as a lone scientist; Vygotsky: the child as an apprentice in a culture. II. Bruner: the teacher should translate ideas into the learner’s way of viewing things. III. Vygotsky: development is the same in every culture, since it is driven by maturation. IV. Piaget: language reflects thought more than it shapes it.","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"I, II and IV are accurate summaries. III is wrong: Vygotsky stressed cultural variation and social interaction rather than maturation alone.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-773","question":"Before a lesson on fractions, a teacher asks the class, ‘Who can share 3 rotis equally among 4 friends?’ and lets them try with paper rotis. Which reason would BOTH a Piagetian and a Brunerian teacher give for this activity?","options":["It provides reinforcement for correct answers, so the right responses get strengthened","It removes the need for later symbolic work, since the concrete task is enough","It lets the teacher quickly identify the most able children in the class for grouping","It gives children active, concrete experience on which understanding can be built"],"answer":3,"explanation":"Both Piaget and Bruner favour active, concrete experience as the basis for understanding, with Bruner adding a planned move to iconic and symbolic forms. Reinforcement is a behaviourist reason.","difficulty":"moderate","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-774","question":"In which situation is a teacher wrongly applying Piaget’s ideas?","options":["She gives Class 2 children counters to explore addition before writing sums","She gives a struggling Class 4 child no hints, saying he must reach the next stage alone","She asks a child to predict what will happen and then test the prediction","She plans hypothetical ‘what if’ debates for Class 10 to stretch abstract reasoning"],"answer":1,"explanation":"Piaget did not say teachers should withhold all help; he advised providing suitable experiences and challenges. The other options are sensible applications of his theory.","difficulty":"hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-775","question":"A two-and-a-half-year-old insists on putting on his own chappals and pouring his own water. His grandmother always does it for him and scolds him loudly whenever he spills. According to Erikson, the child is at risk of developing:","options":["Basic mistrust","Guilt","Shame and doubt","A sense of inferiority"],"answer":2,"explanation":"Toddlers face autonomy versus shame and doubt; overprotection and ridicule of failed attempts breed doubt in their own abilities. Guilt belongs to the next stage (initiative, about 3–6 years).","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-776","question":"A 48-year-old teacher spends her weekends running a free library for village children and mentoring newly joined teachers. Erikson would see this as a healthy resolution of:","options":["Integrity versus despair","Intimacy versus isolation","Industry versus inferiority","Generativity versus stagnation"],"answer":3,"explanation":"Middle adulthood’s task is generativity: guiding and contributing to the next generation. Integrity versus despair is the late-life review of one’s life.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-777","question":"A retired headmaster says, ‘I made mistakes, but on the whole my life was worthwhile, and I am at peace with it.’ Another says, ‘My life was wasted, and now there is no time left to fix anything.’ The two represent the poles of Erikson’s stage of:","options":["Integrity versus despair","Generativity versus stagnation","Identity versus role confusion","Intimacy versus isolation"],"answer":0,"explanation":"In late adulthood people review their lives; acceptance gives integrity (and wisdom), regret and bitterness give despair.","difficulty":"moderate","source":"KVS PRT · NVS"},
  {"id":"cdp-child-development-778","question":"Match Erikson’s stages with the virtue (ego strength) each gives when favourably resolved: 1. Trust vs mistrust 2. Autonomy vs shame and doubt 3. Initiative vs guilt 4. Industry vs inferiority; a. Competence b. Will c. Hope d. Purpose","options":["1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-b, 2-c, 3-d, 4-a","1-c, 2-b, 3-a, 4-d"],"answer":0,"explanation":"Erikson’s virtues: trust gives hope, autonomy gives will, initiative gives purpose, industry gives competence.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-779","question":"Which statement correctly describes how Erikson’s theory differs from Freud’s?","options":["Erikson stressed the id and sexual drives even more strongly than Freud had","Erikson stressed society’s role in ego growth and extended the stages across the lifespan","Erikson ended development at puberty, while Freud extended his stages into old age","Erikson rejected developmental stages altogether in favour of continuous growth"],"answer":1,"explanation":"Erikson kept a stage approach but shifted the focus from psychosexual drives to psychosocial tasks shaped by society, and added stages through adulthood; Freud’s stages end with the genital stage at puberty.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-780","question":"Erikson’s ‘epigenetic principle’ implies that:","options":["Personality is fixed by genes, so the stages unfold the same way whatever the experience","Each person creates his or her own order of stages according to personal needs","Each strength has its own time of ascendancy in a fixed sequence, building on earlier stages","The stages can be completed in any order, depending on what the culture demands first"],"answer":2,"explanation":"Borrowed from embryology, the principle means each psychosocial strength has a critical time of ascendancy within a fixed sequence, with later stages built on earlier resolutions; it does not mean genetic determinism.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-781","question":"Kartik, in Class 12, says firmly, ‘I will be a chartered accountant like my father; it was decided long ago.’ He has never considered any other option or asked himself what he enjoys. In Marcia’s extension of Erikson, his identity status is:","options":["Identity achievement","Moratorium","Identity diffusion","Foreclosure"],"answer":3,"explanation":"Foreclosure is commitment without exploration, often by adopting parents’ choices. Achievement requires commitment after a period of exploration.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-782","question":"Simran, in Class 11, is attending career talks, doing a summer internship at a clinic and talking to designers and journalists, but has not yet decided what she wants to be. Her identity status, in Marcia’s terms, is:","options":["Foreclosure","Moratorium","Identity diffusion","Identity achievement"],"answer":1,"explanation":"Moratorium means active exploration without commitment yet; it is a healthy phase, not a disorder, and usually leads to identity achievement.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-783","question":"A Class 10 boy says, ‘I don’t know what I want and I don’t care; whatever happens will happen.’ He has not explored any options and has no plans. This identity status is:","options":["Identity diffusion","Moratorium","Foreclosure","Negative identity"],"answer":0,"explanation":"Diffusion is the absence of both exploration and commitment. Moratorium involves active exploration; foreclosure involves commitment without exploration.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-784","question":"Match the students with Marcia’s identity statuses. P: Explored science, arts and sports, then chose to become a teacher and is committed to it. Q: Became a doctor because the family decided, without exploring. R: Is still trying out options, undecided. S: Neither explores nor cares to decide.","options":["P-moratorium, Q-foreclosure, R-achievement, S-diffusion","P-achievement, Q-diffusion, R-moratorium, S-foreclosure","P-achievement, Q-foreclosure, R-moratorium, S-diffusion","P-foreclosure, Q-achievement, R-diffusion, S-moratorium"],"answer":2,"explanation":"Achievement is exploration then commitment; foreclosure is commitment without exploration; moratorium is exploration without commitment; diffusion is neither.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-785","question":"A Class 4 child, after poor marks in two tests, says, ‘I am useless at everything.’ Which response by the teacher best fits Erikson’s view of this stage?","options":["Tell him to work harder because his classmates are doing better, to spur him on","Give him tasks he can succeed at, point out real progress, and avoid comparing him","Excuse him from tests for a while until he starts feeling better about himself","Tell him that marks do not matter at all at his age, so he need not worry"],"answer":1,"explanation":"Industry versus inferiority is resolved through experiences of real competence and recognition of effort; comparison deepens inferiority, while excusing him or dismissing marks gives no experience of mastery.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-786","question":"In one pre-school, children plan their own activity corners, take on roles in pretend play and try new ideas, while mess is calmly cleaned up together. In another, children who start their own activities are scolded for ‘creating nuisance’. In Erikson’s terms, the second pre-school risks fostering:","options":["Mistrust","Inferiority","Role confusion","Guilt"],"answer":3,"explanation":"Children of about 3–6 face initiative versus guilt; punishing self-started activity makes them feel guilty about their own plans and aims. Inferiority is the risk of the next, school-age stage.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-787","question":"According to Erikson, what most determines whether an infant develops basic trust?","options":["The quantity of food the infant receives each day","The infant’s inborn intelligence","The consistency, warmth and predictability of the care given","The number of toys and stimulating objects provided in the first year"],"answer":2,"explanation":"Trust grows from the quality of care: reliable, responsive caregiving that makes the world feel predictable. Erikson stressed quality of the relationship over quantity of food or stimulation.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-788","question":"A Class 8 student, neglected in early childhood, finds it hard to trust teachers and assumes they mean her harm. Which statement is most consistent with Erikson’s theory?","options":["Her personality was fixed in infancy, so school can do little to change it now","Crises are never settled for good; warm, reliable adults now can help her rework trust","She is facing the trust versus mistrust stage again simply because she is an adolescent","Mistrust is always harmful, so the healthy goal is a child with no mistrust at all"],"answer":1,"explanation":"Erikson saw outcomes as a balance that can be revisited; later positive experiences can strengthen trust. Some mistrust is healthy; the goal is a favourable ratio, not its total absence.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-789","question":"Which school practice best supports the main psychosocial task Erikson identified for secondary students?","options":["Fixing each student’s stream in Class 8 on the basis of marks alone, to avoid confusion","Offering clubs, projects and community roles so students can explore who they are","Discouraging students from discussing their values, so they can focus on exams","Insisting that all students follow the same career path for discipline’s sake"],"answer":1,"explanation":"Adolescents face identity versus role confusion; varied, safe opportunities to explore roles and values help them form a coherent identity, whereas early fixing forces foreclosure.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-790","question":"Erikson used the term ‘psychosocial moratorium’ to describe:","options":["A permanent failure to form an identity, leaving the youth without direction","A punishment given to adolescents who break social rules, suspending privileges","A stage in early childhood when the child withdraws from others for a time","A period society allows youth to explore roles before adult commitments"],"answer":3,"explanation":"The moratorium is a socially sanctioned delay of adult duties, such as the years of higher education, in which youth can experiment with roles. Permanent failure would be role confusion.","difficulty":"very-hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-791","question":"Assertion (A): Erikson’s theory is called a psychosocial theory. Reason (R): He held that the crisis at each stage arises from the meeting of the individual’s maturing needs and abilities with the demands of society.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Each crisis is psychological and social at once: the growing person meets new social demands, which is exactly why the theory is psychosocial.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-792","question":"Assertion (A): Erikson believed that personality development is complete by the end of adolescence. Reason (R): Erikson proposed eight stages spanning the entire lifespan.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Erikson’s stages continue into young, middle and late adulthood, so development does not end in adolescence; A is false and R is true.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-793","question":"For a typical child in Classes 3 to 5, which stage of Erikson coincides with which stage of Piaget?","options":["Initiative versus guilt with the pre-operational stage","Industry versus inferiority with the concrete operational stage","Identity versus role confusion with the formal operational stage","Autonomy versus shame with the concrete operational stage"],"answer":1,"explanation":"Children of about 8–11 are in Erikson’s industry stage and Piaget’s concrete operational stage; both point to hands-on, achievable tasks that build competence.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-794","question":"A 24-year-old B.Ed trainee keeps everyone at a distance and avoids close friendships, fearing that closeness will mean losing himself. Erikson would locate his difficulty in the stage of:","options":["Identity versus role confusion","Generativity versus stagnation","Intimacy versus isolation","Trust versus mistrust"],"answer":2,"explanation":"Young adults face intimacy versus isolation; Erikson held that people with a shaky identity fear that intimacy will swallow it, so they withdraw into isolation.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-795","question":"A Class 9 group mocks and excludes students who dress, speak or think differently from them. How did Erikson explain such adolescent clannishness?","options":["As a sign of a fixed antisocial personality that will persist into adulthood","As a carry-over of the autonomy versus shame crisis left unresolved in toddlerhood","As purely the result of imitating the violence and bullying they see in the media","As a temporary defence against identity confusion, borrowing a self from the group"],"answer":3,"explanation":"Erikson saw adolescent intolerance and over-identification with cliques as a defence against identity confusion; teachers can widen belonging and challenge exclusion without labelling the students as antisocial.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-796","question":"Which of these statements about Erikson’s theory are correct? I. Each stage poses a crisis whose favourable resolution supports healthy development. II. Favourable resolution means the negative pole, e.g. mistrust, is completely eliminated. III. The stages span the whole life. IV. Social relationships are central at every stage.","options":["I, III and IV only","I and II only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"Erikson saw healthy outcomes as a favourable balance; some mistrust or doubt is adaptive, so II is false. The others are core features of the theory.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-797","question":"Which practice in a primary school is most likely to push children toward the negative pole of Erikson’s fourth stage?","options":["Grouping children for cooperative projects in which every member has a role","Displaying class rank lists publicly and calling out the lowest scorers","Praising specific efforts and strategies rather than marks alone","Giving tasks of graded difficulty so that all children can succeed"],"answer":1,"explanation":"The fourth stage is industry versus inferiority; public ranking and shaming make low achievers feel incompetent. The other practices build a sense of competence.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-798","question":"Having explored several sets of beliefs, a Class 12 student settles on her own values and stays loyal to them and to her friends even under pressure. Which virtue did Erikson link to a favourable resolution of the adolescent crisis?","options":["Hope","Will","Competence","Fidelity"],"answer":3,"explanation":"Resolving identity versus role confusion yields fidelity: the ability to sustain loyalties freely pledged. Hope comes from trust, will from autonomy, competence from industry.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-799","question":"A Class 8 boy who is always noticed only when he misbehaves begins to proudly call himself ‘the class troublemaker’ and lives up to the label. Erikson described this as:","options":["A negative identity, built from roles presented to him as undesirable","Identity achievement, since he now has a clear and confident sense of self","Industry, since he has found something he is good at and gets noticed for","Initiative, since he takes charge of situations and acts on his own plans"],"answer":0,"explanation":"Erikson noted that youth denied a positive, recognised role may embrace a negative identity built from the very roles adults warn against; giving him valued roles is the remedy. It is not achievement, which requires exploration and freely chosen commitment.","difficulty":"very-hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-800","question":"During noisy group work, Class 5 student Irfan is fully absorbed in his own group's chart, yet he immediately turns when someone at the far end of the room says his name. What does this show about attention?","options":["Irfan was not really attending to his group's work, only pretending to","Unattended input is still monitored at some level for personally important cues","Attention works mainly through sight, so hearing his name was mere chance","Divided attention is equally effective for all tasks, so he heard everything"],"answer":1,"explanation":"This is the cocktail-party effect: while we focus on one stream, unattended input is still processed at some level, so highly relevant cues like one's name can capture attention.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-801","question":"Which of the following is a subjective (internal) determinant of attention rather than an objective one?","options":["A child's keen interest in cricket","A sudden loud sound in the corridor","A brightly coloured moving picture","A sharp contrast between a red word and black text"],"answer":0,"explanation":"Objective determinants lie in the stimulus: intensity, movement, novelty, contrast, change. Subjective determinants lie in the learner: interests, needs, motives, mental set.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-802","question":"A Class 1 teacher finds that her children grow restless during a 35-minute continuous story reading. Which response best fits what is known about young children's attention?","options":["Insist on silence so the children learn to attend for the full 35 minutes","Shorten the period to 5 minutes and cancel the story reading altogether","Split it into short segments with changes such as acting, questioning and drawing","Read faster so that the story ends before the children grow restless"],"answer":2,"explanation":"Young children's span of sustained attention is short; planned variation of activity renews attention while keeping the learning goal intact.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-803","question":"Class 6 students are asked to copy long notes from the board while the teacher simultaneously explains a new and difficult concept. Most remember little of the explanation. The most accurate explanation is that:","options":["The students are simply not motivated, so they chose to ignore the explanation","Copying is a purely automatic skill, so it cannot interfere with listening","Listening to explanations is not possible for children under twelve","Both tasks need controlled attention, so dividing it lowers performance on each"],"answer":3,"explanation":"Divided attention works only when at least one task is highly automatic. Copying unfamiliar notes and processing new ideas both draw on limited attentional capacity.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-804","question":"Children stop noticing the steady hum of the ceiling fan, and in the same way they drift off when a teacher speaks in a flat monotone for a long time. When she suddenly lowers her voice to a whisper, all heads turn. This is explained by:","options":["Habituation to unchanging stimuli, and recapture of attention by change","Proactive interference, where earlier words block attention to new ones","Classical conditioning of the voice as a signal to stop listening","Learned helplessness, as children give up trying to follow the talk"],"answer":0,"explanation":"Attention habituates to constant stimuli; change, contrast and novelty are powerful objective determinants that recapture it.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-805","question":"Before a reading passage on the Chipko movement, a teacher says, ‘As you read, find three reasons why villagers hugged the trees.’ This instruction improves learning mainly because it:","options":["Rewards the students in advance, so that they read more willingly","Creates a mental set that directs attention to relevant information","Reduces the length of the passage that students actually have to read","Tests long-term memory directly by asking for facts from earlier lessons"],"answer":1,"explanation":"A purpose or mental set given in advance is a subjective determinant of attention; it guides readers to select and process the information that matters.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-806","question":"Class 3 children who loved drawing in free time were promised and given a prize every time they drew for a class contest. Weeks after the contest ended, they spent much less free time drawing than children who had never been given prizes. This is best explained by:","options":["Spontaneous recovery of their earlier, weaker interest in drawing","Vicarious reinforcement from watching other children win prizes","Overjustification, where expected rewards undermine intrinsic interest","Negative reinforcement, since drawing became linked with contest stress"],"answer":2,"explanation":"When an expected, tangible reward is given for an activity already enjoyed, children may come to see the reward as the reason for doing it, so interest drops once rewards stop.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-807","question":"Which form of feedback is most likely to support a Class 6 child's intrinsic motivation, according to self-determination research?","options":["‘Good, you did exactly what I told you to do in the instructions.’","‘You must keep this up, or you will lose your star on the chart.’","‘You are the best in the class, far better than everyone else.’","‘The way you used dark colours for the storm really shows the mood.’"],"answer":3,"explanation":"Specific, informational feedback signals competence without control. Controlling or comparative praise shifts focus to pleasing others or to rank, which tends to lower intrinsic motivation.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-808","question":"A Class 8 teacher allows students to choose the topic of their science project from a list, lets them decide how to present it, and explains why the project matters. According to Deci and Ryan's self-determination theory, she is mainly supporting the need for:","options":["Autonomy","Safety","Physiological comfort","Competition"],"answer":0,"explanation":"Self-determination theory names three basic psychological needs: autonomy, competence and relatedness. Meaningful choice and a rationale support autonomy.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-809","question":"Under which condition are tangible rewards LEAST likely to harm intrinsic motivation?","options":["When they are promised in advance for an activity that children already love","When they help children start a task that holds little initial interest for them","When they are given only if a child beats all of her classmates in the task","When offered just for taking part in an enjoyable activity, regardless of quality"],"answer":1,"explanation":"The undermining effect is strongest for expected rewards on already interesting tasks. Where initial interest is low, rewards can help children begin and discover competence or interest.","difficulty":"very-hard","source":"CTET Paper 2 · NVS TGT"},
  {"id":"cdp-child-development-810","question":"Gurpreet is bullied every day on the way to school and during break. He cannot concentrate on lessons and often says he has a stomach ache to avoid school. In Maslow's hierarchy, which need is most clearly unmet?","options":["Self-actualisation","Esteem","Safety","Aesthetic"],"answer":2,"explanation":"Fear of harm signals an unmet safety need. Maslow argued that lower deficiency needs must be reasonably met before higher needs such as learning-related esteem can motivate behaviour.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-811","question":"Assertion (A): A child who feels unloved at home may misbehave in class to gain attention from the teacher and classmates. Reason (R): In Maslow's view, unmet belongingness and love needs dominate behaviour until they are reasonably satisfied.","options":["A is true but R is false","A is false but R is true","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Maslow held that unmet lower needs drive behaviour; a child starved of affection seeks it, even through disruption. R explains A.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-812","question":"Which statement about Maslow's hierarchy is accurate?","options":["Self-actualisation is a growth need; the four lower needs are deficiency needs","Esteem needs come before safety needs, since respect matters most to children","All lower needs must be fully satisfied before any higher need can appear","Maslow placed knowledge and understanding at the very bottom of the hierarchy"],"answer":0,"explanation":"Maslow divided needs into deficiency needs (the lower four) and growth needs (self-actualisation). Lower needs must be reasonably, not completely, met before higher ones become dominant.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-813","question":"Riya failed her science test. Which of her explanations is internal, unstable and controllable in Weiner's attribution theory?","options":["‘I am just not intelligent enough for science.’","‘I did not revise the chapter properly.’","‘The paper was set too hard.’","‘I was unlucky with the questions that came.’"],"answer":1,"explanation":"Lack of effort is internal (about her), unstable (can change next time) and controllable. Ability is internal but stable and uncontrollable; task difficulty and luck are external.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-814","question":"After topping a test, Kunal tells friends, ‘I just got lucky with the questions.’ Why might a teacher worry about this attribution even though he succeeded?","options":["Luck is internal and stable, so he will become overconfident about the next test","Luck is controllable, so he will feel free to stop working before the next test","Luck is external and unstable, giving little pride or reason to expect success again","Attributing success to luck always raises self-efficacy, so he may get careless"],"answer":2,"explanation":"Weiner noted that external, unstable attributions for success give little pride and no basis for expecting success again, so they do not build motivation.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-815","question":"After Mehul fails an easy quiz, his teacher speaks to him with obvious pity and immediately offers help he did not ask for, while she reacts to other failing students with mild annoyance. According to attribution research, what message might Mehul draw?","options":["That he failed only because of bad luck","That the teacher thinks he did not try hard enough","That the quiz was unfair","That the teacher believes he lacks ability"],"answer":3,"explanation":"Research by Sandra Graham showed that sympathy and unsolicited help after failure on an easy task can signal that the teacher attributes failure to low ability, while mild anger signals that more effort was expected.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-816","question":"Bhavna has failed maths tests repeatedly despite studying; now she does not even attempt problems, saying, ‘Whatever I do, I'll fail.’ This is best described as:","options":["Learned helplessness","Overjustification","Spontaneous recovery","Mastery goal orientation"],"answer":0,"explanation":"Seligman's learned helplessness arises when a person comes to believe outcomes do not depend on his actions, leading to passivity even when success is possible.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-817","question":"In a ring-toss game, children may stand at any distance from the peg. According to Atkinson's theory of achievement motivation, a child high in need for achievement and low in fear of failure is most likely to:","options":["Stand right next to the peg, to be sure of success on every throw","Stand at a moderate distance where success is possible but uncertain","Stand very far away, where success is nearly impossible but impressive","Refuse to play at all, to avoid any chance of looking foolish"],"answer":1,"explanation":"Success-oriented people prefer tasks of moderate difficulty, where success depends on skill and brings satisfaction. Those dominated by fear of failure tend to pick very easy or very hard tasks.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-child-development-818","question":"A teacher wants to encourage a growth mindset in Class 7 students. Which praise suits this aim best?","options":["‘You are so clever, you didn't even have to try to get these right.’","‘You are a natural at maths, just like your elder brother.’","‘You kept trying new methods until one worked; that's how you solved it.’","‘You got the highest marks in the class, so you must be gifted.’"],"answer":2,"explanation":"Dweck found that praising process (effort, strategy) fosters the belief that ability grows, while praising fixed traits makes children avoid challenges to protect their image.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-819","question":"Two Class 9 students study a history chapter. Ankit keeps asking, ‘Will this come in the exam?’ and studies only those parts. Seema keeps asking why events happened and reads extra stories. Which statement best describes them?","options":["Both have mastery goals, since both are working hard on the chapter","Ankit is intrinsically motivated and Seema is extrinsically motivated","Seema has a performance-avoidance goal, since she avoids exam-only study","Ankit shows a performance goal and Seema a mastery goal"],"answer":3,"explanation":"Mastery (learning) goals aim at understanding and improvement; performance goals aim at grades or looking competent. Mastery goals are linked with deeper learning strategies.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-820","question":"According to the Yerkes–Dodson law, which situation is most likely to give the best performance on a difficult, unfamiliar reasoning test?","options":["A moderate-to-low level of arousal, since the optimum is lower for complex tasks","Very high arousal, since pressure always pushes people to their best performance","No arousal at all, since any level of arousal disturbs careful thinking","High arousal, since difficult tasks need the most stress to stay focused"],"answer":0,"explanation":"Performance rises with arousal up to an optimum and then falls (inverted U). For complex tasks the optimum lies at a lower level of arousal than for simple tasks.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-821","question":"Ravi believes he can easily do well in drawing but sees no point in it, while Sohan values maths highly but is sure he will fail whatever he does. According to expectancy–value theory, which prediction is correct?","options":["Ravi will be highly motivated in drawing, because his expectancy of success is high","Both may show low motivation, since motivation needs both expectancy and value","Sohan will be highly motivated in maths, because he values the subject so highly","Expectancy and value do not affect motivation; interest in the teacher does"],"answer":1,"explanation":"In expectancy–value theory motivation is roughly expectancy multiplied by value; if either is near zero, motivation is low, so both students may disengage.","difficulty":"hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-822","question":"A Class 4 teacher runs a weekly spelling contest in which only the top three are rewarded. After a few weeks, the weaker spellers stop trying. What is the best change?","options":["Increase the prizes for the top three so that everyone tries harder to win","Remove spelling from the timetable, since contests only discourage children","Let each child set and try to beat a personal target, recognising improvement","Publicly display every child's rank so the weaker ones feel pushed to improve"],"answer":2,"explanation":"Competition with fixed winners discourages those who never win. Self-referenced goals let every child experience success through improvement and keep effort linked to outcomes.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-823","question":"Match each need in Maslow's hierarchy with a school practice that addresses it. P. Physiological  Q. Safety  R. Belongingness  S. Esteem. 1. A strict anti-bullying policy 2. The mid-day meal scheme 3. Displaying each child's work and recognising progress 4. Buddy groups so that new children feel part of the class","options":["P-1, Q-2, R-4, S-3","P-2, Q-1, R-3, S-4","P-2, Q-4, R-1, S-3","P-2, Q-1, R-4, S-3"],"answer":3,"explanation":"Food meets physiological needs, protection from bullying meets safety, buddy groups meet belonging, and recognition of work meets esteem needs.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-824","question":"Moumita joined a Pune school in Class 6 after her family moved from Assam. The work suits her level and she has choices in projects, yet her interest drops because she has no friends and feels the teacher hardly knows her. Which basic need from self-determination theory is most clearly unmet?","options":["Relatedness","Competence","Autonomy","Physiological"],"answer":0,"explanation":"Self-determination theory lists autonomy, competence and relatedness. The tasks fit her ability (competence) and she has choice (autonomy); what is missing is a sense of belonging and connection.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-825","question":"Rahul, a Class 4 child with autism, has a support aide who sits beside him all day, answers for him and completes his tasks so that he ‘keeps up’. Over months, his classmates hardly speak to him. What is the main concern?","options":["Rahul should be moved with his aide to a resource room for focused one-to-one help","The aide’s constant help breeds dependence and isolation, so it should be faded","Classmates should be given a talk on autism so that they accept Rahul better","The aide should be trained in autism-specific methods so her help is more expert"],"answer":1,"explanation":"The barrier is the amount and placement of adult support, which does the work and blocks peer contact, so it must be faded. An autism-awareness talk is well meant but leaves the aide still standing between Rahul and his classmates, and a resource room would deepen his isolation.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-826","question":"Match the support with the learner it mainly helps. 1. Screen-reading software 2. FM (radio) listening system 3. Picture communication board 4. Pencil grip and slanted writing board; a. A child with hearing impairment b. A child who is blind c. A child with fine-motor writing difficulty d. A non-speaking child with autism or cerebral palsy","options":["1-b, 2-a, 3-d, 4-c","1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-d, 2-a, 3-b, 4-c"],"answer":0,"explanation":"Screen readers convert text to speech for blind users, FM systems carry the teacher's voice directly to hearing aids, picture boards give a non-speaking child a way to communicate, and grips and slant boards ease handwriting.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-827","question":"Which of these statements reflect an inclusive view of disability? I. Attitudes of teachers and peers can be a bigger barrier than physical ones. II. A child should be placed in a regular class only after she becomes ‘ready’ to cope with it unaided. III. Barriers to learning lie in the school environment as much as in the child.","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":2,"explanation":"Inclusion sees barriers in attitudes, practices and the environment, which the school must remove; making entry conditional on the child becoming ‘ready’ is the old integration model.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-828","question":"A Class 7 wheelchair user cannot reach the school library on the first floor. A committee member says, ‘The problem is her legs; nothing can be done.’ Which statement correctly analyses this?","options":["This is the social model; it rightly locates the problem in the child’s body","This is the medical model; the social model would remove the barrier, e.g. with a ramp","This is the social model; it suggests the child should be taught at home instead","This is the medical model, which is the approach the RPwD Act itself requires"],"answer":1,"explanation":"The medical model sees disability as a defect in the person, while the social model sees disability arising from barriers in the environment; the rights-based law follows the social view.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-829","question":"Which statement about dyslexia is correct?","options":["It is caused mainly by low intelligence, so it shows up across all subjects","It means the child literally sees letters backwards, so b/d reversal confirms it","It is usually a result of laziness and too little reading practice at home","A phonological difficulty that hampers decoding and spelling despite normal intelligence"],"answer":3,"explanation":"Dyslexia is chiefly a phonological processing difficulty unrelated to intelligence; letter reversals are common in all beginning writers and do not by themselves indicate dyslexia.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-830","question":"Simran, in Class 3, has been found to have dyscalculia. Which approach is most suitable for teaching her place value?","options":["Moving from concrete bundles of sticks, to pictures, and only then to symbols","Making her recite multiplication tables loudly every morning until they stick","Giving her daily timed drills of written sums to build speed and confidence","Excusing her from mathematics so that she can focus on languages instead"],"answer":0,"explanation":"The concrete–representational–abstract sequence builds number meaning step by step, which is what children with dyscalculia lack; rote recitation and speed drills skip understanding and raise anxiety.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-831","question":"Which practice is LEAST helpful for a blind student who has just joined a Class 5 classroom?","options":["Taking him round the room so that he learns where the door, his desk and the shelves are","Announcing who is entering or leaving and speaking his name when addressing him","Rearranging desks and cupboards often for different activities without telling him","Keeping walkways clear and doors fully open or fully shut"],"answer":2,"explanation":"A blind child builds a mental map of the room for independent movement; unannounced rearrangement destroys that map and creates hazards, while orientation and clear walkways support it.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-832","question":"A teacher of a deaf Class 2 child uses speech, Indian Sign Language, gestures, lip-reading, pictures and written words together, choosing whatever works best in each situation. This approach is known as:","options":["The oral-only approach","Total communication","The auditory-verbal-only approach","Finger-spelling only"],"answer":1,"explanation":"Total communication combines all available modes, signed, spoken, written and visual, to give the child full access; oral-only and auditory-verbal approaches rely on speech and hearing alone.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-833","question":"Asked to list uses of a brick, a Class 6 student writes 20 answers, but every one is a building use: a wall, a step, a pillar, a shelf base and so on. In terms of divergent thinking, her response shows:","options":["High originality and high flexibility","Low fluency and high flexibility","High elaboration and high originality","High fluency but low flexibility"],"answer":3,"explanation":"Fluency is the number of ideas, which is high; flexibility is the number of different categories, which is low because all answers fall in one category of use.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-834","question":"Mehak, a gifted Class 4 student, tears up her drawing or work sheet whenever she finds even a tiny error and refuses to start tasks she may not do perfectly. What is the most appropriate teacher response?","options":["Praising her as ‘the cleverest’ in class so that her confidence rises","Giving her only easy tasks so that she never has to face a mistake","Normalising mistakes and praising effort and strategy rather than flawless results","Asking her parents to be stricter so that she stops tearing up her work"],"answer":2,"explanation":"Perfectionism is common among gifted children; normalising mistakes and valuing process helps, whereas ‘cleverest’ praise and easy work reinforce the fear of failing.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-835","question":"Gifted children from rural and poor families are often missed when schools identify giftedness. Which practice best reduces this?","options":["Using a single written test in English, the same for every child in the district","Identifying only those children whose parents put in a formal request","Selecting the children with the highest marks in the annual examination","Using varied sources such as observation, portfolios and non-verbal tasks"],"answer":3,"explanation":"Tests that depend on language, exposure or parental awareness favour advantaged children; multiple measures, including non-verbal tasks and observation, find ability wherever it lies.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-836","question":"Varsha, a Class 3 child with ADHD, keeps blurting out answers before others can think. Which strategy best helps her while keeping the whole class involved?","options":["Having every child write an answer on a slate and show it together on a signal","Never asking her any questions, so that she learns to wait quietly","Sending her out of the room each time she calls out, to teach self-control","Letting her answer every question, since her eagerness should be rewarded"],"answer":0,"explanation":"Whole-class response methods give her an immediate way to respond while making everyone think and answer; ignoring, excluding or letting her dominate do not build self-control.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-837","question":"Imran, a Class 5 boy on the autism spectrum, wants friends but talks only about trains and does not notice when others lose interest. Which approach is most appropriate?","options":["Banning him from talking about trains in school so that he learns other topics","Teaching turn-taking through role-play and using his train interest as a bridge","Leaving him to work out social rules by himself, as other children do","Seating him alone so that the other children are not bored by his talk"],"answer":1,"explanation":"Social rules that others pick up naturally often need to be taught directly to autistic children; using a strong interest as a bridge motivates him to interact.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-838","question":"A 13-year-old with moderate intellectual disability in an inclusive Class 6 is given nursery rhymes and baby toys because his reading level is around Class 1. Which principle does this violate?","options":["Task analysis, which breaks skills into small steps","Positive reinforcement, which rewards each success","Age-appropriateness of materials, even when content is simplified","Concrete-to-abstract sequencing, which starts with objects"],"answer":2,"explanation":"Content can be simplified without being childish; using age-appropriate topics and materials respects the learner and supports acceptance among his peers.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-839","question":"Which of the following is an example of differentiating the LEARNING ENVIRONMENT?","options":["Setting up a quiet corner for some students and a discussion area for others","Giving advanced students harder problems on the same topic during the lesson","Letting students present their project either as a poster or as a speech","Teaching the same idea through both a story and a labelled diagram"],"answer":0,"explanation":"Changing where and in what conditions students work, such as seating, noise and space, is differentiation of the environment; the other options vary process, product or representation.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-840","question":"At the end of each lesson, a Class 6 teacher collects a one-question ‘exit slip’ from every student and uses it to decide next day’s groups. Why is this important for differentiated instruction?","options":["It provides regular marks that can be added to the term report card","It helps her rank students accurately for the school merit list","It replaces the need to teach the whole class together the next day","It tracks readiness, so groups and tasks can change as understanding changes"],"answer":3,"explanation":"Differentiation is driven by continuous formative assessment; quick checks such as exit slips let the teacher regroup flexibly instead of fixing students in permanent levels.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-841","question":"Manoj, in Class 6, helps at his family’s tea stall before school and often arrives late and tired. What is the most appropriate response from his teacher?","options":["Marking him absent whenever he is late, to enforce discipline for all","Telling him that school will not help him if he keeps working at the stall","Helping him catch up and working with his parents and the SMC on attendance","Asking him to sit at the back so that his late entry does not disturb others"],"answer":2,"explanation":"Punishing a child for poverty-related constraints pushes him out of school; understanding, academic support and working with the family and community keep him enrolled and learning.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-842","question":"Several Class 8 girls in a rural school are absent for a few days every month during menstruation. Which step by the school best addresses this?","options":["Marking these absences as excused, so the girls are not penalised","Ensuring private toilets with water and disposal, and openly normalising menstruation","Asking the girls to stay home during those days so that they are comfortable","Discussing the issue only privately with the girls’ mothers, to avoid embarrassment"],"answer":1,"explanation":"Absence often stems from lack of facilities and from stigma; proper sanitation and open information remove both barriers, whereas staying home or excusing absence accepts lost learning.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-843","question":"A child of seasonal migrant workers arrives mid-year at a government school in Maharashtra with no transfer certificate and no birth certificate. What does the RTE Act, 2009 require?","options":["Admission only after the previous school sends the transfer certificate","Admission only at the beginning of the next session, to avoid disruption","Admission into Class 1, since her previous learning cannot be verified","Immediate admission, since missing age proof or TC cannot deny or delay it"],"answer":3,"explanation":"RTE bars denial of admission for want of age proof and states that delay in producing a transfer certificate cannot delay or deny admission; she should join an age-appropriate class.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-844","question":"While reviewing a Class 3 book, a teacher finds these illustrations. Which one most reinforces a stereotype?","options":["A boy and a girl playing football together in the school ground","An elderly man cooking dinner for his grandchildren at home","Every doctor pictured is a man and every nurse pictured is a woman","A woman in a wheelchair working as a teacher in a classroom"],"answer":2,"explanation":"Repeated one-sided images teach children that some roles belong to one gender; the other illustrations deliberately counter common stereotypes.","difficulty":"moderate","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-845","question":"Assertion (A): A school can teach discrimination even when nothing in its syllabus is discriminatory. Reason (R): Children learn values from daily routines, such as where they sit, who gets praised and which children are given leadership roles.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"This is the hidden curriculum: unwritten messages in school practices shape children's beliefs about who matters, which explains how discrimination can be taught without any written content.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-846","question":"Which assessment practice is most inclusive for a Class 4 class with children of varied abilities, languages and disabilities?","options":["One written test at the end of the term, the same for all children","Ranking children by marks so that each knows where they stand in class","Testing only reading and writing skills, since these are basic to all learning","Ongoing observation, portfolios, oral answers and projects in varied modes"],"answer":3,"explanation":"Varied, continuous assessment lets every child show what they have learnt and guides teaching; a single written test measures the barrier of the mode as much as the learning.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-847","question":"Assertion (A): Placing a child with a disability in a regular classroom is, by itself, enough to achieve inclusion. Reason (R): Inclusion requires changes in teaching, materials, attitudes and assessment so that the child participates and learns.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Physical placement without change is integration or ‘dumping’; inclusion needs active adaptation of the system, so A is false and R is true.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-848","question":"Before Eid, a Class 5 teacher in Hyderabad plans a lesson where children share how festivals are celebrated in their homes, including Eid, Bonalu, Christmas and Diwali, and finds similarities and differences. What is the main value of this activity for inclusion?","options":["It replaces the need to follow the syllabus during the festival season","It values each child’s culture equally and makes diversity feel normal","It helps the teacher find out which religion each child follows at home","It is useful only in schools where all children share one religion"],"answer":1,"explanation":"Drawing on all children's cultural experiences affirms their identities and builds respect across groups, which is central to an inclusive classroom.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-849","question":"Laila, who is deaf-blind, is joining Class 1 of a regular school in Kerala. Which consideration is most important when planning her communication?","options":["Since she can neither see nor hear, she cannot be taught in a regular school","Consistent touch-based communication, like tactile signing and objects of reference","She should be taught Braille first, before any other form of communication","Loud speech close to her ear will be enough for her to follow the lessons"],"answer":1,"explanation":"Deaf-blindness needs touch-based communication used consistently by everyone around the child; the RPwD Act also requires education of children who are blind, deaf or both in the most appropriate modes.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-850","question":"In a Basic (Nai Talim) school, Class 4 children learn arithmetic by measuring and counting the yarn they spin, geography by finding where cotton is grown, and history through the story of handloom weaving in India. This technique of Basic Education is called:","options":["Integration of subjects through separate textbook units","Programmed learning in small, self-paced steps","Correlation of subjects with the craft and the environment","Ability grouping by children’s skill at spinning"],"answer":2,"explanation":"The Wardha scheme taught subjects by correlating them with three centres: the basic craft, the physical environment and the social environment, so knowledge grew out of productive activity.","difficulty":"hard","source":"CTET · UPTET · REET"},
  {"id":"cdp-child-development-851","question":"Which of these were features of Gandhi’s scheme of Basic Education (Nai Talim)? I. Education centred on a productive craft. II. The mother tongue as the medium of instruction. III. English compulsory from the first class. IV. Education made partly self-supporting through the sale of craft products.","options":["I, II and IV only","I and III only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"Basic Education was craft-centred, taught through the mother tongue and meant to be partly self-supporting; it did not make English compulsory, so III is wrong.","difficulty":"very-hard","source":"CTET · State TET"},
  {"id":"cdp-child-development-852","question":"A school claims to follow Gandhi’s idea of education. Which of its practices contradicts that idea most?","options":["Linking daily lessons to work in the school’s vegetable garden","Teaching in the children’s mother tongue in the early classes","Stressing cleanliness, cooperation and self-reliance in daily routines","Treating literacy as the whole of education and testing only that"],"answer":3,"explanation":"Gandhi saw education as an all-round drawing out of the best in body, mind and spirit, and said literacy is neither the end nor even the beginning of education.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-853","question":"Assertion (A): Gandhi’s Basic Education was meant mainly to train children as skilled labourers for factories. Reason (R): Gandhi saw craft as a medium for developing the whole personality: body, mind and spirit.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Craft in Nai Talim was a medium of education, not vocational training for industry; Gandhi meant it to develop head, hand and heart together and build self-reliant village communities.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-854","question":"Which statement about the origin of Basic Education is correct?","options":["It was proposed by the Kothari Commission in 1966 and detailed by D. S. Kothari","It was discussed at Wardha in 1937 and detailed by a committee under Dr Zakir Husain","It was proposed by Tagore at Santiniketan in 1901 and detailed by Gijubhai Badheka","It was recommended by the NPE, 1986 and detailed by the Yash Pal committee"],"answer":1,"explanation":"Gandhi’s proposals were discussed at the Wardha conference (1937), and the Zakir Husain committee drew up the Wardha scheme of Basic Education.","difficulty":"moderate","source":"CTET · UPTET · REET"},
  {"id":"cdp-child-development-855","question":"NCF 2005’s focus on ‘work and education’ and NEP 2020’s call for vocational exposure from the middle stage both echo Gandhi’s Nai Talim mainly in their belief that:","options":["Work should be reserved only for children who fail in the academic subjects","Vocational training should fully replace academic subjects after Class 5","Productive work is a valid medium of learning, not walled off from academics","Children should be paid fair wages for the productive work they do in school"],"answer":2,"explanation":"Both documents treat work as a source of knowledge and values and reject a hard divide between vocational and academic learning, an idea at the heart of Nai Talim.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-856","question":"Tagore’s satirical story ‘The Parrot’s Training’ (Tota Kahini) is best read as a critique of:","options":["Schooling that crams pupils with lessons while killing their natural joy","The excessive freedom given to children in open-air nature schools","Teaching through the mother tongue instead of a classical language","A shortage of buildings, books and equipment in village schools"],"answer":0,"explanation":"In the story the parrot is caged in gold and force-fed pages until it dies; Tagore mocks lavish but lifeless schooling that values the apparatus over the living child.","difficulty":"hard","source":"CTET · State TET"},
  {"id":"cdp-child-development-857","question":"At Santiniketan, Tagore held many classes in the open, under the trees. His main educational reason was that:","options":["The cost of school buildings had to be saved for books and teachers","Open-air classes made discipline easier to enforce among the children","Close contact with nature nourishes the child’s senses, freedom and joy","Open-air teaching was the surest protection against disease in Bengal"],"answer":2,"explanation":"Tagore believed that a child grows best in harmony with nature and in freedom; walls and rigid routines, he felt, cut the child off from the living world.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-858","question":"Which of these statements about Rabindranath Tagore’s educational ideas are correct? I. He held that the mother tongue should be the medium of education. II. He founded Visva-Bharati with the internationalist ideal of a meeting of cultures. III. He regarded music, art and drama as frills to be kept out of the timetable. IV. Through Sriniketan he linked education with rural reconstruction.","options":["I, II and III only","I, II and IV only","II and IV only","I, III and IV only"],"answer":1,"explanation":"Tagore championed the mother tongue, internationalism (Visva-Bharati) and rural reconstruction (Sriniketan); the arts were central to his school, not frills, so III is false.","difficulty":"very-hard","source":"CTET · DSSSB TGT"},
  {"id":"cdp-child-development-859","question":"In Gijubhai Badheka’s ‘Divaswapna’, the teacher Lakshmishankar spends the first days of term telling stories and playing games before starting formal lessons. The idea behind this is that:","options":["Formal teaching is unnecessary in primary school, so lessons can wait","Stories and games should permanently replace the prescribed syllabus","Children should be kept busy so that the headmaster is satisfied","A bond of trust and interest must come before meaningful learning"],"answer":3,"explanation":"Lakshmishankar first wins the children’s trust, attention and joy through stories and games, and then builds language and other learning on that foundation.","difficulty":"hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-860","question":"Which of these statements about Gijubhai Badheka are correct? I. He adapted Montessori’s ideas to Indian conditions and founded a Bal Mandir at Bhavnagar. II. He wrote a large body of stories and literature for children. III. He opposed fear, punishment and rote examinations in primary schools. IV. He headed the committee that drafted the Wardha scheme.","options":["I, II and III only","I and IV only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"Gijubhai founded the Dakshinamurti Bal Mandir, wrote widely for children and fought fear-based teaching; the Wardha scheme committee was headed by Zakir Husain, so IV is false.","difficulty":"very-hard","source":"CTET Paper I · UPTET"},
  {"id":"cdp-child-development-861","question":"Match each thinker with the idea most closely linked to him: P. Gandhi  Q. Tagore  R. Gijubhai Badheka  S. Dewey — 1. Craft-centred education of the head, heart and hand  2. Harmony with nature, freedom and internationalism  3. Bal Mandir and joyful, fear-free primary teaching through stories  4. The school as an embryonic democratic community","options":["P-2, Q-1, R-3, S-4","P-1, Q-2, R-4, S-3","P-1, Q-2, R-3, S-4","P-3, Q-2, R-1, S-4"],"answer":2,"explanation":"Gandhi stressed craft and 3H education, Tagore nature, freedom and internationalism, Gijubhai joyful teaching in his Bal Mandir, and Dewey the school as a democratic community.","difficulty":"hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-862","question":"Both Gandhi’s Nai Talim and Dewey’s progressive education:","options":["Rejected the mother tongue as the medium of instruction in schools","Saw purposeful work linked to community life as the core of learning","Made religious instruction the centre of the school curriculum","Aimed mainly to train children for regular factory employment"],"answer":1,"explanation":"Both made purposeful, socially useful activity the starting point of learning and tied the school to community life; neither centred on religious instruction or factory training.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-863","question":"A frequent criticism of Basic Education as originally proposed was that:","options":["It ignored the mother tongue and taught mainly in English","It gave no place to manual work or productive craft","It was designed only for urban elite schools, not for villages","Its self-supporting aim risked putting craft sales above learning"],"answer":3,"explanation":"Critics feared that the self-supporting aim could make output, not learning, the goal; the scheme was in fact mother-tongue based, craft-centred and aimed at village children.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-864","question":"A school inspired by Tagore would most likely include:","options":["Music, dance, drama and nature walks woven into daily learning","Long hours of copy-writing in silent rows to build discipline","Uniform textbooks and weekly ranking tests for every class","A ban on festivals and celebrations to save teaching time"],"answer":0,"explanation":"Tagore placed the arts, festivals and nature at the heart of learning at Santiniketan; mechanical copying and competitive ranking were what he rejected.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-865","question":"Tagore criticised the education of his time chiefly because it was:","options":["Too practical and too closely tied to village life and its crafts","Given too much in the mother tongue rather than in English","Foreign-medium, cut off from the child’s surroundings and exam-driven","Too generous in the freedom and play it allowed young children"],"answer":2,"explanation":"Tagore attacked colonial schooling as foreign-medium, bookish, examination-driven and divorced from the child’s life and nature; he wanted the very opposite of options A, B and D.","difficulty":"very-hard","source":"CTET Paper II · State TET"},
  {"id":"cdp-child-development-866","question":"A teacher in a village school in Rajasthan teaches measurement by making clay pots with a local potter, uses folk songs and stories to teach rhythm and counting, and keeps her class free of fear. Which pair of Indian thinkers’ ideas does she most clearly draw on?","options":["Vivekananda (man-making education) and Aurobindo (integral education)","Gandhi (craft-centred learning) and Gijubhai Badheka (fear-free learning)","Macaulay (downward filtration) and Charles Wood (graded schools)","Rousseau (negative education) and Locke (the mind as a blank slate)"],"answer":1,"explanation":"Learning through a local craft reflects Nai Talim, while joyful, fear-free teaching through songs and stories is Gijubhai’s hallmark.","difficulty":"hard","source":"CTET · REET"},
  {"id":"cdp-child-development-867","question":"Assertion (A): Gijubhai Badheka held that strict examinations are necessary to make young children study. Reason (R): He believed that joy, freedom and interest are the basis of learning in the early years.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Gijubhai opposed fear, punishment and examination pressure on young children; he built learning on interest, play and stories, so A is false while R is true.","difficulty":"very-hard","source":"CTET Paper I · UPTET"},
  {"id":"cdp-child-development-868","question":"Under the Wardha scheme of Basic Education, free and compulsory education was to be given for:","options":["5 years, for ages 6 to 11","8 years, for ages 6 to 14","7 years, for ages 7 to 14","10 years, for ages 6 to 16"],"answer":2,"explanation":"The 1937 scheme proposed seven years of free and compulsory education (7 to 14); the 6 to 14 range belongs to the RTE Act, 2009, a common mix-up.","difficulty":"hard","source":"CTET · UPTET · REET"},
  {"id":"cdp-child-development-869","question":"The Dakshinamurti Bal Mandir set up by Gijubhai Badheka at Bhavnagar adapted the ideas of which educator, and with what change?","options":["Maria Montessori, swapping costly apparatus for local materials and stories","J. F. Herbart, introducing his five formal steps of lesson planning","B. F. Skinner, using teaching machines with immediate reinforcement","John Locke, emphasising discipline through habit formation and drill"],"answer":0,"explanation":"Gijubhai was deeply influenced by Montessori but Indianised her method, using inexpensive local materials, folk songs, games and stories.","difficulty":"hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-870","question":"Which practice would Tagore most have objected to?","options":["Children composing and performing songs about the changing seasons","Lessons held in the open, among the trees, in every season","Students from different countries and cultures studying together","Memorising answers for exams in a language children barely understand"],"answer":3,"explanation":"Tagore criticised rote, examination-centred learning through a foreign medium; creativity, nature and internationalism were things he actively promoted.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-871","question":"Assertion (A): Gandhi insisted that Basic Education should be given through the mother tongue. Reason (R): He believed that learning through a foreign medium causes strain, encourages cramming and cuts children off from their own surroundings.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Gandhi’s case for the mother tongue rested on exactly these arguments: a foreign medium strains the child, breeds rote learning and alienates him from home and community.","difficulty":"very-hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-872","question":"For Tagore, a teacher can truly teach only if he or she:","options":["Has memorised the entire syllabus along with its standard answers","Follows the prescribed timetable strictly, without any deviation","Keeps learning, as a lamp lights another only while its own flame burns","Keeps a careful distance from students so as to preserve his or her authority"],"answer":2,"explanation":"Tagore’s image of the lamp says a teacher who has stopped learning can only pass on dead information; living teaching comes from a teacher who keeps growing.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-873","question":"Which NEP 2020 proposal most directly echoes Tagore’s and Gandhi’s insistence on the mother tongue?","options":["English as the compulsory medium of instruction from Grade 1 in all schools","The home language or mother tongue as medium wherever possible, at least till Grade 5","A single national language as the medium of instruction in every state and board","The medium of instruction to be chosen by each student freely, but only after Grade 10"],"answer":1,"explanation":"NEP 2020 recommends the home language or mother tongue as the medium wherever possible, at least till Grade 5 and preferably till Grade 8 and beyond, in line with both thinkers.","difficulty":"hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-874","question":"Which statement about the aim of Nai Talim is MOST accurate?","options":["To prepare educated clerks for government service in the towns","To build self-reliant people rooted in village life through productive work","To prepare children well for competitive examinations and higher studies abroad","To spread English-medium education to children in the villages of India"],"answer":1,"explanation":"Nai Talim aimed at self-reliant, socially useful citizens of a non-exploitative village society; it was a reaction against clerk-producing colonial education.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-875","question":"How does NCF 2005 recommend that gender concerns be addressed in the school curriculum?","options":["Through a separate chapter on women’s issues in the Class 8 social science book","As a concern cutting across all subjects, textbooks and school practices","By offering separate subjects for boys and girls at the secondary stage","Only through special talks and events held on International Women’s Day"],"answer":1,"explanation":"NCF 2005 treats gender as a cross-cutting concern: it must shape content, illustrations, examples, classroom interaction and school culture, not sit in one isolated lesson or event.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-876","question":"Assertion (A): A school can pass on gender stereotypes to its students even when its written syllabus never mentions gender. Reason (R): Much of what children learn in school comes through the hidden curriculum of routines, interactions, seating, duties and illustrations.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Stereotypes travel through who is asked to lead, who cleans, which pictures appear and how children are spoken to, all parts of the hidden curriculum, which is exactly why A holds.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-877","question":"Every birthday, three-year-old Anu receives dolls and kitchen sets from relatives, while her brother receives toy cars and cricket bats; both are praised for playing ‘properly’ with their own toys. This is mainly an example of:","options":["Biological maturation of gender differences","Gender constancy","Gender-role socialisation within the family","Gender identity disorder"],"answer":2,"explanation":"Families shape gender roles by the toys, praise and activities they offer to boys and girls; the differences here are taught, not biologically determined.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-878","question":"Seven-year-old Pinky often watches television advertisements in which only women cook and clean and only men drive cars and run offices. In play she now insists that ‘ladies cook, men go to office’. Which theory most directly explains how she acquired this belief?","options":["Social learning theory, through observing and imitating models","Classical conditioning, by pairing two stimuli over and over again","Chomsky’s nativist theory of an inborn language device","Freud’s theory of the Oedipus complex and identification"],"answer":0,"explanation":"Bandura’s social learning theory explains gender roles as learned by observing models (in the family and media) and by seeing which behaviours are rewarded.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-879","question":"A Class 7 teacher replaces words like ‘chairman’, ‘policeman’ and ‘mankind’ in her worksheets with ‘chairperson’, ‘police officer’ and ‘humankind’. The best psychological justification for this change is that:","options":["Gender-neutral words are shorter, simpler and much easier for young children to spell","Always-male role words can shape children’s ideas of who belongs in those roles","Textbook writers and boards have officially banned the older words","The change is only cosmetic and has no real effect on children’s thinking"],"answer":1,"explanation":"Research on generic masculine terms shows they make people imagine mainly men, in line with weak linguistic relativity; neutral terms help children see all roles as open to everyone.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-880","question":"After a maths test, a teacher tells boys who failed, ‘You didn’t put in enough effort’, but tells girls who failed, ‘Maybe maths just isn’t your thing.’ What long-term effect is most likely?","options":["Girls will try harder, because ability feedback motivates more than effort feedback","Both groups will be equally unaffected, since feedback has little impact","Boys will become helpless, because effort is something they cannot control","Girls will tend to blame low ability, give up, and show learned helplessness"],"answer":3,"explanation":"Attributing failure to a stable, uncontrollable cause (ability) leads to helplessness, while effort attributions keep students trying; such gendered feedback can steer girls away from mathematics.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-881","question":"Tanvi is assertive and competitive in inter-school debates, and is also gentle and nurturing while helping juniors with homework. Sandra Bem would describe a person who combines strong traditionally ‘masculine’ and ‘feminine’ traits in this way as:","options":["Androgynous","Gender-typed","Undifferentiated","Gender-constant"],"answer":0,"explanation":"Bem’s measure scored masculine and feminine traits separately; high scores on both indicate androgyny, which she argued allows more flexible behaviour across situations.","difficulty":"hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-882","question":"Girls from several villages stop attending a secondary school in Rajasthan after Class 8. Which measure addresses the problem at its structural roots instead of blaming the girls or their families?","options":["Lecturing parents at meetings on the value of educating their daughters well","Marking the girls as ‘dropouts’ and removing their names from the rolls","Telling the girls that marriage should wait until they finish school","Safe transport, usable toilets and a timetable that fits local work seasons"],"answer":3,"explanation":"Distance, safety, sanitation and household work are major structural barriers to girls’ schooling; removing them is more effective than blaming individuals.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-883","question":"Which of the following statements are consistent with the view that gender is a social construct? I. Gender roles differ from one culture to another. II. Gender roles can change over time within the same society. III. Differences in boys’ and girls’ school abilities are mostly fixed by hormones. IV. Schools can either reproduce or challenge existing gender roles.","options":["I and II only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"Variation across cultures and time, and the school’s power to shape roles, follow from gender being socially constructed; III claims biological fixity, which this view rejects.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-884","question":"Which statement best captures a balanced critical view of labelling children (for example, ‘learning disabled’ or ‘slow learner’)?","options":["Labels are always harmful and should never be used for any purpose at all","Labels are always useful, because they explain everything about a child","Labels can unlock support but also stigmatise, so focus on each child’s needs","Labels matter only to doctors and specialists, and have no effect inside classrooms"],"answer":2,"explanation":"Diagnosis can open access to support, yet labels risk stereotyping and self-fulfilling expectations; a needs-based, person-first approach keeps the benefits and limits the harm.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-885","question":"A school creates permanent ‘A’ and ‘D’ sections in Class 3 based on a test. Two years later the gap between the sections has widened. Which explanation is best supported by research on ability grouping?","options":["The lower section got less demanding teaching and lower expectations","The test correctly identified children whose abilities were fixed from birth","Children in the higher section were naturally gifted and would have progressed anyway","The gap widened only because of differences in their parents’ income levels"],"answer":0,"explanation":"Rigid tracking tends to give lower groups a thinner curriculum and lower expectations, so initial differences grow; this is why NCF 2005 cautions against early, fixed streaming.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-886","question":"To raise its Class 10 board results, a school in Kota stops art, games and library periods for Class 9 and 10 and devotes the time to drilling past board papers. This is an example of:","options":["Formative assessment that guides improvement in learning","Mastery learning through repeated practice","Enrichment of the core board syllabus","Curriculum narrowing caused by high-stakes testing"],"answer":3,"explanation":"When results on a high-stakes exam drive decisions, schools tend to ‘teach to the test’ and drop untested areas, shrinking the curriculum, which NCF 2005 criticises.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-887","question":"A teacher tells Shabnam, ‘In July you read 20 words a minute; today you read 35 with fewer mistakes,’ without comparing her to classmates. This kind of assessment is called:","options":["Ipsative assessment","Norm-referenced assessment","Summative assessment","Diagnostic testing"],"answer":0,"explanation":"Ipsative assessment compares a learner with her own earlier performance, focusing on progress rather than rank, which supports motivation, especially for struggling learners.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-888","question":"Which feature of the holistic progress card proposed in the National Education Policy 2020 marks a shift away from marks-only reporting?","options":["It reports only the student’s rank in the class, along with the class average","It is filled in only once, at the end of Class 10, for board admission","It records only marks in the five main subjects, leaving out co-scholastic areas","It is 360-degree, with self, peer and teacher assessment across many domains"],"answer":3,"explanation":"NEP 2020 describes a 360-degree, multidimensional progress card covering many domains and including self and peer assessment, instead of marks and ranks alone.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-889","question":"A Class 6 maths test in a Tamil-medium school consists of long, complex English word problems. Many students who solve the same problems easily when they are given in Tamil fail the test. The main problem with this test is its:","options":["Reliability, because the scores would change if the same test were repeated","Objectivity, because different examiners would mark the answers differently","Validity, as it measures English reading as much as mathematical ability","Practicability, because it takes too long to administer in a single period"],"answer":2,"explanation":"Validity is whether a test measures what it claims to measure. A test can give consistent (reliable) scores and still be invalid if language proficiency, not mathematics, drives those scores.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-890","question":"Twelve-year-old Raju sells vegetables in a market and accurately calculates change mentally for customers, yet in school he fails written subtraction sums with the same numbers. This is best interpreted as showing that:","options":["Raju has low intelligence, which only shows up in a school setting","Market calculation is mere habit and does not involve real mathematical thinking","Raju must be getting help or cheating with the change in the market","Knowledge is tied to context, so schools should build on his street maths"],"answer":3,"explanation":"Studies of ‘street mathematics’ show children can be competent in practical settings but fail school formats; the gap reflects context and representation, not lack of ability.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PGT"},
  {"id":"cdp-child-development-891","question":"In Herman Witkin’s terms, a student who easily picks out a simple shape hidden within a complex figure, prefers to work independently and structures problems on her own is described as having which cognitive style?","options":["Field-dependent","Field-independent","Impulsive","Convergent thinking"],"answer":1,"explanation":"Field-independent learners separate details from the surrounding field (as in the Embedded Figures Test) and impose their own structure; field-dependent learners are influenced more by context and social cues.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-892","question":"A training module tells teachers to test each child’s ‘learning style’ (visual, auditory or kinaesthetic) and teach every child only in that style. Which response is most consistent with research evidence?","options":["Studies do not show that matching teaching to such styles improves learning","The method is well proven and should be applied in every class from now on","Learning styles are fixed at birth, so matching is the only way children learn","Only kinaesthetic teaching works for primary children, so it should dominate"],"answer":0,"explanation":"Reviews of the evidence find little support for the ‘meshing’ claim that teaching in a child’s preferred style improves outcomes; children have preferences, but varied, content-appropriate teaching helps all.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-893","question":"In a Pune Class 5 science class, a teacher lets students explain ideas in a mix of Marathi and English and then helps them restate key terms in English. This practice is best supported because:","options":["It lets students avoid learning English altogether in science lessons","Using all their languages helps students make meaning and link new ideas","Mixing languages shows confusion, so it should be allowed only once a week","It reduces the teacher’s workload in explaining difficult science terms"],"answer":1,"explanation":"Drawing on the full linguistic repertoire (code-switching or translanguaging) supports understanding and participation, in line with NCF 2005’s view of multilingualism as a resource.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-894","question":"Four preschoolers sit together; each talks about his own drawing, and no one responds to what the others say, though they appear to be ‘conversing’. Piaget called this:","options":["Inner (silent) speech","Social speech","Collective monologue","Telegraphic speech"],"answer":2,"explanation":"Piaget described collective monologue as a form of egocentric speech in which children talk in each other’s presence without adapting to or answering one another.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-895","question":"Assertion (A): Piaget held that egocentric speech declines and disappears as children become less egocentric. Reason (R): Vygotsky held that egocentric (private) speech does not disappear but goes underground as inner speech.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements correctly describe each thinker’s view, but they are rival accounts; Vygotsky’s position cannot explain Piaget’s, so R is not an explanation of A.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-896","question":"Which of the following is a well-founded criticism of a purely nativist (Chomskyan) account of language development?","options":["It cannot explain why children everywhere learn language at similar ages","It gives too much importance to parents’ reinforcement of correct speech","It underplays social interaction; children rarely learn a language from TV alone","It claims that language is learned only through imitation of adults’ sentences"],"answer":2,"explanation":"Interactionists accept some innate capacity but stress that language grows through responsive conversation; passive exposure without interaction is a poor teacher, a point nativism downplays.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-897","question":"Deaf children who have not been exposed to any sign language still classify objects, solve practical problems and often invent their own gesture systems (‘home sign’). This evidence most directly argues against:","options":["The weak version of linguistic relativity about language and thought","Vygotsky’s idea that private speech guides children’s problem-solving","Gardner’s idea of a separate spatial intelligence in children","The claim that thought is impossible without spoken language"],"answer":3,"explanation":"Reasoning and communication without spoken language show that thought does not wholly depend on it, contradicting strong linguistic determinism; they are compatible with weaker relativity claims.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-898","question":"In Ainsworth’s Strange Situation, a one-year-old explores the room freely while his mother is present, gets upset when she leaves, and on her return quickly goes to her, is comforted and returns to play. His attachment is classified as:","options":["Insecure-avoidant","Insecure-resistant (ambivalent)","Disorganised","Secure"],"answer":3,"explanation":"Using the mother as a secure base, mild-to-moderate distress at separation and easy comfort at reunion define secure attachment. Distress alone does not mean insecurity.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-899","question":"In the Strange Situation, an infant shows little distress when the mother leaves and actively ignores or turns away from her when she returns, playing with toys instead. A teacher-trainee concludes the baby is ‘very independent and securely attached’. What is the error?","options":["It is insecure-avoidant; indifference at reunion signals insecure attachment","There is no error; lack of distress shows a secure and confident attachment","The pattern is disorganised, as the child is confused about the mother","The pattern is insecure-resistant, as the child resists the mother’s return"],"answer":0,"explanation":"Avoidant infants suppress attachment behaviour and avoid the caregiver at reunion, often after repeated rejection of their bids for comfort; it is not healthy independence.","difficulty":"very-hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-900","question":"An infant clings to the mother and barely explores, is extremely upset when she leaves, and on her return alternates between clinging to her and angrily pushing her away, staying hard to comfort. This is:","options":["Secure attachment","Insecure-avoidant attachment","Insecure-resistant attachment","Disorganised/disoriented attachment"],"answer":2,"explanation":"Ambivalence at reunion (seeking contact yet resisting it with anger) together with poor exploration marks resistant attachment, often linked to inconsistent caregiving.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-901","question":"At reunion in the Strange Situation, a toddler approaches the mother with her face turned away, then freezes with a dazed expression. Which pattern did Main and Solomon describe that fits this?","options":["Secure","Disorganised","Insecure-avoidant","Insecure-resistant"],"answer":1,"explanation":"Contradictory, confused behaviours such as approaching while looking away or freezing mark disorganised attachment, added later to Ainsworth’s three patterns and often linked to frightening care.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-902","question":"In Harlow’s experiments, infant monkeys spent most of their time clinging to a soft cloth ‘mother’ that gave no milk, going to a wire ‘mother’ only to feed. What did this mainly show?","options":["Attachment develops mainly because the mother is the source of food","Monkeys cannot form real attachments to any mother figure at all","Contact comfort matters more than feeding in forming attachment","Wire mothers are better for building early independence"],"answer":2,"explanation":"Harlow’s findings undermined the ‘cupboard love’ view that attachment arises from being fed, showing the importance of contact comfort and security.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-903","question":"Bowlby proposed that through early relationships a child builds an ‘internal working model’. In a Class 3 classroom, this concept would best explain why:","options":["A child who found adults dependable expects his new teacher to help him","A child learns multiplication tables quickly through daily repetition in class","A child grows noticeably taller and stronger during the school year","A child learns to write from left to right in Hindi and English"],"answer":0,"explanation":"The internal working model is a mental template of self and others drawn from early care; it shapes expectations of later relationships, e.g. whether teachers can be trusted.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-904","question":"A study of Scottish infants by Schaffer and Emerson found that many babies formed attachments to several people, and that the strongest attachment was often not to the person who fed and bathed them most. What best predicted the strongest attachment?","options":["Who spent the most hours each day with the baby","Who fed and bathed the baby most often","Who was the baby’s biological mother","Who responded most sensitively to the baby"],"answer":3,"explanation":"Sensitive responsiveness and interaction, not the amount of physical care or time, predicted the main attachment figure; this also shows multiple attachments are normal, as in Indian joint families.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-905","question":"An eight-month-old who happily went to anyone a few months ago now cries and clings to her mother when a new neighbour tries to pick her up. What does this most likely indicate?","options":["A developmental disorder needing professional help","Spoiling caused by too much affection at home","Normal stranger anxiety after a specific attachment","Insecure-avoidant attachment to the mother"],"answer":2,"explanation":"Wariness of strangers appearing in the second half of the first year accompanies the formation of clear-cut attachments to particular people; it is a normal developmental sign.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-906","question":"Goslings followed the first moving object they saw after hatching, even Konrad Lorenz himself, and this happened only in a short window after hatching. Which concept does this most directly illustrate?","options":["Imprinting during a critical period","Operant conditioning by food rewards","Secure base behaviour","Internal working model"],"answer":0,"explanation":"Imprinting is rapid, early-formed following that occurs during a brief critical period; Bowlby drew on such ethological work, though human attachment develops more gradually.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-907","question":"Assertion (A): A securely attached toddler explores a new playroom more confidently when his mother is present. Reason (R): A secure attachment figure acts as a safe base from which the child explores and to which he returns when stressed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The secure-base concept (Ainsworth) explains why secure children explore more when the caregiver is nearby; security supports, not reduces, exploration.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-908","question":"A Class 1 child cries and clings to his father at the school gate for the first two weeks. Which response from the teacher fits what attachment research suggests?","options":["Tell the father to slip away without saying goodbye so the child doesn’t notice","Welcome him warmly, keep a steady routine, and let the father say a brief goodbye","Point out to the class that he is crying, so that embarrassment makes him stop","Send the child home and readmit him only when he is ready to come in on his own"],"answer":1,"explanation":"Separation distress is normal; a consistent, warm teacher and predictable routines provide a new secure base, while sneaking away or shaming increases insecurity.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-909","question":"Which of these statements about attachment are correct? I. Infants can form attachments to several caregivers, not only the mother. II. Attachment forms mainly because the caregiver satisfies hunger. III. Early attachment quality can influence later relationships. IV. Insecure attachment in infancy fixes a child’s fate for life, whatever happens later.","options":["I and II only","I and III only","II and IV only","I, III and IV only"],"answer":1,"explanation":"Multiple attachments are common (I) and early bonds shape later relationships (III). Feeding is not the main cause (II false, as Harlow showed), and later sensitive care can change outcomes (IV false).","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-910","question":"Children adopted from severely deprived orphanages into loving families showed substantial recovery, most completely in those adopted early. What does this most strongly suggest?","options":["Early deprivation has no lasting effect whatsoever on development","Development is fully fixed in the first year and cannot be changed","Only heredity matters for how well the children recovered","Early experience matters, yet development remains plastic"],"answer":3,"explanation":"Large adoption studies show early deprivation can harm development, yet good later care brings much recovery, more so when early; this supports plasticity along with sensitive periods.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-911","question":"The district education office decides to cut the library budget of a village school, and the Class 5 children there no longer get new storybooks. The children have never been to that office. In Bronfenbrenner’s model, the office is part of their:","options":["Microsystem","Mesosystem","Exosystem","Macrosystem"],"answer":2,"explanation":"The exosystem includes settings the child does not take part in, such as an administrative office, which affect the child indirectly through settings like the school. It is not the macrosystem, which is broad culture, values and laws.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-912","question":"Mrs. Kaur, a Class 2 teacher, holds regular friendly meetings with parents, and they agree on a common way of helping children read at home and at school. Bronfenbrenner would describe this as strengthening the:","options":["Microsystem","Mesosystem","Exosystem","Chronosystem"],"answer":1,"explanation":"The mesosystem is the set of links between the child’s microsystems, here home and school; strong, consistent links support development.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-913","question":"Widely shared cultural beliefs in a society, for example that girls’ education matters less than boys’, shape how families and schools treat children. In Bronfenbrenner’s model these beliefs belong to the:","options":["Macrosystem","Exosystem","Mesosystem","Microsystem"],"answer":0,"explanation":"The macrosystem is the overarching pattern of culture, values, laws and ideology that shapes all the inner systems.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-914","question":"A Class 6 child’s parents divorce when he is eleven; the effects on him differ from what they would have been at age three. Bronfenbrenner captured the importance of such timing and change over time in the:","options":["Exosystem","Macrosystem","Mesosystem","Chronosystem"],"answer":3,"explanation":"The chronosystem adds the dimension of time: life transitions and historical events, and how their effects depend on when they occur in the child’s life.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-915","question":"Match the following for a Class 4 child in Bronfenbrenner’s model: 1. His classroom and teacher 2. Meetings between his parents and teacher 3. His father’s office transfer policy 4. National laws such as the RTE Act; a. Exosystem b. Microsystem c. Macrosystem d. Mesosystem","options":["1-b, 2-a, 3-d, 4-c","1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-a, 4-c","1-b, 2-d, 3-c, 4-a"],"answer":2,"explanation":"The classroom is a microsystem, the parent–teacher link a mesosystem, a parent’s workplace policy an exosystem, and broad laws and cultural values the macrosystem.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-916","question":"In Bronfenbrenner’s view, a temperamentally irritable child who makes her parents more impatient, whose impatience in turn makes her more irritable, illustrates that:","options":["Microsystem influences are two-way: the child shapes others as they shape her","The child is a passive receiver of whatever forces the environment applies","Only the macrosystem of culture and values really affects development","Heredity has no role in development, since the parents create the irritability"],"answer":0,"explanation":"Bronfenbrenner stressed reciprocal, two-way interactions within microsystems; the child’s own characteristics shape how others respond.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-917","question":"Assertion (A): In Bronfenbrenner’s model, the exosystem can influence a child even though the child never participates in it directly. Reason (R): The exosystem acts on the child through its effects on people and settings in the child’s microsystem.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Decisions in a parent’s workplace or the local school board reach the child indirectly through the parents or teachers; R gives the mechanism behind A.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-918","question":"A student’s parents shout at him over homework while his teacher gently encourages the same work; the two never communicate and give him conflicting messages. Which Bronfenbrenner layer is weak, and what would most help?","options":["The microsystem; the teacher should counsel the boy alone so he copes with both styles","The mesosystem; set up regular parent–teacher talks to agree on shared goals for him","The exosystem; link the family to a community counsellor who can ease stress at home","The chronosystem; give him time, as conflicting messages fade as children mature"],"answer":1,"explanation":"The problem lies in the missing link between two microsystems (home and school), which is the mesosystem, so parent–teacher dialogue fixes it directly. Counselling the boy alone is tempting but leaves the two settings still pulling against each other.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-919","question":"Which statement about Bronfenbrenner’s ecological systems theory is INCORRECT?","options":["The child is at the centre of nested systems that interact with one another","Development is affected by settings in which the child does not directly take part","The theory considers only the immediate family as relevant to development","Time and historical change are part of the model through the chronosystem"],"answer":2,"explanation":"Bronfenbrenner’s whole point is that development is shaped by many interacting layers, from family and school to culture and history, not by the immediate family alone.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-920","question":"A child grows up during the Covid-19 school closures, when classes moved online for long periods, while his elder brother had gone to school normally at the same age. Which Bronfenbrenner layer best explains how this historical event changed his development compared with his brother’s?","options":["Mesosystem","Exosystem","Microsystem","Chronosystem"],"answer":3,"explanation":"The chronosystem includes socio-historical events and their timing in a child’s life, so the same family can raise children whose development differs because they grew up at different times.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-921","question":"A newly-joined Class 1 child keeps checking that his teacher is nearby while he explores the activity corner, and runs to her when a loud noise startles him. In attachment terms, the teacher is acting as:","options":["A secure base and safe haven","A source of stranger anxiety","An exosystem influence","A model for vicarious reinforcement"],"answer":0,"explanation":"He explores from the teacher as a secure base and returns to her for comfort as a safe haven, the two key functions of an attachment figure.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-922","question":"Bowlby claimed that breaking the mother–child bond in early years leads to lasting harm. Michael Rutter refined this by distinguishing two situations. Which distinction did he draw?","options":["Between attachment to mothers and attachment to fathers and siblings","Between deprivation (a bond formed then lost) and privation (no bond ever formed)","Between secure and insecure attachment as measured in the Strange Situation","Between imprinting in birds and the slower attachment seen in humans"],"answer":1,"explanation":"Rutter argued that much of the severe harm Bowlby attributed to separation came from privation, never forming a bond at all, while loss of an existing bond (deprivation) usually had less lasting effect.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-923","question":"Asked why the sun is called ‘sun’, a four-year-old says, ‘Because it is hot and round and yellow,’ and insists it could not have been given any other name. Piaget called this belief that names belong to things themselves:","options":["Nominal realism","Artificialism","Transductive reasoning","Conservation of identity"],"answer":0,"explanation":"Nominal realism treats a word as a real property of the object, a form of pre-operational realism. Artificialism concerns who made natural things, not their names.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-924","question":"A four-year-old wakes up and tells her mother, ‘There was a lion in my room; you saw it too, didn’t you?’ She believes her dream happened outside her and that others could see it. Piaget would describe this as:","options":["Object permanence, knowing objects exist when unseen","Realism: treating mental events as real, external things","Formal operational imagination about possible worlds","Private speech, talking aloud to guide her own actions"],"answer":1,"explanation":"Pre-operational realism confuses psychological events such as dreams with physical reality. Young children often think dreams come from outside and can be seen by others.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-925","question":"A seven-year-old says that a bicycle is alive when it is moving but not when it is parked, while a tree is ‘not alive because it doesn’t walk’. This reasoning is best described as:","options":["A mature, biological understanding of what living things are","Artificialism, the belief that people made nature","Hypothetico-deductive reasoning about life","Animism in a reduced form, linking life with movement"],"answer":3,"explanation":"Piaget found that animism narrows with age: young children call almost anything alive, then only things that move, and later only things that move by themselves. Treating the tree as non-living shows the concept is still immature.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-926","question":"In a Class 1 classroom, two rows of six laddoos are placed side by side and then one row is spread out. A child counts both rows, says ‘six’ and ‘six’, and still insists the longer row has more. This shows that:","options":["Counting does not yet ensure conservation; perceived length still dominates","The child cannot count accurately and needs more drill in counting to six","The child has mastered conservation but simply misheard the question","The child has already reached the formal operational stage of thinking"],"answer":0,"explanation":"Counting is a skill; conservation requires understanding that number stays the same despite changes in appearance. Centration on row length overrides the count.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-927","question":"Asked to arrange ten sticks from shortest to longest, Child A tries pairs at random and makes many corrections, while Child B picks the shortest stick, then the shortest of those left, and so on, finishing without errors. According to Piaget, Child B’s method shows:","options":["Pre-operational intuitive judgement based on how the sticks look","Operational seriation, typical of the concrete operational stage","A tertiary circular reaction, experimenting to see what happens","Bruner’s iconic mode, picturing the sticks in order"],"answer":1,"explanation":"Systematic seriation treats each stick as longer than those before it and shorter than those after it, an operational relation. Trial-and-error ordering is typical of the pre-operational stage.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-928","question":"A child is shown two identical green fields, each with a cow and the same number of small houses. In one field the houses are bunched in a corner; in the other they are scattered. She says the cow in the bunched field has more grass to eat. She has not yet acquired:","options":["Object permanence","Seriation","Conservation of area","Hierarchical class inclusion"],"answer":2,"explanation":"The uncovered area is equal in both fields, but scattered houses look as if they cover more. Conservation of area is normally acquired in the concrete operational stage.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-929","question":"A Class 2 child knows that 7 + 5 = 12, but when asked 12 − 5, she starts counting back on her fingers from 12 and does not see the link. Piaget would say she has not yet fully developed:","options":["Animistic thinking","Object permanence","Seriation of numbers","Reversibility"],"answer":3,"explanation":"Reversibility means seeing that one operation can be undone by its inverse, so that 12 − 5 must give back 7. Without it, each fact is treated separately.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-930","question":"Asked, ‘Are you a Delhiite and an Indian at the same time?’, a five-year-old says, ‘No, I’m from Delhi, not India.’ A nine-year-old says, ‘Yes, because Delhi is in India.’ The difference best reflects the development of:","options":["Class inclusion","Conservation of volume","Object permanence","Deferred imitation"],"answer":0,"explanation":"Piaget found that young children cannot place one class (Delhi) within a larger one (India); understanding nested categories develops with concrete operations.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-931","question":"A 15-year-old in a Class 10 debate passionately describes how India would be with no pollution and no corruption, and criticises adults for not making it happen. In Piaget’s cognitive theory, this mainly reflects:","options":["Pre-operational egocentrism, unable to see others’ views","A failure of conservation when ideas change their form","A new ability to reason about ideals beyond reality","Concrete operational seriation of social problems"],"answer":2,"explanation":"Formal operations let adolescents reason about hypothetical worlds, which often shows up as idealism and criticism of the real world. It is not pre-operational egocentrism.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-932","question":"A 16-year-old rides his scooter without a helmet, saying, ‘Accidents happen to others, not to me.’ David Elkind, building on Piaget’s formal operational stage, called this belief:","options":["The imaginary audience","Transductive reasoning","Centration","The personal fable"],"answer":3,"explanation":"The personal fable is the adolescent belief that one’s experiences are unique and that one is invulnerable. The imaginary audience is the belief that everyone is watching oneself.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-933","question":"On a balance beam, a 9-year-old balances weights by trial and error. A 14-year-old explains, ‘Two weights here at distance 3 will balance three weights at distance 2, because 2 × 3 = 3 × 2.’ The older child is using:","options":["Proportional reasoning, a formal operational scheme","Seriation, a concrete operational scheme for ordering","A secondary circular reaction repeated for its effect","Bruner’s enactive mode of representing by action"],"answer":0,"explanation":"Understanding that weight and distance trade off in proportion is one of the formal operational schemes Piaget and Inhelder described. The younger child’s trial and error lacks this.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-934","question":"Consider these statements. 1. Concrete operational children reason mainly from specific experiences towards a general rule. 2. Formal operational thinkers can reason from a general premise to specific conclusions, even about things they have never seen. 3. Concrete operational children cannot reason logically at all. Which is/are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Concrete operational children do reason logically, but about concrete, familiar content and mostly inductively. Hypothetico-deductive reasoning belongs to formal operations, so statement 3 is false.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-935","question":"A baby who has been breastfed tries to suck milk from a spoon in the same way, then slowly changes the shape of her lips to sip from it. Piaget would say that this shows:","options":["Only assimilation, since the same sucking schema is being used","Only accommodation, since the shape of the lips is changing","Equilibration without any adaptation, as the schema stays fixed","Assimilation and accommodation working together in adaptation"],"answer":3,"explanation":"Applying the sucking schema to the spoon is assimilation; adjusting the lips is accommodation. Piaget held that both are present in every act of adaptation, in varying balance.","difficulty":"very-hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-936","question":"A four-month-old learns to look at a rattle and to grasp it as two separate actions. A few weeks later she looks at the rattle and reaches out to grasp it in one smooth action. Piaget’s term for combining separate schemas into a more complex system is:","options":["Accommodation","Organisation","Conservation","Decentration"],"answer":1,"explanation":"Organisation is the tendency to integrate schemas into higher-order structures. Adaptation, made up of assimilation and accommodation, is the other basic function in Piaget’s theory.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-937","question":"In Piaget’s view, how are play and imitation related to assimilation and accommodation?","options":["Play is mainly accommodation; imitation is mainly assimilation","Both are pure accommodation to the demands of reality","Play is mainly assimilation; imitation is mainly accommodation","Both are unrelated to adaptation and serve only for fun"],"answer":2,"explanation":"In symbolic play a stick becomes a horse because the child fits reality to her schemas, so assimilation dominates. In imitation the child changes her own actions to copy a model, so accommodation dominates.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-938","question":"Consider these statements about Piaget’s stages. 1. The order of the stages is the same for all children. 2. Each stage begins at exactly the same age for every child. 3. With good teaching a child can skip the concrete operational stage. Which is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Piaget held the sequence of stages to be invariant, while the ages are only approximate and vary with experience. No stage can be skipped, because each builds on the one before.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-939","question":"Retelling a story in Class 1, a child says, ‘Then he went there and he hit him and it fell down,’ without naming anyone or explaining what ‘it’ was, as if the listener already knew. Piaget would see this as a sign of:","options":["A language disorder needing therapy","Formal operational thought","The concrete operational stage","Egocentrism in communication"],"answer":3,"explanation":"Pre-operational children often fail to take the listener’s perspective, assuming others know what they know. This is normal egocentric communication, not a disorder.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-940","question":"Studies of children from pottery-making families found that they understood conservation of substance with clay earlier than other children of the same age. What does this finding most directly suggest?","options":["Piaget’s stages do not exist at all in other cultures","Experience can affect when a given conservation appears","Conservation depends only on brain maturation, not on experience","Pottery children skip the pre-operational stage entirely"],"answer":1,"explanation":"Familiar materials and activities can bring forward the age at which a concept is shown, which supports the role of experience. It does not show that stages are skipped or absent.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-941","question":"A teacher shows a five-year-old a box of crayons and asks what is inside. The child says ‘crayons’, but the box actually holds candles. Asked what his friend who has not looked inside will think is in the box, he says ‘candles’. Piaget would relate this mainly to:","options":["Conservation of number","Seriation by size","Egocentric thinking","Object permanence"],"answer":2,"explanation":"The child assumes the friend knows what he himself now knows. Piaget described this inability to take another’s perspective as egocentrism; later researchers studied it under ‘theory of mind’.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-942","question":"In a Class 5 EVS lesson, a child correctly answers that a long thin glass and a short wide glass with water poured from the same bottle hold the same amount, but cannot yet predict whether a clay ball and a flattened clay roti will push up water by the same amount when dropped in a beaker. This is consistent with Piaget because:","options":["Volume displacement is conserved years after liquid quantity","Children of this age should already conserve displaced volume easily","Conservation of liquid is a formal operational skill, not a concrete one","The child has lost her earlier ability to conserve under pressure"],"answer":0,"explanation":"Conservation of volume in the sense of displacement typically appears around 11 to 12 years, well after liquid quantity. This is a further example of horizontal décalage.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-943","question":"Which classroom question would a typical Class 2 child (in the late pre-operational or early concrete operational period) find hardest?","options":["‘Which of these two pencils is longer, the red or the blue?’","‘Sort these leaves into big ones and small ones.’","‘Count the mangoes in the basket and tell me.’","‘If all fish could fly and Golu is a fish, can Golu fly?’"],"answer":3,"explanation":"Reasoning from a premise contrary to fact requires formal operational thought. The other tasks need perception, simple classification or counting, which are within reach of young children.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-944","question":"A child believes all heavy things sink. When she sees a huge steel ship floating in the harbour, she says, ‘It floats because it is tired and wants to rest on the water.’ In Piaget’s terms, she has:","options":["Accommodated her schema successfully to fit the floating ship","Assimilated it into existing ideas without changing her schema","Reached formal operations, since she explains an exception to a rule","Used reversibility to undo her earlier belief"],"answer":1,"explanation":"She explains away the conflicting event with an animistic idea instead of revising her schema, so she assimilates rather than accommodates. Disequilibrium is not resolved by real change here.","difficulty":"very-hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-945","question":"Assertion (A): A Class 7 teacher should not assume that all students can follow a purely verbal, abstract explanation of algebraic identities. Reason (R): Many 12-year-olds are still moving from concrete to formal operational thinking.","options":["A is false, but R is true","A is true, but R is false","Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"Around 11 to 12 years, children are only beginning formal operations, and many still need concrete or pictorial support. That is precisely why purely abstract teaching may fail.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-946","question":"How many of these behaviours would Piaget expect in the pre-operational stage? I. Calling the moon ‘alive’ because it follows you. II. Arranging sticks by length systematically on the first try. III. Using a box as a car in pretend play. IV. Judging that a squashed ball of dough has less dough.","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"I (animism), III (symbolic play) and IV (non-conservation) are pre-operational. Systematic seriation in II belongs to the concrete operational stage.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-947","question":"In a pre-primary class in Chennai, a four-year-old cries that her brother has ‘more juice’ after equal amounts are poured into a tall glass for him and a short wide glass for her. What should the teacher understand from this?","options":["The child is being greedy and should be scolded for comparing glasses","Typical pre-operational centration on height, not a behaviour problem","The child probably has a visual problem and needs an eye test soon","The child has learnt to conserve but is pretending otherwise for attention"],"answer":1,"explanation":"Young children judge quantity by one striking dimension such as height and cannot yet conserve. Understanding this helps the teacher respond calmly rather than treating it as misbehaviour.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-948","question":"A school plans to test every child for a ‘visual’, ‘auditory’ or ‘kinaesthetic’ learning style and then teach each child only in that style. What does research most firmly say about this ‘matching’ idea?","options":["It is strongly proven to raise achievement in all subjects and classes","It helps only in primary classes, where children’s styles are clearest","Good studies find little evidence that such matching improves learning","It works only if each child is retested twice a year to confirm the style"],"answer":2,"explanation":"Children do have preferences, but carefully designed studies have not supported the 'meshing' hypothesis that teaching in a learner's preferred style produces better learning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-949","question":"A teacher labels Rahul a ‘kinaesthetic learner’ and therefore gives him only hands-on tasks, excusing him from reading and listening activities. What is the main concern with this practice?","options":["Hands-on tasks are never useful for learning beyond the early classes","It narrows his learning and may hold back his reading and listening","Kinaesthetic learners cannot learn science through hands-on tasks","He will learn too quickly with hands-on tasks and become bored"],"answer":1,"explanation":"Fixing a child into one style restricts exposure to the varied modes that school learning requires. Activity-based tasks help, but not as a replacement for literacy and listening.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-950","question":"Assertion (A): Children often differ in the ways they prefer information to be presented. Reason (R): Therefore, teaching each child only in his or her preferred mode reliably improves achievement.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true","A is true but R is false"],"answer":3,"explanation":"Preferences are real, but the claim that teaching only to them reliably raises achievement is not supported by good evidence, so R is false.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-951","question":"Which approach to modality is best supported for a whole class?","options":["Fit the mode to the content for all, e.g. maps by sight, pronunciation by ear","Split the class by style and teach map reading by listening to the auditory group","Teach everything only through lectures so that all children get equal treatment","Avoid pictures, since they distract the auditory learners in the class"],"answer":0,"explanation":"Evidence favours matching the mode of presentation to the nature of the content, and using multiple representations, for all learners rather than to each learner's supposed style.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-952","question":"Which statement about learning styles is most defensible for a teacher?","options":["Each child has one fixed learning style that does not change with age","Varied representations such as words, pictures and models help most learners","Style questionnaires reliably identify the way in which each child learns best","Learning styles and Gardner's multiple intelligences are the same idea"],"answer":1,"explanation":"Varied, meaningful representations support understanding for most learners. Styles are not fixed traits, questionnaires measure preference rather than effectiveness, and Gardner's theory is about kinds of ability, not modes of input.","difficulty":"hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-child-development-953","question":"Asked which is greater, 0.25 or 0.5, most Class 5 children in a Bhopal school choose 0.25. What does this error most likely reveal and what should the teacher do?","options":["Carelessness; give a written warning to read the questions slowly","Poor memory; make them memorise that ‘0.5 is greater than 0.25’","Lack of intelligence; move them to an easier section for maths","Whole-number thinking; use grids or money models to compare decimals"],"answer":3,"explanation":"Such a widespread error is systematic: children apply a whole-number rule to decimals. Representations like 10×10 grids or ₹0.50 vs ₹0.25 help them see place value.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-954","question":"When asked to write ‘two hundred and five’, Class 2 student Sonu writes 2005. What is the most useful interpretation?","options":["He writes numbers as he hears them, not yet grasping place value","He has a visual processing disorder that reverses the digits","He is not paying attention and needs to be more careful","He has learnt the wrong number names from his family at home"],"answer":0,"explanation":"He records '200' and then '5' side by side as they sound. The error reveals a gap in understanding place value, which can be addressed with place-value cards and bundles of sticks.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-955","question":"A four-year-old who earlier said ‘went’ and ‘mice’ correctly now says ‘goed’ and ‘mouses’. How should this be interpreted?","options":["As regression in language that needs speech therapy","As imitation of the speech of adults around the child","As overregularisation of a newly found grammar rule","As an early sign of a specific learning disability"],"answer":2,"explanation":"Children never hear adults say 'goed'; the error shows active rule construction (add -ed, add -s). It is a normal step before irregular forms are relearnt.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-956","question":"Many Class 6 students write 3/4 + 1/2 = 4/6. Which teacher response best treats the error as a window into thinking?","options":["Mark it wrong and ask them to do twenty more sums of the same kind","Repeat the rule for finding a common denominator, more slowly and loudly","Ask how they got 4/6, then check with fraction strips whether it can be right","Ignore it for now, since they will meet fraction addition again in Class 8"],"answer":2,"explanation":"Probing reveals the misconception (adding numerators and denominators as whole numbers). A concrete check shows that the sum must be greater than 3/4, creating cognitive conflict that motivates the correct method.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-957","question":"A Class 6 student predicts that 8 × 0.5 will be ‘more than 8’, and is puzzled when the answer is 4. Which misconception has she most likely formed, and from where?","options":["‘Decimals are always larger than whole numbers’, picked up from money","‘Multiplication always makes bigger’, overgeneralised from whole numbers","‘Zero is not really a number’, picked up from early counting","‘Division always makes bigger’, carried over from work with fractions"],"answer":1,"explanation":"With whole numbers greater than 1, multiplying always increased the result, so the child over-generalised. Multiplying by a number less than 1 gives a smaller result.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-958","question":"In a Class 1 writing activity, Neeraj writes ‘I go to skool on my sykl.’ What is the most appropriate view of these spellings?","options":["They show he has failed to learn spelling and needs heavy correction in red","They point to a visual memory problem that needs a specialist","They should be ignored entirely, as spelling will sort itself out","Invented spellings that show growing sound awareness, to be built on"],"answer":3,"explanation":"Invented spellings map sounds to letters logically ('skool', 'sykl'), revealing phonemic knowledge. Teachers build on this while steadily introducing standard spellings.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-959","question":"Which of the following errors most deserves careful diagnostic follow-up by a teacher?","options":["A child who makes the same kind of mistake across many similar sums","A child who gets many sums wrong in one test, each with a different slip","A child who leaves the last few sums blank because the period ran out","A child who makes several errors in a test taken on a day she was unwell"],"answer":0,"explanation":"A consistent, repeated error points to one faulty rule or misconception that diagnosis can uncover and correct. Many errors of different kinds look more alarming but suggest haste or inattention rather than a single underlying misconception.","difficulty":"very-hard","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-960","question":"According to the National Curriculum Framework 2005, which of these views of children's errors are correct? I. Errors are a natural part of the learning process. II. Errors can reveal how a child is thinking. III. Errors show that a child cannot learn the topic. IV. Teachers should use errors to plan further teaching rather than only penalise them.","options":["I and III only","II and III only","I, II and IV only","I, II, III and IV"],"answer":2,"explanation":"NCF 2005 describes errors as windows into children's thinking and encourages using them diagnostically. An error does not show inability to learn, so III is false.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-961","question":"Many Class 6 children say that plants get their food from the soil through their roots. What is the best way to address this alternative conception?","options":["Tell them they are wrong and dictate the definition of photosynthesis","Give a test on photosynthesis and deduct marks whenever the wrong idea appears","Avoid discussing it, since the topic will be repeated in Class 10","Explore their reasons and test the idea with plants kept in light and dark"],"answer":3,"explanation":"Alternative conceptions are reasonable to the child and resist mere telling. Making them explicit and testing them with evidence creates conflict that supports conceptual change.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-962","question":"Class 3 student Fatima says, ‘The moon changes shape because clouds cover different parts of it.’ What should the teacher do first?","options":["Ask her reasoning, then have the class observe the moon for a month","Correct her immediately so that others don't pick up the wrong idea","Tell her the topic is beyond her age and will come in later classes","Praise her creativity warmly and move on to the next question"],"answer":0,"explanation":"Her idea is a reasoned explanation from experience. Understanding the reasoning and providing observation that challenges it helps her reconstruct a better explanation.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-963","question":"Match each factor affecting learning with its category. P. Maturation of fine motor muscles  Q. Noise from a nearby construction site  R. Use of activity-based methods  S. Test anxiety. 1. Environmental  2. Instructional (teacher-related)  3. Learner-related physical  4. Learner-related psychological","options":["P-3, Q-2, R-1, S-4","P-3, Q-1, R-2, S-4","P-4, Q-1, R-2, S-3","P-1, Q-3, R-2, S-4"],"answer":1,"explanation":"Motor maturation is a physical factor in the learner; outside noise is environmental; teaching method is instructional; anxiety is a psychological factor in the learner.","difficulty":"moderate","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-964","question":"Parents of a three-year-old insist on daily practice in joined-up (cursive) writing, but the child cannot form the letters despite weeks of drill. The most accurate explanation is that:","options":["The child lacks motivation and needs rewards for each attempt","The child has a learning disability such as dysgraphia","Fine motor control is not yet mature, and drill cannot replace readiness","Cursive writing is not taught in Indian schools, so it confuses the child"],"answer":2,"explanation":"Learning depends on maturation: skills that need certain neuromuscular development cannot be produced by drill before that development has taken place.","difficulty":"hard","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-965","question":"A student who has learnt to ride a bicycle finds it easier to learn to ride a scooter, but a driver used to driving on the left in India keeps drifting to the wrong side when driving abroad on the right. These are examples of:","options":["Negative transfer and positive transfer respectively","Zero transfer in both cases","Bilateral transfer and zero transfer","Positive transfer and negative transfer respectively"],"answer":3,"explanation":"Earlier learning that helps new learning (balance on bicycle to scooter) is positive transfer; earlier learning that interferes with new learning (left-side habit) is negative transfer.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-966","question":"In Judd's classic study, two groups of boys practised throwing darts at a target under water. Only one group was taught the principle of refraction. When the depth of the target was changed, that group adjusted much faster. Which theory of transfer does this support?","options":["Generalisation: transfer occurs when learners grasp an underlying principle","Identical elements: transfer occurs only with identical stimuli and responses","Formal discipline: any hard practice trains the mind","Law of disuse"],"answer":0,"explanation":"Judd's theory of generalisation holds that understanding general principles enables transfer to new situations, which the refraction group showed when conditions changed.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-967","question":"A principal argues that every child should study hard grammar and geometry because ‘they train the mind's faculties of memory and reasoning, which will then improve every other subject’. This reflects which theory, and what is its status?","options":["Theory of identical elements, which is widely accepted by researchers","Formal discipline, which Thorndike's experiments largely failed to support","Gestalt theory of transposition, which has been fully proven in classrooms","Theory of generalisation, which says any study improves all faculties"],"answer":1,"explanation":"Formal discipline treats the mind as muscles trained by tough subjects. Thorndike's studies found little general improvement; transfer depends on shared elements or principles.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-968","question":"Which teaching practice is most likely to promote transfer of learning to new situations?","options":["Practising one type of example many times in exactly the same form","Teaching facts in isolation and testing them word for word for accuracy","Teaching principles and practising them in varied, real-life contexts","Avoiding discussion of how a concept applies outside the textbook"],"answer":2,"explanation":"Transfer is helped by understanding principles, varied practice and explicit links to new contexts; narrow, identical practice tends to produce knowledge tied to one setting.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-969","question":"Many children in a tribal block of Madhya Pradesh who speak Bhili at home struggle in Class 1 lessons taught only in English. Which factor affecting learning is most directly involved, and what do NCF 2005 and NEP 2020 recommend?","options":["Low intelligence; place them in remedial classes until they catch up","Lack of parental interest; hold parent meetings to motivate the families","Poor eyesight; arrange eye check-ups for all children in the class","Home–school language mismatch; use the home language in early years"],"answer":3,"explanation":"Learning is hindered when instruction is in a language the child does not understand. Both NCF 2005 and NEP 2020 recommend the home language or mother tongue as medium in the early years where possible.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-970","question":"Rekha understands percentages well at home but freezes in maths tests, making errors she would not otherwise make. Research suggests that maths anxiety mainly harms performance by:","options":["Filling working memory with worry, leaving less room for the problem","Erasing what is stored in long-term memory about percentages and rules","Lowering the child's measured intelligence permanently over time","Raising her speed so much that accuracy drops a little"],"answer":0,"explanation":"Anxious, intrusive thoughts compete for limited working memory, so complex problems suffer most; the knowledge itself is still present, as her performance at home shows.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-971","question":"After weeks of practising writing with his right hand, a student finds that his left-hand writing has also improved somewhat, though he never practised with it. This is called:","options":["Negative transfer","Zero transfer","Retroactive interference","Bilateral transfer"],"answer":3,"explanation":"Bilateral transfer is transfer of a skill from one side of the body to the other, showing that some of what is learnt is central rather than tied to a particular limb.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-child-development-972","question":"Several Class 2 children in a Bihar school become drowsy and inattentive by mid-morning. A health check finds many are anaemic. Which statement best captures the link to learning?","options":["Anaemia affects only physical growth, not attention or learning","Health and nutrition directly affect attention, energy and learning","Drowsiness shows that the children are not interested in studies","The teacher should give more homework to improve concentration"],"answer":1,"explanation":"Health and nutrition, including iron deficiency, affect alertness and cognitive functioning. Addressing them, for example through the mid-day meal and supplementation, supports learning.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-973","question":"Parents of a Class 1 child with a benchmark disability want her to study in their neighbourhood school. The school insists that she ‘belongs in a special school’. Which position matches the RPwD Act, 2016?","options":["The family chooses: a neighbourhood school or a special school, free of cost","The school decides, since it knows best what support it can give her","A medical board must decide which type of school she attends","She may attend the neighbourhood school only if her disability is below 60%"],"answer":0,"explanation":"The Act gives every child with a benchmark disability aged 6–18 the right to free education in a neighbourhood school or a special school of her choice, so the school cannot push her out.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-974","question":"To ‘build his confidence’, a Class 4 teacher makes Karan, who has dyslexia, read a new passage aloud in front of the class every day. He now pretends to be ill on reading days. What would be a better practice?","options":["Letting him preview and practise the passage, and join choral reading","Continuing daily public reading, since avoidance must not be rewarded","Stopping all reading practice for him until he feels ready","Asking classmates to correct each error aloud so that he learns faster"],"answer":0,"explanation":"Unprepared public reading exposes a child's disability and creates anxiety and avoidance; preparation, private practice and choral reading build fluency without humiliation.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-975","question":"Sameer, in Class 6, stammers. When he answers, classmates giggle and the teacher often completes his sentences to save time. Which teacher behaviour is most appropriate?","options":["Waiting calmly for him to finish, and addressing the giggling with the class","Telling him each time to slow down and take a deep breath before he speaks","Avoiding asking him questions in class so that he is not embarrassed","Finishing his words for him, so that he is not left stuck in front of others"],"answer":0,"explanation":"Patient, natural listening reduces pressure on a child who stammers; repeated advice to slow down, finishing his words or never asking him all signal that his speech is a problem and reduce participation.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-976","question":"Which of these statements about hearing aids in the classroom are correct? I. A hearing aid restores normal hearing, just as glasses restore clear vision. II. Hearing aids amplify background noise too, so classroom noise control matters. III. A child with hearing aids should be seated away from noisy fans, windows facing the road and corridors.","options":["II and III only","I and II only","I and III only","All of I, II and III"],"answer":0,"explanation":"Hearing aids amplify sound but do not restore normal hearing, and they make background noise louder too; so seating away from noise and keeping the room quiet are essential.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-977","question":"Asked about an elephant, Ravi, a blind Class 3 student, gives a fluent description copied from a story (‘huge, grey, with a trunk like a snake’), but on questioning he has no real idea of its size or shape. This is called verbalism. What is the best remedy?","options":["Making him memorise more precise definitions of each animal","Giving him hands-on experience with models and real objects","Avoiding topics about things he cannot touch for himself","Asking him to stop using colour words he cannot understand"],"answer":1,"explanation":"Verbalism is using words without the underlying experience; blind children need concrete, tactile and real experiences so that concepts have meaning, not more memorised descriptions.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-978","question":"Parents of Bunty, a 9-year-old with intellectual disability, dress him, feed him and carry his bag, saying ‘he cannot do it’. In school he waits for adults to do everything. What should the teacher do?","options":["Continue doing tasks for him in school too, since that is what he is used to","Report the parents to the authorities for overprotecting their child","Teach self-help skills step by step, and have parents practise them at home","Leave him alone to struggle so that he learns through failure"],"answer":2,"explanation":"Overprotection can produce learned helplessness; systematic teaching of self-help skills, shared with the family for consistency, builds independence.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-979","question":"Aditi, in Class 4, solves Class 7 level mathematics but is emotionally young and is happy with friends of her age. Which provision is most suitable for her?","options":["Subject acceleration or enrichment in maths, staying with age-peers otherwise","Promoting her straight to Class 7 in all subjects, to match her maths level","Giving her more Class 4 sums to keep her busy and practised","Waiting until she is older and more mature before offering any challenge"],"answer":0,"explanation":"Her advanced ability is in one subject and she is socially young; subject-specific acceleration or enrichment meets her need without the social cost of a full grade skip.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-980","question":"Asked how a city could reduce traffic jams, a Class 6 student suggests staggering school and office timings. The teacher marks it wrong because the textbook lists only ‘build flyovers’ and ‘use public transport’. What is the main concern?","options":["The student should have copied the textbook answer as given","The teacher should give zero marks to discourage guessing in exams","Such answers should be accepted only from toppers who know the basics","Rejecting a sound, original answer discourages divergent thinking"],"answer":3,"explanation":"Creative and gifted learners often give valid answers outside the book; treating only textbook answers as correct suppresses originality.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-981","question":"Which statement correctly describes the relationship between Universal Design for Learning (UDL) and differentiated instruction (DI)?","options":["They are the same thing, simply described under different names","UDL is used only for students with disabilities, DI only for the gifted","UDL builds in options for all at planning; DI responds to known students","DI replaces UDL once the teacher has got to know her students well"],"answer":2,"explanation":"UDL is proactive design for learner variability, and DI is responsive adjustment for known students; good teachers use both, for all learners.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-982","question":"In a school examination, Arjun, who is blind, is given a scribe. While writing, the scribe rephrases Arjun’s answers into better language and adds a point Arjun missed. Which statement is correct?","options":["This is acceptable, since the scribe is only helping Arjun express his ideas better","The scribe must write exactly what Arjun dictates, adding or improving nothing","The scribe should write only the main points, to save examination time","This is acceptable as long as the teacher is informed about it later"],"answer":1,"explanation":"A scribe removes the barrier of writing, not of knowing; adding or improving content changes what is being assessed and is unfair to the candidate and others.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-983","question":"A Class 2 teacher promises Rohit, who has ADHD, a reward at the end of the month if he stays in his seat. The plan fails. Which change is most likely to work?","options":["Making the reward bigger and keeping it at the end of the month","Removing all rewards, since they spoil children and lower effort","Small, immediate rewards after each short task, gradually spaced out","Punishing him each time he leaves his seat, so he learns the rule"],"answer":2,"explanation":"Children with ADHD find delayed rewards hard to work for; immediate, frequent reinforcement shapes behaviour, after which reinforcement can be thinned.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-984","question":"Kiran, a Class 1 child with autism, refuses writing tasks but loves building blocks. The teacher shows a card with two pictures: ‘First: writing → Then: blocks’. Why does this strategy work?","options":["It punishes him for refusing to do the writing task","It removes the writing task from his day altogether","It is a form of acceleration for an able learner","It is visual and uses a liked activity to motivate"],"answer":3,"explanation":"A ‘first–then’ board gives clear visual structure and links a non-preferred task to a preferred one (the Premack principle), which suits many autistic learners.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-985","question":"Which of these statements about autism are correct? I. Autism is caused by cold, unaffectionate parenting. II. Autism is a spectrum, so autistic children differ widely from one another. III. Many autistic children have uneven profiles, with strong skills in some areas. IV. Childhood vaccines cause autism.","options":["I and II only","II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"The spectrum and uneven profiles are well established; the ‘cold parenting’ and vaccine claims are myths rejected by research.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-986","question":"Durga, a Class 5 girl with low vision, belongs to a Scheduled Tribe and lives in a remote hamlet far from school. Her teacher plans support only for her vision. What is the main weakness of this plan?","options":["It ignores how distance, gender, language and poverty add to her disability","It gives her too much support compared with other children in the class","Disability support is not a teacher’s job but a specialist’s","Children from tribal communities need no special support beyond what others get"],"answer":0,"explanation":"Disadvantages overlap and compound; a girl with a disability from a marginalised, remote community needs support for transport, language and social barriers too, not just vision.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-987","question":"Teacher P gives every child the same book and the same 20 minutes for a reading task. Teacher Q gives the same book to all, but adds a large-print copy for a child with low vision, extra time for a child with dyslexia and a picture glossary for a new Hindi learner. Which statement is correct?","options":["P is fair and Q is unfair, since Q treats the children differently","Both are equally fair, since all children get the very same book","Both are unfair, since no child should ever get extra help","P gives equality of treatment; Q gives equity of support"],"answer":3,"explanation":"Equality gives everyone the same; equity adjusts support so that every child has a fair chance to reach the shared goal, which is the basis of inclusion.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-988","question":"Rani, from a village in Bihar, speaks Hindi with Bhojpuri features. Her teacher often says in class, ‘That is wrong Hindi; speak properly.’ What is the most appropriate view?","options":["The teacher is right, because dialects are incorrect forms of the language","Rani should be asked to stop speaking in class until her Hindi improves","Respect her rule-governed dialect and add standard Hindi alongside it","The teacher should switch to teaching only in Bhojpuri for her sake"],"answer":2,"explanation":"Calling a child's home speech ‘wrong’ hurts identity and participation; dialects follow their own rules, and standard forms are best added alongside them.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-989","question":"Many parents of first-generation learners in a school are daily-wage workers who never attend parent–teacher meetings held at 11 a.m. on working days. Teachers conclude that ‘these parents don’t care’. Which step is most appropriate?","options":["Sending more written circulars insisting that the parents attend","Meeting at flexible times, visiting homes, and talking rather than writing","Stopping communication with these parents until they show interest","Reporting low attendance at meetings in the children’s report cards"],"answer":1,"explanation":"The barrier is timing and literacy, not lack of care; flexible scheduling and oral or face-to-face contact make partnership possible.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-990","question":"Many children in a Class 5 class live in one-room homes in a nearby slum and have no space or light to study in the evening. Which school-level step is most helpful?","options":["Giving them more homework so that they get used to studying at home","Opening a school room for supervised study after school hours","Advising parents to buy study tables and lamps for their children","Lowering expectations for these children in tests and homework"],"answer":1,"explanation":"Providing a space to study removes a concrete barrier created by poverty; more homework or lower expectations would only widen the gap.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-991","question":"A Class 6 teacher notices that she mostly calls on the same few ‘bright’ students and moves on quickly when others hesitate. Which practice best makes her questioning equitable?","options":["Picking students at random, e.g. with name sticks, and giving all wait time","Asking only those who raise their hands, so no one feels pressured","Asking low achievers only easy recall questions to build their confidence","Giving the bright students harder questions so that the rest can listen and learn"],"answer":0,"explanation":"Random selection and adequate wait time signal that every student is expected to think and answer; taking only volunteers or easy questions for some lowers expectations.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-992","question":"For the annual day drama, a Class 5 teacher gives Hari, who is blind, only a singing role, explaining that ‘blind people are naturally musical’. How should this be judged?","options":["It is appropriate, since it makes good use of his natural gift","It is appropriate, since blind children cannot act on a stage safely","It is acceptable, provided Hari agrees to sing rather than act","It is a ‘positive’ stereotype; his own interests should decide the role"],"answer":3,"explanation":"Assuming a talent because of a disability is still stereotyping; a blind child can act with orientation and cues, and his own interest should decide his role.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-993","question":"Some parents learn that a Class 3 child is living with HIV and demand that he be removed from the class. What should the school do?","options":["Remove the child quietly to avoid conflict with other parents","Seat the child separately and give him his own utensils, as a precaution","Keep him in class, keep it confidential, and correct the parents’ fears","Ask the child’s parents to move him to another school for his own good"],"answer":2,"explanation":"HIV does not spread through sharing classrooms, play or food, and the law prohibits discrimination in education against persons living with HIV; separating him would be discrimination.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-994","question":"Bablu, a Class 4 child with epilepsy, has a seizure during class, falling and jerking. What should the teacher do?","options":["Hold his limbs firmly to stop the jerking and prevent injury","Cushion his head, turn him on his side, and put nothing in his mouth","Put a spoon in his mouth so that he does not bite his tongue","Splash water on his face to bring him round as quickly as possible"],"answer":1,"explanation":"Safe seizure first aid protects the child from injury and keeps the airway clear; restraining him or putting objects in the mouth can cause harm.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-995","question":"To teach Neeraj, a child with intellectual disability, to tie his shoelaces, the teacher first does every step herself except the last, which Neeraj completes; then she leaves the last two steps to him, and so on. This technique is called:","options":["Forward chaining","Shaping","Fading of prompts","Backward chaining"],"answer":3,"explanation":"Backward chaining teaches the final step first, so the child always completes the task and experiences success; forward chaining starts with the first step.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-996","question":"Assertion (A): When students in a Class 7 project choose different products, such as a model, a skit or a report, the teacher should assess all of them against the same learning goals. Reason (R): The product is only a means of showing learning; the learning outcome is what is being assessed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Choice of product is a differentiation of how learning is shown; a common rubric tied to the learning goals keeps assessment fair across different products.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-997","question":"In a Class 4 class in Assam with Bodo, Assamese and Bengali speakers, the teacher puts up a science word wall showing each new term in all three languages, along with pictures. What is the main benefit of this practice?","options":["It lets the teacher avoid teaching the standard scientific terms","It is useful only for children who are weak in their studies","It uses home languages as resources to link new terms to known words","It slows down learning, since children get confused by multiple languages"],"answer":2,"explanation":"Using several languages visibly values every child's language and helps concept learning; multilingualism is a resource, not a source of confusion.","difficulty":"moderate","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-998","question":"In a Class 5 lesson on fractions, which activity draws MAINLY on interpersonal intelligence in Gardner’s sense?","options":["Students sort fraction cards into equivalent groups on their own","In pairs, students argue out which fraction is larger until they agree","Students fold paper strips to make halves, quarters and eighths","Students write a short reflection on what they found confusing today"],"answer":1,"explanation":"Interpersonal intelligence concerns understanding and working with others; pair explanation and resolving disagreements uses it most. Folding draws on spatial and bodily skills, and private reflection on intrapersonal intelligence.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-999","question":"Gardner defines an intelligence as a biopsychological potential to process information that can be activated in a cultural setting to solve problems or create products that are valued in a culture. Which part of this definition most clearly departs from the traditional IQ view?","options":["The idea that intelligence involves processing information of many kinds","The idea that intelligence has a biological basis in the brain","The idea that it includes creating products valued in a culture","The idea that intelligence can be measured by a single number"],"answer":2,"explanation":"Traditional IQ views focus on solving test problems and largely ignore cultural context; Gardner’s inclusion of culturally valued products (a song, a map, a crafted object) is the key departure. The last option is the traditional view itself.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1000","question":"A Bharatanatyam student in Chennai performs a dance-drama that tells a story from the Ramayana, keeping rhythm with the music, moving across the stage space and expressing the characters’ emotions. In Gardner’s framework, this is best described as:","options":["Pure bodily-kinaesthetic intelligence, with no other intelligence involved","An activity that mainly shows logical-mathematical intelligence at work","Evidence that one general intelligence controls all of her performance","Several intelligences working together, e.g. bodily, musical, spatial"],"answer":3,"explanation":"Gardner stresses that intelligences are relatively independent but usually work in combination in real tasks; a dance-drama blends movement, rhythm, use of space and understanding of characters.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1001","question":"Following Gardner’s idea of ‘intelligence-fair’ assessment, which is the most suitable way to assess a Class 4 child’s spatial intelligence?","options":["Ask her to find a spot in the school using a sketch map, or build a model from a picture","Ask her to write a detailed paragraph describing the layout of her house and the street outside","Give her a multiple-choice vocabulary test on the names and properties of shapes","Ask her to recite the eight directions in order and explain each one aloud"],"answer":0,"explanation":"Gardner argued that intelligences should be assessed through their own medium rather than through language and logic; reading a map or building from a picture taps spatial ability directly.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-1002","question":"Bhanwar, 13, from a village near Jaisalmer, sells handicrafts to tourists, bargains skilfully in three languages and keeps accurate accounts, yet scores below average on a standard IQ test. According to Sternberg, the most likely reason is that:","options":["His real intelligence is low, and the bargaining skill is merely a habit picked up through repetition","Conventional IQ tests mainly tap analytical ability and miss the practical intelligence he uses daily","IQ tests mainly measure creative intelligence, and his trade relies on routine rather than creativity","He has high emotional intelligence, and strong emotional skills tend to pull IQ scores down"],"answer":1,"explanation":"Sternberg argued that IQ tests concentrate on analytical problems with one right answer and neglect practical (and creative) intelligence, which predicts success in everyday contexts.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1003","question":"A newly appointed teacher in a Shillong school gradually learns, without anyone telling her directly, how to talk to anxious parents, which senior colleague to approach for leave and how to calm a restless class after lunch. Sternberg would call this kind of unspoken, experience-based know-how:","options":["Crystallised intelligence","Metacomponents","Tacit knowledge","Convergent thinking"],"answer":2,"explanation":"Sternberg’s research on practical intelligence highlights tacit knowledge: action-oriented knowledge acquired from experience, usually not formally taught or even put into words.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1004","question":"Assertion (A): When Thurstone’s primary mental abilities were tested in larger groups, the abilities were found to be positively correlated with one another. Reason (R): Such correlations among abilities lend some support to the existence of a general factor of intelligence.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true: the primary abilities did correlate, and Thurstone accepted a second-order general factor. But R is a conclusion drawn from A, not the explanation of why A happened.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1005","question":"Which statement about the relation between IQ and school achievement is most accurate?","options":["IQ scores predict school marks almost perfectly, so other factors add very little to the prediction","IQ and school achievement are unrelated, since marks depend only on effort and teaching","IQ is the only factor that schools need to consider when grouping and guiding students","IQ correlates moderately with achievement, so motivation, teaching and home support also matter"],"answer":3,"explanation":"IQ is one of the better single predictors of school performance, but a moderate correlation leaves most of the variation to effort, interest, teaching quality, health and home conditions.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1006","question":"Which practice most directly builds emotional literacy among Class 2 children?","options":["Using a feelings chart where children name how they feel and discuss what helps when angry or sad","Telling children that crying in school is a weakness so that they learn to control themselves","Keeping emotions out of class and focusing on the syllabus so that children stay calm and busy","Punishing children who show anger in class so that the others learn which feelings are unacceptable"],"answer":0,"explanation":"Emotional literacy starts with recognising and naming feelings and learning strategies to manage them; suppressing or punishing emotions teaches avoidance, not regulation.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1007","question":"Which of the following statements about creativity are correct? I. Creativity is limited to the arts such as painting and music. II. Creativity can be fostered through suitable teaching and classroom climate. III. A creative product is usually both novel and appropriate or useful in its context. IV. Only a few geniuses are creative.","options":["II and III only","I and IV only","I, II and III only","II, III and IV only"],"answer":0,"explanation":"Creativity appears in every field, including science and everyday problem-solving, and in all children to some degree; it can be nurtured, and it requires both novelty and appropriateness.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1008","question":"For a science fair, a Class 8 group first lists twenty possible projects on reducing plastic waste and then judges them on cost, time and safety to choose the single most practical one. The second step mainly involves:","options":["Divergent thinking","Incubation","Convergent thinking","Functional fixedness"],"answer":2,"explanation":"Creative problem-solving alternates: divergent thinking generates many options, and convergent thinking evaluates them to choose the best one. Choosing a single project is the convergent phase.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1009","question":"A school announces large cash prizes for the ‘most creative’ collage, to be judged strictly by a panel, and repeatedly reminds students that they will be judged. What does research on motivation and creativity (for example, Teresa Amabile’s work) suggest?","options":["Expected evaluation and rewards reliably increase creativity, because children try much harder for prizes","Rewards affect effort on routine tasks but have no effect at all on creative work","Creativity depends mainly on IQ, so the prizes and judging will make little difference either way","Heavy emphasis on expected evaluation and reward can lower creativity; intrinsic interest supports it"],"answer":3,"explanation":"Amabile’s research found that working mainly for expected evaluation or reward often reduces the creativity of the products, whereas intrinsic motivation, enjoyment of the task itself, supports it.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1010","question":"In Françoys Gagné’s model of giftedness and talent, what is the difference between a ‘gift’ and a ‘talent’?","options":["A gift is excellence acquired through schooling, while a talent is an inborn ability present from birth","A gift is outstanding natural ability; a talent is outstanding skill developed from it through learning","Both terms mean the same thing, since Gagné used them interchangeably for very high ability","A gift refers to ability in academic subjects, while a talent refers only to sports and the arts"],"answer":1,"explanation":"Gagné’s model separates natural abilities (gifts) from systematically developed skills (talents); the development depends on learning, motivation and environment, so a gift does not automatically become a talent.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1011","question":"In a mixed-ability Class 7 classroom, a teacher gives all students the same topic, the water cycle, but three versions of the task: labelling a diagram, explaining the process in a flow chart, and predicting the effect of deforestation on local rainfall. This strategy is called:","options":["Tiered assignments","Grade skipping","Rote drill","Norm-referenced grouping"],"answer":0,"explanation":"Tiered assignments keep the same core content but vary complexity, letting gifted and struggling learners work at suitable levels of challenge within one class.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1012","question":"Which of the following statements about poverty-related factors and children’s learning are supported by research? I. Chronic malnutrition in early childhood can affect cognitive development. II. Midday meals can improve attendance and attention in class. III. Children from poor families are less intelligent by birth. IV. Stress and lack of learning materials at home can depress school performance.","options":["I and III only","II and III only","I, II and IV only","I, II, III and IV"],"answer":2,"explanation":"Nutrition, school meals, stress and home resources affect learning; but lower average scores reflect these conditions, not an inborn lack of intelligence, so III is false.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1013","question":"Most children in a Class 3 in rural Madhya Pradesh are first-generation learners whose parents have not been to school. Which homework practice is most appropriate?","options":["Set homework that needs parents’ help every evening, so that families become closely involved in learning","Give tasks children can do alone, linked to daily life, with in-school support for those who need it","Give no homework at all, since these children have nobody at home who can guide their learning","Punish children who come without homework, so that they develop regular study habits early"],"answer":1,"explanation":"Homework that assumes educated parents disadvantages first-generation learners; independent, meaningful tasks plus in-school support keep expectations high without penalising home circumstances.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1014","question":"In a village school, a few children from a particular caste group are made to sit separately and are rarely asked questions. Which statement best describes the teacher’s responsibility?","options":["Follow local custom on seating to avoid trouble in the village, while teaching them the same lessons","Seat these children separately but give them extra homework so that they can catch up on their own","Wait for the parents to complain formally before acting, since seating is a community matter","Ensure they sit with everyone and take full part, since such discrimination violates the RTE Act"],"answer":3,"explanation":"The RTE Act requires that children from weaker and disadvantaged groups not be discriminated against; segregation also teaches all children that some deserve less, damaging self-esteem and learning.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1015","question":"Ji-woo, a Korean child, joined a Delhi school a year ago. She chats easily in English with classmates in the playground but struggles to understand her science textbook and write answers in English. In Jim Cummins’s terms, she has developed:","options":["Cognitive academic language proficiency (CALP), but not yet basic interpersonal communicative skills (BICS)","Neither BICS nor CALP","Native-like proficiency in all areas","Basic interpersonal communicative skills (BICS) but not yet cognitive academic language proficiency (CALP)"],"answer":3,"explanation":"Cummins found that everyday conversational fluency (BICS) develops within about 1–2 years, while the academic language needed for textbooks and writing (CALP) takes several more years.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1016","question":"Jim Cummins’s ‘linguistic interdependence’ hypothesis is most often used to support which educational practice?","options":["Banning the home language in school so that children are pushed to learn the second language faster","Teaching only in the home language throughout schooling and never introducing a second language","Strong mother-tongue-based early education, since concepts and literacy built in the first language transfer","Postponing all reading until children are fluent in English, so that literacy starts in a single strong language"],"answer":2,"explanation":"Cummins proposed a common underlying proficiency: knowledge and literacy built in the first language support learning in the second, so strengthening the home language helps, rather than hinders, second-language learning.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-1017","question":"Gond children in a residential school are fined for speaking their own language. Within a few years many can no longer talk comfortably with their grandparents, though their Hindi is still weak. In Wallace Lambert’s terms, this is:","options":["Subtractive bilingualism","Additive bilingualism","Balanced bilingualism","Simultaneous bilingualism"],"answer":0,"explanation":"In subtractive bilingualism a second language replaces the first, often with cultural and cognitive costs; additive bilingualism adds a new language while the first is maintained and valued.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1018","question":"Basil Bernstein distinguished a ‘restricted code’ and an ‘elaborated code’ of speech, linking them to social class. What is the most common criticism of how these ideas were used in education?","options":["They showed that children of all social classes use language in essentially the same way","They were used to portray working-class children’s speech as deficient rather than merely different","They proved that working-class children are unable to learn abstract concepts at school","They led schools to teach only in children’s home dialects and to drop the standard language altogether"],"answer":1,"explanation":"Critics such as Labov argued that treating the restricted code as inferior confused difference with deficit and blamed children’s language for school failure that came from school practices.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1019","question":"Neha, who loves physics and does well in it, is told by the school counsellor before Class 11 to take humanities because ‘science is too demanding for girls and humanities suits them’. The most appropriate evaluation is that:","options":["The advice is sound because girls generally find physics harder and less suited to their natural interests","The advice is neutral, because the counsellor only suggested an option and did not force her","The advice reflects gender stereotyping; Neha’s interests, aptitude and goals should guide her choice","The advice is correct because careers in science and engineering are not suitable for women"],"answer":2,"explanation":"Steering students by gender rather than interest and ability narrows their options and reproduces stereotypes; guidance should be based on the individual.","difficulty":"moderate","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1020","question":"Which of the following is NOT one of the five guiding principles of the National Curriculum Framework 2005?","options":["Connecting knowledge to life outside the school","Making the textbook the sole basis of teaching and assessment so that standards stay uniform","Making examinations more flexible and integrated with classroom life","Enriching the curriculum to provide for the overall development of children rather than remaining textbook-centric"],"answer":1,"explanation":"NCF 2005 explicitly wants the curriculum to move beyond textbooks; its other principles are shifting learning away from rote methods and nurturing an identity informed by caring concerns within the democratic polity.","difficulty":"hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1021","question":"A teacher says, ‘My job is to pour knowledge into children, who come to me as empty vessels.’ NCF 2005 would counter this mainly by holding that:","options":["Children should learn only from their peers, since teachers’ explanations make them passive","Teachers should never explain anything and should leave children to discover everything alone","Knowledge is fixed, and the teacher’s role is to transmit it as efficiently and completely as possible to all","Children actively construct knowledge by linking new ideas to experience, and the teacher facilitates"],"answer":3,"explanation":"NCF 2005 takes a constructivist view: the child is an active constructor of knowledge, not a passive receiver, and the teacher is a facilitator, which does not mean giving up explanation altogether.","difficulty":"moderate","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-1022","question":"According to NCF 2005, the main goal of mathematics education in school is:","options":["Mathematisation of the child’s thinking: the ability to handle abstraction, reasoning and problem-solving","Speed in computation and memorising multiplication tables, as the foundation of all later work","Preparing every child for higher mathematics at university, since mathematics is the gateway to most careers","Scoring high marks in board examinations, which open doors to further education and careers"],"answer":0,"explanation":"NCF 2005 calls ‘useful’ numeracy the narrow aim and the mathematisation of the child’s thought processes the higher aim; computation speed is only a small part of it.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1023","question":"In a Class 3 classroom in Delhi, children speak Bhojpuri, Bengali, Haryanvi and Hindi at home. In line with NCF 2005, the teacher should:","options":["Ban home languages in class so that children pick up standard Hindi faster","Allow home languages only during the lunch break, keeping lessons in Hindi","Use the children’s languages as a resource, letting them compare words across languages","Place children in separate sections by home language so each group is taught easily"],"answer":2,"explanation":"NCF 2005 treats multilingualism as a resource for learning and identity; suppressing home languages silences children and slows learning of the school language itself.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1024","question":"How does NCF 2005 recommend environmental studies (EVS) be handled at the primary stage?","options":["As separate science and social science textbooks from Class 1, so that subject concepts are built from the start","Within language and maths in Classes 1–2, and as integrated EVS (science plus social science) in Classes 3–5","Not taught at all until Class 6, as young children first need to master reading and arithmetic","Only as an activity period, without any textbook or assessment, from Class 1 right up to Class 5"],"answer":1,"explanation":"NCF 2005 integrates EVS concerns into language and maths in Classes 1–2 and teaches EVS as an integrated area of science and social science in Classes 3–5; separate subjects begin later.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1025","question":"Several Class 5 children say that heavier objects always fall faster. NCF 2005 would view this answer as:","options":["A sign of carelessness that should be corrected firmly so it is not repeated","An error to be marked wrong and quickly replaced with the correct statement","Evidence that these children are not yet ready to learn science concepts","A window into their thinking that the teacher can build on through activities"],"answer":3,"explanation":"NCF 2005 sees children’s errors and alternative ideas as starting points for teaching; simply marking them wrong leaves the misconception untouched.","difficulty":"moderate","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-1026","question":"Assertion (A): NCF 2005 recommends that the textbook should not be treated as the only source of knowledge. Reason (R): NCF 2005 sees learning as connected to children’s local environment, experiences and many sources beyond the book.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because NCF 2005 links learning to life outside school and to varied sources, it rejects textbook-centric teaching; R gives the reason for A.","difficulty":"very-hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1027","question":"The Yash Pal Committee report ‘Learning Without Burden’ (1993), on which NCF 2005 drew, argued that the real burden on children is:","options":["The physical weight of the school bag, which harms children’s posture and health","The burden of not understanding: too much information with too little comprehension","The number of school holidays, which breaks the continuity of learning through the year","Too many periods of games and PE, which leave little time for academic study"],"answer":1,"explanation":"The report pointed beyond the heavy bag to the deeper burden of non-comprehension, where children are made to memorise information they do not understand.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1028","question":"Which of these reflect NCF 2005’s approach to the social sciences? I. Including the perspectives of marginalised groups such as women, Dalits and Adivasis. II. Teaching the subject as a collection of facts and dates to be memorised. III. Treating gender as a concern that cuts across all topics. IV. Helping students think critically about democratic institutions.","options":["I and II only","II and III only","I, III and IV only","I, II, III and IV"],"answer":2,"explanation":"NCF 2005 wants social science to be inclusive, gender-sensitive and critical; it rejects the fact-and-date memorisation approach, so II is wrong.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1029","question":"In a Class 8 civics lesson, a teacher invites students to discuss why women in their area are paid less than men for farm work and what could be done about it. NCF 2005 supports this as an example of:","options":["Critical pedagogy, which helps learners examine social realities and their own experience","Behaviourist drill on civic facts, reinforced by repeating correct answers until they stick","Indoctrination, since the teacher is steering students towards a single political opinion","Rote learning of constitutional articles on equality, applied to a local example"],"answer":0,"explanation":"NCF 2005 favours critical pedagogy: learners discuss real social issues from multiple viewpoints and connect them to their lives, rather than receiving fixed answers.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1030","question":"NCF 2005 recommended that board examinations should:","options":["Be made harder and more selective in order to maintain national academic standards","Be introduced at Class 5 as well, so that children get used to examinations early","Continue to test mainly recall of textbook facts, since this is the fairest method","Test understanding and application rather than rote memory, and cause less stress"],"answer":3,"explanation":"NCF 2005’s examination reform aims at questions that test understanding and competencies and at reducing the fear and stress linked to boards.","difficulty":"moderate","source":"CTET · State TET"},
  {"id":"cdp-child-development-1031","question":"A teacher believes that a good classroom is one where children sit silently and never speak unless asked. NCF 2005 would argue that:","options":["Such a silent classroom is ideal in every subject, since it lets all children concentrate fully on the teacher","Fear-imposed silence stifles questioning; discipline should be participatory and respect children’s agency","Children should be free to do whatever they wish, since any rule restricts their natural growth","Discipline is mainly the job of parents, so teachers should focus only on teaching content"],"answer":1,"explanation":"NCF 2005 links learning to dialogue and questioning and calls for participatory rather than authoritarian discipline; this is not the same as having no order at all.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1032","question":"NCF 2005’s position on art education is that it should be:","options":["An optional hobby for talented children, offered outside regular school hours","Taught mainly in Classes 9 and 10, where it can add to board examination marks","A curricular subject at all stages, covering music, dance, visual arts and theatre","Replaced by extra mathematics periods, since art has little value for later careers"],"answer":2,"explanation":"NCF 2005 recommends art education as a regular subject at every stage, valued for aesthetic and cultural development, not as an extra for the gifted.","difficulty":"moderate","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1033","question":"Match each curricular area with the NCF 2005 recommendation for it: P. Language  Q. Mathematics  R. Science  S. Work and education — 1. Multilingualism as a resource  2. Mathematisation of thought  3. Engaging children in inquiry and in the processes of generating knowledge, linked to their environment  4. Productive work as a medium of learning","options":["P-2, Q-1, R-3, S-4","P-1, Q-3, R-2, S-4","P-4, Q-2, R-3, S-1","P-1, Q-2, R-3, S-4"],"answer":3,"explanation":"NCF 2005 links language with multilingualism, mathematics with mathematisation, science with inquiry and the environment, and work education with productive work as pedagogy.","difficulty":"hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1034","question":"NCF 2005 lists criteria for judging a science curriculum. A Class 7 lesson pitched at a level the children can understand has ‘cognitive validity’. A lesson that engages them in observing, experimenting and drawing conclusions to generate knowledge has:","options":["Process validity","Historical validity","Ethical validity","Environmental validity"],"answer":0,"explanation":"Process validity means the curriculum engages learners in the methods by which scientific knowledge is generated; historical validity concerns how science has evolved, ethical validity values such as honesty, and environmental validity the learner’s surroundings.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1035","question":"A teacher always asks boys to carry benches and girls to decorate the classroom. In line with NCF 2005’s concern for gender equality, she should:","options":["Continue, since these tasks suit the natural strengths and interests of each sex","Rotate all tasks among all children regardless of gender and discuss the stereotype","Let parents decide which tasks their children do, to respect family values","Ask only volunteers to do these tasks, so that no child feels forced into one"],"answer":1,"explanation":"NCF 2005 asks teachers to challenge gender stereotypes in everyday school practice; rotating tasks and discussing the issue does both.","difficulty":"hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-1036","question":"Assertion (A): NCF 2005 recommends that the curriculum should connect school knowledge with community knowledge. Reason (R): NCF 2005 holds that knowledge produced in schools is superior to local knowledge and should replace it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"NCF 2005 wants local and community knowledge brought into the classroom and valued, not replaced, so A is true and R contradicts its stance.","difficulty":"very-hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1037","question":"Peace education in NCF 2005 is meant to be:","options":["A perspective infused across subjects and school life, not just a separate subject","A separate examination subject from Class 1, with its own textbook, periods and marks","Moral lectures given in the morning assembly by the principal and teachers","Meant only for schools in regions affected by conflict or communal violence"],"answer":0,"explanation":"NCF 2005 treats education for peace as a perspective running through the curriculum, teaching methods and school ethos.","difficulty":"hard","source":"CTET Paper II · State TET"},
  {"id":"cdp-child-development-1038","question":"According to NCF 2005, environmental education is best handled by:","options":["Making it a separate subject with its own board examination from Class 6","Holding a special lecture and rally every year on World Environment Day","Leaving it entirely to science teachers, as it is mainly a science topic","Infusing it across subjects and linking it to children’s own surroundings"],"answer":3,"explanation":"NCF 2005 (‘habitat and learning’) favours infusing environmental concerns across the curriculum and grounding them in the child’s local environment.","difficulty":"hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1039","question":"Which statement about NCF 2005 and health and physical education is correct?","options":["It may be used as a free period for other subjects in the weeks before examinations","It should be compulsory, as essential to development as the academic subjects","It applies mainly to students selected for school sports teams","It should begin only at the secondary stage, once children are older"],"answer":1,"explanation":"NCF 2005 treats health and physical education as a compulsory curricular area for all children, not as a dispensable period.","difficulty":"hard","source":"CTET · State TET"},
  {"id":"cdp-child-development-1040","question":"‘Nurturing an overriding identity informed by caring concerns within the democratic polity of the country’ is a guiding principle of NCF 2005. Which classroom practice best reflects it?","options":["Celebrating mainly the festivals of the majority community, so that a shared national identity is built","Having students memorise the Preamble word for word and recite it in a test","Discussing a local case of discrimination with empathy, in the light of constitutional equality","Ranking students by their marks in civics to reward good citizenship"],"answer":2,"explanation":"The principle is about caring, empathy and constitutional values lived and examined in real situations; memorising the Preamble is recall, not a caring democratic identity.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1041","question":"A Class 4 teacher in Assam teaches about local bamboo crafts with the help of an artisan from the village. This practice is best described as:","options":["Bringing community knowledge into the classroom, as NCF 2005 recommends","A diversion from the prescribed syllabus, which NCF 2005 discourages","Vocational training, which NCF 2005 reserves for Class 11","An activity suitable only for children weak in academics"],"answer":0,"explanation":"NCF 2005 values local knowledge and community members as learning resources and links them with the school curriculum.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1042","question":"Which of these are consistent with the NCF 2005 view of learning? I. Learning takes place both within and outside school. II. Learning is an active and social process. III. Children’s mistakes should be avoided at any cost. IV. Children’s prior experiences should be the starting point of teaching.","options":["I and III only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"NCF 2005 sees learning as active, social and rooted in experience inside and outside school; mistakes are a natural part of learning, so III is wrong.","difficulty":"very-hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1043","question":"NCF 2005 recommends that English be taught:","options":["Through grammar-translation drills from Class 1 to build accuracy early","Only from Class 6 onwards, once the home language is fully secure","As a replacement for the mother tongue as the medium of instruction as early as possible","Within a multilingual approach, alongside the home language, not replacing it"],"answer":3,"explanation":"NCF 2005 places English within a multilingual framework, building on the child’s home language rather than replacing it.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1044","question":"Which statement reflects NCF 2005’s stance on inclusion?","options":["Children with disabilities should study only in special schools with trained staff","Inclusion means placing all children physically in one room, which by itself is enough to meet their needs","The school should adapt curriculum, teaching and assessment so every child takes part meaningfully","Inclusion is optional and depends on whether the school has resources to spare"],"answer":2,"explanation":"Inclusion in NCF 2005 means the system changes to meet diverse needs; mere physical placement without adaptation is integration at best.","difficulty":"hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1045","question":"Aarav’s parents set clear rules about screen time and homework, explain why the rules matter, listen to his point of view and sometimes adjust a rule after discussion, while remaining warm and affectionate. In Baumrind’s terms, their style is:","options":["Authoritarian","Permissive","Authoritative","Uninvolved"],"answer":2,"explanation":"High warmth plus high, reasoned demands with two-way communication is authoritative parenting. Clear rules alone do not make it authoritarian; authoritarian parents demand obedience without explanation or warmth.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1046","question":"A father enforces strict rules with ‘Because I said so’, punishes disobedience harshly and rarely shows affection or asks his daughter’s views. Research on this style most commonly links it with children who are:","options":["Self-reliant, cheerful and socially confident in new situations","Impulsive and demanding, because they have been given too much freedom","Highly creative and willing to take intellectual risks in class","Obedient but often anxious, withdrawn or lacking in self-reliance"],"answer":3,"explanation":"Authoritarian parenting (high control, low warmth) tends to produce compliance with anxiety and weaker self-direction. Impulsiveness is the typical outcome of permissive parenting.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1047","question":"Very loving parents of a Class 4 boy make almost no demands, let him decide his own bedtime and food, and rarely correct misbehaviour. A teacher notices he struggles to follow class rules and gives up quickly. These patterns are most typical of which parenting style?","options":["Permissive (indulgent)","Authoritative","Authoritarian","Uninvolved (neglectful)"],"answer":0,"explanation":"Permissive parents are warm but low in demands and control, which is linked with poor self-control and impulsivity. Uninvolved parents are low in warmth as well.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1048","question":"On the two dimensions of responsiveness (warmth) and demandingness (control), which combination defines the parenting style most consistently linked with the poorest outcomes for children?","options":["High responsiveness, low demandingness","Low responsiveness, high demandingness","Low responsiveness, low demandingness","High responsiveness, high demandingness"],"answer":2,"explanation":"Low on both is the uninvolved (neglectful) style added by Maccoby and Martin, consistently associated with the worst outcomes. High on both is authoritative.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1049","question":"Which statement about agents of socialisation is most accurate?","options":["The school is the primary agent, as children spend most of their waking time there","The family is usually the primary agent; school, peers and media are key secondary agents","Socialisation is complete by the time a child enters school at about age six","Media cannot act as an agent of socialisation, since it is not a person or a group the child interacts with"],"answer":1,"explanation":"Primary socialisation, the first learning of language, values and roles, happens mainly in the family; school, peers and media shape secondary socialisation, which continues throughout life.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1050","question":"In a co-educational school, girls are always asked to decorate the class board and serve snacks at functions, while boys are asked to carry benches and manage the sound system. No textbook says girls and boys should do this. What is this an example of?","options":["The formal curriculum teaching gender equality through daily practice","Biological differences determining children’s interests","Peer pressure among students shaping who volunteers for which task","The hidden curriculum, socialising students into gender stereotypes"],"answer":3,"explanation":"Unstated messages carried by routines and practices form the hidden curriculum; here the school itself socialises gender roles. Rotating all tasks among all students would counter it.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1051","question":"In Bandura’s Bobo doll studies, children who saw a model punished for hitting the doll imitated less. But when later offered rewards for showing what the model had done, they reproduced the aggression as much as other children. What does this demonstrate?","options":["Seeing the model punished stopped the children from learning the behaviour in the first place","Children learn only those behaviours for which they themselves have been directly and personally reinforced","Observation can produce learning without reinforcement; consequences affect whether it is performed","Aggression is largely inherited, so watching the model made no real difference to what they learnt"],"answer":2,"explanation":"Seeing the model punished suppressed performance, not learning: the children had acquired the behaviour and displayed it once given an incentive. This is Bandura’s learning–performance distinction.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1052","question":"After watching a wrestling show, several Class 3 boys copy the moves on smaller children during recess. Which response by the teacher is most in line with social learning theory and good practice?","options":["Discuss what was seen and why it hurts in real life, and model and praise safer ways to play","Ignore it, since children soon forget what they see on TV and the copying will fade by itself","Punish the boys publicly so that the rest of the class sees the cost and never tries it","Tell the parents to stop all TV at home, since media has only harmful effects on children"],"answer":0,"explanation":"Children imitate models; teachers can build media literacy, offer and reinforce alternative models. Public punishment models aggression itself, and media can also have positive effects.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1053","question":"Bandura found that children who watched a model being rewarded for a behaviour were more likely to copy it. This effect on the observer is called:","options":["Vicarious reinforcement","Negative reinforcement","Classical conditioning","Shaping"],"answer":0,"explanation":"Seeing a model rewarded increases the observer’s tendency to perform the behaviour: vicarious reinforcement. Negative reinforcement is removal of an unpleasant stimulus after the learner’s own response.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1054","question":"A teacher keeps telling her class, ‘Speak softly and politely to each other,’ but she herself shouts at children when annoyed. According to research on modelling, what is most likely?","options":["Children will follow her instructions, since words matter more than actions","Children will ignore both her words and her actions","Children are likely to imitate what she does more than what she says","Children will speak politely only to her and shout at each other"],"answer":2,"explanation":"Studies on modelling show that when words and actions conflict, children tend to copy the model’s actions; teachers socialise more by example than by preaching.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1055","question":"A Class 5 teacher wants to use peer influence positively. Which practice is most suitable?","options":["Seating the weakest students together so that they do not feel embarrassed in front of others","Ranking students publicly so that peer competition pushes every child to work much harder each week","Forbidding students to talk to each other in class so that they are not distracted by peers","Peer tutoring and cooperative tasks where students share responsibility for each other’s learning"],"answer":3,"explanation":"Peers are a powerful agent of socialisation; structured cooperation and peer tutoring channel that influence toward learning and prosocial behaviour. Public ranking breeds rivalry and inferiority.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1056","question":"Which of these statements about the role of peers in development are correct? I. Peer interaction among equals helps children take others’ perspectives. II. Peer groups give a sense of belonging and identity. III. Peers influence only negative behaviour. IV. Children can learn to negotiate and resolve conflicts through peer play.","options":["I, II and IV only","I and III only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"Peers foster perspective-taking, belonging and social skills; their influence can be positive or negative, so III is false.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1057","question":"At the start of the year, a teacher is told (wrongly) that certain students are ‘late bloomers’ likely to make big gains. By the year’s end these students have gained more than others. Which phenomenon does this illustrate?","options":["Halo effect","Self-fulfilling prophecy (Pygmalion effect) through teacher expectations","Hawthorne effect, as the students knew they were being observed and studied","Regression to the mean"],"answer":1,"explanation":"Teachers’ expectations change how they treat students (attention, feedback, warmth), which can bring about the expected gains, as in Rosenthal and Jacobson’s study. The students did not know of the label, so it is not a Hawthorne effect.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1058","question":"From early childhood, Meera’s relatives give her dolls and kitchen sets and praise her for being ‘quiet and helpful’, while her brother gets cars and bats and is praised for being ‘brave’. By age five she says, ‘Cricket is for boys.’ Which statement best explains this?","options":["Gender preferences are fixed at birth, so her experiences at home have had little effect on them","Gender roles are learnt largely through socialisation by the family and others around the child","The pre-primary school has caused the belief, since home influences are weak at this age","Meera is in Kohlberg’s Stage 1 and accepts the rule because she fears being punished"],"answer":1,"explanation":"Differential toys, praise and expectations from the family socialise gender stereotypes early; teachers can counter them by offering all activities to all children.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1059","question":"Assertion (A): Children raised in joint families often have several adult models and caregivers. Reason (R): Socialisation in a joint family is carried out only by the mother.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A joint family offers grandparents, uncles, aunts and cousins as models and caregivers; this contradicts R, so A is true and R is false.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1060","question":"Several Class 9 girls stop eating lunch, saying they want to look like actresses on social media. What is the most suitable response from the school?","options":["Ban phones in school, since social media is the only real cause of such eating problems among girls","Tell the girls firmly that their worries are silly and that they must eat their lunch","Run media-literacy talks on edited images and body diversity, involving parents and counsellors","Ignore it, since such dieting is a passing fad among teenagers that soon fades by itself"],"answer":2,"explanation":"Media is a strong agent of socialisation in adolescence; building critical viewing, healthy self-image and adult support addresses it, while dismissing or banning alone does not.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1061","question":"A shy child makes her parents speak more softly and cautiously, while her outgoing brother draws louder, more playful interactions from the same parents. This shows that socialisation is:","options":["A one-way process in which parents shape the child, who simply absorbs it","Entirely determined by each child’s heredity, regardless of how parents behave","Fixed once the child enters school and peers take over","A two-way process in which children also influence their socialising agents"],"answer":3,"explanation":"Children’s temperament shapes how parents treat them, which in turn shapes the children; socialisation is bidirectional.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1062","question":"On a sociogram of Class 6, Ravi is named by nobody as a friend and also by nobody as someone they dislike; Kunal is named by many as someone they dislike and by almost none as a friend. In the sociometric categories, they are respectively:","options":["Rejected and neglected","Neglected and rejected","Controversial and rejected","Neglected and controversial"],"answer":1,"explanation":"Neglected children receive few positive and few negative nominations; rejected ones receive many negative and few positive. Controversial children get many of both.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1063","question":"Using the sociogram, the teacher finds two neglected and three rejected children in Class 6. Which plan is most appropriate?","options":["Display the sociogram so that the class can see who is left out and make an effort to include them","Tell the rejected children privately that being disliked is a result of their own behaviour","Seat the rejected children apart from others to avoid conflict during group activities","Keep the results confidential and plan groupings, roles and social-skill support to include them"],"answer":3,"explanation":"Sociometric data should be confidential and used to restructure interaction; rejected children especially need social-skill support and inclusive grouping, not exposure or isolation.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1064","question":"Which of these statements about media as an agent of socialisation is most defensible?","options":["Media teaches mainly violence and consumerism and has no real positive effects on children","Media can teach both prosocial and antisocial behaviour, and adult guidance shapes its effect","Media has little influence on children younger than ten, as they cannot yet follow its messages","Media affects mainly adults, since children treat what they watch as only entertainment"],"answer":1,"explanation":"Children learn from both aggressive and prosocial media content; co-viewing and discussion by adults moderate its effects.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1065","question":"Assertion (A): Children of authoritative parents tend to show better self-regulation and social competence. Reason (R): Authoritative parents combine warmth with clear, reasoned limits that children come to understand and internalise.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Reasoned limits within a warm relationship are internalised as self-control, which is why authoritative parenting predicts self-regulation and competence.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1066","question":"A teacher notices that her Class 10 students follow friends on clothes, music and slang, but still rely on parents on decisions about further studies and core values. What does research on adolescent socialisation suggest?","options":["Parents lose almost all influence once a child reaches adolescence, so peers now guide everything","Peers decide everything for adolescents, including career choices and basic values","Peers matter more for everyday choices; parents stay influential on long-term values and plans","Adolescents are equally influenced by peers and by parents on every kind of matter"],"answer":2,"explanation":"Studies find parents and peers influence different domains: peers more for immediate, social choices; parents more for education, careers and basic values.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1067","question":"When a Class 2 child snatches a toy, Teacher A says, ‘Give it back now or no recess!’ Teacher B says, ‘Look, Priya is crying; she was playing with it. How would you feel if someone took yours?’ According to Hoffman, Teacher B’s approach, called induction, is more likely to:","options":["Make the child fear the teacher, which ensures good behaviour","Build empathy and help the child internalise moral standards","Have no effect, since young children cannot understand others’ feelings","Make the child more aggressive"],"answer":1,"explanation":"Inductive discipline points to the effects of the act on others, arousing empathy and fostering internalised morality; power assertion (Teacher A) tends to produce compliance only under surveillance.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1068","question":"During team games like kabaddi, Class 4 children must take turns, follow agreed rules, accept the umpire’s decision and work for the team. In terms of socialisation, such play mainly helps children:","options":["Learn cooperation, rule-following and their roles within a group","Develop only physical strength and stamina, as games have no social value","Become more egocentric, as they focus on winning","Learn rules only from adults, not from each other"],"answer":0,"explanation":"Organised games are a key medium of socialisation; children learn to coordinate roles, follow shared rules and cooperate, which Piaget and Mead both highlighted.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1069","question":"Which of these statements about socialisation are correct? I. It continues throughout life. II. Its goals and methods vary across cultures. III. It is complete by the age of six. IV. The school can reinforce or counter what is learnt at home.","options":["I and III only","II and III only","I, II and IV only","I, II, III and IV"],"answer":2,"explanation":"Socialisation is lifelong, culture-specific, and the school can strengthen or challenge home learning, e.g. on gender roles; III is false because it does not end in early childhood.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1070","question":"A Class 6 teacher wants to scaffold students who find it hard to write an argumentative essay. Which plan is the best example of scaffolding?","options":["Give a planning frame for claim, reasons and conclusion, and withdraw it once they can plan alone","Write a model essay for weak students so that they can copy it out neatly and learn the expected form","Give extra marks to students who write long essays, so that others try to write more","Ask students to keep rewriting the essay on their own until they get it fully correct"],"answer":0,"explanation":"Scaffolding is temporary, adjustable support that lets learners do what they cannot yet do alone and is withdrawn as they improve. Writing it for them removes the learning, and rewriting alone gives no support.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1071","question":"A Class 5 student’s homework is always perfect because his tuition teacher solves each step for him, but in class tests he cannot do similar problems alone. A Vygotskian explanation is that:","options":["The help exceeded what he needed, so he never took over the steps himself and could not work alone","He is still in the pre-operational stage and so cannot yet handle written sums on his own","Homework should never involve adult help, since any help at all weakens independent learning","He lacks reinforcement in class, as the tuition teacher praises him but the class teacher does not"],"answer":0,"explanation":"Help leads to development only when the learner actively takes over the task and support is faded. Doing the task for him produces finished work but no internalisation.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1072","question":"Vygotsky argued that the main problem for a child with a disability is often not the physical condition itself but its social consequences, and that alternative cultural tools can open other routes to development. Which school practice follows most directly from this view?","options":["Placing the child in a separate school so that she is not compared with others","Waiting for the child to outgrow or overcome the disability before teaching her the full curriculum","Providing tools such as Braille or sign language and full participation in class activities","Reducing the curriculum to self-care skills, since academic goals are unrealistic for her"],"answer":2,"explanation":"Vygotsky’s work on disability stressed compensation through alternative tools and inclusion in social activity. Segregation and low expectations deepen the social consequences he warned against.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1073","question":"According to Vygotsky, which of the following is a higher mental function rather than an elementary one?","options":["Turning the head towards a sudden loud noise in the corridor during a lesson","The startle reflex of a newborn","Remembering a list by deliberately grouping the items into categories","Blinking when dust enters the eye"],"answer":2,"explanation":"Higher mental functions are deliberate, mediated by signs and culturally shaped, like voluntary, organised memory. Involuntary attention and reflexes are elementary functions given by biology.","difficulty":"very-hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1074","question":"A unit test in which each child works alone, with no hints or help, measures mainly which level in Vygotsky’s terms?","options":["The upper limit of the zone of proximal development","The actual (independent) developmental level","The level of potential development","The zone of proximal development as a whole"],"answer":1,"explanation":"Unassisted performance shows functions that have already matured. The potential level, and therefore the ZPD, can only be seen when help is given.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1075","question":"A Class 4 child is stuck on a word problem. Which teacher response is the best example of scaffolding?","options":["Telling him the answer quickly so that he does not get frustrated and give up","Asking, ‘What do we already know? What do we need to find? Which operation links them?’","Giving him a star only if he gets it right on the next attempt without any help","Moving him to an easier worksheet without discussion, so that he can succeed at once and stay motivated"],"answer":1,"explanation":"Guiding questions direct attention to the key features of the task while leaving the thinking to the child. Telling the answer or switching tasks removes the chance to work within his ZPD.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1076","question":"Students who have practised for years on an abacus often solve sums mentally by picturing the beads moving, without any abacus in front of them. In Vygotsky’s terms, this best shows:","options":["A cultural tool that has been internalised and now shapes mental activity","An elementary mental function that is given by heredity and present from birth","Egocentric thought","Bruner’s enactive mode only"],"answer":0,"explanation":"Vygotsky held that external cultural tools, once internalised, become means of thinking. The imagined abacus is a mediating tool now working inside the mind.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1077","question":"In a single-teacher multigrade school in rural Rajasthan, children of Classes 1 to 4 learn in one room and older children often help younger ones. From a Vygotskian viewpoint, the main advantage of this arrangement is that:","options":["Younger children learn to obey older children, which keeps the crowded room orderly","The teacher has less work to do and can focus on the oldest class","Older children automatically reach formal operations by teaching the younger ones","Older children can act as more knowledgeable others within younger children’s ZPD"],"answer":3,"explanation":"Mixed-age groups give younger children many more capable partners, and the older children also consolidate their learning by explaining. The point is guided learning, not obedience.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1078","question":"A child has always said wet clothes ‘just dry in the sun’. After learning about evaporation in Class 5, she explains that water from the clothes turns into vapour faster when it is warm and windy. Vygotsky would see this as:","options":["Replacement of a scientific concept by an everyday one drawn from her experience at home","A school-taught scientific concept giving structure and awareness to an everyday one","Accommodation through her own discovery, without any real role for instruction","An iconic representation becoming enactive as she pictures the clothes drying"],"answer":1,"explanation":"Vygotsky argued that scientific concepts introduced by instruction reorganise spontaneous concepts, while everyday experience gives scientific concepts concrete meaning. The two develop in interaction.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1079","question":"Which statement about inner speech, in Vygotsky’s account, is correct?","options":["It is the first form of speech to appear in infancy, well before any speech addressed to others","It has exactly the same structure as speech addressed to others, only without sound","It is a sign of mental disorder when it continues into adolescence or adulthood","It is abbreviated compared with social speech, because the speaker already knows the context"],"answer":3,"explanation":"Vygotsky described inner speech as highly abbreviated, keeping mainly the predicate, since the subject is already known to the thinker. It develops last, from social speech through private speech.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1080","question":"In an English class for students whose home language is Marathi, the teacher gives sentence frames such as ‘I think ___ because ___’ for a discussion, and stops providing them once students speak confidently. This is an example of:","options":["Scaffolding language use within the zone of proximal development","Rote memorisation of fixed phrases to be recalled in tests","Negative reinforcement, since the frames are removed when students improve","Horizontal décalage across different language tasks"],"answer":0,"explanation":"Sentence frames are temporary supports that let learners take part in discussion beyond their independent level; removing them as competence grows is scaffolding.","difficulty":"moderate","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1081","question":"A teacher who has never used a new attendance app mutters, ‘First tap the class... then the date... where is the save button?’ as she uses it. This most clearly supports Vygotsky’s claim that:","options":["Private speech belongs only to young children and disappears completely","Adults are still at the pre-operational stage","Private speech can reappear at any age when a task is new or difficult","Speech and thought are unrelated in adults"],"answer":2,"explanation":"Inner speech can return to an audible form when adults face difficult or unfamiliar tasks, because speaking aloud helps regulate action. It is not a sign of a lower stage.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1082","question":"A Class 3 child cannot follow even step-by-step help from the teacher on solving quadratic equations. What would Vygotsky conclude?","options":["The child needs more drill on quadratic equations until the procedure becomes automatic","The task lies beyond the upper limit of his ZPD, so a task nearer his present level is needed","The child lacks intelligence and should be placed in a lower class with easier work","The help was not detailed enough, so the teacher should explain each step even more slowly"],"answer":1,"explanation":"The ZPD covers only what a learner can do with help. If even full help does not work, the task is outside the zone and instruction there cannot be taken up.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1083","question":"Vygotsky described how a baby’s unsuccessful reach towards an object becomes a pointing gesture once the mother responds by handing the object over. This example was used to show that:","options":["Pointing is an inborn reflex that appears on schedule whatever the mother does","Gestures are learnt only through operant conditioning, with the object acting as the reward each time","Infants already have full formal operations and plan their gestures deliberately","An action’s meaning first arises in interaction with others and is then taken over by the child"],"answer":3,"explanation":"The reach acquires meaning as a request because another person interprets it, and the child then uses it deliberately. This illustrates Vygotsky’s view that higher functions have a social origin.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1084","question":"A computer-based maths program gives a student a general hint after a wrong answer, a more specific hint after a second error, and a worked step after a third, while reducing hints as the student improves. This design is an application of:","options":["Contingent scaffolding based on Vygotsky’s ZPD","Classical conditioning of correct answers to hints","Piaget’s idea of animism","Bruner’s enactive mode of representation"],"answer":0,"explanation":"Help that grows when the learner struggles and shrinks when she succeeds is contingent scaffolding. The program adjusts to the learner’s zone rather than giving a fixed reward.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1085","question":"How many of these practices are consistent with Vygotsky’s theory? I. Waiting until children are developmentally ready before teaching a concept. II. Allowing children to talk to themselves while solving problems. III. Assessing only what children can do alone. IV. Teaching the language and symbols of a subject alongside activities.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and IV follow from his views on private speech and cultural tools. I is inconsistent: for Vygotsky learning leads development, so teaching in the ZPD should not wait for readiness. III ignores the ZPD by assessing only independent work.","difficulty":"hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1086","question":"Two Class 2 children, Pinky and Sumit, both read simple words alone. With the teacher’s prompts, Pinky reads a whole short story, while Sumit manages only a few more words. Which instructional decision follows from Vygotsky?","options":["Give both children exactly the same reading task, since they have the same independent level","Give both the story, since all children of the same age have the same potential","Plan different next steps, since their zones of proximal development differ","Wait until both reach the same level on their own"],"answer":2,"explanation":"Equal independent performance can hide different ZPDs. Instruction should match each child’s assisted level, so Pinky is ready for more challenging reading than Sumit.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1087","question":"Assertion (A): Giving children only tasks they can already do on their own does little to advance their development. Reason (R): Such tasks lie below the zone of proximal development, where no new functions are being formed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Tasks at the independent level only use matured functions. Development is stimulated by tasks just beyond that level, within the ZPD, so R explains A.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1088","question":"In an anganwadi, a worker plays with toddlers, names the objects they touch, asks simple questions and extends their short phrases (‘Ball... yes, a red ball!’). From a Vygotskian view, this is valuable mainly because:","options":["It keeps the children quiet and busy, so that they cause less trouble later","It provides language and social interaction through which children’s thinking develops","It trains children to imitate adult speech exactly, which is how all language is learnt","It speeds up physical growth through extra movement and play"],"answer":1,"explanation":"For Vygotsky, adult talk during shared activity provides the language tools that children later use for thinking. Expanding phrases also scaffolds the child’s own speech.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1089","question":"Which classroom situation shows a misunderstanding of the ‘more knowledgeable other’ in Vygotsky’s theory?","options":["A student who knows a regional song teaches it to the whole class, including the teacher","A teacher refuses to let a peer help, saying, ‘Only an adult can be a proper guide’","A computer tutor gives step-by-step hints","An elder sister guides a younger child in using a dictionary"],"answer":1,"explanation":"The MKO can be a peer, a younger person or even a computer program, as long as it knows more about the task. Restricting it to adults misreads Vygotsky.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1090","question":"Consider these statements. 1. For Vygotsky, the ZPD is a property of the interaction between a learner and a helper on a particular task, not a fixed trait. 2. Vygotsky held that all learning must wait for the matching stage of development to be complete. 3. Vygotsky saw schooling as an important source of new psychological tools. Which is/are correct?","options":["1 and 3 only","1 and 2 only","2 only","1, 2 and 3"],"answer":0,"explanation":"The ZPD depends on the task and on the help available, and schools introduce tools such as writing and scientific concepts. Statement 2 is Piaget’s position, which Vygotsky rejected.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1091","question":"A Class 8 teacher assigns a group project. The group finishes well, but she later finds that two members only coloured the charts and learnt nothing about the topic. Which Vygotskian principle was most neglected?","options":["Children should never work in groups, since some members will always leave the real work to others","Group learning works only if each member takes part in the shared thinking and can internalise it","Groups should contain only children of identical ability, so that everyone contributes equally","Teachers should not monitor group work, so that children learn to manage on their own"],"answer":1,"explanation":"Social interaction leads to development only when learners participate in the joint problem solving. Passive members have nothing to internalise, so careful role design and monitoring matter.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1092","question":"Which of the following best describes ‘mediation’ in Vygotsky’s theory?","options":["Settling quarrels between children in class so that cooperative learning can go on","Rewarding correct responses immediately so that the link between task and answer is strengthened","The child’s mind adjusting to new information on its own, without any outside help","Using tools and signs, often supplied by others, that stand between the child and the task"],"answer":3,"explanation":"For Vygotsky, human thinking is mediated by cultural tools such as language, numbers and diagrams. The term has nothing to do with resolving quarrels or reinforcement.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1093","question":"A Class 3 child learns subtraction by first using a number line with the teacher, then using it alone, then imagining it, and finally solving sums mentally. The step ‘imagining it’ illustrates:","options":["The tool moving from an external support to an internal mental tool","A regression to the sensorimotor stage under the pressure of subtraction","Bruner’s claim that the enactive mode is unnecessary","Operant extinction of the number line"],"answer":0,"explanation":"Vygotsky’s internalisation describes how external aids become inner tools of thought. The imagined number line is a halfway point between using the real one and pure mental calculation.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1094","question":"Which of the following would Vygotsky most likely criticise?","options":["A teacher who asks open questions during group work instead of simply handing out the answers herself","A child who explains a problem to a friend who has not yet understood it","A report labelling a child ‘weak’ from one unaided test, without seeing what she can do with help","A parent who reads stories aloud and talks about them with a child at bedtime every night"],"answer":2,"explanation":"Vygotsky argued that static, unaided testing shows only the actual level and misses the ZPD. The other practices involve the social interaction he valued.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1095","question":"In Tolman's maze experiments, rats that ran the maze for ten days without any food reward made many errors, but once food was introduced on day eleven they almost immediately performed as well as rats rewarded from the start. What does this show?","options":["Learning occurs only when every response is reinforced, so the first ten days produced no learning at all","Rats learn by sudden insight rather than by gradual experience of the maze","Food reward creates the learning on the very day it is introduced, through rapid conditioning","Learning can occur without reinforcement and show in performance only when there is a reason to use it"],"answer":3,"explanation":"Tolman called this latent learning: the rats had formed a cognitive map while exploring, and the reward merely gave them a reason to display what they already knew.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1096","question":"The main corridor of a school is closed for repairs. Class 5 student Divya, who has explored the building for years, immediately takes an unfamiliar route through the library and back stairs to reach the art room. Tolman would explain her behaviour by her:","options":["Cognitive map of the school","Conditioned response to the corridor","Law of exercise","Vicarious reinforcement"],"answer":0,"explanation":"A cognitive map is a mental representation of the layout of an environment; it allows flexible new routes rather than a fixed chain of responses.","difficulty":"hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1097","question":"Class 7 students behave perfectly when the principal is in the corridor but become noisy the moment she leaves, although they are never punished in either case by the class teacher. In operant terms, the principal's presence acts as:","options":["An unconditioned stimulus that naturally produces quiet, orderly behaviour","A discriminative stimulus signalling when certain behaviour will be reinforced or punished","A primary reinforcer, since her presence is rewarding in itself to the students","A neutral stimulus, since she herself neither rewards nor punishes the students in any way"],"answer":1,"explanation":"A discriminative stimulus signals that a particular consequence is available. Behaviour then comes under stimulus control and occurs mainly when that signal is present.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1098","question":"In one school, a long ring of the bell is always followed by lunch break, while a short ring is followed only by a change of period. Soon children start packing tiffin boxes only at the long ring. This illustrates:","options":["Stimulus generalisation","Spontaneous recovery","Stimulus discrimination","Higher-order conditioning"],"answer":2,"explanation":"Children have learnt to respond to one stimulus (long ring) and not to a similar one (short ring) because only the first is paired with lunch: stimulus discrimination.","difficulty":"hard","source":"CTET Paper 1 · REET"},
  {"id":"cdp-child-development-1099","question":"To teach a child with an intellectual disability to tie his shoelaces, a teacher first does all the steps herself except the last tightening pull, which the child completes and is praised for. Gradually she leaves the last two, then the last three steps to him. This method is called:","options":["Forward chaining","Shaping by spontaneous recovery","Fixed-interval reinforcement","Backward chaining"],"answer":3,"explanation":"In backward chaining the learner first masters the final step, which is immediately followed by task completion and reinforcement, and then earlier steps are added one by one.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1100","question":"A teacher sends a disruptive Class 4 child out of the room for ‘time-out’ each time he misbehaves, but his misbehaviour increases. He dislikes the maths lesson. What is the likely reason?","options":["Leaving the lesson removes something he dislikes, so time-out negatively reinforces misbehaving","Time-out always increases behaviour, because any attention from the teacher acts as a reward","The child is showing spontaneous recovery of a behaviour that had earlier been extinguished","Time-out is a form of positive reinforcement, as the teacher adds attention by sending him out"],"answer":0,"explanation":"Time-out works only if the classroom is more rewarding than being outside it. If the lesson is aversive, escaping it strengthens the misbehaviour through negative reinforcement.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1101","question":"Which of these correctly contrasts classical and operant conditioning? I. In classical conditioning the response is mostly elicited by a stimulus; in operant conditioning it is emitted by the learner. II. In operant conditioning the consequence of a response determines whether it is repeated. III. Classical conditioning mainly involves voluntary actions. IV. Skinner called classically conditioned responses ‘respondent’ behaviour.","options":["I and III only","I, II and IV only","II and III only","I, II, III and IV"],"answer":1,"explanation":"Classical conditioning involves largely involuntary, elicited (respondent) responses, so III is false. Operant behaviour is emitted and controlled by its consequences.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1102","question":"Praise for good behaviour given by a Class 1 teacher at the end of the week, rather than immediately, has little effect on the children. The most likely reason is that:","options":["Praise is not a real reinforcer for young children, who respond mainly to tangible rewards","Young children need punishment for misbehaviour rather than praise for good behaviour","For young children, reinforcement works far better when it closely follows the behaviour","Weekly praise is a variable-ratio schedule, which works only with older students"],"answer":2,"explanation":"The closer the consequence to the behaviour, the stronger the connection; young children especially have difficulty linking delayed consequences to earlier actions.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-1103","question":"Each time Monu wanders around the class, his teacher loudly scolds him in front of everyone, but his wandering keeps increasing. A behaviourist would point out that:","options":["The scolding is negative reinforcement, since it removes his freedom to roam freely around the classroom","The scolding is acting as punishment, and the increase is only a temporary extinction burst","Monu’s wandering is caused by spontaneous recovery of a habit extinguished earlier","For an attention-seeking child, the teacher’s attention may be acting as positive reinforcement"],"answer":3,"explanation":"Whether a consequence is a reinforcer or a punisher depends on its effect. If wandering increases, the scolding, which gives attention, is functioning as a reinforcer.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1104","question":"A Class 8 teacher cancels a test whenever the class whines loudly about it. Whining increases, and the teacher finds herself giving in more often. How does operant conditioning explain the teacher's own behaviour?","options":["Giving in is negatively reinforced, because it ends the unpleasant whining","Giving in is positively punished by the students, who whine louder each time she refuses","The teacher’s behaviour is classically conditioned salivation","The teacher is showing latent learning"],"answer":0,"explanation":"The students are positively reinforced (the test is cancelled after whining), while the teacher is negatively reinforced: her giving in removes the aversive whining, so she gives in more.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1105","question":"A library programme gives a child one sticker for every five books read. Teachers notice that children often take a short break from reading right after getting a sticker. This schedule and pattern are:","options":["Variable ratio, with steady responding and no pauses","Fixed ratio, with a pause after each reinforcement","Fixed interval, with scalloping","Continuous reinforcement, with rapid extinction"],"answer":1,"explanation":"Reinforcement after a fixed number of responses is a fixed-ratio schedule; it typically produces high responding with a brief post-reinforcement pause.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-1106","question":"Only the maths teacher praises Rohan for raising his hand, yet he begins raising his hand before speaking in every class, including those where it is not praised. This spread of the behaviour is:","options":["Stimulus discrimination between maths and other classes","Extinction","Operant generalisation to similar situations","Latent learning"],"answer":2,"explanation":"Behaviour reinforced in one setting tends to occur in similar settings: generalisation. If it later continues only in maths class, discrimination will have occurred.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1107","question":"Which of these is the most widely accepted criticism of strict behaviourism as an account of children's learning?","options":["It ignores the effect of rewards and punishments on how often a behaviour is repeated later","It overemphasises thinking and understanding and pays too little attention to behaviour","It explains the creativity of children’s language better than any other theory can","It neglects mental processes and cannot easily explain how children produce new sentences"],"answer":3,"explanation":"Behaviourism studies observable behaviour and associations; critics such as Chomsky argued it cannot explain the creativity of language, and cognitive psychologists stressed internal processes.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1108","question":"Assertion (A): When a teacher praises a child for a correct answer, the child is more likely to answer in that way again. Reason (R): According to Thorndike, a connection followed by a satisfying state of affairs is strengthened.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"This is a direct application of Thorndike's law of effect: satisfying consequences strengthen the stimulus–response bond.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1109","question":"In Watson's ‘Little Albert’ study, a child conditioned to fear a white rat also became afraid of a white rabbit and a fur coat. What is the main lesson for teachers?","options":["Fear cannot be learnt through experience; it is inherited and appears on its own with age","Frightening early experiences in a subject can produce fears that spread to related situations","Children’s fears always extinguish quickly by themselves, so teachers need not worry about them","Fear is learnt only by watching others being frightened, never through direct experience"],"answer":1,"explanation":"Watson showed that emotional responses can be classically conditioned and generalise to similar stimuli. A child shamed in one maths class may come to fear maths in general.","difficulty":"hard","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-1110","question":"Instead of scolding Simran each time she leaves her seat, the teacher deliberately praises her whenever she is seated and working. Her wandering decreases. This strategy is best described as:","options":["Negative punishment of wandering","Positive punishment of wandering, using praise as the punisher","Reinforcing an incompatible behaviour","Classical extinction"],"answer":2,"explanation":"Sitting and working cannot occur at the same time as wandering, so reinforcing it reduces wandering without punishment. This is differential reinforcement of incompatible behaviour.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1111","question":"According to Gagné's hierarchy of learning types, before Class 3 children can learn the rule ‘a sentence begins with a capital letter and ends with a full stop’, they must already have learnt:","options":["Problem solving","Signal learning only, since rules are simple stimulus-response links","Classical conditioning of writing","The concepts of ‘sentence’, ‘capital letter’ and ‘full stop’"],"answer":3,"explanation":"In Gagné's hierarchy, principle (rule) learning requires the relevant concepts to be learnt first; a rule is a relation between concepts.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1112","question":"In a self-learning computer programme, a student who chooses a wrong option is sent to an extra explanatory frame before returning to the main sequence, while correct answerers move on directly. This is:","options":["Branching programming, associated with Norman Crowder","Linear programming, associated with Skinner’s teaching machines","Classical conditioning","Discovery learning"],"answer":0,"explanation":"Skinner's linear programmes have every learner follow the same small steps; Crowder's branching programmes route learners to different frames depending on their answers.","difficulty":"very-hard","source":"CTET Paper 2 · NVS TGT"},
  {"id":"cdp-child-development-1113","question":"Assertion (A): A gold star that increases homework completion for one child may not be a reinforcer at all for another. Reason (R): In operant theory a reinforcer is defined by its effect on the behaviour it follows, not by how pleasant it seems to the teacher.","options":["A is true but R is false","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"A consequence is a reinforcer only if it increases the behaviour. Because children value different things, the same star may reinforce one child and not another.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1114","question":"Which statements about reinforcement schedules are correct? I. Fixed-ratio schedules often produce a short pause after each reinforcement. II. Variable-interval schedules produce a steady, moderate rate of response. III. Behaviour learnt under continuous reinforcement extinguishes faster than behaviour learnt under intermittent reinforcement. IV. Fixed-interval schedules produce a perfectly steady rate throughout the interval.","options":["I and IV only","II and IV only","I, II and III only","I, II, III and IV"],"answer":2,"explanation":"Fixed-interval schedules produce a 'scallop', with little responding early and a burst near the end of the interval, so IV is false. The rest are standard findings.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1115","question":"A pre-primary teacher greets children warmly, plays songs and offers a favourite activity at the start of each day so that the school gate itself comes to evoke happy feelings. Which principle is she mainly using?","options":["Operant shaping of punctual arrival at school","Law of readiness","Insight learning","Classical conditioning of positive emotions"],"answer":3,"explanation":"Repeatedly pairing the school setting with pleasant experiences makes the setting a conditioned stimulus for positive feelings, reducing separation anxiety.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-1116","question":"A coach teaches a nervous Class 6 girl the long jump by first praising a clean run-up, then a run-up with take-off from the board, then a take-off with a good arm swing, and finally the full jump with landing. How does this differ from simple trial and error?","options":["The coach reinforces closer and closer approximations instead of waiting for the full jump by chance","It does not really differ, since both rely on the learner’s random attempts until one finally succeeds","The coach relies on sudden insight into the whole jump rather than on any reinforcement","The coach uses negative reinforcement, removing praise at each step until the jump is complete"],"answer":0,"explanation":"Shaping builds a complex skill through planned reinforcement of successive approximations; in trial and error the learner tries responses until one happens to succeed.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1117","question":"A teacher wants Class 2 children to stop confusing the letters b and d. She shows pairs and praises responses only when the child correctly names the letter, never when b is called d. What process is she trying to build?","options":["Generalisation","Discrimination","Spontaneous recovery","Higher-order conditioning"],"answer":1,"explanation":"Discrimination is learning to respond differently to similar stimuli; reinforcing the correct response to each and not to the other sharpens this distinction.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1118","question":"A boy taught by Thorndike-style drill can recite ‘7 × 8 = 56’ instantly but cannot solve a word problem asking for the cost of 7 packets at ₹8 each. Which statement best explains this?","options":["Drill has caused retroactive interference, so later learning has wiped out the table facts","He has a problem of attention and simply did not read the word problem carefully enough to solve it","Rote S–R bonds may not transfer to new situations unless he understands what multiplication means","He has reached the formal operational stage early and now finds concrete problems too easy"],"answer":2,"explanation":"Rote S–R bonds are tied to the trained form. Without understanding what multiplication means, the learner cannot recognise when to use it in a new context.","difficulty":"hard","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-1119","question":"Which of the following is the best example of negative reinforcement in a classroom?","options":["A child loses break time for not finishing work, so she starts finishing her work more often","A child is scolded for talking in class, which removes the talking that the teacher found unpleasant","A child receives a sticker for neat work, and the sticker is taken away if work gets messy","A child who finishes classwork early is excused from that day’s homework and finishes early more often"],"answer":3,"explanation":"Negative reinforcement increases a behaviour by removing something unpleasant (homework). Losing break time is negative punishment, scolding is positive punishment, and a sticker is positive reinforcement.","difficulty":"moderate","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1120","question":"A school proudly reports that every child with a disability in its area is enrolled. Observation shows that these children rarely take part in class activities, and nobody tracks what they are learning. Which aspects of inclusion are missing?","options":["Presence only","Participation and achievement","Presence and participation","None, since enrolment is the measure of inclusion"],"answer":1,"explanation":"Inclusion means presence, participation and achievement; the children are present, but without taking part and making tracked progress, the school has only achieved enrolment.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1121","question":"A school builds a ramp at its main gate for a wheelchair user, but the toilets have narrow doors and a step, and the drinking-water point is up a flight of stairs. What does this show about accessibility?","options":["The next step is a ramp at her classroom door, since the classroom matters most","A classmate should be assigned to help her reach the toilet and water point daily","Access must cover all daily needs such as toilets and water, not just the entry","She should get a ground-floor classroom near the gate so she has less to travel"],"answer":2,"explanation":"Accessibility means the child can use every facility independently, so toilets, water and play areas must be barrier-free too. A peer helper is kind but makes her dependent and leaves the barriers in place, which accessibility law does not accept.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1122","question":"Despite good teaching, Pinku in Class 4 still confuses short and long matras (ि/ी, ु/ू), cannot read conjunct letters, reads word by word very slowly, and makes the same spelling errors repeatedly. Yet he understands stories read aloud very well. What should the teacher consider?","options":["That he is lazy about reading and needs more homework and daily copying practice","That he may have a specific reading difficulty such as dyslexia and needs structured support and assessment","That he has an intellectual disability, since he still cannot read at his grade level","That Hindi script is too hard for him and he should be moved to an English-medium section from next year"],"answer":1,"explanation":"Persistent decoding and spelling problems, despite good teaching and with strong listening comprehension, are a classic pattern of dyslexia, which also occurs in Indian scripts.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1123","question":"Which of these statements about dyscalculia are correct? I. Dyscalculia can occur together with dyslexia in the same child. II. Maths anxiety can lower performance but is not the same as dyscalculia. III. Children with dyscalculia can never learn mathematics.","options":["I and III only","II and III only","I, II and III","I and II only"],"answer":3,"explanation":"Learning disabilities often co-occur, and anxiety is a separate (though related) factor; with suitable teaching, children with dyscalculia do make progress, so III is false.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1124","question":"Tarun, a Class 7 student with ADHD, often forgets homework, loses worksheets and misses deadlines, though he understands the lessons. Which support is most appropriate?","options":["External organising aids such as a daily checklist, colour-coded folders and a planner reviewed daily","Lowering his marks each time he forgets so that he learns responsibility for his own work","Telling him firmly to try harder to remember, since he clearly understands the lessons and can do it","Excusing him from all homework and deadlines, since ADHD makes organisation impossible for him"],"answer":0,"explanation":"ADHD often involves weak executive functions such as planning and organising; external structure compensates and builds habits, whereas penalties and exhortation do not create the missing skill.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1125","question":"Sneha, a Class 2 child on the autism spectrum, becomes upset when an activity ends suddenly. Which practice will help her most?","options":["Changing activities without warning so that she gradually gets used to surprises and copes better later","Giving advance notice of transitions, such as a five-minute warning with a visual timer and schedule","Letting her continue her preferred activity all day so that she never has to face an ending","Removing her from the class during transitions and bringing her back once the new activity starts"],"answer":1,"explanation":"Advance warnings and visual cues make transitions predictable, which reduces anxiety for many autistic children; sudden change or avoidance does not build coping.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1126","question":"Classmates laugh when Yash, an autistic Class 3 student, flaps his hands when excited. A teacher wants to stop the flapping. Which view is most appropriate?","options":["The flapping should be stopped firmly, since it looks odd and will keep inviting teasing from classmates","Yash should sit at the back so that others cannot see him flap and the laughing stops","Flapping helps many autistic children self-regulate; the teacher should build classmates’ acceptance","Yash should be sent out whenever he flaps, so that the lesson is not disturbed for others"],"answer":2,"explanation":"Harmless self-regulating movements need not be suppressed; the barrier is peers' lack of understanding, which the teacher can address through age-appropriate discussion of differences.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1127","question":"Assertion (A): Blind students writing examinations in Braille should be given extra time. Reason (R): Reading and writing in Braille, and exploring tactile diagrams, generally take longer than reading print by sight.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Extra time compensates for the slower pace of tactile reading and writing, so the test measures knowledge rather than speed of the medium.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1128","question":"Leena, a Class 5 student with low vision, struggles to read the board on sunny afternoons. Which change is most helpful?","options":["Seating her facing the window so that more daylight falls directly on her book and on the board","Seating her with light from beside or behind her, and writing in large, high-contrast letters","Asking her to wear dark glasses in class so that the bright sunlight does not trouble her eyes","Moving her to the last row so that she can see the whole board at once without turning her head"],"answer":1,"explanation":"Glare from facing a bright window reduces usable vision; side or back light and high-contrast writing make the most of her remaining sight.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1129","question":"Assertion (A): Many deaf children find it hard to learn to read in a spoken language such as Hindi or English. Reason (R): Deaf children have lower intelligence than hearing children.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Reading maps print onto a spoken language that deaf children may have had limited access to, which is why reading can be hard; deafness itself does not lower intelligence.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1130","question":"How should the progress of Mohan, a Class 5 child with moderate intellectual disability in an inclusive class, mainly be judged?","options":["By ranking him with the rest of the class on the same tests and marking scheme","By whether he passes the regular Class 5 exam","By comparing him with other children with disabilities in the district, using common tests","Against the goals set in his individualised plan, recording his own growth over time"],"answer":3,"explanation":"For a child working towards individual goals, progress is best measured against those goals; comparison with class norms would only record failure and hide genuine learning.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1131","question":"A gifted Class 5 student has finished the chapter on water and its conservation well ahead of others. Which task extends her thinking most?","options":["Copying the chapter summary neatly into her notebook so that she can revise it later","Answering more textbook questions from the same exercise to make her mastery even more secure","Designing a rainwater harvesting plan for the school, estimating water saved and defending her choices","Reading and memorising the definitions in the next chapter so that she stays ahead of the class all year"],"answer":2,"explanation":"Gifted learners need tasks at higher levels of thinking, such as creating and evaluating in real contexts; more of the same or copying gives no new challenge.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1132","question":"The goal of a Class 3 lesson is that children can describe their village. The teacher’s task says ‘Write a paragraph about your village’. A child with dysgraphia and a new Hindi learner cannot show what they know. Following Universal Design for Learning, what is the best fix?","options":["Letting children describe their village by speaking, writing, drawing or recording","Keeping the written task for everyone but giving these two children lower marks for fairness","Giving these two children an easier topic to write about, such as their family","Excusing these two children from the task until their writing and Hindi improve enough"],"answer":0,"explanation":"When the goal is description, insisting on handwriting adds a barrier unrelated to the goal; UDL offers flexible means of expression while keeping the same goal for all.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1133","question":"Assertion (A): Once students have been grouped by readiness in April, the groups should stay the same for the whole year. Reason (R): A student’s readiness varies from topic to topic and changes with learning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Because readiness differs across topics and grows over time, groups must be flexible; fixing them for a year turns differentiation into tracking.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1134","question":"Children from a community that has long been stereotyped as ‘thieves’ join a Class 4 class. Some classmates repeat this label and refuse to sit with them. What is the most appropriate response?","options":["Seating these children together in one corner so that the others feel comfortable for now","Ignoring the remarks, since young children repeat such words from home without meaning them seriously","Telling the new children to prove their honesty through good behaviour so the label fades","Stating that the label is unacceptable, discussing stereotypes and forming mixed working groups"],"answer":3,"explanation":"Community stereotypes must be confronted directly; working together in mixed groups builds real relationships, whereas isolating or burdening the stereotyped children deepens exclusion.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1135","question":"Sam, a Class 6 student, prefers to dress and be addressed as a girl. Some classmates bully her and refuse to let her use the girls’ line. What should the school do?","options":["Ask the child to dress and behave according to the sex recorded at admission, so as to avoid further trouble","Stop the bullying, respect her identity and safety in school spaces, and involve the counsellor and family","Shift the child to another section so that she is separated from the bullies for good","Treat the matter as private to the family and take no action unless parents complain"],"answer":1,"explanation":"Gender identity is to be respected and every child has a right to a safe, non-discriminatory school; the school must act against bullying rather than move or blame the victim.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1136","question":"A Class 5 teacher praises girls for neat handwriting and good behaviour, and praises boys for clever ideas and solving hard problems. What is the main problem?","options":["Praise should not be used in class at all, since it makes children dependent on approval","Girls should receive more praise than boys, since they generally behave better in class","There is no problem as long as the praise is sincere and each child is praised for genuine strengths","The pattern teaches that intelligence belongs to boys and neatness to girls, reinforcing stereotypes"],"answer":3,"explanation":"Differential feedback silently shapes children's self-image; praise should target ideas and effort for all children equally.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1137","question":"Assertion (A): A child who mixes Hindi and English in one sentence is confused about both languages. Reason (R): Bilingual children draw on both their languages flexibly and strategically to express meaning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Code-switching is a normal, rule-governed skill of bilinguals, not a sign of confusion; so A is false while R is true.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1138","question":"Students in a rural Class 8, mostly first-generation learners, believe that further study is ‘not for people like us’. Which step by the teacher is most likely to raise their aspirations?","options":["Bringing in role models from similar backgrounds and showing real pathways to further study","Telling them that only toppers should think of higher studies, so that expectations stay realistic","Avoiding the topic, since aspirations come mainly from home and cannot be changed by school","Advising them to choose the jobs their parents do, since these are secure and familiar"],"answer":0,"explanation":"Seeing people like themselves succeed, with clear routes forward, counters the belief that education is not for them; avoiding the topic leaves low expectations in place.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1139","question":"Classmates mimic the limp of Raju, a Class 6 student with a locomotor disability. Which response is most effective?","options":["Punishing the children who mimic, firmly and at once, without any further class discussion","Advising Raju to stay inside the classroom during breaks so that he is not exposed to more teasing","Clear rules and consequences for the mimicking, whole-class work on empathy, and support for Raju","Telling Raju that it is only a joke and that he should learn not to mind such teasing"],"answer":2,"explanation":"Bullying of children with disabilities needs a whole-class approach: firm rules and consequences together with building empathy, while supporting the child without restricting him.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1140","question":"A teacher gives a four-step spoken instruction: ‘Take out your book, open page 20, read the first paragraph and underline the verbs.’ Ramesh, who has intellectual disability, completes only the first step. What is the best adjustment?","options":["Repeating all four steps more loudly and slowly so that he can hear every one clearly","Telling him to listen more carefully next time and to ask a friend whenever he forgets a step","Asking a classmate to do the remaining steps for him so that he does not fall behind","Giving one instruction at a time, with a demonstration or picture cue, and checking each step"],"answer":3,"explanation":"Limited working memory makes multi-step oral instructions hard to hold; breaking them into single steps with visual cues lets him complete the full task.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1141","question":"Under the RPwD Act, 2016, which of the following situations amounts to discrimination by denial of reasonable accommodation?","options":["A school refuses to shift Class 7 to an available ground-floor room for its wheelchair-using student","A school arranges a scribe for a student with a fractured hand while writing the annual examinations","A school seats a child with a hearing impairment in the front row, close to the teacher","A school gives large-print question papers to a child with low vision during all tests"],"answer":0,"explanation":"Discrimination on the basis of disability includes denial of reasonable accommodation; moving a class to an available ground-floor room is a simple adjustment without undue burden.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1142","question":"Which teacher belief best supports inclusive education?","options":["I should treat every child exactly alike so that no child ever feels singled out","Every child can learn; if a child is not learning, I should change how I teach","Children with special needs should get easier work so that they never feel failure","A child with a disability should first catch up in a special class, then join mine"],"answer":1,"explanation":"Inclusion locates the barrier in teaching and the environment, so the teacher adapts her practice. Treating everyone exactly alike sounds fair but ignores that equity needs different supports, and easier work or a ‘catch up first’ rule lowers expectations or delays inclusion.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1143","question":"In a Class 4 PE period, Tanya, who has dyspraxia, cannot manage skipping with a rope and has begun avoiding PE altogether. What is the most appropriate response?","options":["Excusing her permanently from PE so that she is spared repeated failure in front of others","Making her practise skipping in front of the class until she gets it, to build confidence","Giving her a lower PE grade without changing anything, so that assessment stays the same for all","Breaking the skill into small steps, offering adapted equipment and valuing her participation"],"answer":3,"explanation":"Dyspraxia affects motor planning, so skills need to be broken down and adapted; inclusion in PE means participation with support, not exemption or public failure.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1144","question":"Assertion (A): In peer tutoring, the student who tutors also gains in understanding. Reason (R): Explaining a concept to someone else requires the tutor to organise and clarify his own knowledge.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Teaching others forces the tutor to restructure and clarify ideas, which deepens his own learning; this is why peer tutoring benefits both partners in an inclusive class.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1145","question":"How many of these statements are correct? I. Spearman used factor analysis of test scores to argue for a general factor. II. Thurstone proposed seven primary mental abilities. III. In Guilford’s model, divergent production is one of the operations. IV. Raymond Cattell proposed the g and s factors.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The g and s factors belong to Spearman; Cattell proposed fluid and crystallised intelligence, so IV is false.","difficulty":"hard","source":"CTET · DSSSB TGT"},
  {"id":"cdp-child-development-1146","question":"A boy aged exactly 10 years has a mental age of 13 years 6 months. What is his ratio IQ?","options":["74","130","135","123"],"answer":2,"explanation":"Ratio IQ = MA ÷ CA × 100 = 13.5 ÷ 10 × 100 = 135. Ignoring the six months gives 130, and inverting the ratio gives about 74.","difficulty":"moderate","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1147","question":"A girl aged 7 years 6 months has a ratio IQ of 120. What is her mental age?","options":["6 years 3 months","9 years","9 years 6 months","8 years 8 months"],"answer":1,"explanation":"MA = IQ × CA ÷ 100 = 1.2 × 7.5 = 9 years. Dividing instead of multiplying gives 7.5 ÷ 1.2 = 6.25 years (6 years 3 months).","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1148","question":"Which popular claim about emotional intelligence is NOT supported by research evidence?","options":["Emotional skills such as recognising and naming feelings can be taught to children in school","EI matters far more than IQ for success in every field, by a fixed margin such as ‘twice as much’","The ability to manage emotions is linked with better relationships and well-being","Emotional intelligence includes perceiving emotions accurately in other people’s faces and voices"],"answer":1,"explanation":"Sweeping claims that EI outweighs IQ by some fixed amount come from popular writing, not research; studies find EI adds modest prediction for some outcomes, while the other statements are well supported.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1149","question":"Kabir, a Class 10 student, often asks questions like ‘Why are we born?’ and ‘What happens after death?’ and enjoys discussing the meaning of life. Gardner discussed such ability as possible ‘existential intelligence’. What is its status in his theory?","options":["It was one of the original seven intelligences he proposed in 1983","It replaced intrapersonal intelligence in later versions of the theory","Gardner rejected the idea completely and never discussed it in any of his writing","Gardner treats it as a strong candidate but has not fully added it to his list"],"answer":3,"explanation":"Gardner added naturalist intelligence and discussed existential intelligence as a candidate, famously speaking of ‘eight and a half’ intelligences, without fully confirming it.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1150","question":"Assertion (A): Both Sternberg’s and Gardner’s theories go beyond the traditional view of intelligence as what IQ tests measure. Reason (R): Both theories hold that intelligence consists of exactly three abilities.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Both theories broaden the idea of intelligence beyond IQ, but only Sternberg proposes three aspects (analytical, creative, practical); Gardner proposes eight or more intelligences.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1151","question":"A test asks students to find one word that links ‘cottage’, ‘Swiss’ and ‘cake’ (answer: cheese). The test is based on Sarnoff Mednick’s view that creativity involves:","options":["Combining remote associative elements into new, useful connections","Remembering lists of words by rote","Choosing the one correct option from a set of four","Repeating the teacher’s explanation in one’s own words without adding anything"],"answer":0,"explanation":"Mednick’s associative theory and his Remote Associates Test treat creativity as the ability to link distant ideas; creative people have flatter association hierarchies and reach remote associations more readily.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1152","question":"E. Paul Torrance offered principles for teachers to encourage creative thinking. Which of the following runs AGAINST them?","options":["Treating unusual questions with respect","Showing children that their ideas have value, even unusual ones","Allowing periods of practice and exploration without the threat of evaluation","Evaluating every attempt immediately so children learn the right answer fast"],"answer":3,"explanation":"Torrance urged respect for unusual questions and imaginative ideas and time to explore without constant evaluation; immediate judgement of every attempt discourages risk-taking.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1153","question":"A district selects children for its talent programme only through teacher nominations. Very few girls and rural children are selected. The most likely explanation is that:","options":["Girls and rural children are less often gifted, so the low numbers simply reflect real ability","Teacher nominations alone can reflect stereotypes and miss talent that doesn’t fit the usual image","Teachers are accurate judges of talent, since they observe their children closely every day in class","Rural children and their families rarely want to join such programmes held away from home"],"answer":1,"explanation":"Giftedness occurs in all groups; under-representation signals biased identification. Multiple measures, non-verbal tasks and local norms help find overlooked talent.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1154","question":"Eight-year-old Advait reads books meant for Class 8 and discusses planets like an adult, but he cries and throws the board when he loses a game of ludo. The best interpretation is that:","options":["His intellectual ability must be overrated, since truly gifted children are always emotionally mature","He is being deliberately difficult to get attention and should be punished to stop the habit","His development is asynchronous: his intellect is ahead of his emotional development, which needs support","His advanced reading level is itself caused by emotional problems that make him withdraw into books all day"],"answer":2,"explanation":"Gifted children often show asynchronous development, with cognitive skills far ahead of emotional and social skills; adults should not expect adult-like emotional control just because of advanced intellect.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1155","question":"Gifted Class 6 student Mehr refuses to begin a drawing or an essay unless she is sure it will be perfect, and tears up work with small mistakes. The most helpful teacher response is to:","options":["Praise only her perfect final products, so that she sees her high standards are rewarded","Value effort, drafts and the learning process, and show that mistakes are a normal part of learning","Exempt her from any task she finds difficult, so that she does not become anxious","Tell her that gifted children should never make mistakes, so she must check her work more carefully"],"answer":1,"explanation":"Unhealthy perfectionism is common in gifted children; stressing process, revision and learning from errors reduces fear of failure, while praising only perfect results feeds it.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1156","question":"The ‘reaction range’ concept describes heredity and environment as working together in which way?","options":["Heredity sets a range of possible outcomes; environment influences where in that range one ends up","Environment sets the range of possible outcomes, and heredity then decides the exact point reached","Heredity alone fixes the exact level of a trait, and environment only affects how it is shown","Heredity and environment each contribute exactly 50 per cent to every trait in every individual"],"answer":0,"explanation":"A genotype allows a range of outcomes; enriched or deprived environments push development towards the upper or lower part of that range, so the same genes can produce different results.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1157","question":"Which pair of findings together shows that BOTH heredity and environment influence measured intelligence?","options":["Identical twins reared apart are no more alike than strangers; adopted children never change in their IQ","Siblings are more alike in IQ than strangers are; brothers are on average taller than their sisters","Identical twins reared apart are still quite similar in IQ; adoption into enriched homes raises scores","IQ scores never change over the lifespan, and all children in a family have exactly the same IQ"],"answer":2,"explanation":"Similarity of identical twins reared apart points to genetic influence, while IQ gains among children adopted into enriched homes point to environmental influence.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1158","question":"A survey finds that on average, children from higher-income families in a city score higher on a reading test than children from lower-income families. Which inference IS justified?","options":["Any low-income child in the class will score lower than any high-income child on this same reading test","The difference must be genetic, since all the children took exactly the same reading test under the same conditions","Income itself makes children more intelligent, so raising family income will raise every child’s score","Income-linked circumstances such as books, nutrition and schooling may contribute to the average difference"],"answer":3,"explanation":"Group averages say nothing certain about individuals, and a correlation does not show genetic cause; differences in resources and opportunities are a plausible explanation that further study can test.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1159","question":"Cross-cultural research on how communities define ‘intelligence’ shows that:","options":["All cultures define intelligence in exactly the same way, as speed in solving abstract puzzles and problems","Only Western cultures have a clear concept of intelligence; others think mainly of character","Cultures that value social skills have no concept of reasoning or problem-solving ability at all","Many communities count social qualities such as responsibility, cooperation and wisdom as intelligence"],"answer":3,"explanation":"Studies in Africa and Asia, for example, find that ideas of intelligence often include social responsibility and getting along with others, not just quick abstract reasoning, which is why tests from one culture may not fit another.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1160","question":"A school builds ramps, keeps a lift working, places a wheelchair user’s class on the ground floor and adapts its PE activities, so that Arnav, who uses a wheelchair, takes part fully. This approach reflects:","options":["The medical model, which treats disability as a problem located within the individual child","The social model, which sees disability as created largely by barriers in the environment","The charity model, which sees disabled children mainly as objects of pity and donation","The deficit model, which seeks only to correct the child rather than change the school"],"answer":1,"explanation":"The social model holds that people are disabled mainly by inaccessible environments and attitudes, so removing barriers enables participation; this view also underlies inclusive education.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1161","question":"Two groups of students obtain different average scores on an aptitude test. Which statement is most accurate from a measurement point of view?","options":["Unequal averages alone do not prove bias; bias means the test measures or predicts differently for groups","The difference proves that the lower-scoring group has less of the ability being measured","The difference proves that the test is biased against the lower-scoring group in some way","Tests can never be biased once they have been carefully standardised on a large, representative national sample"],"answer":0,"explanation":"Mean differences may reflect real differences in opportunity or skill; test bias concerns whether the items and scores mean the same thing for different groups. Standardisation alone does not guarantee fairness.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1162","question":"The National Education Policy 2020 proposes changes to board examinations. Which of the following reflects its stated direction?","options":["Board exams that test core capacities and competencies rather than coaching and memorisation","Adding board exams at the end of every class from Class 1, so that learning is tracked very closely","Making board exams more difficult so that only the best-prepared students pass them","Abolishing all assessment until Class 12 so that children learn without any pressure"],"answer":0,"explanation":"NEP 2020 aims to make board exams ‘easier’ in the sense of testing core concepts and competencies, reducing the need for coaching and rote learning.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1163","question":"Vygotsky argued that to study the relation between thought and speech, one must take a unit that keeps the properties of both. Which unit did he propose?","options":["The phoneme","The grammatical sentence","The conditioned reflex","Word meaning"],"answer":3,"explanation":"For Vygotsky, word meaning is at once a linguistic and an intellectual phenomenon (a generalisation), so it is the unit of verbal thought; meanings develop as children’s concepts develop.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1164","question":"‘The hunter shot the tiger’ and ‘The tiger was shot by the hunter’ look different but mean the same. In Chomsky’s early transformational grammar, they share the same:","options":["Deep structure, with different surface structures","Surface structure, with different deep structures","Phonology and morphology","Holophrase"],"answer":0,"explanation":"Chomsky distinguished the underlying deep structure (meaning relations) from the surface structure (actual word order); transformations such as the passive map one onto the other.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1165","question":"Talking to her baby, a mother in Lucknow uses short sentences, a higher pitch, exaggerated intonation, many repetitions and frequent pauses for the baby’s turn. Interactionist theorists view such child-directed speech as:","options":["Harmful, because it gives the child an incorrect, babyish model of how adult language really works","Irrelevant, because grammar is entirely innate and simply unfolds whatever the input","Helpful, because it holds attention and makes language structure easier for the child to pick up","A form of punishment and reward that gradually shapes correct speech in the baby"],"answer":2,"explanation":"Interactionists argue that child-directed speech supports learning by holding attention, highlighting words and boundaries and inviting turn-taking, while not denying innate capacities.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1166","question":"A teacher says, ‘The Inuit have hundreds of words for snow, so they literally see snow differently from us; this proves language determines thought.’ Which evaluation is soundest?","options":["Correct: it is strong proof of linguistic determinism, since words decide what people are able to perceive","The snow-word count is exaggerated, and vocabulary mainly reflects what a group needs to talk about","Correct, because English speakers cannot tell different kinds of snow apart without the words","Incorrect, because language never influences thought in any way; perception is the same for all"],"answer":1,"explanation":"The snow example is widely overstated; skiers and others develop special terms when they need them. Vocabulary follows needs and can draw attention, but it does not prevent perceiving distinctions.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-1167","question":"A Class 6 science teacher notices that every scientist pictured in the textbook is a man. Which step best addresses the resulting gender message?","options":["Add stories and pictures of women scientists, including Indian ones, and invite women professionals","Tell students that science careers have mostly been for men, so the pictures are simply accurate","Ignore it, because pictures in a textbook do not really affect what children learn or come to believe","Remove all pictures of scientists from the classroom so that no one feels left out"],"answer":0,"explanation":"Counter-stereotypical role models broaden children’s ideas of who can do science; materials that show only men send a hidden message about who belongs in the field.","difficulty":"moderate","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1168","question":"After a popular cartoon showed its hero solving problems by hitting others, a Class 2 teacher notices several children copying the same blows and catchphrases in the playground. Bandura would explain this as learning from:","options":["A live model through direct reinforcement","Classical conditioning to the television","A symbolic model presented through media","Trial and error"],"answer":2,"explanation":"Bandura described live models, verbal instructions and symbolic models (characters in films, books, television). Children can acquire behaviour from symbolic models without being reinforced themselves.","difficulty":"moderate","source":"CTET Paper 1 · REET"},
  {"id":"cdp-child-development-1169","question":"Children weak in subtraction were given the same 42-page workbook. One group was asked to aim for six pages each day; another was asked only to finish all 42 pages by the end of a week. Research by Bandura and Schunk predicts that the first group will show:","options":["Lower self-efficacy, because daily targets create pressure and constant fear of failure","No difference in outcome, since the total amount of work and time is exactly the same","Greater dependence on the teacher, who must check their pages every day","Greater self-efficacy and skill, because near goals give frequent evidence of progress"],"answer":3,"explanation":"Proximal (near) goals provide regular signals of mastery, which raise self-efficacy and motivation; distant goals give little feedback along the way.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1170","question":"Which statement about verbal persuasion as a source of self-efficacy is most accurate?","options":["It works best when encouragement is realistic and followed by tasks the learner can succeed at","It is the strongest of the four sources Bandura described, stronger even than past success","It works even when the learner keeps failing, as long as the encouragement is repeated often","It has no effect on self-efficacy at all, since only one’s own direct experience counts for anything"],"answer":0,"explanation":"Persuasion can boost self-efficacy, but its effect is weaker than mastery experiences and collapses if not confirmed by success, so it should be realistic and linked to achievable tasks.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-1171","question":"In front of the whole class, a student caught copying is made to retake the test after school. Over the next weeks other students copy less, although they themselves were never punished. This is an example of:","options":["Vicarious reinforcement","Vicarious punishment","Negative reinforcement","Response facilitation"],"answer":1,"explanation":"Observing a model's behaviour being punished reduces the observer's tendency to perform it; this is vicarious punishment, the counterpart of vicarious reinforcement.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1172","question":"For a group of Class 8 students who are anxious about solving equations, which peer demonstration is most likely to raise their self-efficacy?","options":["A classmate who solves every problem instantly and without any error, to show it is easy","A recorded expert who explains the method very fast, covering every type of problem","A classmate who shows some confusion, explains how he copes, then solves them step by step","No model at all, since anxious students learn best by working through problems alone"],"answer":2,"explanation":"Schunk's work showed that coping models, who show difficulty and then overcome it, are often more effective than flawless mastery models for anxious or low-achieving learners, because they seem more similar.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1173","question":"Just before a physics test, a teacher remarks to the class, ‘Girls usually find physics harder than boys.’ Girls who had done well in practice score lower on the test. Which explanation is most consistent with research?","options":["Girls lack real ability in physics, and the test simply revealed this more clearly than practice did","The test was harder than the practice papers, which explains everyone’s lower scores on it","Girls were not motivated, since the test did not count towards their final marks","Stereotype threat: a reminder of a negative group stereotype can raise anxiety and lower performance"],"answer":3,"explanation":"Stereotype threat studies show that activating a negative stereotype about one's group can impair performance on a challenging test by adding worry, independent of real ability.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1174","question":"A teacher poses a question, gives children a minute to think silently, then asks them to discuss with a partner before sharing with the class. This strategy mainly reflects:","options":["Social constructivism: understanding built through dialogue","Classical conditioning of answers to the teacher’s question","Programmed instruction through small, fixed steps","Rote learning through repetition with a partner"],"answer":0,"explanation":"Think–pair–share lets learners first form their own ideas and then refine them through talk with a peer, an application of the social construction of knowledge.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-1175","question":"Which question by a Class 6 science teacher is most likely to encourage children to construct understanding?","options":["‘What is the boiling point of water, and in which unit is it measured?’","‘What would happen to the boiling point if we added salt, and how could we find out?’","‘Who discovered the thermometer, and in which year was it invented?’","‘Write the definition of evaporation from the textbook and learn it by heart for tomorrow’s test.’"],"answer":1,"explanation":"Open, investigative questions ask children to predict, reason and design ways to test ideas, which engages them in constructing knowledge rather than recalling facts.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1176","question":"Class 7 students in a Rajasthan village survey water use in their homes, design a model rooftop rainwater harvesting system, and present it to the panchayat. Which approach and principle does this best illustrate?","options":["Programmed learning, since the project work is broken into small sequential frames","Behaviourist drill, since survey and model skills are repeated until fluent","Project-based learning rooted in constructivism, linking knowledge to real problems","Formal discipline, since hard and lengthy work trains the faculties of the mind"],"answer":2,"explanation":"Project-based learning engages learners in authentic, extended investigations; they construct knowledge by applying ideas to a real community problem, as NCF 2005 recommends.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1177","question":"In a jigsaw activity on the freedom struggle, each member of a group studies one movement with members of other groups who have the same movement, then returns to teach it to the home group. Why does this work well?","options":["Each child learns only one movement, so the workload is lighter and the whole topic is covered much faster","The teacher’s role is removed, so students become fully independent of adult guidance","Children compete for the highest marks, since each one’s piece is tested separately","It creates positive interdependence: every member’s part is needed and each must explain it to others"],"answer":3,"explanation":"Jigsaw makes each learner responsible for a piece the group needs; explaining to peers deepens understanding and every member's contribution matters.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-1178","question":"Which sequence correctly describes how, for Piaget, a child's understanding changes?","options":["Equilibrium → disequilibrium → assimilation and accommodation → a new, higher equilibrium","Accommodation → reinforcement → assimilation → extinction of the earlier idea","Disequilibrium → conditioning → imitation of adult models → return to the original equilibrium","Equilibrium → punishment for errors → disequilibrium → memorisation of the answer"],"answer":0,"explanation":"Equilibration is the self-regulating process: experiences that do not fit cause disequilibrium, which is resolved by assimilation and accommodation into a more advanced balance.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1179","question":"Which form of assessment fits a constructivist classroom best?","options":["A single end-of-year test of memorised answers, marked strictly against the answer key","Portfolios and open-ended tasks that show how children’s thinking develops over time","Rapid oral drills marked right or wrong, to check that facts are firmly fixed","Copying exercises checked for neatness and accuracy of the copied text"],"answer":1,"explanation":"Constructivist assessment looks at the process and growth of understanding, using portfolios, projects and open tasks, in line with continuous and comprehensive evaluation.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-1180","question":"At age four, Ayesha solves jigsaw puzzles with her mother, who says things like ‘Find the edges first; look for the blue sky.’ At five she mutters the same hints to herself while working; at seven she solves puzzles silently. Which idea of Vygotsky does this sequence show?","options":["Assimilation followed by accommodation, as she adjusts her puzzle schema through experience","Overjustification","Learned helplessness","Internalisation: a function appears first between people, then within the child"],"answer":3,"explanation":"Vygotsky held that higher mental functions appear first on the social (interpsychological) plane and then on the individual (intrapsychological) plane, via private speech that becomes inner speech.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1181","question":"Which statement correctly relates the zone of proximal development and scaffolding?","options":["They are two names for the same thing, both introduced by Vygotsky to describe teaching","Scaffolding is the region of potential learning, and the ZPD is the help given by the adult or peer","The ZPD is the range of tasks a child can do with help; scaffolding is the support given within it","Both refer to what a child can already do completely alone, without any help"],"answer":2,"explanation":"The ZPD (Vygotsky) is a region of potential development; scaffolding (a term introduced by Wood, Bruner and Ross) is the temporary, adjustable support that helps the learner work within it.","difficulty":"hard","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-1182","question":"A teacher says, ‘Constructivism means every child's answer is equally correct, because each child builds his own knowledge.’ Which reply is most accurate?","options":["She is right; constructivism rejects any standard of correctness, since all knowledge is purely personal","Constructivism applies only to primary classes, so it says nothing about correctness in later years","Constructivism holds that knowledge is transmitted, so only the teacher’s answer is correct","Children build knowledge actively, but ideas are still tested against evidence, and some are more valid"],"answer":3,"explanation":"Constructivism describes how knowledge is built, not that all ideas are equally valid. Teachers help children test and revise their ideas against evidence and shared knowledge.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1183","question":"When Class 5 student Arif says that a heavier ball falls faster, the teacher asks, ‘If you tie a heavy ball to a light one, would the pair fall faster or slower than the heavy ball alone?’ Arif hesitates and starts rethinking. The teacher is using:","options":["Socratic questioning that leads him to a contradiction in his own idea","Negative reinforcement, removing his wrong idea by asking a question","Rote drill of the law of falling bodies","Programmed instruction that breaks the idea into small graded steps"],"answer":0,"explanation":"By a question that reveals a contradiction (the light ball should both slow and speed the pair), the teacher prompts Arif to reconstruct his idea himself rather than be told.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1184","question":"Vygotsky wrote that in play a child behaves ‘a head taller’ than himself. Which classroom implication follows?","options":["Play should be removed from school to make more time for serious academic learning","Pretend play with roles and rules creates a ZPD where children practise self-control","Play is useful mainly for physical exercise and letting off energy between lessons","Only free play without any rules supports development, since rules restrict imagination"],"answer":1,"explanation":"In make-believe play children follow the rules of roles and use objects symbolically, functioning above their everyday level; Vygotsky saw play itself as creating a ZPD.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1185","question":"A young apprentice at a potter's workshop in Khurja first watches the master, then makes small pots with the master guiding his hands, receives less and less help over months, and is finally left to work alone while the master only checks. This sequence best matches:","options":["Classical conditioning of hand movements to the sight of the spinning wheel","Learned helplessness","Cognitive apprenticeship: modelling, coaching, scaffolding and fading","Formal discipline"],"answer":2,"explanation":"Cognitive apprenticeship applies Vygotskian ideas: the expert models, coaches and scaffolds, then fades support so the learner becomes independent.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-1186","question":"Before a unit on birds, a Class 4 teacher makes a chart with three columns: ‘What we Know’, ‘What we Want to know’, and later ‘What we Learnt’. The first column mainly serves to:","options":["Find out who is the most intelligent child in the class before the teaching begins","Test children’s memory of the definitions they learnt last year","Replace the lesson plan with whatever the children want to learn","Activate and reveal prior knowledge so that new learning can be linked to it"],"answer":3,"explanation":"A KWL chart begins by surfacing what children already know or believe, which lets the teacher connect new ideas to it and spot misconceptions.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1187","question":"Assertion (A): Piaget was sceptical of attempts to push children through his stages faster by direct training. Reason (R): For Piaget, a child's developmental level sets limits on what he can understand from instruction.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because Piaget saw development as preceding learning, he called acceleration 'the American question' and doubted its value; instruction can help only when the child is developmentally ready.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1188","question":"Why do constructivist teachers often ask children to explain an answer in their own words rather than repeat the textbook line?","options":["To reduce the time spent on the topic, since textbook lines take longer to copy out","To test their handwriting and spelling in addition to their knowledge of the topic","Because explaining makes learners reorganise ideas and shows what they have really understood","Because textbook language is usually wrong or far too difficult for children to be trusted at all"],"answer":2,"explanation":"Putting ideas in one's own words is elaborative processing that builds understanding, and it shows the teacher whether the concept, not just the wording, has been grasped.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1189","question":"Which statement about Ausubel's view of reception learning is correct?","options":["Reception learning is always rote and should be avoided in favour of pure discovery","Learning by being told can be meaningful if it is related to relevant ideas the learner already has","Only discovery learning can be meaningful, since being told leaves the learner passive","Ausubel rejected advance organisers because they give away the content before the lesson has even begun"],"answer":1,"explanation":"Ausubel argued that reception (expository) learning is not necessarily rote; it becomes meaningful when new information is anchored to existing cognitive structure, often via advance organisers.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1190","question":"Students must lift a small weight using a ruler, a pencil and a few books, but most cannot think of using the ruler as a lever because they see it only as a measuring tool. Gestalt psychologists call this obstacle to insight:","options":["Spontaneous recovery","Proactive interference","Overlearning","Functional fixedness"],"answer":3,"explanation":"Functional fixedness (Duncker) is the tendency to see objects only in their usual function, which blocks restructuring of the problem and the insight needed to solve it.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1191","question":"In a social constructivist Class 3 maths period, two children disagree about whether 1/3 of a chapati is bigger than 1/4. What should the teacher do?","options":["Let them justify their views and test them with real chapatis or paper circles","Tell them the correct answer immediately to save time for the rest of the lesson","Separate them so that the disagreement does not turn into a quarrel","Give a mark to whoever is right, so that both learn to be careful"],"answer":0,"explanation":"Disagreement is an opportunity for reasoning and evidence. Testing ideas with concrete material and discussing them helps both children construct the idea that more equal parts means smaller parts.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1192","question":"Which of these statements about insight learning are correct? I. It involves perceiving the relationships among the parts of a problem. II. Once achieved, the solution is usually remembered and can be repeated easily. III. It depends on the learner's past experience as well as on how the problem is presented. IV. It occurs only in humans and never in animals.","options":["I and IV only","I, II and III only","II and IV only","I, II, III and IV"],"answer":1,"explanation":"Köhler demonstrated insight in chimpanzees, so IV is false. Insight rests on perceiving relationships, is well retained, and is influenced by both experience and the arrangement of the problem.","difficulty":"hard","source":"CTET · REET"},
  {"id":"cdp-child-development-1193","question":"A Class 10 boy races his motorbike without a helmet and tells his worried teacher, ‘Accidents happen to other people. Nothing will happen to me.’ Elkind would explain this belief as:","options":["Imaginary audience","Personal fable","Moral realism","Identity foreclosure"],"answer":1,"explanation":"The personal fable is the adolescent’s belief that he is unique and invulnerable, which feeds risk-taking. The imaginary audience is the belief that everyone is watching and judging him.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1194","question":"After a break-up, a Class 11 girl writes in her diary, ‘Nobody in the world has ever felt pain like mine; my parents could never understand.’ Which aspect of adolescent egocentrism does this show?","options":["Imaginary audience","Centration","Personal fable","Animism"],"answer":2,"explanation":"Feeling that one’s experiences are so unique that no one else can understand them is the uniqueness side of the personal fable. Centration and animism belong to pre-operational thinking.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1195","question":"Match the adolescent statements with Elkind’s concepts: P. ‘Everyone in the assembly noticed my new haircut and is laughing.’ Q. ‘I can smoke; I won’t get addicted like others.’ R. ‘I’m sure the whole class is talking about my spot.’ S. ‘My feelings are too special for anyone to understand.’","options":["P-imaginary audience, Q-personal fable, R-imaginary audience, S-personal fable","P-personal fable, Q-imaginary audience, R-personal fable, S-imaginary audience","P-imaginary audience, Q-imaginary audience, R-personal fable, S-personal fable","P-personal fable, Q-personal fable, R-imaginary audience, S-imaginary audience"],"answer":0,"explanation":"Feeling observed and judged (P, R) is the imaginary audience; feeling invulnerable or uniquely special (Q, S) is the personal fable.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1196","question":"G. Stanley Hall described adolescence as a period of inevitable ‘storm and stress’. Margaret Mead’s studies in Samoa were taken to challenge this by suggesting that:","options":["Adolescence is stormier in simple societies than in industrial ones, because of early marriage and work","Puberty is delayed in some societies, so adolescence and its stresses never really occur there","The degree of adolescent turmoil depends greatly on culture, so storm and stress is not universal","Adolescents everywhere go through the same emotional crises, whatever their culture"],"answer":2,"explanation":"Mead argued that Samoan adolescents passed through puberty relatively smoothly, so cultural context shapes adolescent experience. Modern research agrees that serious turmoil is not universal, though conflict and mood swings are more common than in childhood.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1197","question":"Research shows adolescents take far more risks in a driving game when friends are watching than when alone, while adults are not affected this way. Which explanation is best supported?","options":["Adolescents simply cannot understand risks at all, whether friends are present or not","Adolescents are deliberately disobedient by nature and like to break adult rules","The adolescent brain is already fully mature, so the behaviour is purely a matter of social pressure","Reward systems mature before prefrontal self-control systems, so peers boost the pull of rewards"],"answer":3,"explanation":"Reward-related systems become highly responsive around puberty while prefrontal control matures into the twenties; peers heighten the reward value of risky choices. Adolescents often know the risks but act differently in emotionally charged settings.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1198","question":"Before a school trip, a Class 11 teacher wants to reduce risky behaviour. In the light of research on adolescent decision-making, what is likely to work best?","options":["Giving a detailed lecture on the dangers of risky behaviour, since facts alone change behaviour","Framing rules with students, ensuring supervision and planning for peer-driven risky moments","Leaving them completely free, as adolescents must learn from their own mistakes","Threatening severe punishment for any misbehaviour, without explaining the reasons"],"answer":1,"explanation":"Adolescents often know the facts but act on emotion with peers; shared rule-making respects their autonomy, while structure and supervision limit high-risk ‘hot’ situations.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1199","question":"Class 9 students angrily point out that adults preach honesty yet bribe officials, and some draw up plans for a ‘perfect’ society. Which response best fits their developmental stage?","options":["Treat it as disrespect towards elders and punish it so that it does not spread","Tell them idealism is childish and that they will grow out of it once they start working","Channel it into debates and community projects that test ideals against practical constraints","Avoid all discussion of social issues in class, since it distracts from the syllabus and exams"],"answer":2,"explanation":"Formal operational thought lets adolescents imagine ideal possibilities and spot inconsistencies; constructive outlets build reasoning and civic sense instead of suppressing a normal developmental trait.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1200","question":"In Class 6, a girl who has entered puberty much earlier than her classmates is teased about her body, has started mixing with much older students and seems unhappy with her appearance. What does research on pubertal timing suggest?","options":["Early-maturing girls are at greater risk of low mood and body dissatisfaction, so she may need support","Early maturation is always an advantage for girls, as they quickly gain status and popularity among classmates","Pubertal timing has no real effect on adjustment, so her unhappiness must have another cause","She should be moved to a higher class to be with peers of her own size and maturity level"],"answer":0,"explanation":"Early maturation in girls is consistently linked with greater risk of emotional and behavioural difficulties, partly because they are out of step with peers; discreet support and stopping teasing help.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1201","question":"Which statement about pubertal timing in boys is best supported by research?","options":["Late-maturing boys usually enjoy the highest peer status, since they stay children for longer and seem carefree","Early-maturing boys tend to gain status and confidence, though they also show some higher risks","Pubertal timing affects only girls; for boys it makes no difference to adjustment","Late maturation in boys is a medical disorder that always needs hormonal treatment"],"answer":1,"explanation":"Early-maturing boys are often seen as more mature and athletic, gaining status, though they also show some higher risk-taking; late maturers may feel less confident. Late maturation within the normal range is not a disorder.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1202","question":"A Class 11 teacher complains that many students are drowsy in the first period despite being ‘told to sleep early’. What is the best developmental explanation?","options":["Their heavy study load leaves too little time for sleep, so homework should be cut","Late-night screen use is the cause, so a talk on mobile habits will fix the drowsiness","Growth spurts drain their energy, so they need a nutritious breakfast before school","Puberty shifts the body clock later, so they cannot fall asleep early and lose sleep"],"answer":3,"explanation":"Puberty delays the circadian rhythm (later melatonin release), so adolescents cannot fall asleep early, which is why simply telling them to sleep early fails. A growth spurt raises energy needs but does not explain drowsiness tied to the first period; study load and screens are habits and circumstances, not the developmental cause asked for.","difficulty":"very-hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1203","question":"In Classes 6 and 7, many girls are taller than boys of the same age, but by Class 10 this is usually reversed. The best explanation is that:","options":["Girls on average begin their adolescent growth spurt about two years earlier than boys","Boys are less well nourished than girls in early adolescence, so their growth starts later","Girls stop growing completely at about age twelve, while boys keep growing","Height depends entirely on environment, which changes between Class 6 and Class 10"],"answer":0,"explanation":"Girls typically enter the growth spurt earlier; boys start later but grow for longer and more, so they overtake girls in mid-adolescence.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1204","question":"Over the past century, the average age of first menstruation has fallen in many countries, including India. This trend is mainly attributed to:","options":["Television and cinema","Changes in the human genome over a few generations","Better nutrition and health","Earlier admission to school"],"answer":2,"explanation":"The ‘secular trend’ toward earlier puberty is linked mainly to improved nutrition and health; genes cannot change so quickly across a few generations.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1205","question":"A school plans sessions on puberty and reproductive health under the Adolescence Education Programme, but some parents object. What is the most appropriate approach?","options":["Cancel the sessions, as such topics belong only at home and parents’ wishes must come first","Hold the sessions quietly without informing parents, since students need the information in any case","Leave students to learn from the internet, where they can read privately without embarrassment","Explain the age-appropriate, accurate content to parents, address their concerns and involve them"],"answer":3,"explanation":"Adolescents need accurate information and life skills; engaging parents transparently builds support. Silence or the internet leaves them to myths and risky sources.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1206","question":"A Class 8 student is cheerful one moment and irritable or tearful the next, and her teacher calls her ‘moody and rebellious’ in front of the class. Which view is most accurate?","options":["Mood swings are common in early adolescence; the teacher should respond with empathy and privacy","The student clearly has a psychiatric disorder that needs immediate referral and medical treatment","Public labelling will help her notice her moods and learn to control them quickly","Mood changes are caused only by poor upbringing, so the parents should be called in at once"],"answer":0,"explanation":"Emotional ups and downs are common as bodies and relationships change; public labelling feeds the imaginary audience and resentment, whereas empathy and a private talk help. Persistent distress would need referral.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1207","question":"A Class 10 teacher finds students resisting rules imposed without discussion. Which practice best meets adolescents’ growing need for autonomy while keeping order?","options":["Removing all rules from the classroom so that students feel fully trusted","Imposing stricter rules with harsher penalties so that resistance stops quickly","Involving students in setting class norms and giving choices, within clear limits","Letting the class monitor decide everything, since students accept a peer more readily"],"answer":2,"explanation":"Supporting autonomy through participation and choice within clear limits reduces conflict and builds responsibility; having no rules or harsher rules ignores either the need for structure or the need for autonomy.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1208","question":"Which of these statements about adolescence are correct? I. The capacity for abstract and hypothetical thinking emerges. II. The peer group becomes more important. III. All adolescents necessarily pass through severe emotional turmoil. IV. The search for a personal identity becomes central.","options":["I, II and III only","I, II and IV only","II and IV only","I, II, III and IV"],"answer":1,"explanation":"Abstract thought, stronger peer ties and identity formation are characteristic; severe turmoil is not universal, so III is false.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1209","question":"Assertion (A): Adolescents often argue with parents and teachers about rules they used to accept. Reason (R): Their developing ability to think hypothetically lets them imagine alternatives and notice inconsistencies in adults’ reasoning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Formal operational thinking enables adolescents to question existing rules by imagining how things could be; R explains A.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1210","question":"Assertion (A): The imaginary audience makes many young adolescents intensely self-conscious. Reason (R): Young adolescents are unable to think about other people’s thoughts at all.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Adolescents CAN think about others’ thoughts; the error is assuming others are as focused on them as they are on themselves. So A is true but R is false.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1211","question":"A school wants to prevent tobacco and drug use among its Class 8–10 students. Which approach is best supported by evidence?","options":["Showing frightening images and stories once a year, so that the fear itself keeps students away from drugs","Life-skills sessions where students practise refusing offers, with accurate facts about real peer norms","Expelling any student found experimenting, so that others see the cost and stay away","Avoiding the topic altogether so as not to give students ideas they had not thought of"],"answer":1,"explanation":"Programmes that build refusal and decision-making skills and correct exaggerated beliefs about how many peers use substances work better than scare tactics, which adolescents often dismiss through the personal fable.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1212","question":"A Class 8 student is caught passing notes. Which disciplinary approach is most suitable for an adolescent, given what we know about the imaginary audience?","options":["Read the note aloud to the class so that others learn","Make the student stand outside the class for the rest of the period as a warning","Speak to the student privately, stating the problem clearly and respectfully","Ignore all such incidents in adolescence"],"answer":2,"explanation":"Public humiliation is magnified by adolescents’ sense of being watched and breeds resentment; a private, respectful talk addresses the behaviour while protecting dignity.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1213","question":"A Class 9 girl wants to skip physical education during her periods and is embarrassed to tell the male PE teacher. What is the most appropriate school response?","options":["Insist she participate fully like everyone else, without any discussion, so that no exceptions are ever made","Excuse all girls from PE permanently, so that no girl ever has to raise the issue at all","Announce in class that she cannot take part because she is menstruating, so that others understand","Create a private way to communicate, offer suitable options and teach all students facts about menstruation"],"answer":3,"explanation":"Respecting privacy and providing accurate menstrual education removes stigma; announcing it publicly or excluding girls altogether reinforces shame and inequity.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1214","question":"Before Class 11 stream selection, a student who loves biology is being pushed by his family to take commerce. What is the most appropriate role for the teacher?","options":["Tell him to obey his parents without question, since they know what is best for him","Decide the stream for him on the basis of his marks, since marks are the most objective guide","Tell the parents they have no right to advise him, since the choice is his alone","Help him weigh his interests and aptitudes and facilitate a discussion with his parents"],"answer":3,"explanation":"Guidance supports informed, self-owned choice: identity achievement needs exploration. The teacher facilitates rather than imposing a decision or setting the student against his family.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1215","question":"Which change in friendships is most characteristic of adolescence compared with middle childhood?","options":["Friendships become based mainly on sharing toys, games and playing near each other in the lane","Friendships become based more on intimacy, loyalty and sharing of thoughts and feelings","Adolescents stop forming close friendships and rely only on family","Friendships are chosen mainly by parents"],"answer":1,"explanation":"Adolescent friendships centre on self-disclosure, loyalty and emotional support; play-based friendships are typical of younger children.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1216","question":"Elkind held that adolescent egocentrism declines by mid-to-late adolescence. Which experience is most likely to help it decline?","options":["Close peer interaction, in which they discover that others are absorbed in their own similar concerns","Isolation from peers for a while, so as to avoid embarrassment and protect self-esteem","Strict rules from adults about how to behave in public, so that self-consciousness fades","Repeated public correction of their behaviour, so that they learn exactly how other people really see them"],"answer":0,"explanation":"Through intimate peer exchange, adolescents learn that others share similar worries and are not constantly watching them, which reduces both the imaginary audience and the personal fable.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1217","question":"Given a pendulum and asked what determines how fast it swings, a Class 9 student changes only the string length while keeping the weight and the push the same, then repeats for each factor. In Piaget’s terms this shows:","options":["Concrete operational trial and error, since he works with real objects only","Hypothetico-deductive reasoning, a mark of formal operational thought","Pre-operational centration","Sensorimotor exploration"],"answer":1,"explanation":"Forming hypotheses and systematically isolating variables is hypothetico-deductive reasoning; concrete operational children tend to vary several factors at once without system.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1218","question":"A child lines up ten pebbles and counts them from left to right, then from right to left, then arranges them in a circle and counts again. Each time she gets ten and exclaims that the number stays the same however she counts. Piaget would call the knowledge she has constructed:","options":["Physical knowledge, abstracted from the properties of the pebbles themselves","Social-conventional knowledge, passed on by adults","Logico-mathematical knowledge, built by reflecting on her own actions","Iconic knowledge, stored as images"],"answer":2,"explanation":"That number is independent of the order of counting is not a property of pebbles; it comes from coordinating her own actions. Piaget called this logico-mathematical knowledge.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1219","question":"In Piaget’s classification of knowledge, which of these can a child acquire ONLY by being told by other people?","options":["That a ball rolls but a cube does not","That 5 + 3 always gives the same total as 3 + 5, whatever the objects","That a heavier stone needs more force to lift than a lighter one","That the festival of lights is called ‘Diwali’ in most of India"],"answer":3,"explanation":"Names and customs are social-conventional knowledge, arbitrary and transmitted by others. The rolling and lifting examples are physical knowledge, and commutativity is logico-mathematical.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1220","question":"Arrange the sensorimotor substages in Piaget’s order: P. Coordination of secondary circular reactions Q. Primary circular reactions R. Reflexes S. Tertiary circular reactions T. Secondary circular reactions U. Beginnings of mental representation","options":["R, Q, T, P, S, U","R, T, Q, P, S, U","Q, R, T, S, P, U","R, Q, P, T, S, U"],"answer":0,"explanation":"The six substages run from reflexes, through primary, secondary and coordinated secondary reactions, to tertiary reactions and finally mental representation at about 18 to 24 months.","difficulty":"hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1221","question":"A two-month-old accidentally gets his thumb in his mouth, and then keeps bringing it back to suck again and again. Piaget would classify this as:","options":["A secondary circular reaction","A tertiary circular reaction","Deferred imitation","A primary circular reaction"],"answer":3,"explanation":"Primary circular reactions (about 1 to 4 months) repeat chance actions centred on the infant’s own body. Secondary reactions involve effects on external objects.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1222","question":"Infants of about 8 to 12 months often squeal with delight when a parent hides her face behind a dupatta and then reappears. In Piaget’s terms, the game is enjoyable at this age mainly because:","options":["The infant has mastered conservation and knows the face stays the same size when hidden","Object permanence is developing, so the infant expects the face to be there and enjoys its return","The infant is showing animism, treating the dupatta as a living thing that moves and hides by itself","The infant is using the symbolic mode, pretending that the dupatta is something else"],"answer":1,"explanation":"Once infants begin to represent objects that are out of sight, the hidden face sets up an expectation that is confirmed on reappearance. Much younger infants do not search for what disappears.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1223","question":"Which question in a Class 10 history lesson most clearly calls for formal operational thinking?","options":["‘In which year did the Dandi March take place, and on which date did it reach Dandi?’","‘Name the leader of the Dandi March and list the places where the marchers halted.’","‘If the salt tax had never existed, what other symbol might the movement have chosen, and why?’","‘Draw a map showing the full route of the march from Sabarmati Ashram to the sea coast at Dandi.’"],"answer":2,"explanation":"Reasoning about a counterfactual situation and its consequences requires hypothetical thinking. The other questions call for recall or representation of concrete facts.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1224","question":"A Class 4 teacher shows that a solid block of ice floats on water, although the children believe all solids sink. The main purpose of such a discrepant event, in Piaget’s terms, is to:","options":["Create disequilibrium that motivates children to revise their schemas","Entertain children with a surprise so that they pay attention to the lesson","Reinforce children’s existing belief","Test their memory of facts"],"answer":0,"explanation":"A surprising result that contradicts a belief upsets equilibrium and pushes children to accommodate. Mere entertainment or recall is not the aim.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1225","question":"A teacher wants to challenge a Class 3 child’s belief that bigger things are always heavier. Which experience is MOST likely to lead to real accommodation?","options":["A lecture on density with formulae, so that she learns the correct scientific idea","Lifting a large inflated balloon and then a small marble-sized stone, and comparing them","Being told clearly that the belief is wrong, and then moving on to the next topic","Watching a video on atomic structure that explains why some materials are heavier than others"],"answer":1,"explanation":"Piaget’s idea is that conflict should be just beyond the child’s schema and directly experienced. A formula or atomic structure is too far from her thinking to be assimilated.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1226","question":"A teacher trains Class 1 children to answer ‘same’ in conservation tasks. They now say ‘same’, but when asked ‘Why?’ they reply, ‘Because you told us.’ Piaget would say that:","options":["They have truly acquired conservation, since they give the right answer","Conservation is a formal operational skill, so they could not acquire it yet","Their answer without a logical justification does not show real conservation","Training has helped them skip the pre-operational stage altogether"],"answer":2,"explanation":"Piaget counted a child as conserving only if she could justify the answer through identity, reversibility or compensation. A taught verbal response is not an operation.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1227","question":"Which of the following is an ‘operation’ in Piaget’s sense?","options":["Kicking a ball again and again to watch how it rolls away across the floor each time","Calling the moon alive because it seems to move along with the child","Copying a word written on the board accurately into one’s own notebook","Understanding that adding 4 and then taking away 4 brings you back to the start"],"answer":3,"explanation":"Operations are internalised mental actions that can be reversed and form logical systems. Repetitive kicking is sensorimotor, animism is pre-operational, and copying is not an operation.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1228","question":"A Class 9 student says, ‘I notice I always panic in maths tests and make silly mistakes, so I now check my work twice before handing it in.’ This ability to reflect on one’s own thinking develops mainly in Piaget’s:","options":["Pre-operational stage","Formal operational stage","Sensorimotor stage","Concrete operational stage"],"answer":1,"explanation":"Formal operations bring the ability to treat one’s own thoughts as objects of thinking. This underlies the planning and self-monitoring described here.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1229","question":"Asked to draw a map of their village, Class 1 children draw the temple, school and their own houses as large separate pictures without correct directions or distances, while Class 5 children place them in their correct positions relative to one another. The difference reflects:","options":["Coordinated spatial representation developing in the concrete operational stage","A decline in creativity and imagination as children grow older and begin to conform","Bruner’s claim that maps are enactive and drawn mainly through movement","The appearance of the personal fable, making each child draw his own world"],"answer":0,"explanation":"Concrete operational children can mentally coordinate positions and distances to form a cognitive map. Young children represent landmarks without integrating their spatial relationships.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1230","question":"Two toy cars move along parallel tracks for the same length of time. Car A starts well ahead of car B, and although car B covers a much longer distance, car A stops just ahead of it. A five-year-old says car A was faster ‘because it ended up in front’. This shows:","options":["Mature understanding of speed, distance and time","Formal operational proportional reasoning about distance and time","Centration on the end point, ignoring the starting point and time","Accommodation of the speed schema after seeing the race"],"answer":2,"explanation":"Piaget found that young children judge speed by who finishes ahead, ignoring distance covered and time. This is centration on one striking feature.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1231","question":"Assertion (A): A teacher should not make fun of a Class 1 child who says the moon follows her home. Reason (R): Such ideas are normal features of pre-operational thinking and give the teacher insight into how the child reasons.","options":["Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"Animistic and egocentric ideas are typical at this age and reveal the child’s reasoning. Ridicule would discourage expression without changing the thinking.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1232","question":"A teacher wants to introduce the idea of democracy. Which approach best suits Class 4 children according to Piaget?","options":["Ask them to compare democracy with other systems of government in purely abstract terms","Give them a definition of democracy to memorise","Hold a class election for monitor, with voting, counting and discussion of fairness","Discuss hypothetical constitutions for imaginary countries and compare them"],"answer":2,"explanation":"Concrete operational children grasp ideas best through real, familiar experiences. Abstract comparisons and imaginary constitutions call for formal operations.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1233","question":"Piaget believed that interaction with peers helps young children overcome egocentrism mainly because:","options":["Peers reward each other for correct answers","Peers always know the right answer","Interaction with peers is less important than interaction with adults for decentring","Disagreements with peers force children to notice that others see things differently"],"answer":3,"explanation":"Conflicting views from equals make the child aware of other perspectives, which promotes decentration. Piaget actually saw peers as more useful than adults for this.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1234","question":"Two equal rotis are made; one is cut into eight pieces. An eight-year-old says, ‘It is still the same amount to eat; you only cut it, you didn’t add any.’ The child is reasoning with:","options":["The identity argument, typical of the concrete operational stage","Transductive reasoning","Animism","Hypothetico-deductive logic, testing each piece against a hypothesis"],"answer":0,"explanation":"Noting that nothing was added or taken away is the identity justification for conservation. It typically appears in the concrete operational stage.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1235","question":"A toddler can find her way from her bedroom to the kitchen without any difficulty, but only years later can she draw a plan of the house. Piaget called the reappearance, at a higher level, of a skill already mastered at a lower level:","options":["Horizontal décalage","Vertical décalage","Assimilation","Equilibrium"],"answer":1,"explanation":"Vertical décalage is the reconstruction of the same content at a higher level of thought, here moving from practical action to representation. Horizontal décalage concerns unevenness within one stage.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1236","question":"Which instruction style best suits a group of pre-operational children in a Class 1 classroom?","options":["Long verbal explanations of all the rules before any activity, so that nothing is missed","Short steps with demonstrations and objects to handle, checking understanding as they go","Abstract written instructions on the board for children to read and follow","Debates on hypothetical situations"],"answer":1,"explanation":"Pre-operational children have limited attention and rely on perception and action. Short, demonstrated steps with concrete materials match their thinking.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1237","question":"How many of these statements are correct according to Piaget? I. Schemas exist even in infants, in the form of action patterns such as sucking and grasping. II. Assimilation changes existing schemas, while accommodation leaves them unchanged. III. Adaptation includes both assimilation and accommodation. IV. Organisation and adaptation are lifelong functions, while stages change.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct. Statement II reverses the terms: accommodation changes schemas, while assimilation fits new experience into existing ones.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1238","question":"A Class 6 student treats the letter in ‘a + b = b + a’ as standing for one particular number and cannot see that it holds for all numbers. In Piaget’s terms, the difficulty mainly arises because:","options":["Seeing letters as general variables needs formal operational thinking, which is only beginning now","The student is still in the sensorimotor stage and cannot use symbols at all","The student lacks object permanence, so the letter seems to stand for a hidden object","Algebra is purely social-conventional knowledge, so the meaning of the letters must simply be told to him"],"answer":0,"explanation":"Treating a symbol as standing for any number is an abstract generalisation typical of formal operations. Many students at 11 to 12 are still in transition, so concrete examples help.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1239","question":"A Class 2 child shown a picture puzzle can find the hidden animals by looking carefully at details, but when asked how many legs all the animals have together, she counts each animal separately and loses track. Which teaching support is best suited to her stage?","options":["Ask her to imagine a formula for the total and apply it in her head","Let her mark each animal’s legs with counters and group them","Tell her the answer and move on to the next puzzle","Give her a timed test on multiplication tables to build speed with groups"],"answer":1,"explanation":"Concrete markers let her keep track physically and see the grouping, matching her need for concrete support. A formula is too abstract and a timed test adds pressure without understanding.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1240","question":"Which statement about object permanence is in line with Piaget’s account?","options":["It is present at birth, as shown when newborns follow a moving face with their eyes","It develops only in the concrete operational stage, along with the conservation of number and length","It is learnt only through reinforcement by parents during games such as peek-a-boo","It develops across the sensorimotor period, complete when the child can infer unseen moves"],"answer":3,"explanation":"Piaget saw object permanence developing across the sensorimotor substages, completed when the child can imagine where an object went even without seeing it move, around 18 to 24 months.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1241","question":"Piaget believed that when an adult teaches a child something too early, the adult may keep the child from inventing it herself. Which classroom practice best reflects this concern?","options":["Giving children problems to explore before showing them the standard method","Starting every lesson with the formula and worked examples, then practice","Asking children to memorise results before doing the experiments themselves","Discouraging questions until the end of the year"],"answer":0,"explanation":"Piaget valued the child’s own construction of knowledge; letting children explore first gives them the chance to invent methods. Showing the formula first replaces their thinking.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1242","question":"Assertion (A): A child who has reached the concrete operational stage may still fail a task that requires conservation of weight. Reason (R): Piaget held that all conservation tasks are mastered at the same moment.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Different conservations appear at different ages even within the concrete stage (horizontal décalage), so A is true. R is false because Piaget did not claim they all arrive together.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1243","question":"Salma, aged 11, had never been to school. Under the RTE Act she is admitted to Class 5 with special training. She turns 14 while studying in Class 7. What is her position under the Act?","options":["Her right ends at 14, and the school may charge her fees for Classes 7 and 8 from then on","She must leave the school and join open schooling, since the Act covers only children aged 6 to 14","She stays entitled to free education till she completes elementary education, even after 14","She must be moved back to Class 5 to repeat the years she missed before her admission"],"answer":2,"explanation":"Section 4 provides that a child admitted to an age-appropriate class is entitled to free education till the completion of elementary education even after 14; the right does not stop mid-course.","difficulty":"very-hard","source":"CTET · UPTET · REET"},
  {"id":"cdp-child-development-1244","question":"A migrant worker’s seven-year-old son arrives in Pune in November without a birth certificate. The local government school says it cannot admit him because he has no proof of age and admissions closed in July. Under the RTE Act:","options":["Neither reason is valid: lack of age proof or a late request cannot bar admission","The school is right on both counts, as rules on age proof and admission dates protect order","He may be admitted only after his family obtains a birth certificate from the authorities","He can be admitted only at the start of the next academic year, in April or July"],"answer":0,"explanation":"Section 14 bars denial of admission for want of age proof, and Section 15 says no child shall be denied admission even if it is sought after the extended admission period.","difficulty":"very-hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1245","question":"A Class 6 teacher calls a student ‘duffer’ in front of the whole class and makes him stand outside for the period, without touching him. A colleague says this is allowed under the RTE Act because no physical punishment was given. This view is:","options":["Correct, because Section 17 bans only physical punishment and says nothing else","Correct, provided the parents have agreed to such measures in writing","Incorrect only if the child is below ten years of age; older children can be disciplined so","Incorrect, because Section 17 prohibits mental harassment as well as physical punishment"],"answer":3,"explanation":"Section 17 says no child shall be subjected to physical punishment or mental harassment; public humiliation and exclusion are forms of harassment, not acceptable alternatives.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1246","question":"Under Section 17 of the RTE Act, a teacher who contravenes the ban on physical punishment and mental harassment of children is:","options":["Dismissed automatically, without any inquiry","Liable to disciplinary action under the service rules applicable to him or her","Exempt if the act was meant to improve discipline","Liable only to pay compensation to the child’s parents, not to any service action"],"answer":1,"explanation":"Section 17(2) makes the contravention punishable through disciplinary action under the applicable service rules; good intentions are no defence.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1247","question":"Assertion (A): Supporters of the no-detention provision argued that holding children back increases dropouts without improving learning. Reason (R): The no-detention provision meant that children would not be assessed at all.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"No detention was paired with continuous and comprehensive evaluation, so children were to be assessed all the time; R confuses ‘no failing’ with ‘no assessment’.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1248","question":"Which argument was made by critics of the original no-detention provision of the RTE Act?","options":["Detention lowers dropout among poor children, because repeating a class helps them catch up with the rest","Holding children back raises their self-esteem, since they then do well among younger classmates","No detention made the RTE Act unconstitutional, because it overrode states’ power over exams","Without effective CCE and remedial help, automatic promotion let many reach Class 8 without basic skills"],"answer":3,"explanation":"Critics blamed weak implementation: with CCE poorly done and no remedial help, children moved up without learning; this debate led to the 2019 amendment allowing states to hold exams in Classes 5 and 8.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1249","question":"A government upper primary school (Classes 6–8) has 210 students. Applying the RTE norm of at least one teacher for every 35 children at this stage, the minimum number of teachers, not counting the head teacher, is:","options":["3","6","7","9"],"answer":1,"explanation":"Upper primary norm is 35:1, so 210 ÷ 35 = 6 teachers. Using the primary-stage ratio 30:1 gives 7, using the NEP target of 25:1 for disadvantaged areas gives 9, and quoting only the minimum of one teacher each for science-maths, social studies and languages gives 3.","difficulty":"hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1250","question":"The district office asks primary teachers to: I. help with the decennial population census; II. conduct a household survey for a private company; III. do election duty for the state assembly; IV. do relief work during floods; V. collect electricity bills. Under Section 27 of the RTE Act, teachers may be deployed for:","options":["I, III and IV only","I, II and III only","III and V only","I, III, IV and V"],"answer":0,"explanation":"Section 27 bars deploying teachers for non-educational work except the decennial census, disaster relief and elections to local bodies, state legislatures or Parliament.","difficulty":"very-hard","source":"CTET · UPTET · REET"},
  {"id":"cdp-child-development-1251","question":"A government school teacher in Lucknow runs paid evening tuition classes for students of his own school, outside school hours. Under the RTE Act this is:","options":["Allowed, because it takes place outside school hours in the teacher's own time","Prohibited, because Section 28 bars teachers from private tuition","Allowed, provided the classes are only for Classes 6–8 and are optional","Prohibited only if the students come from his own section of the class"],"answer":1,"explanation":"Section 28 flatly prohibits teachers from private tuition or private teaching activity; the timing or the class does not matter.","difficulty":"moderate","source":"CTET · State TET"},
  {"id":"cdp-child-development-1252","question":"A School Management Committee is being formed under Section 21 of the RTE Act. Which composition meets the Act?","options":["Mostly teachers and local officials, with two parents to represent the community","Three-fourths parents or guardians, but with no requirement for women members","Equal numbers of teachers, local officials and parents, with a woman chairperson","Three-fourths parents, proportionate seats for the disadvantaged, half women"],"answer":3,"explanation":"Section 21 requires at least three-fourths of the SMC to be parents or guardians, proportionate representation for disadvantaged groups and half the members to be women.","difficulty":"very-hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1253","question":"Which of these is a function of the School Management Committee under the RTE Act?","options":["Appointing and dismissing the teachers working in the school","Setting the question papers for the Class 10 and 12 board examinations","Monitoring the school's working and preparing the School Development Plan","Fixing the fee structure that parents will pay to the school every year"],"answer":2,"explanation":"The SMC monitors the school, monitors use of grants and prepares the School Development Plan (Sections 21–22); it does not appoint teachers or set papers.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1254","question":"Which of these are listed among a teacher’s duties under Section 24 of the RTE Act? I. Maintain regularity and punctuality in attending school. II. Complete the curriculum within the specified time. III. Assess the learning ability of each child and give additional instruction as required. IV. Hold regular meetings with parents and guardians.","options":["I, II, III and IV","I, II and III only","I and IV only","II, III and IV only"],"answer":0,"explanation":"Section 24 includes all four: regularity and punctuality, completing the curriculum, assessing each child and supplementing instruction, and regular meetings with parents.","difficulty":"very-hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1255","question":"Section 30 of the RTE Act deals with examinations and the completion certificate. Which statement is correct?","options":["No Board exam is required till elementary education is complete, and a certificate is given on completion","Board examinations are compulsory at Classes 5 and 8, and a certificate is given only on passing them","There is a Board examination at Class 8 only, and no certificate is issued on completing elementary school","No assessment of any kind is allowed in school, and a certificate is issued at the time of admission"],"answer":0,"explanation":"Section 30 says no child shall be required to pass a Board examination till completion of elementary education, and every child completing it gets a certificate.","difficulty":"hard","source":"CTET · REET"},
  {"id":"cdp-child-development-1256","question":"Consider: I. Article 21A was inserted by the 86th Constitutional Amendment Act, 2002. II. The same amendment added a fundamental duty on parents or guardians to provide opportunities for education to their children aged 6 to 14. III. The same amendment recast Article 45 to focus on early childhood care and education for children below six. IV. The RTE Act came into force on 1 April 2010. Which are correct?","options":["I and IV only","I, II and IV only","I, II, III and IV","II and III only"],"answer":2,"explanation":"The 86th Amendment added Article 21A and Article 51A(k) and reworded Article 45 for children under six; the RTE Act, which gives effect to Article 21A, came into force on 1 April 2010.","difficulty":"very-hard","source":"CTET · DSSSB TGT"},
  {"id":"cdp-child-development-1257","question":"Under Section 12(1)(c), a private unaided school must admit at least 25% of its entry-level class from weaker sections and disadvantaged groups and give them free education. Who bears the cost?","options":["The parents, who pay a reduced fee fixed by the school management committee","The school, permanently from its own funds as a social obligation","The other parents, through a small increase in their own fees","The State, reimbursing per-child cost or the fee, whichever is less"],"answer":3,"explanation":"Section 12(2) provides reimbursement by the State at the per-child expenditure in government schools or the actual fee, whichever is less.","difficulty":"very-hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1258","question":"A government school says that tuition is free but requires parents to pay a ‘development charge’ without which the child cannot attend. Under Section 3(2) of the RTE Act:","options":["This is allowed, since tuition is free and the charge is only for development, not teaching","Not allowed: no child pays any charge that may prevent completing elementary education","Charges are allowed up to a limit set by the SMC for the upkeep of the school","Only children from below-poverty-line families are exempt from such charges"],"answer":1,"explanation":"‘Free’ under the Act covers not just tuition but any fee, charge or expense that could keep a child from completing elementary education.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1259","question":"Under the Schedule to the RTE Act, the minimum working days and instructional hours per academic year are:","options":["200 days and 800 hours for primary; 220 days and 1000 hours for upper primary","220 days and 1000 hours for primary; 200 days and 800 hours for upper primary","180 days and 720 hours for both stages","240 days and 1200 hours for both stages"],"answer":0,"explanation":"The Schedule prescribes 200 working days and 800 instructional hours for Classes 1–5 and 220 days and 1000 hours for Classes 6–8; option B swaps the two.","difficulty":"very-hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1260","question":"A Class 7 student in a private school is caught stealing repeatedly, and the principal wants to expel him. Under the RTE Act, as amended in 2019:","options":["Expulsion is allowed after three written warnings to the child and parents","Expulsion is allowed for serious misconduct with the SMC’s approval","No child can be expelled till completion of elementary education","Expulsion is allowed, but only in private unaided schools"],"answer":2,"explanation":"The 2019 amendment let states hold back children after exams in Classes 5 and 8, but it kept the bar on expelling any child till elementary education is complete.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1261","question":"Under the RTE Act, which body has been given the task of examining and reviewing the safeguards for children’s rights provided by the Act and recommending measures for their effective implementation?","options":["The NCERT, as the national academic body for school curriculum","The NCTE, as the regulator of teacher education and qualifications","The CBSE, as the board that affiliates and inspects schools","The NCPCR, along with the State Commissions (SCPCRs)"],"answer":3,"explanation":"Section 31 assigns monitoring of the right to education to the NCPCR and the SCPCRs; NCERT and NCTE are academic bodies and CBSE is an examining board.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1262","question":"A child moves from a school in Bihar to one in Delhi. The old school delays issuing the transfer certificate, and the new school refuses admission until it arrives. Under the RTE Act:","options":["The refusal is valid, as the new school needs the certificate for its own records","Delay in the transfer certificate cannot be a ground to delay or deny admission","The child must wait for one term before being admitted in the new school","The child must first pass an entrance test to prove the class level reached"],"answer":1,"explanation":"Section 5 gives the child a right to transfer and says delay in producing the transfer certificate shall not be a ground for delaying or denying admission.","difficulty":"moderate","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1263","question":"Assertion (A): Under the RTE Act, the medium of instruction must in every case be the child’s mother tongue. Reason (R): Section 29 says the medium of instruction shall, as far as practicable, be in the child’s mother tongue.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"The words ‘as far as practicable’ make the provision a guideline rather than an absolute rule, so A overstates what R actually says.","difficulty":"hard","source":"CTET · REET"},
  {"id":"cdp-child-development-1264","question":"A state wants to recruit Class 1–5 teachers without requiring them to pass a Teacher Eligibility Test. Why does this conflict with the RTE framework?","options":["Because the NCTE, the Section 23 academic authority, made a TET pass a minimum qualification","Because the NCERT alone has the power to recruit teachers for all government schools","Because the RTE Act fixes teachers' salaries and recruitment rules directly in its own Schedule","Because the CBSE conducts all teacher recruitment for Classes 1–5 across India"],"answer":0,"explanation":"Section 23 lets an academic authority notified by the Centre, the NCTE, lay down minimum qualifications, and the NCTE included passing a TET for teachers of Classes 1–8.","difficulty":"hard","source":"CTET · UPTET · REET"},
  {"id":"cdp-child-development-1265","question":"Which statement about Section 11 of the RTE Act (pre-school education) is accurate?","options":["It makes pre-school education a fundamental right, enforceable for every child aged 3 to 6","It lets the appropriate government arrange pre-school education for children above three","It bans pre-school classes in government schools to keep the focus on Classes 1–8","It makes Class 1 admission conditional on the child having attended pre-school"],"answer":1,"explanation":"Section 11 is enabling (‘may’), not a justiciable right: it allows governments to provide pre-school education and ECCE for children from three to six years.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1266","question":"Which statement best captures what ‘compulsory’ means in the RTE Act?","options":["Parents who do not send their children to school are fined or sent to jail by the state","Children are forced to attend school daily under threat of punishment for any absence","Attendance stays optional for parents, but schools must keep a seat open for each child","The government must ensure admission, attendance and completion for all aged 6 to 14"],"answer":3,"explanation":"Under Section 8, ‘compulsory education’ places the obligation on the government, not a penalty on children or parents.","difficulty":"hard","source":"CTET · State TET"},
  {"id":"cdp-child-development-1267","question":"A Class 2 child keeps coming late to school. To ‘teach him a lesson’, the teacher plans to make him kneel in the corridor. In keeping with the RTE Act and child-friendly practice, the best course is to:","options":["Make him kneel briefly, as a mild punishment that builds discipline","Mark him absent for the day so that he learns the cost of lateness","Talk with him and his parents to find the cause and solve it together","Report the matter to the police so that the parents take it seriously"],"answer":2,"explanation":"Kneeling is physical punishment banned under Section 17; understanding the cause (distance, chores, illness) and involving parents addresses the problem.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1268","question":"While reading that ‘camels can go for days without water’, Class 6 students are asked to stop after each fact and answer, ‘Why would that be true, given what you know?’ Compared with simply reading, this practice tends to:","options":["Slow reading down and so reduce recall, because attention is split between tasks","Improve memory and understanding, as explaining why links facts to prior knowledge","Help only students labelled as auditory learners, who learn best by talking","Cause proactive interference, since earlier facts block the recall of new ones"],"answer":1,"explanation":"Elaborative interrogation and self-explanation make learners connect new facts to prior knowledge, producing deeper processing and better retention.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1269","question":"A Class 7 teacher has students practise area, perimeter and volume problems mixed together in each set, rather than one complete set for each type in turn. Pupils find it harder at first. What does research predict?","options":["Mixed practice will give poorer long-term results, because early errors become habits","There will be no difference, since the same number of problems is practised overall","Blocked practice will give better transfer, as each method is mastered before moving on","Mixed practice will give better long-term results, as students learn to pick the method"],"answer":3,"explanation":"Interleaving feels harder and may lower performance during practice, but it improves later performance because learners must discriminate between problem types and choose a strategy.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1270","question":"Most adults who handle ₹10 coins daily cannot correctly draw what is on either side of one. The best explanation is that:","options":["The details were never properly encoded because they were not attended to","The memory decayed through disuse, since people rarely look closely at coins","Retroactive interference from other coins erased the stored details","They are showing motivated forgetting of details they find unimportant"],"answer":0,"explanation":"We attend only to features needed to use the coin, so the other details never pass into long-term memory: encoding failure, not forgetting of stored information.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-1271","question":"A teacher writes a list of fifteen words on the board in black, but writes the word ‘volcano’ in large red letters. Later most children recall ‘volcano’. Which memory effect is this?","options":["The serial position effect, as recall depends on where a word sits in the list","Elaborative rehearsal, as a vivid word gets linked to more meaning","The isolation (von Restorff) effect, as one item stands out from the rest","Flashbulb memory, as a striking stimulus leaves a vivid, lasting imprint"],"answer":2,"explanation":"Only ‘volcano’ was made perceptually different, so its recall reflects distinctiveness (von Restorff), not its list position or any extra rehearsal. Flashbulb memory is tempting but refers to vivid memories of emotionally significant events, not one red word in a list.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1272","question":"In Bartlett's studies, English participants retold an unfamiliar Native American folk tale several times. Their versions became shorter and changed unfamiliar details into familiar ones. What does this show about memory?","options":["Memory is an exact recording of what was experienced and heard","Memory is reconstructive, shaped by existing schemas and culture","Only short-term memory is affected by the listener's culture","Stories are never remembered beyond a week, whatever their content"],"answer":1,"explanation":"Bartlett showed that remembering is an active reconstruction in which schemas fill in and alter details, so recall bends towards what is familiar to the learner.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-child-development-1273","question":"Group A reads a list of word pairs such as ‘hot – cold’. Group B sees ‘hot – c_ _ _’ and must fill in the word. On a later test, Group B recalls more. This is called the:","options":["Serial position effect","Spacing effect","Overjustification effect","Generation effect"],"answer":3,"explanation":"Information that learners produce themselves is remembered better than information they simply read, because generating it requires deeper processing.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1274","question":"A teacher tells a Class 4 child a seven-digit phone number to deliver to the office, and the child is stopped on the way by a friend who chats about a match. On arriving the child has forgotten the number. This happened because:","options":["Short-term memory fades in about 30 seconds without rehearsal, which the chat prevented","Long-term memory was already full, so the new number could not be stored there at all","The number went into procedural memory, which cannot hold digits for long periods","The child probably has a learning disability that affects memory for numbers"],"answer":0,"explanation":"Short-term memory holds unrehearsed information for only around 15–30 seconds; the distracting conversation blocked rehearsal and displaced the digits.","difficulty":"hard","source":"CTET · REET"},
  {"id":"cdp-child-development-1275","question":"A student not paying attention is asked a question and says, ‘Sorry, what?’ and then, a second later, answers correctly before the teacher repeats it. Which memory store made this possible?","options":["Iconic memory, which holds visual images for an instant","Long-term semantic memory, which stores general facts","Echoic memory, which holds sounds for a few seconds","Procedural memory, which stores skills and routines"],"answer":2,"explanation":"Echoic (auditory sensory) memory retains sounds for a few seconds, longer than iconic memory, so a just-missed question can still be recovered if attention is turned to it quickly.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1276","question":"While looking at a drawing of a cube with no shading, a child notices that it ‘flips’ between two views every few seconds, even when she tries to hold one. What does this illustrate?","options":["Learned helplessness after failing to hold one view","Fluctuation of attention and perceptual organisation","Spontaneous recovery of an earlier extinguished response","Divided attention between two separate tasks at once"],"answer":1,"explanation":"Ambiguous figures such as the Necker cube show that attention and perceptual organisation naturally fluctuate; it is difficult to keep attention fixed on one interpretation.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1277","question":"A teacher begins a Class 8 lesson by asking, ‘Why can't we see stars in the daytime, though they are still there?’ Several students who were bored start arguing. This opening mainly works by:","options":["Offering an extrinsic reward for whoever answers the question first","Creating fear of failure so that students pay closer attention","Reducing the difficulty of the topic by starting with everyday facts","Creating a knowledge gap that arouses curiosity, an intrinsic motive"],"answer":3,"explanation":"Curiosity arises when learners sense a gap between what they know and what they want to know; a puzzling question sparks intrinsic motivation to resolve it.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1278","question":"According to Weiner, which emotional reactions are likely when a student attributes failure to (a) lack of effort and (b) lack of ability?","options":["(a) Guilt, with resolve to try harder; (b) shame and hopelessness","(a) Shame and hopelessness; (b) guilt, with resolve to try harder","(a) Pride in honesty; (b) gratitude towards the teacher for help","Both lead to the same feeling of anger directed at the teacher"],"answer":0,"explanation":"Effort is controllable, so failure leads to guilt and can energise effort; ability is uncontrollable and stable, so failure brings shame and low expectations.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1279","question":"Assertion (A): A student who believes she failed because the subject is ‘always too hard for her’ will expect to fail again. Reason (R): In Weiner's theory, the stability dimension of an attribution mainly affects expectations of future success or failure.","options":["A is true but R is false","A is false but R is true","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A"],"answer":2,"explanation":"Attributing an outcome to a stable cause leads one to expect the same outcome in future; unstable causes allow expectations to change. R explains A.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1280","question":"Varun, in Class 10, keeps painting and taking part in art camps although his parents warn it will not help his marks; he says that through art he feels he is becoming the person he wants to be. In Maslow's terms, he is driven mainly by:","options":["Safety needs, seeking a secure future","Physiological needs for rest and relief","Esteem needs, seeking praise from others","The need for self-actualisation"],"answer":3,"explanation":"Self-actualisation is the growth need to fulfil one's potential. Varun's motive is personal growth through art, not marks or outside recognition.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-1281","question":"A teacher lavishly praises a Class 8 student for solving a very easy sum, while giving only brief comments to others who solve hard ones. What unintended message might the student draw?","options":["That he is the most able student in the class, as he gets the most praise","That the teacher thinks he has low ability, as he is praised for an easy task","That effort is unimportant, since praise comes regardless of how hard he tries","That the teacher simply prefers easy sums to hard ones in the classroom"],"answer":1,"explanation":"Attribution research shows that praise for success on easy tasks can signal that the teacher expected little of the student, lowering his view of his own ability.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1282","question":"Neel deliberately does not prepare for an important test and tells friends he stayed up watching a film. If he fails, he can blame lack of study rather than lack of ability. This strategy is called:","options":["Self-handicapping to protect one's sense of self-worth","Mastery goal orientation, focusing on learning over marks","Learned helplessness after repeated failures in tests","Self-actualisation through choosing his own priorities"],"answer":0,"explanation":"Self-handicapping creates an excuse in advance so that failure is not blamed on low ability, a self-worth protection strategy (Covington) linked to fear of failure.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-child-development-1283","question":"Which of these statements about extrinsic motivation are correct? I. It can help students begin tasks that they do not yet find interesting. II. It always destroys intrinsic motivation. III. Over time some extrinsically motivated behaviour can become valued by the learner as important to him. IV. Informational feedback is a form of external input that can support intrinsic motivation.","options":["I and II only","II and IV only","I, III and IV only","I, II, III and IV"],"answer":2,"explanation":"Extrinsic motivation is not always harmful: it can start engagement, behaviour can become internalised, and informational feedback supports competence. Statement II is too absolute.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1284","question":"After a poor result, Simran says, ‘The teacher just doesn't like me, so she gives me low marks; there's no point trying.’ In Rotter's terms she shows:","options":["An internal locus of control","High self-efficacy","A mastery orientation","An external locus of control"],"answer":3,"explanation":"An external locus of control means believing outcomes are controlled by outside forces such as others or luck, which reduces effort; an internal locus links outcomes to one's own actions.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-1285","question":"A teacher introduces percentages to cricket-loving Class 7 students by asking them to calculate players' strike rates and team win percentages from recent matches. Which motivational principle is she using?","options":["Making the task relevant to students' interests, raising its value","Negative reinforcement, removing boring examples from lessons","Fear of failure, since cricket fans want to avoid looking foolish","Overlearning, by repeating percentage sums with familiar data"],"answer":0,"explanation":"Connecting content to students' interests raises the perceived value of the task, which increases motivation according to expectancy–value theory.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1286","question":"Payal repeats a list of new Sanskrit words again and again under her breath without thinking about their meanings. She can say them at the end of the period but forgets most by the next day. Why?","options":["She used elaborative rehearsal, which only helps short-term memory and not long-term","Maintenance rehearsal keeps items active briefly but builds weak long-term memories","Her sensory memory was overloaded by too many new words at once","Repetition causes proactive interference with words learnt the next day"],"answer":1,"explanation":"Mere repetition (maintenance rehearsal) keeps items active; linking them to meaning or other knowledge (elaborative rehearsal) is what supports long-term retention.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1287","question":"A teacher gives Class 3 children twenty picture words to remember. One group gets them in random order; the other gets them grouped under ‘fruits’, ‘animals’, ‘tools’ and ‘vehicles’. The grouped list is recalled better because:","options":["Grouped lists are shorter, so there are fewer items to remember","Random order causes the primacy effect, which weakens later recall","Meaningful categories give a structure that aids storage and retrieval","Grouping makes children rely only on iconic memory for the pictures"],"answer":2,"explanation":"Organisation helps memory: category labels act as retrieval cues and help chunk items, so recall improves even though the number of items is the same.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1288","question":"Information processing research explains improvement in children's memory performance between ages 5 and 12 mainly by:","options":["A sudden increase in the number of brain cells around age 7, adding storage","The disappearance of sensory memory, which reduces distraction","A decline in rehearsal, which frees capacity for other mental work","Faster processing, better strategies, more knowledge and better metacognition"],"answer":3,"explanation":"Older children process faster, use strategies spontaneously, know more (which aids encoding) and monitor their own memory better, all of which improve performance.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1289","question":"Ebbinghaus used nonsense syllables such as ‘DAX’ and ‘BOK’ to study memory. Why does a teacher see much slower forgetting of a meaningful story than his curves suggest?","options":["Meaningful material links to existing knowledge, so it is retained much better","Stories are stored only in sensory memory, which does not fade in the same way","His curves apply only to adults, while children forget at a slower rate","Stories are retold so often that they are never forgotten at all"],"answer":0,"explanation":"Ebbinghaus deliberately used meaningless material to exclude prior associations. Meaningful material can be organised and connected to existing schemas, so it is forgotten more slowly.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1290","question":"A Class 6 teacher notices that students drift off mostly in the middle of a long lecture but are alert at its start and end. Which plan best uses principles of attention and memory?","options":["Speak louder throughout so that drifting students are pulled back to the lecture","Insert short recall or pair tasks at intervals to create more ‘beginnings and ends’","Give the whole lecture twice so that the middle part is heard again","Remove the beginning and end to save time for the important middle part"],"answer":1,"explanation":"Attention and recall are highest at the beginning and end of a session; breaking a long lesson into shorter segments with active tasks creates more of these high points.","difficulty":"hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1291","question":"Which practice best helps Class 5 children remember a science lesson for the long term?","options":["Reading the chapter many times in one sitting until it feels familiar","Copying notes neatly from the board and reading them through every night","Highlighting the key lines on each page in bright colours","Short quizzes over later weeks that ask them to recall and explain"],"answer":3,"explanation":"Retrieval practice spaced over time combines the testing effect and the spacing effect, two of the most robust findings on long-term retention; re-reading, copying and highlighting are comparatively weak.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1292","question":"A timetable planner wants to reduce interference in memory for Class 8 students who study in two back-to-back self-study periods. Which pairing is most likely to cause the greatest confusion between the two sets of material?","options":["Geometry theorems followed by a painting activity in the art room","Physical exercise followed by memorising important history dates","Hindi words followed by Marathi words that look very similar","Music practice followed by map work on the states of India"],"answer":2,"explanation":"Interference, both proactive and retroactive, is greatest when the two sets of material are similar; dissimilar activities interfere very little.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1293","question":"Match the learning difficulty with a typical classroom sign. 1. Dyslexia 2. Dysgraphia 3. Dyscalculia 4. Dyspraxia; a. Cannot tell whether 15 or 51 is larger and mixes up place value b. Spells words correctly aloud but writes them in cramped, barely legible script c. Struggles with buttons, scissors and catching, and bumps into things d. Reads ‘was’ as ‘saw’ and decodes new words very slowly","options":["1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-a, 4-c","1-d, 2-b, 3-c, 4-a"],"answer":1,"explanation":"Decoding problems point to dyslexia, a gap between oral spelling and handwriting to dysgraphia, number-magnitude confusion to dyscalculia, and general motor clumsiness to dyspraxia.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1294","question":"Assertion (A): The RPwD Act, 2016 requires educational institutions to detect specific learning disabilities in children at the earliest. Reason (R): Dyslexia is the most common specific learning disability.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements are true, but early detection is required because timely support prevents years of failure, not because dyslexia happens to be the most common learning disability.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1295","question":"Assertion (A): Children with ADHD usually benefit from clear, predictable routines in class. Reason (R): ADHD is caused by a lack of discipline at home.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Structure and routine compensate for weak self-regulation, so A is true; ADHD is a neurodevelopmental condition, not the result of lax parenting, so R is false.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1296","question":"Which of these practices are consistent with Universal Design for Learning? I. Making text-to-speech available to every student who wants it. II. Designing one standard lesson and later preparing separate worksheets only for children with disabilities. III. Offering students options for checking and reflecting on their own progress.","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":2,"explanation":"UDL builds options for all learners into the design, such as text-to-speech and self-assessment; retrofitting separate material after a one-size lesson is the approach UDL aims to replace.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1297","question":"A Class 4 class of 40 includes a child with low vision, a child with ADHD and two newly arrived Odia-speaking children. The teacher is planning a lesson on reading a map of the school. Which plan best reflects Universal Design for Learning?","options":["Explaining clearly from the textbook map and giving a written test at the end to check","Preparing separate worksheets for the four children while the rest follow the textbook","Seating the four children together at the back with a helper so the class is not slowed","A big high-contrast map, a walk-on floor map, gestures and pictures, and an Odia-speaking buddy"],"answer":3,"explanation":"A large high-contrast map, a movement-based floor map, visual explanation and a language buddy give every learner several ways to access and engage with the same goal, which is the heart of UDL.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1298","question":"Assertion (A): Inclusive education requires that all special schools be closed at once. Reason (R): Inclusion rests on the right of children with disabilities to learn in regular schools with the support they need.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"The right to learn in regular schools with support is the basis of inclusion, but the RPwD Act still lets families choose a special school, and special schools can act as resource centres; so A is false.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1299","question":"Which of these are commonly seen in gifted children? I. Uneven development, with thinking far ahead of emotional or physical maturity. II. Intense sensitivity and a strong sense of fairness. III. Being always popular and socially well adjusted.","options":["I and II only","I only","II and III only","I, II and III"],"answer":0,"explanation":"Asynchronous development and emotional intensity are often reported in gifted children; social popularity is not a feature of giftedness, and some gifted children feel isolated.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1300","question":"Nandini, a very able Class 7 student, has started giving wrong answers on purpose and hiding her scores, because classmates tease her as a ‘know-all’ and say ‘girls who study too much are boring’. What should the teacher do?","options":["Praise her loudly in front of the class every time she does well, to boost her","Value effort and ideas for all, give her challenge discreetly, and tackle the teasing","Ignore it, since her marks are still above average and she will grow out of it","Tell her parents that she is becoming lazy and needs closer watching at home"],"answer":1,"explanation":"Gifted girls often hide ability to fit in; a safe culture that values thinking, discreet challenge and action against teasing let her use her ability without social cost, while loud public praise worsens the teasing.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1301","question":"Bobby, a Class 2 child on the autism spectrum, constantly crashes into walls, jumps and seeks tight hugs, and settles down after carrying heavy books to the library. What does this suggest, and what should the teacher do?","options":["He is seeking sensory input; planned movement breaks and ‘heavy work’ jobs can help","He is being deliberately naughty and should lose play time until he learns to behave","He needs to sit still all day, so that he gradually learns self-control","He is bored, so more worksheets will keep his hands and mind busy"],"answer":0,"explanation":"Some autistic children are under-responsive to body sensations and seek strong input; meeting this need through structured movement and heavy work calms them better than restriction.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1302","question":"Gauri, in Class 4, is quiet and well-behaved but often stares out of the window, misses parts of instructions, loses her things and leaves work half done. Teachers call her ‘dreamy’. What should her teacher consider?","options":["That she is lazy and needs stricter supervision and extra homework to build better study habits","That she is gifted and bored, so no action is needed beyond harder work","That she may have inattentive-type attention difficulties needing support and assessment","That she definitely has a hearing loss, since she misses spoken instructions"],"answer":2,"explanation":"Inattentive-type attention difficulties are less visible than hyperactivity and are frequently overlooked, especially in girls; observation, supports and referral are better than labels like ‘lazy’.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1303","question":"Isha, in Class 5, hears well only with her left ear. The teacher usually teaches from the front of the room. Where should Isha be seated?","options":["At the front, towards the left side of the room as she faces the board","At the back, in the middle of the room, so that she hears the whole class","Next to the window, where the room is quieter and the light is better","At the front, towards the right side of the room as she faces the board"],"answer":3,"explanation":"Sitting at the front on the right side places the teacher and most classmates to her left, towards her better ear; the left side would turn her hearing ear towards the wall.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1304","question":"A Class 8 science exam includes a question asking students to label a diagram of the human heart. How should the school adapt this for a blind student?","options":["A tactile (raised) diagram to label, or an equivalent question in words","Skipping the question and giving him full marks so he is not disadvantaged","Skipping the question and giving him zero, as it cannot be answered fairly","Letting a sighted classmate label the diagram and give both of them marks"],"answer":0,"explanation":"Adaptation should test the same learning through an accessible format; free marks, zero marks or a proxy all distort the assessment.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1305","question":"Assertion (A): A child with a specific learning disability may have average or above-average intelligence. Reason (R): Specific learning disabilities are difficulties in particular processes such as reading or calculation that are not explained by intellectual disability.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because a specific learning disability is defined as a particular processing difficulty not due to low general ability, a child with one can have normal or high intelligence.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1306","question":"Some Class 8 students complain that hostels and scholarships for Scheduled Caste and Scheduled Tribe students are ‘unfair to the rest’. How should the teacher help them understand this?","options":["By agreeing that every student should get exactly the same support, whatever the need","By telling them not to discuss such sensitive topics in school at all","By explaining that such measures aim at equity, offsetting long-standing disadvantage","By saying that these students are less able and so need extra help"],"answer":2,"explanation":"Targeted support corrects historical disadvantage so that opportunity is real, not just formal; framing it as charity for ‘less able’ students reinforces the very stereotype it should remove.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1307","question":"Before an important maths test, a teacher wants to reduce stereotype threat among students from groups often believed to be ‘weak at maths’. Which step is most appropriate?","options":["Reminding the class which groups usually score low, so that those groups try harder","Framing it as a chance to learn that ability grows, with no group comparisons","Asking students to write their caste and gender at the top of the paper","Telling those groups that the test will be made easy especially for them"],"answer":1,"explanation":"Stereotype threat is triggered when group identity and its stereotype are made salient; a growth framing without group comparisons reduces it, while recording identity on the paper can trigger it.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1308","question":"Biru, a Ho-speaking child, joined a Hindi-medium Class 2 three months ago. He follows routines and smiles but says almost nothing in class. What is the most appropriate interpretation?","options":["He may be in a ‘silent period’; let him respond through gestures and pictures","He has a speech disorder and should be referred to a specialist at once","He is shy and should be made to speak in front of the class daily to build confidence","He is unwilling to learn Hindi and needs firmer handling at school and home"],"answer":0,"explanation":"Many second-language learners listen for a long time before speaking; low-pressure ways to participate support them, whereas forced speaking raises anxiety.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1309","question":"Children who studied in Marathi until last year now take a Class 6 science test written in Hindi. Many score poorly, though in oral discussion they explain the concepts well. Which conclusion is most sound?","options":["They have weak scientific understanding, which their poor scores reveal","They should be placed in Class 5 again until their scores improve","The test result reflects their science knowledge accurately, as written work is more reliable","The written Hindi test confuses language with science; oral answers would be fairer"],"answer":3,"explanation":"When the language of a test is a barrier, the score measures language rather than the subject; oral evidence of understanding shows the gap is linguistic.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1310","question":"A Class 3 teacher assigns the same caring, high-achieving girl as the permanent ‘buddy’ of a classmate with a disability. By mid-year the buddy looks tired and her own work has slipped. What is the best change?","options":["Telling the buddy that helping is her duty and will build her character","Removing all peer support, so the child with a disability relies on the teacher alone","Rotating buddies, setting limited roles, and keeping the teacher’s support primary","Asking the buddy’s parents to encourage her more and help with her own work"],"answer":2,"explanation":"Peer support works when it is shared and bounded; resting it on one child burdens her and makes the other child's inclusion fragile.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1311","question":"Which of these statements about differentiated instruction are correct? I. It means writing a separate lesson plan for each child. II. It can use whole-class, small-group and individual work. III. It means lowering expectations for struggling learners. IV. Every group’s task should be equally engaging and meaningful.","options":["I and III only","I, II and IV only","II and IV only","II, III and IV only"],"answer":2,"explanation":"Differentiation mixes groupings and gives every learner respectful, engaging work towards high goals; it does not need a plan per child or lower expectations.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1312","question":"In a Class 6 class, the ‘advanced’ group regularly designs projects and debates ideas, while the ‘struggling’ group fills in worksheets every day. Which principle of differentiation is being violated?","options":["Flexible use of time, as the groups get unequal amounts of class time daily","Respectful tasks: every learner gets engaging work needing real thinking","Curriculum compacting, since the advanced group skips content it knows","Learning-profile grouping, as groups should match learning styles"],"answer":1,"explanation":"Differentiation adjusts the level of support, not the quality of thinking; giving one group only drill while another does rich tasks widens the gap.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1313","question":"A Class 5 teacher seats children from poorer families on the back benches so that ‘the bright ones can sit in front’. What is the most likely effect?","options":["It helps every child concentrate better, since the able ones set the pace in front","It has no effect on learning, as all children hear the same lesson","It improves the performance of the back-bench children through healthy competition","Back-bench children get less attention and sense low expectations, lowering participation"],"answer":3,"explanation":"Seating by background signals worth and reduces teacher contact, feeding a self-fulfilling cycle of low expectation and low performance.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1314","question":"A Class 4 teacher slaps Mahi, who has dyscalculia, for ‘careless’ errors in subtraction. Which statement best evaluates this?","options":["It is doubly wrong: physical punishment is banned, and her errors need support","It is acceptable if done rarely and lightly, as a reminder to be more careful","It is acceptable because careless children need discipline to build good habits","It is wrong only because the parents may complain to the school authorities"],"answer":0,"explanation":"RTE bans physical punishment and mental harassment, and treating a disability as carelessness misreads the cause; she needs concrete support in place value and procedures.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1315","question":"Sabina joined a Hindi-medium school a year ago. She now chats fluently in Hindi in the playground but struggles with textbook passages and written answers. Her teacher suspects a learning disability. Which idea best explains the situation?","options":["Playground fluency proves her academic Hindi should also be strong, so she must have a disability","Conversational language develops much faster than academic language; she needs language support","She is not trying hard enough in class and needs more pressure to read","She has forgotten her first language, and this loss is causing the problem in reading"],"answer":1,"explanation":"Cummins distinguished basic conversational skills, acquired in a year or two, from academic language, which takes years longer; mistaking this gap for a disability leads to wrong labelling.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1316","question":"A Class 6 teacher marks correct answers with green ticks and wrong ones with red crosses, and colours a bar graph using only red and green. One student keeps misreading them. He has red-green colour vision deficiency. Which change helps most?","options":["Using brighter shades of red and green so the difference is more visible","Asking him to guess the meaning from how light or dark each shade is","Using symbols, labels or patterns along with colour, never colour alone","Excusing him from graph work, as it is too hard to adapt for him"],"answer":2,"explanation":"Information carried only by colour excludes students with colour vision deficiency; pairing colour with symbols, labels or patterns is a simple universal-design fix.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1317","question":"Varun, in Class 6, has muscular dystrophy, a condition that gradually weakens the muscles. He tires quickly while writing and walking between floors. Which plan is most appropriate?","options":["Treating him exactly like everyone else, since adjustments would make him dependent","Advising his parents to shift him to home study at once, for his safety","Waiting until he can no longer walk before making any changes to his routine","Planning ahead: ground-floor classes, rest breaks, a scribe or typing, reviewed regularly"],"answer":3,"explanation":"A progressive condition needs supports that anticipate and track changing needs; reasonable accommodation keeps him learning in his school without waiting for a crisis.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1318","question":"A head teacher, citing Gardner, orders that every lesson in every subject must include eight activities, one for each intelligence. Which response is most consistent with Gardner’s own views?","options":["The order is correct, since each child learns only through his or her dominant intelligence","The order is correct, since Gardner’s theory is mainly a lesson-planning template","The theory forbids the use of language when teaching mathematics to children","Gardner urges several meaningful entry points to key ideas, not all eight in every lesson"],"answer":3,"explanation":"Gardner has said the theory is not a recipe; teachers should present key ideas in several ways where this aids understanding, and mechanically covering all eight intelligences in each lesson trivialises both the theory and the subject.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-1319","question":"Sameer looks at a flat net of six squares and immediately says which faces will be opposite each other when it is folded into a cube. In Gardner’s framework, this mainly reflects:","options":["Logical-mathematical intelligence","Spatial intelligence","Bodily-kinaesthetic intelligence","Naturalist intelligence"],"answer":1,"explanation":"Mentally folding and rotating forms is the core of spatial intelligence. Logical-mathematical intelligence concerns reasoning with numbers and abstract patterns, a common confusion because nets appear in maths lessons.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1320","question":"For a Class 7 science exhibition, Lalita explains photosynthesis through a poster painted in the Warli tribal art style, an approach no one in her school has tried before. In Sternberg’s theory, she is showing mainly:","options":["Analytical intelligence","Practical intelligence","Creative intelligence","Crystallised intelligence"],"answer":2,"explanation":"Sternberg’s creative intelligence (the experiential subtheory) is the ability to deal with novelty and combine ideas in new ways; fusing a folk-art form with science content is a novel combination.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1321","question":"A Class 8 teacher plans three tasks on a chapter about Mughal architecture to develop Sternberg’s three abilities. Which task targets PRACTICAL intelligence?","options":["Compare the features of the Taj Mahal and Humayun’s Tomb and explain the key differences","Design an imaginary building that blends Mughal and modern features","Write a poem from the point of view of a stone carver","Suggest a realistic plan by which your town could protect and promote a local monument"],"answer":3,"explanation":"Practical tasks apply knowledge to real-life settings; comparing and explaining is analytical, and designing or imagining new forms is creative.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1322","question":"IQ scores in a large school of 1,200 students follow a normal distribution with a mean of 100 and a standard deviation of 15. About how many students would be expected to score between 85 and 115?","options":["About 600","About 820","About 1,140","About 410"],"answer":1,"explanation":"About 68% of a normal distribution lies within one SD of the mean, and 0.68 × 1,200 ≈ 820. About 1,140 would be the two-SD range (95%), and 410 is only one side (34%).","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1323","question":"In a district with 50,000 children of the same age, IQ is normally distributed with a mean of 100 and a standard deviation of 15. About how many children would be expected to score above 130?","options":["About 7,500","About 2,500","About 1,100","About 50"],"answer":2,"explanation":"130 is two SDs above the mean; about 2.3% of scores lie beyond +2 SD, and 0.023 × 50,000 ≈ 1,100. ‘2,500’ wrongly uses 5%, which is both tails together.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1324","question":"A psychologist reports a child’s IQ as ‘98, probably between 93 and 103’ instead of simply ‘98’. The main reason for giving a range is that:","options":["Every score has some measurement error, so a band is a more honest estimate","The child may have two different IQs, one verbal and one non-verbal","Ranges are required by law only when reporting on gifted children","IQ changes by about five points every week, so one single number would mislead"],"answer":0,"explanation":"No test is perfectly reliable; reporting a confidence band based on the standard error of measurement reminds users that small differences between scores may not be meaningful.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1325","question":"Assertion (A): A single IQ test score should not be the sole basis for deciding a child’s school placement. Reason (R): Every test score contains measurement error, and a single test samples only a limited set of abilities.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because one score is imprecise and narrow, important decisions need several sources of information; R gives exactly the reason why A is sound practice.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1326","question":"Before her board exam, Ritika realises that her irritation with her younger brother comes from tiredness and anxiety, not from anything he did, and she decides to rest before revising. In Goleman’s model, the first part, recognising the real source of her feeling, is mainly:","options":["Empathy","Social skills","Self-awareness","Self-motivation"],"answer":2,"explanation":"Self-awareness is recognising one’s own emotions and their causes as they happen; deciding to rest then moves into self-regulation.","difficulty":"moderate","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1327","question":"E. P. Torrance reported that many children’s scores on creativity tests dip around Class 4. What is the most reasonable implication for teachers?","options":["Creativity is biologically lost around the age of nine and cannot be revived by teaching","Children of this age should not be given open-ended tasks, as they find them confusing","The dip is permanent, so any creativity training should wait until adolescence begins","Pressure to give ‘correct’ answers may suppress creativity, so keep open-ended thinking alive"],"answer":3,"explanation":"Torrance linked this ‘fourth-grade slump’ partly to increasing demands for conformity; it is not a fixed biological loss, and supportive teaching can counter it.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1328","question":"A four-year-old rides a stick around the courtyard as if it were a horse. Vygotsky saw such pretend play as important for later abstract thought mainly because:","options":["The child separates the meaning ‘horse’ from the real object, using a substitute","It keeps the child physically active, which builds the brain for later abstract thinking","It is a way of getting rid of excess energy so the child can focus later","It shows the child cannot yet tell reality from fantasy, a stage to outgrow"],"answer":0,"explanation":"For Vygotsky, in play a child acts in an imagined situation where meaning is separated from the object, a step towards thinking with symbols and concepts; play also creates its own zone of proximal development.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-1329","question":"Testing shows that Ishita, in Class 7, has very high reasoning ability, yet she is failing most subjects. What should the teacher do first?","options":["Conclude that the test was wrong and ignore it, since marks show true ability","Conclude that she is lazy and give her extra homework to build discipline","Move her to a lower section so that she can cope and regain confidence","Look into causes such as boredom, emotional issues, a learning disability or peers first"],"answer":3,"explanation":"Underachievement in a capable student has many possible causes; diagnosis must come before intervention, and a lower section would only reduce challenge further.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1330","question":"In Joseph Renzulli’s Enrichment Triad Model, ‘Type III’ enrichment refers to:","options":["General exploratory activities that expose students to new topics and interests","Group training in thinking, research and communication skills for all students","Remedial lessons for students who are behind, to bring them up to grade level","Individual or small-group investigation of real problems, producing original products"],"answer":3,"explanation":"Type I is general exploration, Type II is training in process skills, and Type III is first-hand investigation of real problems, where students act as practising professionals.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1331","question":"In a Class 3 in Kokrajhar, Assam, the children speak Bodo, Assamese and Bengali at home, while the school language is Assamese. During a story lesson, which practice best uses this diversity?","options":["Allow only Assamese to be spoken in class, so that every child is treated equally","Let groups retell the story in home languages, then bridge key ideas into Assamese","Seat children from each language group separately for the whole year to avoid confusion","Skip the story, because not all children yet understand Assamese well enough"],"answer":1,"explanation":"Allowing home languages builds comprehension and confidence and gives a bridge to the school language; banning them or segregating children wastes their linguistic resources.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1332","question":"In a well-known classroom study (Ray Rist), a kindergarten teacher seated children at ‘fast’ and ‘slow’ tables within the first days of school, largely on the basis of dress, speech and family background, and these groupings persisted for years. This study mainly illustrates:","options":["How social-class-based expectations can become lasting gaps in opportunity","That children’s abilities are already fully visible by the eighth day of school","That ability grouping always raises achievement for every child in the class","That young children learn better sitting in rows than at shared tables"],"answer":0,"explanation":"Rist found that early placements based on social-class cues shaped the attention and instruction children received, so the groupings became self-perpetuating.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1333","question":"Lhamo, from a community that values cooperation and modesty, rarely raises her hand to answer before her classmates, though she helps them quietly in group work. Her new teacher concludes she ‘lacks confidence and ability’. Which is the best evaluation?","options":["The teacher is right, because confident and able children always answer first","She may be misread: a cultural norm of not outshining peers is not low ability","Lhamo should be referred for counselling, since such shyness signals a problem","Lhamo should be made to answer first every day until she changes her habit"],"answer":1,"explanation":"Cultural norms about competition and self-display shape classroom behaviour; judging ability through a single participation style can mislabel children from communities that value cooperation.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1334","question":"In studies by Hermine Sinclair, children who could not yet conserve were trained to use the comparative words that conserving children use (such as ‘longer but thinner’). Most still failed to conserve. These results support the view that:","options":["Language determines thought completely, so more word training is all that is needed","Conservation is learned only through reinforcement, not through words","Grammar is innate and thought is not, so words cannot shape reasoning","Learning a concept’s words does not by itself create the cognitive operation"],"answer":3,"explanation":"The studies, from Piaget’s Geneva school, showed that verbal training alone rarely produced conservation, supporting Piaget’s position that thought drives language more than the reverse.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1335","question":"According to Vygotsky’s studies of concept formation, children sort objects for a long time into ‘complexes’ joined by changing, concrete links. At what period did he say genuine concepts finally develop?","options":["In infancy, with the first words","Around the age of three","In adolescence","Only in adulthood, after formal education ends"],"answer":2,"explanation":"Vygotsky held that thinking in complexes and pseudo-concepts dominates childhood, and that true abstract concepts are formed only in adolescence, supported by school instruction.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1336","question":"If Chomsky is right that children acquire the grammar of their home language with the help of an innate capacity, what is the most sensible implication for early language teaching?","options":["Children need daily drill in grammar rules before they can speak their language correctly","Grammar mistakes in young children should be corrected strictly every time","Provide rich, meaningful language use such as stories and talk, not formal grammar drills","Language need not be taught or used deliberately in school at all"],"answer":2,"explanation":"Children acquire grammatical competence largely from meaningful exposure; early teaching should immerse them in rich language, while explicit grammar suits later, reflective study.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1337","question":"Which statement about age and second-language learning is best supported by research?","options":["Late starters usually keep an accent but can still master vocabulary and grammar","Adults cannot learn any new language after the age of 12, as the brain has set","Age has no effect at all on second-language learning, since only practice matters","Children always learn a second language faster than adults in every aspect"],"answer":0,"explanation":"Early starters tend to reach native-like pronunciation, but older learners can learn quickly and reach high proficiency in vocabulary and grammar; the age effect is strongest for accent.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-1338","question":"Russian has two basic colour words for what English calls ‘blue’: one for light blue and one for dark blue. Experiments found Russian speakers slightly faster at telling shades apart when they crossed this boundary. Such a finding supports:","options":["The strong version of linguistic determinism, as English speakers cannot see the difference","The weak version of linguistic relativity, as language shapes perception in small ways","Chomsky’s claim that colour vocabulary is innate and the same in all languages","Piaget’s claim that language has no effect on any cognitive process at all"],"answer":1,"explanation":"English speakers can obviously see the difference, so the strong version fails; but a small speed advantage linked to language categories supports a weak relativity effect.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1339","question":"A teacher regularly writes ‘Very neat!’ on girls’ notebooks and ‘Excellent reasoning!’ on boys’, even when the work is similar. The most likely effect on girls is that they learn:","options":["That their thinking is valued as much as boys’, since both get praise","That neatness, rather than intellectual quality, is what is expected of them","That feedback has no real meaning, since it is the same for everyone","That they are better at reasoning than boys, as their work looks better"],"answer":1,"explanation":"Feedback signals what is valued. Praising girls for appearance and boys for ideas is a subtle gender bias that can shape self-concepts and later subject choices.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1340","question":"During recess in a Bhubaneswar school, boys’ cricket occupies the whole playground and girls sit at the edges. Which response best promotes gender equity?","options":["Leave it as it is, since boys naturally need more open space to run and play","Ban cricket during recess so that nobody can occupy the whole ground","Tell girls to play indoor games instead, where they will feel safer","Schedule fair shared use of the ground and encourage mixed and girls’ teams"],"answer":3,"explanation":"Use of space is part of the hidden curriculum; fair scheduling and mixed participation give girls equal access to physical activity without punishing boys.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1341","question":"Two-and-a-half-year-old Mahi says, ‘I am a girl’, but when asked what she will be when she grows up, she says, ‘A papa’. In Kohlberg’s sequence, she has reached:","options":["Gender identity, but not yet gender stability","Gender stability, but not yet gender identity","Gender constancy","Androgyny"],"answer":0,"explanation":"Correctly labelling her own gender is gender identity; understanding that gender stays the same over time (stability) comes later, followed by constancy across situations.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1342","question":"After two months of intensive coaching for an entrance test, students’ scores rise substantially, but their performance on related school tasks changes little. The most reasonable interpretation is that:","options":["Their underlying ability roughly doubled during two months of intensive coaching","Coaching has no effect on test scores, so the rise must be due to chance","Scores partly reflect practice with the test format, not just underlying ability","Entrance tests measure only creativity, which coaching has managed to raise"],"answer":2,"explanation":"Score gains from coaching on a particular format show that scores include test-specific skills; this is one reason NCF 2005 and NEP 2020 warn against assessment systems that reward coaching.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1343","question":"Jaspreet performs poorly in timed written tests but builds excellent models and gives clear explanations in projects. Which assessment approach would give the fullest picture of her learning?","options":["A single end-of-year written exam, which is the fairest common measure","A portfolio of projects, drafts, observations and tests over time","Ranking her against the class on test marks to show where she stands","Oral tests only, since she explains well when she speaks"],"answer":1,"explanation":"A portfolio draws on varied evidence across time and formats, capturing learning that a single format misses, in line with comprehensive assessment.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1344","question":"Children who start Class 1 as weak readers read less, learn fewer new words and fall further behind each year, while good readers read more and pull ahead. Keith Stanovich called this pattern:","options":["The halo effect","The Flynn effect","The Matthew effect","The Hawthorne effect"],"answer":2,"explanation":"The Matthew effect (‘the rich get richer’) describes how early advantages and disadvantages in reading compound over time, which is why early support matters and why early labelling can be harmful.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1345","question":"Which of these pairings of theorist and concept are correct? 1. Kohlberg – just community school 2. Gilligan – ethic of care 3. Piaget – immanent justice 4. Erikson – internal working model","options":["1, 2 and 3 only","2 and 3 only","1, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"The internal working model is Bowlby’s attachment concept, not Erikson’s; the other three pairings are correct.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1346","question":"A B.Ed lecturer says, ‘The heritability of intelligence is about 0.5, so half of each child’s IQ comes from genes and half from the environment.’ What is wrong with this statement?","options":["Heritability of intelligence is actually zero, so all of IQ comes from the environment","Heritability is about differences in a population, not the split within one child","Heritability applies only to physical traits like height, never to intelligence","Nothing is wrong; heritability gives each person’s exact genetic share of a trait"],"answer":1,"explanation":"Heritability is a population statistic about differences between people, not a recipe for one person; within an individual, genes and environment interact inseparably.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1347","question":"Height is highly heritable, yet average heights in many countries rose noticeably within a few generations. What does this show?","options":["Height is not influenced by genes at all, only by food and exercise","Genes changed rapidly in those countries through new marriages over a few generations","Even a highly heritable trait can change when the environment, e.g. diet, improves","Heritability estimates are always wrong and should be ignored by scientists"],"answer":2,"explanation":"High heritability within a population does not mean a trait is fixed; improved nutrition and health raised average height across the population.","difficulty":"very-hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1348","question":"Identical twins raised in the same home have the same genes and many shared experiences, yet one becomes outgoing and the other reserved. Which explanation is best supported by behaviour-genetic research?","options":["One twin must secretly have been adopted, since identical twins always match","Personality is fixed at birth, so the difference is only an illusion","Their shared home environment caused the difference between them","Non-shared experiences such as different friends, teachers or illnesses"],"answer":3,"explanation":"Since genes and shared family environment are the same, differences arise from non-shared environmental influences unique to each twin.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1349","question":"In a twin study, identical (MZ) twins turn out to be no more alike on a trait than fraternal (DZ) twins of the same sex raised together. What is the most reasonable conclusion about that trait?","options":["Genes contribute little to it; shared environment probably matters more","It is entirely genetic, since both kinds of twins share genes and families","MZ twins must have different genes from each other for this trait","The trait cannot be studied scientifically because twins are too similar"],"answer":0,"explanation":"If doubling genetic similarity (DZ about 50% to MZ 100%) adds no extra resemblance, genes explain little of the variation; similarity then comes mainly from the shared environment.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1350","question":"A child who suffers damage to the left side of the brain at age three regains much of her language ability, whereas an adult with similar damage often has lasting difficulty. Which principle does this best illustrate?","options":["Development is fixed and unchangeable once brain damage occurs","The developing brain shows greater plasticity in early life","Language is not located in the brain but learnt from others","Heredity alone determines how well a person recovers"],"answer":1,"explanation":"The young brain can reorganise functions to other areas more readily; plasticity is greatest early, though it continues to some extent throughout life.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1351","question":"Parents of a three-year-old want the pre-school to make him write full sentences in a notebook every day. Which principle should the teacher explain to them?","options":["Writing depends only on practice, so the more sentences he writes daily, the better","Children learn best through rote copying from the earliest possible age","Fine motor control matures gradually; pushing before readiness causes frustration","Children of three can master all adult skills if trained early enough"],"answer":2,"explanation":"Maturation sets readiness; three-year-olds still lack the fine motor control and perceptual skills for sustained writing, so drawing, play and large movements come first.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1352","question":"Which of these changes depends mostly on maturation rather than learning?","options":["Reading Hindi fluently by Class 3","Riding a bicycle without training wheels","Using table manners at a family meal","Sitting without support in infancy"],"answer":3,"explanation":"Sitting unsupported appears in a predictable sequence given minimal ordinary opportunity; reading, cycling and manners need specific teaching or practice.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1353","question":"Assertion (A): Imprinting in goslings is usually described as occurring in a critical period, whereas language learning in humans is better described as having a sensitive period. Reason (R): A critical period is a fixed window outside which the development normally cannot occur, while a sensitive period is an optimal time outside which development is possible but harder.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Imprinting has a narrow, near-absolute window, while people can learn languages later, though less easily; the definitions in R explain why the two cases are labelled differently.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1354","question":"Match the theorists with their main position on development: 1. Arnold Gesell 2. John B. Watson 3. Jean Piaget 4. Urie Bronfenbrenner; a. Development shaped by nested environmental systems interacting with the child b. Development is unfolding of maturation c. Development is shaped by environment and conditioning d. Child actively constructs knowledge through interaction of maturation and experience","options":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-a, 4-d","1-b, 2-c, 3-d, 4-a","1-d, 2-c, 3-b, 4-a"],"answer":2,"explanation":"Gesell stressed maturation, Watson environmental conditioning, Piaget active construction through interaction, and Bronfenbrenner nested ecological systems.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1355","question":"Which group of theorists all describe development mainly as a series of qualitatively distinct stages (a discontinuous view)?","options":["Watson, Skinner and Bandura","Piaget, Erikson and Kohlberg","Skinner, Thorndike and Pavlov","Bandura, Watson and Thorndike"],"answer":1,"explanation":"Piaget, Erikson and Kohlberg propose stage theories with qualitative shifts; behaviourists and social learning theorists see development as gradual, continuous accumulation of learning.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1356","question":"Adopted siblings raised in the same home are somewhat alike in IQ in early childhood, but by adolescence their scores are hardly more similar than those of unrelated children raised apart. What does this pattern most suggest?","options":["Shared family influence on IQ fades with age while genetic influence grows more evident","The shared family environment becomes stronger with age as children spend more time at home","Adopted children have no genes in common with anyone in the family, so they differ","IQ is affected by neither genes nor environment, so the scores simply drift"],"answer":0,"explanation":"Behaviour-genetic studies find that shared-environment effects on IQ fade by adolescence while heritability rises, partly as young people increasingly choose their own environments.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1357","question":"Which of these statements reflect the lifespan perspective on development? I. Development continues throughout life. II. It involves both gains and losses. III. It retains some plasticity at all ages. IV. It is shaped by historical and cultural context.","options":["I and II only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":3,"explanation":"The lifespan view (Baltes) holds that development is lifelong, multidirectional, plastic and embedded in history and culture; all four statements fit.","difficulty":"very-hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1358","question":"For a typical Class 9 student, which combination of stages is most likely?","options":["Erikson: industry vs inferiority; Kohlberg: preconventional; Piaget: concrete operational","Erikson: initiative vs guilt; Kohlberg: postconventional; Piaget: formal operational","Erikson: identity vs role confusion; Kohlberg: conventional; Piaget: formal operational","Erikson: intimacy vs isolation; Kohlberg: Stage 6; Piaget: concrete operational"],"answer":2,"explanation":"Fourteen- to fifteen-year-olds face the identity crisis, typically reason conventionally (Stages 3–4) and are developing formal operations.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1359","question":"Assertion (A): Piaget’s heteronomous morality corresponds broadly to Kohlberg’s preconventional level. Reason (R): In both, young children judge right and wrong by authority, rules imposed by adults and the consequences that follow.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both describe young children’s externally controlled morality, judged by authority and consequences; Kohlberg built on Piaget, which is why they line up.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1360","question":"Children from poor families who attended a high-quality pre-school programme showed better school readiness, and some long-term studies found fewer dropouts and better adult outcomes. Which principle of development do such findings most support?","options":["Development is fixed by heredity, so early programmes cannot have any lasting effect","Only experiences in adolescence matter for adult outcomes, not early ones","Development is cumulative, so enriched early settings can have lasting effects","Pre-school education harms children by pushing them into academics too early"],"answer":2,"explanation":"Early experience lays the foundation for later learning; quality early childhood care and education, like the aim of ICDS and NEP’s focus on ECCE, can change developmental trajectories.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1361","question":"A teacher says, ‘Intelligence is inherited, so remedial teaching for slow learners is a waste of time.’ Which is the strongest reply based on child development research?","options":["She is right, since heredity fixes all mental abilities from the moment of birth","Heredity sets broad potential, but teaching strongly affects how much is realised","Intelligence is wholly environmental, so heredity is irrelevant to the debate","Remedial teaching works only for children with high IQ, not slow learners"],"answer":1,"explanation":"Genetic influence does not mean unchangeability; learning opportunities and good teaching substantially affect achievement. Rejecting heredity entirely is the opposite error.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1362","question":"A child’s first drawings are scribbles, then circles and lines, then ‘tadpole’ figures, and only later realistic human figures with body parts in proportion. Which principle does this sequence mainly show?","options":["Development is unpredictable and random, varying from child to child","Development proceeds from simple and general to complex and specific","Development depends only on heredity, as drawing is an inborn talent","Development proceeds from specific details to general wholes"],"answer":1,"explanation":"Drawing moves from undifferentiated scribbles to differentiated, detailed forms, illustrating the simple-to-complex, general-to-specific direction of development.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1363","question":"A Class 3 teacher introduces fractions by sharing rotis and folding paper strips before writing symbols such as 1/2 and 3/4. Which principle of development guides her?","options":["Development proceeds from concrete to abstract","Development proceeds from abstract to concrete","Development is cephalocaudal","Development is reversible"],"answer":0,"explanation":"Children of this age think best with concrete, manipulable experiences; abstract symbols are introduced after concrete understanding is built.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1364","question":"Which statement about heredity and environment is most accurate?","options":["Heredity determines physical traits, environment determines psychological traits","Their effects can be simply added up, e.g. 60% + 40%, for each individual","Heredity is important only before birth, environment only after birth","Heredity and environment interact; the effect of one often depends on the other"],"answer":3,"explanation":"Genes and environment interact: the same environment affects children with different genes differently and vice versa, so neat percentage splits for an individual are meaningless. Physical traits are also affected by environment, e.g. nutrition.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1365","question":"Assertion (A): Children of the same age in a class differ widely in height, temperament and learning pace. Reason (R): Each child has a unique combination of heredity and environment.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Individual differences arise because no two children (except identical twins in genes) share the same heredity and environment; R explains A.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1366","question":"Which observation is the strongest evidence that development is directed by an inner timetable as well as by experience?","options":["Children in different cultures learn to speak quite different languages from an early age","Children everywhere sit, stand and walk in the same order, at slightly different ages","Children of literate parents usually learn to read earlier than other children","Children who practise cricket regularly bat better than those who do not"],"answer":1,"explanation":"A common motor sequence across cultures points to maturation; the differences in age reflect environment and individual variation. The other options show the effect of experience.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1367","question":"A child is born with a genetic tendency toward shyness. In one family she is gently encouraged to join new activities and grows into a moderately outgoing teenager; in another she is overprotected and becomes very withdrawn. This illustrates that:","options":["Temperament is entirely learnt, since the two outcomes differ so much from each other","Genetic tendencies are unaffected by parenting, whatever the family does","Environment can only make traits more extreme, never soften them","A genetic tendency’s outcome depends on how the environment responds to it"],"answer":3,"explanation":"Thomas and Chess’s idea of goodness of fit: development depends on the match between a child’s temperament and the demands and responses of the environment.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1368","question":"Which of these classroom practices best respects the principle that the rate of development differs across children while its sequence is similar?","options":["Same worksheet at the same pace for all, and repeating the year for any who lag","Different syllabi for each child, with no shared goals for the class","Common goals in a sensible sequence, with flexible pacing and varied support","Grouping children by age alone and expecting identical progress from all"],"answer":2,"explanation":"Keep the developmental sequence but vary pace and support: differentiation within common goals fits both a common sequence and individual rates.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1369","question":"Thomas and Chess classified infant temperament into ‘easy’, ‘difficult’ and ‘slow-to-warm-up’. A Class 1 child takes a long time to join new activities, watches quietly first and then participates well. What is the best teacher response?","options":["Push her into every activity immediately, so that she builds up confidence quickly","Give her time to observe, introduce new things gradually and encourage gently","Label her as having a learning difficulty and refer her for testing","Leave her alone permanently, as she clearly prefers to watch others"],"answer":1,"explanation":"Slow-to-warm-up children adapt well when given time; patient, gradual exposure provides a good fit, while pressure or neglect makes adjustment harder.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1370","question":"How many of these did Bruner list as features that a theory of instruction should specify? I. The experiences that predispose a learner to learn. II. How a body of knowledge should be structured so that the learner can grasp it. III. The most effective sequences in which to present material. IV. The nature and pacing of rewards and feedback.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"In ‘Toward a Theory of Instruction’ Bruner named all four: predisposition, structure, sequence, and the nature and pacing of reinforcement. Each is a design choice for the teacher.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1371","question":"Bruner described learning a subject as involving three almost simultaneous processes. A Class 8 student reads about Newton’s laws (P), applies them to explain why passengers lurch forward when a bus brakes (Q), and checks whether her explanation fits the facts (R). These are respectively:","options":["Acquisition, transformation and evaluation","Assimilation, accommodation and equilibration","Enactive, iconic and symbolic representation","Transformation, evaluation and acquisition"],"answer":0,"explanation":"Bruner’s three processes are acquiring new information, transforming it to fit new tasks, and evaluating whether the handling is adequate. The Piagetian terms describe adaptation, not these processes.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1372","question":"A Class 7 social science teacher teaches the Mughal period through the life stories of a farmer, a merchant and a court painter, inviting students to imagine their choices. Bruner described this way of making sense of experience through stories of human intentions as:","options":["The paradigmatic (logical-scientific) mode","The enactive mode","The narrative mode","Operant shaping"],"answer":2,"explanation":"Bruner later distinguished the paradigmatic mode, which seeks logical proof, from the narrative mode, which organises experience as stories about people and intentions. Both are ways of thinking that schools should develop.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1373","question":"Which pairing correctly contrasts Bruner and Ausubel?","options":["Bruner: rote memorisation of facts and rules; Ausubel: pure discovery learning","Bruner: discovery learning; Ausubel: meaningful reception with advance organisers","Both: learning mainly by conditioning and reinforcing correct responses","Bruner: advance organisers before lessons; Ausubel: spiral curriculum and discovery"],"answer":1,"explanation":"Bruner favoured learners discovering structure from instances, while Ausubel held that well-organised expository teaching, introduced with advance organisers, produces meaningful learning. Neither supported rote learning.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1374","question":"In the NCERT mathematics sequence, children meet ‘half’ and ‘quarter’ by sharing objects in early classes, add and subtract fractions later, and study rational numbers in Class 8. This design follows:","options":["Bruner’s spiral curriculum","Piaget’s horizontal décalage","Skinner’s programmed instruction","Vygotsky’s private speech"],"answer":0,"explanation":"Revisiting a concept at increasing depth and formality across years is the spiral curriculum. Programmed instruction is about small, reinforced steps within a single sequence.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1375","question":"A teacher says, ‘Class 2 children are too young for any idea of probability.’ How would Bruner most likely respond?","options":["Agree, since probability is purely symbolic and must wait until Class 10 or later","Agree, since young children cannot learn anything abstract at all before Class 6","Disagree, but only for gifted children who already think symbolically","Disagree: it can be taught honestly, e.g. through ‘more likely, less likely’ games"],"answer":3,"explanation":"Bruner’s hypothesis is that any subject can be introduced in some intellectually honest form at any age by matching the child’s mode of thinking. Simple chance games are such a form.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1376","question":"In a variation of the water-pouring task, children were asked to predict the water level and say whether the amount would be the same while the glasses were hidden behind a screen. Many more young children gave conserving answers than in the standard task. Bruner used such findings to argue that:","options":["Conservation depends only on maturation, so the screen should have made no difference","Young children already have formal operations, which the screen simply revealed","The look of the glasses (iconic) can override reasoning, which language can help fix","The screen created the disequilibrium that Piaget had predicted for this age"],"answer":2,"explanation":"Bruner suggested that young children are dominated by visual appearance; when it is removed and they rely on verbal reasoning, they conserve more. He linked growth to the symbolic mode and language.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1377","question":"During a guided discovery lesson, Class 6 students conclude that ‘all even numbers are divisible by 4’ after checking 4, 8, 12 and 16. The best next move for a Bruner-style teacher is to:","options":["Accept the rule, since discovery must never be corrected by the teacher","Ask them to test it with 6 and 10 and decide whether their rule must change","Tell them the correct rule straight away and move on to the next topic","Give them marks for discovering a rule, to reward their effort and initiative"],"answer":1,"explanation":"In guided discovery the teacher supplies examples or questions that challenge over-generalisations so that students refine the rule themselves. Simply telling the answer ends their discovery.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1378","question":"Why did Bruner regard the symbolic mode as especially powerful?","options":["It lets ideas be held compactly and handled by rules, even when things are absent","It is the only mode infants can use, so it underlies all later thinking","It does not depend on language at all, so it works for every learner","It removes the need for any concrete experience at all once a child reaches school"],"answer":0,"explanation":"Symbols such as words and numbers are arbitrary, compact and rule-governed, allowing reasoning about absent and abstract things. Bruner still saw enactive and iconic forms as useful foundations.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1379","question":"Consider these statements. 1. Bruner, like Vygotsky, gave adults and culture a central role in children’s learning. 2. Bruner introduced the idea of scaffolding with colleagues in a study of tutoring. 3. Bruner held that children must wait for the right stage before any subject can be introduced. Which is/are correct?","options":["1 only","1 and 3 only","1 and 2 only","2 and 3 only"],"answer":2,"explanation":"Bruner was strongly influenced by Vygotsky and co-authored the 1976 tutoring study that introduced scaffolding. Statement 3 is the opposite of his view on readiness.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1380","question":"Match the Bruner idea with its description. P. Spiral curriculum Q. LASS R. Discovery learning S. Enactive mode; 1. Knowing through action 2. Learners find principles from examples 3. Adult routines that support a child’s language 4. Revisiting topics at higher levels","options":["P-4, Q-3, R-1, S-2","P-3, Q-4, R-2, S-1","P-4, Q-2, R-3, S-1","P-4, Q-3, R-2, S-1"],"answer":3,"explanation":"The spiral curriculum revisits topics, LASS refers to supportive adult routines, discovery learning means finding principles from instances, and the enactive mode represents knowledge through action.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1381","question":"Class 7 students in a Kendriya Vidyalaya can find the area of rectangles in textbook exercises, but cannot work out how many tiles are needed for their classroom floor. Bruner would say that the most likely cause is:","options":["They learnt procedures, not the idea’s underlying structure, so transfer fails","They are still in the sensorimotor stage and so cannot think about real spaces","Tiling problems need formal operations, which no Class 7 student has yet","They have not had sufficient reinforcement for solving the textbook exercises"],"answer":0,"explanation":"Bruner argued that understanding the fundamental structure of a subject is what makes transfer to new situations possible. Memorised procedures stay tied to their original form.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1382","question":"A child building a block tower is about to give up after it falls twice. The tutor says, ‘You’ve already got the first three right; let’s just try the top one together.’ In Wood, Bruner and Ross’s account, this tutoring function is:","options":["Demonstration","Reduction in degrees of freedom","Frustration control","Recruitment"],"answer":2,"explanation":"Frustration control keeps the learner from becoming discouraged, so that errors do not end the attempt. Recruitment is first engaging the child’s interest in the task.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1383","question":"While a child fits pieces into a puzzle, the tutor points out, ‘Look, this edge is straight but the space here is curved.’ This tutoring function, highlighting the difference between what the child has done and what is needed, is called:","options":["Direction maintenance","Marking critical features","Recruitment","Reduction in degrees of freedom"],"answer":1,"explanation":"Marking critical features draws the learner’s attention to discrepancies that matter for success. Direction maintenance keeps the learner pursuing the goal.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1384","question":"Which classroom remark best reflects Bruner’s view of the learner?","options":["‘Children are empty vessels to be filled with facts by the class teacher.’","‘Children learn only when their correct answers are rewarded.’","‘Children learn best by actively finding relationships and structure.’","‘Children must not ask questions until they know the basic facts.’"],"answer":2,"explanation":"Bruner saw learners as active problem solvers who discover structure. The other remarks reflect transmission or behaviourist views.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1385","question":"Assertion (A): Bruner held that a learner of any age meeting an unfamiliar idea may benefit from enactive and iconic experiences. Reason (R): Bruner’s modes of representation are strict age-bound stages that cannot be revisited.","options":["Both A and R are true, and R is the correct explanation of A","A is true, but R is false","A is false, but R is true","Both A and R are true, but R is not the correct explanation of A"],"answer":1,"explanation":"Bruner’s modes remain available throughout life, which is exactly why older learners can use action and images for new ideas. R wrongly describes them as fixed stages.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1386","question":"A teacher using discovery learning finds that the lesson took three periods instead of one, and a few students still drew wrong conclusions. Which response is most consistent with research on discovery learning?","options":["Abandon discovery entirely and use only lectures, which are quicker and safer","Use full discovery for every topic regardless of time, as struggle builds learning","Make discovery lessons silent and individual so that each child finds the rule","Use guided discovery: plan key questions and examples, then sum up the principle"],"answer":3,"explanation":"Guided discovery keeps the active element while reducing wasted time and misconceptions. Neither abandoning it nor using it for everything is supported.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1387","question":"Which statement about Bruner’s ‘modes of representation’ and Piaget’s ‘stages’ is correct?","options":["Bruner’s modes coexist for life; Piaget’s stages are qualitatively distinct levels","Both are identical in every respect, differing only in the names they use","Bruner’s modes appear in the reverse order to Piaget’s stages, starting with symbols","Piaget’s stages, but not Bruner’s modes, include a role for action in early learning"],"answer":0,"explanation":"Bruner’s enactive, iconic and symbolic modes coexist and can be used for any new learning. Piaget’s stages describe a fixed sequence of overall cognitive structures, beginning with sensorimotor action.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1388","question":"A Class 5 teacher wants students to understand the concept ‘island’. She shows photos of Lakshadweep, Andaman and a river island in the Brahmaputra (yes), and a peninsula and a lake (no), asking students to work out the defining features. This method draws on Bruner’s work on:","options":["Operant conditioning, rewarding correct answers about places","Concept attainment through positive and negative examples","Classical conditioning, pairing pictures with place names","Moral reasoning about how different peoples use the land"],"answer":1,"explanation":"Bruner, Goodnow and Austin showed how learners infer the critical attributes of a concept by comparing examples with non-examples. Majuli in the Brahmaputra is a river island, while a peninsula is a useful near-miss.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1389","question":"Which practice runs AGAINST Bruner’s recommendations?","options":["Letting students find patterns before stating the general rule to them","Revisiting key ideas in later classes at a higher level of depth","Teaching each fact separately, with no attention to how ideas connect","Using objects and pictures before symbols when introducing new ideas"],"answer":2,"explanation":"Bruner stressed teaching the structure of a subject, the relationships between ideas. Isolated facts are hard to remember and do not transfer.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1390","question":"A Class 3 child learns about clocks by moving the hands of a cardboard clock (Stage P), then by reading clock-face pictures in her book (Stage Q), and finally by writing times like 7:45 (Stage R). If she later cannot read a digital time, the most Bruner-consistent teacher action is to:","options":["Give her many more written times to copy until the digital form finally sticks","Scold her gently for forgetting, so that she pays much closer attention next time","Assume she is not yet ready and stop teaching time for this year","Go back to the cardboard clock beside the digital time, linking action to symbol"],"answer":3,"explanation":"When a symbolic representation breaks down, returning to enactive and iconic support helps rebuild meaning. Bruner did not treat difficulty as a reason to stop teaching.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1391","question":"How many of these classroom practices follow from Bruner’s ideas? I. Planning a topic so that it is met again at higher levels in later classes. II. Encouraging students to make educated guesses and then test them. III. Teaching new ideas only through symbols, since pictures waste time. IV. Asking students to discover principles from carefully chosen examples.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I (spiral curriculum), II (intuitive thinking) and IV (discovery) follow from Bruner. He valued iconic representation as a support, so III contradicts him.","difficulty":"hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1392","question":"A teacher keeps a group of students on track during a long experiment by reminding them, ‘Remember, we are trying to find out which soil holds more water,’ whenever they drift into other questions. In Wood, Bruner and Ross’s scaffolding functions, this is:","options":["Direction maintenance","Demonstration","Frustration control","Marking critical features"],"answer":0,"explanation":"Direction maintenance keeps learners pursuing the goal of the task. Demonstration means modelling a solution for the learner to imitate.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1393","question":"Which pair of ideas is most closely linked to Jerome Bruner?","options":["Equilibration and schema","Zone of proximal development and private speech","Spiral curriculum and intuitive thinking","Operant conditioning and shaping"],"answer":2,"explanation":"Bruner proposed the spiral curriculum and emphasised the value of intuitive thinking. The other pairs belong to Piaget, Vygotsky and Skinner respectively.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1394","question":"A science teacher asks Class 6 students, ‘Why do you think leaves of some plants close at night?’ and lets them suggest guesses before investigating. A colleague says guessing encourages careless thinking. Bruner would argue that:","options":["The colleague is right; only proven facts should ever be stated in a science class","Intuitive guesses, later tested, are central to how scientists and learners think","Guessing is useful only in mathematics, where answers can be checked easily","Students should be encouraged to guess but never asked to test their guesses"],"answer":1,"explanation":"Bruner held that schools undervalue intuitive thinking, which generates hypotheses that analytical thinking then checks. Untested guessing would miss the second half.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1395","question":"Seven-year-old Aarav studies in Grade 2. Under the 5+3+3+4 structure of NEP 2020, he is in the ___ stage, where the pedagogy should be ___.","options":["Preparatory; light textbooks with some formal but interactive classroom learning","Foundational; flexible, multilevel, play- and activity-based learning","Foundational; formal subject teachers and written examinations","Middle; experiential learning across subjects with subject teachers"],"answer":1,"explanation":"The foundational stage covers ages 3–8 (three years of pre-school plus Grades 1–2) and calls for play- and activity-based learning; the preparatory stage starts at Grade 3.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1396","question":"The five years of the foundational stage under NEP 2020 consist of:","options":["Grades 1 to 5, matching the old primary stage of schooling","Two years of pre-school or Anganwadi followed by Grades 1 to 3","One year of Balavatika followed by Grades 1 to 4 of the primary school","Three years of Anganwadi, pre-school or Balavatika, then Grades 1–2"],"answer":3,"explanation":"The foundational stage is ages 3–8: three years of ECCE plus Grades 1 and 2. Grades 3–5 form the preparatory stage, so options A and C mix up the two stages.","difficulty":"very-hard","source":"CTET Paper I · DSSSB PRT"},
  {"id":"cdp-child-development-1397","question":"Which statement correctly compares the 5+3+3+4 structure with the earlier 10+2 structure?","options":["It brings ages 3 to 6 into the curricular structure, which 10+2 did not","It cuts the total years of schooling from 12 to 10 to save time","It removes Grades 11 and 12 from school and moves them to junior colleges","It begins formal schooling with written tests at the age of 3"],"answer":0,"explanation":"5+3+3+4 covers ages 3–18 and so brings early childhood (ages 3–6), earlier outside 10+2, into the curricular framework; Grades 1–12 remain.","difficulty":"hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1398","question":"Why does NEP 2020 treat foundational literacy and numeracy as an urgent national mission and its highest priority?","options":["Because Class 10 board results across the country have been falling steadily","Because English proficiency in schools is low and this limits higher education","Because many elementary pupils lack FLN, and later schooling then means little","Because FLN can replace the need for other subjects in the early grades"],"answer":2,"explanation":"NEP 2020 notes a learning crisis in which many children lack basic reading and arithmetic; since all later learning rests on FLN, it says the rest of the policy becomes largely irrelevant without it.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1399","question":"To tackle gaps in foundational literacy and numeracy, which strategy does NEP 2020 suggest besides the work of teachers?","options":["Detaining weak children in Grade 1 until they can read and count fluently","Peer tutoring and trained community volunteers giving one-on-one support","Replacing teachers with educational apps that adapt to each child","Postponing FLN teaching to Grade 6, when children are more mature"],"answer":1,"explanation":"NEP 2020 proposes peer tutoring and volunteer support (one-on-one help) to supplement teachers; detention and postponement would deepen the problem.","difficulty":"hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-1400","question":"Which statement about the three-language formula in NEP 2020 is correct?","options":["Hindi is made compulsory as one of the three languages in every state of India","English must be one of the three languages, as the link language","Every state must teach Sanskrit as the third language from Class 6","No language is imposed; states choose, with at least two native to India"],"answer":3,"explanation":"NEP 2020 keeps the three-language formula but makes it flexible: states and students choose, provided at least two of the three languages are native to India.","difficulty":"very-hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1401","question":"A five-year-old in a Balavatika attached to a primary school is given daily handwriting drills and weekly written tests. Under NEP 2020, this practice is:","options":["Inappropriate: this stage calls for play- and activity-based learning","Appropriate, because early drills raise literacy faster than play does","Appropriate, but only for children in urban schools with good facilities","Required, so that children are ready for the Grade 1 entrance test"],"answer":0,"explanation":"NEP 2020 frames the Balavatika year as part of ECCE, with play-based, activity-based learning; drill-and-test routines are developmentally inappropriate at age five.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1402","question":"Which school decision is most consistent with the NEP 2020 principle of ‘no hard separations’?","options":["Allowing only science students to take music in Class 11, as a reward","Offering vocational subjects only to students with low marks in Class 10","Letting a Class 11 student combine physics, history and music","Scheduling art classes only after the board examinations are over"],"answer":2,"explanation":"NEP 2020 rejects rigid walls between arts, humanities and sciences, between curricular and ‘extra-curricular’ activities, and between vocational and academic streams.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1403","question":"For students of Grades 6–8, NEP 2020 suggests a ten-day bagless period during which they:","options":["Revise for examinations without carrying books, using only their notes","Intern with local vocational experts such as carpenters, gardeners and potters","Stay at home to reduce their workload and rest before the term exams","Attend special coaching classes held in school for national competitive examinations"],"answer":1,"explanation":"The bagless days give hands-on exposure to local crafts and trades, in line with NEP 2020’s aim of integrating vocational exposure from the middle stage.","difficulty":"moderate","source":"CTET Paper II · State TET"},
  {"id":"cdp-child-development-1404","question":"Assertion (A): NEP 2020 recommends that early grades be taught, wherever possible, in the child’s home language or mother tongue. Reason (R): Children learn and grasp non-trivial concepts more quickly in their home language.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"NEP 2020 itself gives this reason: children understand concepts more readily in their home language, which is why it recommends it as the medium in the early grades.","difficulty":"hard","source":"CTET · REET"},
  {"id":"cdp-child-development-1405","question":"NEP 2020 says assessment should move away from being primarily summative and focused on rote memorisation towards being:","options":["Based on more frequent rote tests to keep students revising regularly","Purely norm-referenced, ranking each student against the class","Limited to board examinations, with no school-level testing","Regular, formative and competency-based, testing higher-order skills"],"answer":3,"explanation":"NEP 2020 calls for regular, formative, competency-based assessment that promotes learning and tests higher-order skills rather than memory.","difficulty":"moderate","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1406","question":"Which of these describe the holistic progress card proposed in NEP 2020? I. It includes self-assessment and peer assessment besides teacher assessment. II. It reports progress in cognitive, affective and psychomotor domains. III. It is meant to be shared with parents, linking home and school. IV. It replaces teacher observation with standardised test scores.","options":["I and IV only","II and IV only","I, II and III only","I, II, III and IV"],"answer":2,"explanation":"The 360-degree progress card covers several domains, draws on self, peer and teacher assessment and actively involves parents; it does not reduce assessment to standardised scores.","difficulty":"very-hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1407","question":"NEP 2020 proposes school examinations in Grades 3, 5 and 8. Their stated purpose is to:","options":["Track learning over the years to improve the system, testing core concepts","Decide which students must be detained in the same grade for one more year","Rank schools publicly so that parents can choose for admission","Replace the Grade 10 board examination with three smaller tests"],"answer":0,"explanation":"These examinations are meant to monitor learning and help improve teaching and the system; they test basic learning outcomes and core concepts, not memorised content.","difficulty":"very-hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1408","question":"A Class 7 teacher teaches symmetry through Warli and Madhubani patterns and the history of the region through its folk art. NEP 2020 calls this:","options":["Rote learning through patterns","Vocational training in folk crafts","Art-integrated education","Remedial teaching through drawing"],"answer":2,"explanation":"NEP 2020 promotes art-integrated education, which uses arts and culture to teach concepts across subjects and links learning with Indian culture.","difficulty":"moderate","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1409","question":"Why does NEP 2020 recommend reducing curriculum content in each subject to its core essentials?","options":["To finish the syllabus faster and so hold more examinations during the year","To free time for critical thinking and inquiry- and discussion-based learning","To reduce the number of teachers needed for each subject in government schools","To shorten the school day so that children have more time for tuition"],"answer":1,"explanation":"Lighter content is meant to free time for deep, experiential and holistic learning instead of rote coverage of an overloaded syllabus.","difficulty":"hard","source":"CTET · State TET"},
  {"id":"cdp-child-development-1410","question":"In a Grade 2 class in Bengaluru, children speak Kannada, Tamil, Urdu and Hindi at home, and the medium of instruction is Kannada. Consistent with NEP 2020, the teacher should:","options":["Insist on Kannada only and fine children who use their home languages","Change the medium to English so that no home language is favoured","Use a bilingual approach, drawing on home languages alongside Kannada","Shift the Urdu-speaking children to a school with an Urdu medium"],"answer":2,"explanation":"NEP 2020 encourages teachers to use a bilingual approach and bilingual materials with children whose home language differs from the medium of instruction.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1411","question":"Match each NEP 2020 stage with its emphasis: P. Foundational  Q. Preparatory  R. Middle  S. Secondary — 1. Flexible, multilevel, play- and activity-based learning  2. Play and discovery with a gradual start of formal but interactive classroom learning  3. Experiential learning across sciences, mathematics, arts, social sciences and humanities with subject teachers  4. Greater depth, critical thinking and flexibility in the choice of subjects","options":["P-1, Q-2, R-3, S-4","P-2, Q-1, R-3, S-4","P-1, Q-3, R-2, S-4","P-1, Q-2, R-4, S-3"],"answer":0,"explanation":"The emphasis moves from play (foundational) to gradual formal learning (preparatory), to subject-based experiential learning (middle), to depth and choice (secondary).","difficulty":"very-hard","source":"CTET · DSSSB TGT"},
  {"id":"cdp-child-development-1412","question":"NEP 2020 proposes that students be allowed to take board examinations on up to two occasions in a school year. The main purpose is to:","options":["Raise the income of examination boards through extra fees for each attempt","Make students study twice as hard, since each sitting is a fresh and complete test","Increase competition among students, as the better of two scores decides rank","Reduce the pressure of a single attempt, allowing a second try for improvement"],"answer":3,"explanation":"A second opportunity reduces the ‘one-shot’ pressure that drives coaching and anxiety, in keeping with NEP 2020’s aim of making board exams low-stakes.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1413","question":"Assertion (A): NEP 2020 recommends that vocational education be introduced only after Class 12. Reason (R): NEP 2020 aims to remove the hard separation between vocational and academic streams.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"NEP 2020 brings vocational exposure in from Grade 6 (with internships and bagless days), precisely because it wants to integrate vocational and academic learning; so A is false.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1414","question":"NEP 2020 says that teachers ‘truly shape the future of our children’. Which reform is consistent with this view?","options":["A four-year integrated B.Ed. as the minimum qualification by 2030","Dropping teacher eligibility requirements to recruit more teachers quickly","Replacing regular teachers with contract para-teachers to cut costs","Deploying teachers more often for census and election duty"],"answer":0,"explanation":"NEP 2020 aims to raise teacher preparation and status through the integrated B.Ed., CPD and an end to para-teacher hiring and non-teaching duties.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1415","question":"Which NEP 2020 measure is aimed specifically at equity for socio-economically disadvantaged groups?","options":["A common entrance test for Class 1 admission, so seats go by merit alone","Ending the mid-day meal scheme to free funds for hiring more teachers","A Gender-Inclusion Fund and Special Education Zones in disadvantaged regions","Merging all small village schools into larger city schools with much better labs"],"answer":2,"explanation":"NEP 2020 proposes a Gender-Inclusion Fund for girls and transgender students and Special Education Zones in disadvantaged regions to close equity gaps.","difficulty":"very-hard","source":"CTET · DSSSB TGT"},
  {"id":"cdp-child-development-1416","question":"Which activity best reflects ‘experiential learning’ as promoted by NEP 2020?","options":["Copying neat notes from the blackboard about rainfall and the monsoon","Measuring rainfall with home-made gauges and graphing the data","Reading the textbook chapter on weather aloud in turns around the class","Memorising definitions of weather terms for a weekly quiz"],"answer":1,"explanation":"Experiential learning means learning by doing and reflecting on real experience; the rain-gauge project combines hands-on work, data and inquiry.","difficulty":"moderate","source":"CTET Paper II · State TET"},
  {"id":"cdp-child-development-1417","question":"Which of these ideas are common to NCF 2005 and NEP 2020? I. Reducing rote learning. II. Using the home language or mother tongue in the early years. III. Making board examinations less stressful. IV. Detaining children who fail from Class 1 onwards.","options":["I and IV only","II and IV only","I, II, III and IV","I, II and III only"],"answer":3,"explanation":"Both documents oppose rote learning, value the home language and want low-stress board exams; neither recommends detention from Class 1.","difficulty":"very-hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1418","question":"A deaf child joins a Grade 3 class. Consistent with NEP 2020, the school should:","options":["Send the child to a special school only, since regular classes cannot cope","Rely on lip-reading alone, so that the child adapts to hearing peers","Use Indian Sign Language, with suitable materials and support","Exempt the child from all language learning to reduce the burden"],"answer":2,"explanation":"NEP 2020 calls for Indian Sign Language to be standardised across the country and for national and state curriculum materials for students with hearing impairment.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1419","question":"A Grade 4 teacher finds that half her class cannot read a Grade 2 text. The response most consistent with NEP 2020’s FLN priority is to:","options":["Continue with the Grade 4 syllabus so as to finish it on time for the exams","Assess levels and teach foundational reading by level for part of each day","Detain these children in Grade 4 until they can read at grade level again","Ask the parents to arrange private tuition so that reading improves at home"],"answer":1,"explanation":"NEP 2020 wants learning gaps in FLN closed urgently through targeted support at the child’s actual level; ploughing on with the syllabus leaves them behind permanently.","difficulty":"very-hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-1420","question":"Match each theorist with the classroom technique that grows most directly out of his work. P. Skinner  Q. Bandura  R. Vygotsky  S. Ausubel. 1. Teacher thinks aloud while solving a problem so students can imitate the strategy 2. Small-step self-paced frames with immediate feedback 3. A brief overview before a new chapter to anchor details 4. Hints that are gradually withdrawn as the learner gains control","options":["P-2, Q-4, R-1, S-3","P-1, Q-2, R-4, S-3","P-2, Q-1, R-4, S-3","P-3, Q-1, R-4, S-2"],"answer":2,"explanation":"Programmed instruction is Skinner's; cognitive modelling follows Bandura; faded scaffolding within the ZPD follows Vygotsky; the advance organiser is Ausubel's.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1421","question":"Asked to choose the larger fraction, many Class 4 children pick 1/8 over 1/4, saying ‘8 is bigger than 4’. What should the teacher conclude?","options":["They are guessing randomly, since fractions still mean nothing at all to them","Whole-number thinking: they miss that more equal parts make each part smaller","They cannot read numbers correctly and so confuse the digits 4 and 8","They need to memorise a list of fraction comparisons by heart"],"answer":1,"explanation":"The error is systematic and logical from a whole-number view. Sharing a roti among 4 versus 8 children quickly shows that each share is smaller when the denominator is larger.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1422","question":"A Class 6 student says, ‘If I double each side of a square, its area will also double.’ What does this error reveal and how should the teacher respond?","options":["Over-applied doubling; drawing unit squares will show the area becomes four times","Careless reading of the question; ask him to read it twice before he answers it","A memory lapse about the formula; make him learn it by heart and recite it","Lack of intelligence for geometry; give him easier sums until he catches up"],"answer":0,"explanation":"Students often assume all quantities change proportionally with length. Drawing a 2×2 and a 4×4 square shows 4 versus 16 unit squares, challenging the linear assumption.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1423","question":"In subtraction sums such as 300 − 156 and 402 − 127, Class 3 student Ritu always writes the bottom digit wherever the top digit is 0 (for example, 0 − 6 as 6). What is the best description of her errors?","options":["Random slips caused by tiredness at the end of a long school day","A visual problem with the digit zero, which she may not be seeing clearly","Proactive interference from addition, where order does not matter","A consistent faulty rule about zeros, to be diagnosed and re-taught"],"answer":3,"explanation":"The error is the same across sums, so it reflects a faulty procedure about zeros rather than carelessness. Exchanging bundles of tens and hundreds addresses the misunderstanding.","difficulty":"hard","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-1424","question":"A Class 5 student whose home language is Hindi writes in English, ‘I am having two brothers’ and ‘What you are doing?’. How should the teacher understand these errors?","options":["As evidence of poor intelligence, since the rules have been taught clearly in class","As deliberate carelessness that should be punished to stop the habit","As natural signs of a developing second language, shaped partly by the first","As a sign that English should be stopped until Class 8 to avoid confusion"],"answer":2,"explanation":"Second-language learners build an interim system using rules from their first language and their emerging hypotheses; such errors show learning in progress and guide teaching.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1425","question":"Which of the following teacher-related factors are known to influence students' learning? I. The teacher's expectations of students. II. The teacher's enthusiasm and clarity of explanation. III. The teacher's relationship and emotional climate in the class. IV. The colour of the teacher's clothes.","options":["I, II and III only","I and II only","II and IV only","I, II, III and IV"],"answer":0,"explanation":"Teacher expectations, clarity, enthusiasm and the emotional climate all affect learning; clothing colour has no established effect.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-1426","question":"A Class 2 teacher keeps the room fear-free: children may ask questions without being laughed at, and mistakes are discussed calmly. Why does this matter for learning?","options":["It is required only for discipline, so that the class stays orderly","Anxiety drains attention and working memory; security invites exploration","It makes the teacher popular with parents, which in turn helps school enrolment","It removes the need for assessment, since mistakes no longer matter"],"answer":1,"explanation":"Anxiety consumes cognitive resources and discourages questioning. A safe climate, which the RTE Act and NCF 2005 both stress, supports active participation and learning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1427","question":"In a school serving many first-generation learners, homework often requires internet searches or explanations from parents. Many children return it incomplete. Which factor affecting learning is most at work, and what is the fair response?","options":["Laziness of the children; give extra homework as punishment to build habits","Low intelligence; place these children in a separate, slower-paced section","Lack of motivation; reward only those who complete it, to set an example","Unequal home resources; set doable tasks and support children at school"],"answer":3,"explanation":"Socio-economic and home factors (access to resources, educated adults) affect learning opportunities. Tasks that assume such support disadvantage some children through no fault of their own.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1428","question":"A Class 6 student must memorise a meaningful 16-line poem. Which method is generally recommended, and when would the alternative be better?","options":["Always the part method, since smaller parts are easier for any child to hold","Whole method here; the part method suits very long or difficult material","Always the whole method, whatever the length or difficulty of the material","Neither method; only the number of repetitions matters for memorising"],"answer":1,"explanation":"Learning a meaningful piece as a whole preserves its sense and connections; for very long or hard material, learning in parts (then joining them) can be more efficient.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1429","question":"Gaurav's typing speed rose quickly for six weeks, then stayed flat for three weeks despite practice, and later began rising again. The flat stretch in his learning curve is called a plateau. Which is a common explanation?","options":["He has reached the absolute limit of his ability, and no further gain is possible","His earlier learning has been erased by interference from other activities","He has begun to forget what he learnt earlier because practice became routine","A shift to higher units, like whole words, or fatigue and lost interest"],"answer":3,"explanation":"Plateaus often occur while lower-level habits are reorganised into higher-level units, or due to fatigue, boredom or poor methods; with new strategies or motivation progress resumes.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1430","question":"A Class 4 teacher (a) praises children immediately when they answer correctly, (b) demonstrates how to fold paper into a boat while children watch, and (c) gives hints when children struggle and withdraws them as they improve. These practices draw respectively on the ideas of:","options":["Pavlov, Köhler and Piaget","Bandura, Skinner and Vygotsky","Skinner, Bandura and Vygotsky","Thorndike, Vygotsky and Bandura"],"answer":2,"explanation":"Immediate reinforcement reflects operant conditioning (Skinner); learning by watching a demonstration reflects Bandura's observational learning; faded hints reflect Vygotskian scaffolding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1431","question":"Assertion (A): A teacher should study the pattern of a child's errors before re-teaching a topic. Reason (R): Systematic errors usually come from a consistent but faulty idea or rule that the child has constructed.","options":["Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Because systematic errors reflect a coherent wrong rule, re-teaching works best when it targets that rule; simply repeating the lesson may leave it untouched.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1432","question":"Assertion (A): Any change in a child's behaviour that appears with growth, such as being able to hold a pencil at age four, is learning. Reason (R): Learning is a relatively lasting change in behaviour or knowledge that results from experience or practice.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"Changes due mainly to maturation, fatigue, illness or drugs are not counted as learning. R correctly defines learning as change through experience, so A is false.","difficulty":"hard","source":"CTET · HTET"},
  {"id":"cdp-child-development-1433","question":"Which of these changes would a psychologist count as learning?","options":["A child running more slowly at the end of a long race because of tiredness","A child who, after weeks of practice, can solve two-step word problems","A baby's first teeth appearing on schedule as the body grows","A child who is drowsy and forgetful after taking cough medicine"],"answer":1,"explanation":"Learning is a relatively permanent change resulting from experience. Fatigue, physical growth and the effects of medicine are temporary or maturational changes.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1434","question":"Two groups practise the same arithmetic. Group A gets back its corrected work with specific comments the next day; Group B only receives final marks at the end of the term. Group A improves far more. Which principle explains this?","options":["Knowledge of results: specific, timely feedback guides correction","Spontaneous recovery of skills after a rest between practice sessions","Overjustification, as marks reduce interest in arithmetic itself","The law of disuse, as Group B forgot what it had not practised"],"answer":0,"explanation":"Specific, prompt feedback (knowledge of results) tells learners what to change and keeps them engaged; delayed marks give little information about what went wrong.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-1435","question":"Before a project, Class 8 student Aditi sets goals and plans her time; while working she checks whether her plan is working and changes strategies; afterwards she reviews what went well. This cycle is best described as:","options":["Classical conditioning of study habits through repeated routines","Learned helplessness masked by over-careful planning","Self-regulated learning: planning, monitoring and reflection","Formal discipline, training the mind through hard tasks"],"answer":2,"explanation":"Self-regulated learners plan, monitor and evaluate their own learning, using metacognitive and motivational strategies; it draws on Bandura's work on self-regulation and on metacognition.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1436","question":"Match each classroom situation with the kind of learning it shows. P. A child repeatedly tries keys until one opens a lock  Q. After puzzling over a figure, a child suddenly sees how to split it into triangles  R. A child copies a classmate's polite greeting after seeing it praised  S. A child who has wandered the village can later guide a visitor along a new route. 1. Insight  2. Observational learning  3. Latent learning with a cognitive map  4. Trial and error","options":["P-1, Q-4, R-2, S-3","P-4, Q-1, R-3, S-2","P-2, Q-1, R-4, S-3","P-4, Q-1, R-2, S-3"],"answer":3,"explanation":"Trying keys is trial and error (Thorndike); sudden restructuring is insight (Köhler); copying a reinforced model is observational learning (Bandura); a cognitive map from exploration is latent learning (Tolman).","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1437","question":"A Class 3 child is easily distracted and has difficulty sustaining attention. Which classroom arrangement is most helpful?","options":["Seat him near the teacher, away from doors, with short tasks and checkpoints","Seat him at the back so that he does not disturb the others while they work","Give him longer tasks to build attention through endurance and practice","Remove him from group activities completely so there are fewer distractions"],"answer":0,"explanation":"Reducing distractions, keeping him near the teacher for cues, and breaking tasks into short segments with feedback support attention without excluding him from learning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1438","question":"Class 9 student Faizan loves reading novels but hides it because classmates mock ‘bookworms’, and he has stopped joining the library club. Which factor affecting learning is most at work here?","options":["Physical maturation, as adolescents naturally lose interest in reading","Retroactive interference between novels and his school textbooks","Learned helplessness about his own ability to read well","Peer-group norms and acceptance shaping his motivation and behaviour"],"answer":3,"explanation":"In adolescence the peer group strongly shapes what is valued; fear of rejection can suppress interests. Teachers can build classroom norms that make reading socially valued.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1439","question":"Which statements about errors in learning are correct? I. A child's error may come from a logical extension of a rule that worked in an earlier context. II. Over-correcting every error in red can discourage children from attempting difficult tasks. III. Errors made by many children in the same way usually point to a common misconception. IV. A correct final answer always proves correct understanding.","options":["I and IV only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"A right answer can come from a wrong method or from memorisation without understanding, so IV is false. The other statements describe errors as windows into children's thinking.","difficulty":"hard","source":"CTET Paper 1 · Super TET"},
  {"id":"cdp-child-development-1440","question":"A teacher asks Class 4 children to explain how they got answers that are correct as well as those that are wrong. One child got 25 × 4 = 100 by adding 25 four times while another reasoned ‘four quarters make a whole, so it is 100’. What is the main value of this practice?","options":["It wastes time, since the answer is already correct and needs no discussion","It helps only weaker students, who need to hear the steps again","It shows the different strategies and understanding behind one answer","It is useful only for grading, to give marks for the method shown"],"answer":2,"explanation":"Asking for reasoning shows the thinking behind answers: repeated addition and a part–whole insight are different levels of understanding, which helps the teacher plan next steps.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1441","question":"Which statement about the relation between learning and maturation is most accurate?","options":["Learning and maturation are the same process seen from two angles","Maturation depends entirely on the teaching and practice given at school","Learning can fully replace maturation if practice is intense enough","Maturation gives readiness, and experience and practice build on it"],"answer":3,"explanation":"Maturation is growth that unfolds largely from within; it provides readiness, and learning through experience builds skills on that base. Drill before readiness yields little.","difficulty":"moderate","source":"CTET · REET"},
  {"id":"cdp-child-development-1442","question":"A teacher notices that Class 6 children recall a science concept much better after they have explained it to younger children in Class 3. The most likely reason is that:","options":["Teaching makes them organise, elaborate and retrieve what they know","Younger children correct the older ones' facts, so errors are removed","Explaining to others works through classical conditioning of the facts","Teaching reduces the amount of material that has to be learnt"],"answer":0,"explanation":"Preparing to teach and explaining involve retrieval, organisation and elaboration, strengthening the tutor's own learning (sometimes called the protégé or learning-by-teaching effect).","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1443","question":"A Class 5 teacher finds that children grasp the idea of ‘perimeter’ much better when they walk around the school garden with a measuring tape than when they read its definition. Which combination of factors best explains this?","options":["Concrete experience suited to their stage, plus active involvement","Negative reinforcement, since children walk to avoid reading the definition","The law of disuse, since reading definitions is quickly forgotten","Only the novelty of going outside, with no real benefit to learning"],"answer":0,"explanation":"Children in the concrete operational stage learn best from concrete, hands-on experience; active participation also aids attention and memory.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1444","question":"Which of these teacher actions is most consistent with what we know about how children learn, across theories?","options":["Covering the syllabus at one uniform pace for everyone and testing only memory","Avoiding feedback so that children discover all their own errors unaided","Using prior knowledge, active tasks, timely feedback and effort-based praise","Rewarding only the top three in every test to set a standard for others"],"answer":2,"explanation":"Prior knowledge (constructivism, Ausubel), active engagement, feedback (behaviourist and cognitive views) and effort attributions (Weiner, Dweck) are all well supported; the other options contradict them.","difficulty":"moderate","source":"CTET · HTET"},
  {"id":"cdp-child-development-1445","question":"Match each teacher’s remark with the theorist it reflects most closely. P. ‘Before teaching, I find out what each child can do with a little help.’ Q. ‘I would rather let him puzzle over why his prediction failed than give him the answer.’ R. ‘I plan to come back to this topic next year at a deeper level.’ 1. Bruner 2. Piaget 3. Vygotsky","options":["P-2, Q-3, R-1","P-3, Q-1, R-2","P-1, Q-2, R-3","P-3, Q-2, R-1"],"answer":3,"explanation":"Assessing assisted performance points to Vygotsky’s ZPD, using a failed prediction to create disequilibrium is Piagetian, and returning to a topic at greater depth is Bruner’s spiral curriculum.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1446","question":"According to Piaget, what mainly motivates a child to move to more advanced ways of thinking?","options":["Rewards and praise from the teacher for each new correct answer given","Fear of punishment for wrong answers, both in class and at home","Competition with classmates to be the first to understand the idea","The need to resolve imbalance when experience does not fit schemas"],"answer":3,"explanation":"For Piaget, disequilibrium is uncomfortable and the drive to restore balance, through accommodation, is intrinsic. External rewards play little part in his theory.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1447","question":"A Class 6 student is sure that 0.5 × 4 must be more than 4, ‘because multiplying always makes a number bigger’. In Piaget’s terms, this error arises because the student is:","options":["Assimilating decimals into a whole-number multiplication schema","Accommodating correctly to decimals by changing his schema","Showing pre-operational animism about how numbers behave","Using formal operational proportional reasoning about size"],"answer":0,"explanation":"The rule ‘multiplication makes bigger’ holds for whole numbers greater than 1, and the student is fitting decimals into that schema without changing it. The teacher’s task is to create conditions for accommodation.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1448","question":"A Class 5 child says 0.25 is greater than 0.3 ‘because 25 is bigger than 3’. Which teacher response best combines Piaget’s and Vygotsky’s ideas?","options":["Mark it wrong and give ten similar sums for homework to correct the habit","Tell the child to memorise the rule that ‘more digits does not mean bigger’","Have her shade both on hundred-squares and guide her with questions","Move the child to a lower-level group permanently for decimals"],"answer":2,"explanation":"Shading creates a concrete conflict with her rule (Piaget), while guiding questions help her reason it through (Vygotsky). Drill or memorised rules leave the faulty schema in place.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1449","question":"To teach the triangle, a Class 2 teacher has children walk along a large triangle chalked on the playground, then draw triangles in their notebooks, and finally name the sides and corners. Her plan follows most closely:","options":["Skinner’s programmed learning in small, rewarded steps","Bruner’s enactive, iconic and symbolic sequence","Kohlberg’s stages of moral development","Pavlov’s classical conditioning of shapes"],"answer":1,"explanation":"Walking the shape is enactive, drawing it is iconic and naming its properties is symbolic. This is Bruner’s recommended sequence for new ideas.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1450","question":"Consider these statements about Piaget’s view of intelligence. 1. Intelligence is a form of adaptation to the environment. 2. The functions of organisation and adaptation remain the same throughout life. 3. The cognitive structures (schemas and operations) change from stage to stage. Which is/are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Piaget distinguished invariant functions (organisation, adaptation) from structures that change across stages. He saw intelligence itself as biological adaptation extended to thought.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1451","question":"Planning an experiment on how fast sugar dissolves, a Class 8 student says, ‘If I change the temperature and the stirring at the same time, I won’t know which one made the difference.’ This shows the formal operational ability to:","options":["Isolate variables by changing one factor at a time","Conserve number when objects are spread out in a row","Classify objects by one attribute at a time","Use symbolic play to stand for real events"],"answer":0,"explanation":"Recognising that only one variable should be changed at a time is the scheme of isolating variables that Piaget and Inhelder linked to formal operations.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1452","question":"Studies using the ‘violation of expectation’ method found that infants of about four months look longer when a screen seems to pass through a hidden box, as if surprised. These findings are mostly used to argue that:","options":["Piaget overestimated infants’ abilities, since they are so easily surprised","Object permanence appears only after two years, as Piaget later admitted","Infants may grasp hidden objects earlier than Piaget’s search tasks implied","Infants are already in the formal operational stage by four months"],"answer":2,"explanation":"Piaget relied on manual search, which needs motor skills infants lack. Looking-time studies, such as Baillargeon’s, suggest some knowledge of hidden objects earlier, so Piaget may have underestimated infants.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1453","question":"Which statement correctly distinguishes the ZPD from scaffolding?","options":["They are two names for exactly the same idea in Vygotsky’s writing","Scaffolding is the range of tasks a child can do alone; the ZPD is the help given","The ZPD is a Piagetian idea, scaffolding a Brunerian one, and they are unrelated","ZPD: tasks a learner can do only with help; scaffolding: support given there"],"answer":3,"explanation":"The ZPD describes where learning can happen; scaffolding describes how support is given there and gradually withdrawn. The two are linked but not identical.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1454","question":"Assertion (A): Piaget recommended that children be given many opportunities to handle and act on real objects. Reason (R): For Piaget, knowledge is constructed through the child’s own actions on the environment, which are gradually internalised as mental operations.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Piaget saw operations as internalised actions, so acting on objects is the raw material of thought. R therefore explains why he recommended it.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1455","question":"A three-year-old chooses a toy car as a birthday present for his grandmother, explaining, ‘She will like it because I like cars.’ Piaget would see this as an example of:","options":["Egocentrism: assuming others share his own preferences","Selfishness, which should be corrected through moral lessons","Conservation of identity, as the car stays the same","Transductive reasoning about time and birthdays"],"answer":0,"explanation":"Pre-operational egocentrism is a cognitive limitation in taking another’s perspective, not a moral fault. He genuinely believes the gift will please her.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1456","question":"In interviewing children, Piaget did not use a fixed list of questions; he followed each child’s answers with new questions tailored to what the child had said. A recognised strength and weakness of this clinical method are respectively:","options":["It is fully standardised; but it reveals nothing about children’s reasoning","It uses large random samples; it ignores the reasoning behind answers","It reveals reasoning behind answers; results may depend on the interviewer","It eliminates the influence of language; it takes too little time"],"answer":2,"explanation":"Flexible probing uncovers how children think, which fixed tests miss. The cost is reduced standardisation, so different interviewers may obtain different responses.","difficulty":"hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1457","question":"Asked to put shapes ‘that go together’ into groups, a four-year-old puts a red square next to a red circle, then a blue circle next to the red circle, then a blue triangle next to the blue circle, changing her basis as she goes. Piaget would say this shows:","options":["Mature multiple classification, using colour and shape together","Seriation, arranging the shapes in a graded order of size","Pre-operational difficulty keeping one criterion while sorting","Formal operational combinatorial thinking about all pairings"],"answer":2,"explanation":"Young children often make ‘chains’ in which each item links to the last by a different feature. Using one consistent criterion develops later, in the concrete operational stage.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1458","question":"A teacher shows that stick A is longer than stick B, then that stick B is longer than stick C, and then hides stick A. Asked which is longer, A or C, a five-year-old says, ‘I don’t know, I haven’t seen them together,’ while an eight-year-old says, ‘A, of course.’ The older child is using:","options":["Animism, treating the hidden stick as if it were alive","Transitive inference, a concrete operational ability","Hypothetical reasoning about imaginary sticks","Iconic representation only, from a mental picture"],"answer":1,"explanation":"Inferring A > C from A > B and B > C is transitivity, which develops with concrete operations. The younger child relies on direct perception and cannot combine the relations.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1459","question":"How many of these classroom practices are consistent with Piaget’s theory? I. Setting problems slightly beyond children’s present understanding. II. Encouraging children to explain their reasoning to one another. III. Expecting all Class 3 children to master proportional reasoning. IV. Using children’s wrong answers to understand their thinking.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV fit Piaget’s ideas of moderate challenge, peer conflict and errors as clues. Proportional reasoning is formal operational, so expecting it in Class 3 contradicts the theory.","difficulty":"hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1460","question":"A Class 1 child, watching the teacher pour juice from a short glass into a tall one, is asked a question that requires conservation. Which of these questions is the actual conservation question?","options":["‘Which of the two glasses is taller, the first or the second?’","‘What colour is the juice, and does it look different now?’","‘Can you pour the juice back into the short glass again?’","‘Is there more juice now, less, or the same amount as before?’"],"answer":3,"explanation":"Conservation is about whether the quantity is understood to stay the same despite a change in appearance. The other questions concern perception or action, not quantity.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1461","question":"A Class 4 child who usually uses Hindi at home learns English words for colours by matching coloured cards with the teacher and saying the words aloud together; later she labels colours in English on her own. Which statement best explains her learning from a Vygotskian view?","options":["She learnt through shared activity before using the words on her own","She learnt only through physical maturation of her speech organs","She learnt the words because she was corrected and punished for mistakes","Her Hindi interfered with learning, so the home language should be banned"],"answer":0,"explanation":"Learning moves from joint activity with a more knowledgeable other to independent use, which is internalisation. The home language is a resource, not a barrier.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1462","question":"Which of the following findings challenges Piaget’s claim that young children cannot take another person’s point of view?","options":["Four-year-olds talk more simply to two-year-olds than to adults","Six-year-olds often fail conservation of liquid in the glass task","Infants show the A-not-B error when searching for toys","Adolescents show the imaginary audience in their worries"],"answer":0,"explanation":"Adjusting speech to a younger listener shows that four-year-olds can consider another’s perspective in familiar situations. The other findings are consistent with Piaget.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1463","question":"Assertion (A): Vygotsky would see a child’s inability to solve a problem alone as incomplete information about her development. Reason (R): Vygotsky held that development is determined only by heredity, so testing is pointless.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Vygotsky argued that we must also see what the child can do with help, so A is true. R is false: he stressed social and cultural influences, not heredity alone.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1464","question":"A teacher sets up a ‘shop’ corner in Class 2 where children buy and sell with toy money, while she plays a customer who asks for change and talks through the calculation with them. Which pair of theorists would BOTH value this activity, and for which reasons?","options":["Piaget, for concrete activity; Vygotsky, for guided talk with a skilled adult","Skinner, for reinforcing correct change; Pavlov, for conditioning money to rewards","Piaget, for formal reasoning; Bruner, for using only the symbolic mode with money","Erikson, for building identity; Kohlberg, for moral reasoning about fair trade"],"answer":0,"explanation":"Handling money and goods gives concrete experience valued by Piaget, while the teacher’s participation provides scaffolding valued by Vygotsky. The other pairs do not fit the reasons given.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1465","question":"A Class 9 teacher notices that her students handle algebra well but struggle to argue a position on whether a law is fair. Piaget’s theory would suggest that:","options":["Students are still pre-operational in social science and need concrete props","Formal thinking may be used unevenly across subjects, depending on experience","Formal operations always appear in social science first, so something is wrong","Students should stop studying algebra until their social reasoning catches up"],"answer":1,"explanation":"Formal reasoning is often domain-specific and depends on familiarity, a point Piaget accepted in his later work. Unevenness does not mean a return to an earlier stage.","difficulty":"hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1466","question":"A five-year-old sees her brother Ravi wearing a lion mask and screams, ‘It’s a real lion!’ even though she watched him put it on. Piaget would explain her fear mainly by:","options":["Formal operational reasoning about what a mask might really hide","Conservation of identity, which tells her that Ravi has truly changed","Seriation, which leads her to order Ravi and the lion by size and danger","The pre-operational tendency to judge by appearance rather than reality"],"answer":3,"explanation":"Young children often judge by how things look and struggle to hold that something is still the same despite a change in appearance. Understanding identity despite such changes develops later.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1467","question":"Which classroom situation best shows Vygotsky’s idea that learning can lead development?","options":["Waiting until a child spontaneously shows readiness for reading before teaching letters","Refusing to teach fractions until every child can conserve area on Piagetian tasks","Guided practice in a new strategy that children later use alone on harder problems","Repeating last year’s work until every child performs it perfectly and fast"],"answer":2,"explanation":"Instruction within the ZPD helps children acquire abilities they then use independently, so learning pulls development forward. Waiting for readiness reflects the opposite view.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1468","question":"Consider these statements. 1. Piaget saw language as a reflection of thought. 2. Vygotsky saw language as a tool that transforms thought. 3. Bruner linked the symbolic mode closely with language. Which is/are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":3,"explanation":"All three statements correctly summarise the theorists’ positions on language and thought.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1469","question":"A Class 3 teacher asks children to estimate how many beans fill a cup, then count them in groups of ten, and compare. One child says, ‘My guess was too small because the beans were tiny.’ Which theoretical idea is best illustrated by the child’s comment?","options":["Operant extinction of her guessing after an unrewarded wrong answer","Revising an expectation after it clashes with experience (equilibration)","Classical conditioning that pairs the size of beans with counting","Imaginary audience, as she worries that others will notice her guess was wrong"],"answer":1,"explanation":"The child notices the gap between prediction and result and adjusts her thinking, the process Piaget described as moving from disequilibrium to a new equilibrium.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1470","question":"Asked about Heinz, a Class 7 student says, ‘If he loves his wife, he should steal; if he doesn’t care much for her, he shouldn’t. It’s his life and his choice; everyone looks after their own interest.’ Which stage does this most closely fit?","options":["Stage 5, because he accepts that values differ from person to person","Stage 2, because right is relative to each person’s own interests","Stage 3, because he talks about love","Stage 4, because he respects individual choice as a rule"],"answer":1,"explanation":"Stage 2 is individualistic and relativistic: each person pursues his own interests, and right depends on what one wants. Stage 5 relativism is grounded in rights and social agreements, which he never mentions.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1471","question":"Kohlberg held that each higher stage reorganises and includes the understandings of the earlier stages, so that people can understand reasoning below their own stage and tend to prefer the highest stage they understand. This property is called:","options":["Invariant sequence of stages","Universality","Hierarchical integration","Structured whole"],"answer":2,"explanation":"Hierarchical integration means higher stages incorporate and transform lower ones. Invariant sequence refers to the fixed order; structured whole to consistency of reasoning across issues.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1472","question":"Piaget distinguished two kinds of respect in children’s moral lives. Which pairing is correct?","options":["Unilateral respect for adults supports heteronomous morality; mutual respect among peers supports autonomous morality","Mutual respect for adults supports heteronomous morality; unilateral respect among peers supports autonomous morality","Both forms of respect lead only to heteronomous morality","Unilateral respect leads to autonomous morality, since children obey adults"],"answer":0,"explanation":"One-sided respect for powerful adults keeps rules external and sacred; mutual respect between equals produces cooperation and an understanding of rules as agreements.","difficulty":"very-hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1473","question":"Asked how to share sweets among children who did unequal work, a younger child says, ‘Whatever the teacher decides’; a slightly older one says, ‘Exactly the same for everyone’; an eleven-year-old says, ‘The little one who couldn’t do much should still get a fair share, and the ones who worked harder can get a bit more.’ Piaget would say the eleven-year-old shows:","options":["Obedience to adult authority as the source of fairness","Strict equality, with identical shares for all","Moral realism, judging by the consequences of acts","Equity, taking individual circumstances into account"],"answer":3,"explanation":"Piaget traced distributive justice from adult authority, to strict equality, to equity, where needs and circumstances are weighed; the eleven-year-old adjusts equality to circumstances.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1474","question":"Which statement best summarises Gilligan’s position?","options":["Women reason at higher Kohlberg stages than men, owing to their more caring nature","Care and justice are both valid moral orientations, and care reasoning develops","Moral development has no stages at all, only differences between the sexes","Moral reasoning is entirely learnt from religion and from family traditions"],"answer":1,"explanation":"Gilligan argued for a ‘different voice’ of care alongside justice and described a developmental sequence in care reasoning; she did not claim women were superior on Kohlberg’s scale.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1475","question":"A school plans to put all its ‘problem students’ from Class 8 into one separate section so they don’t disturb others. What does research on adolescent peer influence warn?","options":["Grouping them can raise problem behaviour, as they reinforce each other’s deviance","Grouping them will make them compete with one another to improve their record","It will have no effect, since peers do not really influence each other’s conduct","Only teachers influence adolescent behaviour, so grouping does not matter"],"answer":0,"explanation":"Studies of ‘deviancy training’ show that aggregating high-risk adolescents can escalate problem behaviour; mixing them with prosocial peers and giving targeted support works better.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1476","question":"Which of these is an example of a mesosystem for a Class 5 child?","options":["The child’s close day-to-day relationship with her best friend","The national curriculum framework that shapes her textbooks","The child’s father’s office, where decisions affect her family","Her parents getting to know her friends and inviting them home"],"answer":3,"explanation":"A mesosystem is a link between two of the child’s microsystems (here family and peer group). A friendship is a microsystem relation; a parent’s office is exosystem; a national framework is broader than both.","difficulty":"very-hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1477","question":"In later work, Bronfenbrenner renamed his approach the ‘bioecological model’. What did this change mainly emphasise?","options":["The child’s own traits and everyday interactions (proximal processes)","That only biology matters for development, and the environment does not","That the macrosystem is the most important layer in every child's life","That development is largely complete by the end of adolescence"],"answer":0,"explanation":"The bioecological model added the person’s characteristics and regular reciprocal interactions with people and objects (proximal processes), together with context and time, as the engines of development.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1478","question":"Assertion (A): Children who were securely attached as infants tend, on average, to be more socially competent with peers and teachers in school. Reason (R): Secure attachment gives children positive expectations of relationships and confidence in exploring and interacting.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Longitudinal studies link secure attachment with later social competence, explained by positive internal working models and confident exploration; the link is probabilistic, not destiny.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1479","question":"Studies of the Strange Situation in many countries found that:","options":["Avoidant attachment is the most common pattern everywhere in the world","Secure attachment is most common in most cultures; insecure types vary","Attachment patterns are identical in all cultures, in type and in proportion","Infants in collectivist cultures never form secure attachments to mothers"],"answer":1,"explanation":"Cross-cultural comparisons show secure attachment as the modal pattern in most samples, with variation in the frequency of avoidant and resistant types, partly reflecting childcare practices.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1480","question":"In a Class 2, parents complete most homework projects for their children, and the teacher praises the polished results. From Erikson’s viewpoint, what is the main risk?","options":["The children will develop too much autonomy and resist adult guidance","The children will become mistrustful of their parents and their help","The children lose real chances to feel competent, weakening industry","The children will move too quickly into the identity stage"],"answer":2,"explanation":"Industry grows from children’s own effort and mastery; when adults do the work, children miss the experience of competence, and praise of adult work can deepen feelings of inadequacy.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1481","question":"A three-month-old smiles and coos at almost anyone who talks to her, though she calms a little more quickly with her mother. In Bowlby’s sequence of attachment, she is most likely in the phase of:","options":["Clear-cut attachment, with marked separation protest and wariness of strangers","Goal-corrected partnership, adjusting to the mother’s plans and goals","Attachment in the making: some preference, but no separation protest","Imprinting, a fixed bond formed in a critical period after birth"],"answer":2,"explanation":"From about 6 weeks to 6–8 months infants respond more to familiar people but do not yet protest separation; clear-cut attachment with separation and stranger anxiety follows later.","difficulty":"very-hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1482","question":"The brain reaches about 90% of its adult weight by around age six, while the reproductive organs grow very little until puberty. Which principle of development does this illustrate?","options":["Development is uniform across all parts and systems of the body","Growth of the brain and body largely stops by around the age of six","Development proceeds from specific to general, as in the brain","Different parts and systems of the body develop at different rates"],"answer":3,"explanation":"Body systems follow different growth curves (as Scammon showed): neural tissue grows fastest early, reproductive tissue at puberty; development is not uniform.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1483","question":"Francis Galton found that eminent men tended to have eminent relatives and concluded that genius is mainly inherited. What is the main flaw in this reasoning?","options":["Such families also share wealth and schooling, confounding genes and environment","Eminence cannot be measured reliably, so nothing can be concluded about any family","Galton studied only identical twins, who share all their genes anyway","Genius can never run in families, as it is a purely random gift at birth"],"answer":0,"explanation":"Relatives share both genes and environment; family resemblance alone cannot separate the two, which is why twin and adoption designs were later developed.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1484","question":"The school council of a senior secondary school debates whether to change the uniform rule. Ritu says, ‘We must keep the rule; rules are rules, and changing them would create disorder.’ Sameer says, ‘The rule was made by agreement for students’ welfare; if most students and teachers agree it no longer serves them, we can change it fairly.’ Their stages are respectively:","options":["Stage 3 and Stage 4","Stage 4 and Stage 5","Stage 4 and Stage 6","Stage 5 and Stage 4"],"answer":1,"explanation":"Ritu upholds rules to maintain order (Stage 4); Sameer sees rules as revisable social contracts serving welfare (Stage 5). Stage 6 would appeal to universal principles above any agreement.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1485","question":"A Class 10 student is being targeted by abusive messages from classmates in a group chat and has become withdrawn. What should the teacher do first?","options":["Tell her to leave the group and ignore the messages, as replying feeds bullies","Read the messages aloud in class so the bullies are shamed in front of everyone","Wait to see whether it stops on its own before involving anyone else","Listen privately, ensure safety, record it and follow the anti-bullying process"],"answer":3,"explanation":"Cyberbullying needs a supportive, private response and a systematic process involving parents and the counsellor; public shaming or waiting can worsen harm.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1486","question":"Over several weeks a usually lively Class 9 student has become withdrawn, sleeps in class, has stopped eating lunch and has written ‘nothing matters’ in her notebook. What is the most appropriate teacher action?","options":["Talk with her privately and promptly involve the counsellor and her parents","Treat it as normal adolescent moodiness that will pass on its own, and do nothing","Scold her for sleeping in class and for her falling standard of work","Announce her problem to the class so that her friends can help her"],"answer":0,"explanation":"Persistent changes in sleep, appetite and mood with hopeless statements are warning signs beyond ordinary moodiness; teachers should respond with care and refer promptly while protecting privacy.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1487","question":"Which statement about Piaget’s and Kohlberg’s methods is correct?","options":["Both relied only on standard paper-and-pencil tests given to large groups of children","Piaget: story pairs and games of marbles; Kohlberg: dilemmas with probing interviews","Kohlberg observed children playing marbles; Piaget used the Heinz dilemma","Both measured moral behaviour in real situations rather than reasoning"],"answer":1,"explanation":"Piaget used clinical questioning about story pairs and watched games of marbles; Kohlberg’s dilemmas and interviews probed reasoning. Both studied judgment rather than behaviour.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1488","question":"A tribal child from a Gond village joins a residential school where the language, food and customs differ from home, and teachers dismiss her home practices as ‘backward’. What does an ecological view of development suggest?","options":["She should forget her home culture so that she can adjust quickly to school","Culture has no effect on learning, so the teachers’ remarks do not matter","Only her family matters for her development, not the residential school","Home–school conflict can harm her; school should build on her home culture"],"answer":3,"explanation":"A weak, conflicting mesosystem and a dismissive school undermine development; culturally responsive teaching that links home and school strengthens it.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1489","question":"Which of these combinations of Bronfenbrenner’s layers and examples is INCORRECT?","options":["Microsystem – the child’s class teacher","Exosystem – the school management committee whose decisions the child never sees","Macrosystem – the child’s grandparents living in the same house","Chronosystem – the child’s family moving cities when she is eight"],"answer":2,"explanation":"Grandparents living with the child are part of her microsystem; the macrosystem is the wider culture, values and laws.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1490","question":"Assertion (A): An adolescent may reason at Kohlberg’s Stage 4 in a class discussion yet follow friends into a risky prank. Reason (R): Moral action depends not only on reasoning but also on factors such as emotions, peer situations and self-control.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The gap between moral reasoning and behaviour is well documented; situational pressures, emotion and self-regulation also shape what adolescents actually do.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1491","question":"A Class 6 teacher wants to foster empathy and moral reasoning together. Which activity combines insights from Kohlberg, Gilligan and Hoffman best?","options":["Students copy moral sayings ten times each so that good values sink in","The teacher reads out a list of rules and the punishments for breaking them","Discussing a real class conflict: each person’s feelings and what is fair","Students are rewarded with sweets each time they obey the class rules"],"answer":2,"explanation":"Discussion of real dilemmas (Kohlberg), attention to relationships and care (Gilligan) and perspective-taking about others’ feelings (Hoffman’s induction) are all present only in this activity.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1492","question":"Which of these statements about attachment and later development is most accurate?","options":["An insecure attachment in infancy guarantees problems in all later relationships","Early attachment shapes later relationships, but later caring bonds can modify it","A child can form an attachment only with one person, usually the mother","Attachment has no relationship to later development once school begins"],"answer":1,"explanation":"Attachment shapes expectations, but development stays open to change; stable, warm relationships later in life can foster ‘earned security’.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1493","question":"A preschool child from a poor family attends a good anganwadi with nutritious meals, stimulating play and a caring worker, and her mother joins a self-help group that raises family income. Which statement in Bronfenbrenner’s terms is correct?","options":["Only the anganwadi, as a microsystem, affects the child directly or indirectly","The self-help group is her exosystem, helping her through the family","The self-help group is part of the child’s microsystem, like the anganwadi","Changes in family income have no developmental effect on a young child"],"answer":1,"explanation":"The child does not attend the self-help group, so it is an exosystem setting; it benefits her indirectly through the family. The anganwadi is a microsystem.","difficulty":"very-hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1494","question":"A Class 4 student consistently tries to please the teacher, saying ‘I want you to think I’m good’, while another says ‘I don’t care what people think; I only do what gets me something.’ Their Kohlberg stages are respectively:","options":["Stage 2 and Stage 3","Stage 1 and Stage 2","Stage 4 and Stage 2","Stage 3 and Stage 2"],"answer":3,"explanation":"Seeking approval as a ‘good’ child is Stage 3; acting for personal gain is Stage 2. The order in the options is the trap.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1495","question":"Eight-year-old Yash, who lives in a crowded part of Mumbai and has never kept plants or pets, can name the make and model of almost any car from a glimpse of its headlights and groups cars by their features. Gardner would most likely see this as an expression of:","options":["Naturalist intelligence, which can also apply to sorting man-made objects","Bodily-kinaesthetic intelligence, from his interest in vehicles","Logical-mathematical intelligence only, as he classifies cars by their features","Interpersonal intelligence, from talking with car-loving adults"],"answer":0,"explanation":"The core of naturalist intelligence is recognising and classifying members of a group by their features; Gardner noted that in urban settings it may be applied to things like cars or shoes.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1496","question":"Which finding is most often cited AGAINST Gardner’s claim that the intelligences are largely independent of one another?","options":["Some people show exceptional talent in only one area, such as music or mathematics","Brain damage can impair one ability while sparing others almost completely","Tests of very different abilities tend to correlate positively with each other","Different cultures value different abilities and train them differently"],"answer":2,"explanation":"The positive correlations among diverse mental tests are the main evidence for a general factor, which challenges strict independence. Savants and selective brain damage are evidence Gardner uses in his favour.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1497","question":"Asked to read a newspaper editorial claiming that ‘mobile phones are the main cause of falling marks’, Farah lists the evidence given, points out that other causes have been ignored and judges that the conclusion goes beyond the data. In Sternberg’s theory, this mainly uses:","options":["Creative intelligence","Analytical intelligence","Practical intelligence","Emotional intelligence"],"answer":1,"explanation":"Analysing, comparing and evaluating arguments is analytical (componential) intelligence; creative intelligence deals with novelty and practical intelligence with everyday adaptation.","difficulty":"moderate","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1498","question":"After a year in the science stream, Divya finds that she cannot thrive in it despite effort. With guidance, she moves to commerce, where her abilities and interests fit well and she flourishes. In Sternberg’s contextual subtheory, this is an example of:","options":["Adaptation","Shaping","Selection","Automatisation"],"answer":2,"explanation":"When neither adapting to nor reshaping an environment works, practical intelligence may choose a different environment that fits better; Sternberg calls this selection.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1499","question":"Assertion (A): According to Spearman, a person’s score on a test of musical pitch cannot be predicted fully from his level of g. Reason (R): Spearman held that, besides g, each test also draws on a specific factor (s) peculiar to that test.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"In the two-factor theory, every performance depends on g plus an s factor specific to the task; because s varies independently, g alone cannot fully predict a particular test score.","difficulty":"hard","source":"CTET · DSSSB TGT"},
  {"id":"cdp-child-development-1500","question":"Kanha, who has had very little schooling, solves unfamiliar pattern-completion puzzles quickly but knows few facts and words from textbooks. In Cattell’s terms, he shows relatively high:","options":["Crystallised intelligence","Fluid intelligence","Emotional intelligence","Level I ability"],"answer":1,"explanation":"Fluid intelligence is the capacity to reason and solve novel problems independent of learned knowledge; crystallised intelligence is the store of knowledge and vocabulary built through education and experience.","difficulty":"moderate","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1501","question":"Which term does the Rights of Persons with Disabilities Act, 2016 use for a condition marked by significant limitation in intellectual functioning and adaptive behaviour?","options":["Mental retardation","Specific learning disability","Mental illness","Intellectual disability"],"answer":3,"explanation":"The RPwD Act, 2016 uses ‘intellectual disability’, replacing the older stigmatising term ‘mental retardation’; mental illness is a different category, and specific learning disability covers difficulties such as dyslexia, not limited intellectual functioning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1502","question":"Which is a widely recognised criticism of many popular self-report questionnaires of emotional intelligence?","options":["They overlap heavily with traits like extraversion, so what new ability they measure is unclear","They are far too difficult for most adults to complete unless a trained examiner reads them aloud","They measure mainly mathematical reasoning rather than any emotional skill","Large studies have shown their scores to be identical to IQ test scores"],"answer":0,"explanation":"Self-report EI scales correlate strongly with personality measures and rely on people’s views of themselves; ability-based tests try to measure emotional skills more directly.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1503","question":"While mixing colours, a Class 2 child discovers, for herself, that yellow and blue make green. The idea is new to her though not to the world. Kaufman and Beghetto would call this kind of creativity:","options":["Big-C creativity","Pro-c creativity","Mini-c creativity","Divergent production"],"answer":2,"explanation":"Mini-c is the personally meaningful new insight of a learner; little-c is everyday creativity, Pro-c is professional-level creativity and Big-C is eminent, field-changing creativity.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1504","question":"A Class 6 teacher asks, ‘Imagine you are a drop of water evaporating from the Narmada; describe how you feel as you rise and cool,’ to help students think about the water cycle in a new way. This use of personal analogy is a technique from:","options":["Programmed instruction","Synectics","Rote learning","Classical conditioning"],"answer":1,"explanation":"Synectics (William Gordon) uses direct, personal and symbolic analogies to ‘make the strange familiar and the familiar strange’, stimulating creative thinking.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-1505","question":"Zoya, a gifted Class 5 student, attends the Class 7 mathematics period each day but stays with her own class for all other subjects. This arrangement is called:","options":["Grade skipping","Enrichment","Curriculum compacting","Subject acceleration"],"answer":3,"explanation":"Subject (or content) acceleration places a student in a higher grade for one subject only; grade skipping moves her up in all subjects, and enrichment deepens work without moving ahead.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1506","question":"Francis Galton is associated with which of the following?","options":["Studying eminent families (‘Hereditary Genius’) and popularising ‘nature and nurture’","Developing, with Théodore Simon, the first practical intelligence scale for French schools","Proposing the zone of proximal development to explain learning with adult help","Coining the term emotional intelligence in his studies of social behaviour"],"answer":0,"explanation":"Galton argued, from studies of eminent families, that ability is largely inherited and popularised the ‘nature versus nurture’ phrase; the first practical scale was Binet and Simon’s.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1507","question":"Identical twins raised together are, on average, more alike in IQ than fraternal twins raised together. Why is this taken as evidence of genetic influence?","options":["Because fraternal twins never share the same home environment as each other","Because identical twins share all their genes and fraternal twins about half, while homes are alike for both","Because identical twins usually attend better schools and receive more attention from their parents at home","Because it proves that IQ is determined entirely by the genes a child inherits"],"answer":1,"explanation":"If environments are similar for both twin types, greater similarity among identical twins points to their greater genetic similarity; it does not mean genes alone decide IQ.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1508","question":"A private school in Delhi admits children under the RTE quota for economically weaker sections but places them in a separate afternoon section with different activities. Which evaluation is correct?","options":["It is acceptable, since these children need a slower pace and separate attention","It is required by the RTE Act, which says quota admissions must be taught in a separate afternoon section","It segregates and stigmatises them, against the RTE Act’s intent that they learn with other children","It is fine as long as both sections use the same textbooks and the same teachers"],"answer":2,"explanation":"The 25% admission provision aims at social inclusion; segregating admitted children labels them and denies the shared learning the Act intends.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1509","question":"Instead of only measuring what a child can do alone, an examiner teaches a strategy during the test and records how much and how quickly the child improves with this help. This approach, associated with Reuven Feuerstein and Vygotskian ideas, is called:","options":["Static assessment","Norm-referenced testing","Summative assessment","Dynamic assessment"],"answer":3,"explanation":"Dynamic assessment measures learning potential through mediated help (the test–teach–retest idea), revealing ability that a one-time static test can underestimate, especially for disadvantaged children.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1510","question":"After a child solves a hard puzzle, Teacher X says, ‘You are so intelligent!’ while Teacher Y says, ‘You tried different strategies until one worked!’ According to Carol Dweck’s research, which is more likely when the children later meet a much harder puzzle?","options":["Children praised like Teacher X persist longer, as they feel sure of their ability","Both kinds of praise have the same effect, since any praise raises motivation","Children praised like Teacher Y persist more, linking success to effort and strategy","Neither kind of praise matters, since persistence depends only on how hard the puzzle is"],"answer":2,"explanation":"Praising fixed ability encourages a fixed mindset, so failure seems to show low intelligence; praising process supports a growth mindset and persistence after setbacks.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1511","question":"A school grades every test ‘on the curve’, so that a fixed share of students always gets the lowest grade. Which is the strongest criticism of this practice?","options":["Some students must get a low grade even if all have mastered the content, so grades show rank, not learning","It makes grading too easy for the teacher, who no longer has to read answers carefully","It gives too many high grades, since the curve always pushes everyone’s marks upwards","It cannot be used for large classes, where so many marks cannot be arranged in order"],"answer":0,"explanation":"Forced norm-referenced grading guarantees ‘failures’ regardless of actual achievement and fosters competition; criterion-referenced reporting shows what each student has learned.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1512","question":"Vygotsky found that young children’s ‘egocentric’ speech dropped sharply when they were placed among children who could not understand them (for example, deaf children or speakers of another language). What did he conclude?","options":["Egocentric speech is purely a sign of immature, self-centred thinking that fades with age","Egocentric speech is social in origin and still depends on listeners, even as it guides the child’s thinking","Children simply stop speaking when they are bored or are placed among unfamiliar classmates","Language develops independently of any social setting, through inner maturation alone"],"answer":1,"explanation":"If the speech were purely egocentric, an audience would not matter; its decline without understanding listeners showed Vygotsky that it is social speech on its way to becoming inner speech.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1513","question":"In Piaget’s theory, the emergence of language in the pre-operational stage is seen as:","options":["The single cause of all later cognitive development, including concrete operations","Unrelated to other changes in thinking, being a separate module that matures on its own","One expression of the broader symbolic function, alongside pretend play and deferred imitation","A result of reinforcement by parents, who reward and repeat the child’s first correctly spoken words"],"answer":2,"explanation":"Piaget saw language as one manifestation of the semiotic or symbolic function, the capacity to represent things mentally, which also appears in pretend play, drawing and deferred imitation.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1514","question":"Assertion (A): Behaviourist principles fully explain how children produce sentences they have never heard before. Reason (R): Behaviourists hold that language is learned through imitation and reinforcement.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"R correctly states the behaviourist view, but imitation and reinforcement cannot account for the endless new sentences children create, which was a central point in Chomsky’s critique.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1515","question":"Hindi has separate words for a father’s younger brother (chacha), a father’s elder brother (tau), a mother’s brother (mama) and a father’s sister’s husband (phupha), where English mostly says ‘uncle’. What is the most defensible conclusion?","options":["English speakers cannot understand these family relations because their language lacks the words","Language reflects distinctions a culture values and makes them easy to express, though others can still grasp them","Hindi speakers think more logically than English speakers, because their kinship vocabulary is far more precise and detailed","Vocabulary like this is fixed at birth by the LAD and does not depend on the surrounding culture"],"answer":1,"explanation":"Kinship vocabulary mirrors the social importance of these relations and keeps them salient, a weak relativity effect; English speakers can express the same relations with phrases.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1516","question":"A teacher conducts a gender audit of a Class 4 EVS textbook. Which set of checks is most relevant?","options":["The number of pages, the size of the font and the quality of the pictures in each chapter","Whether the chapters are arranged in alphabetical order and each one ends with exercises","Only the spelling of women’s names and whether their titles are written correctly","How many women and men appear, in what roles, who takes decisions and whether the language is inclusive"],"answer":3,"explanation":"A gender audit looks at representation, roles, agency and language to find stereotypes and invisibility, which the teacher can then counter in class.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1517","question":"A transgender student joins a Class 9 classroom and some classmates mock her. In the light of the Transgender Persons (Protection of Rights) Act, 2019 and inclusive education principles, the school should:","options":["Advise her to study through correspondence courses so that she avoids further trouble","Ignore the mocking, since classmates will get used to her presence over time","Ask her to dress according to the sex recorded at birth so that she draws less attention","Respect her identity, act firmly against harassment and ensure she takes part equally in all activities"],"answer":3,"explanation":"The 2019 Act prohibits discrimination against transgender persons, including in education; inclusive practice requires a safe, respectful environment, not exclusion or pressure to conform.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1518","question":"Which practice is most likely to reduce test anxiety among Class 8 students?","options":["Announcing that results will be read aloud in rank order to push everyone to work harder","Telling students that this one exam will decide their future, so they take it seriously","Clear criteria in advance, frequent low-stakes practice with feedback, and no public comparison","Increasing surprise tests with heavy penalties so that students stay fully prepared at all times"],"answer":2,"explanation":"Anxiety rises with high stakes, uncertainty and public comparison; transparent expectations and low-stakes practice reduce it and let students show what they know.","difficulty":"moderate","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1519","question":"Arpit was the top student in his village school. After moving to a highly selective residential school where nearly everyone is very able, his academic self-concept drops, though his ability has not changed. This is known as:","options":["The big-fish-little-pond effect","The Flynn effect of rising IQ","The Pygmalion or expectancy effect","Functional fixedness"],"answer":0,"explanation":"Herbert Marsh’s big-fish-little-pond effect describes how students judge their ability by comparison with classmates, so equally able students have a lower academic self-concept in high-ability schools.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1520","question":"J. P. Guilford’s 1950 presidential address to the American Psychological Association is remembered mainly because it:","options":["Introduced the first group IQ test, used to select army recruits in the First World War","Called attention to creativity as neglected and linked it to divergent thinking, unlike IQ tests","Proved through factor analysis that creativity and intelligence are really one and the same ability","Introduced the term emotional intelligence and argued it matters more than IQ for success"],"answer":1,"explanation":"Guilford argued that psychology had neglected creativity and that IQ tests mainly tap convergent thinking, setting off modern research on divergent thinking.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1521","question":"Under the RPwD Act, 2016, which of the following are measures the government is required to take to promote inclusive education? I. Conducting a survey of school-going children every five years to identify children with disabilities. II. Training and employing teachers, including teachers with disabilities, who are qualified in sign language and Braille. III. Providing books, learning materials and assistive devices free to students with benchmark disabilities up to 18 years. IV. Admitting children with disabilities only to special schools after the age of 14.","options":["I and II only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"The Act lists periodic surveys, trained teachers (including teachers with disabilities skilled in sign language and Braille) and free learning materials and devices up to 18; compulsory special schooling after 14 is not part of it.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1522","question":"Parents of a Class 9 student with severe dyslexia ask whether he can be exempted from the third language, which he finds extremely hard to read and write. Which statement is correct?","options":["No exemption is possible, since all students must study the same subjects to the same level","Exemption is allowed only if the student moves from the regular school to a special school","The RPwD Act, 2016 lists exemption from second and third language courses among permitted modifications","Exemption is possible only for students who are blind, never for those with specific learning disabilities"],"answer":2,"explanation":"Among suitable modifications in curriculum and examinations, the Act names extra time, a scribe and exemption from second and third language courses, so the request is legitimate.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1523","question":"A pre-primary teacher is observing 4-year-olds. Which behaviour is part of TYPICAL development and is NOT by itself a reason for concern about autism?","options":["Rarely pointing or showing things to share interest with others","Not responding to her name, though her hearing is normal","Talking aloud to herself while building with blocks","Lining up toys in rows for long periods and becoming upset if they are moved, with no pretend play"],"answer":2,"explanation":"Talking to oneself during play is private speech, which Vygotsky saw as a normal tool for guiding thought; weak joint attention, no response to name and rigid play without pretence are early signs worth discussing.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1524","question":"Assertion (A): A very active 4-year-old in nursery, who runs about and finds it hard to sit through a story, should be considered to have ADHD. Reason (R): For ADHD, the behaviour must be clearly beyond what is expected for the child’s developmental level and must persist across settings.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"High activity and short attention are normal at four; ADHD is considered only when behaviour is excessive for the developmental level and persistent across settings, so A is false and R is true.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1525","question":"Shreya, a Class 4 student with hearing impairment, relies on speech-reading. She has not understood a sentence the teacher has just said. What is the best thing for the teacher to do?","options":["Repeat the same sentence more loudly and slowly, exaggerating every lip movement clearly","Rephrase it in different words, since some words are much harder to read on the lips","Write the whole lesson on the board and stop speaking for the rest of the period","Ask another student to explain it to her later, so the lesson is not interrupted"],"answer":1,"explanation":"Many words look alike or are nearly invisible on the lips, so repeating the same words often fails again; rephrasing offers new visual cues, while extra volume and exaggerated lip movements actually distort speech-reading.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1526","question":"Govind, a blind Class 2 student, often rocks his body and presses his eyes when he is idle in class. What is the most appropriate response?","options":["Scolding him each time it happens so that he learns the habit is not acceptable","Seating him away from others so that the behaviour is not copied by classmates","Ignoring it completely, since such mannerisms in blind children are permanent and cannot be changed","Keeping him engaged with tactile and auditory tasks and gently teaching other uses for his hands"],"answer":3,"explanation":"Such mannerisms often arise from lack of stimulation; active engagement and gentle redirection work better than punishment, and eye-pressing should be reduced because it can harm the eyes.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1527","question":"Arun, who has intellectual disability, throws his book whenever a reading task begins. Each time, he is sent out of the room. The teacher’s records show the throwing has increased. What is the best explanation and response?","options":["It lets him escape a task that is too hard; adjust the task, teach him to ask for a break, stop sending him out","He is aggressive by nature, so he should be suspended until his behaviour clearly improves","He wants classmates’ attention, so the whole class should be told to ignore him completely","He dislikes the teacher, so he should be moved to another section with a different teacher"],"answer":0,"explanation":"Looking at what happens before and after a behaviour shows its function; being sent out rewards escape, so the behaviour grows. Matching the task to his level and teaching a replacement behaviour removes the need for it.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1528","question":"A Class 5 teacher regularly uses Aryan, a gifted student, as an ‘assistant teacher’ to explain lessons to weaker classmates whenever he finishes early. Aryan now seems bored and restless. What is the main concern?","options":["Peer tutoring should never be used in an inclusive class, as it embarrasses weaker students","Aryan should be told to finish his work more slowly so that he does not get restless","Occasional tutoring is fine, but he also needs challenging work at his level, not only a helper’s role","There is no concern, since teaching weaker classmates is always the best form of enrichment for the gifted"],"answer":2,"explanation":"Gifted students have a right to learn something new too; tutoring can be valuable at times, but as a permanent role it replaces their own growth.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1529","question":"A Class 2 teacher plans an activity, ‘Tell us about your mother and father and what they do’. Two children live in a children’s home and one lives with her grandmother. Which change makes the activity most inclusive?","options":["Excusing those three children from the activity so that they are not made to feel sad","Changing it to ‘Tell us about the people who care for you’, so every child’s family is included","Asking those three children to describe an imaginary family instead, so that they can still take part","Keeping the activity as it is, since most children in the class live with both parents"],"answer":1,"explanation":"Activities that assume one family type exclude children in other situations; a broader framing lets every child take part without being singled out.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1530","question":"When Rohan, a Class 3 boy, cries after falling in the playground, his teacher says, ‘Boys don’t cry, be a man.’ What is the main problem with this response?","options":["It reinforces a gender stereotype that harms boys too, teaching them to hide their feelings","There is no problem, since such words toughen boys up for life outside the school","The teacher should have said the same to girls too, so that all children are treated equally","The teacher should instead have ignored the boy until he stopped crying by himself"],"answer":0,"explanation":"Gender stereotypes restrict boys as well as girls; telling boys not to show feelings discourages healthy emotional expression.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1531","question":"An English-medium school fines children who speak their mother tongue on the campus. From a child-development point of view, what is the most serious problem?","options":["The fines are too small to change behaviour, so a stricter penalty is needed to make the rule work","Parents may object to paying the fines, which can damage relations between the school and families","It is fine, since full immersion with no use of the home language is the only way to learn English","It signals that their home language is inferior, silences them, and ignores how a strong first language aids a second"],"answer":3,"explanation":"Punishing home languages damages self-esteem and silences children, and first-language strength actually aids second-language learning; multilingualism should be treated as a resource.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1532","question":"Tenzing, a Class 6 student from Sikkim, is repeatedly called ‘Chinese’ by classmates in a Delhi school. What should the teacher do?","options":["Tell Tenzing to ignore it, since the classmates are only joking and mean no real harm","Stop the name-calling, make clear racist remarks are unacceptable, and teach the class about India’s diversity","Seat Tenzing with other students from the North-East so that he feels more at home in class","Wait until the parents complain, since remarks among students are outside the teacher’s role"],"answer":1,"explanation":"Racial and regional slurs are discrimination that the teacher must address directly, along with building awareness of India's diversity; ignoring or segregating places the burden on the victim.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1533","question":"A teacher realises that, for the same quality of answer, she tends to give higher marks to students whose families she sees as ‘well-educated’. Which step best reduces this bias?","options":["Marking students from poorer families more leniently to balance out the bias","Asking students to write their parents’ occupation on the answer sheet for reference","Marking with a clear rubric and, where possible, without seeing the student’s name","Letting the class monitor do the marking, since students do not have such biases"],"answer":2,"explanation":"Expectation bias in marking is reduced by fixed criteria applied blind to identity; lenient marking for one group is another form of bias.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1534","question":"Which phrase about a Class 5 student reflects respectful, person-first language?","options":["‘She is a student who uses a wheelchair.’","‘She is wheelchair-bound and needs help.’","‘She suffers from a physical disability.’","‘She is a handicapped student in my class.’"],"answer":0,"explanation":"Person-first language puts the child before the condition and describes it neutrally; ‘bound’, ‘suffers’ and ‘handicapped’ suggest tragedy or limitation.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1535","question":"Assertion (A): Letting a Class 7 student with dyslexia listen to an audiobook of the prescribed story for the literature lesson is a form of cheating. Reason (R): The goals of the literature lesson are understanding and appreciating the story, not decoding print.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Since the goal is comprehension and appreciation, an audiobook removes the decoding barrier while keeping the goal; it is an accommodation, not cheating, so A is false and R is true.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1536","question":"Amit, a Class 6 student with dysgraphia, writes correct scientific explanations but with many spelling errors and untidy work. In the science test, how should his answers be marked?","options":["Deducting heavily for spelling, since correct spelling is part of every subject","Marking his scientific content against the science criteria and supporting spelling separately","Giving him full marks for every answer so that he is not discouraged by his writing difficulty","Asking him to rewrite the whole test neatly before it is marked by the teacher"],"answer":1,"explanation":"Assessment should measure the intended learning; penalising a disability-related writing difficulty in a science test measures the barrier, not his science knowledge.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1537","question":"Which classroom job is likely to suit Chirag, a Class 3 child with ADHD, best?","options":["Distributing and collecting notebooks, which lets him move with a purpose","Copying the timetable neatly into every notebook to practise careful work","Sitting at the door as ‘silence monitor’ to learn to control his movements","Keeping a written record of late-comers all day to build responsibility"],"answer":0,"explanation":"Purposeful movement channels restlessness constructively and builds responsibility; long sedentary or detail-heavy jobs work against his difficulties.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1538","question":"In group projects, Mira, an autistic Class 6 student, either takes over or withdraws because she is unsure what to do. Which support is most helpful?","options":["Giving her a card that sets out her role, the task steps and when each part is due","Telling the group to manage her as best they can, as it builds their patience","Letting her work alone on every project so that she never feels stressed in a group","Putting her in the group with the most talkative students to draw her out of herself"],"answer":0,"explanation":"Unclear social expectations are hard for many autistic learners; an explicit role and steps make group work predictable and let her contribute.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1539","question":"A school has both a class teacher and a resource teacher for children with disabilities. Which way of working is most inclusive?","options":["The resource teacher takes the children out of class for all subjects, giving them focused one-to-one help","The resource teacher works only with the parents, guiding them on support at home","The class teacher sends the children to the resource room whenever they fall behind","Both teachers plan and teach together in the regular class, with brief pull-outs only if needed"],"answer":3,"explanation":"Co-teaching keeps children learning with peers while bringing specialist expertise into the regular class; routine pull-out recreates segregation within the school.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1540","question":"Riya, a Class 1 child with a language delay, points and says, ‘Ball fall.’ Which teacher response best supports her language development?","options":["‘No, say it properly.’","Ignoring it until she speaks in a full sentence","‘Yes, the ball fell down. Where did it go?’","‘Ball fall? That is wrong.’"],"answer":2,"explanation":"Expanding the child's words into a correct, slightly fuller model, without criticism, and continuing the conversation, supports language growth; correction and ignoring discourage her from speaking.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1541","question":"Assertion (A): A child with a cochlear implant hears exactly like her hearing classmates and needs no support in class. Reason (R): A cochlear implant gives access to sound, but listening remains effortful, especially in noisy rooms.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Implants do not create typical hearing; noise, distance and fatigue still matter, so quiet rooms, visual support and good seating remain important. A is false, R is true.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1542","question":"During a brainstorming session on ‘how to reduce plastic in our school’, which teacher behaviour best encourages creative thinking?","options":["Correcting every unusual idea immediately so that no time is wasted on poor ones","Recording all ideas without judging them, and evaluating only after many have been collected","Asking only the toppers for ideas, since they are the most likely to give good ones","Giving the class the textbook answer before they begin, so they have a correct model to follow"],"answer":1,"explanation":"Separating idea generation from evaluation allows fluency and originality to grow; early criticism makes students stick to safe, conventional answers.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1543","question":"To ‘avoid crowding’, a school gives its children with disabilities a separate lunch break, 20 minutes before everyone else. What is the main problem with this arrangement?","options":["Twenty minutes is too short for lunch, so the break should be made longer for them","It is subtle segregation that cuts these children off from social time with peers, central to inclusion","It is unfair to the other children, who must then wait longer and have less time to eat and play together","There is no problem, since all children still get lunch and the crowding is avoided"],"answer":1,"explanation":"Inclusion covers social life, not just lessons; separate break times deny friendship and belonging, so needs such as crowding should be handled within shared time.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1544","question":"For maths word problems, a Class 4 teacher reads each problem aloud, shows a picture of the situation and uses simple, consistent wording. Which statement about this practice is most accurate?","options":["It applies UDL’s representation principle, helping many, such as learners with dyslexia or new to the language","It helps only children with dyslexia, so it should be limited to them to avoid slowing down the other learners","It makes the problems easier and therefore lowers the standard expected in Class 4 mathematics","It applies UDL’s engagement principle, since pictures make maths more fun for the class"],"answer":0,"explanation":"Presenting content in several forms reduces barriers of reading and language without changing the maths being assessed, which is UDL's representation principle and benefits many learners.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1545","question":"A Class 7 teacher sets homework that needs internet searches and coloured printouts. Several first-generation learners from low-income homes regularly fail to submit it. What is the best response?","options":["Penalising late submissions so that all students learn to take their homework seriously","Asking these students to use a cyber café or a neighbour’s phone to complete the work","Redesigning homework so all can do it with resources at home, with school access for any tech tasks","Excusing these students from all homework for the year, since their homes cannot support such work at all"],"answer":2,"explanation":"Homework that depends on resources some homes lack measures access, not learning; designing for available resources and offering school access keeps expectations equal and fair.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1546","question":"Many students in Ms. Kaur’s Class 6 section do not submit homework. If she tackles this through action research, her first step should be to:","options":["Frame a broad hypothesis about homework habits in all Indian schools and then test it","Punish the defaulters firmly so that the problem stops at once and others take note","Identify and define the problem precisely (who, which homework, how often) using her class data","Read international studies on homework and apply their conclusions directly to her own Class 6 section"],"answer":2,"explanation":"Action research starts by identifying and sharply defining a problem in the practitioner’s own setting; broad hypotheses and borrowed conclusions come before the problem is even understood.","difficulty":"moderate","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1547","question":"Which is the best example of an action hypothesis?","options":["‘If I set homework linked to daily life and give brief feedback next day, submission in my Class 6 will rise.’","‘Homework is useful for children and should be given regularly in every class at school.’","‘Children from poor families do less homework than other children all over India.’","‘There is a relationship between the amount of homework and children’s intelligence.’"],"answer":0,"explanation":"An action hypothesis names a specific action the teacher will take and the expected improvement in her own situation, so it can be tried and checked; the others are vague beliefs or general research questions.","difficulty":"hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1548","question":"Which feature distinguishes action research from fundamental research?","options":["It uses large random samples so that its results can be generalised to all schools","It is carried out mainly by university experts who visit schools to collect data for their own studies","It aims to build universal theories of learning that hold across all classrooms","It is done by practitioners to improve their own practice in one setting, not to generalise widely"],"answer":3,"explanation":"Fundamental research seeks generalisable theory through rigorous sampling; action research is practitioner-led, local and aimed at immediate improvement.","difficulty":"moderate","source":"CTET · State TET"},
  {"id":"cdp-child-development-1549","question":"Arrange these steps of action research in order: P. Carry out the planned action. Q. Identify and define the problem. R. Analyse probable causes and frame action hypotheses. S. Evaluate the results and reflect, revising the plan if needed.","options":["Q, P, R, S","Q, R, P, S","R, Q, P, S","Q, R, S, P"],"answer":1,"explanation":"The problem is identified first, causes are analysed and action hypotheses framed, the action is carried out, and finally its effect is evaluated, which may start a new cycle.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1550","question":"After trying peer reading for six weeks, Mr. Das finds only partial improvement in his Class 4 students’ reading fluency. Within action research, he should:","options":["End the study and declare the idea a failure for all schools","Publish the result as a general law of reading","Reflect on the evidence, modify the plan and begin another cycle","Give up reading practice altogether and try a different subject instead"],"answer":2,"explanation":"Action research is cyclical (plan, act, observe, reflect); partial success is evidence for revising the action in the next cycle, not a final verdict.","difficulty":"hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-1551","question":"Assertion (A): Action research is usually not meant to produce generalisations valid for all schools. Reason (R): It is carried out with a small, specific group in a particular context, often without random sampling or control of variables.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because action research studies one teacher’s class without random sampling or controls, its findings serve that setting; this is exactly why it does not aim at wide generalisation.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1552","question":"Which pairing about the origins of action research is correct?","options":["Kurt Lewin brought action research into school education; Stephen Corey coined the term","Kurt Lewin coined ‘action research’; Stephen M. Corey popularised it in education","B. F. Skinner coined the term; Jean Piaget later applied it to schools","John Dewey coined the term in the 1990s; Corey then applied it to classrooms"],"answer":1,"explanation":"The social psychologist Kurt Lewin introduced action research in the 1940s; Stephen M. Corey popularised it among teachers in the 1950s. Option A swaps their roles.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1553","question":"While explaining fractions with a drawing of a roti, a teacher notices puzzled faces and immediately switches to folding paper strips. That evening she writes in her diary about why the first explanation failed. These are, respectively:","options":["Reflection-on-action and reflection-in-action","Reflection-for-action and reflection-on-action","Reflection-in-action and reflection-on-action","Routine action and reflection-for-action"],"answer":2,"explanation":"In Donald Schön’s terms, adjusting during the lesson is reflection-in-action; thinking back over it afterwards is reflection-on-action.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1554","question":"Before starting a new unit, a teacher reviews last year’s notes on where children struggled and plans activities to avoid those problems. This is best called:","options":["Reflection-for-action","Reflection-in-action","Routine, habitual action","Summative evaluation"],"answer":0,"explanation":"Reflection-for-action looks ahead, using past reflection to plan future teaching; reflection-in-action happens during teaching itself.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1555","question":"To examine her teaching critically, a teacher recalls her own experiences as a learner, collects anonymous feedback from students, invites a colleague to observe her, and reads research on the topic. She is using:","options":["Kolb’s four-stage cycle of experiential learning","Bloom’s taxonomy of educational objectives","Gagné’s nine events of instruction in sequence","Brookfield’s four lenses of critical reflection"],"answer":3,"explanation":"Stephen Brookfield’s four lenses are the autobiographical lens, students’ eyes, colleagues’ perceptions and theoretical literature; using all four checks a teacher’s assumptions.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1556","question":"A teacher tries group work, notices that several students sit idle, concludes that groups need clearly assigned roles, and next day tries assigning roles. In Kolb’s experiential learning cycle, ‘concluding that groups need clearly assigned roles’ is the stage of:","options":["Concrete experience","Abstract conceptualisation","Reflective observation","Active experimentation"],"answer":1,"explanation":"Kolb’s cycle runs from concrete experience (trying group work) to reflective observation (noticing idle students), abstract conceptualisation (forming the general idea about roles) and active experimentation (trying roles).","difficulty":"hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1557","question":"A new teacher keeps a reflective journal. For it to support her professional growth, most entries should:","options":["List the topics covered each day, so that a full record of her teaching is kept","Record complaints about students and the administration to release her stress","Describe key classroom events, analyse why they happened and consider what to try next","Copy lesson plans from the teachers’ guide so that her daily planning becomes faster and neater"],"answer":2,"explanation":"A reflective journal is useful when it moves from description to analysis to planning; mere logs, complaints or copied plans involve no reflection.","difficulty":"moderate","source":"CTET · State TET"},
  {"id":"cdp-child-development-1558","question":"A teacher asks herself, ‘Why do the children from the nearby basti always sit at the back and rarely speak? Do my practices or the school’s norms silence them?’ In Van Manen’s levels of reflection, this is:","options":["Critical reflection, which examines equity, power and justice in practice","Technical reflection about efficient means to reach fixed classroom goals","Not reflection at all, since it concerns social issues rather than teaching","Reflection-in-action, since she is adjusting the lesson as she teaches"],"answer":0,"explanation":"Van Manen distinguishes technical, practical and critical reflection; questioning how practices and norms affect fairness for marginalised children is the critical level.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1559","question":"Ms. Rao is doing action research on improving girls’ participation in her Class 7 science discussions. Which data source is LEAST appropriate for her study?","options":["A tally of who speaks in each discussion over four weeks","Short interviews with some girls about what holds them back in class","Her own observation notes after each class","National data on women’s enrolment in university science courses"],"answer":3,"explanation":"Action research needs evidence from the teacher’s own setting; national university data says nothing about what is happening in her class or whether her action works.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1560","question":"Which of these statements about action research are correct? I. It can be collaborative, involving several teachers of a school. II. It needs a control group and random sampling to be valid. III. Its success is judged by improvement in the practitioner’s own situation. IV. It treats the teacher as a researcher, not just a consumer of research.","options":["I and II only","II and III only","I, III and IV only","I, II, III and IV"],"answer":2,"explanation":"Action research may be individual or collaborative, aims at local improvement and positions teachers as researchers; it does not require control groups or random sampling, so II is false.","difficulty":"very-hard","source":"CTET · DSSSB TGT"},
  {"id":"cdp-child-development-1561","question":"The idea of the ‘teacher as researcher’, associated with Lawrence Stenhouse, holds that:","options":["Only university experts should research teaching, and teachers should simply apply their findings","Teachers should systematically study their own classrooms to test and improve curriculum ideas","Teachers should avoid changing their practice once they have completed their training","Research has no place in schools, where the teacher’s task is only to teach the syllabus"],"answer":1,"explanation":"Stenhouse argued that curriculum proposals are hypotheses that teachers should test in their own classrooms; this underlies classroom-based action research.","difficulty":"hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1562","question":"Two Class 4 teachers observe each other’s mathematics lessons and discuss what they noticed, without giving any grades. This practice mainly supports:","options":["Collaborative reflection and professional learning","Inspection of lessons leading to disciplinary action","Ranking of teachers for the annual school report","Summative evaluation of teachers for promotion"],"answer":0,"explanation":"Non-judgemental peer observation gives each teacher a colleague’s lens on her practice; once grades are attached it becomes inspection and teachers stop being open.","difficulty":"moderate","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1563","question":"Assertion (A): A teacher who has used the same methods for 20 years necessarily has 20 years of reflective experience. Reason (R): Experience becomes learning only when it is reflected upon and used to change practice.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"By R’s own logic, unexamined repetition may amount to one year’s experience repeated twenty times; years of service do not by themselves make reflective practice, so A is false.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1564","question":"Which question best shows reflective teaching rather than self-justification?","options":["‘Why can’t these students ever pay attention like last year’s batch did?’","‘I taught it well; they just didn’t study at home as I told them to.’","‘What in my lesson made it hard for some to follow, and what is my evidence?’","‘How can I finish the syllabus faster so that more time is left for revision?’"],"answer":2,"explanation":"Reflection examines one’s own practice using evidence; blaming students or focusing only on coverage avoids looking at the teaching itself.","difficulty":"moderate","source":"CTET · State TET"},
  {"id":"cdp-child-development-1565","question":"Which is the most suitable problem for an action research project by a Class 3 teacher?","options":["The effect of socio-economic status on the IQ of children across India","How to improve the reading of the six children in my class who confuse ‘b’ and ‘d’","A history of primary education policy in India since independence","A comparison of the school systems of India and Finland in the 2020s"],"answer":1,"explanation":"Action research problems are specific, local, within the teacher’s control and aimed at immediate improvement; the others are large-scale or historical research topics.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1566","question":"At the end of each week a teacher hands out anonymous slips asking for ‘one thing that helped me and one thing that confused me’. This is mainly a tool for:","options":["Seeing her teaching through students’ eyes to inform her reflection","Grading the students on how well they have understood the week’s work","Identifying and disciplining students who complain about her lessons","Ranking her teaching against her colleagues’ for the annual review"],"answer":0,"explanation":"Anonymous student feedback gives the ‘students’ eyes’ lens on teaching and helps the teacher check her assumptions about what is working.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1567","question":"Mr. Iqbal uses maths games for four weeks, and his Class 5’s test average rises from 52 to 61. Before concluding that the games caused the improvement, a reflective teacher-researcher would MOST need to consider that:","options":["Students’ own feedback on whether they enjoyed the games is the best proof of effect","Four weeks is too short, so only a full year of games could show a real effect","The gain should be checked separately for high and low scorers to see who gained","Other factors, such as an easier second test or extra revision, may explain the rise"],"answer":3,"explanation":"A causal claim needs alternative explanations ruled out, such as test difficulty or extra revision. Running the games longer or splitting the gains by group still leaves those rival causes unexamined, and enjoyment is not evidence of learning.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1568","question":"In an action research project with her own students, which practice is ethically appropriate?","options":["Publishing students’ names and scores without permission","Deliberately withholding help from a ‘control’ group of weak students for a whole term to compare","Informing students and parents, keeping data confidential and ensuring no child is disadvantaged","Recording the class on video and sharing it on social media to showcase the project"],"answer":2,"explanation":"Research with children requires informed consent, confidentiality and no harm; denying weak students help for the sake of a comparison is unethical in a teacher’s own class.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1569","question":"NCF 2005 and NEP 2020 both expect teachers to be reflective practitioners. Which is the best example?","options":["Following the textbook page by page every year, since the board has approved it and parents expect it","Revising a lesson on ‘our food’ after noticing it left out tribal students’ foods, and inviting them to share","Using the same question paper every year so that standards stay consistent","Avoiding any change in her methods unless the principal or a visiting inspector specifically instructs her to"],"answer":1,"explanation":"Reflective practice means noticing how one’s teaching affects particular learners and changing it; here the teacher spots an exclusion and makes the lesson inclusive.","difficulty":"hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-1570","question":"A teacher spends a term studying one child with severe reading difficulty in depth, examining family background, health, school history and work samples, to understand the child’s problem. This is primarily a:","options":["Survey of reading levels","Cycle of action research","Experimental study with a control group","Case study"],"answer":3,"explanation":"An in-depth study of a single individual from many sources is a case study; action research would centre on trying and evaluating a change in practice.","difficulty":"hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1571","question":"In a Class 6 classroom in Uttar Pradesh with 55 students of widely varying levels, which plan best applies Vygotsky’s zone of proximal development?","options":["Tasks at two or three levels, groups based on what students can do with help, and trained peer helpers","Teach the whole class from the textbook at one pace and test everyone together, so that no one is left out","Seat the weakest students at the back so the lesson can move quickly for the majority","Let each student work alone on the same worksheet without help, to build independence"],"answer":0,"explanation":"Large classes still allow for differences in ZPDs through tiered tasks, grouping by assisted performance and peer support. Uniform, unaided work ignores those differences.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1572","question":"NEP 2020’s foundational stage (ages 3 to 8) stresses play, activity and discovery-based learning. Which feature of children’s thinking, as described by Piaget, best supports this emphasis?","options":["They reason mainly through abstract propositions, so discovery lets them test their hypotheses systematically","They learn best from long lectures, so play is needed only as a reward afterwards","They are mostly pre-operational or early concrete operational, learning through action, play and the concrete","They have already mastered all forms of conservation, so they are ready for formal rules"],"answer":2,"explanation":"Ages 3 to 8 cover the pre-operational period and the start of concrete operations, when learning is grounded in action and play. Abstract or lecture-based teaching does not fit this thinking.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1573","question":"In a pre-primary class, four children sit together, each talking about his own drawing, but no one listens or responds to the others. Piaget called this form of speech:","options":["Inner speech","Socialised speech","Private speech used for self-regulation","Collective monologue"],"answer":3,"explanation":"Collective monologue is egocentric speech in a group, where children talk in each other’s presence without real exchange. ‘Private speech used for self-regulation’ is Vygotsky’s interpretation of such talk in other contexts.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1574","question":"How many of these did Piaget describe as forms of egocentric speech in young children? I. Repetition of words and syllables for the pleasure of it. II. Monologue, talking to oneself while acting. III. Collective monologue, talking in a group without real exchange. IV. Adapted information, telling a listener something taking his viewpoint into account.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Piaget classified repetition, monologue and collective monologue as egocentric speech. Adapted information, which considers the listener, is socialised speech.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1575","question":"Vygotsky distinguished technical tools, which act on objects, from psychological tools, which act on the mind. Which of the following is a psychological tool?","options":["A plough for tilling soil","A hammer for driving nails","A system of written numerals","A cooking pot for boiling rice"],"answer":2,"explanation":"Number systems, writing, maps and mnemonics are psychological tools that organise thinking. Ploughs and hammers change the physical world.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1576","question":"A Class 7 maths teacher first shows a fully worked example, then gives examples with the last step blank, then with the last two steps blank, and finally problems with no steps shown. This ‘fading’ technique is an application of:","options":["Piaget’s horizontal décalage across tasks","Scaffolding that is gradually withdrawn","Classical conditioning of correct steps","Bruner’s narrative mode of thought"],"answer":1,"explanation":"Fading worked examples moves responsibility from teacher to learner step by step, the essence of scaffolding within the ZPD.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1577","question":"Asked where they would put a third eye if they could have one, nine-year-olds mostly said ‘in the middle of my forehead’, while many older adolescents suggested places such as the back of the head or the palm, with reasons like ‘to see behind me’. The difference best illustrates:","options":["Formal operational reasoning about hypothetical possibilities","Pre-operational animism persisting into the teenage years","Conservation of number in the concrete stage","Vygotsky’s private speech being used aloud to guide problem-solving"],"answer":0,"explanation":"Concrete operational children stay close to the familiar arrangement, while formal operational thinkers explore unusual possibilities and justify them. The task is hypothetical, so it reveals formal reasoning.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1578","question":"Consider these statements about play. 1. Piaget saw symbolic play mainly as a reflection and practice of the child’s current level of thinking. 2. Vygotsky saw pretend play as creating a zone of proximal development in which children act beyond their usual level. 3. Both Piaget and Vygotsky regarded play as unimportant for cognitive development. Which is/are correct?","options":["1 and 2 only","3 only","1 only","2 and 3 only"],"answer":0,"explanation":"Piaget treated play as assimilation that consolidates existing schemas, while Vygotsky saw it as leading development, for example through self-imposed rules. Both valued play, so statement 3 is false.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1579","question":"Bruner wrote that knowing is a process, not a product. For a Class 8 science teacher, this most directly implies that she should:","options":["Make students memorise the final conclusions of each chapter, since these are what the board exam tests","Engage students in methods of inquiry such as questioning, hypothesising and checking evidence","Cover as many facts as possible in the syllabus, as broad knowledge is the base of science","Replace experiments with notes dictated in class, which save time and avoid confusion"],"answer":1,"explanation":"Bruner wanted students to take part in the process of knowledge-getting, thinking as a scientist or historian would, rather than storing finished conclusions.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1580","question":"How many of these benefits did Bruner claim for learning by discovery? I. It increases intellectual potency, the ability to solve problems. II. It shifts motivation from extrinsic to intrinsic rewards. III. It teaches the methods (heuristics) of discovery. IV. It helps learners remember what they have found.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"In ‘The Act of Discovery’ Bruner listed all four: intellectual potency, intrinsic motivation, learning the heuristics of discovery, and better memory for what is discovered.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1581","question":"Assertion (A): A Piagetian teacher would try to match instruction to the child’s current stage of thinking. Reason (R): Bruner held that readiness can be nurtured by presenting ideas in an appropriate form.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements are accurate, but R describes Bruner’s view and does not explain why a Piagetian teacher matches instruction to stages; that follows from Piaget’s own idea that learning depends on development.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1582","question":"A 20-month-old watches her father put a ball into his closed hand, move the hand inside a basket, and bring the hand out empty. She immediately searches in the basket. Piaget would say she can now:","options":["Follow only the visible displacements of an object she can see","Show secondary circular reactions with objects","Mentally represent invisible displacements of an object","Conserve volume when liquid is poured between containers"],"answer":2,"explanation":"Inferring where an object went when its movement was hidden requires mental representation, the final achievement of object permanence at about 18 to 24 months.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1583","question":"A nine-month-old pushes a pillow aside in order to grab the toy hidden behind it. Piaget regarded this behaviour as a landmark of substage 4 because it shows:","options":["A primary circular reaction, repeating a chance action centred on her own body","Intentional, means-end behaviour, using one action to achieve another","Symbolic play, using the pillow to stand for something else","Deferred imitation of an action she had seen earlier"],"answer":1,"explanation":"Coordinating schemas so that one (pushing) serves another (grasping) is the first clear intentional, means-end behaviour, appearing at about 8 to 12 months.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1584","question":"Which statement about Piaget’s concept of egocentrism is correct?","options":["It means the same as selfishness, so it should be corrected through moral instruction","It disappears completely by about age four, once children begin playing and talking with their peers","It applies only to adults who have rigid opinions and refuse to consider others","It is a cognitive difficulty in separating one’s own perspective from others’, taking different forms across stages"],"answer":3,"explanation":"Egocentrism is a cognitive limitation, not a moral fault. It appears in infancy, in the pre-operational stage and, as Elkind described, in a new form in adolescence.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1585","question":"Two Class 2 children of the same independent reading level are in a teacher’s guided reading group. Which teacher behaviour is LEAST consistent with scaffolding?","options":["Asking a child to predict what will happen next before turning the page","Reading every hard word aloud before the children try, every time, all year","Pointing to the first letter as a cue when a child gets stuck on a word","Gradually letting the children take over more of the discussion as they grow confident"],"answer":1,"explanation":"Help that is never reduced keeps children dependent and prevents them from taking over the task. Scaffolding responds to need and is faded over time.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1586","question":"A Class 3 teacher finds that a child explains clearly in Bhojpuri how she divided 12 mangoes among 4 friends, but cannot answer the same question in a written Hindi worksheet. A teacher drawing on Vygotsky and Bruner would conclude that:","options":["The child has no real understanding of division, only memorised talk, and must start again","The child should be held back a class until her written Hindi improves","The child has the concept but needs help linking it to the symbols and language of school","The child is still in the sensorimotor stage and cannot use symbols yet"],"answer":2,"explanation":"Her oral, home-language explanation shows understanding; the gap lies in moving to written, school forms. Scaffolding that connects familiar language and action to new symbols is the remedy.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1587","question":"Which experimental finding would MOST strongly support Vygotsky over Piaget?","options":["Children given targeted help on a task beyond them later do it alone sooner than children left to explore","Children in every culture studied pass through the sensorimotor stage before the pre-operational stage begins","Infants in many cultures show the A-not-B error at around 8 to 12 months","Most adolescents use formal reasoning in all subjects once they reach about 12"],"answer":0,"explanation":"Faster independent mastery after assisted learning supports Vygotsky’s claim that instruction within the ZPD leads development. The second and third findings fit Piaget.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1588","question":"A Class 10 student argues, ‘If a law is unjust, citizens may have a duty to oppose it peacefully,’ citing examples from the freedom movement. Which Piagetian ability is she mainly using?","options":["Seriation, ordering historical events correctly along a timeline","Conservation of quantity across transformations","Reasoning about abstract principles and applying them to cases","Object permanence, knowing things exist when unseen"],"answer":2,"explanation":"Reasoning about abstract ideas like justice and duty, and testing them against cases, belongs to formal operations. Seriation and conservation are concrete operational skills.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1589","question":"How many of these statements about Vygotsky’s internalisation are correct? I. It is a process by which social, external activity becomes inner mental activity. II. It involves the child simply copying external activity without transforming it. III. It happens without any role for language. IV. Inner speech is a transitional step between social speech and private speech.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. Internalisation transforms rather than copies, language is central to it, and the sequence runs social speech → private speech → inner speech, so private speech (not inner speech) is the transitional step.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1590","question":"In a Class 4 group task, a child who can already conserve area and a child who cannot are asked to agree on which of two equal fields has more grass. After arguing, the non-conserving child begins to justify equality. Which explanation would Piaget most likely give?","options":["The child simply copied the friend to avoid further argument, with no real change in her own underlying thinking","The disagreement created cognitive conflict that pushed the child to coordinate dimensions and re-equilibrate","The child was rewarded by the friend’s approval for agreeing, which reinforced the answer","The child had already conserved area but was hiding it until a friend agreed with her"],"answer":1,"explanation":"Piaget saw peer disagreement as a source of cognitive conflict that leads to restructuring. If the child gives her own justification, the change is more than copying.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1591","question":"Which classroom statement contradicts Piaget’s theory?","options":["‘Children’s mistakes tell me a lot about how they are thinking.’","‘Hands-on experience with real objects is especially valuable for young learners.’","‘Children learn by actively constructing knowledge for themselves.’","‘If I explain clearly enough, any Class 1 child can follow algebraic proofs.’"],"answer":3,"explanation":"Piaget held that what a child can understand is limited by her current cognitive structures; clear explanation alone cannot produce formal reasoning in a pre-operational child.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1592","question":"Consider these statements about Vygotsky’s view of concepts. 1. Everyday (spontaneous) concepts develop from concrete experience upward towards awareness. 2. Scientific concepts develop from definitions downward towards concrete experience. 3. The two kinds of concepts develop completely separately and never influence each other. Which is/are correct?","options":["1 and 2 only","1 only","3 only","1, 2 and 3"],"answer":0,"explanation":"Vygotsky described spontaneous concepts as growing ‘upward’ and scientific concepts ‘downward’, meeting and enriching each other. Statement 3 contradicts this interaction.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1593","question":"A Class 5 teacher in Odisha plans a unit on maps: children first walk around the school and mark landmarks on a rough sketch, then use a printed map of the school, and finally read a map of their district using a key and scale. Which statement best describes the plan?","options":["It moves through Bruner’s enactive, iconic and symbolic modes, suiting concrete operational learners","It skips the iconic mode entirely, going straight from walking around the school to the district map","It is unsuitable for Class 5, because reading any kind of map needs formal operational thinking","It follows Skinner’s schedules of reinforcement, rewarding each correct landmark"],"answer":0,"explanation":"Walking and marking is enactive, the printed map iconic, and the scale and key symbolic. Map reading of familiar places is within reach of concrete operational children.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1594","question":"Assertion (A): Piaget’s stage descriptions should not be used to label a child as ‘incapable’ of a task because of her age. Reason (R): Research shows that performance depends on familiarity with materials, task demands and support, and that ages for stages vary.","options":["A is false, but R is true","A is true, but R is false","Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"Because performance varies with task and context, age-based stage labels can underestimate children. R gives the reason for the caution in A.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs"},
  {"id":"cdp-child-development-1595","question":"A Class 6 teacher introduces negative numbers by asking students to move forward and backward on a number line painted on the floor, then draws the line on the board, and finally writes rules such as (−3) + 5 = 2. When a student says, ‘I picture myself walking backwards when I see a minus sign,’ which idea is best illustrated?","options":["Symbolic thinking supported by earlier enactive and iconic experience","An absence of formal reasoning, since he still needs physical images","Classical conditioning, with the minus sign acting as a conditioned stimulus","Pre-operational animism, treating numbers as if they were alive"],"answer":0,"explanation":"The student draws on enactive and iconic experiences to give meaning to symbols, exactly as Bruner intended. It shows integration of modes, not a lack of reasoning.","difficulty":"hard","source":"CTET · KVS · State TETs"},
  {"id":"cdp-child-development-1596","question":"How many of the following are correctly matched as Erikson stage – period of life – virtue? 1. Trust vs mistrust – infancy – hope 2. Initiative vs guilt – pre-school years – purpose 3. Identity vs role confusion – adolescence – fidelity 4. Generativity vs stagnation – late adulthood – wisdom","options":["One","Two","Three","Four"],"answer":2,"explanation":"The first three are correct. Generativity vs stagnation belongs to middle adulthood and yields care; wisdom comes from integrity vs despair in late adulthood.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1597","question":"Ainsworth linked attachment patterns to the kind of care infants received. Which caregiving pattern is most associated with insecure-resistant (ambivalent) attachment?","options":["Consistently sensitive and responsive care from the mother alone","Inconsistent care, sometimes warm and responsive, sometimes unavailable or intrusive","Consistently rejecting care that discourages the infant from seeking any closeness at all","Care shared by several warm caregivers in a large joint family"],"answer":1,"explanation":"Unpredictable responsiveness leads infants to cling and protest to get attention; consistent rejection is linked with avoidance, and sensitive care, from one or several caregivers, with security.","difficulty":"very-hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1598","question":"Assertion (A): An avoidant infant’s calm behaviour during separation in the Strange Situation shows that he is not stressed. Reason (R): Physiological measures such as heart rate show that avoidant infants are often aroused and stressed during separation despite appearing calm.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Avoidant infants mask distress; physiological arousal reveals stress, so the outward calm is not evidence of no stress. A is false and R is true.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1599","question":"Which statements about Bronfenbrenner’s model are correct? I. The child is an active participant who influences the environment. II. The mesosystem consists of interactions between the child’s microsystems. III. The exosystem consists of settings in which the child directly participates. IV. The macrosystem includes cultural values, customs and laws.","options":["I, II and IV only","I and III only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"III is false: the exosystem consists of settings in which the child does NOT directly participate, such as a parent’s workplace. The others are correct.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1600","question":"Bronfenbrenner used the term ‘ecological transition’ for changes in a person’s role or setting. Which of these is the clearest example for a child?","options":["A child reads a new storybook at home with her elder sister","A child’s grandmother tells her a folktale she has never heard before","A child moves from home and anganwadi into Class 1 of a formal school","A child watches a television programme about life in a faraway country"],"answer":2,"explanation":"Entering formal school changes the child’s setting and role (from home child to pupil), a classic ecological transition; such transitions are both outcomes and drivers of development.","difficulty":"very-hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1601","question":"In a Class 3, boys tease a boy who prefers to play with the girls, calling him ‘girly’, and he begins to avoid them. What does this illustrate, and what should the teacher do?","options":["Peers strongly enforce gender norms; the teacher should challenge the teasing and encourage mixed play","Gender preferences are purely biological, so the teacher should not interfere in how children choose to play","Only parents teach gender roles, so the teacher should simply inform them and stop there","The boy should be encouraged to play only with boys, so that he fits in and is teased less"],"answer":0,"explanation":"From early childhood, peers police gender-typed behaviour through teasing and exclusion; teachers can counter it by addressing teasing and structuring mixed-group activities.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1602","question":"Assertion (A): Schools teach values and attitudes that are not written in any syllabus. Reason (R): Through routines, rules, seating patterns and teachers’ behaviour, a hidden curriculum socialises students.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Punctuality, obedience, gender roles and attitudes to authority are learnt through school practices, which is exactly what the hidden curriculum means; R explains A.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1603","question":"Class 1 children repeatedly demand snacks and toys they have seen in TV advertisements and believe the ads ‘are telling us what’s good’. What does research on children and advertising suggest?","options":["Young children fully understand that ads try to sell products, but they enjoy them anyway","Young children are largely unaffected by advertisements, since they pay attention only to the cartoons in them","Before about seven or eight, children often miss the persuasive intent of ads, making them more susceptible","Only adolescents are affected by advertising, since younger children cannot buy anything"],"answer":2,"explanation":"Young children usually see ads as information or entertainment and do not yet understand they are designed to persuade; media-literacy talk by adults helps.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1604","question":"Research on the move from primary to middle school found that many students’ motivation and self-esteem dip just when schools become more controlling, competitive and impersonal. Eccles explained this as a poor:","options":["Stage–environment fit: schools offer less autonomy and closeness just when adolescents need more","Mesosystem, meaning weak links between the adolescent’s friends, family, school and neighbourhood","Attachment between the student and the mother in early infancy","Maturation of the prefrontal cortex, which temporarily slows down in early adolescence"],"answer":0,"explanation":"Stage–environment fit theory holds that declines occur when school settings offer less autonomy and warmth exactly as adolescents need more; better-matched schools reduce the dip.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1605","question":"Studies of peer pressure found that conformity to peers in antisocial acts (such as cheating or vandalism) tends to:","options":["Decline steadily from early childhood onwards as children become more independent","Remain about equal at all ages from childhood to adulthood","Be highest in late adulthood, when social approval matters most","Rise in early adolescence, peak around the early-to-mid teens, then decline"],"answer":3,"explanation":"Susceptibility to peer pressure, especially for antisocial behaviour, peaks around the age of 14–15 and then decreases as autonomy and self-regulation grow, which makes the early secondary years critical.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1606","question":"Research on parent–adolescent conflict in many families finds that most disagreements concern:","options":["Fundamental values such as honesty, religion and respect for elders","Everyday matters such as chores, dress, phone use and coming-home times","Whether the parent and the adolescent should continue their relationship at all","Only academic marks and the choice of stream after Class 10"],"answer":1,"explanation":"Conflict rises in early adolescence but mostly concerns day-to-day issues that adolescents see as personal choice and parents as rules; basic values are usually shared.","difficulty":"very-hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1607","question":"During the pubertal growth spurt, a Class 8 boy suddenly has large hands and feet while his trunk is still small, making him look and feel clumsy. What does this show?","options":["Pubertal growth follows exactly the same head-to-toe cephalocaudal pattern that is seen in infancy","He has a growth disorder that needs medical treatment before he grows further","Body parts grow at different times; hands and feet often grow before the trunk, causing temporary awkwardness","Growth of the trunk stops at puberty, so his proportions will stay like this"],"answer":2,"explanation":"In the adolescent spurt, the extremities often grow first and the trunk last, a temporary asynchrony; understanding it helps teachers be sensitive to self-consciousness in PE and classwork.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1608","question":"At birth the head is about one-quarter of the body’s length, but in an adult it is about one-eighth. This change in proportion is best explained by:","options":["The proximodistal principle: growth proceeds from the centre to the extremities","Development from specific to general, so that later growth spreads evenly across the body","Uniform growth of all body parts at the same rate throughout life","The cephalocaudal principle: the head develops early and the lower body catches up later"],"answer":3,"explanation":"Growth begins at the head and proceeds downward, so the head is relatively large early; the trunk and legs grow more later, reducing the head’s proportion.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1609","question":"Scores on infant development tests (based on sensorimotor milestones) given in the first year are poor predictors of IQ in later childhood. Which explanation is most reasonable?","options":["Intelligence does not really exist in infancy at all, so there is nothing for these early tests to measure","Infant tests tap sensorimotor skills, which differ in kind from the reasoning skills later IQ tests measure","IQ is fixed at birth, so testing in infancy is unnecessary and adds nothing","Infant tests always overestimate intelligence because babies are tested when alert"],"answer":1,"explanation":"Because development involves qualitative change, early sensorimotor measures tap different abilities from later reasoning; hence low predictive power, a reason not to label infants.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1610","question":"Asked whether it is OK to hit another child if the teacher says there is no rule against it, most four-year-olds say it is still wrong; but they say it is fine to talk without raising a hand if the teacher allows it. What does this suggest about young children’s moral understanding?","options":["They can tell moral rules about harm from social conventions, earlier than Piaget’s account suggested","They see all rules as equally sacred and unchangeable, exactly as Piaget’s account of moral realism claimed","They judge right and wrong only by what the adults around them say","They have no moral understanding at all until they start formal schooling"],"answer":0,"explanation":"Research in social domain theory (Turiel) shows preschoolers treat harm-based rules as wrong regardless of authority, but conventions as changeable, refining the picture of strict moral realism.","difficulty":"very-hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1611","question":"After Class 12, a student with admission offers decides to spend a year volunteering in rural schools and talking to people in different careers before choosing a course. Her parents fear she is ‘lost’. How would Erikson view this?","options":["As role confusion, an unhealthy failure of identity that needs professional treatment","As identity foreclosure, accepting a path without exploring","As a psychosocial moratorium, a healthy period of exploration before commitment","As stagnation, a failure of generativity in early adulthood"],"answer":2,"explanation":"A planned period of exploration before committing to adult roles is what Erikson called a moratorium; it typically leads toward identity achievement, not confusion.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1612","question":"Working parents worry that sending their toddler to a crèche will damage his attachment to them. What does research on childcare broadly suggest?","options":["Any non-parental care always produces insecure attachment, whatever its quality","Security depends mainly on parents’ sensitivity; good, stable childcare generally does not harm it","Children in full-time childcare cannot form attachments to their parents, only to their paid carers","Childcare quality does not matter, as long as the child is fed and kept safe"],"answer":1,"explanation":"Large studies found parental sensitivity is the main predictor of attachment; high-quality, stable care supports development, while very poor-quality care is the concern.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1613","question":"After the mid-day meal scheme reached a village school, teachers found that children paid attention longer, attendance rose and learning improved. Which principle of development does this best illustrate?","options":["Domains of development are interrelated: better nutrition supports attention and learning","Development depends only on heredity, so the improvement must be coincidence","Cognitive development is independent of physical health, so the meal only raised attendance","Development proceeds cephalocaudally, from the head downwards to the feet"],"answer":0,"explanation":"Physical well-being affects cognitive and social functioning; hunger impairs attention, so nutrition supports learning, showing the interrelation of domains.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1614","question":"In a Class 7, a group bullies a quiet student while most classmates watch and laugh. Which approach does research find most effective?","options":["Suspending only the bully, with no change at all for the watching classmates or the school’s rules","Asking the victim to be tougher and stand up to the group on his own","A whole-school approach that teaches bystanders to support the victim and report, with clear rules","Ignoring it, as children must sort out such conflicts and it builds character"],"answer":2,"explanation":"Bullying is a group phenomenon sustained by bystanders; whole-school programmes that mobilise bystanders and set clear norms reduce it more than punishing individuals alone.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1615","question":"A teacher training text says ‘the concrete operational stage runs from 7 to 11 years’ and ‘identity vs role confusion runs from 12 to 18’. How should a teacher interpret such ages?","options":["As exact cut-offs that every child crosses on time, so that teaching can be planned strictly by age","As irrelevant, since research has shown that stages do not exist at all","As approximate averages; children pass through stages in order but at different ages, gradually","As legal age limits that the RTE Act sets for each class"],"answer":2,"explanation":"Stage ages are rough norms; development is continuous with individual differences in rate, so transitions are gradual and vary between children.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1616","question":"Which statement about attachment in adolescence is best supported?","options":["Adolescents no longer need attachment to parents, since peer relationships fully replace it","Secure attachment to parents makes adolescents more dependent on them and less willing to explore","Attachment matters only for girls, as boys become independent at puberty","Securely attached adolescents tend to explore identity and peers more confidently, using parents as a secure base"],"answer":3,"explanation":"Autonomy grows best within secure relationships; parents remain a secure base from which adolescents explore, rather than attachment ending at puberty.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1617","question":"A child with Down syndrome joins Class 1. A teacher says, ‘It is genetic, so nothing can be done to help her learn.’ What is the best response?","options":["The teacher is right; genetic conditions are fixed and cannot be influenced by teaching or care","It is due to an extra chromosome 21, but early intervention and inclusive teaching can greatly aid her development","Down syndrome is caused by poor parenting during infancy, so the parents must change first","She should be kept out of school until she matures enough to cope"],"answer":1,"explanation":"Down syndrome is a chromosomal condition (trisomy 21), not a result of parenting; environment and teaching strongly influence how far each child develops, so inclusion and support matter.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1618","question":"A Class 11 student finds out that seniors are ragging juniors. He reports it, saying, ‘The anti-ragging rules are there to protect the order of the institution; if we let some break them, the whole system collapses.’ His reasoning reflects Kohlberg’s:","options":["Stage 6, because he acts on a self-chosen universal ethical principle","Stage 3, because he wants seniors and teachers to like him","Stage 2, because he will benefit personally by reporting","Stage 4, because he upholds rules to maintain the social order"],"answer":3,"explanation":"Upholding rules because the system depends on them is Stage 4. He refers to institutional order, not universal ethical principles (Stage 6) or personal approval or gain.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1619","question":"In a Class 6 maths class, the teacher always calls on boys for difficult problems and gives girls easy ones ‘so they don’t feel bad’. Over time, the girls start saying maths is ‘for boys’. What process is mainly at work?","options":["Biological differences in mathematical ability that clearly show up between boys and girls by Class 6","Socialisation through teacher expectations and unequal treatment, shaping students’ self-beliefs","Peer pressure from other girls to avoid maths to stay popular","Immanent justice, the belief that wrongdoing is always punished"],"answer":1,"explanation":"Differential treatment communicates low expectations, which students internalise as beliefs about their own abilities: school as an agent of gender socialisation and a self-fulfilling prophecy.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1620","question":"Staff at a crèche are trained to respond promptly to each infant’s cues and to assign each infant a regular primary caregiver instead of rotating staff daily. According to Erikson and attachment research, this mainly supports:","options":["Basic trust and secure attachment, through consistent and responsive care","Industry, through early achievement and the mastery of small tasks","Autonomy, by leaving infants to soothe themselves without adult help","Identity formation, through a stable adult whose role the infant can copy"],"answer":0,"explanation":"Infants build trust and secure attachment when care is consistent, predictable and responsive; a stable primary caregiver provides exactly this.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1621","question":"Match each theorist with the model of intelligence: 1. Spearman 2. Thurstone 3. Guilford 4. Sternberg; a. A three-dimensional ‘cube’ of operations, contents and products b. A general factor plus specific factors c. A triarchic theory rooted in information processing, experience and context d. Several primary mental abilities","options":["1-b, 2-a, 3-d, 4-c","1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-a, 4-c"],"answer":3,"explanation":"Spearman: g and s; Thurstone: primary mental abilities; Guilford: the structure-of-intellect cube; Sternberg: the triarchic theory with componential, experiential and contextual parts.","difficulty":"hard","source":"CTET · DSSSB TGT"},
  {"id":"cdp-child-development-1622","question":"How many of these statements about Sternberg’s triarchic theory are correct? I. The componential subtheory deals with the internal mental processes of thinking. II. The experiential subtheory deals with handling novelty and automatising familiar tasks. III. The contextual subtheory deals with adapting to, shaping and selecting environments. IV. Sternberg held that conventional IQ tests capture all three aspects fully.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III describe the three subtheories correctly. Sternberg argued that IQ tests tap mainly analytical ability and neglect creative and practical intelligence, so IV is false.","difficulty":"hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1623","question":"Simran, a Class 4 child with cerebral palsy, has limited control over her hand movements but remembers and sings long songs perfectly after hearing them once. Applying Gardner’s ideas, the teacher’s best step is to:","options":["Teach her only music, since that is her single intelligence and she will excel in it","Focus only on improving her handwriting until it reaches grade level, since neat writing underlies every subject","Excuse her from all academic learning because of her disability and let her just sing","Use songs and rhythm to teach multiplication tables and new words, while also supporting her other abilities"],"answer":3,"explanation":"Gardner’s theory encourages using a child’s strengths as entry points to other content; confining her to music alone or concentrating only on her weakness ignores her full potential.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1624","question":"In the early twentieth century, English-language intelligence tests given to newly arrived immigrants at Ellis Island in the USA labelled large numbers of them ‘feeble-minded’. The main lesson for test users today is that:","options":["Tests should be translated word for word into each test-taker’s mother tongue","A test in an unfamiliar language and culture can produce invalid, harmful labels","Intelligence tests should be given only by trained psychologists, not officials","Tired travellers score lower, so tests should be repeated after a period of rest"],"answer":1,"explanation":"The tests measured familiarity with English and American culture, not intelligence, so the labels were invalid and were used to justify exclusion. Word-for-word translation is tempting but does not remove culturally loaded content or norms built on a different population.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1625","question":"When a student repeatedly disrupts her lesson, a teacher in Ajmer notices her own anger rising, pauses, lowers her voice and speaks to the student calmly after class. Beyond managing the situation, the teacher is modelling for students the emotional-intelligence skill of:","options":["Empathy","Social awareness","Self-motivation","Self-regulation"],"answer":3,"explanation":"Recognising and controlling one’s own impulses before acting is self-regulation; students learn this skill partly by watching how adults handle strong emotions.","difficulty":"moderate","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1626","question":"Assertion (A): In classrooms where wrong answers are laughed at, students offer fewer original ideas. Reason (R): Creative thinking involves taking intellectual risks, which students do only when they feel psychologically safe.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Original ideas are often wrong at first; when mistakes bring ridicule, students avoid risk and offer only safe answers, which is exactly what R describes.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1627","question":"A Class 9 teacher gives a hard open-ended design problem on Friday, discusses it briefly, and asks students to come back with ideas on Monday rather than solving it in one sitting. Which aspect of the creative process is she deliberately making room for?","options":["Verification","Functional fixedness","Mental set","Incubation"],"answer":3,"explanation":"Stepping away after initial preparation allows incubation, during which ideas may reorganise without conscious effort; illumination often follows when the problem is taken up again.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1628","question":"Which of these questions is genuinely DIVERGENT?","options":["In how many different ways can 12 be written as a product of two whole numbers?","List the three causes of the revolt of 1857 given in the chapter.","Suggest different ways our school could help younger children save electricity.","What is the sum of the interior angles of any triangle drawn on paper?"],"answer":2,"explanation":"The question about 12 sounds open but has one fixed correct answer (1 × 12, 2 × 6, 3 × 4), so it is convergent; only the electricity question invites many varied, original answers.","difficulty":"very-hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1629","question":"Three highly able students in a Class 6 section are placed in the same group for project work so that they can challenge one another, while staying in the regular class. This arrangement is called:","options":["Cluster grouping","Grade skipping","Tracking into a separate section","Remedial grouping"],"answer":0,"explanation":"Cluster grouping places a small group of gifted students together within a regular class, giving them intellectual peers without separating them from the rest of the class.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1630","question":"According to Carol Ann Tomlinson’s model of differentiated instruction, a teacher may adapt content, process and products according to students’:","options":["Caste, religion and gender of the students","Readiness, interests and learning profiles","IQ scores and last year’s class rank only","Parents’ occupation, income and education"],"answer":1,"explanation":"Differentiation responds to readiness (current level), interests and learning profiles; it never sorts children by social identity.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1631","question":"A teacher in a fishing village in Kerala uses children’s knowledge of tides, boat repair, net-mending and fish-market prices to teach measurement, patterns and money. This approach draws on what researchers (Luis Moll and colleagues) call:","options":["Cultural deficit","Hidden curriculum","Funds of knowledge","Crystallised intelligence"],"answer":2,"explanation":"Funds of knowledge are the skills and knowledge accumulated in households and communities; using them treats children’s backgrounds as resources rather than deficits.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1632","question":"Mangal, a Class 1 child whose home language is Kurukh, stays silent in class where only Hindi is used. His teacher writes ‘dull and unresponsive’ in his record. Which is the best evaluation?","options":["The teacher is right; long silence in class is a reliable sign of low intelligence","Mangal should be shifted to a special school, where teachers have more time for slow children like him","The teacher should wait for Mangal to pick up Hindi on his own from his classmates before assessing him at all","His silence likely reflects the language gap, not ability; use his home language and visuals before judging"],"answer":3,"explanation":"A mismatch between home and school language commonly causes silence in the early months; labelling it as dullness is a serious misreading that can become self-fulfilling.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1633","question":"NCF 2005 recommends that children be taught in their home language in the early years. Which view of language mainly underlies this recommendation?","options":["Language is only a means of communication and has no real link with how children think or form concepts","Children grasp new concepts best in the language in which they already think and make meaning","Home languages are easier to set and mark in the board examinations later on","Using English from Class 1 harms young children’s physical health and growth"],"answer":1,"explanation":"NCF 2005 treats language as a medium of thought as well as communication; concepts built in the home language are deeper and transfer later to other languages.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1634","question":"Which of the following statements correctly compare Piaget and Vygotsky? I. For Piaget, development largely sets the limits of what can be learned. II. For Vygotsky, good learning can lead development. III. For Piaget, language is the main driving force of cognitive development. IV. For Vygotsky, social interaction is the source of higher mental functions.","options":["I, II and III only","II and III only","I, II and IV only","I, III and IV only"],"answer":2,"explanation":"Piaget saw language as reflecting cognitive development rather than driving it, so III is false; the other three statements correctly describe the two theorists.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1635","question":"In the 1980s, deaf children brought together in new schools in Nicaragua, without any existing sign language, created their own sign language, and later, younger groups of children made it grammatically richer. This case is often cited as evidence for:","options":["Skinner’s view that grammar must be shaped by adults who reinforce children’s correct forms","An innate human capacity to create grammatical structure, especially in young children","The strong Sapir–Whorf hypothesis that language fixes how people perceive","Piaget’s claim that language appears only after formal operations are reached"],"answer":1,"explanation":"No adult model provided the grammar; children themselves built and regularised it, which is consistent with nativist ideas of an inborn language capacity that is strongest early in life.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1636","question":"A science teacher says, ‘Once students learn words like “evaporation” and “condensation”, they have tools to notice and think about processes they earlier saw only as water disappearing.’ This view of words as tools for thinking is closest to:","options":["Vygotsky’s idea of language as a psychological tool","Skinner’s idea of verbal operants shaped by reward","Freud’s idea of the unconscious mind shaping all thought","Thorndike’s law of exercise strengthening bonds"],"answer":0,"explanation":"Vygotsky saw language as the main psychological tool that mediates and reorganises thinking; scientific words help children form systematic concepts.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1637","question":"A father in Ludhiana tells his eight-year-old son, ‘Boys don’t cry,’ whenever he is hurt or sad. Seen through the lens of gender as a social construct, the most likely effect is that the boy:","options":["Learns that hiding feelings is part of being male, limiting his emotional expression and help-seeking","Becomes emotionally stronger in a healthy way, since he learns early to control upsetting feelings","Is unaffected, because the way emotions are expressed is fixed by biology rather than by what parents say","Learns to express his feelings more openly, since he is told to speak up"],"answer":0,"explanation":"Gender norms restrict boys as well as girls; teaching boys to suppress sadness can hinder emotional development and willingness to seek support.","difficulty":"moderate","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1638","question":"In a Class 7 debate, Arjun interrupts and argues forcefully and is praised as ‘a natural leader’, while Meera, who does the same, is called ‘rude and too loud for a girl’. This is an example of:","options":["Fair, gender-neutral assessment of the two students’ debating skills","Positive discrimination in favour of girls in debates","A double standard judging the same behaviour differently by gender","Criterion-referenced evaluation of speaking skills"],"answer":2,"explanation":"Judging identical behaviour by gender expectations is a double standard; it teaches girls to be silent and boys that assertiveness is their right.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1639","question":"How does Kohlberg’s cognitive-developmental account of gender-role development differ from social learning theory?","options":["Children learn gender roles only through the rewards and punishments that their parents and teachers give them","Once children grasp that gender is permanent, they seek out same-gender activities, socialising themselves","Gender roles are fixed by prenatal hormones, so understanding plays no part in them","Children do not understand gender at all until adolescence, when roles are first learned"],"answer":1,"explanation":"For Kohlberg, cognitive understanding (gender constancy) comes first and motivates children to adopt gender-typed behaviour; social learning theory puts modelling and reinforcement first.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1640","question":"A Dalit girl from a landless family in rural Bihar faces disadvantages that differ from those of a Dalit boy or an upper-caste girl, because caste, gender and poverty combine. The concept that captures this is:","options":["Psychological androgyny","Bourdieu’s cultural capital","Intersectionality","Gender constancy"],"answer":2,"explanation":"Intersectionality (Kimberlé Crenshaw) describes how social identities such as caste, gender and class interact to produce particular, compounded forms of disadvantage.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2"},
  {"id":"cdp-child-development-1641","question":"The same Class 5 students take an arithmetic test on Monday and an equivalent version on Wednesday. Their scores and ranks change wildly between the two days, with no teaching in between. The main problem is that the test is:","options":["Invalid but reliable","Unreliable","Too objective","Criterion-referenced"],"answer":1,"explanation":"Reliability is the consistency of scores across occasions or forms; wildly varying results show low reliability, and an unreliable test cannot be valid either.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1642","question":"A Class 4 teacher passes on a note to next year’s teacher: ‘Rohit – trouble-maker, weak, don’t expect much.’ The most serious risk of this practice is that:","options":["The next teacher will simply ignore the note and form her own views of Rohit over time","Rohit will be promoted too early to the next class without being ready for its much harder work","It will make record-keeping slower and add to the paperwork of both teachers at year end","The next teacher’s expectations may be biased from day one, making the label self-fulfilling"],"answer":3,"explanation":"Labels passed on without context shape how the next teacher treats the child; useful records should describe specific needs and strategies, not fixed judgements.","difficulty":"hard","source":"CTET Paper 1 · State TET"},
  {"id":"cdp-child-development-1643","question":"Assertion (A): Displaying the rank list of every Class 3 child on the notice board motivates all children to work harder. Reason (R): Constant comparison with peers can damage the self-esteem and motivation of children who rank low.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Public ranking may spur a few but discourages many, especially those at the bottom; NCF 2005 discourages comparison of young children, so A is false and R is true.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1644","question":"Assertion (A): A student with a very high IQ may still struggle to work well in group projects. Reason (R): IQ and interpersonal or emotional skills are relatively distinct abilities.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because IQ tests mainly measure reasoning and knowledge, a high score does not guarantee skills in understanding others and managing emotions, which group work needs.","difficulty":"hard","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1645","question":"David Wechsler described intelligence as the ‘aggregate or global capacity’ of a person to act purposefully, to think rationally and to deal effectively with the environment. Which feature of his tests followed from this broad view?","options":["Separate verbal and performance scales, as well as an overall score","A single vocabulary test treated as the complete measure of ability","A focus on the speed of simple reactions as the core of intelligence","Testing only children below the age of eight"],"answer":0,"explanation":"Wechsler saw intelligence as global but made up of different abilities, so his scales gave verbal and performance (non-verbal) scores as well as a full-scale IQ, and he built scales for adults too.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1646","question":"A boy aged 12 years has a mental age of 9 years. What is his ratio IQ?","options":["133","80","75","70"],"answer":2,"explanation":"Ratio IQ = MA ÷ CA × 100 = 9 ÷ 12 × 100 = 75. Inverting the ratio gives about 133.","difficulty":"moderate","source":"CTET Paper 2 · State TET"},
  {"id":"cdp-child-development-1647","question":"Wallach and Kogan gave children creativity tasks in a relaxed, game-like, untimed setting instead of a test-like one. What did they find?","options":["Creativity scores were virtually identical to IQ scores, so a separate creativity test is not needed","Creativity scores were fairly independent of intelligence scores, suggesting the two are distinct","Children could not produce any creative ideas at all without the pressure of time limits","Only children with IQs above 140 showed any creativity on the game-like tasks"],"answer":1,"explanation":"In a non-evaluative, game-like setting, creativity measures correlated highly with one another but only weakly with intelligence measures, supporting creativity as a distinct ability.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1648","question":"Which of the following is one of the six PRODUCTS in Guilford’s structure-of-intellect model?","options":["Divergent production","Figural content","Transformations","Evaluation"],"answer":2,"explanation":"Guilford’s products are units, classes, relations, systems, transformations and implications. Divergent production and evaluation are operations, and figural is a content.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT"},
  {"id":"cdp-child-development-1649","question":"Assertion (A): Thurstone originally argued that intelligence consists of several primary abilities rather than one dominant general factor. Reason (R): Thurstone used factor analysis of scores on many tests.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but factor analysis is only the method; Spearman used it too and reached g. Thurstone’s conclusion came from his particular way of analysing the factors, so R does not explain A.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1650","question":"Provoked by a classmate’s remark, Class 9 student Kunal suddenly explodes in rage and throws a book, then regrets it minutes later and cannot explain why he reacted so strongly. Daniel Goleman popularised a term for such moments when emotion overwhelms rational control:","options":["Emotional (‘amygdala’) hijacking","Self-actualisation (Maslow’s peak need)","Cognitive dissonance (Festinger’s tension)","Functional fixedness under provocation"],"answer":0,"explanation":"Goleman used ‘amygdala hijack’ for sudden emotional reactions that override reasoned responses; EI training teaches pausing and naming feelings to regain control.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1651","question":"Which feature is found in inclusion but NOT in integration?","options":["The child with a disability attends a regular neighbourhood school with other children","The child receives some help from a resource teacher outside the regular class for part of the day","The school changes its curriculum, teaching and assessment so that diverse learners can take part","The child is expected to meet the existing standards with the existing teaching methods"],"answer":2,"explanation":"Both arrangements may place children in regular schools with some extra help, but only inclusion restructures the system itself; expecting the child to fit unchanged methods is the mark of integration.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1652","question":"In a mixed-ability Class 6 class, a few students always finish early and then disturb others, while the teacher is busy with a small group. Which differentiation strategy best addresses this?","options":["Asking early finishers to sit silently with arms folded until everyone is done, to build patience","Setting up ‘anchor activities’: meaningful tasks linked to the unit that students move to on their own","Giving early finishers extra copies of the same exercise to practise more","Sending early finishers to the library without any task, so that they can read whatever they happen to like"],"answer":1,"explanation":"Anchor activities keep finished students learning independently and free the teacher to work with groups; silent waiting or repeated drill wastes their time and invites disruption.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1653","question":"A Class 3 teacher asks, ‘Find as many ways as you can to make 24 using any operations.’ Some children write 12 + 12, while others write 4 × 3 × 2 or 30 − 6. Why is this a good task for an inclusive class?","options":["It is easy, so every child gets full marks and feels successful, which is the main aim of inclusion","It tests only the brightest children, who can find the most ways","It replaces the need for any other teaching of operations in Class 3","It is open-ended: every child can start at her own level while able learners go much further"],"answer":3,"explanation":"Open tasks with an easy entry point and no upper limit let the whole class work on the same problem at different depths, which differentiates naturally.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1654","question":"Anjali, a gifted Class 4 student, scores 100% on every class maths test. Her teacher wants to know how far her ability actually goes. What is the best approach?","options":["Using above-level problems, since grade-level tests have a ceiling and cannot show how far she can go","Relying on her class test scores, since a score of 100% on every single test already shows her full ability","Comparing her marks with the class average to see how far ahead of others she is","Waiting for the board exams in Class 10 to give a fair judgement of her ability"],"answer":0,"explanation":"Grade-level tests have a ceiling: a perfect score shows only that she has mastered that level, not how far beyond it she can go; above-level tasks reveal her true level for planning.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1655","question":"Siddharth, in Class 6, reasons brilliantly in discussions and spends hours on his interest in astronomy, but he is disorganised, loses track in routine tasks and rarely finishes written work. What should the teacher plan?","options":["Only challenging enrichment, since he is clearly gifted and the rest will follow","Only support for attention and organisation, since his written marks are low and that must come first","Both: challenging, interest-based work for his ability and structured support for organisation","Neither, since bright children usually grow out of such problems by themselves"],"answer":2,"explanation":"He shows signs of being twice-exceptional, with high ability alongside attention difficulties; meeting only one need either wastes his ability or leaves the barrier in place.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1656","question":"After repeated failure, Rahul, a Class 5 student with dyslexia, says, ‘I am stupid. I will never be able to read.’ Which teacher response is most helpful?","options":["‘Don’t worry, reading is not that important; many successful people never read much.’","‘You’re not stupid; your brain learns reading differently, and look, you read many more words than in June.’","‘If you just work harder and stop being lazy, you will soon read as well as the others in class.’","‘Everyone is good at something; let’s forget about reading and focus on your drawing.’"],"answer":1,"explanation":"Helping the child attribute difficulty to a specific, changeable cause and showing real evidence of progress counters learned helplessness; ‘work harder’ implies he has not tried, and dismissing reading lowers expectations.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1657","question":"Neel, a Class 6 student with ADHD, often drifts off during independent work. The teacher gives him a card with a small box for every 10 minutes, where he ticks whether he was on task, and they review it together at the end. What is the main purpose of this strategy?","options":["To collect a written record of his lapses that can later justify a punishment or report to parents","To teach self-monitoring, so that he gradually learns to notice and manage his own attention","To replace the teacher’s instruction with a self-paced checklist","To compare him publicly with classmates who stay on task more"],"answer":1,"explanation":"Self-monitoring builds the self-regulation that ADHD makes difficult; reviewing it together turns it into a learning tool rather than a punishment record.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1658","question":"A Class 2 teacher tells Arnav, who is autistic, ‘Be good during assembly.’ He looks confused and wanders off. Which instruction would work better?","options":["‘Behave yourself properly during the assembly today, Arnav.’","‘You know what I mean, so don’t make me repeat it again.’","‘Be nice to everyone, and just do whatever the other children around you are doing.’","‘Stand in line next to Riya and keep your hands by your side till the bell rings.’"],"answer":3,"explanation":"Abstract instructions like ‘be good’ do not tell an autistic child what to do; concrete, specific statements of the expected behaviour are clearer.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1659","question":"Tara, a Class 4 student on the autism spectrum, knows the names and sizes of dozens of dinosaurs but has no interest in maths. What is a sensible step for the teacher?","options":["Using dinosaurs in maths tasks, such as comparing their lengths or ordering their weights","Banning all dinosaur talk in class until her maths marks begin to improve steadily","Ignoring her interest completely, since dinosaurs are not part of the Class 4 maths syllabus","Telling her parents to stop buying dinosaur books so she focuses on maths"],"answer":0,"explanation":"Strong special interests are powerful motivators for many autistic learners and can be used as a bridge into less preferred subjects.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1660","question":"Using the sighted-guide technique, a Class 7 student is guiding her blind classmate to the computer lab. Which description of the correct technique is right?","options":["The guide holds the blind student’s hand firmly and leads him along the corridor at her pace","The guide walks behind him and steers him gently by the shoulders at each turn","The blind student holds the guide’s arm just above the elbow, walking half a step behind","The guide walks ahead and calls out directions from a short distance away"],"answer":2,"explanation":"Holding just above the guide's elbow and following half a step behind lets the blind person feel turns, steps and stops through the guide's movement while staying in control.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1661","question":"Assertion (A): Even though audiobooks and screen readers are widely available, blind children should still learn Braille. Reason (R): Braille gives direct access to spelling, punctuation and the layout of written language, which listening alone does not.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Listening gives content but not the written form; Braille literacy lets blind learners read and write independently with full knowledge of spelling and structure, which is why it remains essential.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1662","question":"During a fire drill, Naveen, a deaf Class 5 student, does not respond to the alarm bell and stays in the classroom. Which arrangement best ensures his safety?","options":["Asking him to watch the clock closely at the scheduled drill time and leave when it is due","Installing visual alerts such as flashing lights, plus a buddy who always alerts him","Excusing him from fire drills since he cannot hear the bell","Making the bell much louder so that he can feel or hear it"],"answer":1,"explanation":"Emergency systems that rely only on sound exclude deaf students; visual signals plus a buddy give reliable access, and a louder bell may still not be heard.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1663","question":"Javed, a Class 5 student with cerebral palsy, answers questions by pointing slowly to words on a communication board. Classmates often call out the answer before he finishes. What should the teacher do?","options":["Ask Javed only yes/no questions so that he can answer quickly and less class time is used","Let classmates finish his answers for him, since they usually know exactly what he is trying to say anyway","Give him enough wait time, teach the class to wait until he finishes, and value his answers equally","Stop asking him questions during lessons to avoid embarrassing him"],"answer":2,"explanation":"Users of communication aids need extra time; when others answer for them, they lose their voice, so the class must learn to wait and respect his communication.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1664","question":"For the annual sports day, the PE teacher plans to make Kunal, who uses a wheelchair, the scorekeeper for all events. Which alternative best reflects inclusion?","options":["Excusing Kunal from sports day so that he is not placed under any strain","Keeping him as scorekeeper for every event, since it is a responsible job that keeps him busy and involved all day","Letting him watch from the stands with his parents and cheer for his house","Designing some events all can join, such as seated throws and mixed relays, so that Kunal competes with others"],"answer":3,"explanation":"Inclusion means taking part as a participant, not only as a helper; adapting events lets him compete, while a permanent support role still leaves him on the sidelines.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1665","question":"A Class 8 teacher learns that Sunita, aged 14, has stopped attending school and that her family is arranging her marriage. What should the teacher do?","options":["Treat it as a private family matter that the school has no right to interfere in, and simply wait for her to return","Speak to the family about her right to education, and alert Childline (1098), as marriage below 18 is prohibited","Remove her name from the register after a month of continuous absence, as attendance rules require","Tell her classmates to persuade her to come back, without involving any adults"],"answer":1,"explanation":"Marriage of a girl under 18 is prohibited by law, and the school has a duty to protect the child's right to education; engaging the family and alerting child-protection services are the right steps.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1666","question":"After the summer break, many first-generation learners in a Class 3 village class have forgotten much of their reading, since their homes have no books. Which step helps most?","options":["A lending library or book bags so children take books home, with activities families can do even without reading","Assigning long written holiday homework so that children keep practising letters and words every day","Blaming the parents for not teaching their children at home, and asking them to sign a written promise to do so","Repeating the whole of last year’s syllabus from the beginning before moving on"],"answer":0,"explanation":"Access to books at home sustains reading; activities that do not depend on literate parents make it possible for every family to help.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1667","question":"For the school’s annual day, a teacher selects only ‘neat, well-dressed and fluent in English’ children to perform. Many children from poorer homes are never chosen. What is the main concern?","options":["The teacher should select children by lottery only, ignoring interest and effort, so that nobody can ever complain","It does not matter, since only a few children can ever perform on annual day","Such criteria reflect class bias and deny some children recognition; every child should get chances, with support","Children from poorer homes are usually not interested in performing on stage"],"answer":2,"explanation":"Criteria like dress and English fluency favour advantaged children; inclusive schools rotate opportunities and support every child to take part.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1668","question":"A Class 5 PE teacher lets only boys play cricket and only girls practise dance for the annual function. A boy who loves dance and a girl who loves cricket complain. What is the best course of action?","options":["Keep the arrangement, since it matches what most children in the class prefer anyway","Allow the two children to switch quietly, but keep the gender rule unchanged for everyone else in the class","Tell the children that these activities do not suit their gender and offer alternatives","Open every activity to all children by interest, and actively encourage participation across gender lines"],"answer":3,"explanation":"Assigning activities by gender reinforces stereotypes and limits every child; access based on interest, with encouragement, challenges those limits.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1669","question":"Under the RPwD Act, 2016, which of the following are among the duties of educational institutions? I. Providing transportation facilities to children with disabilities and their attendants where they have high support needs. II. Monitoring the participation, progress and completion of education of every student with a disability. III. Ensuring that education of children who are blind, deaf or both is in the most appropriate languages and modes of communication.","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":3,"explanation":"All three are listed duties: transport (including for attendants of children with high support needs), monitoring of participation and progress, and education in appropriate languages and modes for blind and deaf learners.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1670","question":"Match each UDL principle with the kind of learner it aims to develop. 1. Engagement 2. Representation 3. Action and expression; a. Strategic and goal-directed b. Resourceful and knowledgeable c. Purposeful and motivated","options":["1-c, 2-b, 3-a","1-a, 2-b, 3-c","1-c, 2-a, 3-b","1-b, 2-c, 3-a"],"answer":0,"explanation":"Engagement builds purposeful, motivated learners; representation builds resourceful, knowledgeable learners; and action and expression build strategic, goal-directed learners.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1671","question":"A Class 6 trip to a science centre costs ₹600. Several children from low-income families say they ‘don’t want to go’ and stay back each year. What should the school do?","options":["Accept their choice without question, since the trip is optional and families know their own situation best","Make the trip compulsory and ask all families to pay the full amount in instalments","Cover the cost discreetly through school funds or sponsorship, so that no child is left out or singled out","Cancel all trips, so that no child ever feels left out of an activity"],"answer":2,"explanation":"Hidden costs quietly exclude poorer children, who often hide the real reason; discreet support keeps the experience open to all without embarrassment.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1672","question":"The RPwD Act, 2016 describes ‘specific learning disabilities’ as a group of conditions involving difficulty in processing spoken or written language or calculation. Which of these does the Act name as examples? I. Dyspraxia II. Developmental aphasia III. Attention deficit hyperactivity disorder","options":["I and II only","I only","II and III only","I, II and III"],"answer":0,"explanation":"The Act's description of specific learning disabilities names conditions such as perceptual disabilities, dyslexia, dysgraphia, dyscalculia, dyspraxia and developmental aphasia; ADHD is not among them.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1673","question":"Priyanshu, a Class 5 student with dyslexia, copies notes from the board very slowly and with many errors, so he has little time left to listen or think. Which support is most suitable?","options":["Making him stay back after school every day until he has copied all the notes correctly","Giving him printed notes or letting him photograph the board, so he can focus on understanding","Asking him to copy only the first half of the notes and leave the rest","Telling him to copy faster, and to practise copying pages from the textbook at home every evening"],"answer":1,"explanation":"Copying is a heavy load for a child with dyslexia and takes attention away from learning; providing notes removes the barrier without lowering the content.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1674","question":"Kartik, a deaf Class 2 child, often hits classmates during games. The teacher notices it usually happens when others change the rules quickly or laugh at something he did not catch. What is the most likely cause and the best response?","options":["He is naturally aggressive and needs strict punishment every time he hits someone","He should be kept out of group games and given solo activities until he learns to control his temper","Frustration at being left out of communication; teach peers simple signs and give Kartik other ways to express it","He is jealous of his classmates and needs counselling only, not classroom changes"],"answer":2,"explanation":"Behaviour often signals unmet communication needs; making communication accessible and teaching alternative ways to express feelings tackles the cause.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1675","question":"Which of these statements are consistent with NEP 2020 regarding children with disabilities? I. Indian Sign Language is to be standardised across the country, with curriculum materials developed for students with hearing impairment. II. Home-based education remains a choice for children with severe and profound disabilities who are unable to go to school. III. All children with disabilities must study in special schools.","options":["I only","II and III only","I, II and III","I and II only"],"answer":3,"explanation":"NEP 2020 calls for standardising Indian Sign Language and keeps home-based education as an option for children who cannot attend school; it supports choice and inclusion, not compulsory special schooling.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1676","question":"A new 15-minute reading test for Class 3 is given in the same week as an established, longer reading assessment, and the two sets of scores correlate highly. This is evidence of the new test’s:","options":["Predictive validity","Concurrent validity","Face validity","Split-half reliability"],"answer":1,"explanation":"Agreement with an established measure taken at about the same time is concurrent validity; predictive validity would compare the test with a criterion measured later.","difficulty":"hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1677","question":"A ‘creativity test’ for Class 6 consists only of questions asking students to recall the names of famous inventors. Its main weakness lies in its:","options":["Inter-rater reliability, since scorers may disagree","Test–retest reliability, since recall can change over a few weeks","Objectivity of scoring, since names can be spelt variously","Construct validity, since it measures memory, not creativity"],"answer":3,"explanation":"Recalling names taps factual memory, not the construct of creativity (fluency, originality, flexibility); such items can be scored objectively and consistently and still measure the wrong thing.","difficulty":"moderate","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1678","question":"To make scoring ‘fair’, a Class 9 English teacher replaces all essay questions with multiple-choice items. Which statement best evaluates this change?","options":["Scoring objectivity rises, but validity for assessing writing and argument falls","Both reliability and validity for assessing writing skills improve together","Validity rises, since well-made multiple-choice items are always more valid than essays","Nothing changes, since the format of a test does not affect what it measures"],"answer":0,"explanation":"MCQs remove scorer disagreement but cannot show whether a student can compose an argument; gaining objectivity at the cost of the target skill lowers validity.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1679","question":"Which top-level rubric descriptor for ‘use of evidence’ in a Class 8 essay is best written?","options":["‘Excellent and impressive use of evidence throughout the whole essay, with very good quotations.’","‘Uses five or more quotations from the text in every paragraph of the essay.’","‘Supports each main point with relevant evidence from the text and explains how it helps.’","‘Uses evidence better than most other students in the class this term.’"],"answer":2,"explanation":"Good descriptors state observable qualities of performance; ‘excellent’ is vague, counting quotations ignores quality, and comparison with peers is not a criterion.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1680","question":"A teacher asks Class 8 students to keep every draft, rough note and reflection from their science project in one folder, so that she can see how their thinking developed and not just the final product. This folder is a:","options":["Showcase portfolio of best work","Assessment rubric for the project","Cumulative record of the student","Process (working) portfolio"],"answer":3,"explanation":"A process portfolio documents the journey of learning, including drafts and reflections; a showcase portfolio holds only best final work, and a cumulative record is the school’s long-term record of a pupil.","difficulty":"hard","source":"CTET Paper II · State TET"},
  {"id":"cdp-child-development-1681","question":"A child moves from Class 5 in one Kendriya Vidyalaya to Class 6 in another. Which document best helps the new teacher understand her progress over the years in scholastic and co-scholastic areas, health and attendance?","options":["An anecdotal record of a single incident","Her cumulative record","The previous teacher’s daily lesson plan","Her admission form"],"answer":1,"explanation":"A cumulative record gathers information on a pupil across years (achievement, co-scholastic areas, health, attendance) and travels with the child; an anecdotal record captures only one incident.","difficulty":"moderate","source":"KVS PRT · NVS"},
  {"id":"cdp-child-development-1682","question":"According to Hattie and Timperley’s model of feedback levels, which comment on a Class 5 child’s division work operates at the ‘process’ level?","options":["‘Well done, you are a star and a very clever mathematician, the best in the class!’","‘Answer 3 is wrong; the correct answer is 47, so please write it out again neatly in your copy.’","‘You got stuck on large numbers; try estimating first to check if your answer is reasonable.’","‘Your handwriting is very neat, and your work is well laid out.’"],"answer":2,"explanation":"Process-level feedback addresses the strategies used to do the task; ‘Answer 3 is wrong’ is task-level, and ‘you are a star’ is self-level praise, which does least for learning.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1683","question":"A teacher writes: ‘You know the features of a good paragraph. Check your draft against them and decide which one you still need to work on.’ This feedback aims mainly at:","options":["Self-regulation, helping the learner monitor and direct her own work","Praise of the learner as a person, to build up her confidence and self-esteem","The correctness of a single answer in the draft paragraph","Comparison of the learner’s work with that of her peers"],"answer":0,"explanation":"The comment does not correct the work itself; it prompts the learner to check against criteria and decide what to do next, which is the self-regulation level.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1684","question":"A Class 2 report card says only ‘Maths: B’, and a parent cannot tell what the child can or cannot do. A more useful report would:","options":["Give an exact percentage instead of a letter grade, since a number is more precise and easy to track","Add the child’s rank in the class so that parents know where she stands","Add the class average beside her grade, so that parents can judge whether she is above or below the others","Describe what the child can do (e.g. adds two-digit numbers with carrying) and what she is still learning"],"answer":3,"explanation":"Descriptive, criterion-based reporting tells parents what has been learnt and what comes next; percentages, ranks and averages are just other kinds of single numbers.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1685","question":"Which of these are consistent with the original intention of continuous and comprehensive evaluation (CCE)? I. Using assessment information to improve teaching during the year. II. Reducing the weight of a single year-end examination. III. Grading every class activity for the report card. IV. Assessing life skills, attitudes and values along with subjects.","options":["I, II and III only","I, II and IV only","III and IV only","I, II, III and IV"],"answer":1,"explanation":"CCE was meant to make assessment part of teaching, reduce dependence on one exam and cover co-scholastic areas; grading every activity was the distortion that arose in practice.","difficulty":"very-hard","source":"CTET · DSSSB TGT"},
  {"id":"cdp-child-development-1686","question":"Which question for Class 6 history tests ‘evaluating’ in the revised Bloom’s taxonomy?","options":["‘Was Ashoka right to give up war after Kalinga? Judge, using his edicts.’","‘In which year was the battle of Kalinga fought, and who won it?’","‘Describe the battle of Kalinga and its results in your own words.’","‘List all the places in India and abroad where Ashoka’s edicts have been found.’"],"answer":0,"explanation":"Evaluating means making a judgement against criteria or evidence; the others are remembering (year, list) and understanding (describing in one’s own words).","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1687","question":"Which statement best distinguishes Dewey from Montessori?","options":["Dewey stressed individual work with self-correcting materials, while Montessori stressed social, community-based activity","Both rejected the importance of the child’s own activity","Dewey stressed shared problem-solving in a community; Montessori stressed individual work with self-correcting materials","Montessori was a pragmatist philosopher, while Dewey was a medical doctor"],"answer":2,"explanation":"Both were child-centred, but Dewey’s school was a social community solving shared problems, while Montessori’s child worked largely individually in a prepared environment; options A and D swap their features.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1688","question":"Which statement best contrasts Tagore and Gandhi on education?","options":["Tagore made a productive craft the centre of the curriculum, while Gandhi stressed the arts, nature and an international outlook","Gandhi centred education on productive craft and self-reliance; Tagore stressed creative freedom, nature and internationalism","Both opposed teaching through the mother tongue and preferred a classical language","Both wanted English as the medium of instruction in all schools"],"answer":1,"explanation":"Both favoured the mother tongue and rejected colonial rote schooling, but Gandhi’s Nai Talim centred on craft and self-reliance, while Tagore’s emphasis was on freedom, the arts, nature and internationalism.","difficulty":"hard","source":"CTET · State TET"},
  {"id":"cdp-child-development-1689","question":"A Montessori teacher arranges low shelves, child-sized jugs and real brooms so that three-year-olds can pour, sweep and dress themselves. The principle behind this ‘prepared environment’ is that:","options":["Children should be kept busy with chores so that the teacher gets time to rest","Adults should model such tasks first and then do them for young children to prevent spills and mistakes","Real tools teach caution, since minor injuries show children what is dangerous","An orderly, accessible setting lets children act independently and learn through their own activity"],"answer":3,"explanation":"Montessori designed the environment to fit the child so that the child can work independently (‘help me to do it myself’); the adult prepares rather than does.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1690","question":"In Froebel’s kindergarten, ‘occupations’ such as paper folding, clay modelling and weaving differ from ‘gifts’ mainly in that:","options":["Occupations change the material itself (it is cut, folded or moulded), while gifts keep a fixed form","Occupations were meant only for the teachers and the older children, never for the kindergarten itself","Gifts were used as rewards and punishments to control the children’s behaviour","There is no real difference, as both terms refer to the same set of materials"],"answer":0,"explanation":"Froebel’s gifts (ball, blocks and so on) are fixed forms that children arrange; occupations use materials the child transforms, moving from discovery to creative production.","difficulty":"very-hard","source":"KVS PRT · DSSSB PRT"},
  {"id":"cdp-child-development-1691","question":"Gijubhai Badheka was affectionately called ‘Moochhali Maa’ (the mother with a moustache) because:","options":["He ran a hostel for orphaned girls and was a mother figure to them","He wrote books mainly for mothers on how to raise small children","Though a man, he cared for children with a mother’s love and tenderness","He insisted that teachers be strict like fathers but gentle like mothers"],"answer":2,"explanation":"The nickname captures his motherly affection for children; Gijubhai rejected fear and strictness and built his Bal Mandir on love, freedom and joy.","difficulty":"moderate","source":"CTET Paper I · UPTET"},
  {"id":"cdp-child-development-1692","question":"Dewey described education as the continuous reconstruction of experience. A teacher acting on this idea would:","options":["Teach facts once and test whether they are reproduced exactly, so learning is measurable","Help children reorganise what they already know in light of new experiences, so it guides further experience","Set aside children’s prior experiences as unscientific and start afresh with the correct textbook ideas instead","Postpone real learning till adulthood, when a person’s experience of life is complete"],"answer":1,"explanation":"For Dewey, each new experience reorganises earlier ones and increases the ability to direct later ones; learning builds on, rather than ignores, what the child brings.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1693","question":"In a Class 7 test, many good students give different answers to one MCQ because two of its options are defensible. The main effect of such an item is that it:","options":["Raises the item’s discrimination, since only the best students notice both answers","Improves the test’s content validity, by covering two different ideas within one single question","Lowers reliability and validity, as scores partly reflect guessing the setter’s intention","Makes the item easier for everyone, since two answers can be marked right"],"answer":2,"explanation":"An ambiguous item adds random error (lower reliability) and measures something other than the intended learning (lower validity); it usually fails to separate strong from weak students.","difficulty":"moderate","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1694","question":"Assertion (A): Self-assessment by students is unreliable and therefore has no place in school assessment. Reason (R): Without clear criteria, students may over- or under-rate their own work.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"R points to a real risk, but the remedy is to give students clear criteria and practice, not to drop self-assessment, which builds metacognition and is part of NEP 2020’s holistic progress card.","difficulty":"very-hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1695","question":"In ‘The Child and the Curriculum’, Dewey argued that the child’s experience and the organised school subjects are:","options":["Opposed to each other, so the teacher must choose to follow either the child’s own interests or the set subject","Unrelated, since subjects are adult inventions that have nothing to do with children’s lives","Two ends of one process: subject matter is the mature form of the child’s experience, and teaching links them","Relevant only for older students who have already gained enough experience of the world"],"answer":2,"explanation":"Dewey rejected both the subject-centred and the purely child-centred extremes; the task of teaching is to lead the child’s present experience towards the organised knowledge of the subjects.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1696","question":"A Montessori teacher shows a child two tablets and says, ‘This is rough; this is smooth.’ Next she asks, ‘Show me the rough one.’ Finally she asks, ‘What is this?’ This sequence is the:","options":["Herbartian five formal steps, from preparation to application","Three-period lesson: naming, then recognition, then recall","Socratic method of questioning to expose the child’s errors","Project method, built around a purposeful real-life task"],"answer":1,"explanation":"Montessori’s three-period lesson moves from naming (‘This is…’) to recognition (‘Show me…’) to recall (‘What is this?’), going from easier to harder demands.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1697","question":"Arrange these in a sensible sequence for helping a Class 4 group that struggles with division: P. Remedial teaching aimed at the error identified. Q. A diagnostic test to locate the specific difficulty. R. A formative check to see whether the difficulty has been resolved. S. Noticing during class work that the group keeps getting division wrong.","options":["S, Q, P, R","Q, S, P, R","S, P, Q, R","P, Q, S, R"],"answer":0,"explanation":"Classroom observation flags the problem, diagnosis pinpoints its cause, remedial teaching targets it and a follow-up check confirms whether it worked; remediating before diagnosing (option C) is guesswork.","difficulty":"hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-1698","question":"Which of these are features of competency-based assessment? I. Items set in real-life or unfamiliar contexts. II. A focus on applying concepts. III. Questions whose answers can be copied word for word from the textbook. IV. A clear statement of the learning outcomes being assessed.","options":["I and III only","II and III only","I, II and IV only","I, II, III and IV"],"answer":2,"explanation":"Competency-based items assess application of learning outcomes in new contexts; answers lifted verbatim from the textbook test recall, the opposite of competency.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1699","question":"Which practice best reduces bias when a teacher marks essays?","options":["Reading the name first so as to recall each student’s past performance and keep all marks consistent","Marking the essays of strong students first to set a high standard for the rest","Giving extra marks for neat handwriting, since it shows care and effort in the essay","Marking without names, using a rubric, and marking one question across all scripts before the next"],"answer":3,"explanation":"Anonymous marking prevents halo and expectation effects, a rubric anchors judgement, and marking question by question keeps standards consistent across scripts.","difficulty":"hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1700","question":"A teacher rates ‘presentation’ on a 1–5 scale with only the labels ‘poor’ to ‘excellent’, and two teachers using it disagree widely. The best fix is to:","options":["Convert it into a rubric that describes performance at each level","Stretch the scale to 1–10 so that finer differences can be shown","Simply average the two teachers’ ratings to cancel out their bias","Drop presentation from assessment altogether, as it is subjective"],"answer":0,"explanation":"Disagreement comes from undefined levels; describing what each level looks like gives raters a shared standard, whereas a longer scale only adds more undefined points.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1701","question":"At a staff meeting, the principal says, ‘Inclusion is the special educator’s job; class teachers should focus on the syllabus.’ Which response best reflects inclusive education?","options":["Inclusion is a whole-school duty: class teachers plan for all learners, with the special educator as a partner","The principal is right, since special educators alone are trained to teach such children","Class teachers should handle inclusion only during free periods, once the syllabus for the day has been covered","Inclusion is mainly the parents’ responsibility, with the school only providing admission"],"answer":0,"explanation":"Children spend most of their time with class teachers, so inclusion depends on every teacher's planning and attitude; specialists support it but cannot carry it alone.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1702","question":"Assertion (A): Schooling children with disabilities in separate institutions can limit their social participation later in adult life. Reason (R): Children build social skills, friendships and community networks by growing up and learning together.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Separation in childhood denies both groups the shared experiences through which social ties and mutual acceptance develop, which is why segregation can carry into adult life.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1703","question":"Assertion (A): Reasonable accommodation must be decided case by case, according to the needs of the individual child. Reason (R): The RPwD Act requires schools to give an identical set of aids to every child with a disability.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"The Act ties reasonable accommodation to individual requirements, so the right adjustment differs from child to child; an identical package for all is not what it requires.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1704","question":"A pre-primary teacher wants to spot early signs that a child may later have difficulty learning to read. Which observation is most worth noting?","options":["The child is left-handed and holds the pencil awkwardly while drawing","At age 5, the child sometimes writes letters such as b, d and s in mirror image on her slate","The child prefers drawing to listening to stories during circle time","Persistent difficulty recognising rhymes and breaking words into syllables, unlike her peers"],"answer":3,"explanation":"Weak phonological awareness, such as trouble with rhyme and syllables, is a strong early predictor of reading difficulty; left-handedness is irrelevant and mirror writing is common at this age.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1705","question":"Harsh, in Class 5, explains maths reasoning well in untimed oral tasks and solves problems correctly at home, but freezes and leaves blank answers in timed class tests, saying ‘I hate maths.’ What is the most likely explanation and response?","options":["He has dyscalculia, a core difficulty with numbers, and needs an immediate referral for formal assessment now","He is lazy during tests and should be warned that marks will be cut","Maths anxiety is the likelier cause; reduce time pressure, use low-stakes practice and build confidence first","He has an attention disorder, since he does well only at home and not in class"],"answer":2,"explanation":"Sound understanding in relaxed settings with breakdown under timed pressure points to anxiety rather than a core number-processing difficulty like dyscalculia.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1706","question":"A Class 3 teacher with several children who have attention difficulties is framing classroom rules. Which set of rules is likely to work best?","options":["A long list of 15 rules, each starting with ‘Don’t’, so that every possible kind of misbehaviour is covered","Rules decided by the teacher and announced once at the start of the year, then enforced","Rules that change every week so that children stay alert and do not get bored","A few positively stated rules (‘Raise your hand to speak’), shown with pictures and practised regularly"],"answer":3,"explanation":"Few, positive, visible and practised rules give clear guidance that children with attention difficulties can remember and follow; long negative lists are hard to hold in mind.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1707","question":"A Class 4 teacher keeps telling Vihaan, who is autistic, ‘Look at me when I’m talking to you.’ Vihaan becomes anxious and stops following what she says. What is the most appropriate view?","options":["Many autistic children find eye contact distracting and listen better without it; check understanding in other ways","Eye contact must be insisted on firmly, since it shows respect and is the only proof that he is listening","Vihaan is being deliberately disrespectful and should be punished so the class sees it","Vihaan probably has a vision problem that makes eye contact hard, so test his eyes first"],"answer":0,"explanation":"Forcing eye contact can overload an autistic child and reduce attention to the content; understanding is better checked through responses than through gaze.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1708","question":"Which of these statements about Braille are correct? I. Braille is read from left to right by touch. II. When writing with a slate and stylus, the dots are pressed into the reverse side of the paper, so the writer works from right to left. III. Standard literary Braille uses a cell of eight dots.","options":["I only","I and II only","II and III only","I, II and III"],"answer":1,"explanation":"Braille is read left to right; with a slate and stylus the dots are pressed from the reverse side, so writing proceeds right to left in mirror image. The standard literary cell has six dots, not eight.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1709","question":"Assertion (A): Identifying hearing loss in infancy is very important for a child’s language development. Reason (R): The early years are a sensitive period for acquiring language.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because language develops most readily in the early years, a hearing loss found late means lost access during that period; early identification allows timely aids and accessible language.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1710","question":"For months, a teacher has guided the hand of Deepu, a child with intellectual disability, through every step of writing his name. He still cannot start on his own and waits for her hand. What is the problem and the fix?","options":["He is unwilling, so he should be made to try alone from now on without any help","He cannot learn to write, so the goal should be dropped from his plan altogether","He has become prompt-dependent; she should fade help step by step, from hand guidance to a touch, to gestures","He needs even more full hand-over-hand guidance, every day and for longer, until his writing improves by itself"],"answer":2,"explanation":"Prompts that are never faded create prompt dependence; reducing the level of help gradually and rewarding independent attempts builds independence.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1711","question":"A school has eight gifted students spread across four Class 5 sections, and each feels isolated. The school places all eight in one section with a teacher trained to extend them, while the section still has students of all abilities. This arrangement is called:","options":["Grade skipping","Tracking","Pull-out programme","Cluster grouping"],"answer":3,"explanation":"Cluster grouping places a small group of gifted students in an otherwise mixed-ability class so that they have intellectual peers and planned challenge; tracking streams whole classes by ability.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1712","question":"A teacher of a Class 6 section with 60 students says that differentiated instruction is impossible in such a large class. Which response is most realistic?","options":["She is right, so she should teach one way to all and simply accept the results","Differentiation means a separate lesson plan for each of the 60 students, so she first needs an assistant","Flexible groups, tiered tasks, choice of products and structured peer support make it workable even at 60","She should differentiate only for the top ten students, who can benefit the most"],"answer":2,"explanation":"Differentiation does not require individual lessons; grouping, tiering, choice and peer support let a teacher respond to diversity at scale.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1713","question":"For a unit on ‘Our Food’, a Class 4 teacher gives a 3 × 3 grid of tasks, such as writing a recipe, drawing a food chain, interviewing a cook or making a market price chart. Students must complete any three in a line. What does this approach mainly provide?","options":["Choice in how students work and show learning, with all tasks aimed at the same unit goals","A way to rank students by how difficult the tasks they choose turn out to be","A replacement for teaching the unit, since students can now learn everything entirely on their own","Separate goals for each student, matched to the tasks they pick"],"answer":0,"explanation":"A choice board differentiates by interest and learning profile, giving students control over the route while every task addresses the shared learning goals.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1714","question":"Several Class 2 children in a school serving a low-income area are listless and inattentive in the first period, and the teacher learns many come to school without breakfast. What best explains the situation and the right response?","options":["They are lazy and need stricter discipline in the first period to build good habits","They have attention disorders and should all be referred to a specialist for diagnosis and medication","They are not interested in learning, so the first period should be made more fun","Hunger blocks attention and learning, so the school should ensure they get food early, via the meal scheme or a snack"],"answer":3,"explanation":"Basic physical needs must be met before children can attend to learning; hunger-related inattention is solved by food, not by discipline or labels.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1715","question":"Assertion (A): Bringing up a child with two languages causes language delay. Reason (R): A bilingual child’s vocabulary in each single language may be smaller at first, though the total across both languages is comparable to that of monolingual children.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Bilingualism does not cause delay; counting only one language underestimates a bilingual child's vocabulary, so A is false while R is true.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1716","question":"After two years in an English-medium school, Lalita, a Tulu-speaking child, refuses to speak Tulu even with her grandmother, saying it is ‘a village language’. Her English is still weak. Which concept best describes this?","options":["Additive bilingualism, where a second language is added to the first","Subtractive bilingualism, where the new language replaces the first instead of adding to it","Code-switching, moving between Tulu and English within the same conversation","Balanced bilingualism, in which she has roughly equal command of both languages"],"answer":1,"explanation":"When the school language displaces a devalued home language, the child loses the first language without fully gaining the second; additive bilingualism keeps and builds both.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1717","question":"A Class 4 grammar worksheet uses sentences such as ‘Ramu cleans the drain’ and ‘Rohit is an engineer’, with names that, in the local context, are linked to caste and class. What is the concern?","options":["There is no concern, since the sentences are grammatically correct and such names are common in the area","Such examples quietly link some communities to low-status work and others to prestige, reinforcing stereotypes","The names are too difficult for Class 4 children to read and spell correctly","The worksheet should use only English names so that it is neutral and modern"],"answer":1,"explanation":"Teaching materials carry social messages; repeatedly pairing certain names with certain jobs reinforces hierarchies, so examples should be chosen to avoid such patterns.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1718","question":"A Class 1 teacher insists that Zainab, who naturally writes with her left hand, must switch to her right hand, and scolds her when she does not. Which evaluation is correct?","options":["The teacher is right, since writing with the right hand is the correct, standard way taught in all good schools","It is acceptable, as long as the parents agree with the teacher’s decision","Left-handedness is natural; forcing a switch can cause frustration and slow writing, so support her left hand","Zainab may use either hand, but her left-handed work should be marked lower"],"answer":2,"explanation":"Handedness is a natural difference, not an error; respecting it, with suitable seating and pencil grip, is part of accepting diversity in class.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-1719","question":"Which of these statements are correct? I. The RTE Act, 2009 requires private unaided schools to admit children from weaker sections and disadvantaged groups in at least 25% of entry-level seats. II. The RPwD Act, 2016 requires government and government-aided higher education institutions to reserve not less than 5% of seats for persons with benchmark disabilities. III. The RPwD Act requires private unaided schools to reserve 25% seats exclusively for children with disabilities.","options":["I and II only","II and III only","I only","I, II and III"],"answer":0,"explanation":"RTE's 25% entry-level provision covers weaker sections and disadvantaged groups, and the RPwD Act reserves at least 5% of seats in government and aided higher education institutions; there is no 25% disability-only quota.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1720","question":"Assertion (A): Autistic children do not want to have friends. Reason (R): Many autistic children find it hard to read social cues and unwritten rules of interaction.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Many autistic children want friendships but struggle with how to make and keep them because social cues are hard to read; so A is false while R is true.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1721","question":"A new Class 5 teacher avoids saying words like ‘see’ and ‘look’ in front of Ayesha, who is blind, and gets flustered when she slips. Which advice is most appropriate?","options":["She should carefully replace every such word with ‘touch’ or ‘hear’ whenever Ayesha is present in class","She should avoid talking directly to Ayesha so that such slips do not upset her","She should ask the whole class never to use such words near Ayesha, to protect her feelings","She can use words like ‘see’ and ‘look’ naturally, as blind people do; what matters is describing visuals clearly"],"answer":3,"explanation":"Blind people use ‘see’ and ‘look’ in ordinary speech; avoiding them only creates awkwardness, while clear verbal description is what gives real access.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1722","question":"Ishita, a Class 8 student with hearing impairment, cannot watch the teacher’s face and take notes at the same time, so she misses either the lesson or the notes. Which support is best?","options":["Asking her to write faster, using abbreviations, so that she can watch the teacher and still keep up","Arranging a peer note-taker or giving printed notes, so she can keep her eyes on the speaker","Asking her to copy a classmate’s notes during the next period instead","Letting her skip note-taking altogether and rely only on the textbook"],"answer":1,"explanation":"Speech-reading needs constant visual attention, which competes with writing; providing notes removes this conflict without lowering the content.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1723","question":"In a Class 5 science lesson on plants, the class studies plant parts and their functions in detail. Bhola, who has intellectual disability, works alongside them in the same activity, learning to name the main parts and to water and care for the class plant. This approach is best described as:","options":["Segregation within the class, since his goals and tasks are kept separate from everyone else’s","Multi-level teaching: children work on the same topic and activity towards different goals suited to them","Tracking, placing him in a lower stream for science","Curriculum compacting, letting him skip parts of the content he has already mastered"],"answer":1,"explanation":"Multi-level teaching (curriculum overlapping) keeps the child in the shared lesson while his goals are set at his level; he is not removed or given an unrelated task.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1724","question":"Assertion (A): Before a gifted child skips a grade, her social and emotional readiness should be considered along with her academic ability. Reason (R): Acceleration always harms gifted children.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A careful decision weighs academic, social and emotional factors and the child's own wishes; for well-chosen students acceleration is often successful, so the claim that it always harms is false.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-1725","question":"In a Class 6 class, several children tease a dark-skinned classmate, calling her ‘kali’ and saying fair skin is beautiful. What is the most appropriate response?","options":["Stopping the teasing as discrimination and discussing how colour-based beauty ideas are prejudices that hurt","Telling the girl to ignore it and stay calm, since the other children mean it only as a harmless joke","Advising her parents to try fairness creams so the teasing stops","Ignoring it, since children usually outgrow such remarks as they get older"],"answer":0,"explanation":"Colour-based teasing reflects a deep social prejudice and harms self-esteem; the teacher must stop it and help children question the bias behind it.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-1726","question":"A nine-year-old who dropped out after Class 1 re-enrols in a government school and is placed in an age-appropriate class. Under the RTE Act, the special training she is entitled to should be:","options":["Given only in a separate residential school, where she must stay until she turns 14 and finishes Class 8","Organised so she can catch up and join her age-appropriate class, preferably on the school premises","Replaced by simply placing her in Class 1 with six-year-olds to start afresh","Given only after she passes an admission test showing her level"],"answer":1,"explanation":"Section 4 and the rules under it treat special training as a bridge that helps an out-of-school child join her age-appropriate class; it is not a reason to segregate, test or demote her.","difficulty":"hard","source":"CTET · UPTET · REET"},
  {"id":"cdp-child-development-1727","question":"A private school continues to run without a certificate of recognition after the RTE Act came into force. Which statement is correct under the Act?","options":["It may keep running as long as it follows the prescribed CBSE syllabus and uses NCERT textbooks in all classes","It may keep running if it admits 25% children from disadvantaged groups every year","It cannot run without recognition; the fine is up to ₹1 lakh, plus up to ₹10,000 per day if it continues","Only government and aided schools need a certificate of recognition under the Act"],"answer":2,"explanation":"Section 18 requires every non-government school covered by the Act to obtain recognition, with fines for running without it; the 25% quota and syllabus have nothing to do with recognition.","difficulty":"very-hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1728","question":"Assertion (A): Dewey accepted Froebel’s emphasis on play and the child’s self-activity. Reason (R): Dewey also endorsed the mystical, symbolic meanings that Froebel attached to his gifts.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Dewey praised Froebel’s respect for play and self-activity but criticised his abstract symbolism, arguing that play should be grounded in the child’s actual social life.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT"},
  {"id":"cdp-child-development-1729","question":"Gandhi’s scheme was called ‘Basic’ Education mainly because:","options":["It taught only the basics of reading, writing and arithmetic to village children","It was meant only for the lowest classes of a school, before the formal academic subjects were begun","It was a short basic course to be followed by English-medium schooling in towns","It was rooted in the basic crafts and needs of village life, as the foundation of national education"],"answer":3,"explanation":"‘Basic’ referred to education grounded in the fundamental crafts and needs of the people, forming the base of national education, not to a minimal literacy course.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1730","question":"When a high-stakes board examination tests mainly recall, teachers start drilling students on past papers and skipping projects and discussion. This influence of an examination on teaching is called the:","options":["Washback (backwash) effect","Halo effect in marking","Hawthorne effect of observation","Pygmalion (expectancy) effect"],"answer":0,"explanation":"Washback is the effect a test has on teaching and learning; NCF 2005 and NEP 2020 want board exams reformed partly so that their washback encourages understanding rather than rote drill.","difficulty":"hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1731","question":"Consider: I. In a criterion-referenced test, every student in a class can get the top grade. II. A norm-referenced test suits situations where a fixed number of candidates must be selected. III. A criterion-referenced test reports each student’s percentile rank in the group. Which are correct?","options":["I only","I and II only","II and III only","I, II and III"],"answer":1,"explanation":"Criterion-referenced results compare each student with a standard, so all can reach it; percentile ranks belong to norm-referenced reporting, which suits selection, so III is wrong.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1732","question":"Ms. Bano judges whether her new reading circles worked by looking at children’s test scores, her own observation notes and short interviews with the children. Using several sources of evidence in this way is called:","options":["Randomisation","Standardisation","Generalisation","Triangulation"],"answer":3,"explanation":"Triangulation cross-checks a finding through different kinds of data; when scores, observation and interviews agree, the teacher-researcher’s conclusion is more credible.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1733","question":"Tagore modelled Santiniketan partly on the ancient Indian ashram (tapovan) ideal. This implies:","options":["Teachers and students living simply together close to nature, learning through a shared life","A strict separation between teachers and students, with lessons held only in formal classrooms","Learning only the scriptures by rote under a single strict guru","Military-style discipline and drill in a remote forest camp"],"answer":0,"explanation":"Tagore drew on the forest-hermitage tradition, where pupils and teachers lived together close to nature; he combined it with freedom, the arts and an international outlook.","difficulty":"hard","source":"CTET · State TET"},
  {"id":"cdp-child-development-1734","question":"Which limitation applies most to true–false items in a classroom test?","options":["They cannot be scored objectively, since different teachers may disagree about the right answer","They take students a long time to answer compared with other item types","With only two choices, guessing succeeds half the time, and such items often test trivial facts","They cannot be used in subjects such as mathematics or science at all"],"answer":2,"explanation":"True–false items are quick and objective to score, but the high chance of guessing lowers reliability, and they tend to test isolated facts rather than understanding.","difficulty":"moderate","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1735","question":"A Class 10 mathematics test is so long that most students cannot finish it, and careful, able students often score lower than quick but careless ones. The main problem is that:","options":["The test is too reliable, giving the same rank order whatever students know","Speed has become a construct-irrelevant factor, lowering validity as a measure of understanding","The test is criterion-referenced, so it cannot separate able students from weak or careless ones","The test has high face validity, which always reduces its true validity"],"answer":1,"explanation":"If the aim is to measure understanding, working speed is irrelevant to that construct; an unintended speed test rewards the wrong quality and so distorts what scores mean.","difficulty":"hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1736","question":"In a village school, Dalit children are made to sit separately during the mid-day meal. Under the RTE Act, this violates:","options":["The duty of government and local authorities to ensure that disadvantaged children are not discriminated against","Nothing in the RTE Act, since seating during the mid-day meal is purely an internal school matter","Only criminal law, since the RTE Act itself says nothing at all about discrimination against any group of children","Section 28 on private tuition, which covers teachers’ conduct in school"],"answer":0,"explanation":"Sections 8 and 9 oblige the government and local authority to ensure that children of weaker sections and disadvantaged groups are not discriminated against; segregation at meals is exactly such discrimination.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-1737","question":"NEP 2020’s idea of school complexes or clusters mainly aims to:","options":["Place all the government schools in a block under a single private management company to cut running costs","Increase the number of board examinations that students must take each year","Let nearby schools share teachers, libraries, labs and counsellors, reducing the isolation of small schools","Replace anganwadis with primary schools so that pre-school ends"],"answer":2,"explanation":"NEP 2020 notes that many schools are very small and isolated; grouping them into complexes lets them share teachers and facilities and builds a professional community.","difficulty":"hard","source":"CTET · KVS PRT"},
  {"id":"cdp-child-development-1738","question":"A Class 4 student asks, ‘Why does our textbook show only city families with cars?’ In the spirit of NCF 2005, the teacher should:","options":["Tell the student that the textbook has been approved by experts and so must not be questioned in class","Ignore the question and continue the lesson so that the syllabus is not delayed","Ask the student to raise such points only after school, so the class is not disturbed","Welcome the question, discuss whose lives the book shows and leaves out, and add examples from children’s lives"],"answer":3,"explanation":"NCF 2005 values children’s questions and experiences and wants the curriculum to reflect diverse lives; a critical question is a learning opportunity, not indiscipline.","difficulty":"moderate","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1739","question":"A teacher inspired by Dewey would expect good discipline in class to come mainly from:","options":["Children’s fear of punishment if they break the class rules","Children’s absorption in shared, purposeful work in which each has a role","Strict rules of silence that the teacher enforces firmly and consistently all day","Rewards for obedience, such as stars and extra play time"],"answer":1,"explanation":"Dewey saw discipline as growing out of engagement in a common task, as in any working community; order imposed by fear or bribes is external and short-lived.","difficulty":"hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1740","question":"Which of these is NOT one of the key strategies of formative assessment described by Dylan Wiliam?","options":["Clarifying and sharing learning intentions and success criteria","Giving feedback that moves learners forward","Ranking students publicly after every test to motivate them","Activating students as owners of their own learning and as resources for one another"],"answer":2,"explanation":"Wiliam’s strategies include sharing intentions, engineering effective discussions and questions, feedback that moves learning forward, and activating peers and the learners themselves; public ranking undermines formative assessment.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-child-development-1741","question":"Which Class 7 mathematics task mainly targets ‘applying’ in the revised Bloom’s taxonomy?","options":["‘State the formula for the area of a rectangle.’","‘How many 30 cm × 30 cm tiles are needed to cover a floor measuring 3 m × 4.5 m?’","‘Devise and justify a new method for finding the area of any irregular shape you like.’","‘Explain in your own words what area means.’"],"answer":1,"explanation":"Applying means using a known procedure in a given situation (here, area and unit conversion, giving 150 tiles); stating is remembering, explaining is understanding and devising a new method is creating.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1742","question":"Which routine best builds assessment AS learning in a Class 4 classroom?","options":["Children end each day writing in a learning log what they learnt, what puzzled them and what to try next","The teacher marks a short test every Saturday and returns it on Monday with grades and corrections","A rank list of the class is displayed on the notice board every month so that all can see their progress","Parents check and sign the homework diary daily to keep track"],"answer":0,"explanation":"Assessment as learning develops the learner’s own monitoring of learning; a reflective learning log does this, whereas teacher marking, ranking and parental checks keep the learner passive.","difficulty":"hard","source":"CTET Paper I · State TET"},
  {"id":"cdp-child-development-1743","question":"Under NEP 2020, early childhood care and education (ECCE) is to be delivered through:","options":["Private play schools only, licensed and regulated by each state government","Grade 1 classrooms only, with ECCE merged fully into formal primary teaching from age five","Home tutoring by parents alone, supported by television lessons","Strengthened anganwadis and stand-alone or co-located pre-schools (Balavatikas), with trained staff"],"answer":3,"explanation":"NEP 2020 proposes universal ECCE through strengthened anganwadis and pre-schools, including those co-located with primary schools, staffed by trained ECCE workers and teachers.","difficulty":"hard","source":"CTET Paper I · KVS PRT"},
  {"id":"cdp-child-development-1744","question":"The 2012 amendment to the RTE Act made provision for children with disabilities. Under it, a child with multiple or severe disabilities:","options":["Is excluded from the coverage of the Act entirely","May also have the right to opt for home-based education","Must attend a special school only, not a regular school","Gets free education only till the age of ten years"],"answer":1,"explanation":"The 2012 amendment brought children with disabilities within the Act and allowed those with multiple or severe disabilities to also opt for home-based education; it did not exclude or segregate them.","difficulty":"very-hard","source":"CTET · DSSSB PRT"},
  {"id":"cdp-child-development-1745","question":"Assertion (A): Nai Talim aimed at the harmonious development of the head, the heart and the hand. Reason (R): Gandhi held that a craft taught scientifically, with the child learning the why and how of each process, develops the intellect as well as the hand.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Gandhi insisted that craft be taught not mechanically but scientifically, so that manual work became a route to intellectual and moral growth, which is how Nai Talim sought to develop head, heart and hand together.","difficulty":"very-hard","source":"CTET Paper II · UPTET"},
  {"id":"cdp-child-development-1746","question":"A teacher video-records her Class 9 lesson and notices that she called on boys four times as often as girls. The most reflective next step is to:","options":["Delete the video and forget about it, since one lesson proves nothing","Conclude that the girls are simply less interested in the subject, so calling on them would embarrass them","Plan a strategy such as random name sticks and longer wait time, then record another lesson to check","Ask the boys to speak less in future so that girls get more chances"],"answer":2,"explanation":"Reflective practice turns evidence into a planned change and then checks the result; blaming the girls or the boys skips the examination of her own questioning habits.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1747","question":"A father in Jaipur keeps his ten-year-old daughter at home to look after her younger siblings. Which RTE provision does this most directly conflict with?","options":["Section 10, which makes it the duty of every parent or guardian to admit the child to elementary education","Section 28, which bars teachers from giving private tuition to their own students","Section 27, which limits the deployment of teachers for non-educational work like the census","Section 23, which lays down the minimum qualifications required for appointing teachers in all schools"],"answer":0,"explanation":"Section 10 (echoing Article 51A(k)) places on parents and guardians the duty to get their children aged 6–14 admitted to elementary education.","difficulty":"hard","source":"CTET · REET"},
  {"id":"cdp-child-development-1748","question":"A teacher has Class 5 children colour pictures of the planets for an hour and calls it ‘learning by doing’. A Deweyan critique would be that:","options":["Colouring is the best form of learning in science, since children enjoy it and remember the planets’ colours","Dewey opposed all hands-on work in school as a waste of learning time","Science should be taught only through lectures, with activities left for art class","Activity is educative only when it involves thinking about a problem and its consequences, not busy handwork"],"answer":3,"explanation":"For Dewey, ‘doing’ matters because it engages reflective thought about a real problem; hands-on activity without minds-on inquiry is just busywork.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT"},
  {"id":"cdp-child-development-1749","question":"A Class 6 child with dyslexia understands science well but scores poorly on written tests. Which adaptation keeps the assessment valid while making it fair?","options":["Asking her easier science questions than the rest of the class, so that she is sure to score well this time","Exempting her from science assessment altogether because of her dyslexia","Grading her mainly on her handwriting and spelling to improve them","Giving extra time, reading questions aloud or allowing oral answers, on the same science concepts"],"answer":3,"explanation":"Accommodations remove barriers unrelated to what is being measured (reading and writing) while the construct, science understanding, stays the same; easier questions would change what is assessed.","difficulty":"hard","source":"CTET · KVS TGT"},
  {"id":"cdp-child-development-1750","question":"A Class 6 child writes ‘0.25 is greater than 0.3, because 25 is greater than 3’. The best formative response is to:","options":["Mark it wrong and write the correct answer beside it in red ink so that he can study it at home that evening","Make him repeat the rule ‘compare the tenths digit first’ ten times until he remembers it","Use place-value charts or shaded grids to show tenths and hundredths, then ask him to compare and explain","Move on, since it is only a minor slip that he will correct later"],"answer":2,"explanation":"The error reveals a misconception (treating decimals as whole numbers, ‘longer is larger’); a representation that exposes place value lets the child rebuild the idea, which correction or drill cannot do.","difficulty":"hard","source":"CTET Paper II · KVS TGT"},
  {"id":"cdp-child-development-1751","question":"Before a debate, a teacher tells nervous Class 9 students: ‘First your heart pounds and your hands shake; the feeling of fear is simply your awareness of those bodily changes, so steady your breathing and the fear will ease.’ Her explanation follows which theory of emotion?","options":["The Cannon–Bard theory","The James–Lange theory","The Schachter–Singer two-factor theory","Lazarus’s cognitive appraisal theory"],"answer":1,"explanation":"James–Lange holds that the felt emotion is the perception of bodily changes, so changing the body should change the feeling. Cannon–Bard makes arousal and feeling simultaneous and independent, and the two-factor theory adds a cognitive label for the arousal.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1752","question":"Two Class 10 students sprint up three flights of stairs and arrive breathless at the exam hall. Asha joins classmates nervously discussing ‘impossible’ questions and feels her racing heart as panic; Bina joins friends joking about the exam and feels the same racing heart as eager excitement. Which theory best accounts for the two different emotions?","options":["Cannon–Bard theory: the thalamus sends arousal and feeling to body and cortex at once","James–Lange theory: each emotion has its own distinct pattern of bodily changes","Schachter–Singer two-factor theory: the same arousal is labelled using cues from the situation","Facial feedback hypothesis: the expressions the girls happen to make produce their feelings"],"answer":2,"explanation":"The same unexplained arousal took different emotional labels from the social context, which is the heart of the two-factor theory; James–Lange would need different bodily patterns for panic and excitement.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1753","question":"Which pair of objections to the James–Lange theory led Walter Cannon, with Philip Bard, to propose a different account of emotion?","options":["Facial muscles, not the viscera, carry the signals that the brain reads as fear, anger or joy","Emotions depend on how arousal is labelled, and the labels are learnt mainly from the people who are nearby at the time","Feelings arise only after a person judges whether an event threatens them and whether they can cope","Very different emotions share similar bodily arousal, and visceral changes are too slow to be the source of feelings"],"answer":3,"explanation":"Cannon argued that the same visceral arousal accompanies fear, anger and even excitement, and that the viscera respond too slowly to produce a sudden feeling; so he proposed that arousal and feeling arise together. The other options describe two-factor, appraisal and facial-feedback ideas.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1754","question":"Before her board practical, Nisha thinks, ‘This practical carries 30 marks, so it really matters to me,’ and then, ‘But I have rehearsed every experiment and the lab assistant will help if equipment fails.’ In Richard Lazarus’s theory, her second thought is:","options":["Secondary appraisal, an evaluation of her resources and options for coping","Primary appraisal, a judgement of whether the event matters to her well-being","Reappraisal, a later revision of her first judgement after the practical is over","Cognitive labelling, naming her bodily arousal from cues given by people around her"],"answer":0,"explanation":"Primary appraisal asks ‘Does this matter to me?’ and secondary appraisal asks ‘What can I do about it?’; weighing rehearsal and available help is secondary appraisal. Reappraisal needs new information after the event, and labelling arousal belongs to the two-factor theory.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1755","question":"Before presenting a project, Arjun tells himself, ‘This is a chance to show what I found, not a test of my worth,’ while Kabir keeps a straight face and hides his nervousness from everyone. Research on emotion regulation (James Gross) suggests that, compared with Kabir’s strategy, Arjun’s is more likely to:","options":["Raise his arousal, because thinking about the situation keeps the emotion active for longer","Lower his visible signs of nervousness while leaving his inner feeling and arousal unchanged","Work only after the talk, since reappraisal acts once the emotion has fully run its course","Lower the nervousness he actually feels without taxing his memory of the presentation"],"answer":3,"explanation":"Reappraisal changes the meaning of a situation early and so reduces the felt emotion; expressive suppression (Kabir) hides the expression but leaves arousal high and tends to impair memory for the event. Option two describes suppression, not reappraisal.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1756","question":"Seven-year-old Tara opens a birthday gift of socks she does not want, smiles and says, ‘Thank you, Aunty, I love it.’ Her behaviour shows that she has learnt:","options":["Social referencing, reading other people’s faces to judge an unfamiliar event","Display rules, the cultural norms about which emotions to show and when","Reaction formation, unconsciously turning a feeling into its opposite","Emotional contagion, automatically taking on the mood of those nearby"],"answer":1,"explanation":"She feels disappointment but deliberately shows pleasure because a social norm asks for it, which is a display rule. Reaction formation is an unconscious defence, not a deliberate, socially guided mask.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1757","question":"On her first day in Class 1, Mehak sees a large, noisy robot toy in the activity corner. She stops, looks at her teacher’s face, and moves towards the toy only after the teacher smiles and nods. Which developmental process is she using?","options":["Joint attention","Secure-base exploration","Social referencing","Observational learning"],"answer":2,"explanation":"Social referencing is using another person’s emotional expression to decide how to respond to an ambiguous situation. Secure-base exploration is exploring with the attachment figure nearby and returning to her; joint attention is simply sharing focus on the same object.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT"},
  {"id":"cdp-child-development-1758","question":"According to Katharine Bridges’ classic observations of infants, a newborn’s emotional life begins with:","options":["General excitement, which later branches into distress and then delight","Three innate emotions, fear, rage and love, all fully present at the moment of birth","Distress alone, with pleasure appearing only after the first year","Pleasure and pain as two separate emotions from the very first day"],"answer":0,"explanation":"Bridges described emotions as differentiating out of an undifferentiated excitement, first into distress and then delight, and later into finer emotions. Fear, rage and love as innate emotions was J. B. Watson’s view.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1759","question":"Joy, anger and fear are seen in the first months of life, but pride, shame and embarrassment appear only from about the second year. The best explanation is that these later emotions require:","options":["Fluent language, since a child cannot feel an emotion before she can name it","Self-awareness and some sense of standards against which the self is judged","Concrete operational thought, which Piaget placed at about seven years","Direct teaching of manners, without which such feelings never arise"],"answer":1,"explanation":"Self-conscious emotions depend on recognising oneself (seen around 18 months in the mirror test) and evaluating one’s acts against rules. They appear well before seven and before language is fluent, so the other options misplace the cause.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1760","question":"Arjun, in Class 3, tears Rani’s storybook during a quarrel. Which teacher response is most likely to produce constructive guilt rather than shame?","options":["‘Don’t worry, Arjun, it is only a book; I will get Rani a new one myself.’","‘I am disappointed in you, Arjun; you are usually such a good and kind boy.’","‘Rani is upset because her book is torn. What could you do to help put it right?’","‘Go and sit quietly in the corner for ten minutes and think about what you have done.’"],"answer":2,"explanation":"Guilt that leads to repair arises when attention is on the act and its effect on another person; comments on the child’s whole self push towards shame, while rescuing or isolating him offers no path to making amends.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1761","question":"After losing a heated inter-house match, Class 7 boys fight far more often when toy guns and wrestling posters are around the hostel common room than when they are not. Which account explains this best?","options":["Aggression is an instinctive drive that builds up and must be drained through vigorous games","Frustration always leads to aggression, and every act of aggression is caused by some frustration","Aggression is learnt only by watching models who are rewarded, so frustration plays no part in it","Frustration creates anger, a readiness to aggress, and aggressive cues nearby make an attack more likely"],"answer":3,"explanation":"Berkowitz revised the frustration–aggression hypothesis: frustration produces anger, and cues associated with aggression raise the chance that it is acted on. The second option is the original strong form of Dollard’s hypothesis, which this revision rejected.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1762","question":"To help angry children ‘get the anger out of their system’, a teacher lets them punch a pillow while thinking about the classmate who upset them. What does research on venting suggest?","options":["Venting while dwelling on the provocation tends to keep anger high or raise it further","Venting drains anger as the catharsis idea predicts, if done soon after the provocation","Venting helps boys release anger but not girls, whose anger is mostly expressed in words","Venting helps only children under eight, whose anger is mostly physical rather than verbal"],"answer":0,"explanation":"Studies of venting (for example Bushman’s pillow-punching experiments) found that hitting while ruminating on the provoker left people angrier and more aggressive; calming down, distraction and reappraisal work better than catharsis.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1763","question":"Match each situation with Kurt Lewin’s type of conflict. P. Choosing between two equally exciting summer camps. Q. Having either to own up to the teacher now or to be caught later. R. Wanting to be class monitor for the status but dreading the extra duties of that same post. S. Choosing between science (good career but heavy load) and arts (enjoyable but parents disapprove). 1. Avoidance–avoidance 2. Approach–approach 3. Double approach–avoidance 4. Approach–avoidance","options":["P-2, Q-4, R-1, S-3","P-2, Q-1, R-4, S-3","P-3, Q-1, R-4, S-2","P-2, Q-1, R-3, S-4"],"answer":1,"explanation":"Two attractive camps is approach–approach; two unpleasant outcomes is avoidance–avoidance; one goal with both pull and push is approach–avoidance; two alternatives that each have good and bad sides is double approach–avoidance.","difficulty":"very-hard","source":"DSSSB TGT · KVS TGT"},
  {"id":"cdp-child-development-1764","question":"Weeks ago, Rohit eagerly volunteered to speak at assembly. As the day approaches he wants to withdraw, though he still values the chance. According to Neal Miller’s analysis of approach–avoidance conflict, this happens because:","options":["Both tendencies stay fixed, but tiredness makes the unpleasant side of the goal feel bigger","The approach tendency rises more steeply than the avoidance tendency as the goal gets nearer","The avoidance tendency rises more steeply than the approach tendency as the goal gets nearer","Approach and avoidance cancel out at a distance, so he feels nothing until the final day"],"answer":2,"explanation":"Miller showed that both tendencies grow as a goal nears, but the avoidance gradient is steeper; far away, approach dominates, close up, avoidance overtakes it, which produces late hesitation and vacillation.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1765","question":"Two-year-old Gauri sees her teacher looking sad and brings her own favourite soft toy to comfort her. In Martin Hoffman’s account of empathy development, this shows:","options":["Mature perspective-taking: she infers exactly what the teacher needs","Global empathy: she cannot yet tell whether the distress she feels is hers or another’s","Empathy for another’s life condition, beyond the immediate situation","Egocentric empathy: she feels for another but offers what would comfort herself"],"answer":3,"explanation":"In Hoffman’s sequence the toddler knows the distress is someone else’s but still assumes others want what she wants, so she offers her own comfort object. Global empathy is the infant’s confusion of self and other, and concern for life conditions comes in late childhood.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1766","question":"Test anxiety is often split into a worry component and an emotionality component. Which is more consistently linked with lower test scores?","options":["The worry component: self-doubting thoughts that occupy working memory during the test","The emotionality component: sweating, a racing heart and ‘butterflies’ during the test","Both equally, since anxious thoughts and bodily signs always rise and fall together","The avoidance component: skipping revision so that failure can be blamed on lack of effort"],"answer":0,"explanation":"Research since Liebert and Morris finds that the cognitive worry component predicts poorer performance more strongly than bodily emotionality, because worry competes for working-memory capacity. The ‘avoidance component’ describes self-handicapping, not a standard part of test anxiety.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1767","question":"Years later, students vividly ‘remember’ where they were when they heard about a dramatic national event, and they are very confident about it. Research on such flashbulb memories shows that they are:","options":["Photographic records that stay accurate in every detail because strong emotion fixes them","Vivid and confidently held, yet often no more accurate than ordinary memories of the same age","Accurate for the central event but never for personal details such as where one was","Lost faster than ordinary memories, since strong emotion blocks storage in long-term memory"],"answer":1,"explanation":"Studies that tested people soon after events and again years later found flashbulb memories change and contain errors much like everyday memories; what stays high is vividness and confidence, not accuracy.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1768","question":"A toddler calms when her caregiver rocks her; by school age she distracts herself or talks herself through a scary injection. This change is best described as a shift from:","options":["Expressive suppression in infancy to reappraisal, which is present from birth","Self-regulation in infancy to dependence on peers for comfort in childhood","Co-regulation of emotion by adults to increasingly independent self-regulation","Social referencing in infancy to display rules as the child’s language grows"],"answer":2,"explanation":"Early emotion regulation is largely external, done by caregivers; with language, attention control and experience children take over these strategies themselves. Reappraisal is not present at birth and display rules concern expression, not soothing.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1769","question":"Riya, in Class 2, cries, ‘I hate maths!’ over a sheet of sums. In John Gottman’s terms, which teacher response is emotion coaching?","options":["‘Big girls handle mistakes calmly. Take a deep breath, stop crying and finish the sheet.’","‘It’s okay to feel that way, Riya; you can skip maths for today and do some drawing instead.’","‘Cheer up! Here’s a sticker for trying. Now let’s get back to the sums with a smile.’","‘You’re really frustrated with these sums. Let’s find the step that’s stuck and try it together.’"],"answer":3,"explanation":"Emotion coaching names and accepts the feeling and then helps the child solve the problem. Accepting the feeling without any guidance is Gottman’s laissez-faire style, distracting with a sticker is dismissing, and telling her to stop crying is disapproving.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1770","question":"Which sequence of typical children’s fears, from infancy to adolescence, is most accurate?","options":["Loud noises and strangers → the dark and imaginary creatures → injury and school failure → social rejection and looks","The dark and imaginary creatures → loud noises and strangers → social rejection and looks → injury and school failure","Loud noises and strangers → injury and school failure → the dark and imaginary creatures → social rejection and looks","Social rejection and looks → loud noises and strangers → the dark and imaginary creatures → injury and school failure"],"answer":0,"explanation":"Infant fears centre on sudden stimuli and strangers; pre-schoolers, who mix fantasy and reality, fear the dark and monsters; school-age fears become realistic (injury, failure); adolescents fear social evaluation and appearance.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1771","question":"Assertion (A): Many five-year-olds insist that a child cannot feel happy and sad at the same time about one event, such as moving to a new house. Reason (R): Young children tend to centre on one salient aspect of a situation at a time.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Research by Susan Harter and others shows understanding of mixed emotions develops gradually in middle childhood; the young child’s difficulty is linked to centration, attending to one feeling at a time.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1772","question":"A Class 4 teacher uses a ‘feelings chart’ on which children point to and name what they feel before a test. Research on affect labelling suggests this helps mainly because:","options":["It mainly widens vocabulary, which shows up as better marks in language tests","Naming a feeling makes it stronger, so children get it fully out of their system","Children who name a feeling stop experiencing it altogether after a few weeks","Putting a feeling into words tends to dampen its intensity and supports regulation"],"answer":3,"explanation":"Studies of affect labelling find that naming one’s emotion reduces its intensity and the brain’s threat response, so it is a simple regulation tool; it does not ‘discharge’ or abolish the feeling.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT"},
  {"id":"cdp-child-development-1773","question":"Rahul, in Class 2, pushes a classmate aside to get the first turn on the swing, though he is not angry with her and does not want to hurt her. This is best described as:","options":["Hostile (reactive) aggression","Instrumental aggression","Relational aggression","Displaced aggression"],"answer":1,"explanation":"Instrumental aggression uses harm as a means to an object or goal; hostile aggression aims at hurting the person, relational aggression damages relationships, and displaced aggression redirects anger onto a safer target.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1774","question":"A school’s anti-bullying rule says only, ‘No hitting, kicking or pushing.’ Which form of aggression, common among upper-primary children, does it leave out?","options":["Hostile aggression, such as kicking a child who teased you, out of anger","Instrumental aggression, such as pushing someone aside in the line to get a turn first","Relational aggression, such as spreading rumours and deliberately excluding a classmate","Reactive aggression, such as hitting back at someone who hit you first"],"answer":2,"explanation":"All the other options involve physical acts the rule already bans; relational aggression harms through relationships and reputation, rises in middle childhood, and needs its own rules and monitoring.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1775","question":"Before a brainstorming session, a teacher plays a short funny clip to her Class 8. Barbara Fredrickson’s broaden-and-build theory predicts that mild positive emotion will:","options":["Widen the range of thoughts and actions students consider, helping creative solutions","Narrow attention onto the single most important detail, helping careful accuracy","Speed up recall of facts while leaving the variety of ideas students produce unchanged","Help only those students who were already in a good mood before the clip"],"answer":0,"explanation":"Fredrickson proposed that positive emotions broaden the momentary repertoire of thought and action, which supports flexible, creative thinking; it is negative emotions like fear that narrow attention.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1776","question":"A Class 3 teacher tells children who dislike writing, ‘Finish your four lines of handwriting first, and then you may play carrom.’ Carrom is something they choose often on their own. Which principle is she using?","options":["The Premack principle","Negative reinforcement","The overjustification effect","Shaping by successive approximation"],"answer":0,"explanation":"The Premack principle uses a high-probability (preferred) activity to reinforce a low-probability one. Nothing unpleasant is being removed, so it is not negative reinforcement, and no step-by-step approximations are rewarded.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1777","question":"Match each student’s reason for studying biology with the type of motivation in Deci and Ryan’s self-determination theory. P. ‘So that Papa does not take away my phone.’ Q. ‘I would feel guilty and ashamed if I didn’t.’ R. ‘Biology matters for my aim of becoming a nurse.’ S. ‘I love working out how cells function.’ 1. Identified regulation 2. Intrinsic motivation 3. External regulation 4. Introjected regulation","options":["P-4, Q-3, R-1, S-2","P-3, Q-4, R-1, S-2","P-3, Q-1, R-4, S-2","P-3, Q-4, R-2, S-1"],"answer":1,"explanation":"Studying to avoid a penalty is external regulation; acting to avoid guilt or protect self-worth is introjected; valuing the activity for a personal goal is identified; doing it for its own enjoyment is intrinsic. Introjected regulation is the trap, as it is internal but still pressured.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1778","question":"Before a class quiz, Shalini says, ‘My main aim is just not to look stupid in front of everyone.’ In the 2 × 2 achievement-goal framework, her goal is:","options":["Mastery-approach","Performance-approach","Mastery-avoidance","Performance-avoidance"],"answer":3,"explanation":"Her standard is comparison with others (performance) and her focus is on avoiding a negative outcome (avoidance). Performance-approach would be wanting to look better than others; mastery-avoidance is fearing not to understand fully.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1779","question":"Carole Ames grouped classroom features that shape students’ goal orientation under the acronym TARGET. In this framework, the ‘R’ stands for:","options":["Recognition: how and for what students are acknowledged","Rewards: how many prizes are given for top scores","Responsibility: which duties students take on in class","Reinforcement: how quickly correct answers are praised"],"answer":0,"explanation":"TARGET stands for Task, Authority, Recognition, Grouping, Evaluation and Time. A mastery climate recognises effort, progress and improvement privately rather than publicly ranking the best scorers.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1780","question":"After failing maths tests for two years despite real effort, Kiran now stops trying even on easy sums that she could solve, saying, ‘It won’t make any difference.’ Which description and remedy fit best?","options":["Performance-avoidance; tell her that her marks will not be compared with anyone else’s","Learned helplessness; excuse her from maths tests for a while until her confidence returns on its own","Self-handicapping; warn her firmly that holding back effort will only make her marks fall further","Learned helplessness; give her tasks she can succeed at and link each success to her own strategies"],"answer":3,"explanation":"Seligman’s learned helplessness is the belief that outcomes are uncontrollable, so effort stops. The remedy is to restore the link between action and outcome through attainable successes and attributions to effort and strategy; simply removing tests leaves the belief untouched.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1781","question":"Before every major test, Varun stays up late watching cricket and tells friends he ‘hasn’t opened a book’. In Covington’s self-worth theory, the most likely purpose of this behaviour is to:","options":["Show his friends that he does not value marks and cares more about sport","Let any failure be blamed on lack of effort rather than lack of ability","Lower his arousal to the moderate level that suits a difficult test best","Make the test feel like a casual game so that he can enjoy it more"],"answer":1,"explanation":"Self-handicapping creates an excuse in advance: if he fails, the cause is the late night, not low ability, and if he succeeds, he looks especially able. Covington saw this as protecting a sense of self-worth tied to ability.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1782","question":"Covington called student effort a ‘double-edged sword’. What did he mean?","options":["Effort helps in practical subjects but harms performance in subjects that depend mainly on sudden insight","Effort raises marks in the short run but steadily lowers the student’s interest in the subject in the long run","Effort earns teachers’ approval, but trying hard and still failing suggests to the student that he lacks ability","Effort is useful for weaker students but tends to make naturally able students lazy and careless"],"answer":2,"explanation":"Teachers reward effort, but for a student who tries hard and fails, the obvious inference is low ability, which threatens self-worth; so some students withhold or hide effort.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1783","question":"A teacher opens a lesson by dropping a heavy and a light ball together; both land at the same moment, and students who expected otherwise eagerly ask why. In Daniel Berlyne’s terms, the lesson begins with:","options":["A collative variable such as surprise or incongruity that arouses epistemic curiosity","A primary drive that pushes students to act in order to reduce an unmet bodily need","A secondary reinforcer that strengthens attention by rewarding it after it occurs","An advance organiser that links the new content to anchoring ideas already held"],"answer":0,"explanation":"Berlyne held that novelty, surprise, complexity and incongruity (collative variables) arouse curiosity, and epistemic curiosity drives the search for knowledge. A discrepant event works by clashing with expectations, not by reward or an organiser.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1784","question":"George Loewenstein’s information-gap view of curiosity predicts that students will be most curious about a topic when they:","options":["Know nothing at all about it beforehand, so that everything about it feels new","Know a little about it and become aware of a specific gap in what they know","Already know almost everything about it, so that they feel confident and in control","Are told the full answer first and are then asked to remember it for a test"],"answer":1,"explanation":"Curiosity arises from noticing a gap between what one knows and wants to know; with no knowledge there is no felt gap, and complete knowledge leaves none. Teachers create curiosity by giving partial information and posing a sharp question.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1785","question":"In Csikszentmihalyi’s account of flow, a Class 7 chess player who wins every game easily against her classmates is most likely to feel:","options":["Flow, because she always succeeds at the task","Anxiety, because her skill is well below the challenge","Boredom, because her skill is well above the challenge","Apathy, because both skill and challenge are high"],"answer":2,"explanation":"Flow appears when a high challenge meets matching high skill; when skill greatly exceeds challenge the result is boredom, and when challenge exceeds skill, anxiety. Apathy goes with low skill and low challenge.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1786","question":"In class projects, Imran always wants to be the group leader, enjoys persuading others to follow his plan and likes being seen as influential. In David McClelland’s terms he shows a strong need for:","options":["Recognition","Achievement","Affiliation","Power"],"answer":3,"explanation":"McClelland’s three learned needs are achievement (excelling at a standard), affiliation (warm relationships) and power (influencing and controlling others); wanting to lead and persuade is the need for power.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1787","question":"Arrange Hidi and Renninger’s phases of interest development in order. P. Emerging individual interest Q. Triggered situational interest R. Well-developed individual interest S. Maintained situational interest","options":["Q, S, P, R","Q, P, S, R","S, Q, P, R","Q, S, R, P"],"answer":0,"explanation":"Interest is first triggered by something in the situation, then maintained by meaningful tasks, then becomes an emerging personal interest the learner returns to, and finally a well-developed individual interest.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1788","question":"Megha enjoys chemistry and knows it is useful for her goal of studying pharmacy, but she drops the optional chemistry club because it would mean giving up her evening kabaddi practice. In Eccles’s expectancy–value theory, the value component behind her decision is:","options":["Utility value","Cost","Attainment value","Intrinsic value"],"answer":1,"explanation":"Eccles named four value components: intrinsic (enjoyment), attainment (importance to identity), utility (usefulness for goals) and cost (what must be given up). The club scores well on the first three, so it is the cost that tipped the decision.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1789","question":"Well-fed, rested Class 4 children spend their whole break taking apart an old radio, though no need is being met and no reward is offered. Which theory of motivation has the most difficulty explaining this?","options":["White’s competence motivation","Arousal (optimal stimulation) theory","Hull’s drive-reduction theory","Self-determination theory"],"answer":2,"explanation":"Drive-reduction theory says behaviour aims to reduce tension from unmet biological needs, so seeking extra stimulation with no need to reduce is hard for it to explain; arousal, competence and self-determination theories all expect such exploration.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1790","question":"Match each statement with the self-belief it best expresses. P. ‘I can solve this quadratic equation.’ Q. ‘I am good at maths.’ R. ‘On the whole, I am satisfied with myself.’ 1. Global self-esteem 2. Self-efficacy 3. Academic self-concept","options":["P-1, Q-3, R-2","P-3, Q-2, R-1","P-2, Q-1, R-3","P-2, Q-3, R-1"],"answer":3,"explanation":"Self-efficacy is confidence about a specific task; academic self-concept is a broader view of oneself in a domain; global self-esteem is an overall evaluation of one’s worth. Confusing self-efficacy with self-concept is the usual trap.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1791","question":"A teacher wants group work in Class 6 to be truly cooperative in Johnson and Johnson’s sense. Which pair of features is essential?","options":["Positive interdependence and individual accountability","A single group mark for all members and a free choice of partners","Grouping by ability, with a prize for the best-performing group","Competition between groups and a group leader"],"answer":0,"explanation":"Members must need one another to succeed (positive interdependence) and each must be answerable for his own learning (individual accountability); without the second, a few students do the work while others coast.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1792","question":"Rahul, a Class 9 boy who often got into fights, is persuaded by his PE teacher to join the school wrestling team. He now pours his aggression into disciplined training and wins medals. In Freud's terms, the defence mechanism at work is:","options":["Displacement","Reaction formation","Sublimation","Rationalisation"],"answer":2,"explanation":"Sublimation channels an unacceptable impulse into a socially valued activity. Displacement only shifts the impulse onto a safer target (for example hitting a younger sibling), reaction formation shows the opposite of the impulse, and rationalisation invents acceptable reasons for it.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1793","question":"Students weak at subtraction worked through a booklet of 42 pages. Group A set a goal of finishing about six pages each session; Group B set the goal of finishing the whole booklet by the end of seven sessions. Bandura and Schunk found that Group A most likely:","options":["Did about as well as Group B, since both groups had to complete exactly the same pages","Gained less, because six pages a session is too easy a target to motivate anyone to try","Gained more skill, self-efficacy and interest, because near goals give frequent evidence of progress","Gained more skill but lost interest, because close, frequent goals feel like constant extra pressure"],"answer":2,"explanation":"Proximal (close) goals give regular, clear evidence of progress, which raises self-efficacy and intrinsic interest; distant goals give little feedback along the way. The total work is the same, so the difference lies in the goal structure.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1794","question":"Large studies of school students in several countries broadly agree that average intrinsic motivation for schoolwork, from the early primary years to the middle-school years:","options":["Rises sharply at puberty","Tends to rise slowly but steadily","Stays almost unchanged","Tends to decline steadily"],"answer":3,"explanation":"Research such as Lepper, Corpus and Iyengar’s found intrinsic motivation falls across grades, linked partly to more grades, comparison and control in school; this is why later classes need deliberate attention to interest and autonomy.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1795","question":"In Diener and Dweck’s studies, children were given problems they could solve and then some they could not. During the failures, ‘mastery-oriented’ children differed from ‘helpless’ children mainly in that they:","options":["Kept or even improved their strategies and treated failure as a problem to work on","Rated themselves as more intelligent than others and so felt that failure was beneath them","Remembered their earlier successes better and so did not notice the failures","Attributed failure to bad luck, which protected their self-esteem from harm"],"answer":0,"explanation":"Helpless children blamed their ability and their strategies broke down; mastery-oriented children hardly mentioned causes, gave themselves instructions and kept using good strategies. The difference was in reaction to failure, not in measured ability.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1796","question":"J. McV. Hunt’s ‘problem of the match’ advises that, to keep children interested, new material should be:","options":["Chosen only after the child has fully mastered the textbook","Exactly the same as what the child already understands","As different as possible from what the child already understands","Moderately different from what the child already understands"],"answer":3,"explanation":"Hunt argued that intrinsic interest is aroused by an optimal discrepancy: input too familiar is boring and input too strange cannot be assimilated, so a moderate mismatch with existing schemas works best.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1797","question":"Assertion (A): Children who are already keen readers may later read fewer books on their own after a scheme pays them a prize for every book read. Reason (R): Every reward given for an activity always lowers intrinsic motivation for it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Expected, tangible rewards for an already enjoyable activity can undermine interest (the overjustification effect), so A is true. R overstates it: informational praise and unexpected rewards usually do not lower intrinsic motivation.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1798","question":"Which statement about setting goals for students is best supported by Locke and Latham’s research?","options":["‘Do your best’ goals work better than specific ones because they reduce pressure","Specific, challenging goals usually lead to better performance than ‘do your best’","Easy goals produce the highest performance because they ensure frequent success","Goals help only adults; children perform the same with or without them"],"answer":1,"explanation":"Goal-setting research consistently finds that specific, difficult but attainable goals, with feedback and commitment, raise performance more than vague ‘do your best’ instructions or easy goals.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1799","question":"A teacher wants to reduce learned helplessness in her Class 5. Which of these steps fit attribution retraining? I. Pointing out after each success which strategy the child used. II. Telling children who fail that the task was simply too hard for them. III. Modelling self-talk such as ‘I made a mistake; let me try another way.’ IV. Telling them that some people are just born good at maths.","options":["II and IV only","I, II and III only","I and III only","I, III and IV only"],"answer":2,"explanation":"Attribution retraining moves explanations of success and failure towards controllable, unstable causes such as effort and strategy. Blaming task difficulty (II) or innate talent (IV) points to causes the child cannot change.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1800","question":"A student says, ‘I don’t see any point in studying; nothing I do here connects to anything I want.’ In self-determination theory this state is called:","options":["Amotivation","External regulation","Introjected regulation","Integrated regulation"],"answer":0,"explanation":"Amotivation is the lack of any intention to act, from seeing no value or no link between action and outcome. External and introjected regulation still involve acting, though for pressured reasons.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1801","question":"In a listening experiment, students repeat aloud a story played to the left ear and ignore a different story in the right ear. When the stories suddenly swap ears, many students briefly continue the original story from the right ear. What does this most directly show?","options":["The ignored message was processed for meaning to some extent, supporting Treisman’s attenuation model over Broadbent’s early filter","The ignored message was blocked entirely, supporting Broadbent’s all-or-none early filter over Treisman’s attenuation model","Attention can be divided equally between two meaningful messages if both are heard through earphones","Students who repeat a message aloud stop processing its meaning and attend only to the voice"],"answer":0,"explanation":"If the unattended ear were filtered out completely on physical features, its content could not pull attention across. Treisman proposed that unattended input is weakened, not blocked, so highly probable or meaningful words can still break through.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1802","question":"A school finds that Class 11 students who chat on their phones during lessons score lower on later quizzes than those who do not. What does research on such classroom multitasking also suggest?","options":["The loss disappears once students become practised at switching between tasks","Classmates who can see a multitasking student’s screen also tend to understand less","The loss affects only students of low ability, not the able students in class","Listening ability actually improves, because phone use keeps students alert and awake"],"answer":1,"explanation":"Attention cannot be fully shared between two demanding tasks; frequent switching lowers comprehension. Studies such as Sana and colleagues’ found that nearby students who could view a laptop multitasker were distracted and scored lower too.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1803","question":"In the Stroop task, children name the ink colour of colour words, such as RED printed in green. Compared with a Class 1 child who cannot yet read, a fluent Class 4 reader is most likely to show:","options":["The same slowing, because the task measures colour perception, which is mature by Class 1","Less slowing, because older children have better attention and simply ignore the printed word","More slowing, because reading the word has become automatic and competes with naming the ink","No slowing at all, because fluent readers process words and colours in separate brain areas"],"answer":2,"explanation":"Stroop interference arises from automatic reading; children who cannot read do not show it, and it appears once word reading becomes automatic in the early school years. It shows that practised skills run without deliberate attention and are hard to switch off.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1804","question":"Students asked to count the passes made by one team in a video often fail to notice a person in a gorilla suit walking through the scene. What is the main lesson for a teacher?","options":["Learners who miss such events lack interest in the subject and need stronger motivation","Learners notice anything unusual, so a surprising object is the surest way to make sure a point is remembered","Young learners cannot attend properly to moving pictures, so videos should be kept out of lessons","Learners focused on one demanding detail may miss even striking information, so direct their attention to what matters"],"answer":3,"explanation":"This is inattentional blindness: what is not attended to is often not perceived at all. Teachers cannot assume something visible will be seen; they must cue attention to the key features.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1805","question":"Asked to check a long list of numbers for errors over an hour, students catch most errors in the first ten minutes and fewer later, though the errors are spread evenly. This decline is called:","options":["Vigilance decrement","Habituation of the orienting response","Retroactive interference","Response set"],"answer":0,"explanation":"Vigilance decrement is the fall in detection over a long monitoring task, showing the limits of sustained attention. Habituation is a weakened response to a repeated stimulus; interference concerns memory, not detection.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1806","question":"Children of different ages were shown cards, each with an animal and a household object, and told to remember only the position of the animals. Later they were also asked which object had gone with which animal. Hagen’s classic findings showed that with age:","options":["Recall of both the animals and the objects stayed the same","Recall of both the animals and the paired objects rose by the same amount","Recall of the paired objects rose more than recall of the animals","Recall of the animals rose clearly, but recall of the paired objects did not"],"answer":3,"explanation":"Central learning improved with age while incidental learning stayed flat or even dropped in the oldest groups, showing that older children are better at selectively attending to the task-relevant items and ignoring others.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1807","question":"A Class 2 teacher claps twice to get attention. It works well in the first week, but by the third week children barely look up. The best explanation is:","options":["Extinction: the clap was never paired with any reward, so the response gradually died out","Habituation: a repeated, predictable stimulus stops drawing the orienting response","Retroactive interference: new rules in the third week replaced the old one","Spontaneous recovery: the response returns after a break and then fades again"],"answer":1,"explanation":"Novel stimuli draw an orienting response, which weakens with repetition; changing the signal or pairing it with something meaningful restores attention. Extinction would need an earlier reinforced response that is no longer reinforced.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1808","question":"A slide on photosynthesis carries a dancing cartoon sun, sound effects and an amusing story about a record-breaking sunflower that has nothing to do with the process. Research on multimedia learning predicts that these additions will most likely:","options":["Make no difference, since students simply ignore whatever is irrelevant to the lesson","Improve learning, because more interest always means more attention to the main content","Reduce learning of the process, because they add extraneous load and pull attention away from it","Help weak students but not strong students, who do not need extra interest"],"answer":2,"explanation":"Mayer’s coherence principle and studies of ‘seductive details’ show that interesting but irrelevant material uses limited attention and working memory and can lead learners to organise the lesson around the wrong ideas.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1809","question":"While showing an animated diagram of blood circulation, a teacher also reads out a text box that repeats her spoken words exactly. According to Mayer’s redundancy principle, students would learn better if she:","options":["Removed the text box and kept the narration with the animation","Removed the narration and kept the text box with the animation","Kept the narration, the text box and the animation all together","Showed the text box alone before showing the animation alone"],"answer":0,"explanation":"Identical printed text competes with the animation for the visual channel and forces learners to reconcile two verbal streams; narration plus the picture uses the auditory and visual channels without overload.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1810","question":"For a labelled diagram of the human ear, which accompanying explanation is predicted by the modality principle to work best for Class 8 students?","options":["A printed paragraph read silently before seeing the diagram","A printed paragraph placed beside the diagram","A printed paragraph on the next page after the diagram","A spoken explanation while students look at the diagram"],"answer":3,"explanation":"When a picture must be examined, words are better heard than read, because both the diagram and printed text compete for visual attention; spreading the load across ears and eyes frees working memory.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1811","question":"Fully solved examples help beginners in algebra learn more than solving the same problems unaided. For students who are already skilled, however, the same worked examples can give less benefit than practice problems. This is called:","options":["The redundancy principle","The expertise reversal effect","The generation effect in problem solving","The spacing (distributed practice) effect"],"answer":1,"explanation":"Worked examples reduce load for novices, but experts already hold the schemas, so processing the steps becomes redundant extra load; methods must change as expertise grows.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1812","question":"In cognitive load theory, which task carries the highest intrinsic load for a Class 7 student meeting it for the first time?","options":["Memorising the names of the eight planets in their order outward from the Sun","Learning the spellings of ten unrelated new words, one word at a time each day","Solving a two-step equation, where each step depends on keeping the others in mind","Learning the meanings of the Hindi names for the days of the week"],"answer":2,"explanation":"Intrinsic load depends on element interactivity: how many elements must be processed together. Word lists can be learnt item by item, but equation-solving requires several interacting elements at once.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1813","question":"A teacher asks students to proofread an essay only for spelling mistakes. Most find every spelling error but miss a glaring factual error about a date. Which determinant of attention does this show most clearly?","options":["Mental set, the readiness to attend to what one expects or is looking for","Intensity, the strength of a stimulus such as a loud sound or bright colour","Novelty, the unusual or unexpected element in a situation","Movement, a change in position that draws the eye"],"answer":0,"explanation":"Mental (preparatory) set is a subjective determinant: the instruction tuned students to spelling, so other errors, though obvious, went unnoticed. The other options are objective features of the stimulus.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1814","question":"Looking at a line drawing of a cube, a student finds that first one face seems to be in front and then, a few seconds later, another. This illustrates:","options":["The division of attention","The span of attention","The fluctuation of attention","The distraction of attention"],"answer":2,"explanation":"Attention cannot stay fixed on one interpretation for long; with reversible figures such as the Necker cube it alternates every few seconds even though the drawing does not change.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1815","question":"Which pair of activities is a Class 5 student most likely to carry out together with the least loss on either?","options":["Listening to a story read aloud while reading a different story silently","Listening to a story read aloud while colouring a simple familiar pattern","Silently reading a story while copying a different passage from the board","Listening to a story while also listening to a different story on a radio"],"answer":1,"explanation":"Divided attention is easiest when tasks use different modalities and codes and when one is practised and automatic. The other pairs compete for the same verbal or auditory resources (multiple-resource theory).","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1816","question":"In a recorded lecture, one group of students gets a short quiz after each segment; the other group gets no quizzes until the end. Research on such interpolated testing found that the quizzed group mostly:","options":["Showed no differences, since they had heard the same lecture","Mind-wandered more, because the frequent quizzes made them anxious and distracted","Learnt more only of the quizzed segments and less of the rest","Mind-wandered less, took more notes and learnt more of the lecture"],"answer":3,"explanation":"Szpunar and colleagues found that brief quizzes between segments reduced mind-wandering, increased note-taking and improved final test performance, besides giving retrieval practice.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1817","question":"Before a race, the starter says, ‘On your marks, get set…’, and runners become ready to respond. In Michael Posner’s model of attention networks, this preparation mainly involves the:","options":["Alerting network","Orienting network","Executive network","Default network"],"answer":0,"explanation":"Posner described three networks: alerting (achieving and keeping a ready state after a warning), orienting (selecting a location or input) and executive (resolving conflict and controlling responses). A warning signal engages alerting.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1818","question":"A Class 3 teacher adds three-minute movement breaks between long periods of seated work. Classroom studies of such brief activity breaks generally found:","options":["No change, since attention depends only on the lesson","More off-task behaviour, as children stayed excited","More on-task behaviour in the lessons that followed","Better behaviour only on days with no outdoor games"],"answer":2,"explanation":"Studies of short in-class activity breaks, such as the ‘Energizers’ programme, reported more time on task after the breaks; young children’s sustained attention benefits from changes in activity.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1819","question":"Ms Rao asks the class, ‘Why does the moon seem to change shape?’, pauses while looking around the room, and only then names a student to answer. Jacob Kounin would call this:","options":["Withitness","Group alerting","Overlapping","The ripple effect"],"answer":1,"explanation":"Group alerting keeps the whole class attentive by posing the question before naming the responder, so everyone must think. Naming first lets the rest switch off.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1820","question":"Match Jacob Kounin’s classroom terms with their meanings. P. Withitness Q. Overlapping R. Smoothness S. Ripple effect 1. Handling two matters at once without dropping either 2. Moving between activities without abrupt breaks or digressions 3. A correction given to one student influences others who see it 4. Showing students that the teacher knows what is happening everywhere in the room","options":["P-4, Q-1, R-3, S-2","P-1, Q-4, R-2, S-3","P-4, Q-2, R-1, S-3","P-4, Q-1, R-2, S-3"],"answer":3,"explanation":"Kounin found that effective managers show withitness, overlap tasks, keep lessons smooth and maintain momentum; his early work also described the ripple effect of a teacher’s desists on onlookers.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1821","question":"A teacher wants one key value in a table of 40 numbers to be spotted instantly by every student. According to feature-integration research on visual search, the best design is to:","options":["Print that one value in a colour different from all the others","Print that value in a colour and font both shared with some other values","Put that value in the same style as the others but in the middle of the table","Repeat that value in several places in the table in the same style"],"answer":0,"explanation":"An item that differs from all others by a single feature ‘pops out’ almost regardless of the number of items; when it shares features with others (a conjunction), search becomes slow and item by item.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1822","question":"A teacher underlines the key terms on a slide, adds headings such as ‘Cause’ and ‘Effect’, and points to each part of the diagram as she speaks about it. Which of Mayer’s multimedia principles is she mainly applying?","options":["Pre-training","Segmenting","Signalling","Personalisation"],"answer":2,"explanation":"Signalling adds cues that highlight the essential material and its organisation, guiding attention; segmenting splits a lesson into learner-paced parts, and pre-training teaches key names beforehand.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1823","question":"Before showing a complex animation of how a bicycle pump works, a teacher first lets students handle the piston, inlet valve and outlet valve and learn what each part is called and does. Mayer would predict this helps because:","options":["Handling parts makes students more interested, and interest is what reduces cognitive load","Knowing the parts in advance frees working memory to follow how they interact in the animation","It replaces the animation, so students no longer need to watch the full sequence","It adds a second, practical modality, so the information enters memory twice"],"answer":1,"explanation":"This is the pre-training principle: when the main lesson is complex, learning the names and characteristics of key components first means learners can devote capacity to the causal sequence instead of identifying parts.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1824","question":"A long animated explanation of the water cycle plays straight through without pause, and many students lose track. Which change applies Mayer’s segmenting principle?","options":["Playing the whole animation twice in a row without stopping","Adding on-screen text that repeats every word of the narration","Adding background music throughout to keep students attentive and alert","Breaking it into short parts that students advance at their own pace"],"answer":3,"explanation":"Segmenting divides a continuous lesson into learner-paced chunks so each part can be processed before the next arrives; adding repeated text or music increases load rather than reducing it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1825","question":"According to Easterbrook’s cue-utilisation hypothesis, a very anxious student taking a complex reasoning test is likely to:","options":["Narrow attention to fewer cues, which can make him miss information the problem needs","Widen attention to more cues, which overloads him with irrelevant details","Attend to cues normally but recall them less well afterwards","Attend better to every single cue, since anxiety always sharpens a student’s focus"],"answer":0,"explanation":"Easterbrook proposed that rising arousal shrinks the range of cues used. On simple tasks dropping irrelevant cues can help, but on complex tasks relevant peripheral cues are lost too, so performance falls.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1826","question":"Divers who learnt word lists underwater recalled them better underwater, and those who learnt on land recalled better on land. A Class 10 student always revises in her quiet bedroom but takes board exams in a noisy hall. Which advice follows best from this research?","options":["Revise in a few varied places and, in the hall, mentally recall the setting where she studied","Revise only in the bedroom, since one familiar, quiet setting always makes memories strongest","Revise only in the exam hall, since recall depends on nothing but the testing place","Ignore study settings, since context effects on memory appear only in unusual places such as underwater"],"answer":0,"explanation":"Encoding specificity means retrieval is best when cues present at learning are present at testing. Varying study contexts makes memories less tied to one place, and mentally reinstating the study context recovers some of its cues.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1827","question":"To prepare for a science test a month away, Kavya studies three hours on one Sunday, while Arif studies one hour on each of three Sundays. If both learn the same material, what does research on the spacing effect predict for the test?","options":["Kavya will remember more, because one long session builds deeper concentration","Arif will remember more, because spaced sessions give better long-term retention","Both will remember the same, because total study time is what decides retention","Kavya will remember more, because her learning ended closer to the test"],"answer":1,"explanation":"For the same total time, distributed practice gives better long-term retention than massed practice; Kavya’s session actually ended earlier, not later, than Arif’s last session.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1828","question":"Group A practises volume problems for cubes, then for cylinders, then for cones, each block separately. Group B practises the same problems mixed in random order. Group B scores lower during practice but much higher on a test a week later. The best explanation is that mixing:","options":["Lets students memorise each formula in its own block first, before applying it in mixed tests later","Gives students more problems to solve in the same time, so they get more total practice","Makes practice easier, so that students feel confident and try harder on the test","Forces students to choose the right method for each problem, which blocked practice lets them skip"],"answer":3,"explanation":"Interleaved practice requires learners to discriminate problem types and select a strategy each time, as a test does; blocked practice tells them the method in advance. Rohrer and Taylor found exactly this pattern of lower practice but higher delayed scores.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1829","question":"Assertion (A): Practice that makes learning feel slower and harder, such as spacing sessions and testing oneself, often produces better long-term retention than easy re-reading. Reason (R): Conditions that make performance during learning look best are always the conditions that make long-term learning best.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Robert Bjork called these ‘desirable difficulties’: they lower immediate performance but strengthen durable learning. R is false precisely because performance during learning is a poor guide to long-term learning.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1830","question":"One group of students reads word pairs like ‘hot–cold’; another sees ‘hot–c_ _ _’ and must complete the second word. On a later memory test, the second group usually recalls more words. This is called the:","options":["Generation effect","Testing effect","Spacing effect","Von Restorff effect"],"answer":0,"explanation":"Producing information oneself, even with a small effort, leads to better memory than reading it; the testing effect is specifically retrieval of previously learnt material, and the von Restorff effect concerns a distinctive item.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1831","question":"Match each memory aid with an example. P. Method of loci Q. Acronym R. Acrostic S. Peg-word method 1. ‘VIBGYOR’ for the colours of the spectrum 2. ‘My Very Educated Mother Just Served Us Nachos’ for the planets 3. Imagining each item of a list placed at a spot along the route from home to school 4. Linking each item to a memorised rhyme such as ‘one is a bun, two is a shoe’","options":["P-3, Q-1, R-4, S-2","P-4, Q-1, R-2, S-3","P-3, Q-2, R-1, S-4","P-3, Q-1, R-2, S-4"],"answer":3,"explanation":"Loci uses familiar places along a route; an acronym makes a word from first letters; an acrostic makes a sentence from them; the peg-word method hangs items on a pre-learnt rhyming list.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1832","question":"Which order correctly ranks the three methods of measuring retention from the most sensitive (detecting the faintest traces) to the least sensitive?","options":["Recall, recognition, relearning (savings)","Relearning (savings), recognition, recall","Recognition, recall, relearning (savings)","Relearning (savings), recall, recognition"],"answer":1,"explanation":"Material that cannot be recalled may still be recognised, and material that can no longer be recognised may still be relearnt faster than the first time, as Ebbinghaus’s savings method showed.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1833","question":"Asked the name of the scientist who discovered penicillin, Rohan says, ‘It starts with F… two syllables… it’s on the tip of my tongue!’ Research on this state shows that:","options":["The word was never stored in long-term memory, only in sensory memory","The word has been completely lost from long-term memory and must now be learnt all over again","Partial information about the word, such as its first letter or length, is often available","The state is caused by low intelligence and seldom happens to people who speak fluently"],"answer":2,"explanation":"Brown and McNeill showed that in the tip-of-the-tongue state people can often report the first letter, number of syllables or similar-sounding words, so the problem is retrieval, not storage.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1834","question":"A teacher stops an exciting story just before the climax at the end of the period. Next day, children remember the unfinished story in rich detail. Which effect is this?","options":["The Zeigarnik effect","The primacy effect","The von Restorff effect","The overjustification effect"],"answer":0,"explanation":"Bluma Zeigarnik found that interrupted, unfinished tasks are recalled better than completed ones, as the open goal keeps the material active; primacy concerns items at the start of a list.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1835","question":"Having learnt the multiplication table of 13 until he can recite it once without error, Abhay keeps practising it for a few more days. What does research on overlearning predict?","options":["He will forget it faster, because extra practice after mastery causes boredom and interference","He will forget it more slowly, though each extra round of practice adds less benefit than the one before","He will gain nothing, because once material is mastered further practice cannot strengthen it","He will gain more from each additional round than from the first, so practice should continue indefinitely"],"answer":1,"explanation":"Practice beyond first mastery strengthens retention, as Krueger showed, but with diminishing returns; spacing the extra practice over time is especially useful.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1836","question":"A Class 6 student must learn a 40-line poem whose stanzas tell one connected story. Which method is generally best for him?","options":["Learn the last stanza first so that recency helps him finish confidently","Learn it strictly one line at a time, never looking ahead until each line is perfect","Read it through as a whole for its meaning, then give extra practice to the hard stanzas","Read it in a fixed order once a day without attending to its meaning"],"answer":2,"explanation":"For meaningful, connected material the whole method preserves the links between parts, while extra attention to difficult sections (a combined or progressive approach) handles long passages; pure line-by-line learning loses the structure.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1837","question":"Students who are made to feel sad recall more sad events from a story they read, while happy students recall more happy events. Gordon Bower described this as:","options":["Retroactive interference","Repression","Encoding failure","Mood-congruent memory"],"answer":3,"explanation":"Mood-congruent memory is the tendency to encode and retrieve material that matches one’s current mood; repression is a Freudian motivated forgetting of threatening material, which does not explain the symmetrical pattern.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1838","question":"Students judge a list of adjectives in three ways: whether each is printed in capitals, whether it rhymes with another word, or whether it describes themselves. On a surprise test, which group recalls the most adjectives?","options":["Those who judged whether each word described themselves","Those who judged whether each word rhymed with another","Those who judged whether each word was in capital letters","All three groups recall equally, since they saw the same words"],"answer":0,"explanation":"Rogers and colleagues found a self-reference effect: relating material to oneself is a very deep, elaborative way of encoding, beyond semantic or sound-based judgements.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1839","question":"While reading that ‘camels can go many days without drinking water’, a student asks herself, ‘Why would that be true for a camel?’ and answers using what she knows about deserts and fat stores. This strategy is called:","options":["Maintenance rehearsal","Elaborative interrogation","Self-testing by retrieval practice","Interleaved practice"],"answer":1,"explanation":"Elaborative interrogation prompts learners to explain why a fact is true, linking it to prior knowledge; maintenance rehearsal merely repeats, and retrieval practice recalls material without the text.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1840","question":"In a large review by Dunlosky and colleagues, which study techniques were rated as having high usefulness for students across many conditions? I. Practice testing II. Distributed practice III. Highlighting and underlining IV. Re-reading","options":["II and III only","I, II and IV only","I and II only","I, III and IV only"],"answer":2,"explanation":"The review rated practice testing and distributed practice as high utility; highlighting and re-reading were rated low because they give little benefit beyond simple reading.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1841","question":"Reena keeps forgetting to bring her signed permission slip for the school trip, though she knows the trip details perfectly. Her lapse is mainly a failure of:","options":["Procedural memory","Episodic memory","Semantic memory","Prospective memory"],"answer":3,"explanation":"Prospective memory is remembering to carry out an intended action in the future; her memory for past facts and events about the trip is intact.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1842","question":"Shown ten pictures, most pre-schoolers predict they will remember all ten, but they actually recall only three or four; older children predict much more accurately. This study by Flavell and colleagues shows the development of:","options":["Metamemory","Rehearsal","Recognition memory","Memory span"],"answer":0,"explanation":"Metamemory is knowledge about one’s own memory and its limits. Young children greatly overestimate how much they will remember, which partly explains why they do not use strategies to help themselves.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1843","question":"After reading a chapter three times, Neha feels she ‘knows it perfectly’ because it now reads so easily, but she scores poorly on a test. The most likely explanation is that:","options":["Re-reading three times was too much and caused interference among the many facts in the chapter","Familiarity from re-reading created an illusion of knowing without testing her ability to retrieve it","She forgot the chapter because it was read in a different room from the test","Her feeling of knowing was accurate, so the test must have been unfair or badly set"],"answer":1,"explanation":"Fluent re-reading makes material feel familiar, which learners mistake for mastery; self-testing reveals what can actually be retrieved and also strengthens it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1844","question":"Most adults remember almost nothing from before about the age of three. Which explanation is best supported?","options":["Infants cannot learn anything before three, since they cannot form any memories","Infants store everything but repress all early memories to protect themselves from anxiety","Brain systems and the self-concept and language used to organise lasting memories are still immature","Early memories are perfectly stored but are lost when children start school"],"answer":2,"explanation":"Infants clearly learn and remember in the short term; childhood (infantile) amnesia is explained by the immaturity of brain structures such as the hippocampus and by the late development of a self-concept and language for organising autobiographical memories.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1845","question":"A Class 1 child says an older student pushed her. When the teacher asks what happened, which question is most likely to give an accurate account?","options":["‘Did he push you with his right hand or his left?’","‘He pushed you very hard on purpose, didn’t he, beta?’","‘Was it Raju who pushed you, or was it Sonu?’","‘Tell me everything that happened near the swings.’"],"answer":3,"explanation":"Young children are especially open to suggestion; leading, tag or forced-choice questions plant details, while open-ended prompts let the child give her own account.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1846","question":"Students watch a video of two cycles colliding. Those later asked ‘How fast were the cycles going when they smashed into each other?’ give higher speed estimates and are more likely to ‘remember’ broken glass than those asked with the word ‘hit’. This shows:","options":["The misinformation effect: wording after an event can change memory of it","Proactive interference: earlier memories block the learning of new ones","Encoding failure: the speed was never noticed during the video","Mood-congruent memory: frightened students remember more damage"],"answer":0,"explanation":"Loftus and Palmer showed that information supplied after an event can alter the memory itself; the video was the same for both groups, so encoding and mood cannot explain the difference.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1847","question":"Five-year-olds who do not rehearse on their own are taught to repeat names of pictures, and their recall improves. Given a free choice later, many stop rehearsing. Flavell called this:","options":["A capacity deficiency","A mediation deficiency","A utilisation deficiency","A production deficiency"],"answer":3,"explanation":"In a production deficiency children can use a strategy that would help them but do not produce it spontaneously. A mediation deficiency means the strategy does not help even when used; a utilisation deficiency means it is used but gives little benefit yet.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1848","question":"Ten-year-old chess players recalled board positions from real games better than adult non-players, but the adults recalled lists of digits better. What does Michelene Chi’s study show?","options":["Children have a larger basic memory capacity than adults for every kind of material","A rich knowledge base in a domain improves memory for material in that domain","Adults have better strategies for every kind of material than children","Memory depends only on age, so the chess results must simply reflect chance"],"answer":1,"explanation":"The children’s expert knowledge let them chunk and interpret chess positions, so domain knowledge, not age or general capacity, drove recall; on digits, where they had no special knowledge, adults did better.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1849","question":"In Sperling’s experiments, a grid of 12 letters is flashed briefly. Asked to report all letters, people give about 4; but when a tone right after the flash cues just one row, they can report most of that row. What does this show?","options":["Attention can be divided equally among all rows at the same moment","Short-term memory can hold all 12 letters as long as they are rehearsed quickly","Sensory (iconic) memory briefly holds much more than can be reported before it fades","Long-term memory stores the letters that are later cued by a particular tone"],"answer":2,"explanation":"Since any row could be cued, nearly all the letters must have been available for an instant; the visual trace fades within about a second, faster than whole report can be given.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1850","question":"Students who could recall only a few words from a long list were given category names such as ‘fruits’ and ‘tools’, and then recalled many more. Tulving and Pearlstone concluded that much forgetting reflects:","options":["Items that are available in memory but not accessible without suitable cues","Items that decayed from memory and were regenerated by guessing","Items that were never encoded, which the categories then supplied","Items displaced from short-term memory when the category names were presented"],"answer":0,"explanation":"Cues recovered words that free recall missed, so those words had been stored; the problem was retrieval. This is the distinction between availability and accessibility.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1851","question":"Pre-school children are shown unfamiliar gadgets. Some gadgets are described as ‘things girls really like’ and others as ‘things boys really like’. A week later, children have explored more and remember more names for the gadgets labelled for their own sex. Which theory predicts this most directly?","options":["Psychoanalytic theory: children identify with the same-sex parent after resolving the Oedipal conflict","Gender schema theory: children attend to and remember what their gender schema marks as ‘for me’","Operant learning: children remember gadgets for which they were directly rewarded","Biological theory: prenatal hormones fix interest in particular kinds of objects"],"answer":1,"explanation":"The gadgets were new, so no prior reward or hormone-linked preference could favour them; only the label differed. Martin and Halverson’s gender schema theory says children use ‘own-sex’ labels to decide what to explore and encode.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1852","question":"Two-year-olds already prefer gender-typed toys, though most children do not grasp gender constancy until about five to seven years. Which theory is more directly challenged by this finding?","options":["Bandura’s social learning theory, which links gender-typing to modelling and to direct reinforcement by others","Gender schema theory, which needs only a basic gender identity, not constancy, for gender-typing to begin","Kohlberg’s cognitive-developmental theory, which made gender constancy the starting point of gender-typing","Bronfenbrenner’s ecological theory, which places gender norms in the macrosystem"],"answer":2,"explanation":"Kohlberg held that children first understand that gender is permanent and then seek out gender-appropriate behaviour; preferences seen long before constancy fit schema and social learning accounts better.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1853","question":"From about age three, children increasingly choose same-sex playmates even when teachers encourage mixed play, and this peaks in middle childhood. Eleanor Maccoby’s explanation emphasised that:","options":["Each sex has a different profile of abilities, so boys and girls cannot easily share games","Teachers quietly reward same-sex play, so children learn to prefer it through reinforcement","Children copy their parents, who mostly choose close friends of their own sex","Boys’ rough, dominant play and girls’ preference for negotiation make same-sex play more compatible"],"answer":3,"explanation":"Maccoby argued that children seek partners whose interaction style matches theirs; girls find boys unresponsive to polite influence, and boys prefer rough play, so segregation arises largely from the children themselves.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1854","question":"In early adolescence, both boys and girls often become stricter about acting ‘like a man’ or ‘like a woman’ in dress, interests and behaviour. Hill and Lynch called this:","options":["Gender intensification","Gender constancy","Gender-role transcendence","Gender stability"],"answer":0,"explanation":"The gender intensification hypothesis links increased pressure to conform to gender roles in early adolescence to puberty and to expectations from parents and peers; constancy and stability are early childhood understandings.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1855","question":"Janet Hyde reviewed many studies of psychological differences between males and females. Her ‘gender similarities hypothesis’ concluded that:","options":["Differences are large in childhood but disappear only after age forty","Most differences are large and are fixed at birth by biological sex","Girls are much better in maths and boys much better in reading","Most differences, including in maths ability, are small or close to zero"],"answer":3,"explanation":"Hyde found that most effect sizes were small or near zero, with a few exceptions such as some motor skills; overstating differences can harm children’s choices and teachers’ expectations.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1856","question":"Studies of parents watching their children play found that cross-gender play (such as a boy playing with dolls) drew more disapproval when it was done by:","options":["Girls, especially from their fathers","Boys, especially from their fathers","Girls, especially from their mothers","Boys and girls equally, from both parents"],"answer":1,"explanation":"Research such as that of Fagot and of Langlois and Downs found that boys’ cross-gender play is discouraged more strongly than girls’, with fathers the most likely to react.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1857","question":"Ramesh begins to think of himself as ‘clever’ after noticing how his teachers and friends react to his answers in class. This idea that the self is formed by imagining how others see and judge us was given by:","options":["Erik Erikson, as ‘identity achievement’ in adolescence","George Herbert Mead, as the ‘generalised other’","Charles Horton Cooley, as the ‘looking-glass self’","Carl Rogers, as the ‘ideal self’"],"answer":2,"explanation":"Cooley’s looking-glass self has three parts: we imagine how we appear to others, imagine their judgement, and feel pride or shame. Mead’s generalised other refers to the attitudes of the community as a whole.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1858","question":"A five-year-old pretends to be a doctor, then a shopkeeper; a nine-year-old playing cricket adjusts to the roles of bowler, fielders and umpire all at once and follows the rules of the game. George Herbert Mead saw the second child as having reached:","options":["The game stage, taking the attitude of the generalised other","The play stage, taking the role of one particular other","The preparatory stage, imitating others without understanding roles","The formal stage, reasoning about hypothetical roles"],"answer":0,"explanation":"In the play stage a child takes one role at a time; in the game stage he must hold the expectations of all players and the rules together, the ‘generalised other’ that becomes the basis of the social self.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1859","question":"Match each process with its example. P. Primary socialisation Q. Secondary socialisation R. Anticipatory socialisation S. Resocialisation 1. A Class 12 student practises formal speech and dress before joining a college debate club 2. A toddler learns language and basic habits at home 3. A child learns to wait for turns and follow timetables at school 4. A boy who had worked in a factory adjusts to classroom routines after a bridge course","options":["P-2, Q-1, R-3, S-4","P-2, Q-3, R-1, S-4","P-3, Q-2, R-1, S-4","P-2, Q-3, R-4, S-1"],"answer":1,"explanation":"Primary socialisation happens mainly in the family in early years; secondary socialisation occurs in wider institutions such as school; anticipatory socialisation prepares for a role one expects to take; resocialisation replaces earlier patterns with new ones.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1860","question":"At home, a child is loved and treated as special simply because she is ‘our daughter’; at school she is judged by the same rules and standards as everyone else in her class. Parsons and Dreeben saw this second experience as the school teaching the norm of:","options":["Ascription","Particularism","Universalism","Affectivity"],"answer":2,"explanation":"Families treat members particularistically, by who they are; schools apply universalistic standards to all pupils alike and reward achievement rather than ascribed status, preparing children for wider society.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1861","question":"Parents who set few rules and also show little warmth or involvement, rarely knowing where their child is or how she is doing at school, fit which style in Maccoby and Martin’s extension of Baumrind’s model?","options":["Authoritative","Permissive (indulgent)","Authoritarian (restrictive)","Uninvolved (neglectful)"],"answer":3,"explanation":"Crossing demandingness with responsiveness gives four styles; low demands with low responsiveness is uninvolved, while permissive parents make few demands but are warm and responsive.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1862","question":"Children of families who have moved from Kerala to Delhi grow up speaking Hindi with the accent of their Delhi classmates rather than that of their parents. Judith Rich Harris used such cases to argue that:","options":["Peer groups play a major part in socialising children, sometimes more than parents","Parents have no influence at all on any aspect of their children’s development","Language accent is fixed genetically and only appears to have been learnt from others","Teachers, not peers or parents, decide how children speak outside class"],"answer":0,"explanation":"Harris’s group socialisation theory holds that children adapt to the norms of their peer group outside the home; it does not claim parents have zero influence, only that peer effects are often underrated.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1863","question":"In many farming communities, young children learn to sort grain or tend animals by watching closely and joining in family work, with adults adjusting their help as the child’s part grows. Barbara Rogoff describes this as:","options":["Programmed instruction in small, carefully graded steps","Guided participation in culturally valued activities","Discovery learning without any adult involvement at all","Classical conditioning of useful household habits"],"answer":1,"explanation":"Rogoff’s guided participation extends Vygotsky’s ideas: children learn through shared participation in real activities, with mutual involvement and support that shifts as competence grows.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1864","question":"Philip Jackson, who coined the term ‘hidden curriculum’, said that children in classrooms must learn to live with three facts of school life. These are:","options":["Tests, grades and promotion","Rules, rewards and punishments","Crowds, praise and power","Peers, parents and teachers"],"answer":2,"explanation":"In ‘Life in Classrooms’ Jackson described crowds (waiting, delay, sharing attention), praise (constant evaluation) and power (the teacher’s authority) as lessons learnt beyond the official syllabus.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1865","question":"A mother believes boys are naturally better at maths. Even when her daughter scores as well as her son, she rates the daughter’s maths ability lower. Research in Eccles’s parent-socialiser model suggests that over time:","options":["The son’s maths self-concept falls, since he is compared with a high-scoring sister","The daughter’s maths marks rise, since she works harder to prove her mother wrong","The mother’s belief has no effect, since children judge ability only from test scores","The daughter’s own view of her maths ability tends to fall, regardless of her actual marks"],"answer":3,"explanation":"Jacobs and Eccles found that parents’ gender-stereotyped beliefs shape their perceptions of their child’s ability, which in turn shape the child’s self-perceptions and choices, independent of actual performance.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1866","question":"A six-year-old insists that ‘only girls can be nurses’ and is upset when shown a male nurse; by nine she accepts that ‘boys and girls can both do it’. This change reflects the typical pattern that:","options":["Rigidity about gender stereotypes peaks around five to seven and then becomes more flexible","Children are flexible about gender at six and become steadily more rigid as they grow older","Gender rigidity is fixed by heredity and does not change during childhood","Children lose all knowledge of gender stereotypes once they reach school age"],"answer":0,"explanation":"Once children learn stereotypes they apply them rigidly in early childhood; with more cognitive flexibility and experience, they come to see gender roles as conventions that can vary.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1867","question":"In a summer school, children are given blue or yellow T-shirts at random. In some classes teachers use the colours to organise the day (separate lines, desks labelled by colour); in others the colours are worn but never used. Bigler’s study found that children showed favouritism towards their own colour group:","options":["Equally in both kinds of class, as soon as the coloured shirts were handed out","Mainly in classes where teachers made functional use of the colour groups","Only in classes where teachers said that one colour group was cleverer","In neither kind of class, since the groups were assigned at random"],"answer":1,"explanation":"Even arbitrary groups produced in-group bias when adults made them salient by using them to sort and label children; merely wearing the shirts was not enough. Teachers’ routine sorting by gender or caste can similarly fuel bias.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1868","question":"A school wants its mixed activities to reduce prejudice between children of two communities. According to Allport’s contact hypothesis, which arrangement is most likely to help?","options":["Competitions between teams drawn from each community, to build healthy rivalry","Seating children of both communities in the same room while each group works on its own","Teams with equal status working cooperatively towards shared goals, backed by school leaders","Lectures on tolerance with the communities seated in separate sections of the hall"],"answer":2,"explanation":"Allport held that contact reduces prejudice under four conditions: equal status, common goals, intergroup cooperation and institutional support. Mere co-presence or competition can even strengthen bias.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1869","question":"Annette Lareau found that middle-class parents tend to fill children’s time with organised activities and to train them to question adults and negotiate, while working-class parents let children play freely and expect obedience to authority. She called the middle-class approach:","options":["Cultural deprivation","Accomplishment of natural growth","Authoritarian control","Concerted cultivation"],"answer":3,"explanation":"Concerted cultivation develops skills that schools reward, such as speaking up to adults; the working-class pattern she called the accomplishment of natural growth. She stressed both had strengths but schools valued the first.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1870","question":"When Class 3 children are asked to ‘draw a scientist’, most draw a man. Reviews of such studies over several decades have found that:","options":["Children now draw more women scientists than decades ago, but drawing men increases with age","Children draw only women scientists today, so the stereotype has vanished","The share of children drawing men falls steadily as they move up to higher classes","Drawings show no gender pattern at all once children have studied science for a year"],"answer":0,"explanation":"Reviews of draw-a-scientist studies show more female scientists drawn now than in the 1960s–70s, yet children increasingly draw men as they get older, so classroom images and role models still matter.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1871","question":"Children watched several adult men and women choose between pairs of neutral items. Perry and Bussey found that children most strongly copied the choices of their own sex when:","options":["The models were children rather than adults of either sex","Only one same-sex model made the choice and others did not watch","The model was of the other sex but was rewarded for the choice","Most or all of the same-sex models agreed in their choices"],"answer":3,"explanation":"Children learn what counts as appropriate for their sex partly by noticing which behaviours are typical of many same-sex people; imitation was strongest when same-sex models showed high consensus.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1872","question":"Children in a Class 2 playground invent their own version of a ‘teacher’ game in which the ‘teacher’ is teased and rules are made up together. William Corsaro would see this as an example of:","options":["Passive internalisation: children absorb adult norms exactly as given, without changing them","Interpretive reproduction: children creatively take up adult culture to form their own peer culture","Regression: children return to the play of earlier stages when anxious about school","Classical conditioning: cues in the school setting trigger fixed, learnt play responses"],"answer":1,"explanation":"Corsaro argued that socialisation is not one-way; children appropriate and reshape adult information in their peer cultures and so both reproduce and change society.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1873","question":"Assertion (A): Even without any adult instruction, children in a playground may chase ‘boys versus girls’ and tease those who cross over, keeping the sexes apart. Reason (R): Children actively construct and police gender boundaries in their peer play, a process Barrie Thorne called ‘borderwork’.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Thorne’s observations showed children themselves marking and policing gender lines through games and teasing, which explains why boundaries persist even without adult pressure.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1874","question":"A Class 3 worksheet says, ‘Every child must bring his own lunch box and keep his desk clean.’ Research on such ‘generic he’ wording suggests that children reading it:","options":["Picture girls more often, since lunch and tidiness are seen as girls’ tasks","Understand that it includes everyone, so the wording has no effect on what they picture","Tend to picture boys, so inclusive wording such as ‘their’ or ‘his or her’ is better","Ignore pronouns completely and attend only to the instructions"],"answer":2,"explanation":"Studies show that generic masculine pronouns call up mostly male images in children’s minds, which can subtly suggest that instructions or roles are for boys; inclusive wording avoids this.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1875","question":"Children who watch many hours of television in which women appear mostly at home and men at work come to believe that this is how the real world is. This media effect is best described by:","options":["Cultivation theory","Catharsis theory","Uses and gratifications","Recapitulation theory"],"answer":0,"explanation":"Gerbner’s cultivation theory holds that heavy, long-term viewing gradually shapes viewers’ beliefs about social reality to match television’s portrayals, which can strengthen gender stereotypes.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1876","question":"Health records show that girls in a district now reach menarche, on average, a year or more earlier than their grandmothers did, and are taller as adults. This trend is mainly explained by:","options":["Better nutrition and health across generations, known as the secular trend","A genetic change in the population that has built up over two generations","Earlier admission to school, which speeds up children’s physical growth","Greater exam competition, which triggers the early release of growth hormones"],"answer":0,"explanation":"The secular trend towards earlier puberty and greater height has followed improvements in nutrition, health and living conditions; two or three generations are far too short for genetic change to explain it.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1877","question":"In Class 6, many girls are taller than the boys; by Class 10 most boys have caught up and passed them. The best explanation is that:","options":["Boys grow at a steady rate throughout, while girls stop growing at about twelve","Girls’ growth spurt usually starts about two years before boys’ does","Girls get better nutrition in childhood, which stops mattering in adolescence","Boys’ growth spurt happens in early childhood, before they join school"],"answer":1,"explanation":"Girls start and finish their growth spurt earlier; boys’ spurt comes later, lasts longer and is larger, so they overtake girls in mid-adolescence.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1878","question":"Which statement about early-maturing boys is best supported by research?","options":["They show no social differences from other boys, since only girls are affected by pubertal timing","They are usually more anxious and less popular, since their changing bodies make them stand out from classmates","They are often more popular and confident, but are also at higher risk of early substance use and rule-breaking","They do better in every respect, so schools should try to speed up maturation in other boys"],"answer":2,"explanation":"Early maturation often brings status for boys through size and sports, but it also draws them towards older peers and earlier risky behaviour; anxiety and lower status are more typical of late-maturing boys.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1879","question":"Many Class 11 students are sleepy and slow in a 7:30 a.m. first period, though they say they cannot fall asleep before 11 p.m. Sleep research explains this mainly by:","options":["An attention disorder that appears in most students at about sixteen years","Laziness learnt from late-night phone use, which is the only real cause of this pattern","Lower total sleep needs in adolescence, so they simply do not feel tired late at night","A biological shift in adolescents’ body clock, with sleep hormones released later at night"],"answer":3,"explanation":"Puberty shifts the circadian rhythm so that melatonin is released later, pushing natural sleep and wake times later while sleep needs remain high; screens can worsen this but are not the only cause.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1880","question":"A 16-year-old reasons as well as an adult about risks in a calm classroom discussion, yet takes a dangerous dare at night with friends watching. Which distinction best explains this gap?","options":["‘Cold’ cognition matures earlier than ‘hot’ cognition used in emotionally charged, social situations","Formal operations are lost in social settings and must be regained each time the person is alone","Adolescents understand risks only when they are told about them by a trusted adult","Adolescents have a weaker knowledge of risks than adults, whatever the situation"],"answer":0,"explanation":"Logical reasoning under calm conditions is adult-like by mid-adolescence, but self-control in arousing, peer-laden situations matures later, as the dual-systems account explains. Knowledge of risks is not the problem.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1881","question":"Robert Havighurst defined a developmental task as one that:","options":["Is decided only by physical maturation, with no part played by society or by the individual","Is set by teachers for each class level and must be passed before a child can be promoted","Appears only in adolescence and is resolved once and for all by about eighteen years","Arises around a certain period of life, and mastering it eases later tasks"],"answer":3,"explanation":"Havighurst saw developmental tasks as arising from physical maturation, cultural pressure and personal values; mastering them leads to adjustment and success later, while failure brings difficulty with later tasks.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1882","question":"A Class 10 student increasingly wants to make her own decisions and depends less on her parents for emotional support, though she still loves them. Leta Hollingworth called this adolescent process:","options":["Identity foreclosure","Psychological weaning","Emotional regression","Reactive detachment disorder"],"answer":1,"explanation":"Hollingworth used ‘psychological weaning’ for the adolescent’s gradual emotional and practical move towards independence from the family; it is a normal developmental process, not a disorder.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1883","question":"Harry Stack Sullivan held that, just before adolescence, the most important new need is met by a close same-sex friend, a ‘chum’. This need is for:","options":["Acceptance, through membership of a large and popular peer group","Tenderness, through the physical care and comfort given by a parent","Intimacy, through a relationship of mutual concern between equals","Romantic love, through a partner of the other sex at this age"],"answer":2,"explanation":"Sullivan placed the need for intimacy in preadolescence, first met in a chumship; tenderness belongs to infancy and the desire for romantic partners comes later in adolescence.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1884","question":"In Dexter Dunphy’s classic account of how adolescent peer groups change, which sequence is correct?","options":["Same-sex cliques → a mixed-sex crowd of linked cliques → loose groups of couples","A mixed-sex crowd of linked cliques → same-sex cliques → loose groups of couples","Loose groups of couples → same-sex cliques → a mixed-sex crowd of linked cliques","Same-sex cliques → loose groups of couples → a mixed-sex crowd of linked cliques"],"answer":0,"explanation":"Dunphy observed early adolescents in same-sex cliques, which then joined into larger mixed-sex crowds, and in late adolescence the crowd broke up into loosely linked couples.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1885","question":"In a large school, students talk about ‘the toppers’, ‘the sports gang’ and ‘the band kids’, though many so labelled have never spoken to each other. Researchers call such reputation-based groups:","options":["Chumships","Cliques","Dyads","Crowds"],"answer":3,"explanation":"Crowds are larger, reputation-based categories that place students by image or activity, whether or not members interact; cliques are small groups of friends who actually spend time together.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1886","question":"The son of a respected police officer, constantly told to be a ‘model student’, begins skipping school and openly copying the local troublemakers’ style. Erikson might describe this as:","options":["Identity achievement: committing to values after a period of exploration","A negative identity: taking on the very roles presented as most undesirable","Identity foreclosure: accepting his parents’ choices without exploring","Generativity: caring for the next generation through guidance and teaching"],"answer":1,"explanation":"Erikson described a negative identity as one built, often defiantly, on roles adults have shown as most undesirable, when acceptable identities seem out of reach or imposed.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1887","question":"A Class 11 student from a tribal community, who had never thought about her heritage, begins reading about her community’s history, talking to elders and attending cultural events, unsure what it means for her. In Jean Phinney’s model, she is in the stage of:","options":["Achieved ethnic identity","Unexamined ethnic identity","Ethnic identity search","Ethnic identity diffusion"],"answer":2,"explanation":"Phinney’s model moves from an unexamined ethnic identity, through a search (exploration) stage, to an achieved, secure sense of one’s ethnic identity; active exploration without settled commitment marks the search stage.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1888","question":"Asked, ‘If all purple animals have six legs, and Bholu is a purple animal, how many legs does Bholu have?’, an eight-year-old says, ‘There are no purple animals!’ while a fourteen-year-old answers ‘six’. The older child shows:","options":["Propositional thought, reasoning from premises regardless of whether they are true","Conservation, recognising that quantity stays the same despite changes in form","Seriation, arranging items in order along a dimension such as length","Animism, attributing life and feelings to things that are not alive"],"answer":0,"explanation":"In the formal operational stage adolescents can judge the logic of statements apart from real-world content; concrete thinkers tie reasoning to known reality and reject premises contrary to fact.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1889","question":"Ananya passionately campaigns for a plastic-free school in assembly, yet leaves plastic wrappers on her desk. David Elkind would describe this as:","options":["Imaginary audience: believing that everyone is watching and judging her behaviour","Personal fable: believing that her experiences are unique and that nothing can harm her","Apparent hypocrisy: believing that stating an ideal is the same as living up to it","Pseudostupidity: approaching a simple problem at too complex a level and failing"],"answer":2,"explanation":"Elkind used apparent hypocrisy for young adolescents’ feeling that expressing an ideal is enough, without the work of acting on it; it is a cognitive immaturity rather than deliberate dishonesty.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1890","question":"A bright Class 8 student gets a simple puzzle wrong because she looks for hidden tricks and complex motives that are not there. Elkind called this tendency:","options":["Personal fable","Pseudostupidity","Apparent hypocrisy","Imaginary audience"],"answer":1,"explanation":"Elkind’s pseudostupidity is the young adolescent’s habit of over-interpreting simple situations with newly gained formal thinking, so she fails not because the task is too hard but because it is too simple.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1891","question":"Simmons and Blyth found that girls’ self-esteem dropped most when they moved to a new, larger school at the same time as they were going through puberty. Their explanation was that:","options":["Girls’ self-esteem falls at thirteen for purely biological reasons","Puberty by itself lowers self-esteem, whatever kind of school a girl is in","A change of school by itself lowers self-esteem, whatever the stage of puberty","Several major changes at once overwhelm coping more than the same changes spread out"],"answer":3,"explanation":"Their ‘cumulative change’ view held that adolescents cope better when changes come one at a time; girls in schools without an early transition, facing puberty alone, showed smaller drops.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1892","question":"A 15-year-old writes, ‘I’m cheerful with friends, rude at home and shy in class. Which one is the real me?’ and feels upset by this. Susan Harter’s research suggests that:","options":["Noticing contradictory selves across roles peaks in mid-adolescence and is later integrated","This shows a serious identity disorder that needs specialist treatment straight away","Such contradictions are common in early childhood but become rare after about age ten","She is in Piaget’s concrete stage and cannot yet think abstractly about herself"],"answer":0,"explanation":"With abstract thought, middle adolescents notice that their traits differ across settings but cannot yet integrate them, which causes distress; by late adolescence they form higher-order ideas such as ‘moody’ or ‘flexible’.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1893","question":"Laurence Steinberg distinguished three kinds of adolescent autonomy. A Class 12 student who forms her own reasoned views on right and wrong, rather than taking them from parents or friends, shows:","options":["Behavioural autonomy","Emotional autonomy","Value autonomy","Economic autonomy"],"answer":2,"explanation":"Emotional autonomy concerns relinquishing childish dependence on parents, behavioural autonomy making and acting on one’s own decisions, and value autonomy holding an independent set of principles.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1894","question":"Research by Stattin and Kerr on how parents come to know what their adolescents are doing found that parents’ knowledge comes mainly from:","options":["Strict rules and curfews set by the parents","The adolescent’s own willingness to tell them","Parents’ questioning of friends and teachers","Checking the adolescent’s phone and private messages"],"answer":1,"explanation":"Their studies found that what parents know depends mostly on the teenager’s voluntary disclosure, which flows from a warm, trusting relationship, rather than from parental control or surveillance.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1895","question":"Which of these statements about adolescence are supported by research? I. Before puberty boys and girls show similar rates of depression, but after puberty girls show about twice the rate. II. Body dissatisfaction tends to rise in many girls during puberty. III. Most adolescents go through severe, continuous turmoil with their families.","options":["I, II and III","I and III only","II and III only","I and II only"],"answer":3,"explanation":"The gender gap in depression and the rise in girls’ body dissatisfaction around puberty are well documented; severe, continuous turmoil describes only a minority, contrary to the ‘storm and stress’ stereotype.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1896","question":"A Class 9 student says, ‘I like science, I’m good at maths and I want work that helps people, so maybe medicine or engineering.’ In Eli Ginzberg’s theory of career choice, she is in the:","options":["Tentative period","Fantasy period","Realistic period","Maintenance period"],"answer":0,"explanation":"Ginzberg described a fantasy period in childhood, a tentative period in early adolescence when interests, capacities and values are weighed, and a realistic period from about 17 when options are explored and narrowed.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1897","question":"A Class 10 student enjoys repairing bicycles, working with tools and building things with his hands. In John Holland’s RIASEC model, his interests are closest to the:","options":["Artistic type","Investigative type","Realistic type","Enterprising type"],"answer":2,"explanation":"Holland’s Realistic type prefers practical, hands-on work with tools, machines and objects; Investigative people like ideas and analysis, Artistic people self-expression, Enterprising people persuading and leading.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1898","question":"Which set consists entirely of core life skills listed by the World Health Organization for school-based life skills education?","options":["Decision making, time management, coping with stress","Decision making, empathy, coping with stress","Empathy, leadership, critical thinking","Self-awareness, goal setting, problem solving"],"answer":1,"explanation":"WHO’s ten core life skills are decision making, problem solving, creative thinking, critical thinking, effective communication, interpersonal relationships, self-awareness, empathy, coping with emotions and coping with stress.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1899","question":"Which feature most clearly makes cyberbullying harder for adolescents to escape than playground bullying?","options":["It is always carried out by older students against younger ones","It always involves physical threats that are later carried out inside the school","It happens only between students who have never met each other in person","It can reach the victim at any hour and spread to a wide audience, often anonymously"],"answer":3,"explanation":"Online bullying follows the student home, can be shared widely and kept, and may be anonymous; it frequently involves classmates and is not limited to physical threats or older bullies.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1900","question":"A survey shows that most Class 10 students in a school believe ‘most of my classmates smoke’, though only a small minority actually do. A programme that shares the accurate figures with students is using the:","options":["Social norms approach","Fear-appeal approach","Information-deficit approach","Zero-tolerance approach"],"answer":0,"explanation":"The social norms approach corrects exaggerated beliefs about how common a risky behaviour is, because adolescents tend to conform to what they think peers do; fear appeals and bare health facts work differently.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1901","question":"During free play, four-year-old Tenzin stands near a group building a sand fort, watches closely, asks them questions and makes suggestions, but does not join in. In Mildred Parten’s categories, this is:","options":["Onlooker behaviour","Solitary play","Parallel play","Unoccupied behaviour"],"answer":0,"explanation":"An onlooker watches a particular group and may talk to them without joining; unoccupied behaviour is aimless watching of anything that catches attention, and parallel play means playing beside others with similar materials.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1902","question":"Several pre-schoolers are all making clay animals at one table. They chat, lend each other tools and admire each other’s work, but each makes whatever he likes and there is no shared plan or division of roles. In Parten’s terms this is:","options":["Cooperative play","Associative play","Parallel play","Onlooker behaviour"],"answer":1,"explanation":"In associative play children interact and share materials but do not organise around a common goal; cooperative play involves a shared aim and assigned roles, while parallel play involves little interaction at all.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1903","question":"Parten saw solitary play as the least mature form of social play. Later research by Kenneth Rubin and others suggested that, for a five-year-old who often builds detailed models alone:","options":["The child is still at the stage of unoccupied behaviour and needs adult direction","Any solitary play at this age shows a social delay that needs immediate referral","Solitary constructive play is not in itself a warning sign and can go with competence","The child should be stopped from building alone and placed in a group every time"],"answer":2,"explanation":"Rubin found that the kind of solitary play matters: solitary construction and reading are linked with competence, whereas aimless, reticent hovering or repetitive solitary-functional play in older pre-schoolers is more of a concern.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1904","question":"Match each play activity with Smilansky’s cognitive category. P. A toddler repeatedly fills and empties a bucket of water. Q. A child builds a bridge from blocks. R. Children act as a doctor and patient. S. Children play kho-kho by its rules. 1. Constructive play 2. Games with rules 3. Functional play 4. Dramatic play","options":["P-3, Q-1, R-2, S-4","P-1, Q-3, R-4, S-2","P-3, Q-4, R-1, S-2","P-3, Q-1, R-4, S-2"],"answer":3,"explanation":"Functional play is repeated simple muscle action, constructive play makes something, dramatic play involves pretence and roles, and games with rules follow agreed rules; Smilansky adapted these from Piaget.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1905","question":"Sara Smilansky’s studies of sociodramatic play found that children from very poor families showed less of it than other children. What did she conclude from her interventions?","options":["Adult ‘play tutoring’ could increase sociodramatic play and the skills linked with it","Such children lacked the ability for pretend play, so formal drills should replace it","The difference was hereditary and could not be changed by any adult support","Pretend play was harmful for these children, as it confused fantasy with reality"],"answer":0,"explanation":"Smilansky showed that teachers modelling roles, suggesting themes and joining play raised the amount and quality of sociodramatic play, with gains in language and social skills; the gap reflected opportunity, not ability.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1906","question":"Match each classical theory of play with its claim. P. Surplus energy theory Q. Relaxation (recreation) theory R. Practice (pre-exercise) theory S. Recapitulation theory 1. Play prepares the young for adult roles 2. Play burns off energy left over after needs are met 3. Play re-enacts stages in the evolution of the human race 4. Play restores energy used up in work","options":["P-2, Q-1, R-4, S-3","P-4, Q-2, R-1, S-3","P-2, Q-4, R-3, S-1","P-2, Q-4, R-1, S-3"],"answer":3,"explanation":"Schiller and Spencer saw play as using up surplus energy; Lazarus saw it as recreation from fatigue; Groos saw it as practice of instincts needed in adult life; Hall saw it as reliving the race’s past.","difficulty":"hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1907","question":"Kittens stalk and pounce on a ball of wool, and young girls and boys play at cooking, shopkeeping and farming. Which theorist explained such play mainly as practice for skills needed in adult life?","options":["Herbert Spencer","Karl Groos","G. Stanley Hall","Moritz Lazarus"],"answer":1,"explanation":"Groos’s pre-exercise (practice) theory held that play exercises instincts and skills the animal or child will need as an adult; Spencer linked play to surplus energy and Hall to recapitulation of evolution.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1908","question":"After receiving a painful injection, four-year-old Pihu spends days playing ‘doctor’, firmly giving injections to her dolls. A psychoanalytic view of play would explain this mainly as:","options":["Practising a skill she will need later as an adult in a medical career","Using up surplus energy left over after her ordinary needs were met","Mastering an upsetting event by turning a passive role into an active one","Imitating a model only because the doctor was rewarded for his actions"],"answer":2,"explanation":"Freud described children repeating distressing events in play so that what they suffered passively they now control actively, which helps them master the anxiety; the other options belong to other theories.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1909","question":"Erik Erikson described play as moving through three spheres. Which order is correct?","options":["Autosphere (own body) → microsphere (small toys) → macrosphere (play shared with others)","Microsphere (small toys) → autosphere (own body) → macrosphere (play shared with others)","Macrosphere (play shared with others) → microsphere (small toys) → autosphere (own body)","Autosphere (own body) → macrosphere (play shared with others) → microsphere (small toys)"],"answer":0,"explanation":"Erikson saw the infant first playing with its own body, then the young child mastering a small world of toys, and later sharing play with others in the wider macrosphere.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1910","question":"A counsellor lets a withdrawn six-year-old choose freely among toys, reflects the child’s feelings back without directing the play, and accepts whatever the child does within a few safety limits. This approach follows:","options":["Smilansky’s sociodramatic play tutoring","Skinner’s programmed instruction","Montessori’s method of practical-life exercises","Virginia Axline’s non-directive play therapy"],"answer":3,"explanation":"Axline, drawing on Carl Rogers, set out principles of non-directive play therapy: warm acceptance, reflecting feelings and letting the child lead, so that play becomes a means of expressing and working through feelings.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1911","question":"A teacher wants to tell rough-and-tumble play from real fighting in the playground. Which set of signs points to play?","options":["Frowns and fixed stares, one child always winning, and the children separating afterwards","Smiling ‘play faces’, children taking turns being on top, and staying together afterwards","Loud shouting, many children watching, and a struggle lasting several minutes","Children of the same sex involved, physical contact, and running across the ground"],"answer":1,"explanation":"Pellegrini’s work shows that rough-and-tumble play has play faces, role reversal and self-handicapping, and partners stay together after; real fights show hostile faces, one-sided outcomes and separation. Noise and contact occur in both.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1912","question":"A teacher wants children to discover the properties of shapes. She sets out a ‘mystery shapes’ box with chosen shapes, lets children handle and sort them as they like, and asks open questions such as ‘What do you notice about the corners?’. This is best described as:","options":["Direct instruction","Free play","Guided play","Unstructured exploration"],"answer":2,"explanation":"In guided play the adult designs the setting with a learning goal in mind and supports through questions while the child keeps the lead; in free play there is no adult learning goal, and in direct instruction the adult leads.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1913","question":"In the ‘Tools of the Mind’ curriculum, pre-schoolers draw and talk through a ‘play plan’ before pretend play and keep to the roles they have chosen. The main aim, following Vygotsky, is to develop:","options":["Self-regulation and executive functions through mature make-believe play","Fine motor control and neat handwriting through drawing the plan before play","Rote memory for the vocabulary used in the different pretend themes","Healthy competition between children for the most popular roles in play"],"answer":0,"explanation":"Bodrova and Leong used play plans and sustained roles to make children act by rules of the imaginary situation, strengthening inhibition, working memory and planning; studies reported gains in executive functions.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1914","question":"A Class 1 teacher adds menus, order pads, price labels and pencils to the play ‘dhaba’ corner. Studies of such literacy-enriched play settings found that children:","options":["Played less, because the materials made the corner feel like a classroom","Ignored the materials, since play and literacy cannot be combined","Read and wrote more during play, using print for real purposes","Learnt to read only if the teacher tested them on the labels every day"],"answer":2,"explanation":"Research by Neuman and Roskos and others found that adding print props to play settings increased children’s reading and writing behaviours and their talk about print during play.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1915","question":"A two-year-old pretends to ‘drink’ only from a toy cup, while a four-year-old happily uses a block as a cup and a five-year-old ‘drinks’ from an imaginary cup. What does this show?","options":["Younger children are more imaginative, since they need fewer objects to pretend","Pretend play becomes less dependent on realistic objects as symbolic thought develops","Pretend play is learnt mainly by copying the uses of toys that adults provide","Children stop pretending once they can use blocks as other objects"],"answer":1,"explanation":"Object substitution develops gradually: toddlers need realistic props, older pre-schoolers can use less similar substitutes, and later they can pretend with no object at all, reflecting growing ability to separate meaning from objects.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1916","question":"A school removes all climbing frames and bans running games to prevent injuries. Research on children’s ‘risky play’ suggests that, within reasonable safety limits, such play:","options":["Matters mainly for boys, so girls lose little or nothing from such a ban","Has little developmental value, so removing it costs children nothing important","Makes children reckless in later life, so a full ban is the safer policy","Helps children judge risks and manage fear, so it should not be removed altogether"],"answer":3,"explanation":"Studies of risky play, such as Sandseter’s, suggest that climbing, speed and rough play help children learn to assess risk, master fear and build confidence; the aim is to manage hazards, not eliminate challenge.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1917","question":"Five-year-old Riya often talks to an imaginary friend called ‘Chiku’. Her parents worry. What does research suggest?","options":["Imaginary companions are common in early childhood and are not a sign of disturbance","Imaginary companions signal emotional disturbance and call for professional treatment","Imaginary companions appear only in only-children who have no real friends","Imaginary companions show that the child cannot tell fantasy from reality"],"answer":0,"explanation":"Studies by Marjorie Taylor and others show that a majority of children have pretend friends at some point; such children usually know the friend is pretend and often show good social understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1918","question":"In studies of primary children, attention to classwork was higher just after recess, and the longer children waited for recess, the less attentive they became. Pellegrini and Bjorklund linked this mainly to:","options":["The fact that recess removes the need for any teacher-directed work","Physical tiredness after recess, which makes children sit still and quiet afterwards","Young children’s immature cognitive control, which benefits from spaced breaks","Rewards handed out at recess, which reinforce attention in the next period"],"answer":2,"explanation":"Their ‘cognitive immaturity’ view holds that young children are less able to sustain focused, effortful attention, so breaks spaced through the day restore attention; recess complements, not replaces, classwork.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1919","question":"Which of these is NOT among the commonly listed characteristics of play (as given by Rubin, Fein and Vandenberg)?","options":["It is intrinsically motivated rather than done for a reward","It is aimed at a product that an adult has set in advance","It focuses on the process more than on any end result","It is non-literal, often involving pretence or ‘as if’"],"answer":1,"explanation":"Play is intrinsically motivated, process-oriented, non-literal, free from externally imposed rules and actively engaged; an activity steered towards an adult’s pre-set product is closer to work.","difficulty":"hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1920","question":"Pre-schoolers had to get a prize out of a box by clamping two sticks together. One group first played freely with the sticks and clamps; another watched an adult demonstrate the solution. Sylva, Bruner and Genova found that the play group:","options":["Solved it as well but gave up sooner, because play made them restless","Failed far more often, since free play without any instruction teaches nothing useful","Solved it faster only because they had been told the answer in advance","Solved the problem about as well as the demonstration group and persisted more when stuck"],"answer":3,"explanation":"Children who had played did as well as those who saw the principle demonstrated, and used hints more and gave up less, supporting Bruner’s view that play lowers the cost of trying and encourages flexible problem solving.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1921","question":"How did Maria Montessori’s view of young children’s fantasy and pretend play differ from Froebel’s and Vygotsky’s?","options":["She gave it less value, preferring real, purposeful activities with real materials","She valued it most of all, seeing it as the highest form of children’s learning","She saw it as dangerous and banned all play from her Children’s Houses","She agreed with them fully and built her whole method around sociodramatic play"],"answer":0,"explanation":"Montessori preferred practical-life work with real, child-sized tools and graded materials to make-believe, whereas Froebel valued play as self-expression and Vygotsky saw pretend play as a leading activity of development.","difficulty":"hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1922","question":"Which sequence matches Piaget’s types of play to the periods of development in which they first become prominent?","options":["Practice play (sensorimotor) → games with rules (pre-operational) → symbolic play (concrete operational)","Symbolic play (sensorimotor) → practice play (pre-operational) → games with rules (concrete operational)","Practice play (sensorimotor) → symbolic play (pre-operational) → games with rules (concrete operational)","Games with rules (sensorimotor) → symbolic play (pre-operational) → practice play (concrete operational)"],"answer":2,"explanation":"Infants repeat actions for pleasure (practice play); from about two, symbolic play reflects the semiotic function; from about seven, children enjoy rule-governed games that need cooperation and decentration.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1923","question":"In a pretend ‘bus’ game, the teacher wants to deepen play without taking it over. In Smilansky’s terms, which is an ‘inside’ intervention?","options":["She stands just outside the play and says, ‘Perhaps the bus needs a conductor to sell tickets.’","She takes the role of a passenger and asks the ‘conductor’ for a ticket to the market","She stops the game to explain how real buses work and then lets it restart","She praises the children afterwards for playing nicely together on the bus"],"answer":1,"explanation":"Inside intervention means the adult joins the play in a role and models from within the pretend frame; outside intervention gives suggestions or comments from outside the play while the children keep their roles.","difficulty":"hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1924","question":"Given a new toy with levers and lights, a child first looks at it intently, handles it carefully and tries each lever; later she uses it in many relaxed, varied ways in a pretend game. Corinne Hutt distinguished the first phase as exploration. Its guiding question is:","options":["‘How can I win with this object?’","‘What can I do with this object?’","‘Who gave me this object?’","‘What does this object do?’"],"answer":3,"explanation":"Hutt found that exploration, focused on discovering an object’s properties, comes first; play, asking what the child can do with it, follows once the object is familiar.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1925","question":"A pre-school is choosing materials for its play area. Which choice best supports varied, imaginative play?","options":["Open-ended materials such as blocks, cloth and boxes that can become many things","Battery toys that perform one fixed action each time a button is pressed","Detailed model kits that can be assembled in only one correct way","Worksheets with play-themed pictures for children to colour in neatly"],"answer":0,"explanation":"Open-ended materials let children assign many meanings and uses, encouraging symbolic, constructive and cooperative play, while single-purpose toys and colouring sheets limit what children can invent.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1926","question":"On Jerome Kagan’s Matching Familiar Figures Test, a child must find the one picture, among six similar variants, that exactly matches a standard. Aryan answers within seconds and makes many errors; Bela takes much longer and makes few. In Kagan’s terms:","options":["Aryan is field dependent and Bela is field independent in cognitive style","Aryan has an impulsive cognitive tempo and Bela a reflective one","Aryan has low intelligence and Bela high intelligence on this measure","Aryan is a divergent thinker and Bela a convergent thinker on such tasks"],"answer":1,"explanation":"Kagan’s reflection–impulsivity dimension combines response speed and accuracy on uncertain tasks: fast and inaccurate is impulsive, slow and accurate is reflective. It is a style of responding, not a measure of intelligence or of field dependence.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1927","question":"Jerome Kagan found that some infants react strongly to unfamiliar sights and sounds and become shy, cautious toddlers. Follow-up research on such ‘behaviourally inhibited’ children showed that:","options":["Inhibition is moderately stable, but many become less shy, especially with gentle encouragement to approach","Inhibition is completely fixed, so a shy toddler always becomes a withdrawn adult whatever happens","Inhibition disappears in almost all children by school age, regardless of how they are handled","Inhibition is caused entirely by over-protective parenting and has no basis in temperament"],"answer":0,"explanation":"Kagan’s longitudinal work found a biologically based tendency with some stability, yet many inhibited toddlers became less so, particularly when caregivers gently supported approach rather than either forcing or shielding them.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1928","question":"Rahul, a highly active child, does well with a Class 2 teacher who builds in movement and short tasks, but is constantly in trouble with a teacher who expects children to sit still for long periods. Thomas and Chess would explain this through the idea of:","options":["Fixed hereditary traits that the environment cannot influence","A difficult temperament that always predicts poor school adjustment","Goodness of fit between temperament and the demands of the setting","Low intelligence showing up only when tasks become long"],"answer":2,"explanation":"Thomas and Chess stressed that adjustment depends on the match between a child’s temperament and the expectations of the environment; the same child fares well where demands fit his temperament.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1929","question":"Mary Rothbart’s model of temperament includes a dimension that covers a child’s ability to hold back a dominant response, such as waiting for a turn, and to shift attention on purpose. This dimension is called:","options":["Rhythmicity","Surgency (extraversion)","Negative affectivity","Effortful control"],"answer":3,"explanation":"Rothbart’s three broad dimensions are surgency/extraversion, negative affectivity and effortful control; effortful control involves inhibitory and attentional control and predicts later self-regulation. Rhythmicity is one of Thomas and Chess’s nine dimensions.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1930","question":"Babbling appears at about the same age in infants across very different cultures and home environments, and even deaf infants begin to babble vocally. Waddington’s term for such strongly genetically guided development is:","options":["Reaction range","Canalisation","Niche-picking","Imprinting"],"answer":1,"explanation":"A highly canalised trait follows a similar course across a wide range of environments, like a ball rolling down a deep groove; a reaction range describes the spread of outcomes a genotype allows in different environments.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1931","question":"Large reviews of the ‘Big Five’ personality traits and school achievement have found that the trait most consistently linked with higher marks is:","options":["Neuroticism","Extraversion","Openness to experience","Conscientiousness"],"answer":3,"explanation":"Conscientiousness, being organised, persistent and dependable, predicts academic performance across ages, partly independent of intelligence; extraversion shows weak or mixed links and neuroticism, if anything, a small negative one.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1932","question":"Hans Eysenck first described personality using two broad dimensions, and later added a third. Which set is his?","options":["Extraversion–introversion, neuroticism–stability, psychoticism","Openness, conscientiousness and agreeableness, with two more traits","Cardinal, central and secondary traits of the individual","Surface traits, source traits and dynamic (motivational) traits"],"answer":0,"explanation":"Eysenck’s PEN model uses extraversion, neuroticism and psychoticism; openness and the others belong to the Big Five, cardinal/central/secondary traits are Allport’s, and surface/source traits are Cattell’s.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1933","question":"Eysenck proposed a biological explanation for why introverted students often prefer quiet study and avoid noisy crowds. According to him, introverts:","options":["Have weaker memories, so they need quiet to remember what they study","Have a lower resting level of cortical arousal, so they actively seek out extra stimulation","Have a higher resting level of cortical arousal, so extra stimulation quickly feels too much","Have less intelligence, so they cannot process several inputs at once"],"answer":2,"explanation":"Eysenck argued that introverts are chronically more aroused, so they avoid further stimulation, while extraverts are under-aroused and seek it; this concerns preference for stimulation, not memory or intelligence.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1934","question":"Carl Jung described a personality type whose energy is directed inward, who prefers reflection and a few close relationships, and who is drained by long social gatherings. This type is called:","options":["Extravert","Introvert","Ambivert","Endomorph"],"answer":1,"explanation":"Jung’s introvert turns attention and energy towards the inner world of thoughts and feelings; the extravert turns outward. An ambivert shows both tendencies, and endomorph is one of Sheldon’s body types.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1935","question":"In William Sheldon’s body-type theory, a lean, delicate, tall build (ectomorph) was linked with which temperament?","options":["Ambiversion: equally outgoing and reserved in all settings","Viscerotonia: relaxed, sociable and fond of comfort and food","Somatotonia: assertive, energetic and fond of adventure","Cerebrotonia: restrained, sensitive and inclined to inhibition"],"answer":3,"explanation":"Sheldon paired endomorphy with viscerotonia, mesomorphy with somatotonia and ectomorphy with cerebrotonia. His links between physique and temperament are now regarded as weak and are not used to judge children.","difficulty":"moderate","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1936","question":"Mahatma Gandhi’s life is often said to have been organised around a commitment to non-violence. In Gordon Allport’s trait theory, a single trait that dominates a person’s whole life like this is a:","options":["Cardinal trait","Central trait","Secondary trait","Source trait"],"answer":0,"explanation":"Allport called rare, all-pervading traits cardinal; central traits are the handful of general characteristics describing most people, and secondary traits are narrower preferences. Source traits belong to Cattell’s theory.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1937","question":"Raymond Cattell used factor analysis on many observed behaviours. In his theory, the 16 basic underlying factors that explain clusters of observable behaviour are called:","options":["Cardinal traits","Surface traits","Source traits","Secondary traits"],"answer":2,"explanation":"Cattell distinguished surface traits, clusters of behaviour seen together, from the deeper source traits that cause them; his 16PF questionnaire measures sixteen source traits.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1938","question":"A counsellor shows a child pictures of animals in human-like situations and asks her to tell a story about each, to learn about her concerns and relationships. This is:","options":["A self-report inventory of the child’s personality traits","A projective technique, the Children’s Apperception Test","A standardised test of the child’s verbal intelligence","A rating scale completed by the child’s class teacher"],"answer":1,"explanation":"Projective techniques present ambiguous stimuli so that the person projects needs and conflicts into responses; the CAT, adapted from the TAT for children, uses animal figures.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1939","question":"When a personality questionnaire asks Class 9 students, ‘Do you always tell the truth?’, many answer ‘Yes’. This illustrates a major limitation of self-report inventories, namely:","options":["The halo effect: one good trait colouring the rater’s judgement of others","Projection: revealing hidden conflicts through ambiguous pictures","Social desirability: answering in ways that look good rather than accurately","Low reliability caused by scoring that depends on the examiner’s judgement"],"answer":2,"explanation":"Respondents may present themselves favourably, so inventories often include lie or social-desirability scales. Projection belongs to projective tests, and the halo effect concerns ratings by others.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1940","question":"In John Carroll’s model of school learning, how much a student learns depends on the ratio of:","options":["Time actually spent on learning to the time the student needs to learn","Marks obtained in class tests to marks obtained in annual examinations","Intelligence quotient to the age of the student at the time of learning","Number of teachers in the school to the number of students in each class"],"answer":0,"explanation":"Carroll saw aptitude as the time needed to learn; time spent depends on opportunity and perseverance. If enough time and good instruction are given, most students can learn, which Bloom built into mastery learning.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1941","question":"A study finds that highly structured, step-by-step teaching helps anxious, lower-scoring students most, while a more open, discovery approach suits confident, high-scoring students better. Cronbach and Snow called such findings:","options":["Practice and fatigue effects","Expectancy (Pygmalion) effects","Regression towards the mean","Aptitude–treatment interactions"],"answer":3,"explanation":"An aptitude–treatment interaction exists when the best method depends on learner characteristics, so no single method is best for everyone; it supports adapting instruction to individual differences.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1942","question":"Children who read well early read more, gain more vocabulary and knowledge, and so read even better, while weak early readers read less and fall further behind. Keith Stanovich called this:","options":["The Flynn effect","The Matthew effect","The Pygmalion effect","The Hawthorne effect"],"answer":1,"explanation":"Stanovich used the ‘rich get richer’ Matthew effect to describe how early differences in reading widen over time, which is why early support for weak readers matters so much.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1943","question":"A test that asks students to solve problems based on what was taught in Class 7 maths is an achievement test. A test used to predict how well students will do in a future course of study, such as music training, is:","options":["An interest inventory","An attitude scale","An aptitude test","A diagnostic test"],"answer":2,"explanation":"Achievement tests measure what has been learnt; aptitude tests predict potential to learn in a future area. Interest inventories measure preferences, and diagnostic tests locate specific learning difficulties.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1944","question":"Benjamin Bloom reported that students taught one-to-one by a tutor using mastery methods scored about two standard deviations above students taught in a conventional class. The ‘2 sigma problem’ he posed to teachers was:","options":["How to find group teaching methods that come close to the results of one-to-one tutoring","How to raise every single student to two standard deviations above the national mean","How to pick out the two per cent of students who most need individual tutoring","How to cut class time by two-thirds without lowering average achievement"],"answer":0,"explanation":"Since one-to-one tutoring is too costly for all, Bloom challenged educators to find group methods, such as mastery learning with feedback and correctives, that approach its effects.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1945","question":"In Fred Keller’s Personalized System of Instruction, students work through units of written material, take a test on each unit and move on only after showing mastery, with older students acting as proctors. Which feature is central to PSI?","options":["Group tests, so the class moves on together","Lectures as the main source of new content","Grading on a curve, so only a few earn top marks","Self-pacing, so each student moves on when ready"],"answer":3,"explanation":"Keller’s PSI is self-paced and mastery-based, relies on written materials and proctors, and uses lectures mainly for motivation; it treats individual differences in learning time rather than ranking students.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1946","question":"Which of the Big Five personality traits is most consistently associated with creativity and divergent thinking?","options":["Conscientiousness","Openness to experience","Extraversion (sociability)","Emotional stability"],"answer":1,"explanation":"Openness, which includes imagination, curiosity and preference for variety, is the trait most strongly linked with creative achievement; conscientiousness predicts marks but is not especially tied to creativity.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1947","question":"Learning a new topic, Ishaan likes to go step by step, mastering each small part before moving on, while Tanya first wants the big picture and links ideas across the whole topic. Gordon Pask would call Ishaan’s style:","options":["Field independent","Holist","Serialist","Reflective"],"answer":2,"explanation":"Pask distinguished serialists, who build understanding in linear, step-by-step sequences, from holists, who prefer to grasp the overall structure and make wide connections first.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1948","question":"A Class 4 teacher reports, ‘Neha now reads 60 words per minute, up from 35 in June.’ She is comparing Neha with her own earlier performance rather than with classmates or a fixed standard. This is:","options":["Ipsative assessment","Norm-referenced assessment","Criterion-referenced assessment","Summative assessment"],"answer":0,"explanation":"Ipsative assessment compares a learner with her own previous attainment, which respects individual differences in starting points; norm-referenced compares with others and criterion-referenced with a set standard.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1949","question":"A teacher notices that her quieter, more introverted students rarely answer when she calls for instant replies. Which practice best allows for this individual difference without lowering expectations?","options":["Grading participation only by the number of times a student speaks aloud","Calling only on students who raise their hands first, so no one is put on the spot","Excusing introverted students from all speaking tasks to protect their comfort","Think-pair-share: individual thinking time, then discussion with a partner, then sharing"],"answer":3,"explanation":"Thinking time and a low-risk partner stage let reflective students prepare and still contribute to the whole class; excusing them or rewarding only quick talkers either lowers expectations or favours one temperament.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1950","question":"Arif is among the best in his class at mathematics but well below his own level in written English. This difference within Arif is an example of:","options":["Inter-individual differences","Intra-individual differences","Group differences","Developmental delay"],"answer":1,"explanation":"Intra-individual differences are variations among a single person’s own abilities; inter-individual differences are variations between people, and an uneven profile alone does not indicate developmental delay.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1951","question":"Match each student’s remark with the kind of metacognitive knowledge John Flavell described. P. ‘I remember words much better than numbers.’ Q. ‘Essay questions need more organised revision than one-word questions.’ R. ‘Making my own summary helps me understand a chapter.’ 1. Strategy knowledge 2. Person knowledge 3. Task knowledge","options":["P-2, Q-1, R-3","P-3, Q-2, R-1","P-2, Q-3, R-1","P-1, Q-3, R-2"],"answer":2,"explanation":"Flavell divided metacognitive knowledge into person variables (beliefs about oneself and others as learners), task variables (how a task’s demands affect performance) and strategy variables (which methods work for which goals).","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1952","question":"While reading a science chapter, Mohit stops and says to himself, ‘Wait, I didn’t follow that paragraph about friction,’ and goes back to reread it with the diagram. Which component of metacognitive regulation is he mainly showing?","options":["Monitoring his comprehension while the task is going on","Planning which strategies to use before starting the task","Evaluating the final outcome after the task is completed","Declaring knowledge of facts he has already memorised"],"answer":0,"explanation":"Metacognitive regulation includes planning (before), monitoring (during) and evaluating (after). Noticing a breakdown in understanding mid-reading and fixing it is monitoring with a repair strategy.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1953","question":"In Barry Zimmerman’s cyclical model of self-regulated learning, setting goals and choosing strategies, then observing oneself while working, and then judging results and explaining them belong, in order, to which phases?","options":["Performance, forethought, self-reflection","Forethought, performance, self-reflection","Self-reflection, performance, forethought","Forethought, self-reflection, performance"],"answer":1,"explanation":"Zimmerman’s forethought phase covers goal setting, planning and self-efficacy; the performance phase includes self-control and self-observation; the self-reflection phase includes self-evaluation, attributions and adjustments that feed the next cycle.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1954","question":"Before a unit on birds, a Class 4 teacher draws three columns on the board, fills the first with what children already know, the second with what they want to find out, and returns at the end to fill the third. This strategy is called:","options":["A flow chart","A concept map","A Venn diagram","A KWL chart"],"answer":3,"explanation":"Donna Ogle’s KWL chart (Know, Want to know, Learned) activates prior knowledge, gives learners a say in what they will explore, and ends with reflection on what was learnt.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1955","question":"Hattie and Timperley suggest that effective feedback answers three questions. Which set matches ‘feed up’, ‘feed back’ and ‘feed forward’ in that order?","options":["Where to next? How am I going? Where am I going?","How am I going? Where am I going? Where to next?","Where am I going? How am I going? Where to next?","Where am I going? Where to next? How am I going?"],"answer":2,"explanation":"Feed up clarifies the goal, feed back describes progress towards it, and feed forward identifies the next steps; together they help close the gap between current and desired performance.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1956","question":"Ms Kaur asks, ‘Why do we see lightning before we hear thunder?’ Rani answers, ‘Because light is faster.’ Ms Kaur then turns to Sohail: ‘Do you agree with Rani? Why?’ This questioning technique is called:","options":["Rhetorical questioning","Probing","Prompting","Redirecting"],"answer":3,"explanation":"Redirecting puts the same question or a classmate’s answer to another student, widening participation; probing would ask Rani herself to explain further, and prompting gives hints to a student who is stuck.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1957","question":"In the 5E model of inquiry teaching, which sequence is correct?","options":["Engage, Explore, Explain, Elaborate, Evaluate","Explain, Engage, Explore, Elaborate, Evaluate","Engage, Explain, Explore, Evaluate, Elaborate","Explore, Engage, Explain, Evaluate, Elaborate"],"answer":0,"explanation":"Students’ interest is first engaged, they then explore phenomena hands-on, concepts are explained (building on that exploration), applied in new situations (elaborate), and understanding is evaluated.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-child-development-1958","question":"Which classroom sequence is typical of problem-based learning?","options":["The teacher first explains all the concepts, then gives problems from the textbook to practise them","Students first meet an open, real problem, find out what they need to learn, research it and propose solutions","Students read the textbook chapter alone and then answer the questions given at its end","The teacher demonstrates a solution, then students repeat the same steps on similar problems"],"answer":1,"explanation":"In problem-based learning an ill-structured, realistic problem comes first and drives self-directed inquiry, with the teacher as facilitator; teaching concepts first and then setting problems is conventional instruction.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1959","question":"Class 6 decides to set up a small kitchen garden. Which order follows the steps of William Kilpatrick’s project method?","options":["Purposing, executing, planning, judging","Planning, purposing, executing, judging","Purposing, planning, executing, judging","Executing, purposing, planning, judging"],"answer":2,"explanation":"Kilpatrick, Dewey’s student, described a project as a ‘wholehearted purposeful activity’: learners first form the purpose, then plan, carry out the plan and finally judge the outcome.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1960","question":"In Robert Slavin’s Student Teams–Achievement Divisions (STAD), mixed-ability teams study together, but each student takes the quiz alone. How are team scores worked out?","options":["From one joint quiz answered together by the whole team","From the single highest quiz score obtained by any member","From the quiz score of the weakest member of the team only","From how much each member improves on his or her own past average"],"answer":3,"explanation":"STAD awards improvement points based on each student’s gain over his own base score, so every member, weak or strong, can contribute equally; individual quizzes keep each member accountable.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1961","question":"A teacher first solves a sum aloud while the class watches, then solves similar sums together with the class, then lets pairs try, and finally has each child solve on his own. This follows the model of:","options":["Gradual release of responsibility","Skinner’s linear programmed instruction","Bruner’s guided discovery learning","Rote drill and repeated practice"],"answer":0,"explanation":"Pearson and Gallagher’s gradual release model (‘I do, we do, you do together, you do alone’) shifts responsibility from teacher to learner step by step.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1962","question":"Before dropping a sheet of paper and a crumpled ball of the same paper, a teacher asks students to write down which will land first and why, then to watch, and then to reconcile what they saw with what they predicted. This strategy is:","options":["Think–Pair–Share","Predict–Observe–Explain","Know–Want–Learned (KWL)","Drill and repeated practice"],"answer":1,"explanation":"White and Gunstone’s POE makes students commit to a prediction based on their ideas, so a surprising observation creates conflict that the explanation stage helps resolve.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1963","question":"In Helen Parkhurst’s Dalton Plan, students receive monthly assignments in each subject, decide their own pace and order of work, and use subject ‘laboratories’ with teachers as advisers. Its central principles are:","options":["Teacher lectures, rote revision and monthly ranking","Strict class timetables, daily drill and frequent rewards","Freedom, cooperation and budgeting of one’s own time","Play, songs and Froebel-style gifts in groups"],"answer":2,"explanation":"Parkhurst based the Dalton Plan on freedom to work at one’s own rhythm, cooperation among students, and responsibility for budgeting time through assignment contracts.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1964","question":"Rousseau, in ‘Emile’, recommended ‘negative education’ in the early years. By this he meant that:","options":["Children should be corrected for every mistake so that bad habits never take root","Adults should not force lessons or rules early, but let nature and experience teach","Early education should focus on correcting children’s negative feelings and attitudes","Children should learn by memorising what not to do from books of rules"],"answer":1,"explanation":"For Rousseau, early education should guard the heart from vice and the mind from error rather than teach virtue and truth directly; the child learns from things and natural consequences at his own pace.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1965","question":"Pestalozzi insisted that teaching should begin with what children directly perceive through the senses, moving from the concrete to the abstract. His term for this principle is:","options":["Anschauung (sense impression)","Kindergarten (child garden)","Apperception (assimilating ideas)","Prepared environment"],"answer":0,"explanation":"Pestalozzi’s Anschauung stressed observation and sense experience as the foundation of knowledge, leading to object lessons; the kindergarten is Froebel’s, apperception Herbart’s, and the prepared environment Montessori’s.","difficulty":"moderate","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1966","question":"Which order gives the Herbartian formal steps of a lesson?","options":["Application, preparation, presentation, association, generalisation","Presentation, preparation, generalisation, association, application","Preparation, association, presentation, application, generalisation","Preparation, presentation, association, generalisation, application"],"answer":3,"explanation":"Herbart’s followers set out preparation (linking to old ideas), presentation, association (comparison), generalisation and application; the plan is systematic but largely teacher-directed.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1967","question":"In a Class 7 discussion, the teacher responds to each answer by asking others to build on it, chains the ideas together over several turns and keeps the discussion moving towards a clear goal. Robin Alexander calls teaching with these features:","options":["Rote teaching","Recitation","Dialogic teaching","Expository teaching"],"answer":2,"explanation":"Alexander’s dialogic teaching is collective, reciprocal, supportive, cumulative and purposeful; recitation is a closed question–answer–feedback cycle that tests recall rather than building ideas together.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1968","question":"A Class 9 teacher asks students to watch a short video lesson at home and uses class time for problem-solving, discussion and individual help. This model is called:","options":["Programmed learning","The flipped classroom","The Dalton Plan","Team teaching by two teachers"],"answer":1,"explanation":"In the flipped classroom, first exposure to content happens outside class and class time is used for active work and guidance; the Dalton Plan uses monthly assignment contracts and subject laboratories.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-child-development-1969","question":"Michelene Chi and colleagues studied students learning physics from worked examples. Those who learnt the most were the ones who:","options":["Explained each step to themselves, saying why it worked and how it linked to principles","Read each worked example several times until they could reproduce it from memory","Skipped the examples and went straight to solving practice problems","Copied the examples neatly into their notebooks before solving problems"],"answer":0,"explanation":"Chi’s self-explanation effect: good learners generated explanations that filled gaps and connected steps to principles, while weaker learners paraphrased or simply read; prompting self-explanation improves learning.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1970","question":"In ‘cognitive apprenticeship’, as described by Collins, Brown and Newman, a teacher first thinks aloud while solving, then coaches and scaffolds students, and then asks them to put their own reasoning into words. That last step is called:","options":["Exploration","Modelling","Coaching","Articulation"],"answer":3,"explanation":"The methods of cognitive apprenticeship are modelling, coaching, scaffolding, articulation, reflection and exploration; articulation gets learners to make their knowledge and reasoning explicit.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1971","question":"Group A is taught a formula for variability and then practises it. Group B is first asked to invent their own ways of comparing the consistency of two cricketers, mostly fails to find the standard method, and is then taught the formula. Manu Kapur’s studies of such ‘productive failure’ found that Group B typically:","options":["Did better only because they spent more total time on the topic","Did worse on all measures, because failing first lowered their confidence","Gained deeper conceptual understanding and transfer, with similar routine skill","Did equally well on everything, since both groups learnt the same formula"],"answer":2,"explanation":"Generating solutions first activates prior knowledge and highlights the key features of the problem, so later instruction is better understood; studies found gains in conceptual understanding and transfer with similar procedural skill.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1972","question":"When Varun refuses to work and says, ‘You can’t make me,’ his teacher feels angry and challenged. According to Rudolf Dreikurs, Varun’s mistaken goal is most likely:","options":["Attention","Power","Revenge","Display of inadequacy"],"answer":1,"explanation":"Dreikurs used the teacher’s own reaction as a clue: annoyance suggests attention-seeking, feeling challenged or defeated suggests a power struggle, feeling hurt suggests revenge, and feeling helpless suggests assumed inadequacy.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1973","question":"During art, Kavya carelessly knocks over a pot of paint on the floor. Which response is a ‘logical consequence’ in Dreikurs’ sense?","options":["Kavya helps wipe up the paint before going on with her work","Kavya loses her games period for the rest of the week","Kavya writes ‘I will be careful’ fifty times after school","Kavya is scolded in front of the class so that others learn"],"answer":0,"explanation":"A logical consequence is related to the behaviour, respectful and reasonable, so the child sees the link between action and result; unrelated penalties or public shaming are punishments.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1974","question":"William Glasser’s choice theory holds that all behaviour is an attempt to satisfy basic needs. Which set lists the needs he proposed?","options":["Achievement, affiliation, power","Physiological, safety, belonging, esteem, self-actualisation","Autonomy, competence, relatedness","Survival, love and belonging, power, freedom, fun"],"answer":3,"explanation":"Glasser named five needs, survival, love and belonging, power (competence), freedom and fun, and urged schools to meet them so students choose to work; the other sets are Maslow’s, Deci and Ryan’s, and McClelland’s.","difficulty":"hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1975","question":"In ‘Experience and Education’, John Dewey warned that not all experiences are educative. He judged an experience by two criteria, namely:","options":["Discipline, whether it trains the mind, and memory, how much of it can be recalled later","Pleasure, whether learners enjoy it, and speed, how quickly the syllabus gets covered","Continuity (does it lead to further growth?) and interaction (does it fit learner and setting?)","Novelty, whether it is new, and difficulty, whether it challenges the brightest students"],"answer":2,"explanation":"Dewey argued that an experience is educative when it promotes further growth (continuity) and arises from the interplay between the learner’s needs and the environment (interaction); some enjoyable experiences are mis-educative.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT"},
  {"id":"cdp-child-development-1976","question":"Children watch a puppet, Sally, put her marble in a basket and leave. Another puppet moves it to a box. Asked, ‘Where will Sally look for her marble?’, most three-year-olds point to the box. Typically developing children begin to answer ‘the basket’ at about:","options":["Ten to eleven years","Eighteen months","Seven to eight years","Four to five years"],"answer":3,"explanation":"Passing this first-order false-belief task shows understanding that people act on their beliefs even when the beliefs are wrong; most children pass at about four to five, while three-year-olds answer from their own knowledge.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1977","question":"A three-year-old is shown a familiar sweets box, says it holds sweets, and is then shown it actually holds pencils. Asked, ‘What did you think was inside before we opened it?’, she replies, ‘Pencils.’ This shows that she:","options":["Cannot yet represent her own earlier false belief about the box","Is deliberately lying so as not to look foolish in front of the adult","Has forgotten what she said because of a weak short-term memory","Lacks object permanence and cannot remember objects once hidden"],"answer":0,"explanation":"In Gopnik and Astington’s unexpected-contents task, three-year-olds misreport their own past belief as well as predicting others will think ‘pencils’; understanding false belief in self and others develops together, around four.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1978","question":"Baron-Cohen, Leslie and Frith gave the Sally–Anne task to autistic children, to children with Down syndrome of lower mental age, and to typically developing four-year-olds. Their key finding was that:","options":["All three groups failed, since the task was too hard for under-tens","Most autistic children failed while most children in the other two groups passed","Children with Down syndrome failed most often because of their lower mental age","The autistic children passed more often, because of their good memory for detail"],"answer":1,"explanation":"Most autistic children, despite higher mental age, predicted Sally would look where the marble really was, while most of the other children passed, suggesting a specific difficulty in theory of mind rather than general delay.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1979","question":"Asked, ‘Where does Rohan think that Meena thinks the ice-cream van is?’, children must reason about one person’s belief about another person’s belief. Such second-order false-belief tasks are usually passed at about:","options":["Four to five years","Three to four years","Six to seven years","Thirteen to fourteen years"],"answer":2,"explanation":"Perner and Wimmer found that understanding beliefs about beliefs comes later than first-order false belief, at about six to seven; it underlies grasp of white lies, irony and social strategies in the primary years.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1980","question":"Studies found that pre-schoolers with more brothers and sisters, especially older ones, tended to pass false-belief tasks earlier. The most likely reason is that:","options":["Parents of large families use more physical punishment, which speeds up maturity","Children with many siblings inherit greater general intelligence from their parents","Children with siblings receive more formal teaching in reading before starting school","Daily talk, pretend play and quarrels with siblings give practice in reading minds"],"answer":3,"explanation":"Perner, Ruffman and others linked sibling numbers to earlier theory of mind; daily interaction, pretence, teasing and arguments about what others want and believe supply rich social experience.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1981","question":"In Walter Mischel’s delay-of-gratification studies, which strategy helped young children wait longest for a bigger reward?","options":["Being reminded again and again by the adult how delicious the treats were while waiting","Keeping the treats in full view and thinking about how sweet and tasty they would be","Thinking of the treats in ‘cool’ abstract ways, such as imagining marshmallows as clouds","Holding one treat in a hand the whole time so that they could feel it while they waited"],"answer":2,"explanation":"Mischel found that focusing on ‘hot’, consummatory features made waiting harder, whereas covering the rewards, self-distraction or ‘cool’ abstract thoughts made it easier; self-control can be taught as strategy.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1982","question":"Before a marshmallow-waiting test, one group of children found that an adult’s earlier promises of better crayons were broken; another group found they were kept. The first group waited far less. Kidd and colleagues concluded that waiting depends partly on:","options":["A rational judgement about whether the environment can be trusted to deliver","A fixed trait of self-control that the experience could not have changed","The number of marshmallows offered, which differed between the groups","How hungry the children were, since the first group had eaten less"],"answer":0,"explanation":"Children who had experienced an unreliable adult reasonably expected the bigger reward might never come, so they did not wait; this shows that ‘self-control’ scores reflect beliefs about the environment as well as an inner ability.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1983","question":"Three-year-olds sort cards correctly by colour. When told, ‘Now sort them by shape,’ many go on sorting by colour, even though they can repeat the new rule aloud. Most five-year-olds switch easily. This task mainly tracks the growth of:","options":["Conservation of number, as described for Piaget’s concrete operational stage","Cognitive flexibility and inhibitory control, parts of executive function","Colour and shape perception, which mature only at about five years of age","Long-term memory for the names of the different shapes and colours"],"answer":1,"explanation":"In Zelazo’s Dimensional Change Card Sort, the younger children know the new rule but cannot inhibit the old one or shift their mental set; the improvement reflects developing executive functions.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1984","question":"Asked about a quarrel between two friends, Ayesha, aged 12, says, ‘If I were a neutral outsider, I’d see that both of them had a point and both behaved badly.’ In Robert Selman’s levels of perspective taking, this shows:","options":["Undifferentiated (egocentric) perspective taking","Self-reflective perspective taking","Social-informational perspective taking","Third-party (mutual) perspective taking"],"answer":3,"explanation":"Selman’s third-party level involves stepping outside a two-person situation and imagining how a neutral observer would see both people; the self-reflective level only allows viewing one’s own thoughts from the other’s side.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1985","question":"Robert Siegler watched children solve addition sums over many weeks. On the same day, a child might count from one, count on from the larger number, or simply recall the answer, with the mix slowly shifting towards better strategies. He described this as:","options":["Vygotsky’s zone of proximal development","Piaget’s stage model with abrupt shifts between stages","The overlapping-waves model of strategy development","Skinner’s model of shaping by successive approximation"],"answer":2,"explanation":"In Siegler’s model several strategies coexist and compete, and their frequency changes gradually with experience, rather than one way of thinking being replaced abruptly by the next.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1986","question":"Neo-Piagetian Robbie Case explained children’s progress through stages mainly in terms of:","options":["More efficient use of working memory, as practice makes schemes automatic","Moral reasoning that moves from fear of punishment to universal principles","Social interaction with more capable others within a zone of proximal development","Unconscious conflicts between the id, ego and superego at each stage"],"answer":0,"explanation":"Case combined Piaget’s stages with information processing: as processing becomes automatic, it frees working-memory space, letting children coordinate more ideas and form central conceptual structures.","difficulty":"hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1987","question":"On Gibson and Walk’s ‘visual cliff’, most crawling infants refuse to cross the side that looks deep, even when their mother calls. Later research by Joseph Campos found that:","options":["Infants cannot perceive depth at all until some time after their first birthday","Pre-crawling infants notice the depth, but fear of it grows with crawling experience","Fear of heights is fully present at birth and needs no experience to develop","Infants avoid the deep side only because they dislike the feel of its glass surface"],"answer":1,"explanation":"Very young infants showed interest, not fear, at the deep side (slowed heart rate), while infants with crawling experience showed fear (faster heart rate), so wariness of heights develops with self-produced locomotion.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1988","question":"Robert Fantz showed babies pairs of pictures and measured how long they looked at each. He found that even very young infants:","options":["Could not focus on pictures until about six months of age","Looked equally at all pictures, showing no visual preferences at all","Looked longer only at bright colours, ignoring all patterns","Looked longer at patterned and face-like pictures than at plain ones"],"answer":3,"explanation":"Fantz’s preferential-looking method showed that newborns and young infants prefer patterned and face-like stimuli, so they can discriminate visual patterns far earlier than once believed.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1989","question":"A baby is shown the same picture of a cat again and again until she looks at it only briefly. A picture of a dog is then shown, and she looks at it much longer. Researchers infer that she:","options":["Prefers dogs to cats, since she looked at the dog picture for so much longer","Can tell the dog from the cat, as shown by renewed attention to the new picture","Has forgotten the cat picture, since her looking time fell with each repetition","Is simply tired by now, since attention always drops as a session goes on"],"answer":1,"explanation":"In the habituation–dishabituation method, recovery of looking to a new stimulus shows that the infant detects a difference; the fall in looking reflects familiarity, not forgetting.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1990","question":"Renée Baillargeon showed four- to five-month-old infants a screen that seemed to rotate right through the space where a box had been hidden. The infants looked longer at this event than at one where the screen stopped at the box. This suggests that:","options":["Infants may understand that hidden objects still exist earlier than Piaget’s search tasks implied","Infants this young understand nothing at all about objects that they cannot see","Infants prefer a rotating screen, because longer movement always attracts more attention","Infants look longest at events they find familiar and expected from experience"],"answer":0,"explanation":"Longer looking at the ‘impossible’ event suggests surprise that the hidden box did not stop the screen; looking-time methods avoid the motor demands of manual search, which may have led Piaget to underestimate infants.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1991","question":"Karen Wynn showed five-month-olds one doll placed behind a screen and then a second doll added. When the screen dropped to reveal only one doll, infants looked longer than when it showed two. What did she conclude?","options":["Infants cannot tell one object from two before they learn to count","Infants simply prefer looking at one doll rather than at two dolls","Young infants may have a basic sense of small numbers and simple addition","Infants look longer at whatever they saw most recently"],"answer":2,"explanation":"Longer looking at the ‘impossible’ outcome of 1 + 1 = 1 suggested that infants expected two dolls; the finding has been debated, but it supports claims of early, non-verbal number sense.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-1992","question":"Robert Kail found that children’s speed on many different tasks, from mental rotation to memory search, increased with age along a very similar curve. This pattern suggests that:","options":["Children become faster only on the kinds of tasks they have been trained on in school","Each task improves for entirely separate reasons, with no common cause behind them","Speed stays the same through childhood and improves only after adolescence begins","A general, age-related increase in processing speed underlies improvement across tasks"],"answer":3,"explanation":"Because the speed-up followed the same exponential pattern across unrelated tasks, Kail argued for a global change in processing speed, probably linked to brain maturation such as myelination.","difficulty":"hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1993","question":"According to Brainerd and Reyna’s fuzzy-trace theory, which statement is correct?","options":["Children rely more on gist than adults, who store mainly exact verbatim details","Verbatim and gist traces are stored in parallel, and reliance on gist grows with age","Only verbatim traces are stored; the gist is constructed afresh at the time of recall","Verbatim traces last much longer than gist traces once stored in long-term memory"],"answer":1,"explanation":"Fuzzy-trace theory holds that verbatim and gist traces are encoded in parallel; gist lasts longer, and reliance on gist increases with age, which is why some gist-based false memories actually increase with development.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1994","question":"To study how children discover a new maths strategy, a researcher observes the same children solving problems in many sessions over a few weeks, recording each strategy closely. This research design is called:","options":["The microgenetic method","The cross-sectional method","The case-history method","The co-twin control method"],"answer":0,"explanation":"Microgenetic studies make dense observations during a period of rapid change, so the process of change itself can be seen; cross-sectional studies compare different age groups at one time.","difficulty":"hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1995","question":"Elizabeth Spelke’s ‘core knowledge’ view proposes that infants:","options":["Develop all knowledge only through stages driven by a general, logical structure","Begin life as blank slates who must learn everything from experience alone","Begin life with a few specialised systems for objects, number, space and agents","Gain knowledge only through the language that they learn from caregivers"],"answer":2,"explanation":"Core knowledge theorists argue for innate, domain-specific systems that are built on through experience; this contrasts with empiricist blank-slate views and with Piaget’s domain-general stages.","difficulty":"hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1996","question":"A one-year-old points at a bird, looks at her father to check that he is looking too, and smiles. This pointing to share interest, rather than to ask for something, is called:","options":["Telegraphic speech, a short two-word sentence","Protoimperative pointing, a request for an object","Holophrastic speech, a one-word sentence","Protodeclarative pointing, a sign of joint attention"],"answer":3,"explanation":"Protodeclarative pointing directs another’s attention to share an experience and emerges with joint attention around nine to twelve months; protoimperative pointing is used to obtain something.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1997","question":"Usha Goswami found that many three- and four-year-olds could complete analogies such as ‘Play-dough is to cut play-dough as apple is to ___’ (choosing a cut apple). What did this show?","options":["Analogical reasoning appears only once children reach formal operations at eleven","Young children can reason by analogy when they understand the relation involved","Young children solve such items only by matching surface features such as colour","Analogical reasoning depends only on how many words a young child already knows"],"answer":1,"explanation":"Earlier studies used relations unfamiliar to young children; with familiar causal relations like cutting, they reasoned by analogy, showing that relational knowledge, not stage, limits performance.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT"},
  {"id":"cdp-child-development-1998","question":"A three-year-old handles a sponge painted to look like a rock. She then says it ‘really is a sponge’ and also that it ‘looks like a sponge’. John Flavell’s research shows that this difficulty with the appearance–reality distinction:","options":["Is common at three and largely overcome by about six or seven years","Persists until adolescence in most children, whatever their experiences","Is found mainly in children with learning disabilities, not in others","Shows that she cannot yet perceive colours or shapes properly at all"],"answer":0,"explanation":"Young children struggle to hold two representations of one object, how it looks and what it is; skill improves markedly during the pre-school and early school years, alongside theory of mind.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-child-development-1999","question":"Asked what happens at a birthday party, a four-year-old says, ‘You come, you give presents, you cut the cake, you eat, you go home.’ Katherine Nelson would describe this general knowledge of a routine event as a:","options":["Episodic flashback","Schema of conservation","Script","Mnemonic device"],"answer":2,"explanation":"Scripts are general representations of the sequence of familiar events; young children organise memory of routines this way and recall ‘what usually happens’ better than unique details.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-child-development-2000","question":"Some parents talk with their pre-schoolers about past events in rich detail, asking open questions and adding information (‘What did we see at the zoo? Yes, and what was the elephant doing?’). Research by Reese and Fivush found that their children later:","options":["Became more anxious, since talking about the past revived old feelings","Remembered fewer events, since parents did the remembering for them","Showed no difference from children of parents who asked only yes–no questions","Gave fuller, more detailed accounts of their own past experiences"],"answer":3,"explanation":"Elaborative reminiscing provides a model of how to organise and narrate memories, so children develop richer autobiographical memory; repetitive, yes–no styles are less helpful.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
];

export default questions;
